# V19.24 — Magalu, fase 0: só a conexão (OAuth do ID Magalu). Nada aqui lê pedido
# nem grava na fila. Uma conta só, de Araçatuba (decisão do dono, 14/10).
# Autorização: id.magalu.com/login?...&choose_tenants=true (o seller escolhe a loja).
# Troca do code e renovação: POST id.magalu.com/oauth/token — o code em JSON, o
# refresh em form-urlencoded (como na documentação). Access token dura até 2 h.
# ---------------------------------------------------------------------------
MAGALU_TOKEN_LOCK = threading.Lock()


def magalu_credentials_configured() -> bool:
    return bool(MAGALU_CLIENT_ID and MAGALU_CLIENT_SECRET)


def magalu_integration_row() -> sqlite3.Row | None:
    with DB_LOCK:
        return DB.execute("SELECT * FROM magalu_integration WHERE id=1").fetchone()


def magalu_log_event(topic: str, resource: str, result: str, detail: str = "") -> None:
    with DB_LOCK:
        DB.execute(
            "INSERT INTO magalu_event_log(created_at,topic,resource,result,detail) VALUES(?,?,?,?,?)",
            (now_iso(), str(topic or "")[:120], str(resource or "")[:500],
             str(result or "")[:80], str(detail or "")[:2000]),
        )
        DB.commit()


def magalu_status_payload() -> dict[str, Any]:
    row = magalu_integration_row()
    connected = bool(row and str(row["access_token"] or "").strip() and str(row["refresh_token"] or "").strip())
    return {
        "configured": magalu_credentials_configured(),
        "connected": connected,
        "client_id": MAGALU_CLIENT_ID,
        "scope": str(row["scope"] or "") if row else "",
        "connected_at": str(row["connected_at"] or "") if row else "",
        "last_sync_at": str(row["last_sync_at"] or "") if row else "",
        "last_error": str(row["last_error"] or "") if row else "",
        "token_expires_at": int(row["token_expires_at"] or 0) if row else 0,
        "redirect_uri": MAGALU_REDIRECT_URI,
        "credentials_server_side": True,
        "importacao_ligada": magalu_importacao_ligada(),  # V19.27
    }


def magalu_connect_url() -> str:
    if not magalu_credentials_configured():
        raise RuntimeError("Configure MAGALU_CLIENT_ID e MAGALU_CLIENT_SECRET no /home/expedicao/.env antes de conectar.")
    state = secrets.token_urlsafe(32)
    now_epoch = int(time.time())
    with DB_LOCK:
        DB.execute("DELETE FROM magalu_oauth_state WHERE expires_at_epoch<?", (now_epoch,))
        DB.execute("INSERT INTO magalu_oauth_state(state,expires_at_epoch) VALUES(?,?)", (state, now_epoch + 15 * 60))
        DB.commit()
    parametros = {
        "client_id": MAGALU_CLIENT_ID,
        "redirect_uri": MAGALU_REDIRECT_URI,
        "scope": MAGALU_OAUTH_SCOPE,
        "response_type": "code",
        "choose_tenants": "true",  # obrigatório para seller: escolhe a loja (PJ)
        "state": state,
    }
    return f"{MAGALU_AUTH_URL}?{urlencode(parametros)}"


def _magalu_token_http(dados: dict[str, str]) -> dict[str, Any]:
    """Só a chamada de rede ao ID Magalu. Isolada para poder ser testada.

    V19.25: produção 14/10 — o code em JSON (exemplo da doc) voltou 401 invalid_client
    ("nenhuma autenticação de cliente incluída"). Vai como formulário com o secret no
    corpo (client_secret_post); se ainda vier invalid_client, uma vez com Basic
    (client_secret_basic). A recusa do cliente não gasta o code."""
    def _enviar(campos: dict[str, str], basic: bool) -> dict[str, Any]:
        cab = {"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"}
        if basic:
            par = f"{quote(campos.get('client_id', ''), safe='')}:{quote(campos.get('client_secret', ''), safe='')}"
            cab["Authorization"] = "Basic " + base64.b64encode(par.encode("utf-8")).decode("ascii")
            campos = {k: v for k, v in campos.items() if k != "client_secret"}
        req = urllib.request.Request(MAGALU_TOKEN_URL, data=urlencode(campos).encode("utf-8"),
                                     method="POST", headers=cab)
        with urllib.request.urlopen(req, timeout=20) as resp:
            return json.loads(resp.read().decode("utf-8", "replace") or "{}")

    try:
        try:
            data = _enviar(dict(dados), basic=False)
        except urllib.error.HTTPError as exc:
            texto = exc.read().decode("utf-8", "replace")
            if exc.code != 401 or "invalid_client" not in texto:
                raise RuntimeError(f"ID Magalu HTTP {exc.code}: {texto[:500]}")
            data = _enviar(dict(dados), basic=True)
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"ID Magalu HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:500]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede no ID Magalu: {exc.reason}")
    if not isinstance(data, dict):
        raise RuntimeError("Resposta inválida do ID Magalu.")
    return data


def _magalu_gravar_token(data: dict[str, Any], conectando: bool) -> None:
    access = str(data.get("access_token") or "").strip()
    refresh = str(data.get("refresh_token") or "").strip()
    if not access or not refresh:
        raise RuntimeError("O ID Magalu não devolveu access_token/refresh_token.")
    try:
        expira = int(data.get("expires_in") or 7200)
    except (TypeError, ValueError):
        expira = 7200
    agora = now_iso()
    with DB_LOCK:
        DB.execute(
            """INSERT INTO magalu_integration(id,access_token,refresh_token,scope,token_expires_at,connected_at,updated_at,last_error)
               VALUES(1,?,?,?,?,?,?,'')
               ON CONFLICT(id) DO UPDATE SET
                 access_token=excluded.access_token, refresh_token=excluded.refresh_token,
                 scope=CASE WHEN excluded.scope='' THEN magalu_integration.scope ELSE excluded.scope END,
                 token_expires_at=excluded.token_expires_at,
                 connected_at=CASE WHEN ? THEN excluded.connected_at ELSE magalu_integration.connected_at END,
                 updated_at=excluded.updated_at, last_error=''""",
            (access, refresh, str(data.get("scope") or ""), int(time.time()) + max(60, expira),
             agora, agora, 1 if conectando else 0),
        )
        DB.commit()


def magalu_exchange_code(code: str, state: str) -> dict[str, Any]:
    now_epoch = int(time.time())
    with DB_LOCK:
        row = DB.execute("SELECT * FROM magalu_oauth_state WHERE state=?", (state,)).fetchone()
        DB.execute("DELETE FROM magalu_oauth_state WHERE state=? OR expires_at_epoch<?", (state, now_epoch))
        DB.commit()
    if not row or int(row["expires_at_epoch"] or 0) < now_epoch:
        raise RuntimeError("Estado OAuth inválido ou expirado. Inicie a conexão novamente.")
    data = _magalu_token_http({
        "grant_type": "authorization_code",
        "client_id": MAGALU_CLIENT_ID,
        "client_secret": MAGALU_CLIENT_SECRET,
        "redirect_uri": MAGALU_REDIRECT_URI,
        "code": str(code or "").strip(),
    })
    _magalu_gravar_token(data, conectando=True)
    magalu_log_event("oauth", "/callback", "CONECTADO", str(data.get("scope") or ""))
    return magalu_status_payload()


def _magalu_token_valido(row: sqlite3.Row | None, margem: int = 300) -> bool:
    return bool(row and str(row["access_token"] or "").strip()
                and int(row["token_expires_at"] or 0) > int(time.time()) + margem)


def magalu_access_token(force: bool = False, recusado: str | None = None) -> str:
    """Access token válido; renova com o refresh_token sob a trava (mesma regra da
    Shopee/ML, V18.56: renovação serializada e relida sob a trava)."""
    row = magalu_integration_row()
    if not row or not str(row["refresh_token"] or "").strip():
        raise RuntimeError("Magalu não conectada. Conecte a conta em Integrações.")
    token_antes = str(row["access_token"] or "").strip()
    if recusado is not None:  # V20.34 (revisao): compara com o token que a Magalu recusou, nao com o lido agora
        token_antes = str(recusado).strip()
    if not force and _magalu_token_valido(row):
        return str(row["access_token"] or "").strip()
    with MAGALU_TOKEN_LOCK:
        row = magalu_integration_row()
        if not row or not str(row["refresh_token"] or "").strip():
            raise RuntimeError("Magalu não conectada. Conecte a conta em Integrações.")
        if str(row["access_token"] or "").strip() != token_antes and _magalu_token_valido(row, margem=60):
            return str(row["access_token"]).strip()
        if not force and _magalu_token_valido(row):
            return str(row["access_token"]).strip()
        try:
            data = _magalu_token_http({
                "grant_type": "refresh_token",
                "client_id": MAGALU_CLIENT_ID,
                "client_secret": MAGALU_CLIENT_SECRET,
                "refresh_token": str(row["refresh_token"]).strip(),
            })
            _magalu_gravar_token(data, conectando=False)
        except Exception as exc:
            with DB_LOCK:
                DB.execute("UPDATE magalu_integration SET last_error=?, updated_at=? WHERE id=1",
                           (str(exc)[:500], now_iso()))
                DB.commit()
            magalu_log_event("oauth_refresh", "", "ERRO", str(exc))
            raise
        magalu_log_event("oauth_refresh", "", "OK", "Access token renovado.")
        return str(magalu_integration_row()["access_token"]).strip()


# ---------------------------------------------------------------------------
# V19.63 — TikTok Shop (loja de Bauru), fase 0: só a conexão. Nada aqui mexe em
# estoque nem na fila. Feito pela documentação do Partner Center, sem resposta real:
# a 1ª resposta de cada chamada fica em tiktok_amostra_v1963 — conferir ao conectar.
# Autorização: services.tiktokshop.com/open/authorize?service_id=...&state=...
# Token: GET auth.tiktok-shops.com/api/v2/token/get (grant_type=authorized_code) e
# /api/v2/token/refresh. Os *_expire_in da resposta são data (epoch), não duração.
# Chamadas: open-api.tiktokglobalshop.com, app_key + timestamp + sign na URL,
# token no cabeçalho x-tts-access-token, shop_cipher nas rotas da loja.
# ---------------------------------------------------------------------------
TIKTOK_TOKEN_LOCK = threading.Lock()


def tiktok_credentials_configured() -> bool:
    return bool(TIKTOK_APP_KEY and TIKTOK_APP_SECRET and TIKTOK_SERVICE_ID)


def tiktok_integration_row() -> sqlite3.Row | None:
    with DB_LOCK:
        return DB.execute("SELECT * FROM tiktok_integration WHERE id=1").fetchone()


def tiktok_log_event(topic: str, resource: str, result: str, detail: str = "") -> None:
    with DB_LOCK:
        DB.execute(
            "INSERT INTO tiktok_event_log(created_at,topic,resource,result,detail) VALUES(?,?,?,?,?)",
            (now_iso(), str(topic or "")[:120], str(resource or "")[:500],
             str(result or "")[:80], str(detail or "")[:2000]),
        )
        DB.commit()


def _tiktok_guardar_amostra(tipo: str, resposta: Any) -> None:
    with DB_LOCK:
        if DB.execute("SELECT 1 FROM tiktok_amostra_v1963 WHERE tipo=?", (tipo,)).fetchone():
            return
        DB.execute("INSERT INTO tiktok_amostra_v1963(tipo,resposta,created_at) VALUES(?,?,?)",
                   (tipo, json_dumps(resposta)[:500000], now_iso()))
        DB.commit()


def tiktok_status_payload() -> dict[str, Any]:
    row = tiktok_integration_row()
    connected = bool(row and str(row["access_token"] or "").strip() and str(row["refresh_token"] or "").strip())
    return {
        "configured": tiktok_credentials_configured(),
        "connected": connected,
        "app_key": TIKTOK_APP_KEY,
        "casa": TIKTOK_CASA,
        "seller_name": str(row["seller_name"] or "") if row else "",
        "shop_name": str(row["shop_name"] or "") if row else "",
        "shop_region": str(row["shop_region"] or "") if row else "",
        "tem_loja": bool(row and str(row["shop_cipher"] or "").strip()),
        "connected_at": str(row["connected_at"] or "") if row else "",
        "access_expires_at": int(row["access_expires_at"] or 0) if row else 0,
        "refresh_expires_at": int(row["refresh_expires_at"] or 0) if row else 0,
        "last_error": str(row["last_error"] or "") if row else "",
        "redirect_uri": TIKTOK_REDIRECT_URI,
        "credentials_server_side": True,
        "importacao_ligada": tiktok_importacao_ligada(),  # V19.64
        "etiqueta_ligada": tiktok_etiqueta_ligada(),  # V20.29
        "fonte": tiktok_fonte(),  # V20.40: extensao | api
    }


def tiktok_connect_url() -> str:
    if not tiktok_credentials_configured():
        raise RuntimeError("Configure TIKTOK_APP_KEY, TIKTOK_APP_SECRET e TIKTOK_SERVICE_ID no /home/expedicao/.env antes de conectar.")
    state = secrets.token_urlsafe(32)
    now_epoch = int(time.time())
    with DB_LOCK:
        DB.execute("DELETE FROM tiktok_oauth_state WHERE expires_at_epoch<?", (now_epoch,))
        DB.execute("INSERT INTO tiktok_oauth_state(state,expires_at_epoch) VALUES(?,?)", (state, now_epoch + 15 * 60))
        DB.commit()
    return f"{TIKTOK_AUTH_URL}?{urlencode({'service_id': TIKTOK_SERVICE_ID, 'state': state})}"


def tiktok_assinar(path: str, params: dict[str, Any], corpo: str = "") -> str:
    """Assinatura da documentação: caminho + chaves em ordem alfabética (sem sign e
    access_token) coladas com o valor + corpo, embrulhado no secret; HMAC-SHA256."""
    base = path + "".join(f"{k}{params[k]}" for k in sorted(params) if k not in ("sign", "access_token"))
    base = TIKTOK_APP_SECRET + base + (corpo or "") + TIKTOK_APP_SECRET
    return hmac.new(TIKTOK_APP_SECRET.encode("utf-8"), base.encode("utf-8"), hashlib.sha256).hexdigest()


def _tiktok_token_http(caminho: str, params: dict[str, str]) -> dict[str, Any]:
    """Só a chamada de rede ao servidor de token. Isolada para poder ser testada."""
    url = TIKTOK_TOKEN_BASE + caminho + "?" + urlencode(params)
    req = urllib.request.Request(url, method="GET", headers={"Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"TikTok token HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:500]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede no TikTok: {exc.reason}")
    if not isinstance(data, dict):
        raise RuntimeError("Resposta inválida do TikTok.")
    return data


def _tiktok_expira(valor: Any, padrao: int) -> int:
    try:
        n = int(valor or 0)
    except (TypeError, ValueError):
        n = 0
    if n <= 0:
        return int(time.time()) + padrao
    return n if n > 1_000_000_000 else int(time.time()) + n  # data (doc) ou duração (tolerante)


def _tiktok_gravar_token(resp: dict[str, Any], conectando: bool) -> None:
    if int(resp.get("code") or 0) != 0:
        raise RuntimeError(f"TikTok recusou: {resp.get('code')} {resp.get('message') or ''}".strip())
    data = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    access = str(data.get("access_token") or "").strip()
    refresh = str(data.get("refresh_token") or "").strip()
    if not access or not refresh:
        raise RuntimeError("O TikTok não devolveu access_token/refresh_token.")
    agora = now_iso()
    scopes = data.get("granted_scopes")
    with DB_LOCK:
        DB.execute(
            """INSERT INTO tiktok_integration(id,casa,access_token,refresh_token,access_expires_at,refresh_expires_at,
                   open_id,seller_name,scopes,connected_at,updated_at,last_error)
               VALUES(1,?,?,?,?,?,?,?,?,?,?,'')
               ON CONFLICT(id) DO UPDATE SET
                 access_token=excluded.access_token, refresh_token=excluded.refresh_token,
                 access_expires_at=excluded.access_expires_at, refresh_expires_at=excluded.refresh_expires_at,
                 open_id=CASE WHEN excluded.open_id='' THEN tiktok_integration.open_id ELSE excluded.open_id END,
                 seller_name=CASE WHEN excluded.seller_name='' THEN tiktok_integration.seller_name ELSE excluded.seller_name END,
                 scopes=CASE WHEN excluded.scopes='' THEN tiktok_integration.scopes ELSE excluded.scopes END,
                 connected_at=CASE WHEN ? THEN excluded.connected_at ELSE tiktok_integration.connected_at END,
                 updated_at=excluded.updated_at, last_error=''""",
            (TIKTOK_CASA, access, refresh, _tiktok_expira(data.get("access_token_expire_in"), 7 * 86400),
             _tiktok_expira(data.get("refresh_token_expire_in"), 30 * 86400),
             str(data.get("open_id") or ""), str(data.get("seller_name") or ""),
             ",".join(str(x) for x in scopes) if isinstance(scopes, list) else "",
             agora, agora, 1 if conectando else 0),
        )
        DB.commit()


def tiktok_exchange_code(code: str, state: str) -> dict[str, Any]:
    now_epoch = int(time.time())
    with DB_LOCK:
        row = DB.execute("SELECT * FROM tiktok_oauth_state WHERE state=?", (state,)).fetchone()
        DB.execute("DELETE FROM tiktok_oauth_state WHERE state=? OR expires_at_epoch<?", (state, now_epoch))
        DB.commit()
    if not row or int(row["expires_at_epoch"] or 0) < now_epoch:
        raise RuntimeError("Estado OAuth inválido ou expirado. Inicie a conexão novamente.")
    resp = _tiktok_token_http("/api/v2/token/get", {
        "app_key": TIKTOK_APP_KEY, "app_secret": TIKTOK_APP_SECRET,
        "auth_code": str(code or "").strip(), "grant_type": "authorized_code",
    })
    dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    # Amostra sem os tokens: só o formato da resposta.
    _tiktok_guardar_amostra("token_get", {"code": resp.get("code"), "message": resp.get("message"),
                                          "data_campos": sorted(dados.keys())})
    _tiktok_gravar_token(resp, conectando=True)
    tiktok_log_event("oauth", "/callback", "CONECTADO", str(dados.get("seller_name") or ""))
    try:
        tiktok_buscar_loja()
    except Exception as exc:  # o token fica; a loja é buscada de novo no próximo uso
        tiktok_log_event("lojas", "/authorization/202309/shops", "ERRO", str(exc))
    return tiktok_status_payload()


def _tiktok_token_valido(row: sqlite3.Row | None, margem: int = 300) -> bool:
    return bool(row and str(row["access_token"] or "").strip()
                and int(row["access_expires_at"] or 0) > int(time.time()) + margem)


def tiktok_access_token(force: bool = False) -> str:
    """Access token válido; renova sob a trava, relendo a linha (regra da V18.56)."""
    row = tiktok_integration_row()
    if not row or not str(row["refresh_token"] or "").strip():
        raise RuntimeError("TikTok não conectado. Conecte a conta em Integrações.")
    token_antes = str(row["access_token"] or "").strip()
    if not force and _tiktok_token_valido(row):
        return token_antes
    with TIKTOK_TOKEN_LOCK:
        row = tiktok_integration_row()
        if not row or not str(row["refresh_token"] or "").strip():
            raise RuntimeError("TikTok não conectado. Conecte a conta em Integrações.")
        if str(row["access_token"] or "").strip() != token_antes and _tiktok_token_valido(row, margem=60):
            return str(row["access_token"]).strip()
        if not force and _tiktok_token_valido(row):
            return str(row["access_token"]).strip()
        try:
            resp = _tiktok_token_http("/api/v2/token/refresh", {
                "app_key": TIKTOK_APP_KEY, "app_secret": TIKTOK_APP_SECRET,
                "refresh_token": str(row["refresh_token"]).strip(), "grant_type": "refresh_token",
            })
            _tiktok_gravar_token(resp, conectando=False)
        except Exception as exc:
            with DB_LOCK:
                DB.execute("UPDATE tiktok_integration SET last_error=?, updated_at=? WHERE id=1",
                           (str(exc)[:500], now_iso()))
                DB.commit()
            tiktok_log_event("oauth_refresh", "", "ERRO", str(exc))
            raise
        tiktok_log_event("oauth_refresh", "", "OK", "Access token renovado.")
        return str(tiktok_integration_row()["access_token"]).strip()


def _tiktok_http(metodo: str, url: str, token: str, corpo: str = "") -> Any:
    """Só a chamada de rede. Isolada para poder ser testada."""
    req = urllib.request.Request(url, method=metodo, data=corpo.encode("utf-8") if corpo else None, headers={
        "x-tts-access-token": token, "Content-Type": "application/json", "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            return json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        raise RuntimeError(f"TikTok HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:500]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede no TikTok: {exc.reason}")


def tiktok_api(metodo: str, path: str, params: dict[str, Any] | None = None,
               body: Any = None, loja: bool = True) -> dict[str, Any]:
    """Chamada assinada. `loja=True` põe o shop_cipher (rotas da loja)."""
    token = tiktok_access_token()
    query = {k: str(v) for k, v in (params or {}).items() if v is not None and v != ""}
    query["app_key"] = TIKTOK_APP_KEY
    query["timestamp"] = str(int(time.time()))
    if loja:
        row = tiktok_integration_row()
        cipher = str(row["shop_cipher"] or "").strip() if row else ""
        if not cipher:
            cipher = tiktok_buscar_loja()
        query["shop_cipher"] = cipher
    corpo = json.dumps(body, ensure_ascii=False, separators=(",", ":")) if body is not None else ""
    query["sign"] = tiktok_assinar(path, query, corpo)
    resp = _tiktok_http(metodo, TIKTOK_API_BASE + path + "?" + urlencode(query), token, corpo)
    if not isinstance(resp, dict):
        raise RuntimeError("Resposta inválida do TikTok.")
    # V20.29: uma amostra por ROTA — o id do pacote/pedido vira {id} (senão uma linha por pedido).
    # revisar-antes-de-subir: a 1ª recusa (ex.: sem NF) fica em "<rota> [erro]" e não ocupa o lugar
    # da 1ª resposta BOA, que é a que mostra o formato real a conferir.
    rota = f"{metodo} " + re.sub(r"/(packages|orders)/[^/]+/", r"/\1/{id}/", path)
    rota = re.sub(r"/(products|categories)/\d+", r"/\1/{id}", rota)  # revisar-antes-de-subir (V20.41): uma por rota
    # revisar-antes-de-subir (V20.40): a amostra guarda o formato, nunca o CPF/nome/endereço do comprador
    _tiktok_guardar_amostra(rota if int(resp.get("code") or 0) == 0 else rota + " [erro]", _tiktok_sc_mascarar(resp))
    if int(resp.get("code") or 0) != 0:
        raise RuntimeError(f"TikTok {path}: {resp.get('code')} {resp.get('message') or ''}".strip())
    return resp


def tiktok_buscar_loja() -> str:
    """Loja autorizada (uma só: Bauru) e o shop_cipher que as rotas da loja exigem."""
    resp = tiktok_api("GET", "/authorization/202309/shops", loja=False)
    lojas = ((resp.get("data") or {}).get("shops") or []) if isinstance(resp.get("data"), dict) else []
    if not lojas:
        raise RuntimeError("Nenhuma loja do TikTok Shop autorizada para o app.")
    loja = lojas[0]
    with DB_LOCK:
        DB.execute("UPDATE tiktok_integration SET shop_id=?, shop_name=?, shop_region=?, shop_cipher=?, updated_at=? WHERE id=1",
                   (str(loja.get("id") or ""), str(loja.get("name") or ""), str(loja.get("region") or ""),
                    str(loja.get("cipher") or ""), now_iso()))
        DB.commit()
    if len(lojas) > 1:
        tiktok_log_event("lojas", "/authorization/202309/shops", "ATENCAO", f"{len(lojas)} lojas autorizadas; usando {loja.get('name')}")
    return str(loja.get("cipher") or "")


def tiktok_teste_leitura() -> dict[str, Any]:
    """Só lê: loja e depósitos (o estoque da fase 1 é por depósito)."""
    etapas = []
    for nome, caminho, loja in (("Loja autorizada", "/authorization/202309/shops", False),
                                ("Depósitos", "/logistics/202309/warehouses", True)):
        try:
            r = tiktok_api("GET", caminho, loja=loja)
            d = r.get("data") if isinstance(r.get("data"), dict) else {}
            itens = d.get("shops") or d.get("warehouses") or []
            etapas.append({"etapa": nome, "caminho": caminho, "ok": True, "itens": len(itens),
                           "nomes": [str(i.get("name") or "") for i in itens[:10] if isinstance(i, dict)]})
        except Exception as exc:
            etapas.append({"etapa": nome, "caminho": caminho, "ok": False, "erro": str(exc)[:300]})
    tiktok_log_event("teste", "leitura", "OK" if all(e["ok"] for e in etapas) else "ERRO",
                     "; ".join(f"{e['etapa']}: {'ok' if e['ok'] else e['erro']}" for e in etapas)[:1000])
    return {"ok": True, "etapas": etapas}


# ---------------------------------------------------------------------------
# V19.26 — Magalu, fase 1a: PRÉVIA dos pedidos que entrariam na fila. Só lê: nada
# aqui grava em conf_pedidos. O dono confere com o Portal do Seller antes da 1b
# (importação). A 1ª resposta real com pedidos fica em magalu_amostra_v1926 para
# conferir os nomes dos campos (a documentação só tem exemplo).
# ---------------------------------------------------------------------------
MAGALU_PEDIDOS_POR_PAGINA = 100
MAGALU_PEDIDOS_MAX_PAGINAS = 20
# Entrega que ainda precisa sair daqui (shipped/delivered/cancelled/frozen ficam fora).
MAGALU_ENTREGA_PARA_EXPEDIR = {"approved", "invoiced"}


class MagaluHttp401(Exception):
    pass


def _magalu_http_get(url: str, token: str) -> Any:
    """Só a chamada de rede. Isolada para poder ser testada."""
    req = urllib.request.Request(url, method="GET", headers={
        "Authorization": f"Bearer {token}", "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            return json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            raise MagaluHttp401()
        raise RuntimeError(f"Magalu HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:500]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede na Magalu: {exc.reason}")


def magalu_api_get(path: str, params: dict[str, Any] | None = None) -> Any:
    query = {k: v for k, v in (params or {}).items() if v is not None and v != ""}
    url = MAGALU_API_BASE + path + (("?" + urlencode(query)) if query else "")
    try:
        return _magalu_http_get(url, magalu_access_token())
    except MagaluHttp401:
        # Token recusado antes do vencimento: renova uma vez (sob a trava) e tenta de novo.
        try:
            return _magalu_http_get(url, magalu_access_token(force=True))
        except MagaluHttp401:
            raise RuntimeError("Magalu recusou o acesso (401). Reconecte a conta em Integrações.")


def _magalu_guardar_amostra(tipo: str, resposta: Any) -> None:
    tem_dado = bool(isinstance(resposta, dict) and resposta.get("results"))
    with DB_LOCK:
        atual = DB.execute("SELECT tem_dado FROM magalu_amostra_v1926 WHERE tipo=?", (tipo,)).fetchone()
        if atual and (int(atual["tem_dado"] or 0) or not tem_dado):
            return  # já tem a 1ª resposta com dado
        DB.execute("INSERT OR REPLACE INTO magalu_amostra_v1926(tipo,resposta,tem_dado,created_at) VALUES(?,?,?,?)",
                   (tipo, json_dumps(resposta)[:500000], 1 if tem_dado else 0, now_iso()))
        DB.commit()


# ---------------------------------------------------------------------------
# V19.53: teste de LEITURA para a promoção automática da Magalu (pedido do dono, 18/10).
# A documentação da API Promocional não mostra os corpos (criar promoção, SKU da promoção, preço);
# antes de construir, lê de verdade — promoções da loja, os SKUs de uma delas, SKUs do catálogo e o
# preço de alguns — e guarda a resposta em magalu_amostra_v1926 (tipo "promo_*"). Só GET: nada é
# criado nem alterado na Magalu. O token da loja já tem os escopos de promoção e de preço (18/10).
# ---------------------------------------------------------------------------
MAGALU_PROMO_TESTE_SKUS = 3


def _magalu_lista(resp: Any) -> list[Any]:
    """Itens de uma resposta paginada da Magalu (results/data/items/promotions/skus), tolerante."""
    if isinstance(resp, list):
        return resp
    if isinstance(resp, dict):
        for chave in ("results", "data", "items", "promotions", "skus", "promos"):
            if isinstance(resp.get(chave), list):
                return resp[chave]
    return []


def _magalu_campos(obj: Any, prefixo: str = "", fundo: int = 3) -> list[str]:
    """Nomes dos campos (até 3 níveis) — para ver o formato sem precisar ler o JSON inteiro."""
    out: list[str] = []
    if fundo <= 0:
        return out
    if isinstance(obj, list):
        return _magalu_campos(obj[0], prefixo + "[]", fundo) if obj else [prefixo + "[]"]
    if isinstance(obj, dict):
        for k, v in obj.items():
            nome = f"{prefixo}.{k}" if prefixo else str(k)
            out.append(nome)
            if isinstance(v, (dict, list)):
                out.extend(_magalu_campos(v, nome, fundo - 1))
    return out


def magalu_promo_teste() -> dict[str, Any]:
    """Só leitura. Cada chamada vale por si: a que falhar mostra o erro e as outras seguem."""
    magalu_access_token()   # sem conexão: erro claro antes de qualquer chamada
    etapas: list[dict[str, Any]] = []

    def chamar(nome: str, caminho: str, params: dict[str, Any] | None = None) -> Any:
        try:
            resp = magalu_api_get(caminho, params)
        except Exception as exc:
            etapas.append({"etapa": nome, "caminho": caminho, "ok": False, "erro": str(exc)[:500]})
            return None
        itens = _magalu_lista(resp)
        _magalu_guardar_amostra(f"promo_{nome}", resp if isinstance(resp, dict) else {"results": resp})
        # um registro só (detalhe da promoção) conta como 1; lista vazia ("results": []) conta 0
        tem_lista = isinstance(resp, list) or (isinstance(resp, dict) and any(
            isinstance(resp.get(k), list) for k in ("results", "data", "items", "promotions", "skus", "promos")))
        qtd = len(itens) if tem_lista else (1 if isinstance(resp, dict) and resp else 0)
        etapas.append({"etapa": nome, "caminho": caminho, "ok": True, "itens": qtd,
                       "campos": _magalu_campos(resp)[:80]})
        return resp

    # V19.54: sem filtro a Magalu devolve só as que COMEÇAM entre hoje e +30 dias (start_date_gte/lte,
    # visto em produção 18/10) — a promoção já em andamento ficava de fora. Pede desde 1 ano atrás.
    agora = datetime.now(timezone.utc)
    promos = _magalu_lista(chamar("promocoes", "/seller/v1/promotions", {
        "_limit": 50, "start_date_gte": (agora - timedelta(days=365)).isoformat(),
        "start_date_lte": (agora + timedelta(days=60)).isoformat()}))

    def peso(p: dict[str, Any]) -> int:
        tipo = p.get("type")
        tipo = tipo.get("id") if isinstance(tipo, dict) else tipo
        return (0 if tipo == "absolute_discount" else 1) + (0 if str(p.get("origin") or "") == "self_service" else 2)

    alvos = sorted((p for p in promos if isinstance(p, dict) and (p.get("id") or p.get("promotion_id"))), key=peso)[:3]
    for n, alvo in enumerate(alvos, 1):
        pid = quote(str(alvo.get("id") or alvo.get("promotion_id")), safe="")
        sufixo = "" if n == 1 else f"_{n}"
        chamar("promocao" + sufixo, f"/seller/v1/promotions/{pid}")
        chamar("promocao_skus" + sufixo, f"/seller/v1/promotions/{pid}/skus", {"_limit": 20})
    skus = _magalu_lista(chamar("catalogo_skus", "/seller/v1/portfolios/skus", {"_limit": 20}))
    codigos = []
    for item in skus:
        if isinstance(item, dict):
            codigo = item.get("sku") or item.get("code") or item.get("id")
            if isinstance(codigo, dict):
                codigo = codigo.get("code") or codigo.get("id")
            if codigo:
                codigos.append(str(codigo))
    for codigo in codigos[:MAGALU_PROMO_TESTE_SKUS]:
        chamar("preco", f"/seller/v1/portfolios/prices/{quote(codigo, safe='')}")
    resumo = {"ok": True, "promocoes": len(promos), "skus_lidos": len(skus), "etapas": etapas,
              "tipos_de_promocao": sorted({str((p.get("type") or {}).get("id") if isinstance(p.get("type"), dict) else p.get("type"))
                                           for p in promos if isinstance(p, dict)})}
    magalu_log_event("promo_teste", "/seller/v1/promotions", "OK" if all(e["ok"] for e in etapas) else "ERRO",
                     "; ".join(f"{e['etapa']}={'ok' if e['ok'] else 'erro'}" for e in etapas)[:400])
    return resumo


def magalu_pedidos_abertos() -> list[dict[str, Any]]:
    """Pedidos aprovados da Magalu (paginado). Só lê."""
    pedidos_api: list[dict[str, Any]] = []
    for pagina in range(MAGALU_PEDIDOS_MAX_PAGINAS):
        params = {"status": "approved", "_limit": MAGALU_PEDIDOS_POR_PAGINA,
                  "_offset": pagina * MAGALU_PEDIDOS_POR_PAGINA, "_sort": "purchased_at:asc"}
        resp = magalu_api_get("/seller/v1/orders", params)
        _magalu_guardar_amostra("orders", resp)
        resultados = resp.get("results") if isinstance(resp, dict) else None
        if not isinstance(resultados, list) or not resultados:
            break
        pedidos_api.extend(r for r in resultados if isinstance(r, dict))
        if len(resultados) < MAGALU_PEDIDOS_POR_PAGINA:
            break
    return pedidos_api


def magalu_pedidos_previa() -> dict[str, Any]:
    pedidos_api = magalu_pedidos_abertos()
    products_raw, _, _ = get_storage("conf_produtos")
    products = _rows_from_storage_value(products_raw)
    fila_raw, _, _ = get_storage("conf_pedidos")
    na_fila = {order_number(r) for r in _rows_from_storage_value(fila_raw) if isinstance(r, dict)}
    saida: list[dict[str, Any]] = []
    for pedido in pedidos_api:
        code = str(pedido.get("code") or "").strip()
        if not code:
            continue
        linhas_brutas: list[dict[str, Any]] = []
        limite = ""
        for entrega in pedido.get("deliveries") or []:
            if not isinstance(entrega, dict):
                continue
            if str(entrega.get("status") or "").strip().lower() not in MAGALU_ENTREGA_PARA_EXPEDIR:
                continue
            shipping = entrega.get("shipping") if isinstance(entrega.get("shipping"), dict) else {}
            handling = shipping.get("handling_time") if isinstance(shipping.get("handling_time"), dict) else {}
            limite = limite or str(handling.get("limit_date") or "")
            for item in entrega.get("items") or []:
                if not isinstance(item, dict):
                    continue
                info = item.get("info") if isinstance(item.get("info"), dict) else {}
                sku = str(info.get("sku") or "").strip()
                linhas_brutas.append({"Pedido": code, "SKU": sku, "SkuOrigemImportacao": sku,
                                      "Quantidade": str(item.get("quantity") or 1),
                                      "Descrição": str(info.get("name") or ""),
                                      "EntregaMagalu": str(entrega.get("code") or "")})
        if not linhas_brutas:
            continue
        linhas = []
        for row in _shopee_expand_kit_lines(linhas_brutas, products):  # V18.71: mesma regra de kit
            produto = _ml_find_product(products, str(row.get("SKU") or ""))
            linhas.append({
                "sku": str(row.get("SKU") or ""), "quantidade": str(row.get("Quantidade") or ""),
                "descricao": str((produto or {}).get("Descrição") or row.get("Descrição") or ""),
                "ean": str((produto or {}).get("Código de Barras") or ""),
                "kit": str(row.get("SkuKitOrigem") or ""), "entrega": str(row.get("EntregaMagalu") or ""),
                "cadastrado": bool(produto),
            })
        cliente = pedido.get("customer") if isinstance(pedido.get("customer"), dict) else {}
        saida.append({"pedido": code, "comprado_em": str(pedido.get("purchased_at") or ""),
                      "limite_envio": limite, "cliente": str(cliente.get("name") or ""),
                      "ja_na_fila": code in na_fila, "linhas": linhas})
    return {"ok": True, "pedidos": saida, "total_api": len(pedidos_api), "buscado_em": now_iso()}


# ---------------------------------------------------------------------------
# V19.27 — Magalu, fases 1b e 2: pedidos na fila (Pedidos pendentes/Conferência) e
# etiqueta automática. A importação começa LIGADA, como a dos outros marketplaces
# (decisão do dono, 14/10); o botão Desligar do cartão é a parada de emergência.
# Regras (as da Shopee): chave = número do pedido Magalu; pedido que já está na fila
# por outra origem (extensão/manual) NÃO é duplicado; kit vira componentes
# (_shopee_expand_kit_lines); linha já importada só recebe os campos operacionais
# (status, NF, etiqueta) — o resto (Nome Conferência, SKU, EAN editados) fica; tudo
# grava pelo save_storage, cujas barreiras finais (override/tombstone do ADMIN e
# concluído) valem por último. API falhou = nada é gravado (a fila não esvazia).
# Etiqueta: entrega faturada (invoiced) → POST /seller/v1/logistics/shipping-labels
# (zpl) → baixa o signed_url → conf_etiquetas (marketplace "magalu"). Sem NF a
# Magalu não libera: a linha mostra "AGUARDANDO NF".
# ---------------------------------------------------------------------------
MAGALU_SYNC_LOCK = threading.Lock()
MAGALU_PEDIDOS_INTERVALO = max(60, min(900, int(os.getenv("MAGALU_PEDIDOS_INTERVALO", "120"))))
MAGALU_CAMPOS_OPERACIONAIS = ("StatusMagalu", "Etiqueta API Magalu", "NF", "Nota Fiscal", "Chave de Acesso",
                              "PrazoEnvioMagalu", "EntregaMagalu", "EntregaIdMagalu", "CanalMagalu",
                              "MagaluAtualizadoEm")


def magalu_importacao_ligada() -> bool:
    with DB_LOCK:
        row = DB.execute("SELECT valor FROM magalu_config_v1927 WHERE chave='importacao'").fetchone()
    # V19.27: sem escolha gravada = LIGADA (decisão do dono, 14/10: "igual aos outros marketplaces").
    return True if not row else str(row["valor"]) == "1"


def magalu_importacao_definir(ligada: bool, usuario: str) -> None:
    with DB_LOCK:
        DB.execute("INSERT OR REPLACE INTO magalu_config_v1927(chave,valor,atualizado_em,atualizado_por) VALUES('importacao',?,?,?)",
                   ("1" if ligada else "0", now_iso(), str(usuario or "")))
        DB.commit()
    magalu_log_event("importacao", "", "LIGADA" if ligada else "DESLIGADA", f"por {usuario}")


def _magalu_etiquetas_vinculadas() -> set[str]:
    """IDs de entrega que já têm etiqueta da Magalu no banco de etiquetas."""
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    registros = bank.get("registros") if isinstance(bank, dict) and isinstance(bank.get("registros"), dict) else {}
    ids: set[str] = set()
    for rec in registros.values():
        if isinstance(rec, dict) and rec.get("marketplace") == "magalu":
            meta = rec.get("metadados") if isinstance(rec.get("metadados"), dict) else {}
            if str(meta.get("entrega_id") or ""):
                ids.add(str(meta.get("entrega_id")))
    return ids


class MagaluNaoEncontrado(RuntimeError):
    """V19.29: 404 da etiqueta (DELIVERY_NOT_FOUND) — vale tentar outra forma do canal."""


def _magalu_corpos_etiqueta(pedido: dict[str, Any], entrega: dict[str, Any]) -> list[dict[str, Any]]:
    """V19.29: produção 15/10 (pedido 1578270107775283) — o pedido real NÃO traz channel.id
    (a doc traz); o canal vazio deu 404 DELIVERY_NOT_FOUND. No exemplo da doc o channel.id é o
    id do vendedor sem "GENPUB.", e a entrega real traz o vendedor e a filial (branch). Tenta,
    nesta ordem: canal do vendedor + filial, canal do vendedor, id cheio do vendedor + filial e o
    channel.id do pedido (quando vier). Sem repetir corpo igual."""
    entrega_id = str(entrega.get("id") or "").strip()
    vendedor = entrega.get("seller") if isinstance(entrega.get("seller"), dict) else {}
    vendedor_id = str(vendedor.get("id") or "").strip()
    curto = vendedor_id.split(".", 1)[1] if vendedor_id.upper().startswith("GENPUB.") else vendedor_id
    filial_api = entrega.get("branch") if isinstance(entrega.get("branch"), dict) else {}
    filial = {k: str(filial_api.get(k) or "") for k in ("external_id", "name") if str(filial_api.get(k) or "")}
    canal = pedido.get("channel") if isinstance(pedido.get("channel"), dict) else {}
    canal_id = str(canal.get("id") or "").strip()
    tentativas: list[tuple[str, bool]] = []
    if curto:
        tentativas += [(curto, True), (curto, False)]
    if vendedor_id and vendedor_id != curto:
        tentativas.append((vendedor_id, True))
    if canal_id:
        tentativas.append((canal_id, True))
    corpos: list[dict[str, Any]] = []
    for cid, com_filial in tentativas:
        ent: dict[str, Any] = {"id": entrega_id}
        if com_filial and filial:
            ent["branch"] = filial
        corpo = {"channel": {"id": cid}, "deliveries": [ent], "label": {"format": "zpl", "type": "full"}}
        if corpo not in corpos:
            corpos.append(corpo)
    return corpos


def _magalu_baixar_etiqueta(corpo: dict[str, Any]) -> str:
    """Gera a etiqueta (ZPL) da entrega e baixa o conteúdo do signed_url. Isolada para teste."""
    token = magalu_access_token()
    req = urllib.request.Request(MAGALU_API_BASE + "/seller/v1/logistics/shipping-labels",
                                 data=json.dumps(corpo).encode("utf-8"), method="POST",
                                 headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json",
                                          "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            dados = json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        texto = f"Magalu etiqueta HTTP {exc.code}: {exc.read().decode('utf-8', 'replace')[:400]}"
        if exc.code == 404:
            raise MagaluNaoEncontrado(texto)
        raise RuntimeError(texto)
    _magalu_guardar_amostra("shipping_label", {"results": [dados]} if dados else {})
    label = dados.get("label") if isinstance(dados, dict) and isinstance(dados.get("label"), dict) else {}
    url = str(label.get("signed_url") or "").strip()
    if not url.startswith("https://"):
        raise RuntimeError("Magalu não devolveu o link da etiqueta.")
    with urllib.request.urlopen(urllib.request.Request(url, method="GET"), timeout=30) as resp:
        conteudo = resp.read().decode("utf-8", "replace")
    if "^XA" not in conteudo.upper():
        raise RuntimeError("O arquivo da etiqueta da Magalu não é ZPL.")
    return conteudo


def _magalu_guardar_etiqueta(pedido: str, entrega_code: str, entrega_id: str, nf: str, zpl: str) -> None:
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    if not isinstance(bank, dict):
        bank = {}
    bank["version"] = max(8, int(bank.get("version") or 0))
    for chave, padrao in (("registros", {}), ("ordem", []), ("porChave", {}), ("avisos", []),
                          ("auditoria", []), ("resumo", {}), ("vinculados", {})):
        bank.setdefault(chave, padrao)
    rid = "etq_magalu_api_" + hashlib.sha1(entrega_id.encode("utf-8")).hexdigest()[:18]
    chaves = [x for x in (pedido, entrega_code, entrega_id, nf) if x]
    bank["registros"][rid] = {
        "id": rid, "marketplace": "magalu", "envio": zpl, "danfe": "",
        "arquivo": f"Magalu API · entrega {entrega_code or entrega_id}",
        "metadados": {"pedido": pedido, "entrega": entrega_code, "entrega_id": entrega_id, "chaveAcesso": nf},
        "chaves": chaves, "vinculadoA": [pedido], "pedido": pedido,
        "vinculo": "api_magalu", "origem": "api_magalu",
        "adicionadaEm": now_iso(), "adicionadaPor": "magalu-api",
    }
    if rid not in bank["ordem"]:
        bank["ordem"].append(rid)
    for chave in chaves:
        bank["porChave"].setdefault(chave, [])
        if rid not in bank["porChave"][chave]:
            bank["porChave"][chave].append(rid)
    bank["atualizadoEm"] = now_iso()
    bank["auditoria"].append({"marketplace": "magalu", "pedido": pedido, "criterio": "api_magalu",
                              "etiqueta": rid, "arquivo": bank["registros"][rid]["arquivo"]})
    bank["auditoria"] = bank["auditoria"][-250:]
    save_storage("conf_etiquetas", raw, json_dumps(bank), False, actor="magalu-api", actor_role="sistema",
                 source_screen="API Magalu", change_method="Etiqueta automática após NF", client_ip="127.0.0.1")


def _magalu_linhas_do_pedido(pedido: dict[str, Any], products: list[dict[str, Any]],
                             com_etiqueta: set[str]) -> list[dict[str, Any]]:
    code = str(pedido.get("code") or "").strip()
    cliente = pedido.get("customer") if isinstance(pedido.get("customer"), dict) else {}
    canal = pedido.get("channel") if isinstance(pedido.get("channel"), dict) else {}
    linhas: list[dict[str, Any]] = []
    for entrega in pedido.get("deliveries") or []:
        if not isinstance(entrega, dict):
            continue
        status = str(entrega.get("status") or "").strip().lower()
        if status not in MAGALU_ENTREGA_PARA_EXPEDIR:
            continue
        entrega_id = str(entrega.get("id") or "").strip()
        shipping = entrega.get("shipping") if isinstance(entrega.get("shipping"), dict) else {}
        handling = shipping.get("handling_time") if isinstance(shipping.get("handling_time"), dict) else {}
        notas = [n for n in (entrega.get("invoices") or []) if isinstance(n, dict)]
        nf = str((notas[-1] if notas else {}).get("key") or "").strip()
        if entrega_id in com_etiqueta:
            etiqueta = "VINCULADA"
        elif status == "invoiced":
            etiqueta = "AGUARDANDO"
        else:
            etiqueta = "AGUARDANDO NF"
        for indice, item in enumerate(entrega.get("items") or []):
            if not isinstance(item, dict):
                continue
            info = item.get("info") if isinstance(item.get("info"), dict) else {}
            sku = str(info.get("sku") or "").strip()
            if not sku:
                continue
            try:
                qtd = max(1, int(float(item.get("quantity") or 1)))
            except Exception:
                qtd = 1
            identidade = f"{code}|{entrega_id}|{info.get('id') or ''}|{sku}|{item.get('sequencial') or indice}"
            row = {
                "Pedido": code, "Marketplace": "MAGALU",
                "Data do Pedido": str(pedido.get("purchased_at") or "")[:10],
                "Kit": "", "Nome do Kit": "", "Quantidade de Kits": "", "Quantidade por Kit": "",
                "Cliente": str(cliente.get("name") or ""), "NomeFiscalMagalu": str(cliente.get("name") or ""),
                "SKU": sku, "Quantidade": str(qtd), "Código de Barras": "",
                "Descrição": str(info.get("name") or ""),
                "Rua": "", "Módulo": "", "Prateleira": "", "Nível": "", "Posição": "", "Foto": "",
                "NF": nf, "Nota Fiscal": nf, "Chave de Acesso": nf,
                "StatusMagalu": status, "Etiqueta API Magalu": etiqueta,
                "PrazoEnvioMagalu": str(handling.get("limit_date") or ""),
                "EntregaMagalu": str(entrega.get("code") or ""), "EntregaIdMagalu": entrega_id,
                "CanalMagalu": str(canal.get("id") or ""),
                "OrigemCadastro": "API_MAGALU", "SkuOrigemImportacao": sku,
                "MagaluAtualizadoEm": now_iso(), "CriadoEm": now_iso(),
                "__uidLinha": "MAGALUAPI_" + hashlib.sha1(identidade.encode("utf-8")).hexdigest()[:20],
            }
            produto = _ml_find_product(products, sku)
            if produto:
                for campo in ("SKU", "Código de Barras", "Descrição", "Rua", "Módulo", "Prateleira", "Nível", "Posição", "Foto"):
                    if str(produto.get(campo) or "").strip():
                        row[campo] = produto.get(campo)
            linhas.append(row)
    linhas = _sem_linhas_excluidas_admin_v2022(linhas)  # V20.22: antes de abrir o kit
    return _shopee_expand_kit_lines(linhas, products)  # V18.71: mesma regra de kit


def _magalu_merge(atual: list[dict[str, Any]], api: list[dict[str, Any]], origem: str = "API_MAGALU",
                  campos: tuple[str, ...] = MAGALU_CAMPOS_OPERACIONAIS) -> tuple[list[dict[str, Any]], set[str], int]:
    """Junta as linhas da API à fila. Retorna (fila, identidades removidas, pedidos pulados por já existirem).
    V19.64: `origem`/`campos` deixam o TikTok usar a mesma regra (API_TIKTOK)."""
    origem = normalize(origem)
    pedidos_outra_origem = {normalize(order_number(r)) for r in atual
                            if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) != origem}
    ativos = {normalize(order_number(r)) for r in api}
    antigos: dict[str, dict[str, Any]] = {}
    saida: list[dict[str, Any]] = []
    removidas: set[str] = set()
    for indice, row in enumerate(atual):
        if not isinstance(row, dict):
            continue
        if normalize(row.get("OrigemCadastro")) != origem:
            saida.append(row)
        elif normalize(order_number(row)) in ativos:
            antigos[str(row.get("__uidLinha") or "")] = row
        else:
            removidas.add(_pending_identity_v1714(row, indice))  # entrega enviada/cancelada: sai
    pulados: set[str] = set()
    for nova in api:
        pedido = normalize(order_number(nova))
        if pedido in pedidos_outra_origem:
            pulados.add(pedido)  # veio pela extensão/manual: não duplica
            continue
        velha = antigos.get(str(nova.get("__uidLinha") or ""))
        if velha:
            junta = dict(velha)
            for campo in campos:
                if campo in nova:
                    junta[campo] = nova[campo]
            saida.append(junta)
        else:
            saida.append(nova)
    return saida, removidas, len(pulados)


def magalu_importar_pedidos() -> dict[str, Any]:
    with MAGALU_SYNC_LOCK:
        pedidos_api = magalu_pedidos_abertos()  # erro aqui = nada gravado
        products_raw, _, _ = get_storage("conf_produtos")
        products = _rows_from_storage_value(products_raw)
        # Fase 2: etiqueta das entregas faturadas que ainda não têm (antes de montar as
        # linhas, para a linha já sair com "VINCULADA").
        com_etiqueta = _magalu_etiquetas_vinculadas()
        etiquetas_novas = erros_etiqueta = 0
        for pedido in pedidos_api:
            code = str(pedido.get("code") or "").strip()
            canal = pedido.get("channel") if isinstance(pedido.get("channel"), dict) else {}
            for entrega in pedido.get("deliveries") or []:
                if not isinstance(entrega, dict) or str(entrega.get("status") or "").lower() != "invoiced":
                    continue
                entrega_id = str(entrega.get("id") or "").strip()
                if not entrega_id or entrega_id in com_etiqueta:
                    continue
                notas = [n for n in (entrega.get("invoices") or []) if isinstance(n, dict)]
                try:
                    zpl = ""
                    ultimo_404: Exception | None = None
                    for corpo in _magalu_corpos_etiqueta(pedido, entrega):  # V19.29
                        try:
                            zpl = _magalu_baixar_etiqueta(corpo)
                            break
                        except MagaluNaoEncontrado as exc404:
                            ultimo_404 = exc404  # tenta a próxima forma do canal
                    if not zpl:
                        raise ultimo_404 or RuntimeError("Sem dados da entrega para pedir a etiqueta (vendedor/canal).")
                    _magalu_guardar_etiqueta(code, str(entrega.get("code") or ""), entrega_id,
                                             str((notas[-1] if notas else {}).get("key") or ""), zpl)
                    com_etiqueta.add(entrega_id)
                    etiquetas_novas += 1
                except Exception as exc:
                    erros_etiqueta += 1
                    magalu_log_event_se_mudou("etiqueta", f"pedido={code} entrega={entrega_id}", "ERRO", str(exc)[:800])
        api_linhas: list[dict[str, Any]] = []
        for pedido in pedidos_api:
            api_linhas.extend(_magalu_linhas_do_pedido(pedido, products, com_etiqueta))
        atual_raw, _, _ = get_storage("conf_pedidos")
        atual = _rows_from_storage_value(atual_raw)
        fila, removidas, pulados = _magalu_merge(atual, api_linhas)
        save_storage("conf_pedidos", atual_raw, json_dumps(fila), False,
                     actor="sistema", actor_role="sistema", source_screen="Admin / Integrações / Magalu",
                     change_method="Sincronização API Magalu", client_ip="127.0.0.1",
                     allow_completed_reimport=False,
                     # V18.52: remoção NOMEADA (entrega enviada/cancelada) — só as linhas
                     # da API que saíram; linha protegida pelo ADMIN nunca sai por aqui.
                     remove_pending_identities=removidas)
        with DB_LOCK:
            DB.execute("UPDATE magalu_integration SET last_sync_at=?, last_error='' WHERE id=1", (now_iso(),))
            DB.commit()
        resumo = {"ok": True, "pedidos": len({order_number(r) for r in api_linhas}), "linhas": len(api_linhas),
                  "removidas": len(removidas), "ja_na_fila_por_outra_origem": pulados,
                  "etiquetas_novas": etiquetas_novas, "erros_etiqueta": erros_etiqueta}
        magalu_log_event_se_mudou("pedidos", "/seller/v1/orders", "OK",
                                  f"{resumo['pedidos']} pedido(s), {resumo['linhas']} linha(s), {len(removidas)} removida(s), "
                                  f"{pulados} já na fila, {etiquetas_novas} etiqueta(s) nova(s)")
        return resumo


_MAGALU_LOG_ULTIMO: dict[tuple[str, str], tuple[str, str]] = {}


def magalu_log_event_se_mudou(topic: str, resource: str, result: str, detail: str = "") -> bool:
    """V18.78: o worker só grava no log quando (resultado, detalhe) mudou."""
    chave = (topic, resource)
    if _MAGALU_LOG_ULTIMO.get(chave) == (result, detail):
        return False
    _MAGALU_LOG_ULTIMO[chave] = (result, detail)
    magalu_log_event(topic, resource, result, detail)
    return True


def magalu_rodada() -> dict[str, Any]:
    """Uma volta do worker: mantém o token vivo e, com a chave ligada, importa."""
    if not magalu_status_payload().get("connected"):
        return {"importou": False, "motivo": "desconectada"}
    magalu_access_token()  # renova perto do vencimento, mesmo com a importação desligada
    if not magalu_importacao_ligada():
        return {"importou": False, "motivo": "importacao_desligada"}
    return {"importou": True, **magalu_importar_pedidos()}


def magalu_pedidos_loop(stop_event: threading.Event) -> None:
    stop_event.wait(45)
    while not stop_event.is_set():
        try:
            magalu_rodada()
        except Exception as exc:
            with DB_LOCK:
                DB.execute("UPDATE magalu_integration SET last_error=? WHERE id=1", (str(exc)[:500],))
                DB.commit()
            magalu_log_event_se_mudou("pedidos", "worker", "ERRO", str(exc)[:800])
        stop_event.wait(MAGALU_PEDIDOS_INTERVALO)


