def _tiktok_estoque_log(sku_id: str, seller_sku: str, de: int | None, para: int | None, modo: str,
                        resultado: str, detalhe: str, por: str) -> None:
    with DB_LOCK:
        DB.execute("""INSERT INTO tiktok_estoque_log_v1964(criado_em,sku_id,seller_sku,de,para,modo,resultado,detalhe,por)
                      VALUES(?,?,?,?,?,?,?,?,?)""",
                   (now_iso(), sku_id, seller_sku, de, para, modo, resultado, str(detalhe or "")[:800], str(por or "")))
        DB.execute("DELETE FROM tiktok_estoque_log_v1964 WHERE id <= (SELECT MAX(id) FROM tiktok_estoque_log_v1964) - 5000")
        DB.commit()


def _tiktok_pecas(texto: Any) -> list[tuple[str, int]]:
    """seller_sku (ou vínculo à mão) → [(código Apollo, unidades)]. "A/B" = uma de cada;
    "KITn-X" = n unidades de X; "151490-0893270212" (anúncio-código) = o código."""
    saida: dict[str, int] = {}
    ordem: list[str] = []
    for parte in str(texto or "").strip().upper().split("/"):
        parte = parte.strip()
        unidades = 1
        m = re.match(r"^KIT(\d*)-(.+)$", parte)
        if m:
            unidades = max(1, int(m.group(1) or 1))
            parte = m.group(2).strip()
        if re.match(r"^\d{5,}-.+", parte):
            parte = parte.split("-", 1)[1].strip()
        if not _exp_norm_codigo(parte):
            continue
        if parte not in saida:
            ordem.append(parte)
            saida[parte] = 0
        saida[parte] += unidades
    return [(c, saida[c]) for c in ordem]


def _tiktok_sku_cortado(row: dict[str, Any]) -> bool:
    """V20.08: SKU no limite do TikTok sem vínculo à mão. O fim pode ter sido perdido (código pela
    metade ou peça inteira), então nem lê o Apollo nem envia até alguém confirmar o código."""
    return not row.get("vinculo") and len(str(row.get("seller_sku") or "")) >= TIKTOK_SKU_LIMITE


def tiktok_sugerir_sku(seller_sku: Any, conhecidos: set[str]) -> list[str]:
    """V20.08: SKU cortado com o último código completado pelo cadastro. Só sugere: quem confirma é
    o ADMIN, no vínculo à mão. Mais de 6 códigos com o mesmo começo não ajudam a escolher. O próprio
    trecho nunca é sugerido: o botão gravaria o SKU cortado como vínculo e soltaria a trava."""
    texto = str(seller_sku or "").strip().upper()
    base, barra, ultima = texto.rpartition("/")
    ultima = ultima.strip()
    if not ultima:
        return []
    achados = sorted(c for c in conhecidos if c.startswith(ultima) and c != ultima)
    return [f"{base}{barra}{c}" for c in achados] if len(achados) <= 6 else []


def _tiktok_quantidade(valor: Any) -> int | None:
    try:
        return int(float(valor))
    except (TypeError, ValueError, OverflowError):  # V19.81: "Infinity" vindo da extensão
        return None


def tiktok_produtos_sincronizar() -> dict[str, Any]:
    """Lê todos os anúncios da loja (paginado) e guarda cada variação. Só lê."""
    vistos: dict[str, dict[str, Any]] = {}
    token = ""
    for _ in range(200):
        params: dict[str, Any] = {"page_size": 100}
        if token:
            params["page_token"] = token
        resp = tiktok_api("POST", "/product/202502/products/search", params=params, body={"status": "ALL"})
        dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
        for prod in dados.get("products") or []:
            if not isinstance(prod, dict):
                continue
            status = str(prod.get("status") or "")
            if status in ("DELETED", "PLATFORM_DEACTIVATED_DELETED", "SELLER_DELETED"):
                continue
            for sku in prod.get("skus") or []:
                if not isinstance(sku, dict) or not str(sku.get("id") or "").strip():
                    continue
                inv = [i for i in (sku.get("inventory") or []) if isinstance(i, dict)]
                vistos[str(sku["id"])] = {
                    "product_id": str(prod.get("id") or ""), "titulo": str(prod.get("title") or "")[:300],
                    "status": status, "seller_sku": str(sku.get("seller_sku") or "").strip(),
                    "warehouse_id": str((inv[0] if inv else {}).get("warehouse_id") or ""),
                    "armazens": len(inv),
                    "qtd": _tiktok_quantidade((inv[0] if inv else {}).get("quantity")) if len(inv) == 1 else None,
                }
        token = str(dados.get("next_page_token") or "")
        if not token:
            break
    # revisar-antes-de-subir (V20.40): as travas da extensão (V19.81) também aqui. Lista vazia ou leitura que parou
    # antes da última página nunca apaga; leitura com menos de 70% do que existe também não.
    apagar = bool(vistos) and not token
    if apagar:
        with DB_LOCK:
            existentes = int(DB.execute("SELECT COUNT(*) FROM tiktok_sku_v1964").fetchone()[0])
        if existentes >= 10 and len(vistos) < existentes * TIKTOK_LEITURA_MINIMA:
            apagar = False
    return _tiktok_sku_gravar(vistos, apagar_ausentes=apagar)


TIKTOK_CATALOGO_LOCK = threading.Lock()  # revisar-antes-de-subir (V20.40): uma leitura dos anúncios por vez


def tiktok_catalogo_iniciar() -> bool:
    """Botão "Atualizar anúncios" (fonte API): lê o catálogo numa thread. False = já tem uma rodando."""
    if not TIKTOK_CATALOGO_LOCK.acquire(blocking=False):
        return False

    def rodar() -> None:
        try:
            tiktok_produtos_sincronizar()
        except Exception as exc:
            tiktok_log_event_se_mudou("anuncios", "atualizar", "ERRO", str(exc)[:800])
        finally:
            TIKTOK_CATALOGO_LOCK.release()
    threading.Thread(target=rodar, name="tiktok-catalogo", daemon=True).start()
    return True


def _tiktok_sku_gravar(vistos: dict[str, dict[str, Any]], apagar_ausentes: bool) -> dict[str, Any]:
    agora = now_iso()
    with DB_LOCK:
        for sku_id, v in vistos.items():
            DB.execute("""INSERT INTO tiktok_sku_v1964(sku_id,product_id,titulo,status,seller_sku,warehouse_id,armazens,qtd_tiktok,visto_em)
                          VALUES(?,?,?,?,?,?,?,?,?)
                          ON CONFLICT(sku_id) DO UPDATE SET product_id=excluded.product_id, titulo=excluded.titulo,
                            status=excluded.status, seller_sku=excluded.seller_sku, warehouse_id=excluded.warehouse_id,
                            armazens=excluded.armazens, qtd_tiktok=excluded.qtd_tiktok, visto_em=excluded.visto_em""",
                       (sku_id, v["product_id"], v["titulo"], v["status"], v["seller_sku"], v["warehouse_id"],
                        v["armazens"], v["qtd"], agora))
        # Variação que sumiu da loja sai da lista (o vínculo à mão fica guardado).
        if apagar_ausentes:
            # V19.81: pelos ids vistos, não pelo horário (duas leituras no mesmo segundo).
            for row in DB.execute("SELECT sku_id FROM tiktok_sku_v1964").fetchall():
                if str(row["sku_id"]) not in vistos:
                    DB.execute("DELETE FROM tiktok_sku_v1964 WHERE sku_id=?", (row["sku_id"],))
        _tiktok_anuncios_espelhar()  # V20.40: os mesmos anúncios na plataforma de anúncios (/anuncios)
        DB.commit()
    return {"ok": True, "variacoes": len(vistos), "apagou": bool(apagar_ausentes)}


# V20.40 — anúncios do TikTok de Bauru na plataforma de anúncios (decisão do dono, 07/11: "listar e ligar à ficha").
# Cada variação lida (pela API ou pela extensão) vira uma linha canal='tiktok', conta='bauru', anuncio_id = id da
# variação, ligada à ficha pelo SKU do vendedor (o vínculo à mão da tela Estoque TikTok vence). `controle='tiktok'`:
# o estoque é da tela Estoque TikTok (V19.64/V19.81) — o controle de estoque da plataforma (V20.26) só age em
# `controle='noromak'`, e "Passar para o Noromak" recusa o canal. Só o nosso banco: nada é lido nem gravado no TikTok
# aqui. Variação que sumiu da loja fica como estava (regra do puxar do ML); removido pelo ADMIN não volta.
TIKTOK_ANUNCIO_CANAL = "tiktok"
TIKTOK_ANUNCIO_CONTROLE = "tiktok"
# V20.41 (dono, 07/11: "plataforma, por anúncio"): com a fonte "api" os anúncios do TikTok ficam com controle 'noromak' e
# ganham Manual/Automático em /anuncios (conta de estoque 'tiktok'); com a extensão, 'tiktok' (a tela Estoque TikTok manda).


def _tiktok_controle_atual() -> str:
    return "noromak" if tiktok_fonte() == "api" else TIKTOK_ANUNCIO_CONTROLE
TIKTOK_STATUS_HUB = {"ACTIVATE": "active", "SELLER_DEACTIVATED": "paused", "PLATFORM_DEACTIVATED": "paused",
                     "FREEZE": "paused", "PENDING": "under_review", "DRAFT": "inactive", "FAILED": "inactive"}


def _tiktok_anuncio_estoque(sku_id: str, qtd: Any) -> None:
    """V20.40: estoque gravado no TikTok aparece na plataforma de anúncios na hora (quem chama segura o DB_LOCK)."""
    if qtd is None:
        return
    DB.execute("UPDATE anuncio_canal_v2023 SET estoque=? WHERE canal=? AND conta=? AND anuncio_id=? AND removido_em=''",
               (qtd, TIKTOK_ANUNCIO_CANAL, TIKTOK_CASA, str(sku_id)))


def tiktok_anuncios_espelhar_boot() -> None:
    """V20.40: no boot, o que já estava em tiktok_sku_v1964 entra na plataforma de anúncios (sem chamar o TikTok)."""
    try:
        with DB_LOCK:
            _tiktok_anuncios_espelhar()
            DB.commit()
    except sqlite3.Error as exc:
        print(f"Aviso: anúncios do TikTok não espelhados: {exc}", file=sys.stderr)


def _tiktok_anuncios_espelhar() -> int:
    """Espelha tiktok_sku_v1964 em anuncio_canal_v2023. Quem chama segura o DB_LOCK e faz o commit."""
    vinculos = {str(r["sku_id"]): str(r["codigos"] or "") for r in DB.execute("SELECT sku_id, codigos FROM tiktok_vinculo_v1964")}
    controle = _tiktok_controle_atual()  # V20.41
    # revisar-antes-de-subir (V20.40): uma leitura só e grava só o que mudou (sem regravar centenas de linhas)
    atuais = {str(r["anuncio_id"]): r for r in DB.execute(
        "SELECT * FROM anuncio_canal_v2023 WHERE canal=? AND conta=?", (TIKTOK_ANUNCIO_CANAL, TIKTOK_CASA))}
    n = 0
    agora = now_iso()
    for r in DB.execute("SELECT * FROM tiktok_sku_v1964").fetchall():
        sku_id = str(r["sku_id"])
        sku = vinculos.get(sku_id) or str(r["seller_sku"] or "")
        ficha = normalize(sku) if str(sku).strip() else ""
        status = TIKTOK_STATUS_HUB.get(str(r["status"] or "").upper(), str(r["status"] or "").lower())
        atual = atuais.get(sku_id)
        if atual is not None and str(atual["removido_em"] or ""):
            continue  # removido pelo ADMIN: não é atualizado nem recriado
        if atual is not None and (str(atual["ficha_codigo"] or ""), str(atual["sku_anuncio"] or ""),
                                  str(atual["controle"] or ""), str(atual["status"] or ""),
                                  str(atual["user_product_id"] or "")) == (
                ficha, str(r["seller_sku"] or ""), controle, status, str(r["product_id"] or "")) \
                and (not str(r["titulo"] or "") or str(atual["titulo"] or "") == str(r["titulo"] or "")) \
                and (r["qtd_tiktok"] is None or atual["estoque"] == r["qtd_tiktok"]):
            continue  # nada mudou
        if atual is None:
            DB.execute("INSERT INTO anuncio_canal_v2023(canal,conta,anuncio_id,ficha_codigo,sku_anuncio,controle,titulo,"
                       "estoque,status,user_product_id,lido_em) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                       (TIKTOK_ANUNCIO_CANAL, TIKTOK_CASA, sku_id, ficha, str(r["seller_sku"] or ""),
                        controle, str(r["titulo"] or ""), r["qtd_tiktok"], status,
                        str(r["product_id"] or ""), agora))
        else:
            # V20.41: o controle segue a fonte; saiu do Noromak = o Automático vira Manual (nunca religa sozinho)
            DB.execute("UPDATE anuncio_canal_v2023 SET ficha_codigo=?, sku_anuncio=?, controle=?, "
                       "estoque_modo=CASE WHEN ?<>'noromak' THEN 'manual' ELSE estoque_modo END, "
                       "titulo=COALESCE(NULLIF(?,''),titulo), estoque=COALESCE(?,estoque), status=?, user_product_id=?, "
                       "lido_em=? WHERE canal=? AND conta=? AND anuncio_id=?",
                       (ficha, str(r["seller_sku"] or ""), controle, controle, str(r["titulo"] or ""),
                        r["qtd_tiktok"], status, str(r["product_id"] or ""), agora,
                        TIKTOK_ANUNCIO_CANAL, TIKTOK_CASA, sku_id))
        n += 1
    return n


# V19.81: sem a Open API (o TikTok exige gerente de contas), a extensão NOROMAK_TIKTOK_ESTOQUE
# lê a lista de produtos do Seller Center (sessão do vendedor no Edge) e manda para cá; o
# cálculo é o mesmo da V19.64. Quem grava no TikTok é a extensão, e ela devolve o resultado.
# O Seller Center grava por DIFERENÇA (quantity_variation): duas rodadas juntas somariam duas
# vezes, por isso só existe uma rodada de envio por vez (TIKTOK_RODADA, vence sozinha).
TIKTOK_RODADA_PRAZO = 15 * 60
TIKTOK_EXTENSAO_RECENTE = 6 * 3600  # sem a API, o Apollo só é lido se a extensão leu a loja há menos que isto
TIKTOK_LEITURA_MINIMA = 0.7  # leitura "completa" com menos de 70% do que já existe não apaga ninguém
TIKTOK_RODADA: dict[str, Any] = {}


class TikTokRodadaOcupada(Exception):
    pass


def _tiktok_texto(valor: Any, limite: int) -> str:
    return str(valor if valor is not None else "").strip()[:limite]


def tiktok_produtos_da_extensao(produtos: Any, completo: bool) -> dict[str, Any]:
    """Estoque por SKU do Seller Center, agrupado por produto pela extensão. `completo` = a
    extensão leu todas as páginas: só então quem não veio sai da lista."""
    _tiktok_recusar_extensao()  # V20.40: com a fonte "api" quem lê os anúncios é a API
    if not isinstance(produtos, list):
        raise ValueError("Lista de produtos inválida.")
    if completo and not produtos:
        raise ValueError("Lista de produtos vazia: nada foi alterado.")  # leitura que falhou não esvazia a loja
    vistos: dict[str, dict[str, Any]] = {}
    for prod in produtos:
        if not isinstance(prod, dict) or not isinstance(prod.get("skus"), list):
            continue
        for sku in prod["skus"]:
            sku_id = _tiktok_texto(sku.get("id"), 64) if isinstance(sku, dict) else ""
            if not sku_id:
                continue
            inv = [q for q in (sku.get("quantities") if isinstance(sku.get("quantities"), list) else []) if isinstance(q, dict)]
            vistos[sku_id] = {
                "product_id": _tiktok_texto(prod.get("product_id"), 64), "titulo": _tiktok_texto(prod.get("product_name"), 300),
                "status": _tiktok_texto(prod.get("product_status"), 40),
                "seller_sku": _tiktok_texto(sku.get("seller_sku"), 120),
                "warehouse_id": _tiktok_texto((inv[0] if inv else {}).get("warehouse_id"), 64),
                "armazens": len(inv),
                # quantidade vazia fica nula (nunca vira "enviar" contra um número inventado)
                "qtd": _tiktok_quantidade((inv[0] if inv else {}).get("available_quantity")) if len(inv) == 1 else None,
            }
    apagar = bool(completo)
    if apagar:
        with DB_LOCK:
            existentes = int(DB.execute("SELECT COUNT(*) FROM tiktok_sku_v1964").fetchone()[0])
        if existentes >= 10 and len(vistos) < existentes * TIKTOK_LEITURA_MINIMA:
            apagar = False  # leitura cortada que se diz completa: não some com a loja
    res = _tiktok_sku_gravar(vistos, apagar_ausentes=apagar)
    _tiktok_config_gravar("extensao_lida_epoch", str(int(time.time())), "extensao")
    if completo and not apagar:
        res["aviso"] = "Leitura bem menor que a lista atual: nenhuma variação foi apagada."
    return res


def tiktok_extensao_pendentes() -> dict[str, Any]:
    modo = tiktok_estoque_config()["modo_estoque"]
    itens = [{"sku_id": i["sku_id"], "product_id": i["product_id"], "warehouse_id": i["warehouse_id"],
              "seller_sku": i["seller_sku"], "titulo": i["titulo"], "tiktok": i["tiktok"], "desejado": i["desejado"],
              "apollo": i["apollo"], "pendente": i["pendente"]}
             for i in tiktok_estoque_itens() if i["situacao"] == "enviar"]
    if tiktok_fonte() == "api":  # revisar-antes-de-subir (V20.40): a vez é da API
        return {"ok": True, "modo": modo, "pode_enviar": False, "itens": [], "fonte": "api"}
    return {"ok": True, "modo": modo, "pode_enviar": modo != "simulacao", "itens": itens, "fonte": "extensao"}


def tiktok_extensao_iniciar(ator: str) -> dict[str, Any]:
    """Abre a rodada de envio (uma por vez) e devolve a lista a gravar."""
    with TIKTOK_ESTOQUE_LOCK:
        _tiktok_recusar_extensao()  # V20.40: dentro da trava (a troca de fonte também a usa)
        p = tiktok_extensao_pendentes()
        if not p["pode_enviar"]:
            raise ValueError("O Noromak está em Simulação: nada é gravado no TikTok. Mude para Lote na tela Estoque TikTok.")
        agora = time.time()
        if TIKTOK_RODADA and agora - float(TIKTOK_RODADA.get("desde") or 0) < TIKTOK_RODADA_PRAZO:
            raise TikTokRodadaOcupada(f"Já tem um envio em andamento (por {TIKTOK_RODADA.get('por')}). Espere ele terminar.")
        TIKTOK_RODADA.clear()
        TIKTOK_RODADA.update(id=secrets.token_hex(8), desde=agora, por=str(ator or ""))
        p["rodada"] = TIKTOK_RODADA["id"]
        return p


def tiktok_extensao_resultado(resultados: Any, ator: str, rodada: str = "", fim: bool = False) -> dict[str, Any]:
    if not isinstance(resultados, list):
        raise ValueError("Resultados inválidos.")
    modo = tiktok_estoque_config()["modo_estoque"]
    ok_count = erros = ignorados = 0
    with TIKTOK_ESTOQUE_LOCK:
        for r in resultados[:2000]:
            sku_id = _tiktok_texto(r.get("sku_id"), 64) if isinstance(r, dict) else ""
            with DB_LOCK:
                row = DB.execute("SELECT seller_sku FROM tiktok_sku_v1964 WHERE sku_id=?", (sku_id,)).fetchone()
            if not row:
                ignorados += 1
                continue
            de, para = _tiktok_quantidade(r.get("de")), _tiktok_quantidade(r.get("para"))
            final = _tiktok_quantidade(r.get("final"))
            if final is not None:
                # o que o TikTok disse que ficou é o dado real, certo ou errado
                with DB_LOCK:
                    DB.execute("UPDATE tiktok_sku_v1964 SET qtd_tiktok=? WHERE sku_id=?", (final, sku_id))
                    _tiktok_anuncio_estoque(sku_id, final)  # V20.40
                    DB.commit()
            if r.get("ok") is True and final is not None and final == para:
                ok_count += 1
                _tiktok_estoque_log(sku_id, row["seller_sku"], de, para, modo, "OK",
                                    f"pela extensão do Seller Center; TikTok ficou com {final}", ator)
                continue
            erros += 1
            if r.get("ok") is True:
                motivo = "o TikTok não confirmou a quantidade" if final is None else f"o TikTok ficou com {final}, não {para}"
            else:
                motivo = _tiktok_texto(r.get("erro"), 400) or "sem detalhe"
            _tiktok_estoque_log(sku_id, row["seller_sku"], de, para, modo, "ERRO", f"pela extensão: {motivo}", ator)
        if rodada and TIKTOK_RODADA.get("id") == rodada:
            if fim:
                TIKTOK_RODADA.clear()
            else:
                TIKTOK_RODADA["desde"] = time.time()  # cada item devolvido renova a rodada (rodada longa não vence)
    return {"ok": True, "ok_count": ok_count, "erros": erros, "ignorados": ignorados}


# V19.84: preço ideal do TikTok (loja de Bauru), pela extensão. Decisões do dono (23/10): afiliado
# fixo de 5% em TODA venda (a margem nunca fura na venda por afiliado); loja inteira no programa de
# frete grátis (6%, teto de R$ 50 por produto); imposto = o do Financeiro; custo = Apollo de BAURU.
# Tarifa do TikTok BR desde 15/07/2026 (preço já com o desconto do vendedor). Margem = lucro ÷ preço.
TIKTOK_FAIXAS_TARIFA = ((50.0, 10.0, 4.0), (float("inf"), 6.0, 6.0))  # (até, comissão %, fixo R$)
TIKTOK_FRETE_TETO = 50.0
TIKTOK_REVENDA_CUSTO = 3  # Bauru no Apollo


def tiktok_preco_config() -> dict[str, float]:
    def num(chave: str, padrao: float) -> float:
        try:
            return float(_tiktok_config_ler(chave) or padrao)
        except (TypeError, ValueError):
            return padrao
    return {"afiliado": num("preco_afiliado_pct", 5.0), "frete": num("preco_frete_pct", 6.0),
            "imposto": float(FINANCEIRO_IMPOSTO_PERCENT)}


def _tiktok_faixa(preco: float) -> tuple[float, float, float]:
    return next(f for f in TIKTOK_FAIXAS_TARIFA if preco < f[0])


def tiktok_preco_detalhe(preco: float, custo: float, cfg: dict[str, float]) -> dict[str, Any]:
    _, comissao_pct, fixo = _tiktok_faixa(preco)
    partes = {"imposto": preco * cfg["imposto"] / 100, "afiliado": preco * cfg["afiliado"] / 100,
              "tarifa": preco * comissao_pct / 100 + fixo, "frete": min(preco * cfg["frete"] / 100, TIKTOK_FRETE_TETO)}
    lucro = preco - custo - sum(partes.values())
    return {"preco": round(preco, 2), "custo": round(custo, 2), **{k: round(v, 2) for k, v in partes.items()},
            "lucro": round(lucro, 2), "margem": round(lucro / preco * 100, 2) if preco > 0 else None,
            "faixa": f"{comissao_pct:g}% + R$ {fixo:.2f}".replace(".", ",")}


def tiktok_preco_ideal(custo: float, margem: float, cfg: dict[str, float]) -> dict[str, Any] | None:
    """Menor preço que dá a margem pedida. Cada faixa da tarifa e o teto do frete mudam a conta,
    então tenta cada combinação e fica com a que cai dentro da própria faixa."""
    base = (cfg["imposto"] + cfg["afiliado"] + margem) / 100
    inicio = 0.0
    for ate, comissao_pct, fixo in TIKTOK_FAIXAS_TARIFA:
        for frete_prop in (True, False):
            denom = 1 - base - comissao_pct / 100 - (cfg["frete"] / 100 if frete_prop else 0)
            if denom <= 0:
                continue
            preco = (custo + fixo + (0 if frete_prop else TIKTOK_FRETE_TETO)) / denom
            frete_ok = (preco * cfg["frete"] / 100 <= TIKTOK_FRETE_TETO) == frete_prop
            if inicio <= preco < ate and frete_ok:
                preco = round(preco, 2)
                return tiktok_preco_detalhe(preco, custo, cfg)
        # buraco entre as faixas: o começo da faixa seguinte já dá a margem?
        if ate != float("inf") and tiktok_preco_detalhe(ate, custo, cfg)["margem"] >= margem:
            return tiktok_preco_detalhe(ate, custo, cfg)
        inicio = ate
    return None


def _tiktok_custo_bauru(codigo: str) -> tuple[float | None, str]:
    try:
        r = crm_cost_lookup(codigo, operador="tiktok-preco", wait_seconds=5)
        for c in r.get("custos") or []:
            if int(c.get("revenda") or 0) == TIKTOK_REVENDA_CUSTO and float(c.get("custo_medio") or 0) > 0:
                return float(c["custo_medio"]), "Apollo de Bauru (agora)"
        erro = "Bauru sem custo no Apollo (estoque zerado?)"
    except Exception as exc:
        erro = str(exc)[:120]
    with DB_LOCK:
        row = DB.execute("SELECT custos_json,data FROM custo_apollo_v1931 WHERE codigo=?", (codigo.upper(),)).fetchone()
    try:
        guardado = float(json.loads(row["custos_json"]).get(str(TIKTOK_REVENDA_CUSTO)) or 0) if row else 0
    except (TypeError, ValueError):
        guardado = 0
    if guardado > 0:
        return guardado, f"Apollo de Bauru (última leitura, {str(row['data'])[:10]})"
    return None, erro  # nunca o custo de outra filial (decisão do dono, V19.79)


def tiktok_preco_sku(sku: str, margens: list[float], preco_atual: float | None = None,
                     custo_digitado: float | None = None) -> dict[str, Any]:
    sku = _tiktok_texto(sku, 200)
    pecas = _tiktok_pecas(sku)
    if not pecas:
        raise ValueError("Informe o SKU (código Apollo, KIT2-código ou código/código).")
    cfg = tiktok_preco_config()
    detalhe: list[dict[str, Any]] = []
    faltando: list[str] = []
    if custo_digitado is not None and custo_digitado > 0:
        custo: float | None = float(custo_digitado)
        detalhe.append({"codigo": sku, "unidades": 1, "custo": custo, "origem": "digitado"})
    else:
        custo = 0.0
        for codigo, unidades in pecas:
            valor, origem = _tiktok_custo_bauru(codigo)
            detalhe.append({"codigo": codigo, "unidades": unidades, "custo": valor, "origem": origem})
            if valor is None:
                faltando.append(codigo)
            else:
                custo += valor * unidades
        if faltando:
            custo = None
    precos = []
    for m in margens if custo is not None else []:
        ideal = tiktok_preco_ideal(custo, m, cfg)
        if ideal:
            precos.append({**ideal, "margem_pedida": m})
    return {"ok": True, "sku": sku, "custo": round(custo, 2) if custo is not None else None, "pecas": detalhe,
            "faltando": faltando, "config": cfg, "precos": precos,
            "atual": tiktok_preco_detalhe(preco_atual, custo, cfg) if custo is not None and preco_atual else None}


def tiktok_vinculo_definir(sku_id: str, codigos: str, ator: str) -> dict[str, Any]:
    sku_id = str(sku_id or "").strip()
    if not sku_id:
        raise ValueError("Informe a variação do TikTok.")
    codigos = str(codigos or "").strip()
    if codigos and not _tiktok_pecas(codigos):
        raise ValueError("Código Apollo inválido.")
    with DB_LOCK:
        if codigos:
            DB.execute("INSERT OR REPLACE INTO tiktok_vinculo_v1964(sku_id,codigos,por,em) VALUES(?,?,?,?)",
                       (sku_id, codigos, str(ator or ""), now_iso()))
        else:
            DB.execute("DELETE FROM tiktok_vinculo_v1964 WHERE sku_id=?", (sku_id,))
        _tiktok_anuncios_espelhar()  # V20.40: o vínculo à mão também liga a ficha na plataforma de anúncios
        DB.commit()
    _tiktok_estoque_log(sku_id, "", None, None, "", "VINCULO", f"vínculo à mão: {codigos or '(apagado)'}", ator)
    return {"ok": True, "sku_id": sku_id, "codigos": codigos}


def _tiktok_apollo_bauru(resposta: dict[str, Any]) -> float | None:
    return _apollo_da_revenda(resposta, TIKTOK_REVENDA_APOLLO)  # V20.23: parser unico por revenda


def tiktok_apollo_ler(codigo: str) -> float | None:
    """Uma consulta ao Apollo (com o limite do Apollo). Bauru sem resposta fica nulo."""
    chave = _exp_norm_codigo(codigo)
    disponivel: float | None = None
    erro = ""
    try:
        disponivel = _tiktok_apollo_bauru(crm_stock_lookup(codigo, operador="tiktok-estoque", wait_seconds=0))
        if disponivel is None:
            erro = "Bauru não respondeu no Apollo"
    except CrmLimiteAtingido:
        raise
    except Exception as exc:
        erro = str(exc)[:300]
    with DB_LOCK:
        DB.execute("""INSERT OR REPLACE INTO tiktok_apollo_v1964(codigo,disponivel,respondeu,erro,lido_em,lido_epoch)
                      VALUES(?,?,?,?,?,?)""",
                   (chave, disponivel, 1 if disponivel is not None else 0, erro, now_iso(), int(time.time())))
        DB.commit()
    return disponivel


def _tiktok_linhas_sku() -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("""SELECT s.*, v.codigos AS vinculo FROM tiktok_sku_v1964 s
                             LEFT JOIN tiktok_vinculo_v1964 v ON v.sku_id=s.sku_id ORDER BY s.titulo, s.seller_sku""").fetchall()
    return [dict(r) for r in rows]


def _tiktok_codigos_apollo() -> dict[str, str]:
    """Códigos do Apollo das variações do TikTok ({chave _exp_norm_codigo: código}). V20.42: o rodízio e o lote."""
    codigos: dict[str, str] = {}
    for row in _tiktok_linhas_sku():
        if _tiktok_sku_cortado(row):  # V20.08: não gasta a vaga do Apollo com código pela metade
            continue
        for codigo, _ in _tiktok_pecas(row.get("vinculo") or row.get("seller_sku")):
            codigos.setdefault(_exp_norm_codigo(codigo), codigo)
    return codigos


def _tiktok_extensao_le_apollo() -> bool:
    """V20.42: a mesma condição do tiktok_estoque_loop para ler o Apollo de Bauru da tela Estoque TikTok: sem a API
    (fonte extensão) e com a extensão lendo a loja nas últimas TIKTOK_EXTENSAO_RECENTE."""
    try:
        if tiktok_status_payload().get("connected") and tiktok_fonte() == "api":
            return False
    except Exception:
        return False
    return time.time() - float(_tiktok_config_ler("extensao_lida_epoch") or 0) < TIKTOK_EXTENSAO_RECENTE


def tiktok_apollo_ler_proximo() -> str | None:
    """Uma volta do rodízio: no máximo TIKTOK_APOLLO_POR_MINUTO por minuto. Ordem: nunca lido,
    estoque baixo lido há mais de 10 min, depois o mais antigo."""
    agora = time.monotonic()
    _TIKTOK_APOLLO_CHAMADAS[:] = [t for t in _TIKTOK_APOLLO_CHAMADAS if agora - t < 60]
    if len(_TIKTOK_APOLLO_CHAMADAS) >= TIKTOK_APOLLO_POR_MINUTO:
        return None
    codigos = _tiktok_codigos_apollo()
    if not codigos:
        return None
    with DB_LOCK:
        lidos = {str(r["codigo"]): dict(r) for r in DB.execute("SELECT * FROM tiktok_apollo_v1964").fetchall()}
    epoch = int(time.time())

    def prioridade(chave: str) -> tuple[int, int]:
        r = lidos.get(chave)
        if not r:
            return (0, 0)
        baixo = r["disponivel"] is not None and float(r["disponivel"]) <= TIKTOK_ESTOQUE_BAIXO
        if baixo and epoch - int(r["lido_epoch"] or 0) > 600:
            return (1, int(r["lido_epoch"] or 0))
        return (2, int(r["lido_epoch"] or 0))

    escolhido = min(codigos, key=prioridade)
    _TIKTOK_APOLLO_CHAMADAS.append(agora)
    try:
        tiktok_apollo_ler(codigos[escolhido])
    except CrmLimiteAtingido:
        return None  # o limite do Apollo está com as outras telas: fica para a próxima volta
    return escolhido


def _tiktok_pendentes_bauru() -> dict[str, int]:
    """Unidades vendidas na fila de Bauru (ainda não baixadas no Apollo), por código.
    V20.33 (2ª revisão, 06/11): continua descontando TODO pendente, mesmo com atendimento no Apollo. Seguir a chave
    `apollo_desconta_atendimento` dos anúncios subiria o estoque assim que o atendimento é criado, antes de o rodízio
    reler o Apollo (o TikTok não tem a trava de queda dos anúncios, `_anuncio_pend_observar`). Errar para menos."""
    return pendentes_da_filial(TIKTOK_CASA)  # V20.23: mesma conta para qualquer filial


def tiktok_estoque_itens() -> list[dict[str, Any]]:
    with DB_LOCK:
        apollo = {str(r["codigo"]): dict(r) for r in DB.execute("SELECT * FROM tiktok_apollo_v1964").fetchall()}
    pendentes = _tiktok_pendentes_bauru()
    itens = []
    for row in _tiktok_linhas_sku():
        pecas = _tiktok_pecas(row.get("vinculo") or row.get("seller_sku"))
        item = {"sku_id": row["sku_id"], "product_id": row["product_id"], "titulo": row["titulo"],
                "status": row["status"], "seller_sku": row["seller_sku"], "vinculo": row.get("vinculo") or "",
                "pecas": [[c, u] for c, u in pecas], "tiktok": row["qtd_tiktok"], "warehouse_id": row["warehouse_id"],
                "apollo": None, "pendente": 0, "desejado": None, "lido_em": "", "motivo": ""}
        if not pecas:
            item.update(situacao="sem_vinculo", motivo="Sem código Apollo no SKU do vendedor")
            itens.append(item)
            continue
        if _tiktok_sku_cortado(row):
            item.update(situacao="sku_cortado", motivo=f"O TikTok corta o SKU em {TIKTOK_SKU_LIMITE} caracteres: "
                        "confira as peças do kit e salve os códigos completos — o TikTok não é alterado")
            itens.append(item)
            continue
        possivel: list[int] = []
        faltou = ""
        lidos_em = []
        for codigo, unidades in pecas:
            chave = _exp_norm_codigo(codigo)
            ap = apollo.get(chave)
            if not ap:
                faltou = faltou or f"{codigo}: ainda não lido no Apollo"
                continue
            lidos_em.append(str(ap["lido_em"] or ""))
            if not int(ap["respondeu"] or 0) or ap["disponivel"] is None:
                faltou = faltou or f"{codigo}: {ap['erro'] or 'Apollo sem resposta'}"
                continue
            pend = pendentes.get(chave, 0)
            item["pendente"] += pend
            livre = max(0, int(math.floor(float(ap["disponivel"]))) - pend)
            possivel.append(livre // unidades)
        if len(pecas) == 1 and apollo.get(_exp_norm_codigo(pecas[0][0])) and not faltou:
            item["apollo"] = int(math.floor(float(apollo[_exp_norm_codigo(pecas[0][0])]["disponivel"])))
        item["lido_em"] = min(lidos_em) if lidos_em else ""
        if faltou:
            item.update(situacao="desconhecido", motivo=faltou + " — o TikTok não é alterado")
        else:
            item["desejado"] = min(possivel) if possivel else None
            if int(row["armazens"] or 0) != 1 or not row["warehouse_id"]:
                item.update(situacao="varios_depositos", motivo="A variação não tem um depósito só no TikTok — não enviado")
            elif row["qtd_tiktok"] is not None and int(row["qtd_tiktok"]) == item["desejado"]:
                item["situacao"] = "igual"
            else:
                item["situacao"] = "enviar"
        itens.append(item)
    return itens


class TikTokEstoqueOcupado(Exception):
    """revisar-antes-de-subir (V20.40): o worker está enviando agora; o clique não espera (nginx corta em 60 s)."""


def tiktok_estoque_enviar(ator: str, automatico: bool = False, skus: list[str] | None = None,
                          espera: float | None = None) -> dict[str, Any]:
    """Manda ao TikTok as variações com quantidade diferente. Simulação nunca chama o TikTok;
    o worker (automatico=True) só envia no modo Automático; o clique, no Lote ou Automático."""
    modo = tiktok_estoque_config()["modo_estoque"]
    if automatico and modo != "automatico":
        return {"ok": True, "enviados": 0, "erros": 0, "modo": modo}
    if not automatico and modo == "simulacao":
        raise ValueError("Modo Simulação: nada é enviado ao TikTok. Mude para Lote para enviar.")
    if not TIKTOK_ESTOQUE_LOCK.acquire(timeout=-1 if espera is None else espera):
        raise TikTokEstoqueOcupado("O Noromak está enviando o estoque ao TikTok agora. Tente de novo em instantes.")
    try:
        if TIKTOK_RODADA and time.time() - float(TIKTOK_RODADA.get("desde") or 0) < TIKTOK_RODADA_PRAZO:
            # revisar-antes-de-subir (V20.40): rodada da extensão ainda aberta (grava por diferença): a API espera
            return {"ok": True, "enviados": 0, "erros": 0, "modo": modo, "aguardando": "rodada da extensão aberta"}
        itens = [i for i in tiktok_estoque_itens() if i["situacao"] == "enviar"
                 and (skus is None or i["sku_id"] in set(skus))]
        por_produto: dict[str, list[dict[str, Any]]] = {}
        for i in itens:
            por_produto.setdefault(i["product_id"], []).append(i)
        enviados = erros = 0
        for product_id, lista in por_produto.items():
            corpo = {"skus": [{"id": i["sku_id"], "inventory": [{"warehouse_id": i["warehouse_id"], "quantity": i["desejado"]}]}
                              for i in lista]}
            try:
                resp = tiktok_api("POST", f"/product/202309/products/{product_id}/inventory/update", body=corpo)
                recusados = {}
                for e in ((resp.get("data") or {}).get("errors") or []) if isinstance(resp.get("data"), dict) else []:
                    det = e.get("detail") if isinstance(e, dict) and isinstance(e.get("detail"), dict) else {}
                    recusados[str(det.get("sku_id") or "*")] = f"{e.get('code')} {e.get('message') or ''}".strip()
            except Exception as exc:
                recusados = {"*": str(exc)[:500]}
            for i in lista:
                motivo = recusados.get(i["sku_id"]) or recusados.get("*")
                if motivo:
                    erros += 1
                    _tiktok_estoque_log(i["sku_id"], i["seller_sku"], i["tiktok"], i["desejado"], modo, "ERRO", motivo, ator)
                    continue
                enviados += 1
                with DB_LOCK:
                    DB.execute("UPDATE tiktok_sku_v1964 SET qtd_tiktok=? WHERE sku_id=?", (i["desejado"], i["sku_id"]))
                    _tiktok_anuncio_estoque(i["sku_id"], i["desejado"])  # V20.40: a plataforma de anúncios acompanha
                    DB.commit()
                _tiktok_estoque_log(i["sku_id"], i["seller_sku"], i["tiktok"], i["desejado"], modo, "OK",
                                    f"Apollo {i['apollo'] if i['apollo'] is not None else '—'} − fila {i['pendente']}", ator)
    finally:
        TIKTOK_ESTOQUE_LOCK.release()
    return {"ok": True, "enviados": enviados, "erros": erros, "modo": modo}


def tiktok_estoque_payload() -> dict[str, Any]:
    itens = tiktok_estoque_itens()
    resumo: dict[str, int] = {"total": len(itens)}
    for i in itens:
        resumo[i["situacao"]] = resumo.get(i["situacao"], 0) + 1
    # V20.08: só a tela sugere (o worker também monta os itens e não deve abrir o Precificador a cada volta).
    cortados = [i for i in itens if i["situacao"] == "sku_cortado"]
    if cortados:
        try:
            conhecidos = _separacao_codigos_conhecidos()
        except Exception:
            conhecidos = set()
        for i in cortados:
            i["sugestoes"] = tiktok_sugerir_sku(i["seller_sku"], conhecidos)
    with DB_LOCK:
        log = [dict(r) for r in DB.execute("SELECT * FROM tiktok_estoque_log_v1964 ORDER BY id DESC LIMIT 100").fetchall()]
    return {"ok": True, "config": tiktok_estoque_config(), "conectado": tiktok_status_payload()["connected"],
            "fonte": tiktok_fonte(),  # V20.40
            "resumo": resumo, "itens": itens, "log": log, "apollo_por_minuto": TIKTOK_APOLLO_POR_MINUTO}


def _tiktok_iso(epoch: Any) -> str:
    n = _tiktok_quantidade(epoch)
    return datetime.fromtimestamp(n, timezone.utc).isoformat() if n else ""


def tiktok_pedidos_abertos() -> list[dict[str, Any]]:
    """Pedidos a expedir (aguardando envio/coleta), paginado. Só lê."""
    pedidos: list[dict[str, Any]] = []
    for status in TIKTOK_PEDIDOS_STATUS:
        token = ""
        for _ in range(20):
            params: dict[str, Any] = {"page_size": 50}
            if token:
                params["page_token"] = token
            resp = tiktok_api("POST", "/order/202309/orders/search", params=params, body={"order_status": status})
            dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
            pedidos.extend(o for o in (dados.get("orders") or []) if isinstance(o, dict))
            token = str(dados.get("next_page_token") or "")
            if not token:
                break
    return pedidos


# ---------------------------------------------------------------------------
# V20.29 — etiqueta do TikTok (decisões do dono, 06/11): o servidor organiza o envio do pacote
# sozinho e vincula a etiqueta; a Conferência de Bauru imprime em PDF, baixado na hora pela rota
# /api/etiqueta-tiktok-pdf (o link do TikTok vence: nunca é guardado, e o PDF não vai para o
# banco — o registro em conf_etiquetas guarda só o marcador TIKTOK_PDF:<pacote>). A nota sai
# pelo Linx: sem ela o TikTok recusa e a linha mostra AGUARDANDO NF. É a única ação que GRAVA
# no TikTok, por isso tem chave própria e começa DESLIGADA. Endpoints de fontes de terceiros:
# a 1ª resposta fica em tiktok_amostra_v1963 (conferir ao ligar o app de parceiro).
# ---------------------------------------------------------------------------
_TIKTOK_ETIQUETA_TENTATIVA: dict[str, float] = {}   # pacote -> epoch da última tentativa que falhou
_TIKTOK_ETIQUETA_ESTADO: dict[str, str] = {}        # pacote -> AGUARDANDO NF / ERRO (memória do processo)
_TIKTOK_ETIQUETA_ORGANIZADO: set[str] = set()      # revisão final: envio já organizado; só falta o documento


class TikTokSemNota(RuntimeError):
    """O TikTok recusou porque a NF-e do pedido ainda não foi enviada a ele."""


def tiktok_etiqueta_ligada() -> bool:
    return _tiktok_config_ler("etiqueta") == "1"  # sem escolha = DESLIGADA


def tiktok_etiqueta_definir(ligada: bool, usuario: str) -> None:
    _tiktok_config_gravar("etiqueta", "1" if ligada else "0", usuario)
    tiktok_log_event("etiqueta", "", "LIGADA" if ligada else "DESLIGADA", f"por {usuario}")


def _tiktok_pacotes(pedido: dict[str, Any]) -> list[str]:
    return [str(p.get("id") or "").strip() for p in (pedido.get("packages") or [])
            if isinstance(p, dict) and str(p.get("id") or "").strip()]


def _tiktok_sem_nota(exc: Exception) -> bool:
    return bool(re.search(r"invoice|nota|nf-?e", str(exc), re.I))


def tiktok_organizar_envio(pacote: str) -> None:
    try:
        tiktok_api("POST", f"/fulfillment/202309/packages/{pacote}/ship", body={})
    except RuntimeError as exc:
        if _tiktok_sem_nota(exc):
            raise TikTokSemNota(str(exc))
        raise


def tiktok_documento_url(pacote: str) -> str:
    try:
        resp = tiktok_api("GET", f"/fulfillment/202309/packages/{pacote}/shipping_documents",
                          params={"document_type": "SHIPPING_LABEL", "document_size": "A6"})
    except RuntimeError as exc:
        if _tiktok_sem_nota(exc):
            raise TikTokSemNota(str(exc))
        raise
    dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    url = str(dados.get("doc_url") or "").strip()
    if not url:
        raise RuntimeError("O TikTok não devolveu o link da etiqueta.")
    # revisar-antes-de-subir (06/11): os hosts aceitos foram deduzidos. Conferir já ao vincular —
    # senão a linha fica VINCULADA e toda impressão em Bauru falha. O erro diz o host que veio.
    alvo = urlparse(url)
    host = (alvo.hostname or "").lower()
    if alvo.scheme != "https" or not any(host.endswith(h) for h in TIKTOK_PDF_HOSTS):
        raise RuntimeError(f"Link da etiqueta fora do TikTok ({alvo.scheme}://{host}); ajustar TIKTOK_PDF_HOSTS se for do TikTok.")
    return url


def _tiktok_etiquetas_vinculadas() -> set[str]:
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    registros = bank.get("registros") if isinstance(bank, dict) and isinstance(bank.get("registros"), dict) else {}
    return {str((rec.get("metadados") or {}).get("pacote") or "") for rec in registros.values()
            if isinstance(rec, dict) and rec.get("marketplace") == "tiktok"
            and isinstance(rec.get("metadados"), dict) and str(rec["metadados"].get("pacote") or "")}


def _tiktok_guardar_etiqueta(pedido: str, pacote: str) -> None:
    """Mesma montagem de _magalu_guardar_etiqueta, com o marcador do PDF no lugar do ZPL."""
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    if not isinstance(bank, dict):
        bank = {}
    bank["version"] = max(8, int(bank.get("version") or 0))
    for chave, padrao in (("registros", {}), ("ordem", []), ("porChave", {}), ("avisos", []),
                          ("auditoria", []), ("resumo", {}), ("vinculados", {})):
        bank.setdefault(chave, padrao)
    rid = "etq_tiktok_api_" + hashlib.sha1(pacote.encode("utf-8")).hexdigest()[:18]
    chaves = [x for x in (pedido, pacote) if x]
    bank["registros"][rid] = {
        "id": rid, "marketplace": "tiktok", "envio": f"TIKTOK_PDF:{pacote}", "danfe": "",
        "arquivo": f"TikTok API · pacote {pacote}",
        "metadados": {"pedido": pedido, "pacote": pacote},
        "chaves": chaves, "vinculadoA": [pedido], "pedido": pedido,
        "vinculo": "api_tiktok", "origem": "api_tiktok",
        "adicionadaEm": now_iso(), "adicionadaPor": "tiktok-api",
    }
    if rid not in bank["ordem"]:
        bank["ordem"].append(rid)
    for chave in chaves:
        bank["porChave"].setdefault(chave, [])
        if rid not in bank["porChave"][chave]:
            bank["porChave"][chave].append(rid)
    bank["atualizadoEm"] = now_iso()
    bank["auditoria"].append({"marketplace": "tiktok", "pedido": pedido, "criterio": "api_tiktok",
                              "etiqueta": rid, "arquivo": bank["registros"][rid]["arquivo"]})
    bank["auditoria"] = bank["auditoria"][-250:]
    save_storage("conf_etiquetas", raw, json_dumps(bank), False, actor="tiktok-api", actor_role="sistema",
                 source_screen="API TikTok", change_method="Etiqueta automática (envio organizado)",
                 client_ip="127.0.0.1")


def _tiktok_pedidos_que_ficam_na_fila(pedidos: list[dict[str, Any]],
                                      products: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Revisão final (06/11): os pedidos cujas linhas passam pelas barreiras do ADMIN — linha excluída
    (já tirada em _tiktok_linhas_do_pedido), tombstone do pedido inteiro e concluído — as mesmas
    que o save_storage aplica por último."""
    linhas: list[dict[str, Any]] = []
    for pedido in pedidos:
        linhas.extend(_tiktok_linhas_do_pedido(pedido, products))
    # revisar-antes-de-subir (06/11): a linha de kit que o ADMIN excluiu é gravada pelo UID da peça
    # (KITDB_…), que só existe depois de abrir o kit — filtra de novo aqui.
    linhas = _sem_linhas_excluidas_admin_v2022(linhas)
    # Conexão compartilhada: as barreiras leem o banco e nunca podem rodar sem a trava (V18.06).
    # Erro aqui sobe: quem chama não organiza nada (sem saber o que o ADMIN tirou, não grava).
    with DB_LOCK:
        valor = filter_completed_orders_v1772(_pending_filter_manual_deleted_orders_value(json_dumps(linhas)))
    ficam = {normalize(order_number(r)) for r in _rows_from_storage_value(valor) if isinstance(r, dict)}
    return [p for p in pedidos if normalize(str(p.get("id") or "")) in ficam]


def _tiktok_cancelamento_pedido(pedido: dict[str, Any]) -> bool:
    """V20.29: comprador pediu cancelamento (ou o pedido está retido): não organiza o envio.
    Nomes dos campos a conferir na 1ª resposta real (leitura tolerante)."""
    return any(pedido.get(c) for c in ("cancel_reason", "cancellation_initiator", "is_on_hold"))


def tiktok_etiquetas_rodada(pedidos: list[dict[str, Any]]) -> dict[str, Any]:
    """Organiza o envio (AWAITING_SHIPMENT) e confere o documento de cada pacote ainda sem etiqueta.
    Chamadas ao TikTok fora do DB_LOCK; falha de um pacote não para os outros nem a importação."""
    vinculados = _tiktok_etiquetas_vinculadas()
    resumo = {"novas": 0, "aguardando_nf": 0, "erros": 0}
    agora = time.time()
    for pedido in pedidos:
        numero = str(pedido.get("id") or "").strip()
        status = str(pedido.get("status") or "").upper()
        if _tiktok_cancelamento_pedido(pedido):
            continue
        for pacote in _tiktok_pacotes(pedido)[:1]:
            if pacote in vinculados:
                continue
            if agora - _TIKTOK_ETIQUETA_TENTATIVA.get(pacote, 0.0) < TIKTOK_ETIQUETA_REPETIR_S:
                if _TIKTOK_ETIQUETA_ESTADO.get(pacote) == "AGUARDANDO NF":
                    resumo["aguardando_nf"] += 1
                continue
            try:
                if status == "AWAITING_SHIPMENT" and pacote not in _TIKTOK_ETIQUETA_ORGANIZADO:
                    tiktok_organizar_envio(pacote)
                    _TIKTOK_ETIQUETA_ORGANIZADO.add(pacote)  # nunca chamar o /ship duas vezes
                tiktok_documento_url(pacote)  # só confere que o documento existe; o PDF é baixado na impressão
                _tiktok_guardar_etiqueta(numero, pacote)
                vinculados.add(pacote)
                _TIKTOK_ETIQUETA_TENTATIVA.pop(pacote, None)
                _TIKTOK_ETIQUETA_ESTADO.pop(pacote, None)
                _TIKTOK_ETIQUETA_ORGANIZADO.discard(pacote)
                resumo["novas"] += 1
            except TikTokSemNota as exc:
                _TIKTOK_ETIQUETA_TENTATIVA[pacote] = agora
                _TIKTOK_ETIQUETA_ESTADO[pacote] = "AGUARDANDO NF"
                resumo["aguardando_nf"] += 1
                tiktok_log_event_se_mudou("etiqueta", f"pedido={numero} pacote={pacote}", "AGUARDANDO NF", str(exc)[:800])
            except Exception as exc:
                _TIKTOK_ETIQUETA_TENTATIVA[pacote] = agora
                _TIKTOK_ETIQUETA_ESTADO[pacote] = "ERRO"
                resumo["erros"] += 1
                tiktok_log_event_se_mudou("etiqueta", f"pedido={numero} pacote={pacote}", "ERRO", str(exc)[:800])
    return resumo


def _tiktok_etiqueta_situacao(pacote: str, vinculados: set[str], ligada: bool) -> str:
    if pacote and pacote in vinculados:
        return "VINCULADA"
    if not ligada:
        return ""
    return _TIKTOK_ETIQUETA_ESTADO.get(pacote) or "AGUARDANDO"


def _tiktok_linhas_do_pedido(pedido: dict[str, Any], products: list[dict[str, Any]],
                             etiqueta: tuple[set[str], bool] | None = None) -> list[dict[str, Any]]:
    numero = str(pedido.get("id") or "").strip()
    if not numero:
        return []
    pacotes = _tiktok_pacotes(pedido)
    pacote = pacotes[0] if pacotes else ""
    situacao = _tiktok_etiqueta_situacao(pacote, *etiqueta) if etiqueta else ""
    endereco = pedido.get("recipient_address") if isinstance(pedido.get("recipient_address"), dict) else {}
    agrupado: dict[tuple[str, str], dict[str, Any]] = {}
    for item in pedido.get("line_items") or []:
        if not isinstance(item, dict) or str(item.get("display_status") or "").upper() == "CANCELLED":
            continue
        sku = str(item.get("seller_sku") or "").strip()
        chave = (str(item.get("sku_id") or ""), sku)
        if chave not in agrupado:
            agrupado[chave] = {"sku": sku, "nome": str(item.get("product_name") or ""), "qtd": 0}
        # A API manda um line_item por unidade; o Seller Center (V20.30) manda a quantidade.
        agrupado[chave]["qtd"] += max(1, _tiktok_quantidade(item.get("quantity")) or 1)
    linhas = []
    for (sku_id, sku), g in agrupado.items():
        if not sku:
            continue
        identidade = f"{numero}|{sku_id}|{sku}"
        row = {
            "Pedido": numero, "Marketplace": "TIKTOK", "Casa": TIKTOK_CASA,
            "Data do Pedido": _tiktok_iso(pedido.get("create_time"))[:10],
            "Kit": "", "Nome do Kit": "", "Quantidade de Kits": "", "Quantidade por Kit": "",
            "Cliente": str(endereco.get("name") or ""),
            "SKU": sku, "Quantidade": str(g["qtd"]), "Código de Barras": "", "Descrição": g["nome"],
            "Rua": "", "Módulo": "", "Prateleira": "", "Nível": "", "Posição": "", "Foto": "",
            "StatusTikTok": str(pedido.get("status") or ""),
            "PrazoEnvioTikTok": _tiktok_iso(pedido.get("rts_sla_time")),
            "PacoteTikTok": pacote, "Etiqueta API TikTok": situacao,  # V20.29
            "OrigemCadastro": "API_TIKTOK", "SkuOrigemImportacao": sku,
            "TikTokAtualizadoEm": now_iso(), "CriadoEm": now_iso(),
            "__uidLinha": "TIKTOKAPI_" + hashlib.sha1(identidade.encode("utf-8")).hexdigest()[:20],
        }
        produto = _ml_find_product(products, sku)
        if produto:
            for campo in ("SKU", "Código de Barras", "Descrição", "Rua", "Módulo", "Prateleira", "Nível", "Posição", "Foto"):
                if str(produto.get(campo) or "").strip():
                    row[campo] = produto.get(campo)
        linhas.append(row)
    linhas = _sem_linhas_excluidas_admin_v2022(linhas)  # V20.22: antes de abrir o kit
    return _shopee_expand_kit_lines(linhas, products)  # V18.71: mesma regra de kit


def tiktok_importar_pedidos() -> dict[str, Any]:
    with TIKTOK_SYNC_LOCK:
        pedidos = tiktok_pedidos_abertos()  # erro aqui = nada gravado
        pedidos = [_tiktok_api_pacote_aberto_primeiro(o) for o in pedidos]  # 2ª revisão (V20.40)
        # V20.29: etiqueta antes de montar as linhas, para a linha já sair VINCULADA.
        ligada = tiktok_etiqueta_ligada()
        products_raw, _, _ = get_storage("conf_produtos")
        products = _rows_from_storage_value(products_raw)
        etiquetas = {"novas": 0, "aguardando_nf": 0, "erros": 0}
        if ligada:
            # Revisão final: só organiza o envio (escrita no TikTok) de pedido que vai ficar na
            # fila — o que o ADMIN excluiu (tombstone/linha) ou que já foi concluído fica de fora.
            try:
                ficam = _tiktok_pedidos_que_ficam_na_fila(pedidos, products)
            except Exception as exc:
                ficam = None  # sem as barreiras do ADMIN: nenhuma escrita no TikTok nesta volta
                etiquetas["erros"] += 1
                tiktok_log_event_se_mudou("etiqueta", "barreiras do ADMIN", "ERRO", str(exc)[:800])
            if ficam is not None:
                etiquetas = tiktok_etiquetas_rodada(ficam)
        vinculados = _tiktok_etiquetas_vinculadas()
        # revisar-antes-de-subir (V20.40): a fila é montada pela MESMA regra da extensão (V20.30). Pedido que sumiu
        # da lista "a enviar" (ou lista vazia) só sai com o TikTok CONFIRMANDO a saída na releitura do pedido; peça
        # já bipada fica com aviso; quantidade nunca abaixo do bipado; TikTokAtualizadoEm só anda com mudança real.
        abertos = [x for x in (_tiktok_api_para_sc(o) for o in pedidos) if x]
        ids = {x["id"] for x in abertos}
        atual_raw, _, _ = get_storage("conf_pedidos")
        sumidos = sorted(_tiktok_sc_pedidos_na_fila(_rows_from_storage_value(atual_raw)) - ids)
        relidos = _tiktok_api_reler(sumidos)  # fora do DB_LOCK; sem resposta = {} (ninguém sai)
        saiu = {n for n, st in relidos.items() if st in TIKTOK_SC_SAIU}
        with DB_LOCK:
            guardados = {r["pedido"]: dict(r) for r in DB.execute("SELECT pedido, nome FROM tiktok_sc_pedido_v2030")}
            atual_raw, _, _ = get_storage("conf_pedidos")
            atual = _rows_from_storage_value(atual_raw)
            fila, removidas, pulados, api_linhas, ficam = _tiktok_sc_montar_fila(
                atual, abertos, saiu, guardados, products, etiqueta=(vinculados, ligada))
            save_storage("conf_pedidos", atual_raw, json_dumps(fila), False,
                         actor="sistema", actor_role="sistema", source_screen="Admin / Integrações / TikTok",
                         change_method="Sincronização API TikTok", client_ip="127.0.0.1",
                         allow_completed_reimport=False, remove_pending_identities=removidas)
        resumo = {"ok": True, "pedidos": len({order_number(r) for r in api_linhas if isinstance(r, dict)}),
                  "linhas": len(api_linhas), "removidas": len(removidas), "ja_na_fila_por_outra_origem": pulados,
                  "saiu_confirmado": len(saiu), "mantidos_sem_confirmar": len(ficam - saiu), "etiquetas": etiquetas}
        tiktok_log_event_se_mudou("pedidos", "/order/202309/orders/search", "OK",
                                  f"{len(abertos)} pedido(s) a enviar, {len(removidas)} linha(s) removida(s), "
                                  f"{len(saiu)} confirmado(s) enviado/cancelado, {pulados} já na fila")
        _tiktok_config_gravar("pedidos_api_epoch", str(int(time.time())), "sistema")  # V20.40: Painel de saúde
        try:
            resumo["atendimento"] = _tiktok_api_registrar_pedidos(pedidos, relidos)  # V20.40: preço/CPF/endereço
        except Exception as exc:  # leitura tolerante: nunca derruba a importação
            tiktok_log_event_se_mudou("atendimento", "dados da API", "ERRO", str(exc)[:500])
        return resumo


def tiktok_sincronizar_iniciar() -> bool:
    """Botão "Sincronizar agora": roda a importação numa thread. False = já tem uma rodando."""
    if TIKTOK_SYNC_LOCK.locked():
        return False

    def rodar() -> None:
        try:
            if _tiktok_extensao_em_uso():  # revisão das correções (06/11): uma fonte de cada vez, também no botão
                tiktok_log_event_se_mudou("pedidos", "sincronizar agora", "IGNORADO",
                                          "a fonte do TikTok é a extensão do Seller Center: a API não importa")
                return
            tiktok_importar_pedidos()
        except Exception as exc:
            tiktok_log_event_se_mudou("pedidos", "sincronizar agora", "ERRO", str(exc)[:800])
    threading.Thread(target=rodar, name="tiktok-sincronizar-agora", daemon=True).start()
    return True


# ---------------------------------------------------------------------------
# V20.30 — pedidos do TikTok pela extensão do Seller Center. A API oficial exige gerente de
# contas (o TikTok confirmou em 06/11); a extensão NOROMAK_TIKTOK_ESTOQUE lê as chamadas
# internas da própria página com a sessão do vendedor (mapa em
# docs/superpowers/specs/2026-11-06-tiktok-seller-center-mapa.md). Decisões do dono (06/11):
# - a extensão lê a aba "Para enviar" sozinha a cada 2 min, com uma aba do Seller Center
#   aberta; ao ligar o PC pega o que entrou à noite;
# - pedido que sumiu da aba só sai da fila com o TikTok CONFIRMANDO (o detalhe do pedido diz
#   enviado/cancelado). Leitura pela metade ou erro nunca tira nada; ADMIN e concluído valem
#   como sempre (save_storage);
# - o Painel de saúde fica Crítico (e-mail) sem leitura há 30 min no expediente.
# Mesmas linhas da importação pela API (_tiktok_linhas_do_pedido, uid TIKTOKAPI_, origem
# API_TIKTOK): se a API um dia for liberada, as duas falam do mesmo pedido.
# ---------------------------------------------------------------------------
# sku_display_status do Seller Center = os códigos de situação da Open API (conferido: 121 em
# pedido enviado). O que não está aqui é desconhecido e nunca tira pedido da fila.
TIKTOK_SC_STATUS = {100: "UNPAID", 105: "ON_HOLD", 111: "AWAITING_SHIPMENT", 112: "AWAITING_COLLECTION",
                    114: "PARTIALLY_SHIPPING", 121: "IN_TRANSIT", 122: "DELIVERED", 130: "COMPLETED",
                    140: "CANCELLED"}
TIKTOK_SC_NA_FILA = ("AWAITING_SHIPMENT", "AWAITING_COLLECTION", "PARTIALLY_SHIPPING")
# V20.38: desde a publicação da V20.33 (06/11 22:56 UTC) todo detalhe lido guarda o preço; só o lido antes disso é reaberto
# por falta dele (um detalhe novo sem preço não seria resolvido reabrindo, e voltaria a cada 2 min).
TIKTOK_SC_PRECO_DESDE = "2026-11-06T22:56:00"
# V20.39: versão da regra do preço. Pedido "a enviar" cujo preço deu erro numa regra mais velha volta a ter o detalhe
# aberto (uma vez: o erro novo leva esta versão). Mudou a regra do _tiktok_sc_venda? suba o número.
TIKTOK_SC_VENDA_REGRA = 2039
TIKTOK_SC_SAIU = ("IN_TRANSIT", "DELIVERED", "COMPLETED", "CANCELLED")
TIKTOK_SC_MAX_PEDIDOS = 500
TIKTOK_SC_SEM_LEITURA_S = 30 * 60   # Painel de saúde
TIKTOK_SC_FONTE_UNICA_S = 6 * 3600  # revisão 06/11: extensão leu nas últimas 6 h = a API não importa pedidos
TIKTOK_SC_ORIGEM = "API_TIKTOK"


class TikTokImportacaoDesligada(Exception):
    pass


TIKTOK_SC_TENTATIVAS_CPF = 5        # revisão 06/11: detalhe sem CPF é reaberto até aqui


def ensure_tiktok_sc_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """
            CREATE TABLE IF NOT EXISTS tiktok_sc_pedido_v2030 (
                pedido TEXT PRIMARY KEY,
                nome TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT '',
                detalhe_em TEXT NOT NULL DEFAULT '',
                visto_em TEXT NOT NULL DEFAULT '',
                cpf_ok INTEGER NOT NULL DEFAULT 0,
                tentativas INTEGER NOT NULL DEFAULT 0,
                saiu_epoch REAL NOT NULL DEFAULT 0
            );
            """
        )
        colunas = {r["name"] for r in DB.execute("PRAGMA table_info(tiktok_sc_pedido_v2030)")}
        for nome, tipo in (("cpf_ok", "INTEGER NOT NULL DEFAULT 0"), ("tentativas", "INTEGER NOT NULL DEFAULT 0"),
                           ("saiu_epoch", "REAL NOT NULL DEFAULT 0")):
            if nome not in colunas:
                DB.execute(f"ALTER TABLE tiktok_sc_pedido_v2030 ADD COLUMN {nome} {tipo}")
        DB.commit()


def _tiktok_sc_endereco(o: dict[str, Any]) -> dict[str, str]:
    """Endereço do detalhe vem como lista chave/valor (name, geo_l1, zipcode...)."""
    comprador = o.get("buyer_info_module") if isinstance(o.get("buyer_info_module"), dict) else {}
    endereco = comprador.get("shipping_address") if isinstance(comprador.get("shipping_address"), dict) else {}
    saida: dict[str, str] = {}
    for item in endereco.get("items") or []:
        if isinstance(item, dict) and item.get("key"):
            saida[str(item["key"])] = str(item.get("value") or "").strip()
    return saida


def _tiktok_sc_sem_comprador(o: Any) -> Any:
    """Revisão 06/11: a amostra guarda o formato, nunca o CPF, o nome ou o endereço do comprador."""
    if not isinstance(o, dict):
        return o
    copia = dict(o)
    comprador = copia.get("buyer_info_module")
    if isinstance(comprador, dict):
        copia["buyer_info_module"] = {k: "***" for k in comprador}
    for chave in ("delivery_module", "logistics_info_module", "note_module"):
        if chave in copia:
            copia[chave] = "***"
    # revisar-antes-de-subir (06/11): também em módulo que ainda não conhecemos (nota, destinatário...)
    return _tiktok_sc_mascarar(copia)


_TIKTOK_SC_CHAVE_PESSOAL = re.compile(
    r"cpf|cnpj|tax|phone|mobile|email|address|zip|street|recipient|receiver|buyer|nick|document|contact|"
    r"^name$|full_name|first_name|last_name|real_name|user_name", re.I)


def _tiktok_sc_so_chaves(v: Any, nivel: int = 0) -> Any:
    """Mantém as chaves (o formato) e troca todo valor por ***."""
    if nivel > 12:
        return "***"
    if isinstance(v, dict):
        return {k: _tiktok_sc_so_chaves(x, nivel + 1) for k, x in v.items()}
    if isinstance(v, list):
        return [_tiktok_sc_so_chaves(x, nivel + 1) for x in v[:3]]
    return "***"


def _tiktok_sc_mascarar(v: Any, nivel: int = 0) -> Any:
    """Troca por *** o valor de toda chave que parece dado da pessoa, em qualquer nível."""
    if nivel > 12:
        return "***"
    if isinstance(v, dict):
        saida: dict[str, Any] = {}
        rotulo = str(v.get("key") or "")
        for k, x in v.items():
            if _TIKTOK_SC_CHAVE_PESSOAL.search(str(k)) or (k == "value" and _TIKTOK_SC_CHAVE_PESSOAL.search(rotulo)):
                saida[k] = _tiktok_sc_so_chaves(x, nivel + 1)
            else:
                saida[k] = _tiktok_sc_mascarar(x, nivel + 1)
        return saida
    if isinstance(v, list):
        return [_tiktok_sc_mascarar(x, nivel + 1) for x in v]
    return v


def tiktok_sc_pedido(o: Any) -> dict[str, Any] | None:
    """Um pedido do Seller Center (lista ou detalhe) no formato da Open API que
    _tiktok_linhas_do_pedido já entende. Leitura tolerante: o que falta fica vazio.
    Revisão 06/11: a quantidade conta só as unidades ainda a enviar (cancelada e já enviada
    ficam de fora); `_skus_fora` = SKU do vendedor sem nenhuma unidade a enviar no pedido."""
    if not isinstance(o, dict):
        return None
    numero = str(o.get("main_order_id") or "").strip()
    if not numero.isdigit():
        return None
    por_linha: dict[str, str] = {}
    desconhecidos: set[str] = set()  # revisar-antes-de-subir (06/11): vão para o Painel de saúde
    for s in o.get("order_status_module") or []:
        if isinstance(s, dict):
            codigo = _tiktok_quantidade(s.get("sku_display_status"))
            por_linha[str(s.get("order_line_id") or "")] = TIKTOK_SC_STATUS.get(codigo or -1, "")
            if (codigo or -1) not in TIKTOK_SC_STATUS:
                desconhecidos.add(str(s.get("sku_display_status") if s.get("sku_display_status") not in (None, "")
                                      else "sem situação")[:20])
    if not por_linha:
        desconhecidos.add("sem situação")
    nomes = set(por_linha.values())
    if not nomes or "" in nomes:
        status = ""                                   # alguma linha com situação desconhecida
    elif nomes == {"CANCELLED"}:
        status = "CANCELLED"
    elif nomes - {"CANCELLED"} <= set(TIKTOK_SC_SAIU):
        status = next(s for s in TIKTOK_SC_SAIU if s in nomes)
    else:
        status = next((s for s in TIKTOK_SC_NA_FILA if s in nomes), "")
    fora = set(TIKTOK_SC_SAIU)                        # cancelada ou já enviada: não se separa mais
    fora_uids: set[str] = set()
    itens: list[dict[str, Any]] = []
    abertas: set[str] = set()
    skus_abertos: set[str] = set()
    skus_vistos: set[str] = set()
    for sk in o.get("sku_module") or []:
        if not isinstance(sk, dict):
            continue
        sku = str(sk.get("seller_sku_name") or "").strip()
        linhas = [str(x) for x in (sk.get("order_line_ids") or [])]
        if linhas:
            minhas = [x for x in linhas if por_linha.get(x) not in fora]
            abertas.update(minhas)
            qtd = len(minhas)
        else:
            qtd = _tiktok_quantidade(sk.get("quantity"))
            if qtd is None:
                # revisar-antes-de-subir (06/11): quantidade que não veio é desconhecida, nunca zero —
                # o pedido inteiro fica como está (não entra nem sai nada) e vai para o Painel de saúde.
                desconhecidos.add("sem quantidade")
                status = ""
                qtd = 0
        if sku:
            skus_vistos.add(normalize(sku))
        if qtd <= 0:
            if sku:
                fora_uids.add(_tiktok_uid_api(numero, str(sk.get("sku_id") or ""), sku))
            continue
        if sku:
            skus_abertos.add(normalize(sku))
        itens.append({"sku_id": str(sk.get("sku_id") or ""), "seller_sku": sku,
                      "product_name": str(sk.get("product_name") or ""), "quantity": min(qtd, 999)})
    trade = o.get("trade_order_module") if isinstance(o.get("trade_order_module"), dict) else {}
    pacotes_todos = [f for f in (o.get("fulfill_unit_id_mapper") or [])
                     if isinstance(f, dict) and str(f.get("package_id") or "").strip()]
    # O pacote que ainda tem unidade a enviar vem primeiro (o 1º é o que vai na coluna).
    pacotes_todos.sort(key=lambda f: 0 if abertas & {str(x) for x in (f.get("order_line_id") or [])} else 1)
    pacotes = [{"id": str(f["package_id"]).strip()} for f in pacotes_todos]
    comprador = o.get("buyer_info_module") if isinstance(o.get("buyer_info_module"), dict) else {}
    endereco = _tiktok_sc_endereco(o)
    return {"id": numero, "status": status, "create_time": trade.get("create_time"),
            "rts_sla_time": trade.get("latest_rts_time"), "line_items": itens, "packages": pacotes,
            "recipient_address": {"name": endereco.get("name") or ""},
            "_skus_fora": skus_vistos - skus_abertos,     # para as peças de kit (KITDB_ não tem o sku_id)
            "_fora_uids": fora_uids,                       # linha comum: pela variação exata
            "_apelido": str(comprador.get("buyer_nickname") or ""),
            "_cpf": re.sub(r"\D", "", str(comprador.get("cpf") or "")),
            "_cpf_nome": re.sub(r"\s+", " ", str(comprador.get("cpf_name") or "")).strip(),
            "_desconhecidos": sorted(desconhecidos)}


def _tiktok_uid_api(numero: str, sku_id: str, sku: str) -> str:
    """O __uidLinha que _tiktok_linhas_do_pedido dá à linha (sem kit) dessa variação."""
    return "TIKTOKAPI_" + hashlib.sha1(f"{numero}|{sku_id}|{sku}".encode("utf-8")).hexdigest()[:20]


def _tiktok_sc_linha_fora(row: dict[str, Any], p: dict[str, Any]) -> bool:
    """A linha da fila é de uma variação sem nenhuma unidade a enviar (cancelada ou já enviada)?"""
    uid = str(row.get("__uidLinha") or "")
    if uid in p["_fora_uids"]:
        return True
    return uid.upper().startswith("KITDB_") and normalize(row.get("SkuKitOrigem")) in p["_skus_fora"]


def _tiktok_sc_pedidos_na_fila(fila: list[dict[str, Any]]) -> set[str]:
    return {str(order_number(r) or "").strip() for r in fila
            if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) == normalize(TIKTOK_SC_ORIGEM)
            and str(order_number(r) or "").strip()}


def tiktok_sc_estado() -> dict[str, Any]:
    """O que a extensão precisa saber antes de ler: os pedidos do TikTok na fila (para conferir
    os que sumiram da aba) e os que não precisam mais do detalhe (CPF guardado, ou já tentado
    TIKTOK_SC_TENTATIVAS_CPF vezes)."""
    with DB_LOCK:
        raw, _, _ = get_storage("conf_pedidos")
        # V20.38 (07/11, pedido 587022850875164046): pedido "a enviar" lido antes da V20.33 tem o CPF mas NÃO o preço
        # (venda_json): sem ele o atendimento não é criado. Fica fora desta lista para a extensão reabrir o detalhe.
        a_enviar = tuple(TIKTOK_SC_NA_FILA)
        com_detalhe = [r["pedido"] for r in DB.execute(
            "SELECT pedido FROM tiktok_sc_pedido_v2030 WHERE detalhe_em<>'' AND (cpf_ok=1 OR tentativas>=?) "
            f"AND (status NOT IN ({','.join('?' * len(a_enviar))}) OR ("
            "(COALESCE(venda_json,'')<>'' OR detalhe_em>=?) "
            "AND NOT (venda_json LIKE '%\"erro\"%' AND venda_json NOT LIKE ?))) "
            "ORDER BY detalhe_em DESC LIMIT ?",
            (TIKTOK_SC_TENTATIVAS_CPF, *a_enviar, TIKTOK_SC_PRECO_DESDE, f'%"regra":{TIKTOK_SC_VENDA_REGRA}%',
             TIKTOK_SC_MAX_PEDIDOS))]
    na_fila = sorted(_tiktok_sc_pedidos_na_fila(_rows_from_storage_value(raw)))[:TIKTOK_SC_MAX_PEDIDOS]
    # revisar-antes-de-subir (V20.40): com a fonte "api" a extensão não lê a aba (só levaria 409 a cada 2 min)
    return {"ok": True, "importacao": tiktok_importacao_ligada() and tiktok_fonte() != "api", "fonte": tiktok_fonte(),
            "na_fila": na_fila, "com_detalhe": com_detalhe,
            "ultima_leitura_epoch": int(float(_tiktok_config_ler("pedidos_extensao_epoch") or 0))}


def _tiktok_sc_lido_no_servidor(lido_em: Any, agora: Any) -> float:
    """Revisão 06/11: quando a extensão leu, no relógio do servidor (o do PC pode estar errado:
    só a diferença entre os dois números do PC conta). Sem os dois = agora."""
    try:
        atraso = (float(agora) - float(lido_em)) / 1000.0
    except (TypeError, ValueError):
        return time.time()
    if atraso != atraso or atraso < 0 or atraso == float("inf"):
        return time.time()
    return time.time() - min(atraso, 3600.0)


TIKTOK_SC_AVISO_PREFIXO = "TikTok: "


def _tiktok_sc_overrides_admin() -> set[tuple[str, str]]:
    """(identidade da linha, campo) que o ADMIN alterou na fila: a extensão não mexe neles."""
    try:
        with DB_LOCK:
            return {(str(r["entity_id"]), str(r["field_name"])) for r in DB.execute(
                "SELECT entity_id, field_name FROM admin_manual_overrides WHERE storage_key='conf_pedidos' "
                "AND is_deleted=0 AND field_name IN ('Quantidade','Cliente')").fetchall()}
    except Exception:
        return set()


def _tiktok_sc_aviso(row: dict[str, Any], texto: str) -> None:
    """Revisão 06/11: o aviso vai na Observação (a Conferência mostra como ⚠ no item); só mexe na
    Observação que ele mesmo escreveu — a do operador/ADMIN nunca é trocada nem apagada."""
    atual = str(row.get("Observação") or "")
    nosso = not atual or atual.startswith(TIKTOK_SC_AVISO_PREFIXO)
    if texto:
        row["AvisoTikTok"] = texto
        if nosso:
            row["Observação"] = TIKTOK_SC_AVISO_PREFIXO + texto
    elif "AvisoTikTok" in row:
        row.pop("AvisoTikTok", None)
        if atual.startswith(TIKTOK_SC_AVISO_PREFIXO):
            row["Observação"] = ""


def _tiktok_sc_acertar_existentes(fila: list[dict[str, Any]], atual: list[dict[str, Any]],
                                  novas: list[dict[str, Any]]) -> None:
    """Revisão 06/11, depois do _magalu_merge (que só copia os campos operacionais):
    - quantidade: a do TikTok agora (cancelamento parcial), nunca abaixo do que já foi bipado
      — nesse caso fica o bipado e a linha ganha o aviso; campo que o ADMIN alterou não muda;
    - TikTokAtualizadoEm só anda quando outro campo mudou (senão a fila seria regravada e
      todas as telas baixariam tudo a cada 2 min)."""
    antigas: dict[str, tuple[int, dict[str, Any]]] = {}
    for i, r in enumerate(atual):
        if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) == normalize(TIKTOK_SC_ORIGEM):
            antigas[str(r.get("__uidLinha") or "")] = (i, r)
    por_uid = {str(r.get("__uidLinha") or ""): r for r in novas if isinstance(r, dict)}
    overrides = _tiktok_sc_overrides_admin()
    for row in fila:
        if not isinstance(row, dict):
            continue
        uid = str(row.get("__uidLinha") or "")
        if uid not in antigas:
            continue
        indice, velha = antigas[uid]
        entidade = _admin_override_entity_id("conf_pedidos", velha, indice)
        if (entidade, "Cliente") in overrides and "Cliente" in velha:
            row["Cliente"] = velha["Cliente"]
        nova = por_uid.get(uid)
        if nova is not None and (entidade, "Quantidade") not in overrides:
            qtd_nova = _tiktok_quantidade(nova.get("Quantidade"))
            lido = max(0, _tiktok_quantidade(row.get("Lido")) or 0)
            if qtd_nova is not None:
                if qtd_nova >= lido:
                    if str(row.get("Quantidade")) != str(qtd_nova):
                        row["Quantidade"] = str(qtd_nova)
                        if "Quantidade de Kits" in nova:
                            row["Quantidade de Kits"] = nova["Quantidade de Kits"]
                    _tiktok_sc_aviso(row, "")
                else:
                    row["Quantidade"] = str(lido)
                    _tiktok_sc_aviso(row, f"cancelado em parte: ficou {qtd_nova} un., já bipado {lido}. "
                                          "Confira antes de enviar.")
        if "TikTokAtualizadoEm" in velha:
            sem_hora = {k: v for k, v in row.items() if k != "TikTokAtualizadoEm"}
            if sem_hora == {k: v for k, v in velha.items() if k != "TikTokAtualizadoEm"}:
                row["TikTokAtualizadoEm"] = velha["TikTokAtualizadoEm"]


def tiktok_pedidos_da_extensao(pedidos: Any, detalhes: Any, completo: bool, ator: str,
                               lido_em: Any = None, agora: Any = None) -> dict[str, Any]:
    """Recebe a aba "Para enviar" (e os detalhes que a extensão abriu) e acerta a fila de Bauru."""
    _tiktok_recusar_extensao()  # V20.40: com a fonte "api" os pedidos vêm da API
    if not tiktok_importacao_ligada():
        raise TikTokImportacaoDesligada("A importação do TikTok está desligada (Admin → Integrações).")
    if not isinstance(pedidos, list) or not isinstance(detalhes, list):
        raise ValueError("Formato inválido: pedidos e detalhes precisam ser listas.")
    if len(pedidos) > TIKTOK_SC_MAX_PEDIDOS or len(detalhes) > TIKTOK_SC_MAX_PEDIDOS:
        raise ValueError(f"No máximo {TIKTOK_SC_MAX_PEDIDOS} pedidos por envio.")
    if pedidos:
        _tiktok_guardar_amostra("seller_center pedidos/list", _tiktok_sc_sem_comprador(pedidos[0]))
    if detalhes:
        _tiktok_guardar_amostra("seller_center pedidos/get", _tiktok_sc_sem_comprador(detalhes[0]))
    lido_srv = _tiktok_sc_lido_no_servidor(lido_em, agora)
    lidos: dict[str, dict[str, Any]] = {}
    for o in pedidos:
        p = tiktok_sc_pedido(o)
        if p:
            lidos[p["id"]] = p
    det: dict[str, dict[str, Any]] = {}
    for o in detalhes:
        p = tiktok_sc_pedido(o)
        if p:
            det[p["id"]] = p
    for numero, p in det.items():              # o detalhe foi lido agora: vale mais que a lista
        if numero in lidos or p["status"] in TIKTOK_SC_NA_FILA:
            lidos[numero] = p
    if not TIKTOK_SYNC_LOCK.acquire(blocking=False):
        raise TikTokRodadaOcupada("Já tem uma importação do TikTok rodando. Tente de novo em instantes.")
    try:
        # Dentro da vez: a saída confirmada por outro PC (saiu_epoch) já está gravada quando esta lê.
        with DB_LOCK:
            guardados = {r["pedido"]: dict(r) for r in DB.execute(
                "SELECT pedido, nome, status, saiu_epoch FROM tiktok_sc_pedido_v2030")}
        # Revisão 06/11: leitura feita ANTES de o TikTok confirmar a saída (outro PC, envio atrasado)
        # não reabre o pedido nem desfaz a situação guardada.
        atrasados = {n for n, p in lidos.items() if p["status"] in TIKTOK_SC_NA_FILA
                     and float((guardados.get(n) or {}).get("saiu_epoch") or 0) > lido_srv}
        for n in atrasados:
            lidos.pop(n, None)
            det.pop(n, None)
        abertos = [p for p in lidos.values() if p["status"] in TIKTOK_SC_NA_FILA]
        saiu = {n for n, p in det.items() if p["status"] in TIKTOK_SC_SAIU}  # só com o TikTok confirmando
        # revisar-antes-de-subir (06/11): leitura da fila, conta e gravação na mesma vez do DB_LOCK — um bip
        # entre a leitura e a gravação deixava a Quantidade abaixo do bipado até a rodada seguinte.
        with DB_LOCK:
            products_raw, _, _ = get_storage("conf_produtos")
            products = _rows_from_storage_value(products_raw)
            atual_raw, _, _ = get_storage("conf_pedidos")
            atual = _rows_from_storage_value(atual_raw)
            fila, removidas, pulados, api_linhas, ficam = _tiktok_sc_montar_fila(atual, abertos, saiu, guardados,
                                                                                products)
            save_storage("conf_pedidos", atual_raw, json_dumps(fila), False,
                         actor=f"extensao-tiktok:{ator}", actor_role="sistema",
                         source_screen="Extensão TikTok (Seller Center)", change_method="Pedidos do Seller Center TikTok",
                         client_ip="127.0.0.1", allow_completed_reimport=False,
                         remove_pending_identities=removidas)
        agora_epoch = time.time()
        with DB_LOCK:
            for numero in saiu:
                DB.execute("""INSERT INTO tiktok_sc_pedido_v2030(pedido,status,detalhe_em,visto_em,saiu_epoch)
                              VALUES(?,?,?,?,?)
                              ON CONFLICT(pedido) DO UPDATE SET status=excluded.status, visto_em=excluded.visto_em,
                                  saiu_epoch=excluded.saiu_epoch, detalhe_em=excluded.detalhe_em""",
                           (numero, det[numero]["status"], now_iso(), now_iso(), agora_epoch))
            DB.commit()
        fiscais, cpf_ok = _tiktok_sc_guardar_fiscais(det)
        # revisar-antes-de-subir (06/11): o registro dos lidos também dentro da vez (outro PC não grava por cima)
        _tiktok_sc_registrar_lidos(lidos, det, cpf_ok)
        # V20.33: preço e endereço do detalhe, para o atendimento no Apollo (só dos que ficam a enviar)
        _tiktok_sc_guardar_venda([o for o in detalhes if isinstance(o, dict)
                                  and str(o.get("main_order_id") or "").strip() in det
                                  and det[str(o.get("main_order_id")).strip()]["status"] in TIKTOK_SC_NA_FILA])
    finally:
        TIKTOK_SYNC_LOCK.release()
    # revisar-antes-de-subir (06/11): situação/quantidade que o sistema não conhece vai para o Painel de saúde
    # (sem isso nenhum pedido entrava e o painel dizia "ok").
    todos = list(lidos.values()) + list(det.values())
    desconhecidos = sorted({c for p in todos for c in p.get("_desconhecidos") or []})
    if completo or desconhecidos:
        _tiktok_config_gravar("pedidos_desconhecidos", json.dumps(
            {"epoch": int(time.time()), "codigos": desconhecidos[:10],
             "pedidos": sorted({p["id"] for p in todos if p.get("_desconhecidos")})[:10]}, ensure_ascii=False), ator)
    if completo:
        _tiktok_config_gravar("pedidos_extensao_epoch", str(int(time.time())), ator)
    resumo = {"ok": True, "pedidos": len({order_number(r) for r in api_linhas if isinstance(r, dict)}),
              "abertos": len(abertos), "linhas": len(api_linhas), "removidas": len(removidas),
              "saiu_confirmado": len(saiu), "mantidos_sem_confirmar": len(ficam - saiu),
              "ignorados_leitura_antiga": len(atrasados), "situacao_desconhecida": desconhecidos,
              "ja_na_fila_por_outra_origem": pulados, "nome_cpf_guardados": fiscais, "completo": bool(completo)}
    tiktok_log_event_se_mudou("pedidos", "extensao Seller Center", "OK" if completo else "PARCIAL",
                              f"{len(abertos)} pedido(s) a enviar, {len(removidas)} linha(s) removida(s), "
                              f"{len(saiu)} confirmado(s) enviado/cancelado"
                              + (f"; situação desconhecida: {', '.join(desconhecidos)}" if desconhecidos else ""))
    return resumo


def _tiktok_sc_montar_fila(atual: list[dict[str, Any]], abertos: list[dict[str, Any]], saiu: set[str],
                           guardados: dict[str, dict[str, Any]], products: list[dict[str, Any]],
                           etiqueta: tuple[set[str], bool] | None = None):
    """Fila nova (sob o DB_LOCK, sem rede): linhas dos pedidos a enviar, os que ficam e as remoções nomeadas."""
    cliente_atual: dict[str, str] = {}
    for r in atual:
        if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) == normalize(TIKTOK_SC_ORIGEM):
            nome_linha = str(r.get("Cliente") or "").strip()
            if nome_linha:
                cliente_atual.setdefault(str(order_number(r) or "").strip(), nome_linha)
    api_linhas: list[dict[str, Any]] = []
    for p in abertos:
        if not p["recipient_address"]["name"]:
            # revisar-antes-de-subir (06/11): o Cliente que a linha já tem vale mais que o apelido (ou vazio)
            p["recipient_address"]["name"] = ((guardados.get(p["id"]) or {}).get("nome")
                                              or p["_cpf_nome"] or cliente_atual.get(p["id"]) or p["_apelido"])
        api_linhas.extend(_tiktok_linhas_do_pedido(p, products, etiqueta))  # V20.40: a API manda a etiqueta
    novas = list(api_linhas)
    # Quem sumiu da aba sem o TikTok confirmar fica como está (a linha antiga volta igual).
    # (pedido aberto que não gerou linha — sem SKU, por exemplo — também fica como está)
    com_linhas = {str(order_number(r) or "").strip() for r in api_linhas}
    ficam = _tiktok_sc_pedidos_na_fila(atual) - com_linhas - saiu
    for r in atual:
        if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) == normalize(TIKTOK_SC_ORIGEM) \
                and str(order_number(r) or "").strip() in ficam:
            api_linhas.append(r)
    fila, removidas, pulados = _magalu_merge(atual, api_linhas, origem=TIKTOK_SC_ORIGEM,
                                             campos=TIKTOK_CAMPOS_OPERACIONAIS + ("Cliente",))
    _tiktok_sc_acertar_existentes(fila, atual, novas)
    # Revisão 06/11 — remoção NOMEADA (a linha protegida pelo ADMIN nunca sai por aqui). O merge
    # já deixou estas linhas de fora; sem o nome, o preserve_pending_records_v1714 as traria de volta:
    # (a) SKU do pedido aberto sem nenhuma unidade a enviar (cancelado inteiro ou já enviado);
    # (b) pedido que o ADMIN incluiu por outra origem depois da importação: a cópia da
    #     extensão sem bip sai (com bip fica: o progresso da conferência não se perde).
    abertos_por_id = {p["id"]: p for p in abertos}
    outra_origem = {normalize(order_number(r)) for r in atual
                    if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) != normalize(TIKTOK_SC_ORIGEM)}
    no_resultado = {str(r.get("__uidLinha") or "") for r in fila if isinstance(r, dict)}
    for indice, r in enumerate(atual):
        if not isinstance(r, dict) or normalize(r.get("OrigemCadastro")) != normalize(TIKTOK_SC_ORIGEM):
            continue
        if str(r.get("__uidLinha") or "") in no_resultado:
            continue
        numero = str(order_number(r) or "").strip()
        p = abertos_por_id.get(numero)
        bipado = _tiktok_quantidade(r.get("Lido")) or 0
        if numero in saiu and bipado:
            # revisar-antes-de-subir (06/11): pedido cancelado/enviado INTEIRO com peça já bipada também
            # não some calado (o _magalu_merge já tinha posto a linha na remoção nomeada).
            removidas.discard(_pending_identity_v1714(r, indice))
            fica = dict(r)
            _tiktok_sc_aviso(fica, f"cancelado ou já enviado no TikTok, já bipado {bipado}. "
                                   "Confira antes de enviar.")
            fila.append(fica)
            continue
        if p and _tiktok_sc_linha_fora(r, p):
            if bipado:
                # Já bipada: não some calada (a peça está separada) — fica com o aviso.
                fica = dict(r)
                _tiktok_sc_aviso(fica, f"cancelado ou já enviado no TikTok, já bipado {bipado}. "
                                       "Confira antes de enviar.")
                fila.append(fica)
            else:
                removidas.add(_pending_identity_v1714(r, indice))
        elif normalize(numero) in outra_origem and not bipado:
            removidas.add(_pending_identity_v1714(r, indice))
    return fila, removidas, pulados, api_linhas, ficam


def _tiktok_sc_guardar_fiscais(det: dict[str, dict[str, Any]]) -> tuple[int, set[str]]:
    # Nome/CPF da nota (para o cadastro no Apollo): só quando o pedido ainda não tem nada guardado
    # — o que outra extensão ou o Admin gravou nunca é sobrescrito (conferido de novo por pedido).
    fiscais = 0
    cpf_ok: set[str] = set()
    for numero, p in det.items():
        with DB_LOCK:
            ja = DB.execute("SELECT 1 FROM cliente_fiscal WHERE order_key=?", (normalize(numero),)).fetchone()
        if ja:
            cpf_ok.add(numero)
            continue
        if p["status"] in TIKTOK_SC_NA_FILA and len(p["_cpf"]) in (11, 14) and p["_cpf_nome"]:
            try:
                # revisar-antes-de-subir (06/11): `so_se_vazio` confere e grava na mesma vez do DB_LOCK
                r_fiscal = salvar_cliente_fiscal(numero, p["_cpf"], p["_cpf_nome"], fonte="tiktok_sc",
                                                 usuario="extensao-tiktok", so_se_vazio=True)
                if r_fiscal.get("ok") or r_fiscal.get("ja_existia"):
                    cpf_ok.add(numero)
                if r_fiscal.get("ok"):
                    fiscais += 1
            except Exception as exc:
                tiktok_log_event_se_mudou("pedidos", f"cliente_fiscal {numero}", "ERRO", str(exc)[:300])
    return fiscais, cpf_ok


def _tiktok_sc_registrar_lidos(lidos: dict[str, dict[str, Any]], det: dict[str, dict[str, Any]],
                               cpf_ok: set[str]) -> None:
    agora_iso = now_iso()
    with DB_LOCK:
        for p in lidos.values():
            no_det = p["id"] in det
            nome = p["recipient_address"]["name"] if no_det else ""
            DB.execute(
                """INSERT INTO tiktok_sc_pedido_v2030(pedido,nome,status,detalhe_em,visto_em,cpf_ok,tentativas)
                   VALUES(?,?,?,?,?,?,?)
                   ON CONFLICT(pedido) DO UPDATE SET status=excluded.status, visto_em=excluded.visto_em,
                       nome=CASE WHEN excluded.nome<>'' THEN excluded.nome ELSE tiktok_sc_pedido_v2030.nome END,
                       detalhe_em=CASE WHEN excluded.detalhe_em<>'' THEN excluded.detalhe_em ELSE tiktok_sc_pedido_v2030.detalhe_em END,
                       cpf_ok=MAX(tiktok_sc_pedido_v2030.cpf_ok, excluded.cpf_ok),
                       tentativas=tiktok_sc_pedido_v2030.tentativas + excluded.tentativas""",
                (p["id"], nome[:200], p["status"], agora_iso if no_det else "", agora_iso,
                 1 if p["id"] in cpf_ok else 0, 1 if no_det else 0))
        DB.execute("DELETE FROM tiktok_sc_pedido_v2030 WHERE visto_em < ?",
                   ((datetime.now(timezone.utc) - timedelta(days=60)).astimezone().isoformat(timespec="milliseconds"),))
        DB.commit()


_TIKTOK_LOG_ULTIMO: dict[tuple[str, str], tuple[str, str]] = {}


def tiktok_log_event_se_mudou(topic: str, resource: str, result: str, detail: str = "") -> bool:
    chave = (topic, resource)
    if _TIKTOK_LOG_ULTIMO.get(chave) == (result, detail):
        return False
    _TIKTOK_LOG_ULTIMO[chave] = (result, detail)
    tiktok_log_event(topic, resource, result, detail)
    return True


def tiktok_rodada() -> dict[str, Any]:
    """Uma volta do worker de pedidos: mantém o token vivo e, ligada, importa."""
    if not tiktok_status_payload().get("connected"):
        return {"importou": False, "motivo": "desconectado"}
    tiktok_access_token()
    if not tiktok_importacao_ligada():
        return {"importou": False, "motivo": "importacao_desligada"}
    # revisar-antes-de-subir (06/11): uma fonte de cada vez. A API e a extensão do Seller Center gravam as mesmas
    # linhas com regras diferentes (a extensão só tira com o TikTok confirmando); juntas, a fila alternava.
    # V20.40: a fonte é escolhida pelo Admin no cartão (tiktok_fonte); antes era "a extensão leu nas últimas 6 h".
    if _tiktok_extensao_em_uso():
        tiktok_log_event_se_mudou("pedidos", "worker", "IGNORADO",
                                  "a fonte do TikTok é a extensão do Seller Center: a API não importa")
        return {"importou": False, "motivo": "extensao_em_uso"}
    return {"importou": True, **tiktok_importar_pedidos()}


def _tiktok_extensao_em_uso() -> bool:
    """V20.40: a fonte do TikTok é a extensão do Seller Center (a escolha do Admin no cartão)?"""
    return tiktok_fonte() != "api"


def tiktok_pedidos_loop(stop_event: threading.Event) -> None:
    stop_event.wait(50)
    while not stop_event.is_set():
        try:
            tiktok_rodada()
        except Exception as exc:
            with DB_LOCK:
                DB.execute("UPDATE tiktok_integration SET last_error=? WHERE id=1", (str(exc)[:500],))
                DB.commit()
            tiktok_log_event_se_mudou("pedidos", "worker", "ERRO", str(exc)[:800])
        stop_event.wait(TIKTOK_PEDIDOS_INTERVALO)


# ---------------------------------------------------------------------------
# V20.33 — Atendimento do TikTok no Apollo (decisões do dono, 06/11: "a mesma rotina do ML").
# O TikTok não tem integração com o Apollo: ninguém cria o cliente nem o atendimento. Esta rotina
# faz o que a integração do ML faz: cadastra o cliente (cria se não existe, com o endereço do
# detalhe do pedido) e em seguida cria o atendimento pela porta `atendimento/criar` na revenda de
# Bauru, com o kit aberto em peças e o preço do kit dividido pelo CUSTO (Araçatuba, regra do
# Financeiro). Venda = preço da unidade com o desconto da LOJA (o subsídio do TikTok não entra).
# A porta nunca cria dois atendimentos para o mesmo `pedido_externo` ("ja_existia"): resposta
# perdida pode ser repetida. Interruptor em tiktok_config_v1964 `atendimento_auto`, começa DESLIGADO.
# ---------------------------------------------------------------------------
TIKTOK_ATEND_ORIGEM = "TIKTOK"
TIKTOK_ATEND_CONDICAO = 973          # condição de pagamento do TikTok (dono, 06/11)
# revisar-antes-de-subir (06/11): UM pedido por volta de 2 min. A porta aceita 6 escritas/min e cada pedido faz até 4
# (criar, atualizar, crédito, atendimento); dois seguidos estouravam o limite e o painel/Faturamento levavam 429.
TIKTOK_ATEND_POR_RODADA = 1
TIKTOK_ATEND_INTERVALO = 120
TIKTOK_ATEND_FINAIS = ("criado", "ja_existia")
# Quanto esperar para tentar de novo, por situação (segundos).
TIKTOK_ATEND_ESPERA = {"passageiro": 120, "incerto": 600, "erro": 1800, "revisar": 3600, "cadastro": 600}


class TikTokAtendRevisar(Exception):
    """Dado que o sistema não resolve sozinho (preço, kit, custo): alguém confere."""


def ensure_tiktok_atendimento_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """
            CREATE TABLE IF NOT EXISTS tiktok_atendimento_v2033 (
                pedido TEXT PRIMARY KEY,
                situacao TEXT NOT NULL DEFAULT '',
                detalhe TEXT NOT NULL DEFAULT '',
                cliente TEXT NOT NULL DEFAULT '',
                atendimento TEXT NOT NULL DEFAULT '',
                valor REAL,
                itens_json TEXT NOT NULL DEFAULT '',
                tentativas INTEGER NOT NULL DEFAULT 0,
                proxima_epoch REAL NOT NULL DEFAULT 0,
                atualizado_em TEXT NOT NULL DEFAULT ''
            );
            """
        )
        colunas = {r["name"] for r in DB.execute("PRAGMA table_info(tiktok_sc_pedido_v2030)")}
        for nome in ("venda_json", "endereco_json"):
            if nome not in colunas:
                DB.execute(f"ALTER TABLE tiktok_sc_pedido_v2030 ADD COLUMN {nome} TEXT NOT NULL DEFAULT ''")
        # V20.43: peças do atendimento comprometidas (porta atendimento/comprometer)
        colunas = {r["name"] for r in DB.execute("PRAGMA table_info(tiktok_atendimento_v2033)")}
        for nome, tipo in (("comprometido", "TEXT NOT NULL DEFAULT ''"), ("comp_detalhe", "TEXT NOT NULL DEFAULT ''"),
                           ("comp_itens_json", "TEXT NOT NULL DEFAULT ''"),
                           ("comp_tentativas", "INTEGER NOT NULL DEFAULT 0"), ("comp_proxima", "REAL NOT NULL DEFAULT 0")):
            if nome not in colunas:
                DB.execute(f"ALTER TABLE tiktok_atendimento_v2033 ADD COLUMN {nome} {tipo}")
        DB.commit()


def tiktok_atendimento_ligado() -> bool:
    return _tiktok_config_ler("atendimento_auto") == "1"   # sem escolha = DESLIGADO


def tiktok_atendimento_definir(ligado: bool, usuario: str) -> None:
    estava = tiktok_atendimento_ligado()
    if ligado and not estava:
        # revisar-antes-de-subir (06/11): o que JÁ está na fila ao ligar foi (ou está sendo) atendido à mão —
        # um atendimento aberto à mão não tem a chave TIKTOK-<pedido>, e a porta criaria outro. Fica de fora.
        with DB_LOCK:
            bruto, _, _ = get_storage("conf_pedidos")
            na_fila = _tiktok_sc_pedidos_na_fila(_rows_from_storage_value(bruto))
            agora = now_iso()
            for numero in na_fila:
                DB.execute("INSERT OR IGNORE INTO tiktok_atendimento_v2033(pedido,situacao,detalhe,atualizado_em) "
                           "VALUES(?,?,?,?)", (numero, "anterior", "Já estava na fila ao ligar: atendimento à mão.", agora))
            DB.commit()
        _tiktok_config_gravar("atendimento_ligado_em", now_iso(), usuario)
    _tiktok_config_gravar("atendimento_auto", "1" if ligado else "0", usuario)
    tiktok_log_event("atendimento", "", "LIGADO" if ligado else "DESLIGADO", f"por {usuario}")


def _tiktok_num(v: Any) -> float | None:
    """Preço do Seller Center: número, texto ou {"price_val": ...}. Desconhecido = None (nunca zero)."""
    if isinstance(v, dict):
        for k in ("price_val", "amount", "value", "val"):
            if k in v:
                return _tiktok_num(v[k])
        return None
    try:
        n = float(str(v).replace(",", ".")) if isinstance(v, str) else float(v)
    except (TypeError, ValueError):
        return None
    return n if n == n and abs(n) != float("inf") else None


def _tiktok_sc_venda(o: Any) -> dict[str, Any] | None:
    """Valor de cada SKU do pedido (só as unidades ainda a enviar) pelo detalhe do Seller Center.
    Unidade = `sku_unit_price` (preço cheio); o desconto da loja (`seller_discount_total`) é rateado.
    Confere com `main_order_origin_sale_price`: se a soma das unidades já é o valor com desconto, não
    desconta de novo; se não bate com nenhum dos dois, devolve {"erro"} (ninguém adivinha o preço)."""
    if not isinstance(o, dict):
        return None
    p = tiktok_sc_pedido(o)
    pm = o.get("price_module") if isinstance(o.get("price_module"), dict) else {}
    if not p or not pm:
        return None
    abertas = {(str(i["sku_id"]), normalize(i["seller_sku"])): int(i["quantity"]) for i in p["line_items"]}
    soma_cheia, itens = 0.0, []
    parcial = False
    for sk in o.get("sku_module") or []:
        if not isinstance(sk, dict):
            continue
        unit = _tiktok_num(sk.get("sku_unit_price"))
        total_linhas = len(sk.get("order_line_ids") or []) or _tiktok_quantidade(sk.get("quantity")) or 0
        if unit is None or unit <= 0:
            return {"erro": f"o TikTok não informou o preço do SKU {sk.get('seller_sku_name') or '?'}"}
        soma_cheia += unit * total_linhas
        sku = str(sk.get("seller_sku_name") or "").strip()
        qtd = abertas.get((str(sk.get("sku_id") or ""), normalize(sku)), 0)
        parcial = parcial or qtd < total_linhas
        if qtd > 0:
            itens.append({"sku_id": str(sk.get("sku_id") or ""), "sku": sku, "qtd": qtd, "unitario": unit})
    origem = _tiktok_num(pm.get("main_order_origin_sale_price"))
    desconto = _tiktok_num(pm.get("seller_discount_total")) or 0.0
    plataforma = _tiktok_num(pm.get("platform_discount_total")) or 0.0  # V20.39: subsídio do TikTok
    if origem is None or origem <= 0:
        return {"erro": "o TikTok não informou o valor do pedido"}
    # revisar-antes-de-subir (06/11): desconto negativo inflaria o preço; e com unidade cancelada não dá para saber de
    # qual produto era o desconto da loja (o rateio pelo pedido inteiro erraria o preço do que ficou).
    if desconto < 0:
        return {"erro": "desconto da loja negativo no TikTok"}
    if plataforma < 0:
        return {"erro": "desconto do TikTok negativo"}
    if parcial and (desconto > 0 or plataforma > 0):
        return {"erro": "pedido com unidade cancelada e desconto da loja: não dá para saber de qual produto era o desconto"}
    if abs(soma_cheia - origem) <= 0.02:
        fator = (origem - desconto) / origem
    elif abs(soma_cheia - (origem - desconto)) <= 0.02:
        fator = 1.0
    elif plataforma > 0 and abs(soma_cheia - (origem - desconto - plataforma)) <= 0.02:
        # V20.39 (1º pedido real, 07/11, 587022850875164046): o Seller Center manda a unidade já SEM os dois descontos
        # (119,90 − 45,10 da loja − 5,05 do TikTok = 69,75). A venda leva só o desconto da loja (o subsídio o TikTok
        # repassa): volta ao valor com o desconto da loja (74,80).
        fator = (origem - desconto) / soma_cheia
    else:
        return {"erro": f"preço das unidades ({soma_cheia:.2f}) não confere com o valor do pedido ({origem:.2f})"}
    if fator <= 0:
        return {"erro": "desconto da loja maior que o pedido"}
    for i in itens:
        i["valor"] = round(i["unitario"] * i["qtd"] * fator, 4)
    return {"itens": itens, "fator": round(fator, 6), "desconto_loja": desconto, "origem": origem,
            "desconto_tiktok": plataforma}


def _tiktok_sc_endereco_cadastro(o: Any) -> dict[str, str] | None:
    """Endereço do detalhe no formato que o cadastro lê (exp_endereco_do_texto) + o bairro à parte."""
    if not isinstance(o, dict):
        return None
    e = _tiktok_sc_endereco(o)
    limpo = lambda v: re.sub(r"\s+", " ", str(v or "")).strip().replace(",", " ")
    rua, cidade, uf, cep = limpo(e.get("street_name")), limpo(e.get("geo_l2")), limpo(e.get("geo_l1")), \
        re.sub(r"\D", "", str(e.get("zipcode") or ""))
    partes = [rua, limpo(e.get("street_number")) or "S/N", limpo(e.get("address_detail")), cidade, uf, cep]
    if not (rua and cidade and uf and len(cep) == 8) or any("*" in x for x in partes):
        return None
    bairro = limpo(e.get("neighborhood"))
    return {"texto": ", ".join(x for x in partes if x), "bairro": "" if "*" in bairro else bairro}


def _tiktok_sc_guardar_venda(detalhes: list[Any]) -> None:
    """Guarda o valor e o endereço lidos no detalhe (o que faltar não apaga o que já está)."""
    for o in detalhes:
        if not isinstance(o, dict) or not str(o.get("main_order_id") or "").strip().isdigit():
            continue
        numero = str(o["main_order_id"]).strip()
        try:
            venda = _tiktok_sc_venda(o)
            if isinstance(venda, dict) and venda.get("erro"):
                venda = {**venda, "regra": TIKTOK_SC_VENDA_REGRA}  # V20.39: erro de regra velha é relido uma vez
            endereco = _tiktok_sc_endereco_cadastro(o)
        except Exception as exc:  # leitura tolerante: nunca derruba a importação
            tiktok_log_event_se_mudou("atendimento", f"leitura {numero}", "ERRO", str(exc)[:300])
            continue
        if not venda and not endereco:
            continue
        with DB_LOCK:
            DB.execute(
                """INSERT INTO tiktok_sc_pedido_v2030(pedido,visto_em,venda_json,endereco_json) VALUES(?,?,?,?)
                   ON CONFLICT(pedido) DO UPDATE SET
                       venda_json=CASE WHEN excluded.venda_json<>'' THEN excluded.venda_json ELSE tiktok_sc_pedido_v2030.venda_json END,
                       endereco_json=CASE WHEN excluded.endereco_json<>'' THEN excluded.endereco_json ELSE tiktok_sc_pedido_v2030.endereco_json END""",
                (numero, now_iso(), json_dumps(venda) if venda else "", json_dumps(endereco) if endereco else ""))
            DB.commit()


# ---------------------------------------------------------------------------
# V20.40 — com a fonte "api", o atendimento no Apollo (V20.33) recebe da Open API o que hoje vem do detalhe do
# Seller Center: situação, preço, endereço e nome/CPF da nota, nas MESMAS tabelas (tiktok_sc_pedido_v2030,
# cliente_fiscal). Formato da Open API 202309 pela documentação, sem resposta real: a 1ª fica em
# tiktok_amostra_v1963 (conferir ao conectar). Leitura tolerante: o que falta fica vazio e o atendimento espera
# ("aguardando") ou vai para "revisar" — nunca adivinha preço, CPF ou endereço.
# ---------------------------------------------------------------------------
TIKTOK_API_RELER_MAX = 50       # pedidos que sumiram da lista "a enviar" relidos por volta (GET /orders?ids=)
_TIKTOK_API_RELIDO: dict[str, float] = {}  # pedido -> quando foi relido (rodízio: o mais antigo primeiro)


def _tiktok_api_pacote_aberto_primeiro(o: Any) -> Any:
    """2ª revisão (V20.40): o pacote que ainda tem unidade a enviar vem primeiro (é o da coluna e o da etiqueta), como
    na extensão. Parcialmente enviado: o 1º pacote da API pode ser o que já saiu. Devolve uma cópia; sem como saber,
    a ordem fica a da API."""
    if not isinstance(o, dict) or not isinstance(o.get("packages"), list):
        return o
    abertos = {str(li.get("package_id") or "") for li in (o.get("line_items") or [])
               if isinstance(li, dict) and str(li.get("display_status") or "").upper() not in TIKTOK_SC_SAIU}
    abertos.discard("")
    if not abertos:
        return o
    pacotes = sorted(o["packages"], key=lambda p: 0 if isinstance(p, dict) and str(p.get("id") or "") in abertos else 1)
    return {**o, "packages": pacotes}


def _tiktok_api_para_sc(o: Any) -> dict[str, Any] | None:
    """revisar-antes-de-subir (V20.40): pedido da Open API no formato que _tiktok_sc_montar_fila (a regra da extensão,
    V20.30) entende. Conta só as unidades ainda a enviar (cancelada e já enviada ficam fora); variação sem unidade a
    enviar vai para `_fora_uids`/`_skus_fora` (sai pela remoção nomeada, ou fica com aviso se já bipada)."""
    if not isinstance(o, dict):
        return None
    numero = str(o.get("id") or "").strip()
    if not numero:
        return None
    fora = set(TIKTOK_SC_SAIU)
    grupos: dict[tuple[str, str], dict[str, Any]] = {}
    for li in o.get("line_items") or []:
        if not isinstance(li, dict):
            continue
        sku = str(li.get("seller_sku") or "").strip()
        g = grupos.setdefault((str(li.get("sku_id") or ""), sku),
                              {"nome": str(li.get("product_name") or ""), "abertas": 0})
        if str(li.get("display_status") or "").upper() not in fora:
            g["abertas"] += max(1, _tiktok_quantidade(li.get("quantity")) or 1)
    itens, fora_uids, vistos, abertos_skus = [], set(), set(), set()
    for (sku_id, sku), g in grupos.items():
        if sku:
            vistos.add(normalize(sku))
        if g["abertas"] <= 0:
            if sku:
                fora_uids.add(_tiktok_uid_api(numero, sku_id, sku))
            continue
        if sku:
            abertos_skus.add(normalize(sku))
        itens.append({"sku_id": sku_id, "seller_sku": sku, "product_name": g["nome"], "quantity": min(g["abertas"], 999)})
    endereco = o.get("recipient_address") if isinstance(o.get("recipient_address"), dict) else {}
    return {"id": numero, "status": str(o.get("status") or ""), "create_time": o.get("create_time"),
            "rts_sla_time": o.get("rts_sla_time"), "line_items": itens,
            "packages": [p for p in (o.get("packages") or []) if isinstance(p, dict)],
            "recipient_address": {"name": str(endereco.get("name") or "")},
            "_skus_fora": vistos - abertos_skus, "_fora_uids": fora_uids, "_apelido": "",
            "_cpf": re.sub(r"\D", "", str(o.get("cpf") or "")),
            "_cpf_nome": re.sub(r"\s+", " ", str(o.get("cpf_name") or "")).strip(), "_desconhecidos": []}


def _tiktok_api_reler(numeros: list[str]) -> dict[str, str]:
    """Situação atual dos pedidos que sumiram da lista "a enviar" (até TIKTOK_API_RELER_MAX por volta, o relido há
    mais tempo primeiro). Sem resposta ou pedido que não veio = fora do resultado (fica como está, nunca "saiu")."""
    if not numeros:
        return {}
    fila = sorted(numeros, key=lambda n: _TIKTOK_API_RELIDO.get(n, 0.0))[:TIKTOK_API_RELER_MAX]
    saida: dict[str, str] = {}
    for i in range(0, len(fila), 50):
        lote = fila[i:i + 50]
        try:
            resp = tiktok_api("GET", "/order/202309/orders", params={"ids": ",".join(lote)})
        except Exception as exc:
            tiktok_log_event_se_mudou("pedidos", "/order/202309/orders", "ERRO", str(exc)[:500])
            break
        agora = time.time()
        for n in lote:
            _TIKTOK_API_RELIDO[n] = agora
        dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
        for o in dados.get("orders") or []:
            if isinstance(o, dict) and str(o.get("id") or "") in lote and str(o.get("status") or ""):
                saida[str(o["id"])] = str(o["status"])
    for n in list(_TIKTOK_API_RELIDO):
        if n not in numeros:
            _TIKTOK_API_RELIDO.pop(n, None)
    return saida


def _tiktok_api_venda(o: dict[str, Any]) -> dict[str, Any] | None:
    """Preço do pedido pela Open API: cada line_item é UMA unidade. Valor = preço cheio − desconto da LOJA (o subsídio
    do TikTok não entra, mesma regra do Seller Center, V20.39). Unidade cancelada fica de fora."""
    itens: dict[tuple[str, str], dict[str, Any]] = {}
    desconto_loja = desconto_tiktok = origem = 0.0
    for li in o.get("line_items") or []:
        if not isinstance(li, dict):
            continue
        if str(li.get("display_status") or "").upper() in TIKTOK_SC_SAIU:
            continue  # 2ª revisão (V20.40): cancelada E já enviada ficam fora (a fila conta só o que falta enviar)
        sku = str(li.get("seller_sku") or "").strip()
        cheio = _tiktok_num(li.get("original_price"))
        loja = _tiktok_num(li.get("seller_discount"))
        plataforma = _tiktok_num(li.get("platform_discount"))
        if cheio is None or cheio <= 0:
            return {"erro": f"a API do TikTok não informou o preço do SKU {sku or '?'}"}
        loja = loja or 0.0
        if loja < 0 or (plataforma or 0) < 0:
            return {"erro": "desconto negativo na API do TikTok"}
        if loja >= cheio:
            return {"erro": f"desconto da loja maior que o preço do SKU {sku or '?'}"}
        n = max(1, _tiktok_quantidade(li.get("quantity")) or 1)  # a API manda um line_item por unidade
        chave = (str(li.get("sku_id") or ""), sku)
        it = itens.setdefault(chave, {"sku_id": chave[0], "sku": sku, "qtd": 0, "unitario": cheio, "valor": 0.0})
        it["qtd"] += n
        it["valor"] = round(it["valor"] + (cheio - loja) * n, 4)
        origem += cheio * n
        desconto_loja += loja * n
        desconto_tiktok += (plataforma or 0.0) * n
    if not itens:
        return None
    return {"itens": list(itens.values()), "fator": round((origem - desconto_loja) / origem, 6) if origem else 1.0,
            "desconto_loja": round(desconto_loja, 2), "origem": round(origem, 2),
            "desconto_tiktok": round(desconto_tiktok, 2), "fonte": "api"}


_TIKTOK_NIVEL_NOME = {"uf": ("state", "estado", "province"), "cidade": ("city", "cidade", "municipality", "município"),
                      "bairro": ("district", "neighborhood", "neighbourhood", "bairro")}


def _tiktok_api_endereco(o: dict[str, Any]) -> dict[str, str] | None:
    """Endereço da Open API no formato do cadastro (exp_endereco_do_texto): rua, número, complemento, cidade, UF, CEP.
    `district_info`: casa pelo nome do nível (state/city/district); sem nome, L1 = UF, L2 = cidade, L3 = bairro.
    revisar-antes-de-subir (V20.40): o número tem de vir claro (`address_line2` só com número); faltou ou parece outra
    coisa = None — o atendimento espera, nunca troca o endereço certo do cliente por um montado por suposição."""
    e = o.get("recipient_address") if isinstance(o.get("recipient_address"), dict) else {}
    limpo = lambda v: re.sub(r"\s+", " ", str(v or "")).strip().replace(",", " ")
    por_nivel: dict[str, str] = {}
    por_nome: dict[str, str] = {}
    for d in e.get("district_info") or []:
        if not isinstance(d, dict):
            continue
        valor = limpo(d.get("address_name"))
        por_nivel[str(d.get("address_level") or "").upper()] = valor
        nome_nivel = str(d.get("address_level_name") or "").strip().lower()
        for campo, nomes in _TIKTOK_NIVEL_NOME.items():
            if nome_nivel in nomes:
                por_nome.setdefault(campo, valor)
    uf = por_nome.get("uf") or por_nivel.get("L1", "")
    cidade = por_nome.get("cidade") or por_nivel.get("L2", "")
    bairro = por_nome.get("bairro") or por_nivel.get("L3", "")
    rua = limpo(e.get("address_line1"))
    numero = limpo(e.get("address_line2"))
    if not re.fullmatch(r"\d{1,6}\s?[A-Za-z]?", numero):
        return None
    compl = limpo(e.get("address_line3"))
    cep = re.sub(r"\D", "", str(e.get("postal_code") or ""))
    partes = [rua, numero, compl, cidade, uf, cep]
    if not (rua and cidade and uf and len(cep) == 8) or any("*" in x for x in partes):
        return None
    return {"texto": ", ".join(x for x in partes if x), "bairro": "" if "*" in bairro else bairro}


def _tiktok_api_registrar_pedidos(pedidos: list[dict[str, Any]], relidos: dict[str, str] | None = None) -> dict[str, int]:
    """Grava situação, preço, endereço e nome/CPF da nota dos pedidos lidos pela API (o que faltar não apaga o que
    já está) e a situação confirmada dos que sumiram da lista (`relidos`, de _tiktok_api_reler)."""
    agora_iso = now_iso()
    fiscais = 0
    ids: set[str] = set()
    for o in pedidos:
        numero = str(o.get("id") or "").strip()
        if not numero:
            continue
        ids.add(numero)
        venda = _tiktok_api_venda(o)
        erro = isinstance(venda, dict) and bool(venda.get("erro"))
        if erro:
            venda = {**venda, "regra": TIKTOK_SC_VENDA_REGRA}
        endereco = _tiktok_api_endereco(o)
        nome = str(((o.get("recipient_address") or {}) if isinstance(o.get("recipient_address"), dict) else {}).get("name") or "")
        cpf = re.sub(r"\D", "", str(o.get("cpf") or ""))
        cpf_nome = re.sub(r"\s+", " ", str(o.get("cpf_name") or "")).strip()
        cpf_ok = 0
        if len(cpf) in (11, 14) and cpf_nome:
            try:
                r_fiscal = salvar_cliente_fiscal(numero, cpf, cpf_nome, fonte="tiktok_api", usuario="api-tiktok",
                                                 so_se_vazio=True)
                cpf_ok = 1 if (r_fiscal.get("ok") or r_fiscal.get("ja_existia")) else 0
                fiscais += 1 if r_fiscal.get("ok") else 0
            except Exception as exc:
                tiktok_log_event_se_mudou("pedidos", f"cliente_fiscal {numero}", "ERRO", str(exc)[:300])
        else:
            # revisar-antes-de-subir (V20.40): sem o CPF (ou o nome da nota) o atendimento fica parado — registrado
            tiktok_log_event_se_mudou("pedidos", f"cpf {numero}", "AUSENTE", "a API não trouxe o CPF/nome da nota")
        with DB_LOCK:
            ja = DB.execute("SELECT venda_json FROM tiktok_sc_pedido_v2030 WHERE pedido=?", (numero,)).fetchone()
            venda_txt = json_dumps(venda) if venda else ""
            if erro and ja and str(ja["venda_json"] or "") and '"erro"' not in str(ja["venda_json"] or ""):
                venda_txt = ""  # revisar-antes-de-subir (V20.40): um erro passageiro não apaga o preço bom já lido
            DB.execute(
                """INSERT INTO tiktok_sc_pedido_v2030(pedido,nome,status,detalhe_em,visto_em,cpf_ok,venda_json,endereco_json)
                   VALUES(?,?,?,?,?,?,?,?)
                   ON CONFLICT(pedido) DO UPDATE SET status=excluded.status, visto_em=excluded.visto_em,
                       detalhe_em=excluded.detalhe_em, saiu_epoch=0,
                       nome=CASE WHEN excluded.nome<>'' THEN excluded.nome ELSE tiktok_sc_pedido_v2030.nome END,
                       cpf_ok=MAX(tiktok_sc_pedido_v2030.cpf_ok, excluded.cpf_ok),
                       venda_json=CASE WHEN excluded.venda_json<>'' THEN excluded.venda_json ELSE tiktok_sc_pedido_v2030.venda_json END,
                       endereco_json=CASE WHEN excluded.endereco_json<>'' THEN excluded.endereco_json ELSE tiktok_sc_pedido_v2030.endereco_json END""",
                (numero, nome[:200], str(o.get("status") or ""), agora_iso, agora_iso, cpf_ok,
                 venda_txt, json_dumps(endereco) if endereco else ""))
            DB.commit()
    agora = time.time()
    with DB_LOCK:
        for numero, status in (relidos or {}).items():
            if numero in ids:
                continue
            DB.execute("""INSERT INTO tiktok_sc_pedido_v2030(pedido,status,visto_em,saiu_epoch) VALUES(?,?,?,?)
                          ON CONFLICT(pedido) DO UPDATE SET status=excluded.status,
                              saiu_epoch=CASE WHEN excluded.saiu_epoch>0 THEN excluded.saiu_epoch ELSE tiktok_sc_pedido_v2030.saiu_epoch END""",
                       (numero, status, agora_iso, agora if status in TIKTOK_SC_SAIU else 0))
        DB.commit()
    return {"pedidos": len(ids), "fiscais": fiscais, "relidos": len(relidos or {})}


def _tiktok_sc_guardado(pedido: str) -> dict[str, Any]:
    with DB_LOCK:
        row = DB.execute("SELECT venda_json, endereco_json FROM tiktok_sc_pedido_v2030 WHERE pedido=?",
                         (str(pedido),)).fetchone()
    saida: dict[str, Any] = {"venda": None, "endereco": None}
    if row:
        for chave, col in (("venda", "venda_json"), ("endereco", "endereco_json")):
            try:
                saida[chave] = json.loads(row[col]) if row[col] else None
            except (TypeError, ValueError):
                saida[chave] = None
    return saida


def tiktok_atendimento_do_pedido(pedido: str) -> dict[str, Any] | None:
    with DB_LOCK:
        row = DB.execute("SELECT * FROM tiktok_atendimento_v2033 WHERE pedido=?", (str(pedido),)).fetchone()
    return dict(row) if row else None


def _tiktok_atendimento_registrar(pedido: str, situacao: str, detalhe: str, *, espera: str = "",
                                  cliente: str = "", atendimento: str = "", valor: float | None = None,
                                  itens: Any = None) -> None:
    proxima = time.time() + TIKTOK_ATEND_ESPERA[espera] if espera else 0.0
    with DB_LOCK:
        DB.execute(
            """INSERT INTO tiktok_atendimento_v2033(pedido,situacao,detalhe,cliente,atendimento,valor,itens_json,
                   tentativas,proxima_epoch,atualizado_em) VALUES(?,?,?,?,?,?,?,1,?,?)
               ON CONFLICT(pedido) DO UPDATE SET situacao=excluded.situacao, detalhe=excluded.detalhe,
                   cliente=CASE WHEN excluded.cliente<>'' THEN excluded.cliente ELSE tiktok_atendimento_v2033.cliente END,
                   atendimento=CASE WHEN excluded.atendimento<>'' THEN excluded.atendimento ELSE tiktok_atendimento_v2033.atendimento END,
                   valor=COALESCE(excluded.valor, tiktok_atendimento_v2033.valor),
                   itens_json=CASE WHEN excluded.itens_json<>'' THEN excluded.itens_json ELSE tiktok_atendimento_v2033.itens_json END,
                   tentativas=tiktok_atendimento_v2033.tentativas+1, proxima_epoch=excluded.proxima_epoch,
                   atualizado_em=excluded.atualizado_em""",
            (str(pedido), situacao, str(detalhe or "")[:500], cliente, atendimento, valor,
             json_dumps(itens) if itens is not None else "", proxima, now_iso()))
        DB.commit()


# ---------------------------------------------------------------------------
# V20.43 — peças do atendimento COMPROMETIDAS (dono, 09/11: "o atendimento balcão precisa cair comprometido").
# A porta `atendimento/criar` só abre o atendimento e insere as peças; quem compromete é a porta nova do
# Guilherme, `atendimento/comprometer {revenda, operador, contato}` (idempotente: relê antes; tudo já comprometido
# = `ja_comprometido` sem chamar o Apollo; cada item diz `comprometido` e o `motivo` quando não). Chamada logo
# depois do `criar` (criado ou ja_existia) e, se não comprometeu tudo, de novo nas voltas seguintes (até
# TIKTOK_COMP_MAX vezes) — nunca o `criar` de novo. Só "sim" com prova (tudo comprometido ou `ja_comprometido`);
# sem a prova a peça conta como sem atendimento no estoque (o lado seguro). O painel mostra e tem o botão.
# ---------------------------------------------------------------------------
TIKTOK_COMP_MAX = 5
TIKTOK_COMP_ESPERA = {"passageiro": 120, "incerto": 600, "erro": 1800, "parcial": 3600, "nao": 3600}


def _tiktok_comp_registrar(pedido: str, estado: str, detalhe: str, itens: Any = None, espera: str = "") -> None:
    proxima = time.time() + TIKTOK_COMP_ESPERA[espera] if espera else 0.0
    with DB_LOCK:
        DB.execute("UPDATE tiktok_atendimento_v2033 SET comprometido=?, comp_detalhe=?, "
                   "comp_itens_json=CASE WHEN ?<>'' THEN ? ELSE comp_itens_json END, "
                   "comp_tentativas=comp_tentativas+?, comp_proxima=?, atualizado_em=? WHERE pedido=?",
                   (estado, str(detalhe or "")[:500], json_dumps(itens) if itens is not None else "",
                    json_dumps(itens) if itens is not None else "", 0 if estado == "comprometendo" else 1,
                    proxima, now_iso(), str(pedido)))
        DB.commit()


def tiktok_atendimento_comprometer(pedido: str) -> dict[str, Any]:
    """Compromete as peças do atendimento do TikTok já criado. Grava o resultado; nunca levanta."""
    pedido = str(pedido).strip()
    atual = tiktok_atendimento_do_pedido(pedido) or {}
    contato = re.sub(r"\D", "", str(atual.get("atendimento") or ""))
    if str(atual.get("situacao") or "") not in TIKTOK_ATEND_FINAIS or not contato:
        return {"ok": False, "comprometido": "", "motivo": "sem atendimento criado"}
    corpo = {"revenda": _exp_revenda(pedido), "operador": "noromak", "contato": int(contato)}
    with EXP_PORTA_LOCK:
        try:
            r = _exp_porta("atendimento/comprometer", corpo, escrita=True)
        except PortaErro as exc:
            # Idempotente: o incerto (resposta perdida) e o "ocupado" são tentados de novo sozinhos.
            estado = "incerto" if exc.incerto else "erro"
            espera = "passageiro" if exc.passageiro else ("incerto" if exc.incerto else "erro")
            _tiktok_comp_registrar(pedido, estado, "Comprometer: " + str(exc), espera=espera)
            tiktok_log_event_se_mudou("atendimento", f"{pedido} comprometer", estado.upper(), str(exc)[:300])
            return {"ok": False, "comprometido": estado, "motivo": str(exc)}
    _tiktok_guardar_amostra("porta atendimento/comprometer", r)
    situacao = str(r.get("situacao") or "")
    itens = [i for i in (r.get("itens") or []) if isinstance(i, dict)]
    faltam = [f"{i.get('codigo') or i.get('item') or '?'}: {i.get('motivo') or 'não comprometeu'}"
              for i in itens if i.get("comprometido") is not True]
    if r.get("ok") is True and (situacao == "ja_comprometido" or (itens and not faltam)):
        estado, espera, detalhe = "sim", "", "Peças comprometidas no Apollo."
    elif r.get("ok") is True and faltam:
        estado, espera = "parcial", "parcial"
        detalhe = "Peças NÃO comprometidas: " + "; ".join(faltam)
    else:
        estado, espera = "nao", "nao"
        detalhe = "Não comprometido: " + str(r.get("erro") or r.get("mensagem") or situacao or "o Apollo não confirmou")
    tentativas = int(atual.get("comp_tentativas") or 0) + 1
    if estado != "sim" and tentativas >= TIKTOK_COMP_MAX:
        detalhe += " — comprometa no Apollo ou pelo botão do painel."
    _tiktok_comp_registrar(pedido, estado, detalhe, itens=itens or None, espera=espera)
    audit("automatico", "tiktok.atendimento_comprometer", f"{pedido}|{contato}|{estado}")
    tiktok_log_event_se_mudou("atendimento", f"{pedido} comprometer", "OK" if estado == "sim" else estado.upper(),
                              detalhe[:300])
    return {"ok": estado == "sim", "comprometido": estado, "motivo": detalhe}


def _tiktok_comp_candidatos() -> list[str]:
    """Atendimentos criados cujas peças ainda não estão comprometidas, com a vez chegada, o pedido ainda na fila e
    sem romaneio/caixa (com romaneio solto o atendimento já seguiu: comprometer não serve mais)."""
    with DB_LOCK:
        bruto, _, _ = get_storage("conf_pedidos")
        rows = DB.execute(
            "SELECT pedido FROM tiktok_atendimento_v2033 WHERE situacao IN ('criado','ja_existia') AND atendimento<>'' "
            "AND comprometido NOT IN ('sim','comprometendo') AND comp_tentativas<? AND comp_proxima<=? "
            "ORDER BY comp_proxima", (TIKTOK_COMP_MAX, time.time())).fetchall()
    na_fila = _tiktok_sc_pedidos_na_fila(_rows_from_storage_value(bruto))
    return [r["pedido"] for r in rows if r["pedido"] in na_fila and not _tiktok_atendimento_ja_atendido(r["pedido"])]


# Situações em que a rotina não mexe mais no pedido ("anterior" = atendido à mão; "fora_da_fila" = saiu sem atendimento).
TIKTOK_ATEND_PARADOS = TIKTOK_ATEND_FINAIS + ("anterior", "fora_da_fila")


def _tiktok_atendimento_ja_atendido(pedido: str) -> bool:
    """revisar-antes-de-subir (06/11): romaneio ou caixa já registrados (painel/Faturamento) = o pedido já tem
    atendimento no Apollo, aberto à mão (sem a chave TIKTOK-<pedido>); criar outro duplicaria venda e estoque."""
    # 2ª revisão (06/11): qualquer tentativa de romaneio/caixa com número de atendimento (inclusive erro/incerto)
    # prova que o atendimento existe — todo soltar exige o número.
    estado = _exp_estado_operacoes(pedido)
    return any(o.get("etapa") in ("romaneio", "caixa") and str(o.get("contato") or "").strip()
               for o in estado["operacoes"])


def _tiktok_atendimento_candidatos() -> list[str]:
    """Pedidos do TikTok na fila (pendentes) que ainda não têm atendimento e cuja vez chegou.
    revisar-antes-de-subir (06/11): só os que o TikTok ainda diz "a enviar" (cancelado/enviado com peça bipada fica
    na fila com o aviso, e não ganha atendimento)."""
    with DB_LOCK:
        bruto, _, _ = get_storage("conf_pedidos")
        estados = {r["pedido"]: dict(r) for r in DB.execute(
            "SELECT pedido, situacao, proxima_epoch FROM tiktok_atendimento_v2033")}
        situacao_tt = {r["pedido"]: (str(r["status"] or ""), float(r["saiu_epoch"] or 0)) for r in DB.execute(
            "SELECT pedido, status, saiu_epoch FROM tiktok_sc_pedido_v2030")}
    agora = time.time()
    saida: list[str] = []
    for numero in sorted(_tiktok_sc_pedidos_na_fila(_rows_from_storage_value(bruto))):
        e = estados.get(numero) or {}
        parado = e.get("situacao") in TIKTOK_ATEND_PARADOS and e.get("situacao") != "fora_da_fila"  # voltou à fila
        if parado or float(e.get("proxima_epoch") or 0) > agora:
            continue
        status, saiu = situacao_tt.get(numero, ("", 0.0))
        if status not in TIKTOK_SC_NA_FILA or saiu:
            continue
        if _tiktok_atendimento_ja_atendido(numero):
            _tiktok_atendimento_registrar(numero, "anterior", "Já tem romaneio/caixa pelo painel: atendimento à mão.")
            continue
        saida.append(numero)
    return saida


def _tiktok_marcar_fora_da_fila(na_fila: set[str] | None = None) -> int:
    """revisar-antes-de-subir (06/11): pedido do TikTok (lido depois de ligar) que saiu da fila sem atendimento — concluído
    antes de chegar o CPF, por exemplo — fica no cartão ("crie à mão"), em vez de sumir calado.
    2ª revisão: a fila (qualquer origem) e a tabela são lidas na MESMA vez do DB_LOCK (a extensão grava as duas);
    sem a data de ligar não marca nada; o pedido que volta à fila volta a ser candidato."""
    desde = _tiktok_config_ler("atendimento_ligado_em") or ""
    if not desde:
        return 0
    with DB_LOCK:
        if na_fila is None:
            bruto, _, _ = get_storage("conf_pedidos")
            na_fila = {str(order_number(r) or "").strip() for r in _rows_from_storage_value(bruto) if isinstance(r, dict)}
        rows = DB.execute(
            "SELECT s.pedido FROM tiktok_sc_pedido_v2030 s LEFT JOIN tiktok_atendimento_v2033 a ON a.pedido=s.pedido "
            "WHERE a.pedido IS NULL AND s.status NOT IN ('CANCELLED','IN_TRANSIT','DELIVERED','COMPLETED') "
            "AND s.saiu_epoch=0 AND s.visto_em>=?", (desde,)).fetchall()
    n = 0
    for r in rows:
        if r["pedido"] not in na_fila:
            _tiktok_atendimento_registrar(r["pedido"], "fora_da_fila",
                                          "Saiu da fila sem atendimento no Apollo: crie à mão se a venda vai ser faturada.")
            n += 1
    return n


def _tiktok_atendimento_custo(codigo: str, ctx: dict[str, Any]) -> float | None:
    """Custo de UMA unidade da peça (Araçatuba, regra do Financeiro). Separado para o teste."""
    custo, _ = _financeiro_custo_aracatuba(codigo, ctx)
    return custo


def _tiktok_atendimento_dividir(total_cent: int, pecas: list[tuple[str, int, float]]) -> list[int]:
    """Centavos por unidade de cada peça: proporção do peso (custo); o centavo que sobra vai numa
    peça cuja quantidade divide a sobra (de preferência a de 1 unidade e maior peso). Pode sobrar
    menos que a menor quantidade (aceito: o valor esperado é a soma do que vai)."""
    soma_peso = sum(n * p for _, n, p in pecas)
    cent = [int(total_cent * p / soma_peso) for _, n, p in pecas]
    sobra = total_cent - sum(c * n for c, (_, n, _) in zip(cent, pecas))
    ordem = sorted(range(len(pecas)), key=lambda k: (pecas[k][1] != 1, -pecas[k][2]))
    while sobra > 0:
        k = next((k for k in ordem if pecas[k][1] <= sobra and sobra % pecas[k][1] == 0), None)
        if k is None:
            k = next((k for k in ordem if pecas[k][1] <= sobra), None)
            if k is None:
                break
        passo = sobra // pecas[k][1]
        cent[k] += passo
        sobra -= passo * pecas[k][1]
    return cent


def _tiktok_vinculos() -> dict[str, str]:
    """Vínculo à mão do TikTok (V19.64): sku_id → códigos ("A/B"). Vence o SKU do vendedor."""
    with DB_LOCK:
        return {str(r["sku_id"]): str(r["codigos"] or "") for r in DB.execute(
            "SELECT sku_id, codigos FROM tiktok_vinculo_v1964 WHERE codigos<>''")}


def _tiktok_atendimento_pecas_do_sku(it: dict[str, Any], catalogo: dict[str, Any], conhecidos: Any,
                                     confirmadas: frozenset[str], vinculos: dict[str, str]
                                     ) -> tuple[list[tuple[str, int]], dict[str, Any] | None]:
    """Peças de UMA unidade do SKU vendido. Vínculo à mão vence; SKU cortado (V20.08) e SKU com cara de dois códigos
    sem Cadastro de Kits = revisar (o atendimento sairia sem peça)."""
    sku = str(it.get("sku") or "").strip()
    vinculo = vinculos.get(str(it.get("sku_id") or ""))
    if vinculo:
        return [(c, u) for c, u in _tiktok_pecas(vinculo)], None
    if len(sku) >= TIKTOK_SKU_LIMITE:
        raise TikTokAtendRevisar(f"SKU {sku} veio cortado pelo TikTok (limite de {TIKTOK_SKU_LIMITE} caracteres): faça o "
                                 f"vínculo à mão na tela Estoque TikTok para o atendimento sair com todas as peças.")
    partes, comp = _anuncio_sku_partes(sku, catalogo, conhecidos, confirmadas)
    miolo = re.sub(r"^KIT\d*-", "", normalize(sku))
    if not comp and anuncio_sku_parece_kit(miolo) and normalize(sku) not in confirmadas \
            and miolo not in confirmadas:
        raise TikTokAtendRevisar(f"SKU {sku} parece dois códigos juntos: cadastre o kit (Plataforma de anúncios → "
                                 f"Peça · Kit) para o atendimento sair com todas as peças.")
    return [(str(c).strip(), int(u)) for c, u in partes if str(c).strip() and int(u) > 0], comp


def _tiktok_atendimento_conferir_fila(pedido: str, venda: dict[str, Any], linhas: list[dict[str, Any]]) -> None:
    """revisar-antes-de-subir (06/11): o atendimento só sai se as peças da FILA (com as exclusões e alterações do
    ADMIN já aplicadas pelo get_storage) baterem com as do TikTok. Linha excluída, SKU/quantidade mudados pelo ADMIN
    ou fila desatualizada = revisar (a decisão do ADMIN vence a integração; ninguém adivinha qual vale)."""
    catalogo = _load_kit_catalog()
    confirmadas = _anuncio_pecas_confirmadas()
    conhecidos = _anuncios_conhecidos_lazy()
    vinculos = _tiktok_vinculos()
    por_sku = {normalize(i.get("sku")): i for i in venda.get("itens") or []}

    def somar(destino: dict[str, int], pecas: list[tuple[str, int]], vezes: int) -> None:
        for codigo, unidades in pecas:
            chave = _exp_norm_codigo(codigo)
            destino[chave] = destino.get(chave, 0) + unidades * vezes

    esperado: dict[str, int] = {}
    for it in venda.get("itens") or []:
        somar(esperado, _tiktok_atendimento_pecas_do_sku(it, catalogo, conhecidos, confirmadas, vinculos)[0],
              int(it.get("qtd") or 0))
    na_fila: dict[str, int] = {}
    for row in linhas:
        qtd = max(0, _tiktok_quantidade(row.get("Quantidade")) or 0)
        if str(row.get("__uidLinha") or "").upper().startswith("KITDB_"):
            somar(na_fila, [(str(row.get("SKU") or ""), 1)], qtd)
            continue
        # 2ª revisão (06/11): pelo SKU ATUAL da linha. O ADMIN que troca o SKU deixa o do TikTok em
        # SkuOrigemImportacao; procurar por ele contava a peça do TikTok dos dois lados e deixava passar.
        it = por_sku.get(normalize(row.get("SKU")))
        if it is not None:
            pecas = _tiktok_atendimento_pecas_do_sku(it, catalogo, conhecidos, confirmadas, vinculos)[0]
        else:
            pecas = _anuncio_sku_partes(row.get("SKU"), catalogo, conhecidos, confirmadas)[0]
        somar(na_fila, pecas, qtd)
    esperado = {k: v for k, v in esperado.items() if k and v}
    na_fila = {k: v for k, v in na_fila.items() if k and v}
    if esperado != na_fila:
        raise TikTokAtendRevisar("As peças da fila não batem com as do TikTok (linha excluída ou alterada pelo ADMIN, "
                                 "ou cancelamento ainda não lido). Confira o pedido e crie o atendimento à mão.")


def _tiktok_atendimento_itens(venda: dict[str, Any]) -> list[dict[str, Any]]:
    """Itens do atendimento: SKU do TikTok aberto em peças (vínculo à mão / Cadastro de Kits / "KITn-X" / "A/B"),
    preço do kit dividido pelo custo. SKU cortado ou com cara de dois códigos sem Cadastro de Kits = revisar."""
    catalogo = _load_kit_catalog()
    confirmadas = _anuncio_pecas_confirmadas()
    conhecidos = _anuncios_conhecidos_lazy()
    vinculos = _tiktok_vinculos()
    ctx: dict[str, Any] | None = None
    saida: list[dict[str, Any]] = []
    for it in venda.get("itens") or []:
        sku = str(it.get("sku") or "").strip()
        qtd = int(it.get("qtd") or 0)
        total_cent = int(round(float(it.get("valor") or 0) * 100))
        if not sku or qtd <= 0:
            continue
        if total_cent <= 0:
            raise TikTokAtendRevisar(f"SKU {sku} sem valor de venda.")
        partes, _ = _tiktok_atendimento_pecas_do_sku(it, catalogo, conhecidos, confirmadas, vinculos)
        if not partes:
            raise TikTokAtendRevisar(f"SKU {sku} sem código do Apollo.")
        if len(partes) == 1:
            codigo, por = partes[0]
            n = por * qtd
            pecas = [(codigo, n, 1.0)]
        else:
            if ctx is None:
                ctx = _financeiro_custos_aracatuba(com_vendas_ml=False)
            pecas = []
            for codigo, por in partes:
                custo = _tiktok_atendimento_custo(codigo, ctx)
                if not custo or custo <= 0:
                    raise TikTokAtendRevisar(f"Peça {codigo} do kit {sku} sem custo de Araçatuba: sem ele o preço do "
                                             f"kit não é dividido. Digite o custo (Demanda de Compra) ou confira.")
                pecas.append((codigo, por * qtd, float(custo)))
        cents = _tiktok_atendimento_dividir(total_cent, pecas)
        for (codigo, n, _), c in zip(pecas, cents):
            if c <= 0:
                raise TikTokAtendRevisar(f"Peça {codigo} do SKU {sku} ficaria sem valor.")
            saida.append({"codigo": codigo, "quantidade": n, "unitario": round(c / 100, 2)})
    if not saida:
        raise TikTokAtendRevisar("Pedido sem peça a enviar.")
    return saida


def tiktok_atendimento_pedido(pedido: str) -> dict[str, Any]:
    """Cadastro do cliente e atendimento de UM pedido do TikTok. Grava o estado; nunca levanta."""
    pedido = str(pedido).strip()
    conhecido = _exp_cliente_do_pedido(pedido)
    if not conhecido["documento"] or not conhecido["nome_fiscal"]:
        return {"ok": False, "situacao": "aguardando", "motivo": "sem nome/CPF da nota"}  # espera o detalhe
    guardado = _tiktok_sc_guardado(pedido)
    venda = guardado["venda"]
    if not venda:
        return {"ok": False, "situacao": "aguardando", "motivo": "sem o preço do detalhe"}
    def revisar(exc: Exception) -> dict[str, Any]:
        _tiktok_atendimento_registrar(pedido, "revisar", str(exc), espera="revisar")
        tiktok_log_event_se_mudou("atendimento", pedido, "REVISAR", str(exc)[:300])
        return {"ok": False, "situacao": "revisar", "motivo": str(exc)}

    try:
        if venda.get("erro"):
            raise TikTokAtendRevisar("Preço: " + str(venda["erro"]) + ".")
        itens = _tiktok_atendimento_itens(venda)
    except TikTokAtendRevisar as exc:
        return revisar(exc)
    esperado = round(sum(i["quantidade"] * i["unitario"] for i in itens), 2)
    # 1) cadastro (cria se não existe), uma vez por pedido
    codigo = conhecido["codigo"]
    auto = cadastro_auto_do_pedido(pedido) or {}
    if auto.get("situacao") != "feito" or not codigo:
        end = guardado["endereco"] or {}
        r = exp_cadastro_atualizar(pedido, "automatico", endereco_texto=end.get("texto") or "",
                                   criar=True, bairro=end.get("bairro") or "")
        if not r.get("ok"):
            situacao = "incerto" if r.get("situacao") == "incerto" else "erro"
            detalhe = "Cadastro do cliente: " + str(r.get("error") or r.get("situacao") or "?")
            _tiktok_atendimento_registrar(pedido, situacao, detalhe, espera="cadastro")
            tiktok_log_event_se_mudou("atendimento", pedido, "ERRO", detalhe[:300])
            return {"ok": False, "situacao": situacao, "motivo": detalhe}
        codigo = str(r.get("cliente") or "")
        agora = time.time()
        _cadastro_auto_registrar(pedido, agora, agora, 1, "feito", "automático do TikTok", codigo)
    # 2) revisar-antes-de-subir (06/11): relê a fila AGORA (o cadastro leva tempo): o pedido ainda está lá, o TikTok
    # ainda diz "a enviar", ninguém soltou romaneio, e as peças da fila (com as decisões do ADMIN) batem com o TikTok.
    with DB_LOCK:
        bruto, _, _ = get_storage("conf_pedidos")
        # 2ª revisão (06/11): TODAS as linhas do pedido — a que o ADMIN acrescentou à mão também conta
        linhas = [r for r in _rows_from_storage_value(bruto) if isinstance(r, dict)
                  and str(order_number(r) or "").strip() == pedido]
        row_tt = DB.execute("SELECT status, saiu_epoch FROM tiktok_sc_pedido_v2030 WHERE pedido=?", (pedido,)).fetchone()
    if not linhas or not row_tt or str(row_tt["status"] or "") not in TIKTOK_SC_NA_FILA or float(row_tt["saiu_epoch"] or 0):
        return {"ok": False, "situacao": "aguardando", "motivo": "saiu da fila ou não está mais a enviar"}
    if _tiktok_atendimento_ja_atendido(pedido):
        _tiktok_atendimento_registrar(pedido, "anterior", "Já tem romaneio/caixa pelo painel: atendimento à mão.")
        return {"ok": False, "situacao": "anterior"}
    try:
        _tiktok_atendimento_conferir_fila(pedido, venda, linhas)
    except TikTokAtendRevisar as exc:
        return revisar(exc)
    # 3) atendimento (revenda pela conta do pedido: TikTok = Bauru)
    corpo = {"revenda": _exp_revenda(pedido), "operador": "noromak", "origem": TIKTOK_ATEND_ORIGEM,
             "pedido_externo": f"{TIKTOK_ATEND_ORIGEM}-{pedido}", "cliente": int(codigo),
             "condicao_pagamento": TIKTOK_ATEND_CONDICAO, "observacao": f"TikTok {pedido}",
             "valor_esperado": esperado, "itens": itens}
    with EXP_PORTA_LOCK:
        try:
            r = _exp_porta("atendimento/criar", corpo, escrita=True)
        except PortaErro as exc:
            situacao = "incerto" if exc.incerto else "erro"
            # A mesma chave nunca cria outro atendimento: o incerto é tentado de novo sozinho.
            _tiktok_atendimento_registrar(pedido, situacao, str(exc), cliente=codigo, valor=esperado, itens=itens,
                                          espera="passageiro" if exc.passageiro else ("incerto" if exc.incerto else "erro"))
            tiktok_log_event_se_mudou("atendimento", pedido, situacao.upper(), str(exc)[:300])
            return {"ok": False, "situacao": situacao, "motivo": str(exc)}
    _tiktok_guardar_amostra("porta atendimento/criar", r)
    situacao = str(r.get("situacao") or "")
    numero = re.sub(r"\D", "", str(r.get("atendimento") or ""))
    if not r.get("ok") or situacao not in TIKTOK_ATEND_FINAIS or not numero:
        motivo = str(r.get("erro") or r.get("mensagem") or situacao or "o Apollo não confirmou")
        textos = {"sem_credito": "Cliente sem crédito liberado no Apollo", "sem_estoque": "Peça sem estoque no Apollo",
                  "item_nao_encontrado": "Peça não encontrada no Apollo", "preco_recusado": "O Apollo recusou o preço",
                  "valor_divergente": "O Apollo gravou outro valor", "cliente_nao_encontrado": "Cliente não encontrado no Apollo",
                  "apollo_fora": "Apollo fora do ar"}
        detalhe = f"{textos.get(situacao, 'Recusado')}: {motivo}"[:500]
        espera = "passageiro" if situacao == "apollo_fora" else "erro"
        estado_final = "erro"
        if situacao == "sem_credito":
            # revisar-antes-de-subir (06/11): o crédito não se resolve sozinho (o cadastro já está feito e não é
            # refeito); alguém libera pelo painel do pedido (Linx web) ou no Apollo, e a rotina tenta de novo em 1 h.
            estado_final, espera = "revisar", "revisar"
            detalhe = ("Crédito não liberado no Apollo: libere pelo painel do pedido (Liberar pelo Linx web) ou no Apollo. "
                       + motivo)[:500]
        _tiktok_atendimento_registrar(pedido, estado_final, detalhe, espera=espera, cliente=codigo, valor=esperado,
                                      itens=itens)
        tiktok_log_event_se_mudou("atendimento", pedido, estado_final.upper(), detalhe[:300])
        return {"ok": False, "situacao": estado_final, "motivo": detalhe}
    valor = _tiktok_num(r.get("valor"))
    detalhe = "Atendimento criado" if situacao == "criado" else "Atendimento já existia (mesma venda)"
    if valor is not None and abs(valor - esperado) > 0.009:
        detalhe += f" — ATENÇÃO: o Apollo gravou R$ {valor:.2f}".replace(".", ",") + \
                   f" e a venda é R$ {esperado:.2f}".replace(".", ",")
    _tiktok_atendimento_registrar(pedido, situacao, detalhe, cliente=codigo, atendimento=numero, valor=esperado,
                                  itens=itens)
    audit("automatico", "tiktok.atendimento", f"{pedido}|{numero}|{situacao}|{esperado:.2f}")
    tiktok_log_event_se_mudou("atendimento", pedido, "OK", detalhe[:300])
    # V20.43: em seguida, comprometer as peças (o criar não compromete). Falhar aqui não desfaz o atendimento:
    # fica registrado e a rotina tenta de novo só o comprometer.
    try:
        comp = tiktok_atendimento_comprometer(pedido)
    except Exception as exc:  # nunca derruba a criação já feita
        _tiktok_comp_registrar(pedido, "erro", "Comprometer: " + str(exc)[:300], espera="erro")
        comp = {"comprometido": "erro", "motivo": str(exc)}
    return {"ok": True, "situacao": situacao, "atendimento": numero, "valor": esperado,
            "comprometido": comp.get("comprometido"), "comprometido_motivo": comp.get("motivo")}


def tiktok_atendimento_rodada(forcar: bool = False) -> dict[str, Any]:
    if not tiktok_atendimento_ligado():
        return {"ok": True, "ligado": False, "feitos": 0}
    feitos = 0
    resultados = []
    try:
        _tiktok_marcar_fora_da_fila()
    except Exception as exc:  # aviso no cartão: falhar aqui não impede o atendimento
        tiktok_log_event_se_mudou("atendimento", "fora da fila", "ERRO", str(exc)[:300])
    for numero in _tiktok_atendimento_candidatos():
        if feitos >= TIKTOK_ATEND_POR_RODADA and not forcar:
            break
        try:
            r = tiktok_atendimento_pedido(numero)
        except Exception as exc:
            _tiktok_atendimento_registrar(numero, "erro", str(exc)[:300], espera="erro")
            r = {"ok": False, "situacao": "erro", "motivo": str(exc)}
        if r.get("situacao") != "aguardando":
            feitos += 1
            resultados.append({"pedido": numero, **r})
    # V20.43: atendimento criado e ainda sem as peças comprometidas — só o comprometer, na vaga que sobrou
    # (a porta aceita 6 escritas/min; um pedido por volta).
    for numero in _tiktok_comp_candidatos():
        if feitos >= TIKTOK_ATEND_POR_RODADA and not forcar:
            break
        try:
            r = tiktok_atendimento_comprometer(numero)
        except Exception as exc:
            _tiktok_comp_registrar(numero, "erro", "Comprometer: " + str(exc)[:300], espera="erro")
            r = {"ok": False, "comprometido": "erro", "motivo": str(exc)}
        feitos += 1
        resultados.append({"pedido": numero, "etapa": "comprometer", **r})
    return {"ok": True, "ligado": True, "feitos": feitos, "resultados": resultados}


def tiktok_atendimento_payload() -> dict[str, Any]:
    with DB_LOCK:
        linhas = [dict(r) for r in DB.execute(
            "SELECT pedido, situacao, detalhe, cliente, atendimento, valor, comprometido, comp_detalhe, atualizado_em "
            "FROM tiktok_atendimento_v2033 "
            "ORDER BY atualizado_em DESC LIMIT 30")]
    return {"ok": True, "ligado": tiktok_atendimento_ligado(), "pedidos": linhas}


# V20.37 (dono, 07/11, pedido 587022850875164046): com o automático desligado o painel do pedido não tinha como criar o
# atendimento. O botão "Criar atendimento no Apollo" roda para UM pedido a mesma criação da rotina
# (`tiktok_atendimento_pedido`: cadastro, conferência da fila, preço, kit e a porta `atendimento/criar`, que nunca cria dois
# para a mesma venda). Em segundo plano (a porta espera a vez; o nginx corta em 60 s); um por vez; a tela relê a situação.
_TIKTOK_ATEND_MANUAL_LOCK = threading.Lock()


def tiktok_atendimento_manual_iniciar(pedido: str, ator: str) -> dict[str, Any]:
    pedido = str(pedido or "").strip()
    if not pedido:
        raise ValueError("Informe o pedido.")
    with DB_LOCK:
        row = DB.execute("SELECT status, saiu_epoch FROM tiktok_sc_pedido_v2030 WHERE pedido=?", (pedido,)).fetchone()
    if row is None:
        raise ValueError("Este pedido não é do TikTok (ou a extensão ainda não leu o detalhe dele).")
    atual = tiktok_atendimento_do_pedido(pedido) or {}
    # V20.43: atendimento já criado e as peças ainda não comprometidas = o botão só compromete (nunca cria outro).
    so_comprometer = str(atual.get("situacao") or "") in TIKTOK_ATEND_FINAIS
    if so_comprometer and str(atual.get("comprometido") or "") == "sim":
        raise ValueError(f"O atendimento {atual.get('atendimento') or ''} já foi criado e as peças estão comprometidas.")
    if not _TIKTOK_ATEND_MANUAL_LOCK.acquire(blocking=False):
        return {"ok": False, "ocupado": True, "error": "Outro atendimento do TikTok está sendo criado. Aguarde e tente de novo."}
    try:
        if so_comprometer:
            _tiktok_comp_registrar(pedido, "comprometendo", f"Comprometendo pelo painel ({ator})…")
            audit(ator, "tiktok.atendimento_comprometer_manual", pedido)
        else:
            _tiktok_atendimento_registrar(pedido, "criando", f"Criando pelo painel ({ator})…")
            audit(ator, "tiktok.atendimento_manual", pedido)

        def rodar() -> None:
            try:
                if so_comprometer:
                    tiktok_atendimento_comprometer(pedido)
                    return
                r = tiktok_atendimento_pedido(pedido)
                if r.get("situacao") == "aguardando":  # nada foi feito: deixa o motivo na tela
                    _tiktok_atendimento_registrar(pedido, "revisar", "Não criado: " + str(r.get("motivo") or "aguardando"))
            except Exception as exc:
                if so_comprometer:
                    _tiktok_comp_registrar(pedido, "erro", "Comprometer: " + str(exc)[:300], espera="erro")
                else:
                    _tiktok_atendimento_registrar(pedido, "erro", str(exc)[:300], espera="erro")
            finally:
                _TIKTOK_ATEND_MANUAL_LOCK.release()
        threading.Thread(target=rodar, name=f"tiktok-atendimento-{pedido}", daemon=True).start()
    except BaseException:
        _TIKTOK_ATEND_MANUAL_LOCK.release()
        raise
    return {"ok": True, "iniciado": True, "atendimento_tiktok": tiktok_atendimento_do_pedido(pedido)}


def tiktok_atendimento_loop(stop_event: threading.Event) -> None:
    stop_event.wait(90)
    while not stop_event.is_set():
        try:
            tiktok_atendimento_rodada()
        except Exception as exc:
            tiktok_log_event_se_mudou("atendimento", "worker", "ERRO", str(exc)[:800])
        stop_event.wait(TIKTOK_ATEND_INTERVALO)


def tiktok_estoque_loop(stop_event: threading.Event) -> None:
    """Rodízio do Apollo (≤ 3/min) + refaz o estoque quando a fila muda; anúncios de hora em hora."""
    stop_event.wait(70)
    ultima_versao = -1
    ultimo_catalogo = 0.0
    while not stop_event.is_set():
        try:
            # V20.40: a API só lê os anúncios e grava o estoque com a fonte "api" (nunca junto com a extensão)
            if tiktok_status_payload().get("connected") and tiktok_fonte() == "api":
                if (time.monotonic() - ultimo_catalogo > 3600 or ultimo_catalogo == 0)                         and TIKTOK_CATALOGO_LOCK.acquire(blocking=False):  # V20.40: nunca junto com o botão
                    try:
                        tiktok_produtos_sincronizar()
                        ultimo_catalogo = time.monotonic()
                    finally:
                        TIKTOK_CATALOGO_LOCK.release()
                # V20.41: com a API o estoque é da plataforma de anúncios (Manual/Automático por anúncio, conta
                # 'tiktok' do anuncios_estoque_loop); aqui só o catálogo. Nada mais é enviado por esta rotina.
            elif time.time() - float(_tiktok_config_ler("extensao_lida_epoch") or 0) < TIKTOK_EXTENSAO_RECENTE \
                    and _tiktok_linhas_sku() and not apollo_lote_em_dia(tiktok=True):
                # V19.81: sem a API, as variações vêm da extensão; o rodízio do Apollo continua só
                # enquanto a extensão está em uso (o limite do Apollo é dividido com as outras telas).
                # V20.42: o lote do anuncios_estoque_loop relê os códigos do TikTok a cada minuto; o rodízio
                # só roda quando o lote não está em dia (reserva).
                tiktok_apollo_ler_proximo()
        except Exception as exc:
            tiktok_log_event_se_mudou("estoque", "worker", "ERRO", str(exc)[:800])
        stop_event.wait(20)


def shopee_api_get(path: str, params: dict[str, Any] | None = None, retry_auth: bool = True) -> dict[str, Any]:
    row = shopee_refresh_access_token(False)
    shop_id = str(row["shop_id"] or "").strip()
    access_token = str(row["access_token"] or "").strip()
    timestamp = int(time.time())
    query = {
        "partner_id": int(SHOPEE_PARTNER_ID),
        "timestamp": timestamp,
        "access_token": access_token,
        "shop_id": int(shop_id),
        "sign": shopee_sign(path, timestamp, access_token, shop_id),
    }
    if params:
        for key, value in params.items():
            if value is not None and value != "":
                query[key] = value
    url = SHOPEE_API_BASE + path + "?" + urlencode(query)
    req = urllib.request.Request(url, headers={"Accept": "application/json"}, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=25) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", "replace")
        if retry_auth and exc.code in (401, 403):
            shopee_refresh_access_token(True)
            return shopee_api_get(path, params, False)
        raise RuntimeError(f"Shopee API HTTP {exc.code}: {body[:700]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede na Shopee API: {exc.reason}")
    if not isinstance(data, dict):
        raise RuntimeError("Resposta inválida da Shopee API.")
    error = str(data.get("error") or "").strip()
    if error:
        auth_error = error.lower() in {"error_auth", "error_authentication", "invalid_access_token", "error_token"}
        if retry_auth and auth_error:
            shopee_refresh_access_token(True)
            return shopee_api_get(path, params, False)
        raise RuntimeError(f"Shopee API: {error} {data.get('message') or ''}".strip())
    return data



def shopee_api_post(path: str, payload: dict[str, Any] | None = None, retry_auth: bool = True) -> dict[str, Any]:
    row = shopee_refresh_access_token(False)
    shop_id = str(row["shop_id"] or "").strip()
    access_token = str(row["access_token"] or "").strip()
    timestamp = int(time.time())
    query = {"partner_id": int(SHOPEE_PARTNER_ID), "timestamp": timestamp,
             "access_token": access_token, "shop_id": int(shop_id),
             "sign": shopee_sign(path, timestamp, access_token, shop_id)}
    url = SHOPEE_API_BASE + path + "?" + urlencode(query)
    body = json.dumps(payload or {}).encode("utf-8")
    req = urllib.request.Request(url, data=body, headers={"Accept":"application/json","Content-Type":"application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=35) as resp:
            data = json.loads(resp.read().decode("utf-8", "replace") or "{}")
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", "replace")
        if retry_auth and exc.code in (401,403):
            shopee_refresh_access_token(True); return shopee_api_post(path, payload, False)
        raise RuntimeError(f"Shopee API HTTP {exc.code}: {raw[:700]}")
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de rede na Shopee API: {exc.reason}")
    if not isinstance(data, dict): raise RuntimeError("Resposta inválida da Shopee API.")
    if data.get("error"):
        err=str(data.get("error") or "")
        if retry_auth and err.lower() in {"error_auth","error_authentication","invalid_access_token","error_token"}:
            shopee_refresh_access_token(True); return shopee_api_post(path, payload, False)
        raise RuntimeError(f"Shopee API: {err} {data.get('message') or ''}".strip())
    return data


def shopee_api_post_bytes(path: str, payload: dict[str, Any]) -> tuple[bytes, str]:
    row=shopee_refresh_access_token(False); shop_id=str(row["shop_id"] or "").strip(); token=str(row["access_token"] or "").strip(); ts=int(time.time())
    q={"partner_id":int(SHOPEE_PARTNER_ID),"timestamp":ts,"access_token":token,"shop_id":int(shop_id),"sign":shopee_sign(path,ts,token,shop_id)}
    req=urllib.request.Request(SHOPEE_API_BASE+path+"?"+urlencode(q), data=json.dumps(payload).encode(), headers={"Accept":"*/*","Content-Type":"application/json"}, method="POST")
    with urllib.request.urlopen(req, timeout=45) as resp:
        return resp.read(), str(resp.headers.get("Content-Type") or "application/octet-stream")


def _shopee_logistics_order_list(shipments: list[dict[str,str]]) -> list[dict[str,str]]:
    return [{"order_sn":x["order_sn"], **({"package_number":x["package_number"]} if x.get("package_number") else {})} for x in shipments if x.get("order_sn")]


def _shopee_extract_zpl(raw: bytes) -> str:
    """Extrai ZPL de resposta direta ou ZIP da Shopee, quando disponível."""
    if not raw:
        return ""
    candidates: list[bytes] = [raw]
    if raw[:4] == b"PK\x03\x04":
        try:
            with zipfile.ZipFile(io.BytesIO(raw)) as zf:
                for name in zf.namelist():
                    if name.lower().endswith((".zpl", ".txt", ".prn")):
                        candidates.append(zf.read(name))
        except Exception:
            pass
    for blob in candidates:
        for enc in ("utf-8", "latin-1"):
            try:
                text = blob.decode(enc, errors="ignore")
            except Exception:
                continue
            pos = text.find("^XA")
            if pos >= 0 and "^XZ" in text[pos:]:
                # V17.99: a Shopee manda a etiqueta como uma imagem baixada por ~DG
                # ANTES do ^XA (o ^XA só imprime a imagem com ^XG). Cortar no ^XA
                # jogava a imagem fora e a etiqueta saía em branco.
                grafico = text.find("~DG")
                if 0 <= grafico < pos:
                    pos = grafico
                return text[pos:].strip()
    return ""


def shopee_reparar_etiquetas_sem_grafico() -> int:
    """V17.99: regrava as etiquetas Shopee vindas da API que ficaram sem a imagem
    (~DG), relendo o arquivo original salvo em shopee_labels. Idempotente: só mexe
    em etiqueta da API que manda imprimir uma imagem (^XG) que ela não carrega."""
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        return 0
    registros = bank.get("registros") if isinstance(bank, dict) else None
    if not isinstance(registros, dict):
        return 0
    labels_dir = DB_PATH.parent / "shopee_labels"
    reparadas = 0
    for rec in list(registros.values()):
        if not isinstance(rec, dict) or rec.get("origem") != "api_shopee":
            continue
        envio = str(rec.get("envio") or "")
        if "~DG" in envio or "^XG" not in envio:
            continue
        meta = rec.get("metadados") if isinstance(rec.get("metadados"), dict) else {}
        order_sn = str(meta.get("pedido") or rec.get("pedido") or "").strip()
        pkg = str(meta.get("package_number") or "").strip()
        if not order_sn:
            continue
        safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", order_sn + ("_" + pkg if pkg else ""))
        for ext in ("zip", "bin", "pdf"):
            arquivo = labels_dir / f"{safe}.{ext}"
            if not arquivo.exists():
                continue
            zpl = _shopee_extract_zpl(arquivo.read_bytes())
            if "~DG" in zpl and _shopee_store_linked_label(order_sn, pkg, zpl):
                reparadas += 1
                shopee_log_event("etiqueta_reparada", f"order={order_sn}", "OK", "imagem ~DG restaurada (V17.99)")
            break
    return reparadas


def _kit_e_residuo_prefixo(row: dict[str, Any]) -> bool:
    """V18.04: True se a linha é um produto SIMPLES que foi marcado como kit pelo
    bug do alias (kit KIT2-X vazando para a venda do X puro).

    Distingue do kit de verdade pelo SKU VENDIDO (SkuOrigemImportacao): num kit
    real ele é "KIT2-X" (mesmo com prefixo numérico do ML, ex.: 152285-KIT2-X);
    no resíduo é só o SKU simples (ex.: 152285-0893014105), sem "KIT".
    """
    if not isinstance(row, dict):
        return False
    sku_kit = str(row.get("SkuKitOrigem") or "").strip()
    if not re.match(r"^KIT\s*\d", sku_kit, re.I):
        return False
    if str(row.get("Kit") or "").upper() != "SIM" and not sku_kit:
        return False
    # V20.22: kit aberto pelo Cadastro de Kits/prefixo (Shopee e Magalu desde a V18.71,
    # Admin desde a V16.46) tem __uidLinha KITDB_ e o SkuOrigemImportacao é o SKU do
    # COMPONENTE, sem "KIT". Não é resíduo: o reparo de boot voltava o kit2 da Shopee para
    # 1 unidade a cada publicação (261104EF1BKBAP, 04/11).
    if str(row.get("__uidLinha") or "").upper().startswith("KITDB_"):
        return False
    for campo in ("SkuReferenciaShopee", "SkuPrincipalShopee"):
        if str(row.get(campo) or "").strip().upper().startswith("KIT"):
            return False
    origem = str(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or "").strip()
    if not origem:
        return False
    operacional = re.sub(r"^\d+-", "", origem, count=1)  # tira o prefixo numérico do ML
    if operacional.upper().startswith("KIT"):
        return False  # kit de verdade
    return True


def _kits_residuo_prefixo_reparar_rows(rows: Any) -> int:
    """Limpa o selo de kit das linhas de resíduo, in place. Retorna quantas mudaram.

    A quantidade correta é a quantidade vendida (Quantidade de Kits); os campos de
    kit são zerados para a tela parar de recalcular (Qtd de Kits × Qtd por Kit).
    """
    if not isinstance(rows, list):
        return 0
    mudou = 0
    for row in rows:
        if not _kit_e_residuo_prefixo(row):
            continue
        try:
            vendidas = max(1, int(float(row.get("Quantidade de Kits") or 1)))
        except Exception:
            vendidas = 1
        row["Quantidade"] = str(vendidas)
        row["Kit"] = ""
        row["Nome do Kit"] = ""
        row["Quantidade de Kits"] = ""
        row["Quantidade por Kit"] = ""
        row["SkuKitOrigem"] = ""
        mudou += 1
    return mudou


def reparar_kits_residuo_prefixo_v1803() -> int:
    """V18.04: reparo de boot para o resíduo do bug do kit-prefixo (V18.03).

    A sincronização do ML já corrige a QUANTIDADE, mas o merge preserva os campos
    de kit antigos, então a tela continua mostrando o dobro. Aqui grava DIRETO
    (sem passar pelo merge, que reporia o selo) só nas linhas de resíduo.
    Idempotente: depois de limpo, não acha mais nada.
    """
    row = DB.execute("SELECT value,version FROM storage WHERE key='conf_pedidos'").fetchone()
    if not row:
        return 0
    try:
        items = json.loads(str(row["value"] or "[]"))
    except Exception:
        return 0
    mudou = _kits_residuo_prefixo_reparar_rows(items)
    if mudou:
        DB.execute(
            "UPDATE storage SET value=?,version=?,updated_at=? WHERE key='conf_pedidos'",
            (json_dumps(items), int(row["version"] or 0) + 1, now_iso()),
        )
        DB.commit()
    return mudou


def _shopee_store_linked_label(order_sn: str, package_number: str, zpl: str) -> bool:
    """Vincula a etiqueta ZPL Shopee ao banco usado pela Expedição/Conferência."""
    order_sn = str(order_sn or "").strip()
    package_number = str(package_number or "").strip()
    if not order_sn or not str(zpl or "").strip():
        return False
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    if not isinstance(bank, dict):
        bank = {}
    bank["version"] = max(8, int(bank.get("version") or 0))
    bank.setdefault("registros", {})
    bank.setdefault("ordem", [])
    bank.setdefault("porChave", {})
    bank.setdefault("avisos", [])
    bank.setdefault("auditoria", [])
    bank.setdefault("resumo", {})
    bank.setdefault("vinculados", {})

    rid = "etq_shopee_api_" + hashlib.sha1((order_sn + "|" + package_number).encode("utf-8")).hexdigest()[:18]
    keys = [x for x in (order_sn, package_number) if x]
    record = {
        "id": rid,
        "marketplace": "shopee",
        "envio": zpl,
        "danfe": "",
        "arquivo": f"Shopee API · pedido {order_sn}",
        "metadados": {"pedido": order_sn, "package_number": package_number, "rastreio": "", "nf": "", "chaveAcesso": ""},
        "chaves": keys,
        "vinculadoA": [order_sn],
        "pedido": order_sn,
        "vinculo": "api_shopee_ready_to_print",
        "origem": "api_shopee",
        "adicionadaEm": now_iso(),
        "adicionadaPor": "shopee-api",
    }
    bank["registros"][rid] = record
    if rid not in bank["ordem"]:
        bank["ordem"].append(rid)
    bank["porChave"] = {}
    for record_id in bank["ordem"]:
        rec = bank["registros"].get(record_id)
        if not isinstance(rec, dict):
            continue
        for key in rec.get("chaves") or []:
            key = str(key or "").strip()
            if not key:
                continue
            bank["porChave"].setdefault(key, [])
            if record_id not in bank["porChave"][key]:
                bank["porChave"][key].append(record_id)
    bank["atualizadoEm"] = now_iso()
    if not any(isinstance(a, dict) and a.get("etiqueta") == rid for a in bank["auditoria"]):
        bank["auditoria"].append({"marketplace":"shopee","pedido":order_sn,"criterio":"api_ready_to_print","etiqueta":rid,"arquivo":record["arquivo"]})
        bank["auditoria"] = bank["auditoria"][-250:]
    save_storage("conf_etiquetas", raw, json_dumps(bank), False,
                 actor="shopee-api", actor_role="sistema",
                 source_screen="API Shopee", change_method="Etiqueta automática Shopee",
                 client_ip="127.0.0.1")
    return True


def _shopee_shipping_mode_payload(order_sn: str, package_number: str) -> tuple[dict[str, Any] | None, str, str]:
    """Consulta get_shipping_parameter e monta somente os campos exigidos por ship_order.

    Retorna (payload, modo, detalhe). payload=None significa que a modalidade exige
    um dado manual/externo que a integração não deve inventar.
    """
    q: dict[str, Any] = {"order_sn": order_sn}
    if package_number:
        q["package_number"] = package_number
    data = shopee_api_get("/api/v2/logistics/get_shipping_parameter", q)
    resp = data.get("response") if isinstance(data, dict) and isinstance(data.get("response"), dict) else {}
    info = resp.get("info_needed") if isinstance(resp.get("info_needed"), dict) else {}

    def _need(name: str) -> list[str]:
        value = info.get(name)
        if value is None and name == "non_integrated":
            value = info.get("non-integrated")
        if not isinstance(value, list):
            return []
        return [str(x or "").strip().lower() for x in value if str(x or "").strip()]

    pickup_need = _need("pickup")
    dropoff_need = _need("dropoff")
    nonint_need = _need("non_integrated")
    pickup_info = resp.get("pickup") if isinstance(resp.get("pickup"), dict) else {}
    dropoff_info = resp.get("dropoff") if isinstance(resp.get("dropoff"), dict) else {}
    pickup_addresses = pickup_info.get("address_list") if isinstance(pickup_info.get("address_list"), list) else []
    dropoff_branches = dropoff_info.get("branch_list") if isinstance(dropoff_info.get("branch_list"), list) else []
    dropoff_slugs = dropoff_info.get("slug_list") if isinstance(dropoff_info.get("slug_list"), list) else []

    # A Shopee define a modalidade pelos campos info_needed. Se a lista vier vazia,
    # a própria documentação exige ainda enviar o objeto da modalidade; nesse caso
    # inferimos pelo bloco de dados efetivamente retornado.
    mode = ""
    if pickup_need:
        mode = "pickup"
    elif dropoff_need:
        mode = "dropoff"
    elif nonint_need:
        mode = "non_integrated"
    elif pickup_addresses and not (dropoff_branches or dropoff_slugs):
        mode = "pickup"
    elif (dropoff_branches or dropoff_slugs) and not pickup_addresses:
        mode = "dropoff"
    elif isinstance(resp.get("pickup"), dict) and not isinstance(resp.get("dropoff"), dict):
        mode = "pickup"
    elif isinstance(resp.get("dropoff"), dict) and not isinstance(resp.get("pickup"), dict):
        mode = "dropoff"
    elif "pickup" in info and "dropoff" not in info:
        mode = "pickup"
    elif "dropoff" in info and "pickup" not in info:
        mode = "dropoff"
    elif "non_integrated" in info or "non-integrated" in info:
        mode = "non_integrated"

    base: dict[str, Any] = {"order_sn": order_sn}
    if package_number:
        base["package_number"] = package_number

    if mode == "pickup":
        # tracking_number em info_needed é um rastreio de terceiro a ser informado
        # antes do arrange; não é o tracking gerado pela Shopee depois de ship_order.
        if any(x in {"tracking_number", "tracking_no"} for x in pickup_need):
            return None, mode, "pickup exige tracking externo antes do arrange"
        addresses = [x for x in pickup_addresses if isinstance(x, dict)]
        chosen = None
        # Prefere endereço de coleta/default/current; se não houver flag, usa o primeiro válido.
        for addr in addresses:
            flags = [str(x or "").strip().lower() for x in (addr.get("address_flag") or addr.get("address_type") or []) if str(x or "").strip()]
            if any(x in {"pickup_address", "pick_up_address", "current_address", "default_address"} for x in flags):
                chosen = addr
                break
        if chosen is None and addresses:
            chosen = addresses[0]
        pickup_payload: dict[str, Any] = {}
        if chosen:
            aid = chosen.get("address_id")
            if aid not in (None, ""):
                try:
                    pickup_payload["address_id"] = int(aid)
                except Exception:
                    pickup_payload["address_id"] = aid
            slots = chosen.get("time_slot_list") if isinstance(chosen.get("time_slot_list"), list) else []
            valid_slots = [x for x in slots if isinstance(x, dict) and str(x.get("pickup_time_id") or "").strip()]
            selected_slot = None
            for slot in valid_slots:
                flags = [str(x or "").strip().lower() for x in (slot.get("flags") or [])]
                if "recommended" in flags:
                    selected_slot = slot
                    break
            if selected_slot is None and valid_slots:
                selected_slot = valid_slots[0]
            if selected_slot:
                pickup_payload["pickup_time_id"] = str(selected_slot.get("pickup_time_id") or "").strip()
        if "address_id" in pickup_need and not pickup_payload.get("address_id"):
            return None, mode, "pickup sem address_id disponível"
        # Alguns canais retornam pickup_time_id como necessário mas não ofertam slots;
        # a documentação permite arrange sem slot nesses casos. Portanto só enviamos se existir.
        base["pickup"] = pickup_payload
        return base, mode, f"pickup; needs={','.join(pickup_need) or '-'}; address={'sim' if pickup_payload.get('address_id') else 'nao'}; slot={'sim' if pickup_payload.get('pickup_time_id') else 'nao'}"

    if mode == "dropoff":
        if any(x in {"tracking_number", "tracking_no", "sender_real_name"} for x in dropoff_need):
            # Esses campos dependem de dado de transportadora/remetente externo e não
            # podem ser inventados automaticamente.
            return None, mode, f"dropoff exige dado manual: {','.join(dropoff_need)}"
        dropoff_payload: dict[str, Any] = {}
        if "branch_id" in dropoff_need:
            branches = [x for x in dropoff_branches if isinstance(x, dict) and x.get("branch_id") not in (None, "")]
            if not branches:
                return None, mode, "dropoff exige branch_id, mas não há branch disponível"
            bid = branches[0].get("branch_id")
            try:
                dropoff_payload["branch_id"] = int(bid)
            except Exception:
                dropoff_payload["branch_id"] = bid
        if "slug" in dropoff_need:
            slugs = [x for x in dropoff_slugs if isinstance(x, dict) and str(x.get("slug") or "").strip()]
            if not slugs:
                return None, mode, "dropoff exige slug, mas não há slug disponível"
            dropoff_payload["slug"] = str(slugs[0].get("slug") or "").strip()
        base["dropoff"] = dropoff_payload
        return base, mode, f"dropoff; needs={','.join(dropoff_need) or '-'}; branch={'sim' if dropoff_payload.get('branch_id') else 'nao'}; slug={'sim' if dropoff_payload.get('slug') else 'nao'}"

    if mode == "non_integrated":
        if nonint_need:
            return None, mode, f"canal não integrado exige dado manual: {','.join(nonint_need)}"
        base["non_integrated"] = {}
        return base, mode, "non_integrated sem parâmetro adicional"

    # Não escolhe pickup/dropoff arbitrariamente quando a Shopee não informa qual usar.
    keys = sorted(str(k) for k in resp.keys())
    return None, "indefinido", f"modalidade não identificada; response_keys={','.join(keys)}"


def _shopee_ship_order_cached(order_sn: str, package_number: str) -> tuple[bool, bool]:
    key = (str(order_sn or "").strip(), str(package_number or "").strip())
    now = time.time()
    with SHOPEE_SHIP_ORDER_CACHE_LOCK:
        # Limpa entradas antigas para o dicionário permanecer pequeno.
        stale = [k for k, ts in SHOPEE_SHIP_ORDER_CACHE.items() if now - float(ts or 0) > SHOPEE_SHIP_ORDER_CACHE_TTL]
        for k in stale:
            SHOPEE_SHIP_ORDER_CACHE.pop(k, None)
            SHOPEE_SHIP_ORDER_UNSPLIT_CACHE.discard(k)
        return key in SHOPEE_SHIP_ORDER_CACHE, key in SHOPEE_SHIP_ORDER_UNSPLIT_CACHE


def _shopee_forget_ship_order(order_sn: str, package_number: str) -> None:
    """V17.90 — descarta o "organizado" em cache de um pedido ainda sem rastreio."""
    key = (str(order_sn or "").strip(), str(package_number or "").strip())
    with SHOPEE_SHIP_ORDER_CACHE_LOCK:
        SHOPEE_SHIP_ORDER_CACHE.pop(key, None)
        SHOPEE_SHIP_ORDER_UNSPLIT_CACHE.discard(key)


def _shopee_mark_ship_order_cached(order_sn: str, package_number: str, *, unsplit: bool = False) -> None:
    key = (str(order_sn or "").strip(), str(package_number or "").strip())
    with SHOPEE_SHIP_ORDER_CACHE_LOCK:
        SHOPEE_SHIP_ORDER_CACHE[key] = time.time()
        if unsplit:
            SHOPEE_SHIP_ORDER_UNSPLIT_CACHE.add(key)
        else:
            SHOPEE_SHIP_ORDER_UNSPLIT_CACHE.discard(key)


def _shopee_package_not_needed_error(message: str) -> bool:
    # V17.89: a mensagem real da Shopee é
    #   "logistics.ship_order_not_need_pacakge_number Please don’t request with
    #    package_number for this unsplit order."
    # — "pacakge" com erro de digitação e apóstrofo tipográfico (’). Nenhuma das
    # comparações antigas batia, o fallback sem package_number nunca rodava e as
    # etiquetas Shopee pararam de sair sozinhas em 10/09/2026.
    low = str(message or "").lower().replace("’", "'").replace("‘", "'")
    return (
        bool(re.search(r"not_need_pa[a-z]{2,4}ge_number", low))
        or "request with package_number" in low
    )


def shopee_sync_shipping_documents(shipments: list[dict[str,str]],
                                   ja_organizados: set[str] | frozenset[str] = frozenset()) -> dict[str,Any]:
    """Organiza envio e processa etiquetas Shopee sem bloquear o request HTTP.

    V17.32: get_shipping_parameter -> ship_order -> get_tracking_number ->
    create_shipping_document -> get_shipping_document_result -> download/vínculo.
    Para pedidos unsplit, ship_order e tracking omitem package_number.
    O worker chama esta função; não existe polling síncrono no endpoint de sync.
    """
    summary={
        "consultados":0,"shipping_parameter_ok":0,"ship_order_ok":0,"ship_order_pendente":0,
        "tracking_ok":0,"tracking_pendente":0,"criados":0,"prontos":0,"baixados":0,
        "vinculados":0,"nao_zpl":0,"pendentes":0,"erros":0,"data_info_ok":0,
        "data_info_imagem":0,"aguardando":0,
    }
    orders=_shopee_logistics_order_list(shipments)
    if not orders:
        return summary

    labels_dir = DB_PATH.parent / "shopee_labels"
    labels_dir.mkdir(parents=True, exist_ok=True)

    def _key(row: dict[str,Any]) -> tuple[str,str]:
        return (str(row.get("order_sn") or "").strip(), str(row.get("package_number") or "").strip())

    def _safe_err(exc: Exception) -> str:
        return str(exc or "")[:900]

    def _parse_result_list(data: dict[str,Any]) -> list[dict[str,Any]]:
        resp=data.get("response") if isinstance(data,dict) and isinstance(data.get("response"),dict) else {}
        vals=resp.get("result_list") if isinstance(resp.get("result_list"),list) else []
        return [x for x in vals if isinstance(x,dict)]

    for off in range(0,len(orders),50):
        base_batch=orders[off:off+50]
        summary["consultados"] += len(base_batch)
        try:
            # Documento: descobre package_number e tipo sugerido antes de qualquer create.
            try:
                par=shopee_api_post("/api/v2/logistics/get_shipping_document_parameter", {"order_list":base_batch})
                presults=_parse_result_list(par)
            except Exception as exc:
                shopee_log_event("shipping_document_parameter","batch","ERRO",_safe_err(exc))
                summary["erros"] += len(base_batch)
                continue

            work: list[dict[str,Any]]=[]
            seen:set[tuple[str,str]]=set()
            for pr in presults:
                order_sn,pkg=_key(pr)
                if not order_sn:
                    continue
                ferr=str(pr.get("fail_error") or "").strip()
                if ferr:
                    summary["erros"] += 1
                    shopee_log_event("shipping_document_parameter",f"order={order_sn}","ERRO",f"erro={ferr}; msg={str(pr.get('fail_message') or '')[:450]}")
                    continue
                dtype=str(pr.get("suggest_shipping_document_type") or "").strip()
                selectable=pr.get("selectable_shipping_document_type")
                if not dtype and isinstance(selectable,list) and selectable:
                    dtype=str(selectable[0] or "").strip()
                k=(order_sn,pkg)
                if k in seen:
                    continue
                seen.add(k)
                row={"order_sn":order_sn}
                if pkg:
                    row["package_number"]=pkg
                if dtype:
                    row["shipping_document_type"]=dtype
                work.append(row)
                shopee_log_event("shipping_document_parameter",f"order={order_sn}","OK",f"pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")

            if not work:
                for src in base_batch:
                    order_sn,pkg=_key(src)
                    if not order_sn:
                        continue
                    row={"order_sn":order_sn}
                    if pkg:
                        row["package_number"]=pkg
                    work.append(row)

            for row in work:
                order_sn=str(row.get("order_sn") or "").strip()
                pkg=str(row.get("package_number") or "").strip()
                dtype=str(row.get("shipping_document_type") or "").strip()
                if not order_sn:
                    continue

                # 1) get_shipping_parameter -> 2) ship_order. Só pula o POST quando
                # este mesmo processo já recebeu confirmação recente para o pacote.
                arranged,unsplit_order=_shopee_ship_order_cached(order_sn,pkg)
                organizado_neste_ciclo=not arranged and order_sn not in ja_organizados
                # V17.91: pedido que não está mais na lista "a organizar" da Shopee
                # (get_shipment_list) já foi organizado — vai direto ao rastreio.
                if order_sn in ja_organizados:
                    arranged,unsplit_order=True,True
                if not arranged:
                    try:
                        ship_payload,mode,detail=_shopee_shipping_mode_payload(order_sn,pkg)
                        summary["shipping_parameter_ok"] += 1
                        shopee_log_event("shipping_parameter",f"order={order_sn}","OK",f"modo={mode}; pacote={'sim' if pkg else 'nao'}; {detail}")
                    except Exception as exc:
                        summary["erros"] += 1
                        summary["pendentes"] += 1
                        shopee_log_event("shipping_parameter",f"order={order_sn}","ERRO",_safe_err(exc))
                        continue

                    if not ship_payload:
                        summary["ship_order_pendente"] += 1
                        summary["pendentes"] += 1
                        shopee_log_event("ship_order",f"order={order_sn}","PENDENTE",f"modo={mode}; {detail}")
                        continue

                    try:
                        shopee_api_post("/api/v2/logistics/ship_order", ship_payload)
                        arranged=True
                        _shopee_mark_ship_order_cached(order_sn,pkg,unsplit=False)
                        summary["ship_order_ok"] += 1
                        shopee_log_event("ship_order",f"order={order_sn}","OK",f"modo={mode}; pacote={'sim' if pkg else 'nao'}")
                    except Exception as exc:
                        msg=_safe_err(exc)
                        low=msg.lower()
                        if "lack_of_invoice" in low:
                            summary["pendentes"] += 1
                            shopee_log_event("ship_order",f"order={order_sn}","PENDENTE","aguardando NF-e na Shopee; "+msg[:200])
                            continue
                        # Shopee devolve package_number no parâmetro de documento mesmo
                        # para pedidos UNSPLIT, mas ship_order rejeita esse campo. Nesse
                        # caso refazemos UMA vez sem package_number e lembramos o estado
                        # para que get_tracking_number também seja chamado sem o pacote.
                        if pkg and _shopee_package_not_needed_error(msg):
                            retry_payload=dict(ship_payload)
                            retry_payload.pop("package_number",None)
                            try:
                                shopee_api_post("/api/v2/logistics/ship_order", retry_payload)
                                arranged=True
                                unsplit_order=True
                                _shopee_mark_ship_order_cached(order_sn,pkg,unsplit=True)
                                summary["ship_order_ok"] += 1
                                shopee_log_event("ship_order",f"order={order_sn}","OK",f"modo={mode}; unsplit=sim; fallback_sem_package=sim")
                            except Exception as retry_exc:
                                retry_msg=_safe_err(retry_exc)
                                retry_low=retry_msg.lower()
                                # V17.91: "lack_of_invoice_data ... already submitted" contém
                                # "already" e era lido como "já organizado". É falta de NF-e.
                                if "lack_of_invoice" in retry_low:
                                    summary["pendentes"] += 1
                                    shopee_log_event("ship_order",f"order={order_sn}","PENDENTE","aguardando NF-e na Shopee; "+retry_msg[:200])
                                    continue
                                already_tokens=("already", "has been shipped", "already shipped", "already arrange", "already arranged", "logistics_request_created")
                                if any(tok in retry_low for tok in already_tokens):
                                    arranged=True
                                    unsplit_order=True
                                    _shopee_mark_ship_order_cached(order_sn,pkg,unsplit=True)
                                    summary["ship_order_ok"] += 1
                                    # V17.90: registra a mensagem real — em 18/09/2026 este "já
                                    # organizado" escondia a recusa da Shopee por falta de NF-e.
                                    shopee_log_event("ship_order",f"order={order_sn}","OK",f"já organizado; unsplit=sim; fallback_sem_package=sim; resposta={retry_msg[:240]}")
                                else:
                                    summary["erros"] += 1
                                    summary["pendentes"] += 1
                                    shopee_log_event("ship_order",f"order={order_sn}","ERRO",f"modo={mode}; fallback_sem_package=sim; {retry_msg}")
                                    continue
                        else:
                            # ship_order é uma transição de estado. Em restart do serviço,
                            # o pedido pode já estar organizado; esses retornos são idempotentes.
                            already_tokens=("already", "has been shipped", "already shipped", "already arrange", "already arranged", "logistics_request_created")
                            if any(tok in low for tok in already_tokens):
                                arranged=True
                                _shopee_mark_ship_order_cached(order_sn,pkg,unsplit=unsplit_order)
                                summary["ship_order_ok"] += 1
                                shopee_log_event("ship_order",f"order={order_sn}","OK",f"já organizado; pacote={'sim' if pkg else 'nao'}; resposta={msg[:240]}")
                            else:
                                summary["erros"] += 1
                                summary["pendentes"] += 1
                                shopee_log_event("ship_order",f"order={order_sn}","ERRO",f"modo={mode}; {msg}")
                                continue
                else:
                    shopee_log_event("ship_order",f"order={order_sn}","OK",f"cache=sim; unsplit={'sim' if unsplit_order else 'nao'}; pacote={'sim' if pkg else 'nao'}")

                # 3) O rastreio só é consultado depois do arrange confirmado.
                # Pedido UNSPLIT deve omitir package_number também nesta etapa.
                q={"order_sn":order_sn}
                if pkg and not unsplit_order:
                    q["package_number"]=pkg
                tracking=""
                hint=""
                # V18.62: logo após o ship_order o rastreio costuma levar alguns
                # segundos; uma segunda tentativa curta evita esperar o ciclo seguinte.
                for tentativa in range(2 if organizado_neste_ciclo else 1):
                    if tentativa:
                        time.sleep(SHOPEE_DOC_RESULT_RETRY_WAIT)
                    try:
                        tr=shopee_api_get("/api/v2/logistics/get_tracking_number", q)
                        tresp=tr.get("response") if isinstance(tr.get("response"),dict) else {}
                        tracking=str(tresp.get("tracking_number") or "").strip()
                        hint=str(tresp.get("hint") or "").strip()
                        # V17.91: pedido que chegou já organizado não sabe se é unsplit;
                        # sem rastreio consultando sem o pacote, tenta com o pacote.
                        if not tracking and pkg and "package_number" not in q:
                            tr=shopee_api_get("/api/v2/logistics/get_tracking_number", {"order_sn":order_sn,"package_number":pkg})
                            tresp=tr.get("response") if isinstance(tr.get("response"),dict) else {}
                            tracking=str(tresp.get("tracking_number") or "").strip()
                            hint=hint or str(tresp.get("hint") or "").strip()
                    except Exception as exc:
                        shopee_log_event("tracking_number",f"order={order_sn}","AVISO",_safe_err(exc))
                    if tracking:
                        break
                if tracking:
                    summary["tracking_ok"] += 1
                    shopee_log_event("tracking_number",f"order={order_sn}","OK",f"obtido=sim; pacote={'sim' if pkg and not unsplit_order else 'nao'}; unsplit={'sim' if unsplit_order else 'nao'}")
                else:
                    summary["tracking_pendente"] += 1
                    summary["pendentes"] += 1
                    summary["aguardando"] += 1
                    shopee_log_event("tracking_number",f"order={order_sn}","PENDENTE",f"obtido=nao; pacote={'sim' if pkg and not unsplit_order else 'nao'}; unsplit={'sim' if unsplit_order else 'nao'}; hint={hint[:300] or '-'}")
                    # O tracking pode ser emitido alguns minutos depois do ship_order.
                    # Worker tenta novamente no próximo ciclo; não faz polling aqui.
                    # V17.91: a falta de NF-e agora é tratada no ship_order (não entra
                    # mais no cache), e o pedido organizado segue no ciclo seguinte
                    # pela lista de pendentes sem etiqueta — não precisa esquecer aqui.
                    continue

                # 4) Cria documento somente com tracking disponível.
                create_row={"order_sn":order_sn,"tracking_number":tracking}
                if pkg:
                    create_row["package_number"]=pkg
                if dtype:
                    create_row["shipping_document_type"]=dtype
                create_ok=False
                create_soft=False
                try:
                    created=shopee_api_post("/api/v2/logistics/create_shipping_document", {"order_list":[create_row]})
                    crlist=_parse_result_list(created)
                    failures=[x for x in crlist if str(x.get("fail_error") or "").strip()]
                    if failures:
                        fr=failures[0]
                        ferr=str(fr.get("fail_error") or "").strip()
                        fmsg=str(fr.get("fail_message") or "")[:500]
                        if ferr in {"logistics.shipping_document_processing","logistics.shipping_document_already_exist","logistics.shipping_document_already_exists"}:
                            create_soft=True
                            shopee_log_event("shipping_document_create",f"order={order_sn}","OK",f"estado_existente={ferr}; pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")
                        else:
                            summary["erros"] += 1
                            summary["pendentes"] += 1
                            shopee_log_event("shipping_document_create",f"order={order_sn}","ERRO",f"erro={ferr}; msg={fmsg}; tracking=sim; pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")
                    else:
                        create_ok=True
                        summary["criados"] += 1
                        shopee_log_event("shipping_document_create",f"order={order_sn}","OK",f"tracking=sim; pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")
                except Exception as exc:
                    msg=_safe_err(exc)
                    low=msg.lower()
                    if "already" in low or "processing" in low:
                        create_soft=True
                        shopee_log_event("shipping_document_create",f"order={order_sn}","OK",f"estado_existente; pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")
                    else:
                        shopee_log_event("shipping_document_create",f"order={order_sn}","ERRO",f"{msg}; tracking=sim; pacote={'sim' if pkg else 'nao'}; doc={dtype or '-'}")
                        summary["erros"] += 1
                        summary["pendentes"] += 1

                # Regra crítica: nunca consulta result se create não foi confirmado.
                if not (create_ok or create_soft):
                    continue

                # 5) Consulta de status. V18.62: se ainda estiver gerando, espera
                # alguns segundos e consulta UMA vez mais; o resto fica para o worker.
                result_row={"order_sn":order_sn}
                if pkg:
                    result_row["package_number"]=pkg
                if dtype:
                    result_row["shipping_document_type"]=dtype
                rlist=[]
                result_exc=None
                for tentativa in range(2):
                    if tentativa:
                        time.sleep(SHOPEE_DOC_RESULT_RETRY_WAIT)
                    try:
                        result=shopee_api_post("/api/v2/logistics/get_shipping_document_result", {"order_list":[result_row]})
                        rlist=_parse_result_list(result)
                        result_exc=None
                    except Exception as exc:
                        rlist=[]
                        result_exc=exc
                        if "shipping_document_should_print_first" not in _safe_err(exc):
                            break
                        continue
                    st_tmp=str((rlist[0] if rlist else {}).get("status") or "").upper().strip()
                    ferr_tmp=str((rlist[0] if rlist else {}).get("fail_error") or "").strip()
                    if rlist and (ferr_tmp or st_tmp not in {"PROCESSING","PENDING",""}):
                        break
                if result_exc is not None:
                    msg=_safe_err(result_exc)
                    summary["pendentes"] += 1
                    if "shipping_document_should_print_first" in msg:
                        summary["aguardando"] += 1
                        shopee_log_event("shipping_document_result",f"order={order_sn}","AVISO",f"create confirmado neste ciclo, mas Shopee ainda não liberou result; {msg}")
                    else:
                        summary["erros"] += 1
                        shopee_log_event("shipping_document_result",f"order={order_sn}","ERRO",msg)
                    continue

                if not rlist:
                    summary["pendentes"] += 1
                    summary["aguardando"] += 1
                    shopee_log_event("shipping_document_result",f"order={order_sn}","PENDENTE","result_list vazio")
                    continue

                rr=rlist[0]
                st=str(rr.get("status") or "").upper().strip()
                ferr=str(rr.get("fail_error") or "").strip()
                fmsg=str(rr.get("fail_message") or "")[:500]
                if st=="READY":
                    summary["prontos"] += 1
                    shopee_log_event("shipping_document_result",f"order={order_sn}","OK",f"status=READY; doc={dtype or '-'}")
                    reqrow={"order_sn":order_sn}
                    if pkg:
                        reqrow["package_number"]=pkg
                    payload={"order_list":[reqrow]}
                    if dtype:
                        payload["shipping_document_type"]=dtype
                    try:
                        raw,ctype=shopee_api_post_bytes("/api/v2/logistics/download_shipping_document", payload)
                        if raw:
                            if raw.startswith(b"%PDF") or "pdf" in ctype.lower():
                                ext="pdf"
                            elif raw[:4]==b"PK\x03\x04":
                                ext="zip"
                            else:
                                ext="bin"
                            safe=re.sub(r"[^A-Za-z0-9_.-]+","_",order_sn+("_"+pkg if pkg else ""))
                            fp=labels_dir/f"{safe}.{ext}"
                            fp.write_bytes(raw)
                            summary["baixados"] += 1
                            zpl=_shopee_extract_zpl(raw)
                            if zpl and _shopee_store_linked_label(order_sn,pkg,zpl):
                                summary["vinculados"] += 1
                                state="VINCULADA_ZPL"
                            else:
                                summary["nao_zpl"] += 1
                                state="BAIXADA_SEM_ZPL"
                            shopee_log_event("shipping_document_download",f"order={order_sn}","OK",f"arquivo={fp.name}; bytes={len(raw)}; tipo={ctype[:80]}; doc={dtype}; estado={state}")
                    except Exception as exc:
                        summary["erros"] += 1
                        shopee_log_event("shipping_document_download",f"order={order_sn}","ERRO",_safe_err(exc))
                elif st in {"PROCESSING","PENDING",""} and not ferr:
                    summary["pendentes"] += 1
                    summary["aguardando"] += 1
                    shopee_log_event("shipping_document_result",f"order={order_sn}","PENDENTE",f"status={st or 'PROCESSING'}; doc={dtype or '-'}")
                    continue
                elif ferr or st=="FAILED":
                    summary["erros"] += 1
                    summary["pendentes"] += 1
                    shopee_log_event("shipping_document_result",f"order={order_sn}","ERRO",f"status={st or '-'}; erro={ferr or '-'}; msg={fmsg}")
                else:
                    summary["pendentes"] += 1

                # V18.62: o diagnóstico era uma chamada extra por pedido em todo ciclo,
                # inclusive com a etiqueta já baixada. Agora só roda quando algo falhou.
                if st=="READY":
                    continue
                # Diagnóstico por pedido; nunca bloqueia o fluxo principal se falhar.
                try:
                    dinfo_payload={"order_sn":order_sn}
                    if pkg:
                        dinfo_payload["package_number"]=pkg
                    info_data=shopee_api_post("/api/v2/logistics/get_shipping_document_data_info", dinfo_payload)
                    resp=info_data.get("response") if isinstance(info_data.get("response"),dict) else {}
                    if resp:
                        summary["data_info_ok"] += 1
                        def has_image(v):
                            if isinstance(v,dict):
                                return any(("image" in str(k).lower() and bool(x)) or has_image(x) for k,x in v.items())
                            if isinstance(v,list):
                                return any(has_image(x) for x in v)
                            return False
                        if has_image(resp):
                            summary["data_info_imagem"] += 1
                        keys=sorted(str(k) for k in resp.keys())
                        shopee_log_event("shipping_data_info",f"order={order_sn}","OK",f"chaves={','.join(keys)[:800]}; com_imagem={1 if has_image(resp) else 0}")
                except Exception as exc:
                    shopee_log_event("shipping_data_info",f"order={order_sn}","AVISO",_safe_err(exc))
        except Exception as exc:
            summary["erros"] += len(base_batch)
            shopee_log_event("shipping_documents","batch","ERRO",_safe_err(exc))
    return summary

def shopee_pedidos_sem_etiqueta(dias: int = 10, limite: int = 40) -> list[dict[str, str]]:
    """V17.91 — pedidos Shopee pendentes no Noromak que ainda não têm etiqueta
    vinculada no banco da Conferência. Só os recentes, para não varrer histórico."""
    corte = (datetime.now() - timedelta(days=dias)).strftime("%Y-%m-%d")
    with DB_LOCK:
        pendentes, _, _ = get_storage("conf_pedidos")
        etiquetas, _, _ = get_storage("conf_etiquetas")
    try:
        banco = json.loads(etiquetas or "{}")
    except Exception:
        banco = {}
    vinculados = set((banco.get("porChave") or {}).keys()) if isinstance(banco, dict) else set()
    candidatos: list[tuple[str, dict[str, str]]] = []
    vistos: set[str] = set()
    for row in _rows_from_storage_value(pendentes):
        if not isinstance(row, dict) or "SHOPEE" not in str(row.get("Marketplace") or "").upper():
            continue
        order_sn = str(row.get("Pedido") or "").strip()
        if not order_sn or order_sn in vistos or order_sn in vinculados:
            continue
        data = _vendas_data_iso(row.get("Data do Pedido"))
        if data < corte:
            continue
        vistos.add(order_sn)
        candidatos.append((data, {"order_sn": order_sn, "package_number": str(row.get("PacoteShopee") or "").strip()}))
    # V18.62: mais recentes primeiro. Antes o corte em `limite` seguia a ordem do
    # banco e pedidos travados (ex.: sem NF-e) deixavam o pedido novo de fora.
    candidatos.sort(key=lambda x: x[0], reverse=True)
    return [x for _, x in candidatos[:limite]]


def shopee_current_shipments() -> list[dict[str, str]]:
    """Lista o que realmente está aguardando expedição na Shopee.

    get_shipment_list é preferido aqui porque não depende de janela de 15 dias e
    retorna os pedidos/pacotes em READY_TO_SHIP/RETRY_SHIP.
    """
    path = "/api/v2/order/get_shipment_list"
    cursor = ""
    found: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for _ in range(30):
        params: dict[str, Any] = {"page_size": 100}
        if cursor:
            params["cursor"] = cursor
        data = shopee_api_get(path, params)
        response = data.get("response") if isinstance(data.get("response"), dict) else {}
        order_list = response.get("order_list") if isinstance(response.get("order_list"), list) else []
        for item in order_list:
            if not isinstance(item, dict):
                continue
            order_sn = str(item.get("order_sn") or "").strip()
            package_number = str(item.get("package_number") or "").strip()
            key = (order_sn, package_number)
            if order_sn and key not in seen:
                found.append({"order_sn": order_sn, "package_number": package_number})
                seen.add(key)
        if not bool(response.get("more")):
            break
        next_cursor = str(response.get("next_cursor") or "").strip()
        if not next_cursor or next_cursor == cursor:
            break
        cursor = next_cursor
    return found


# V20.14 (03/11): a get_shipment_list vem vazia desde 07:41 e pedido novo não entrava na fila
# (261103C3DHY4SQ, NF válida). Os pedidos "a enviar" também vêm da get_order_list (janela
# máxima de 15 dias da API, como as vendas); a sincronização junta as duas listas.
SHOPEE_A_ENVIAR_STATUS = ("READY_TO_SHIP", "RETRY_SHIP")
SHOPEE_A_ENVIAR_DIAS = 15


def shopee_pedidos_a_enviar() -> list[str]:
    agora = int(time.time())
    sns: list[str] = []
    for status in SHOPEE_A_ENVIAR_STATUS:
        cursor = ""
        for _ in range(30):
            params: dict[str, Any] = {"time_range_field": "create_time", "time_from": agora - SHOPEE_A_ENVIAR_DIAS * 86400,
                                      "time_to": agora, "page_size": 100, "order_status": status}
            if cursor:
                params["cursor"] = cursor
            resp = shopee_api_get("/api/v2/order/get_order_list", params).get("response") or {}
            for o in resp.get("order_list") or []:
                sn = str((o or {}).get("order_sn") or "").strip()
                if sn and sn not in sns:
                    sns.append(sn)
            proximo = str(resp.get("next_cursor") or "").strip()
            if not resp.get("more") or not proximo or proximo == cursor:
                break
            cursor = proximo
    return sns


def shopee_order_details(order_sns: list[str], campos: str = "") -> list[dict[str, Any]]:
    path = "/api/v2/order/get_order_detail"
    details: list[dict[str, Any]] = []
    unique = list(dict.fromkeys(str(x).strip() for x in order_sns if str(x).strip()))
    optional = campos or "recipient_address,item_list,package_list,shipping_carrier,invoice_data,buyer_cpf_id,buyer_cnpj_id,buyer_user_id,buyer_username,buyer_name,buyer_phone_number,address"
    for offset in range(0, len(unique), 50):
        batch = unique[offset:offset + 50]
        data = shopee_api_get(path, {
            "order_sn_list": ",".join(batch),
            "response_optional_fields": optional,
        })
        response = data.get("response") if isinstance(data.get("response"), dict) else {}
        rows = response.get("order_list") if isinstance(response.get("order_list"), list) else []
        details.extend(x for x in rows if isinstance(x, dict))
    return details


def _shopee_date(timestamp: Any) -> str:
    try:
        value = int(timestamp or 0)
        if value > 0:
            return datetime.fromtimestamp(value, timezone.utc).astimezone().strftime("%d/%m/%Y")
    except Exception:
        pass
    return datetime.now().astimezone().strftime("%d/%m/%Y")


def _shopee_build_pending_lines(order: dict[str, Any], package_numbers: list[str], products: list[dict[str, Any]]) -> list[dict[str, Any]]:
    order_sn = str(order.get("order_sn") or "").strip()
    if not order_sn:
        return []
    recipient = order.get("recipient_address") if isinstance(order.get("recipient_address"), dict) else {}
    address = order.get("address") if isinstance(order.get("address"), dict) else {}

    def _shopee_real_text(*values: Any) -> str:
        # A API pode devolver dados mascarados como ****. Não grava máscara como nome.
        for value in values:
            text = str(value or "").strip()
            if not text:
                continue
            visible = re.sub(r"[\s*•xX._-]+", "", text)
            if visible:
                return text
        return ""

    # Nome usado na expedição/NF-e: prioriza nome real. A Shopee BR está
    # mascarando recipient_address.name nesta conta; por solicitação operacional,
    # usa buyer_username apenas como fallback visível para permitir conferência
    # manual até que a API libere o nome fiscal completo.
    buyer_username = str(order.get("buyer_username") or "").strip()
    # V17.88: nome real separado do fallback. O nome de usuário continua
    # servindo para a coluna Cliente, mas NUNCA como nome fiscal — ele ia para
    # o cadastro do Linx como se fosse o nome da nota.
    shopee_nome_real = _shopee_real_text(
        recipient.get("name"),
        order.get("buyer_name"),
        address.get("name"),
    )
    client = shopee_nome_real or _shopee_real_text(buyer_username) or "NOME NÃO DISPONÍVEL"
    buyer_cpf = _shopee_real_text(order.get("buyer_cpf_id"))
    buyer_cnpj = _shopee_real_text(order.get("buyer_cnpj_id"))
    buyer_phone = _shopee_real_text(order.get("buyer_phone_number"), recipient.get("phone"), address.get("phone"))

    # Diagnóstico seguro: registra apenas presença/mascaramento dos campos, sem
    # gravar tokens e sem colocar CPF/CNPJ no log de integração.
    def _field_state(value: Any) -> str:
        text = str(value or "").strip()
        if not text:
            return "ausente"
        return "visivel" if _shopee_real_text(text) else "mascarado"
    shopee_name_diag = ";".join((
        f"buyer_name={_field_state(order.get('buyer_name'))}",
        f"recipient_name={_field_state(recipient.get('name'))}",
        f"address_name={_field_state(address.get('name'))}",
        f"buyer_username={_field_state(buyer_username)}",
        f"buyer_cpf_id={_field_state(order.get('buyer_cpf_id'))}",
        f"buyer_cnpj_id={_field_state(order.get('buyer_cnpj_id'))}",
    ))
    status = str(order.get("order_status") or "READY_TO_SHIP").strip()
    packages = order.get("package_list") if isinstance(order.get("package_list"), list) else []
    api_packages = [str(x.get("package_number") or "").strip() for x in packages if isinstance(x, dict) and str(x.get("package_number") or "").strip()]
    all_packages = list(dict.fromkeys([*package_numbers, *api_packages]))
    invoice = order.get("invoice_data") if isinstance(order.get("invoice_data"), dict) else {}
    invoice_number = str(invoice.get("number") or "").strip()
    invoice_key = str(invoice.get("access_key") or "").strip()
    shipping_carrier = str(order.get("shipping_carrier") or "").strip()
    lines: list[dict[str, Any]] = []
    for idx, item in enumerate(order.get("item_list") or []):
        if not isinstance(item, dict):
            continue
        sku = str(item.get("model_sku") or item.get("item_sku") or "").strip()
        if not sku:
            continue
        quantity = item.get("active_qty")
        try:
            quantity = int(quantity or 0)
        except Exception:
            quantity = 0
        if quantity <= 0:
            try:
                quantity = int(item.get("model_quantity_purchased") or 1)
            except Exception:
                quantity = 1
        description = str(item.get("item_name") or "").strip()
        model_name = str(item.get("model_name") or "").strip()
        if model_name and normalize(model_name) not in normalize(description):
            description = f"{description} - {model_name}".strip(" -")
        identity = f"{order_sn}|{item.get('item_id')}|{item.get('model_id')}|{item.get('line_item_id')}|{sku}"
        row = {
            "Pedido": order_sn,
            "Marketplace": "SHOPEE",
            "Data do Pedido": _shopee_date(order.get("create_time")),
            "Kit": "",
            "Nome do Kit": "",
            "Quantidade de Kits": "",
            "Quantidade por Kit": "",
            "Cliente": client,
            "NomeFiscalShopee": shopee_nome_real,
            "UsuarioShopee": buyer_username,
            "CPFShopee": buyer_cpf,
            "CNPJShopee": buyer_cnpj,
            "TelefoneShopee": buyer_phone,
            "DiagnosticoNomeShopee": shopee_name_diag,
            "SKU": sku,
            "Quantidade": str(max(1, quantity)),
            "Código de Barras": "",
            "Descrição": description,
            "Rua": "", "Módulo": "", "Prateleira": "", "Nível": "", "Posição": "", "Foto": "",
            "Código de Rastreio": "",
            "NF": invoice_number,
            "Nota Fiscal": invoice_number,
            "Chave de Acesso": invoice_key,
            "PacoteShopee": ",".join(all_packages),
            "TransportadoraShopee": shipping_carrier,
            "StatusShopee": status,
            "StatusOrigemShopee": status,
            "OrigemCadastro": "API_SHOPEE",
            "ShopIdShopee": str((shopee_integration_row() or {"shop_id": ""})["shop_id"] if shopee_integration_row() else ""),
            "SkuOrigemImportacao": sku,
            "SkuPrincipalShopee": str(item.get("item_sku") or "").strip(),
            "SkuReferenciaShopee": str(item.get("model_sku") or "").strip(),
            "VariacaoShopee": model_name,
            "ItemIdShopee": str(item.get("item_id") or ""),
            "ModelIdShopee": str(item.get("model_id") or ""),
            "LineItemIdShopee": str(item.get("line_item_id") or ""),
            "ShopeeAtualizadoEm": now_iso(),
            "CriadoEm": now_iso(),
            "__uidLinha": "SHOPEEAPI_" + hashlib.sha1(identity.encode("utf-8")).hexdigest()[:20],
        }
        product = _ml_find_product(products, sku)
        if product:
            for field in ("SKU", "Código de Barras", "Descrição", "Rua", "Módulo", "Prateleira", "Nível", "Posição", "Foto"):
                value = product.get(field)
                if str(value or "").strip():
                    row[field] = value
        lines.append(row)
    return lines



def _shopee_consolidate_api_quantities_v1778(lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Consolida linhas repetidas da mesma venda/item Shopee sem inflar quantidade."""
    result: list[dict[str, Any]]=[]
    positions: dict[tuple[str,str,str,str,str],int]={}
    for row in lines:
        if not isinstance(row,dict):
            continue
        key=(
            normalize(order_number(row)),
            str(row.get("ItemIdShopee") or ""),
            str(row.get("ModelIdShopee") or ""),
            str(row.get("LineItemIdShopee") or ""),
            normalize(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or row.get("SKU")),
        )
        # line_item_id presente identifica uma linha real única. Sem ele,
        # item/model/SKU formam a unidade comercial e duplicatas são somadas.
        if key not in positions:
            positions[key]=len(result)
            result.append(dict(row))
            continue
        i=positions[key]
        try: a=max(1,int(float(result[i].get("Quantidade") or 1)))
        except Exception: a=1
        try: b=max(1,int(float(row.get("Quantidade") or 1)))
        except Exception: b=1
        result[i]["Quantidade"]=str(a+b)
    return result


def _shopee_expand_kit_lines(lines: list[dict[str, Any]], products: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """V18.71: KIT da Shopee vira os produtos do kit, pelo Cadastro de Kits (como no ML).

    Bug de 06/10/2026 (261006VAG06G07): a Shopee manda uma linha só com o SKU do
    anúncio do kit ("0893600022/0893764272"). O Admin abria o kit só na tela
    (V16.46) e a Conferência mostrava a linha colada, que não dá para bipar.

    Só abre kit CADASTRADO e ativo cujo SKU é exatamente o do kit (produto comum
    nunca herda composição). O __uidLinha é o mesmo que o Admin grava ao salvar
    (KITDB_<pedido>_<kit>_<sku>_<i>): casa com linhas já gravadas e seus bips.
    SkuOrigemImportacao vira o SKU do componente, para a exclusão manual de UM
    componente não apagar o kit inteiro; o SKU do anúncio fica em SkuReferenciaShopee.
    """
    if not lines:
        return []
    catalog = _load_kit_catalog()   # V20.22: vazio também lê o prefixo KITn-
    out: list[dict[str, Any]] = []
    for row in lines:
        sku = str(row.get("SkuOrigemImportacao") or row.get("SKU") or "").strip()
        kit = _kit_catalog_lookup(catalog, sku) if (sku and catalog) else None
        if kit and normalize(kit.get("sku_kit")) != normalize(sku) and not re.match(r"^KIT", sku, flags=re.I):
            kit = None
        if not kit and sku:
            # V20.22: como no ML, "KITn-X" sem cadastro = n × X (261028SR23HUPK: kit10-10396473
            # subia como 1 unidade do SKU do kit; o romaneio saía com 10).
            kit = _infer_quantity_kit_from_sku(sku)
        comps = (kit or {}).get("componentes") or []
        if not kit or not kit.get("ativo", True) or not comps or (
            len(comps) == 1 and int(comps[0].get("quantidade") or 0) == 1 and normalize(comps[0].get("sku")) == normalize(sku)
        ):
            out.append(row)
            continue
        try:
            kits = max(1, int(float(row.get("Quantidade") or 1)))
        except Exception:
            kits = 1
        kit_sku = str(kit.get("sku_kit") or sku).strip()
        for indice, comp in enumerate(comps):
            comp_sku = str(comp.get("sku") or "").strip()
            por_kit = max(1, int(comp.get("quantidade") or 1))
            nova = dict(row)
            for campo in ("Código de Barras", "Rua", "Módulo", "Prateleira", "Nível", "Posição", "Foto"):
                nova[campo] = ""
            nova.update({
                "SKU": comp_sku, "Quantidade": str(kits * por_kit),
                "Kit": "SIM", "Nome do Kit": str(kit.get("nome") or kit_sku).strip(),
                "Quantidade de Kits": str(kits), "Quantidade por Kit": str(por_kit),
                "SkuKitOrigem": kit_sku, "SkuOrigemImportacao": comp_sku,
                "__uidLinha": f"KITDB_{normalize(order_number(row))}_{normalize(kit_sku)}_{normalize(comp_sku)}_{indice}",
            })
            product = _ml_find_product(products, comp_sku)
            if product:
                for field in ("SKU", "Código de Barras", "Descrição", "Rua", "Módulo", "Prateleira", "Nível", "Posição", "Foto"):
                    value = product.get(field)
                    if str(value or "").strip():
                        nova[field] = value
            out.append(nova)
    return out


def _shopee_filter_artificial_kit_lines(lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Remove linhas artificiais de kit quando os produtos reais já vieram da Shopee.

    Casos cobertos de forma conservadora:
    - SKU composto por barras (A/B) quando A e B já existem no mesmo pedido;
    - SKU no padrão kit2-SKU quando o SKU real também existe no mesmo pedido e
      sua quantidade já contempla a multiplicidade indicada no prefixo.
    """
    if not lines:
        return []
    by_order: dict[str, list[dict[str, Any]]] = {}
    for row in lines:
        by_order.setdefault(normalize(order_number(row)), []).append(row)
    result: list[dict[str, Any]] = []
    for _, group in by_order.items():
        real_qty: dict[str, int] = {}
        for row in group:
            sku = str(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or row.get("SKU") or "").strip()
            norm = normalize(sku)
            if not norm or "/" in sku or re.match(r"^KIT\s*\d*[-_: ]+", sku, re.I):
                continue
            try:
                qty = max(1, int(float(row.get("Quantidade") or 1)))
            except Exception:
                qty = 1
            real_qty[norm] = real_qty.get(norm, 0) + qty
        for row in group:
            sku = str(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or row.get("SKU") or "").strip()
            if "/" in sku:
                parts = [normalize(x) for x in sku.split("/") if normalize(x)]
                if len(parts) >= 2 and all(part in real_qty for part in set(parts)):
                    continue
            m = re.match(r"^KIT\s*(\d+)?[-_: ]+(.+)$", sku, re.I)
            if m:
                mult = max(1, int(m.group(1) or 1))
                base = normalize(m.group(2))
                if base and real_qty.get(base, 0) >= mult:
                    continue
            result.append(row)
    return result



PENDING_ORDER_DELETE_KEY_V1766 = "conf_pedidos_exclusoes_v1766"


def _pending_order_manual_deletions() -> list[dict[str, Any]]:
    row = DB.execute("SELECT value FROM storage WHERE key=?", (PENDING_ORDER_DELETE_KEY_V1766,)).fetchone()
    if not row:
        return []
    try:
        parsed = json.loads(str(row["value"] or "[]"))
    except Exception:
        return []
    return [dict(x) for x in parsed if isinstance(x, dict)] if isinstance(parsed, list) else []


def _pending_order_is_manually_deleted(row: dict[str, Any], deletions: list[dict[str, Any]] | None = None) -> bool:
    order = normalize(order_number(row))
    if not order:
        return False
    for item in (deletions if deletions is not None else _pending_order_manual_deletions()):
        if normalize(item.get("Pedido")) == order and bool(item.get("Ativo", True)):
            return True
    return False


def _pending_admin_restore_orders(order_keys: set[str]) -> None:
    """V17.78 — inclusão explícita do ADMIN vence exclusão/tombstone anterior."""
    keys={normalize(x) for x in order_keys if normalize(x)}
    if not keys:
        return
    # V18.56: a conexão é UMA só para todas as threads. Sem o DB_LOCK, o COMMIT
    # abaixo gravava pela metade a transação de um save_storage() de outra thread.
    with DB_LOCK:
        _pending_admin_restore_orders_locked(keys)


def _pending_admin_restore_orders_locked(keys: set[str]) -> None:
    # Tombstone genérico V17.66.
    row=DB.execute("SELECT value,version FROM storage WHERE key=?", (PENDING_ORDER_DELETE_KEY_V1766,)).fetchone()
    if row:
        try: items=json.loads(str(row["value"] or "[]"))
        except Exception: items=[]
        changed=False
        if isinstance(items,list):
            for item in items:
                if isinstance(item,dict) and normalize(item.get("Pedido")) in keys and bool(item.get("Ativo",True)):
                    item["Ativo"]=False
                    item["RestauradoPorAdminEm"]=now_iso()
                    changed=True
        if changed:
            DB.execute("UPDATE storage SET value=?,version=?,updated_at=? WHERE key=?",
                       (json_dumps(items),int(row["version"] or 0)+1,now_iso(),PENDING_ORDER_DELETE_KEY_V1766))
    # Tombstones Shopee por pedido/linha também não podem bloquear uma reinclusão ADMIN.
    row=DB.execute("SELECT value,version FROM storage WHERE key='conf_shopee_exclusoes_v1'").fetchone()
    if row:
        try: items=json.loads(str(row["value"] or "[]"))
        except Exception: items=[]
        changed=False
        if isinstance(items,list):
            kept=[]
            for item in items:
                if isinstance(item,dict) and normalize(item.get("Pedido")) in keys:
                    changed=True
                    continue
                kept.append(item)
            if changed:
                DB.execute("UPDATE storage SET value=?,version=?,updated_at=? WHERE key='conf_shopee_exclusoes_v1'",
                           (json_dumps(kept),int(row["version"] or 0)+1,now_iso()))
    # V17.82: os UPDATEs acima abrem transação implícita. Sem este COMMIT, o
    # BEGIN IMMEDIATE do save_storage() seguinte falhava e a reinclusão explícita
    # do ADMIN morria em HTTP 409 — deixando o pedido preso no tombstone.
    DB.commit()


def _pending_filter_manual_deleted_orders_value(value: str | None) -> str:
    try:
        rows = json.loads(value or "[]")
    except Exception:
        return value or "[]"
    if not isinstance(rows, list):
        return value or "[]"
    deletions = _pending_order_manual_deletions()
    if not deletions:
        return json_dumps(rows)
    return json_dumps([
        row for row in rows
        if not (isinstance(row, dict) and _pending_order_is_manually_deleted(row, deletions))
    ])


def _shopee_load_manual_deletions() -> list[dict[str, Any]]:
    raw, _, _ = get_storage("conf_shopee_exclusoes_v1")
    rows = _rows_from_storage_value(raw)
    return [x for x in rows if isinstance(x, dict)]


def _shopee_is_manually_deleted(row: dict[str, Any], deletions: list[dict[str, Any]]) -> bool:
    order = normalize(order_number(row))
    uid = str(row.get("__uidLinha") or "").strip()
    source_sku = normalize(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or row.get("SKU"))
    for item in deletions:
        if normalize(item.get("Pedido")) != order:
            continue
        # V17.66: exclusão do KIT/pedido inteiro pelo ADMIN vence qualquer sync Shopee.
        if bool(item.get("ExcluirPedido")) or normalize(item.get("Tipo")) in {"PEDIDO", "KIT_INTEIRO"}:
            return True
        deleted_uid = str(item.get("UidLinha") or "").strip()
        deleted_sku = normalize(item.get("SkuOrigem") or item.get("SKU"))
        if deleted_uid and uid and deleted_uid == uid:
            return True
        if deleted_sku and source_sku and deleted_sku == source_sku:
            return True
    return False


SHOPEE_MANUAL_EDIT_FIELDS = (
    "Cliente",
    "NomeFiscalShopee",
    "Nome Conferência",
    "Kit",
    "Nome do Kit",
    "Quantidade de Kits",
    "Quantidade por Kit",
    "SKU",
    # V17.78: Quantidade não entra na proteção automática Shopee. A quantidade
    # real da venda vem da API; alterações explícitas do ADMIN continuam soberanas
    # pelo admin_manual_overrides aplicado no final do save_storage.
    "Código de Barras",
    "Descrição",
    "Rua",
    "Módulo",
    "Prateleira",
    "Nível",
    "Posição",
    "Foto",
    "NF",
    "Nota Fiscal",
    "Chave de Acesso",
)


def _shopee_snapshot_editable(row: dict[str, Any]) -> dict[str, Any]:
    """Snapshot dos valores fornecidos automaticamente pela Shopee/Noromak.

    Ele permite distinguir, nas sincronizações seguintes, um valor que veio da API
    de um valor que o operador alterou manualmente na tela.
    """
    return {field: row.get(field, "") for field in SHOPEE_MANUAL_EDIT_FIELDS}


def _shopee_parse_snapshot(row: dict[str, Any]) -> dict[str, Any]:
    raw = row.get("ShopeeApiSnapshot")
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str) and raw.strip():
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, dict):
                return parsed
        except Exception:
            pass
    return {}


def _shopee_line_match_key(row: dict[str, Any]) -> tuple[str, str, str]:
    """Chave estável para casar a linha já existente com o novo retorno da API."""
    uid = str(row.get("__uidLinha") or "").strip()
    if uid:
        return ("uid", uid, "")
    order = normalize(order_number(row))
    source_sku = normalize(row.get("SkuOrigemImportacao") or row.get("SkuReferenciaShopee") or row.get("SKU"))
    return ("order_sku", order, source_sku)


def _shopee_merge_api_line_preserving_manual(old_row: dict[str, Any], api_row: dict[str, Any]) -> dict[str, Any]:
    """Atualiza dados automáticos sem sobrescrever edição manual do operador.

    Regra: se o valor atual for diferente do último snapshot automático, ele foi
    editado manualmente e prevalece. Status/logística/metadados da API continuam
    sendo atualizados normalmente.
    """
    previous_snapshot = _shopee_parse_snapshot(old_row)
    if not previous_snapshot:
        # Migração V17.25 -> V17.26: o usuário confirmou que ainda não editou os
        # pedidos Shopee, então o estado existente é uma linha-base segura.
        previous_snapshot = _shopee_snapshot_editable(old_row)

    merged = dict(old_row)
    # Primeiro recebe tudo que é novo/operacional da API.
    merged.update(api_row)

    for field in SHOPEE_MANUAL_EDIT_FIELDS:
        old_value = old_row.get(field, "")
        baseline_value = previous_snapshot.get(field, old_value)
        # Qualquer diferença em relação ao último valor automático significa edição
        # manual (inclusive apagar um valor). Nesse caso não sobrescrever.
        if old_value != baseline_value:
            merged[field] = old_value

    # O snapshot sempre guarda o que a API teria aplicado nesta sincronização,
    # independentemente de existir uma edição manual preservada.
    merged["ShopeeApiSnapshot"] = json_dumps(_shopee_snapshot_editable(api_row))
    merged["ShopeeProtecaoManual"] = "ATIVA"
    return merged


def _shopee_merge_pending_lines(current: list[dict[str, Any]], api_lines: list[dict[str, Any]], active_orders: set[str], detail_orders: set[str]) -> tuple[list[dict[str, Any]], int, int]:
    """Reconcilia somente linhas API_SHOPEE e preserva campos editados à mão."""
    current_api: dict[tuple[str, str, str], dict[str, Any]] = {}
    preserved_non_api: list[dict[str, Any]] = []
    removed = 0
    active_norm = {normalize(x) for x in active_orders}
    detail_norm = {normalize(x) for x in detail_orders}

    for row in current:
        if not isinstance(row, dict):
            continue
        if normalize(row.get("OrigemCadastro")) != "API_SHOPEE":
            preserved_non_api.append(row)
            continue
        oid_norm = normalize(order_number(row))
        if oid_norm not in active_norm:
            removed += 1
            continue
        current_api[_shopee_line_match_key(row)] = row

    merged_api: list[dict[str, Any]] = []
    seen_keys: set[tuple[str, str, str]] = set()
    protected_count = 0
    for api_row in api_lines:
        key = _shopee_line_match_key(api_row)
        old = current_api.get(key)
        if old:
            before = {f: old.get(f, "") for f in SHOPEE_MANUAL_EDIT_FIELDS}
            merged = _shopee_merge_api_line_preserving_manual(old, api_row)
            after_api = _shopee_snapshot_editable(api_row)
            if any(before.get(f) != _shopee_parse_snapshot(old).get(f, before.get(f)) for f in SHOPEE_MANUAL_EDIT_FIELDS):
                protected_count += 1
            # V20.04: CriadoEm é de quando a linha nasceu e ShopeeAtualizadoEm só anda se
            # algo mudou. Trocados a cada minuto, a fila mudava de versão sem mudar nada e
            # toda tela aberta baixava a fila inteira de novo.
            if old.get("CriadoEm"):
                merged["CriadoEm"] = old["CriadoEm"]
            if old.get("ShopeeAtualizadoEm") and all(
                merged.get(f) == old.get(f) for f in set(merged) | set(old) if f != "ShopeeAtualizadoEm"
            ):
                merged["ShopeeAtualizadoEm"] = old["ShopeeAtualizadoEm"]
            merged_api.append(merged)
        else:
            fresh = dict(api_row)
            fresh["ShopeeApiSnapshot"] = json_dumps(_shopee_snapshot_editable(api_row))
            fresh["ShopeeProtecaoManual"] = "ATIVA"
            merged_api.append(fresh)
        seen_keys.add(key)

    # Se o detalhe de um pedido ativo falhou nesta rodada, mantém as linhas antigas.
    for key, row in current_api.items():
        if key in seen_keys:
            continue
        oid_norm = normalize(order_number(row))
        if oid_norm in active_norm and oid_norm not in detail_norm:
            merged_api.append(row)

    return [*preserved_non_api, *merged_api], removed, protected_count


SHOPEE_ORDERS_SYNC_LOCK = threading.Lock()


def shopee_manual_sync(*, acordar_etiquetas: bool = True) -> dict[str, Any]:
    # V17.92: o worker automático e o botão de sincronizar não rodam juntos.
    with SHOPEE_ORDERS_SYNC_LOCK:
        return _shopee_manual_sync_sem_trava(acordar_etiquetas)


def _shopee_manual_sync_sem_trava(acordar_etiquetas: bool = True) -> dict[str, Any]:
    status = shopee_status_payload()
    if not status["connected"]:
        raise RuntimeError("Shopee ainda não está conectada.")
    sync_started = now_iso()
    try:
        shipments = shopee_current_shipments()
        # V20.14: + os "a enviar" da get_order_list; falha nela = só a lista de envio, como antes.
        try:
            na_lista = {str(x.get("order_sn") or "").strip() for x in shipments}
            shipments = shipments + [{"order_sn": sn, "package_number": ""}
                                     for sn in shopee_pedidos_a_enviar() if sn not in na_lista]
        except Exception as exc:
            shopee_log_event_se_mudou("orders_sync", "a_enviar", "AVISO", str(exc)[:300])
        packages_by_order: dict[str, list[str]] = {}
        for shipment in shipments:
            order_sn = str(shipment.get("order_sn") or "").strip()
            package = str(shipment.get("package_number") or "").strip()
            if order_sn:
                packages_by_order.setdefault(order_sn, [])
                if package and package not in packages_by_order[order_sn]:
                    packages_by_order[order_sn].append(package)

        order_sns = list(packages_by_order)
        details = shopee_order_details(order_sns) if order_sns else []
        for order in details:   # V20.14: pacote de quem veio só da get_order_list
            sn = str(order.get("order_sn") or "").strip()
            if sn in packages_by_order and not packages_by_order[sn]:
                packages_by_order[sn] = [str(p.get("package_number") or "").strip()
                                         for p in (order.get("package_list") or [])
                                         if isinstance(p, dict) and str(p.get("package_number") or "").strip()]
        # V18.93: aviso de venda com o mesmo detalhe (sem chamada a mais).
        try:
            avisos_venda_registrar("shopee", avisos_vendas_da_shopee(details))
        except Exception as exc:
            print(f"[avisos-venda] shopee: {exc}", file=sys.stderr, flush=True)
        products_raw, _, _ = get_storage("conf_produtos")
        products = _rows_from_storage_value(products_raw)
        api_lines: list[dict[str, Any]] = []
        detail_orders: set[str] = set()
        for order in details:
            order_sn = str(order.get("order_sn") or "").strip()
            if not order_sn:
                continue
            detail_orders.add(order_sn)
            api_lines.extend(_shopee_build_pending_lines(order, packages_by_order.get(order_sn, []), products))

        # V17.43: remove linhas artificiais de kit antes da reconciliação e respeita
        # exclusões manuais persistentes feitas no Admin/Conferência.
        api_lines = _shopee_consolidate_api_quantities_v1778(api_lines)
        api_lines = _shopee_filter_artificial_kit_lines(api_lines)
        # V18.71: exclusões manuais valem ANTES de abrir o kit (a linha do kit que o
        # ADMIN excluiu não volta como componentes) e DEPOIS (a exclusão de um
        # componente só continua valendo).
        manual_deletions = _shopee_load_manual_deletions()
        if manual_deletions:
            api_lines = [row for row in api_lines if not _shopee_is_manually_deleted(row, manual_deletions)]
        api_lines = _shopee_expand_kit_lines(api_lines, products)
        if manual_deletions:
            api_lines = [row for row in api_lines if not _shopee_is_manually_deleted(row, manual_deletions)]

        current_raw, _, _ = get_storage("conf_pedidos")
        current = _rows_from_storage_value(current_raw)
        active_orders = set(order_sns)
        # V17.26: reconcilia as linhas Shopee sem sobrescrever campos que o operador
        # alterou manualmente. Pedidos manuais/ML/Magalu continuam intocados.
        pending, removed, protected_count = _shopee_merge_pending_lines(
            current, api_lines, active_orders, detail_orders
        )
        # V20.04: nada mudou = nada a gravar (a ordem das linhas não conta: o merge põe as
        # da API no fim). Antes, 1 gravação por minuto sem mudança nenhuma.
        def _assinatura(linhas: list[dict[str, Any]]) -> list[str]:
            return sorted(json.dumps(r, sort_keys=True, ensure_ascii=False, default=str) for r in linhas)
        if not removed and _assinatura(pending) == _assinatura(current):
            saved = current_raw
        else:
            saved, _, _ = save_storage(
                "conf_pedidos", current_raw, json_dumps(pending), False,
                actor="sistema", actor_role="sistema", source_screen="Admin / Integrações / Shopee",
                change_method="Sincronização API Shopee Live", client_ip="127.0.0.1",
                allow_completed_reimport=False,
            )
        final_rows = _rows_from_storage_value(saved)
        imported_orders = len({order_number(r) for r in final_rows if normalize(r.get("OrigemCadastro")) == "API_SHOPEE"})
        # V18.62: pedido que entrou agora na fila acorda o worker de etiquetas na
        # hora (antes esperava até 3 min). Sem pedido novo, segue a regra da V17.92.
        pedidos_antes = {order_number(r) for r in current if isinstance(r, dict)}
        pedidos_novos = {
            order_number(r) for r in final_rows
            if isinstance(r, dict) and normalize(r.get("OrigemCadastro")) == "API_SHOPEE"
        } - pedidos_antes
        # V17.27: nunca bloqueia a requisição esperando criação/READY/download de etiqueta.
        # O worker do servidor acorda imediatamente e continua o fluxo em background.
        # V17.92: a sincronização automática (a cada minuto) não acorda o worker
        # de etiquetas — ele segue no intervalo próprio, sem multiplicar chamadas.
        if acordar_etiquetas or pedidos_novos:
            SHOPEE_LABEL_WAKE_EVENT.set()
        shipping_docs = {
            "enfileirados": len(shipments),
            "baixados": 0,
            "vinculados": 0,
            "pendentes": len(shipments),
            "background": True,
        }
        with DB_LOCK:
            DB.execute("UPDATE shopee_integration SET last_sync_at=?,updated_at=?,last_error='' WHERE id=1", (now_iso(), now_iso()))
            DB.commit()
        shopee_log_event("orders_sync", f"shop_id={status.get('shop_id')}", "OK",
                         f"{len(order_sns)} pedido(s) para expedição; {len(api_lines)} linha(s); {removed} linha(s) API antiga(s) reconciliada(s); {protected_count} linha(s) com edição manual preservada.")
        # Resumo seguro para diagnosticar o que a Shopee realmente liberou.
        diag_counts = {"recipient_visivel": 0, "recipient_mascarado": 0, "recipient_ausente": 0, "buyer_visivel": 0}
        for order in details:
            recipient = order.get("recipient_address") if isinstance(order.get("recipient_address"), dict) else {}
            rn = str(recipient.get("name") or "").strip()
            bn = str(order.get("buyer_name") or "").strip()
            def _visible_name(v: str) -> bool:
                return bool(re.sub(r"[\s*•xX._-]+", "", v or ""))
            if not rn:
                diag_counts["recipient_ausente"] += 1
            elif _visible_name(rn):
                diag_counts["recipient_visivel"] += 1
            else:
                diag_counts["recipient_mascarado"] += 1
            if _visible_name(bn):
                diag_counts["buyer_visivel"] += 1
        shopee_log_event("recipient_diag", f"shop_id={status.get('shop_id')}", "OK", json_dumps(diag_counts))
        return {
            "ok": True,
            "imported": imported_orders,
            "orders_found": len(order_sns),
            "lines_imported": len(api_lines),
            "removed_api_lines": removed,
            "detail_missing": max(0, len(order_sns) - len(detail_orders)),
            "name_diagnostic": diag_counts,
            "shipping_documents": shipping_docs,
            "sync_started_at": sync_started,
            "message": f"Shopee sincronizada: {len(order_sns)} pedido(s), {len(api_lines)} item(ns). Etiquetas enviadas ao processamento automático do servidor: {len(shipments)}.",
        }
    except Exception as exc:
        with DB_LOCK:
            DB.execute("UPDATE shopee_integration SET last_error=?,updated_at=? WHERE id=1", (str(exc)[:1000], now_iso()))
            DB.commit()
        shopee_log_event("orders_sync", f"shop_id={status.get('shop_id')}", "ERRO", str(exc))
        raise


SHOPEE_ORDERS_WORKER_INTERVAL = max(30, min(900, int(os.getenv("SHOPEE_ORDERS_WORKER_INTERVAL", "60"))))


def shopee_orders_worker_loop(stop_event: threading.Event) -> None:
    """V17.92 — importa os pedidos da Shopee sozinho, como o Mercado Livre.

    Até aqui a importação só rodava pelo botão de sincronizar da tela de
    Integrações. Mesma função do botão (shopee_manual_sync), a cada minuto.
    """
    stop_event.wait(20)
    while not stop_event.is_set():
        try:
            if shopee_status_payload().get("connected"):
                shopee_manual_sync(acordar_etiquetas=False)
        except Exception as exc:
            shopee_log_event("orders_worker", "background", "ERRO", str(exc)[:800])
        stop_event.wait(SHOPEE_ORDERS_WORKER_INTERVAL)


def _shopee_label_proxima_espera(result: dict[str, Any], rapidos: int) -> tuple[int, int]:
    """V18.62 — quanto o worker de etiquetas espera até o próximo ciclo.

    Com pedido no meio do fluxo (rastreio ou documento ainda saindo) volta em
    SHOPEE_LABEL_FOLLOWUP_INTERVAL. Sem progresso, no máximo
    SHOPEE_LABEL_FOLLOWUP_MAX vezes seguidas; etiqueta vinculada ou envio
    organizado zera a contagem. Retorna (segundos, ciclos rápidos seguidos).
    """
    if int(result.get("vinculados", 0) or 0) or int(result.get("ship_order_ok", 0) or 0):
        rapidos = 0
    if int(result.get("aguardando", 0) or 0) and rapidos < SHOPEE_LABEL_FOLLOWUP_MAX:
        return SHOPEE_LABEL_FOLLOWUP_INTERVAL, rapidos + 1
    return SHOPEE_LABEL_WORKER_INTERVAL, 0


# V20.13 (caso real 03/11): a get_shipment_list passou a vir vazia, sem erro, com pedidos
# READY_TO_SHIP e NF-e válida (pacote LOGISTICS_READY). Fora da lista não quer dizer
# organizado: a situação do pacote no get_order_detail decide. Sem o detalhe, fica como
# antes (V17.91). E todos os pendentes sem etiqueta entram, não só os 40 mais recentes.
SHOPEE_LABEL_PENDENTES_LIMITE = 150
SHOPEE_PACOTE_A_ORGANIZAR = "LOGISTICS_READY"


def shopee_label_candidatos(shipments: list[dict[str, str]]) -> tuple[list[dict[str, str]], set[str]]:
    """(lista para shopee_sync_shipping_documents, pedidos já organizados)."""
    na_lista = {x.get("order_sn") for x in shipments}
    pendentes = [x for x in shopee_pedidos_sem_etiqueta(limite=SHOPEE_LABEL_PENDENTES_LIMITE)
                 if x["order_sn"] not in na_lista]
    if not pendentes:
        return list(shipments), set()
    try:
        por_pedido = {str(o.get("order_sn") or "").strip(): o
                      for o in shopee_order_details([x["order_sn"] for x in pendentes], campos="package_list")}
    except Exception as exc:
        shopee_log_event_se_mudou("shipping_worker", "detalhe", "AVISO", str(exc)[:300])
        por_pedido = {}
    extra: list[dict[str, str]] = []
    ja: set[str] = set()
    for x in pendentes:
        o = por_pedido.get(x["order_sn"]) or {}
        prontos = [str(p.get("package_number") or "").strip() for p in (o.get("package_list") or [])
                   if isinstance(p, dict) and p.get("logistics_status") == SHOPEE_PACOTE_A_ORGANIZAR]
        if o.get("order_status") in ("READY_TO_SHIP", "RETRY_SHIP") and prontos:
            extra.extend({"order_sn": x["order_sn"], "package_number": pk or x.get("package_number", "")} for pk in prontos)
        else:
            extra.append(x)
            ja.add(x["order_sn"])
    return list(shipments) + extra, ja


def shopee_label_worker_loop(stop_event: threading.Event) -> None:
    """Continua geração/consulta/download das etiquetas Shopee em background.

    A requisição de sincronização apenas acorda este worker. Assim, mesmo que a
    Shopee demore para preparar documentos, o Nginx não recebe uma requisição
    longa e não retorna HTTP 504.
    """
    # Pequeno atraso inicial para deixar HTTP/DB totalmente prontos no boot.
    stop_event.wait(5)
    # V17.99: etiquetas da API gravadas sem a imagem (saíam em branco) são
    # regravadas a partir do arquivo original. Só age em quem está quebrado.
    try:
        with SHOPEE_LABEL_WORKER_LOCK:
            shopee_reparar_etiquetas_sem_grafico()
    except Exception as exc:
        try:
            shopee_log_event("etiqueta_reparada", "boot", "ERRO", str(exc)[:500])
        except Exception:
            pass
    espera, rapidos = SHOPEE_LABEL_WORKER_INTERVAL, 0
    while not stop_event.is_set():
        # Acorda imediatamente após sincronização manual / pedido novo, ou no intervalo.
        # V18.83: a espera por este evento também conta no pulso do Painel de saúde.
        _saude_esperar(SHOPEE_LABEL_WAKE_EVENT, espera)
        espera = SHOPEE_LABEL_WORKER_INTERVAL
        SHOPEE_LABEL_WAKE_EVENT.clear()
        if stop_event.is_set():
            break
        if not SHOPEE_LABEL_WORKER_LOCK.acquire(blocking=False):
            continue
        try:
            st = shopee_status_payload()
            if not st.get("connected"):
                continue
            shipments = shopee_current_shipments()
            # V17.91: organizado, o pedido sai de get_shipment_list — justamente
            # quando a etiqueta fica disponível. Os pendentes no Noromak sem
            # etiqueta e fora dessa lista seguem direto para rastreio/etiqueta.
            lista, ja_organizados = shopee_label_candidatos(shipments)   # V20.13
            if not lista:
                continue
            result = shopee_sync_shipping_documents(lista, ja_organizados=ja_organizados)
            espera, rapidos = _shopee_label_proxima_espera(result, rapidos)
            # V18.78: só grava quando os contadores mudaram — ciclo de 30 s com os mesmos
            # números era uma linha nova em shopee_event_log a cada vez (V18.56 já avisava).
            shopee_log_event_se_mudou(
                "shipping_worker",
                f"shop_id={st.get('shop_id')}",
                "OK",
                "consultados={consultados}; shipping_param={shipping_parameter_ok}; ship_order={ship_order_ok}; "
                "tracking={tracking_ok}; prontos={prontos}; baixados={baixados}; vinculados={vinculados}; "
                "pendentes={pendentes}; erros={erros}; aguardando={aguardando}".format(**{
                    k: int(result.get(k, 0) or 0)
                    for k in ("consultados","shipping_parameter_ok","ship_order_ok","tracking_ok","prontos","baixados","vinculados","pendentes","erros","aguardando")
                }) + f"; proximo_ciclo={espera}s",
            )
        except Exception as exc:
            shopee_log_event("shipping_worker", "background", "ERRO", str(exc)[:800])
        finally:
            SHOPEE_LABEL_WORKER_LOCK.release()


# Mercado Livre API / OAuth / Orders
# ---------------------------------------------------------------------------

def ml_credentials_configured() -> bool:
    return bool(ML_CLIENT_ID and ML_CLIENT_SECRET and ML_REDIRECT_URI)


def ml_log_event(topic: str, resource: str, user_id: Any, application_id: Any, result: str, detail: str = "") -> None:
    # V18.94: evento de outra casa aparece marcado no log ("[Bauru] new_order_watcher").
    casa = ml_casa_atual()
    if casa != CASA_PRINCIPAL:
        topic = f"[{CASAS.get(casa, casa)}] {topic or ''}"
    with DB_LOCK:
        DB.execute(
            """INSERT INTO ml_event_log(created_at,topic,resource,user_id,application_id,result,detail)
               VALUES(?,?,?,?,?,?,?)""",
            (
                now_iso(),
                str(topic or "")[:100],
                str(resource or "")[:500],
                str(user_id or "")[:80],
                str(application_id or "")[:80],
                str(result or "")[:80],
                str(detail or "")[:2000],
            ),
        )
        DB.commit()


# V18.78: os workers registravam o MESMO resultado para o MESMO recurso a cada
# ciclo (71 pedidos manuais ~168 vezes cada em 12 h; 16 Full ~383 vezes cada).
# Cada registro é um INSERT + commit segurando o DB_LOCK — disputa com a bipagem.
# Aqui só vai para o banco quando (resultado, detalhe) mudou desde o último
# registro daquele (tópico, recurso). Memória em processo: depois de um restart
# cada recurso é registrado uma vez e pronto.
_ML_LOG_ULTIMO: dict[tuple[str, str, str], tuple[str, str]] = {}
_ML_LOG_ULTIMO_LOCK = threading.Lock()
_ML_LOG_ULTIMO_MAX = 20000


def _log_se_mudou(chave: tuple[str, str, str], valor: tuple[str, str]) -> bool:
    """Devolve True (e lembra) quando `valor` difere do último visto para `chave`.
    Serve ao log do ML e ao da Shopee — a chave começa pelo nome do log."""
    with _ML_LOG_ULTIMO_LOCK:
        if _ML_LOG_ULTIMO.get(chave) == valor:
            return False
        if len(_ML_LOG_ULTIMO) >= _ML_LOG_ULTIMO_MAX:
            _ML_LOG_ULTIMO.clear()
        _ML_LOG_ULTIMO[chave] = valor
    return True


def ml_log_event_se_mudou(topic: str, resource: str, user_id: Any, application_id: Any, result: str, detail: str = "") -> bool:
    if not _log_se_mudou(("ml", ml_casa_atual(), str(topic or ""), str(resource or "")), (str(result or ""), str(detail or ""))):
        return False
    ml_log_event(topic, resource, user_id, application_id, result, detail)
    return True


def shopee_log_event_se_mudou(topic: str, resource: str, result: str, detail: str = "") -> bool:
    if not _log_se_mudou(("shopee", str(topic or ""), str(resource or "")), (str(result or ""), str(detail or ""))):
        return False
    shopee_log_event(topic, resource, result, detail)
    return True


# ---------------------------------------------------------------------------
# V18.94 — uma conta do Mercado Livre por CASA (Araçatuba e Bauru).
#
# Araçatuba (a casa principal) continua exatamente onde sempre esteve: a linha id=1
# de ml_integration. As outras casas ficam em ml_integration_casa_v1894, uma linha por
# casa. Todo o código do ML (token, renovação, /orders, etiqueta, importação) lê a
# conta da CASA ATUAL — por padrão a principal; com `with ml_na_casa("bauru"):` o
# mesmo código passa a usar a conta de Bauru. Assim nada do que Araçatuba faz muda,
# e Bauru reaproveita as mesmas regras (ADMIN soberano, concluídos, kits, Full...).
# O contexto é por thread: quem abre thread nova precisa entrar na casa de novo.
# ---------------------------------------------------------------------------
CASA_PRINCIPAL = "aracatuba"
CASAS = {"aracatuba": "Araçatuba", "bauru": "Bauru"}
_ML_CASA_LOCAL = threading.local()


def ml_casa_atual() -> str:
    return getattr(_ML_CASA_LOCAL, "casa", CASA_PRINCIPAL)


def ml_casa_valida(casa: Any) -> str:
    casa = str(casa or "").strip().lower() or CASA_PRINCIPAL
    if casa not in CASAS:
        raise ValueError(f"Casa desconhecida: {casa}")
    return casa


@contextlib.contextmanager
def ml_na_casa(casa: str):
    anterior = getattr(_ML_CASA_LOCAL, "casa", None)
    _ML_CASA_LOCAL.casa = ml_casa_valida(casa)
    try:
        yield
    finally:
        if anterior is None:
            try:
                del _ML_CASA_LOCAL.casa
            except AttributeError:
                pass
        else:
            _ML_CASA_LOCAL.casa = anterior


def ml_casa_da_linha(row: dict[str, Any]) -> str:
    """CONTA do ML de um pedido da fila (com qual conta buscar etiqueta e reconciliar).
    V18.95: a conta (`ContaMercadoLivre`) é separada da filial que confere (`Casa`): o
    ADMIN pode mover o pedido de filial, mas a etiqueta continua vindo da conta de origem.
    Linha sem marca (tudo o que existia antes da V18.94, manual, Shopee) é da principal."""
    row = row or {}
    casa = str(row.get("ContaMercadoLivre") or row.get("Casa") or "").strip().lower()
    return casa if casa in CASAS else CASA_PRINCIPAL


# ---------------------------------------------------------------------------
# V18.95 — Conferência separada por FILIAL (decisões do dono, 10/10).
#
# Cada usuário tem uma filial (app_users.casa): aracatuba, bauru ou — só perfil Admin —
# todas. Quem tem "todas" escolhe a filial num seletor do Admin (cabeçalho
# X-Noromak-Filial; sem ele, vê tudo). O FILTRO É NO SERVIDOR: fila, etiquetas, histórico
# e coleta saem do /api/storage só com a filial efetiva. Na gravação, o que o usuário não
# via é JUNTADO DE VOLTA antes do save_storage (storage_remontar_por_filial): senão uma
# fila filtrada gravada por um Admin viraria tombstone ADMIN de tudo da outra filial
# (_admin_override_record_delta) e um operador perderia linhas. Linha sem `Casa` é de
# Araçatuba. Shopee é sempre Araçatuba.
# ---------------------------------------------------------------------------
FILIAL_TODAS = "todas"
FILIAL_CHAVES_LISTA = ("conf_pedidos", "conf_historico_conferencias_v2", "conf_logs")
FILIAL_CHAVES = (*FILIAL_CHAVES_LISTA, "conf_etiquetas", "conf_coleta_dia_v1")


def usuario_filial(row: Any) -> str:
    try:
        casa = str(row["casa"] or "").strip().lower()
    except (KeyError, IndexError, TypeError):
        casa = ""
    try:
        admin = str(row["role"] or "").lower() == "admin"
    except (KeyError, IndexError, TypeError):
        admin = False
    if role_efetivo(row) == PERFIL_CONSULTA:
        return FILIAL_TODAS  # V19.40: Consulta vê sempre todas as filiais
    if casa == FILIAL_TODAS:
        return FILIAL_TODAS if admin else CASA_PRINCIPAL
    return casa if casa in CASAS else CASA_PRINCIPAL


def filial_normalizar(valor: Any, role: str) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or "")).encode("ascii", "ignore").decode().strip().lower()
    if is_consulta_role(role):
        return FILIAL_TODAS  # V19.40
    if texto in ("", "aracatuba"):
        return CASA_PRINCIPAL
    if texto in ("todas", "todas as filiais"):
        if str(role or "").lower() != "admin":
            raise ValueError("Só o perfil Admin pode ver todas as filiais.")
        return FILIAL_TODAS
    if texto in CASAS:
        return texto
    raise ValueError(f"Filial desconhecida: {valor}")


def filial_efetiva(ctx: dict[str, Any] | None, escolhida: Any = "") -> str:
    """Filial que a requisição enxerga: a do usuário; quem tem "todas" pode escolher uma."""
    casa = str((ctx or {}).get("casa") or CASA_PRINCIPAL)
    if casa != FILIAL_TODAS:
        return casa if casa in CASAS else CASA_PRINCIPAL
    escolhida = str(escolhida or "").strip().lower()
    return escolhida if escolhida in CASAS else FILIAL_TODAS


def filial_da_linha(row: Any) -> str:
    casa = str(row.get("Casa") or "").strip().lower() if isinstance(row, dict) else ""
    return casa if casa in CASAS else CASA_PRINCIPAL


def _filial_json(valor: str | None, padrao: Any) -> Any:
    try:
        return json.loads(valor) if valor else padrao
    except Exception:
        return None


def _filial_mapa_pedidos() -> dict[str, str]:
    """Pedido (normalizado) → filial, pela fila atual."""
    bruto, _, _ = get_storage("conf_pedidos")
    mapa: dict[str, str] = {}
    for row in _rows_from_storage_value(bruto):
        if isinstance(row, dict):
            numero = normalize(order_number(row))
            if numero:
                mapa.setdefault(numero, filial_da_linha(row))
    return mapa


def _filial_do_registro_etiqueta(rec: dict[str, Any], mapa: dict[str, str]) -> str:
    # O pedido na fila manda (o ADMIN pode ter mudado a filial); sem ele, a filial gravada
    # na etiqueta (a da conta que baixou ou a de quem subiu o arquivo).
    for numero in [rec.get("pedido"), *(rec.get("vinculadoA") or [])]:
        n = normalize(numero)
        if n and n in mapa:
            return mapa[n]
    casa = str(rec.get("casa") or "").strip().lower()
    return casa if casa in CASAS else CASA_PRINCIPAL


def _filial_coleta(valor: Any, filial: str) -> dict[str, Any]:
    obj = valor if isinstance(valor, dict) else {}
    if filial == FILIAL_TODAS:
        return obj
    if filial == CASA_PRINCIPAL:
        return {k: v for k, v in obj.items() if k != "porFilial"}
    por = obj.get("porFilial") if isinstance(obj.get("porFilial"), dict) else {}
    return por.get(filial) if isinstance(por.get(filial), dict) else {}


def storage_filtrar_por_filial(key: str, valor: str | None, filial: str) -> str | None:
    """O valor que a filial enxerga (leitura e resposta de gravação)."""
    if filial == FILIAL_TODAS or valor is None or key not in FILIAL_CHAVES:
        return valor
    dados = _filial_json(valor, None)
    if key in FILIAL_CHAVES_LISTA:
        if not isinstance(dados, list):
            return valor
        return json_dumps([r for r in dados if not isinstance(r, dict) or filial_da_linha(r) == filial])
    if key == "conf_coleta_dia_v1":
        return json_dumps(_filial_coleta(dados, filial))
    if key == "conf_etiquetas":
        if not isinstance(dados, dict):
            return valor
        mapa = _filial_mapa_pedidos()
        registros = dados.get("registros") if isinstance(dados.get("registros"), dict) else {}
        visiveis = {rid: rec for rid, rec in registros.items()
                    if not isinstance(rec, dict) or _filial_do_registro_etiqueta(rec, mapa) == filial}
        banco = dict(dados)
        banco["registros"] = visiveis
        banco["ordem"] = [rid for rid in (dados.get("ordem") or []) if str(rid) in visiveis]
        banco["auditoria"] = [a for a in (dados.get("auditoria") or [])
                              if not isinstance(a, dict) or str(a.get("etiqueta") or "") in visiveis]
        return json_dumps(rebuild_label_bank(banco))
    return valor


def storage_remontar_por_filial(key: str, valor_cliente: str | None, filial: str) -> str | None:
    """Gravação de quem vê uma filial só: junta de volta o que ela não via (estado atual do
    banco) e marca com a filial o que nasceu sem marca. Sem isso, a fila filtrada gravada
    apagaria (ou viraria tombstone ADMIN de) tudo da outra filial."""
    if valor_cliente is None or key not in FILIAL_CHAVES:
        return valor_cliente
    if filial == FILIAL_TODAS:
        if key == "conf_coleta_dia_v1":
            # Quem grava a coleta de Araçatuba vendo tudo não apaga a das outras filiais.
            novo = _filial_json(valor_cliente, {})
            atual = _filial_json(get_storage(key)[0], {})
            if isinstance(novo, dict) and isinstance(atual, dict) and isinstance(atual.get("porFilial"), dict):
                novo.setdefault("porFilial", atual["porFilial"])
                return json_dumps(novo)
        return valor_cliente
    atual_bruto, _, _ = get_storage(key)
    novo = _filial_json(valor_cliente, None)
    atual = _filial_json(atual_bruto, None)
    if key in FILIAL_CHAVES_LISTA:
        if not isinstance(novo, list):
            return valor_cliente
        escondidas = [r for r in (atual if isinstance(atual, list) else [])
                      if isinstance(r, dict) and filial_da_linha(r) != filial]
        # V19.00: a filial de uma linha que já existe é a do BANCO. Uma aba com a cópia de outra
        # filial (seletor trocado em outra aba, ou operador cuja filial o Admin mudou com a tela
        # aberta) mandava as linhas de Araçatuba sem "Casa" — e elas eram remarcadas como Bauru.
        filial_no_banco = {item_id(key, r, i): filial_da_linha(r)
                           for i, r in enumerate(atual if isinstance(atual, list) else []) if isinstance(r, dict)}
        proprias = []
        for i, r in enumerate(novo):
            if isinstance(r, dict):
                if filial_no_banco.get(item_id(key, r, i), filial) != filial:
                    continue  # no banco é de outra filial: vale a do banco (já está em escondidas)
                if str(r.get("Casa") or "").strip() and filial_da_linha(r) != filial:
                    continue  # linha de outra filial que o cliente não deveria ter: vale a do banco
                if filial != CASA_PRINCIPAL and not str(r.get("Casa") or "").strip():
                    r = {**r, "Casa": filial}
            proprias.append(r)
        return json_dumps(proprias + escondidas)
    if key == "conf_coleta_dia_v1":
        base = atual if isinstance(atual, dict) else {}
        coleta = novo if isinstance(novo, dict) else {}
        por = dict(base.get("porFilial") or {}) if isinstance(base.get("porFilial"), dict) else {}
        if filial == CASA_PRINCIPAL:
            return json_dumps({**{k: v for k, v in coleta.items() if k != "porFilial"}, "porFilial": por})
        por[filial] = {k: v for k, v in coleta.items() if k != "porFilial"}
        return json_dumps({**base, "porFilial": por})
    if key == "conf_etiquetas":
        if not isinstance(novo, dict):
            return valor_cliente
        mapa = _filial_mapa_pedidos()
        atual = atual if isinstance(atual, dict) else {}
        atuais = atual.get("registros") if isinstance(atual.get("registros"), dict) else {}
        escondidos = {rid: rec for rid, rec in atuais.items()
                      if isinstance(rec, dict) and _filial_do_registro_etiqueta(rec, mapa) != filial}
        registros: dict[str, Any] = {}
        for rid, rec in (novo.get("registros") or {}).items():
            if rid in escondidos:
                continue
            if isinstance(rec, dict) and filial != CASA_PRINCIPAL and not str(rec.get("casa") or "").strip():
                rec = {**rec, "casa": filial}
            registros[rid] = rec
        registros.update(escondidos)
        banco = dict(novo)
        banco["registros"] = registros
        banco["ordem"] = [*[rid for rid in (novo.get("ordem") or []) if str(rid) in registros and str(rid) not in escondidos],
                          *[rid for rid in (atual.get("ordem") or []) if str(rid) in escondidos]]
        banco["auditoria"] = [*(novo.get("auditoria") or []),
                              *[a for a in (atual.get("auditoria") or [])
                                if isinstance(a, dict) and str(a.get("etiqueta") or "") in escondidos]][-250:]
        return json_dumps(rebuild_label_bank(banco))
    return valor_cliente


def _filial_linhas_do_pedido(pedido: Any) -> list[dict[str, Any]]:
    numero = normalize(pedido)
    bruto, _, _ = get_storage("conf_pedidos")
    return [r for r in _rows_from_storage_value(bruto)
            if isinstance(r, dict) and numero and numero in {normalize(order_number(r)), normalize(r.get("VendaMercadoLivre")),
                                                             normalize(r.get("PackIdMercadoLivre"))}]


def ml_etiqueta_pdf(pedido: str, filial: str) -> bytes:
    """V18.95: etiqueta do ML em PDF (10x15) para a filial sem Zebra (Bauru). Buscada na
    hora, com a CONTA do pedido (a filial pode ter sido mudada pelo ADMIN)."""
    with DB_LOCK:
        linhas = _filial_linhas_do_pedido(pedido)
    if not linhas:
        raise ValueError(f"Pedido {pedido} não está na fila.")
    if filial != FILIAL_TODAS and not any(filial_da_linha(r) == filial for r in linhas):
        raise PermissionError(f"O pedido {pedido} é de outra filial.")
    envio = next((str(r.get("ShipmentIdMercadoLivre") or "").strip() for r in linhas
                  if str(r.get("ShipmentIdMercadoLivre") or "").strip()), "")
    if not envio:
        raise ValueError(f"Pedido {pedido} ainda sem envio do Mercado Livre.")
    with ml_na_casa(ml_casa_da_linha(linhas[0])):
        bruto, _ = ml_api_get_bytes(f"/shipment_labels?{urlencode({'shipment_ids': envio, 'response_type': 'pdf'})}")
    if not bruto.startswith(b"%PDF"):
        raise RuntimeError("O Mercado Livre não devolveu a etiqueta em PDF.")
    return bruto


# V20.29: hosts aceitos para o PDF da etiqueta do TikTok (link fora deles = recusado sem baixar).
TIKTOK_PDF_HOSTS = (".tiktokcdn.com", ".tiktokcdn-us.com", ".ibytedtos.com", ".tiktokglobalshop.com")


def _tiktok_baixar_pdf(url: str) -> bytes:
    """Só a rede. Isolada para teste."""
    with urllib.request.urlopen(urllib.request.Request(url, method="GET"), timeout=30) as resp:
        return resp.read()


def tiktok_etiqueta_pdf(pedido: str, filial: str) -> bytes:
    """V20.29: etiqueta do TikTok em PDF, mesmo contrato do ml_etiqueta_pdf. Pede o link ao
    TikTok a cada impressão (o link vence; nunca é guardado)."""
    with DB_LOCK:
        linhas = _filial_linhas_do_pedido(pedido)
    if not linhas:
        raise ValueError(f"Pedido {pedido} não está na fila.")
    if filial != FILIAL_TODAS and not any(filial_da_linha(r) == filial for r in linhas):
        raise PermissionError(f"O pedido {pedido} é de outra filial.")
    pacote = next((str(r.get("PacoteTikTok") or "").strip() for r in linhas
                   if str(r.get("PacoteTikTok") or "").strip()), "")
    if not pacote:
        raise ValueError(f"Pedido {pedido} ainda sem pacote do TikTok.")
    url = tiktok_documento_url(pacote)  # já recusa link fora de TIKTOK_PDF_HOSTS
    bruto = _tiktok_baixar_pdf(url)
    if not bruto.startswith(b"%PDF"):
        raise RuntimeError("O TikTok não devolveu a etiqueta em PDF.")
    return bruto


def pedido_mover_filial(pedido: str, filial: str, usuario: str) -> dict[str, Any]:
    """V18.95: o ADMIN muda a filial que confere o pedido (decisão do dono, 10/10). Grava
    pelo save_storage como ADMIN: vira override do campo Casa e a importação do ML não
    desfaz. A conta (ContaMercadoLivre) não muda: a etiqueta continua vindo dela."""
    if filial not in CASAS:
        raise ValueError(f"Filial desconhecida: {filial}")
    numero = normalize(pedido)
    with DB_LOCK:
        bruto, _, _ = get_storage("conf_pedidos")
        linhas = _rows_from_storage_value(bruto)
        movidas = 0
        novas = []
        for r in linhas:
            if (isinstance(r, dict) and numero and numero in {normalize(order_number(r)), normalize(r.get("VendaMercadoLivre")),
                                                              normalize(r.get("PackIdMercadoLivre"))}):
                if filial_da_linha(r) != filial:
                    r = {**r, "Casa": filial}
                    if "MERCADO" in normalize(r.get("Marketplace")) and not str(r.get("ContaMercadoLivre") or "").strip():
                        r["ContaMercadoLivre"] = ml_casa_da_linha({**r, "Casa": ""})
                    movidas += 1
            novas.append(r)
        if not any(isinstance(r, dict) and numero in {normalize(order_number(r)), normalize(r.get("VendaMercadoLivre")),
                                                       normalize(r.get("PackIdMercadoLivre"))} for r in linhas):
            raise ValueError(f"Pedido {pedido} não está na fila.")
        if movidas:
            save_storage("conf_pedidos", bruto, json_dumps(novas), False, actor=usuario, actor_role="admin",
                         source_screen="Admin / Pedidos pendentes", change_method=f"Mover de filial para {CASAS[filial]}",
                         client_ip="127.0.0.1")
    return {"ok": True, "pedido": pedido, "filial": filial, "linhas": movidas}


def pedido_da_filial(pedido: Any, filial: str) -> bool:
    """O pedido pode ser tocado por quem vê `filial`? Pedido que não está na fila: sim
    (cada rota decide o que fazer com pedido inexistente)."""
    if filial == FILIAL_TODAS:
        return True
    numero = normalize(pedido)
    if not numero:
        return True
    bruto, _, _ = get_storage("conf_pedidos")
    achou = False
    for row in _rows_from_storage_value(bruto):
        if isinstance(row, dict) and numero in {normalize(order_number(row)), normalize(row.get("VendaMercadoLivre")),
                                                normalize(row.get("PackIdMercadoLivre"))}:
            achou = True
            if filial_da_linha(row) == filial:
                return True
    return not achou


def ensure_ml_casas_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """
            CREATE TABLE IF NOT EXISTS ml_integration_casa_v1894 (
                casa TEXT PRIMARY KEY,
                seller_id TEXT NOT NULL DEFAULT '',
                nickname TEXT NOT NULL DEFAULT '',
                access_token TEXT NOT NULL DEFAULT '',
                refresh_token TEXT NOT NULL DEFAULT '',
                token_type TEXT NOT NULL DEFAULT 'Bearer',
                scope TEXT NOT NULL DEFAULT '',
                expires_at_epoch INTEGER NOT NULL DEFAULT 0,
                connected_at TEXT NOT NULL DEFAULT '',
                updated_at TEXT NOT NULL DEFAULT '',
                last_sync_at TEXT NOT NULL DEFAULT '',
                last_error TEXT NOT NULL DEFAULT ''
            );
            """
        )
        colunas = {r[1] for r in DB.execute("PRAGMA table_info(ml_oauth_state)").fetchall()}
        if "casa" not in colunas:
            DB.execute("ALTER TABLE ml_oauth_state ADD COLUMN casa TEXT NOT NULL DEFAULT 'aracatuba'")
        DB.commit()


def _ml_tabela_conta() -> tuple[str, str, tuple[Any, ...]]:
    """(tabela, condição, parâmetros) da conta ML da casa atual."""
    casa = ml_casa_atual()
    if casa == CASA_PRINCIPAL:
        return "ml_integration", "id=1", ()
    return "ml_integration_casa_v1894", "casa=?", (casa,)


def _ml_conta_atualizar(campos: str, valores: tuple[Any, ...]) -> None:
    """UPDATE na conta ML da casa atual (`campos` = "a=?,b=?")."""
    tabela, onde, params = _ml_tabela_conta()
    with DB_LOCK:
        DB.execute(f"UPDATE {tabela} SET {campos} WHERE {onde}", tuple(valores) + params)
        DB.commit()


def ml_integration_row() -> sqlite3.Row | None:
    tabela, onde, params = _ml_tabela_conta()
    with DB_LOCK:
        return DB.execute(f"SELECT * FROM {tabela} WHERE {onde}", params).fetchone()


def ml_casas_conectadas() -> list[str]:
    """Casas com conta ML conectada (a principal primeiro)."""
    casas = []
    for casa in CASAS:
        try:
            with ml_na_casa(casa):
                row = ml_integration_row()
            if row and str(row["access_token"] or "").strip():
                casas.append(casa)
        except Exception:
            continue
    return casas


def ml_casa_do_seller(seller_id: Any) -> str | None:
    seller_id = str(seller_id or "").strip()
    if not seller_id:
        return None
    for casa in CASAS:
        with ml_na_casa(casa):
            row = ml_integration_row()
        if row and str(row["seller_id"] or "") == seller_id:
            return casa
    return None


def ml_status_payload() -> dict[str, Any]:
    row = ml_integration_row()
    has_access = bool(row and row["access_token"] and row["seller_id"])
    has_refresh = bool(row and str(row["refresh_token"] or "").strip())
    scope_text = str(row["scope"] if row else "")
    scope_set = {x.strip().lower() for x in re.split(r"[\s,]+", scope_text) if x.strip()}
    offline_access = "offline_access" in scope_set
    expires_at = int(row["expires_at_epoch"] or 0) if row else 0
    now_epoch = int(time.time())
    token_expired = bool(has_access and expires_at and expires_at <= now_epoch)
    # Um access_token vencido sem refresh_token NÃO é conexão ativa. Antes isso
    # aparecia como "conectado" e mascarava a falha de Orders/etiquetas após 6h.
    connected = bool(has_access and (not token_expired or has_refresh))
    needs_reconnect = bool(has_access and not has_refresh)
    return {
        "configured": ml_credentials_configured(),
        "connected": connected,
        "needs_reconnect": needs_reconnect,
        "seller_id": str(row["seller_id"] if row else ""),
        "nickname": str(row["nickname"] if row else ""),
        "scope": scope_text,
        "offline_access_granted": offline_access,
        "refresh_token_available": has_refresh,
        "oauth_scope_requested": ML_OAUTH_SCOPE,
        "expires_at_epoch": expires_at,
        "token_expired": token_expired,
        "token_seconds_remaining": max(0, expires_at - now_epoch) if expires_at else 0,
        "connected_at": str(row["connected_at"] if row else ""),
        "updated_at": str(row["updated_at"] if row else ""),
        "last_sync_at": str(row["last_sync_at"] if row else ""),
        "last_error": str(row["last_error"] if row else ""),
        "redirect_uri": ML_REDIRECT_URI,
        "notification_url": ML_NOTIFICATION_URL,
        "client_id_suffix": (ML_CLIENT_ID[-6:] if ML_CLIENT_ID else ""),
        "worker": ml_worker_status_payload(),
    }



ML_ITEM_META_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
ML_ITEM_META_CACHE_LOCK = threading.RLock()
ML_ITEM_META_CACHE_TTL = 20 * 60
ML_ITEM_META_CACHE_MAX = 20000


def _cache_podar(cache: dict[str, tuple[float, Any]], ttl: float, limite: int) -> None:
    """V18.56: os caches em memória tinham TTL mas nenhuma limpeza — entradas
    vencidas ficavam para sempre. Remove as vencidas e, se ainda passar do limite,
    as mais antigas. Chamar com a trava do cache (quando houver)."""
    if len(cache) < limite:
        return
    agora = time.time()
    for chave in [k for k, (t, _) in cache.items() if agora - t >= ttl]:
        cache.pop(chave, None)
    if len(cache) >= limite:
        for chave, _ in sorted(cache.items(), key=lambda kv: kv[1][0])[: len(cache) - limite // 2]:
            cache.pop(chave, None)


def _ml_item_meta_from_body(body: dict[str, Any]) -> dict[str, Any]:
    sku = str(body.get("seller_custom_field") or "").strip()
    if not sku:
        attrs = body.get("attributes") if isinstance(body.get("attributes"), list) else []
        for attr in attrs:
            if not isinstance(attr, dict):
                continue
            if str(attr.get("id") or "").upper() in ("SELLER_SKU", "SKU"):
                sku = str(attr.get("value_name") or attr.get("value_id") or "").strip()
                if sku:
                    break
    return {
        "id": str(body.get("id") or "").replace("MLB", ""),
        "title": str(body.get("title") or "").strip(),
        "sku": sku,
        "available_quantity": max(0, int(body.get("available_quantity") or 0)),
        "status": str(body.get("status") or "").strip().lower(),
        "price": float(body.get("price") or 0),
        "permalink": str(body.get("permalink") or "").strip(),
        "stock_known": True,
    }


def ml_items_meta(ids: list[str]) -> dict[str, dict[str, Any]]:
    """Lê metadados/SKU de anúncios do Mercado Livre.

    V17.68: tenta primeiro o endpoint multi-get autenticado. Algumas aplicações
    recebem HTTP 403 / PolicyAgent nessa rota mesmo com Bearer válido. Nesse caso,
    cai automaticamente para GET /items/{MLB} individual, que é o mesmo caminho
    autenticado já usado pela análise de promoções do sistema.
    """
    normalized: list[str] = []
    seen: set[str] = set()
    for value in ids:
        raw = re.sub(r"\D+", "", str(value or ""))
        if not raw or raw in seen:
            continue
        seen.add(raw)
        normalized.append(raw)
        if len(normalized) >= 100:
            break

    now = time.time()
    result: dict[str, dict[str, Any]] = {}
    missing: list[str] = []

    with ML_ITEM_META_CACHE_LOCK:
        for mlb in normalized:
            cached = ML_ITEM_META_CACHE.get(mlb)
            if cached and now - cached[0] < ML_ITEM_META_CACHE_TTL:
                result[mlb] = dict(cached[1])
            else:
                missing.append(mlb)

    def unknown_meta(mlb: str, error: str = "") -> dict[str, Any]:
        return {
            "id": mlb,
            "title": "",
            "sku": "",
            "available_quantity": None,
            "status": "unknown",
            "price": 0,
            "permalink": "",
            "stock_known": False,
            "error": str(error or "")[:500],
        }

    for start_idx in range(0, len(missing), 20):
        batch = missing[start_idx:start_idx + 20]
        if not batch:
            continue

        fetched: dict[str, dict[str, Any]] = {}
        batch_error = ""
        try:
            ids_param = ",".join("MLB" + item for item in batch)
            payload = ml_api_get("/items?" + urlencode({"ids": ids_param}))
            rows = payload if isinstance(payload, list) else []
            for wrapper in rows:
                if not isinstance(wrapper, dict):
                    continue
                body = wrapper.get("body") if isinstance(wrapper.get("body"), dict) else {}
                meta = _ml_item_meta_from_body(body)
                mlb = str(meta.get("id") or "")
                if mlb:
                    fetched[mlb] = meta
        except Exception as exc:
            batch_error = str(exc)
            policy_blocked = (
                "HTTP 403" in batch_error
                or "PA_UNAUTHORIZED_RESULT_FROM_POLICIES" in batch_error
                or "PolicyAgent" in batch_error
            )
            if not policy_blocked:
                raise

            # Fallback autenticado por item. Esse endpoint já é usado com sucesso
            # em ml_promotions_analysis_payload.load_item().
            for mlb in batch:
                try:
                    body = ml_api_get(f"/items/{quote('MLB' + mlb)}")
                    if isinstance(body, dict):
                        meta = _ml_item_meta_from_body(body)
                        meta_id = str(meta.get("id") or mlb)
                        fetched[meta_id] = meta
                except Exception as item_exc:
                    fetched[mlb] = unknown_meta(mlb, str(item_exc))

        with ML_ITEM_META_CACHE_LOCK:
            for mlb in batch:
                meta = fetched.get(mlb)
                if meta and str(meta.get("sku") or "").strip():
                    meta = dict(meta)
                    meta["stock_known"] = True
                elif meta and meta.get("stock_known") is not False:
                    meta = dict(meta)
                    meta["stock_known"] = True
                elif not meta:
                    meta = unknown_meta(mlb, batch_error)
                ML_ITEM_META_CACHE[mlb] = (time.time(), dict(meta))
                result[mlb] = dict(meta)
            _cache_podar(ML_ITEM_META_CACHE, ML_ITEM_META_CACHE_TTL, ML_ITEM_META_CACHE_MAX)

    return result


def ml_http_json(
    method: str,
    url: str,
    *,
    token: str = "",
    data: dict[str, Any] | None = None,
    headers: dict[str, str] | None = None,
) -> dict[str, Any] | list[Any]:
    body = None
    final_headers = {"Accept": "application/json", "User-Agent": f"NoromakExpedicao/{APP_VERSION}"}
    if token:
        final_headers["Authorization"] = f"Bearer {token}"
    if data is not None:
        body = urlencode({k: "" if v is None else str(v) for k, v in data.items()}).encode("utf-8")
        final_headers["Content-Type"] = "application/x-www-form-urlencoded"
    final_headers.update(headers or {})
    req = urllib.request.Request(url, data=body, headers=final_headers, method=method.upper())
    try:
        with urllib.request.urlopen(req, timeout=ML_HTTP_TIMEOUT) as resp:
            raw = resp.read()
            if not raw:
                return {}
            return json.loads(raw.decode("utf-8", errors="replace"))
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="replace")
        try:
            detail = json.loads(raw)
        except Exception:
            detail = raw
        raise RuntimeError(f"Mercado Livre HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de conexão com Mercado Livre: {exc.reason}") from exc


def ml_store_token(
    payload: dict[str, Any],
    *,
    nickname: str = "",
    preserve_refresh_if_missing: bool = True,
    refresh_expected: bool = False,
) -> None:
    seller_id = str(payload.get("user_id") or "")
    access_token = str(payload.get("access_token") or "")
    refresh_received = str(payload.get("refresh_token") or "").strip()
    token_type = str(payload.get("token_type") or "Bearer")
    scope = str(payload.get("scope") or "")
    expires_in = int(payload.get("expires_in") or 0)
    expires_at = int(time.time()) + max(0, expires_in)
    if not access_token or not seller_id:
        raise RuntimeError("Resposta de token do Mercado Livre incompleta.")

    previous = ml_integration_row()
    refresh_token = refresh_received
    if previous and not refresh_token and preserve_refresh_if_missing:
        refresh_token = str(previous["refresh_token"] or "").strip()

    scope_set = {x.strip().lower() for x in re.split(r"[\s,]+", scope) if x.strip()}
    token_error = ""
    if refresh_expected and not refresh_received:
        if "offline_access" not in scope_set:
            token_error = (
                "Mercado Livre retornou access_token sem refresh_token/offline_access. "
                "O token funcionará somente até expirar (normalmente 6 horas)."
            )
        else:
            token_error = (
                "Mercado Livre retornou offline_access sem refresh_token; a renovação automática não poderá funcionar."
            )

    connected_at = str(previous["connected_at"] or "") if previous else ""
    if not connected_at:
        connected_at = now_iso()
    # V18.94: a mesma conta do ML nunca pode ficar em duas casas (conectar Bauru logado na
    # conta de Araçatuba faria os pedidos entrarem duas vezes, cada um numa fila).
    dona = ml_casa_do_seller(seller_id)
    if dona and dona != ml_casa_atual():
        raise RuntimeError(f"Esta conta do Mercado Livre já está conectada em {CASAS[dona]}. "
                           f"Entre no Mercado Livre com a conta de {CASAS[ml_casa_atual()]} e conecte de novo.")
    if ml_casa_atual() != CASA_PRINCIPAL:
        with DB_LOCK:
            DB.execute(
                """INSERT INTO ml_integration_casa_v1894(
                     casa,seller_id,nickname,access_token,refresh_token,token_type,scope,
                     expires_at_epoch,connected_at,updated_at,last_sync_at,last_error
                   ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
                   ON CONFLICT(casa) DO UPDATE SET
                     seller_id=excluded.seller_id,
                     nickname=CASE WHEN excluded.nickname<>'' THEN excluded.nickname ELSE ml_integration_casa_v1894.nickname END,
                     access_token=excluded.access_token,
                     refresh_token=excluded.refresh_token,
                     token_type=excluded.token_type,
                     scope=excluded.scope,
                     expires_at_epoch=excluded.expires_at_epoch,
                     connected_at=CASE WHEN ml_integration_casa_v1894.connected_at='' THEN excluded.connected_at ELSE ml_integration_casa_v1894.connected_at END,
                     updated_at=excluded.updated_at,
                     last_error=excluded.last_error""",
                (
                    ml_casa_atual(), seller_id, nickname, access_token, refresh_token, token_type, scope,
                    expires_at, connected_at, now_iso(),
                    str(previous["last_sync_at"] or "") if previous else "",
                    token_error,
                ),
            )
            DB.commit()
    else:
        with DB_LOCK:
            DB.execute(
                """INSERT INTO ml_integration(
                     id,seller_id,nickname,access_token,refresh_token,token_type,scope,
                     expires_at_epoch,connected_at,updated_at,last_sync_at,last_error
                   ) VALUES(1,?,?,?,?,?,?,?,?,?,?,?)
                   ON CONFLICT(id) DO UPDATE SET
                     seller_id=excluded.seller_id,
                     nickname=CASE WHEN excluded.nickname<>'' THEN excluded.nickname ELSE ml_integration.nickname END,
                     access_token=excluded.access_token,
                     refresh_token=excluded.refresh_token,
                     token_type=excluded.token_type,
                     scope=excluded.scope,
                     expires_at_epoch=excluded.expires_at_epoch,
                     connected_at=CASE WHEN ml_integration.connected_at='' THEN excluded.connected_at ELSE ml_integration.connected_at END,
                     updated_at=excluded.updated_at,
                     last_error=excluded.last_error""",
                (
                    seller_id, nickname, access_token, refresh_token, token_type, scope,
                    expires_at, connected_at, now_iso(),
                    str(previous["last_sync_at"] or "") if previous else "",
                    token_error,
                ),
            )
            DB.commit()

    try:
        ml_log_event(
            "oauth_token", "/oauth/token", seller_id, ML_CLIENT_ID,
            "REFRESH_TOKEN_OK" if refresh_received else "REFRESH_TOKEN_AUSENTE",
            json_dumps({
                "scope": scope,
                "offline_access": "offline_access" in scope_set,
                "refresh_token_received": bool(refresh_received),
                "expires_in": expires_in,
                "payload_keys": sorted(str(k) for k in payload.keys()),
            }),
        )
    except Exception:
        pass


# V18.56: o refresh_token do ML também é de USO ÚNICO. Seis workers + os handlers
# HTTP pedem o token; quando ele entrava nos últimos 300 s, dois renovavam juntos com
# a mesma chave e um levava invalid_grant (ou gravava um par já ultrapassado).
# Mesma solução da Shopee (V18.01): um renova, os outros esperam e reaproveitam.
ML_TOKEN_LOCK = threading.Lock()
# V18.94: cada casa renova a própria conta; a principal continua no ML_TOKEN_LOCK.
_ML_TOKEN_LOCKS_CASA: dict[str, threading.Lock] = {}


def _ml_token_lock() -> threading.Lock:
    casa = ml_casa_atual()
    if casa == CASA_PRINCIPAL:
        return ML_TOKEN_LOCK
    return _ML_TOKEN_LOCKS_CASA.setdefault(casa, threading.Lock())


def ml_access_token(*, force_refresh: bool = False) -> tuple[str, str]:
    row = ml_integration_row()
    if not row or not row["access_token"]:
        raise RuntimeError("Mercado Livre ainda não está conectado.")
    if not ml_credentials_configured():
        raise RuntimeError("ML_CLIENT_ID / ML_CLIENT_SECRET não estão configurados no servidor.")
    if not force_refresh and int(row["expires_at_epoch"] or 0) > int(time.time()) + 300:
        return str(row["access_token"]), str(row["seller_id"])
    token_antes = str(row["access_token"] or "")
    with _ml_token_lock():
        row = ml_integration_row()
        if not row or not row["access_token"]:
            raise RuntimeError("Mercado Livre ainda não está conectado.")
        expira = int(row["expires_at_epoch"] or 0)
        # Outro renovou enquanto esperávamos: reaproveita (vale também após um 401).
        if str(row["access_token"] or "") != token_antes and expira > int(time.time()) + 60:
            return str(row["access_token"]), str(row["seller_id"])
        if not force_refresh and expira > int(time.time()) + 300:
            return str(row["access_token"]), str(row["seller_id"])
        return _ml_refresh_token_locked(row)


def _ml_refresh_token_locked(row: sqlite3.Row) -> tuple[str, str]:
    refresh_token = str(row["refresh_token"] or "")
    if not refresh_token:
        if int(row["expires_at_epoch"] or 0) <= int(time.time()):
            raise RuntimeError("TOKEN_ML_EXPIRADO_SEM_REFRESH: o access_token venceu e o Mercado Livre não forneceu refresh_token. Orders, etiquetas e custos ficam indisponíveis até uma nova autorização que retorne refresh_token.")
        raise RuntimeError("Refresh token do Mercado Livre não está disponível; o access_token atual ainda está temporariamente válido.")
    payload = ml_http_json(
        "POST",
        f"{ML_API_BASE}/oauth/token",
        data={
            "grant_type": "refresh_token",
            "client_id": ML_CLIENT_ID,
            "client_secret": ML_CLIENT_SECRET,
            "refresh_token": refresh_token,
        },
    )
    if not isinstance(payload, dict):
        raise RuntimeError("Resposta inválida ao renovar o token Mercado Livre.")
    # V18.01: PRESERVE o refresh_token quando o ML responder sem um novo.
    # Com preserve=False, uma resposta "access_token sem refresh_token" (cenário
    # que o próprio ml_store_token já prevê) apagava a chave de renovação e a
    # integração morria até reconectar à mão — derrubando o fim de semana inteiro.
    # Manter a chave anterior é a única chance de continuar renovando.
    ml_store_token(payload, nickname=str(row["nickname"] or ""), preserve_refresh_if_missing=True, refresh_expected=True)
    fresh = ml_integration_row()
    return str(fresh["access_token"]), str(fresh["seller_id"])



def _ml_worker_state_update(**values: Any) -> None:
    with ML_WORKER_STATE_LOCK:
        ML_WORKER_STATE.update(values)


def ml_worker_status_payload() -> dict[str, Any]:
    with ML_WORKER_STATE_LOCK:
        state = dict(ML_WORKER_STATE)
    row = ml_integration_row()
    expires_at = int(row["expires_at_epoch"] or 0) if row else 0
    now_ts = int(time.time())
    state.update({
        "server_worker": True,
        "browser_required": False,
        "server_time": now_iso(),
        "token_expires_at_epoch": expires_at,
        "token_seconds_remaining": max(0, expires_at - now_ts) if expires_at else 0,
        "has_refresh_token": bool(row and str(row["refresh_token"] or "").strip()),
        "ml_connected": bool(row and str(row["access_token"] or "").strip()),
        "token_expired": bool(expires_at and expires_at <= now_ts),
        "new_order_interval_seconds": ML_NEW_ORDER_WATCH_INTERVAL,
        "token_keepalive_interval_seconds": ML_TOKEN_KEEPALIVE_INTERVAL,
        "safety_catchup_interval_seconds": ML_SAFETY_CATCHUP_INTERVAL,
        "safety_catchup_hours": ML_SAFETY_CATCHUP_HOURS,
    })
    return state


def ml_token_keepalive_once() -> dict[str, Any]:
    """Mantém OAuth renovado no servidor, mesmo sem qualquer navegador aberto."""
    checked_at = now_iso()
    row = ml_integration_row()
    if not row or not str(row["access_token"] or "").strip():
        result = {"ok": True, "connected": False, "refreshed": False, "reason": "not_connected"}
        _ml_worker_state_update(last_token_check_at=checked_at, last_error="")
        return result
    expires_at = int(row["expires_at_epoch"] or 0)
    remaining = expires_at - int(time.time())
    try:
        # Renovação proativa evita que o watcher encontre um token vencido no meio da noite.
        force = remaining <= ML_TOKEN_REFRESH_AHEAD_SECONDS
        ml_access_token(force_refresh=force)
        result = {"ok": True, "connected": True, "refreshed": bool(force), "seconds_remaining_before": remaining}
        updates = {"last_token_check_at": checked_at, "last_error": ""}
        if force:
            updates["last_token_refresh_at"] = now_iso()
            ml_log_event("token_keeper", "/oauth/token", str(row["seller_id"] or ""), ML_CLIENT_ID,
                         "TOKEN RENOVADO NO SERVIDOR", json_dumps(result))
        _ml_worker_state_update(**updates)
        return result
    except Exception as exc:
        message = str(exc)[:1200]
        _ml_worker_state_update(last_token_check_at=checked_at, last_error=message)
        try:
            ml_log_event("token_keeper", "/oauth/token", str(row["seller_id"] or ""), ML_CLIENT_ID, "ERRO", message)
        except Exception:
            pass
        return {"ok": False, "connected": True, "refreshed": False, "error": message}


def ml_token_keepalive_loop(stop_event: threading.Event) -> None:
    # Verifica poucos segundos após o boot e depois continuamente na VPS.
    if stop_event.wait(8):
        return
    while not stop_event.is_set():
        ml_token_keepalive_once()
        # V18.94: as outras casas renovam a própria conta (o estado da tela é o da principal).
        for casa in ml_casas_conectadas():
            if casa != CASA_PRINCIPAL:
                try:
                    with ml_na_casa(casa):
                        ml_token_keepalive_once()
                except Exception:
                    pass
        if stop_event.wait(ML_TOKEN_KEEPALIVE_INTERVAL):
            break


def ml_api_get(path_or_url: str, *, headers: dict[str, str] | None = None) -> dict[str, Any] | list[Any]:
    token, _ = ml_access_token()
    url = path_or_url if path_or_url.startswith("http") else f"{ML_API_BASE}{path_or_url}"
    try:
        return ml_http_json("GET", url, token=token, headers=headers)
    except RuntimeError as exc:
        if "HTTP 401" not in str(exc):
            raise
    token, _ = ml_access_token(force_refresh=True)
    return ml_http_json("GET", url, token=token, headers=headers)


def ml_http_bytes(url: str, *, token: str = "", headers: dict[str, str] | None = None) -> tuple[bytes, str]:
    final_headers = {"Accept": "*/*", "User-Agent": f"NoromakExpedicao/{APP_VERSION}"}
    if token:
        final_headers["Authorization"] = f"Bearer {token}"
    final_headers.update(headers or {})
    req = urllib.request.Request(url, headers=final_headers, method="GET")
    try:
        with urllib.request.urlopen(req, timeout=ML_HTTP_TIMEOUT) as resp:
            return resp.read(), str(resp.headers.get("Content-Type") or "")
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Mercado Livre HTTP {exc.code}: {raw}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Falha de conexão com Mercado Livre: {exc.reason}") from exc


def ml_api_get_bytes(path_or_url: str, *, headers: dict[str, str] | None = None) -> tuple[bytes, str]:
    token, _ = ml_access_token()
    url = path_or_url if path_or_url.startswith("http") else f"{ML_API_BASE}{path_or_url}"
    try:
        return ml_http_bytes(url, token=token, headers=headers)
    except RuntimeError as exc:
        if "HTTP 401" not in str(exc):
            raise
    token, _ = ml_access_token(force_refresh=True)
    return ml_http_bytes(url, token=token, headers=headers)



def _promo_float(value: Any, default: float = 0.0) -> float:
    try:
        return float(value if value is not None else default)
    except Exception:
        return float(default)


# V19.65: o JSON do Precificador é grande e era decodificado inteiro a cada consulta (lista
# das Promoções, Demanda, Financeiro, Shopee/Magalu...) — em produção (20/10) isso empilhou
# CPU e memória até o processo chegar a 900 MB. Agora é decodificado uma vez por versão do
# storage: mudou no Precificador (ou na gaveta), a próxima leitura já vê. NÃO alterar o
# objeto devolvido — é compartilhado; quem precisa mudar e gravar continua no get_storage.
_PRECIFICADOR_CACHE: dict[str, Any] = {"versao": None, "dados": {}}
_PRECIFICADOR_CACHE_LOCK = threading.Lock()


def precificador_dados() -> dict[str, Any]:
    with DB_LOCK:
        row = DB.execute("SELECT version, updated_at, length(value) FROM storage WHERE key=?",
                         ("precificador_online_v1",)).fetchone()
    # versão + horário + tamanho: banco restaurado (ou de teste) pode repetir o número da versão
    versao = (id(DB), row[0], row[1], row[2]) if row else None
    with _PRECIFICADOR_CACHE_LOCK:
        if _PRECIFICADOR_CACHE["versao"] == versao and versao is not None:
            return _PRECIFICADOR_CACHE["dados"]
        raw, _, _ = get_storage("precificador_online_v1")
        try:
            dados = json.loads(raw or "{}")
        except Exception:
            dados = {}
        if not isinstance(dados, dict):
            dados = {"products": dados} if isinstance(dados, list) else {}
        _PRECIFICADOR_CACHE.update({"versao": versao, "dados": dados})
        return dados


def _promo_precifier_index() -> dict[str, dict[str, Any]]:
    products = precificador_dados()   # V19.65
    out: dict[str, dict[str, Any]] = {}
    if isinstance(products, dict):
        products = products.get("products") or products.get("produtos") or []
    for product in products if isinstance(products, list) else []:
        if not isinstance(product, dict):
            continue
        sku = str(product.get("sku") or "").strip().upper()
        if sku:
            out[sku] = product
    return out


def _promo_item_sku(item: dict[str, Any]) -> str:
    sku = str(item.get("seller_custom_field") or "").strip()
    if sku:
        return sku
    attrs = item.get("attributes") or []
    for attr in attrs if isinstance(attrs, list) else []:
        if not isinstance(attr, dict):
            continue
        aid = str(attr.get("id") or "").upper()
        if aid in ("SELLER_SKU", "SKU"):
            value = str(attr.get("value_name") or attr.get("value_id") or "").strip()
            if value:
                return value
    return ""


def ml_promotions_analysis_payload(max_items: int = 250, tax_percent: float = 12.0, simulated_discount: float = 10.0) -> dict[str, Any]:
    """Modo somente leitura: cruza Seller Promotions com Precificador/Apollo.

    V16.28: se a rota geral /seller-promotions/users/{seller} for bloqueada por
    PolicyAgent, usa fallback oficial por item: lista anúncios ativos do vendedor e
    consulta /seller-promotions/items/{ITEM_ID}?app_version=v2.
    """
    _, seller_id = ml_access_token()
    precifier = _promo_precifier_index()
    item_cache: dict[str, dict[str, Any]] = {}
    rows: list[dict[str, Any]] = []
    errors: list[str] = []
    max_items = max(1, min(1000, int(max_items or 250)))
    source_mode = "campaigns"
    campaigns: list[dict[str, Any]] = []

    def load_item(item_id: str) -> dict[str, Any]:
        item = item_cache.get(item_id)
        if item is not None:
            return item
        try:
            fetched = ml_api_get(f"/items/{quote(item_id)}")
            item = fetched if isinstance(fetched, dict) else {}
        except Exception as exc:
            item = {"id": item_id, "title": "", "_error": str(exc)}
        item_cache[item_id] = item
        return item

    def append_offer(offer: dict[str, Any], campaign: dict[str, Any]) -> None:
        if len(rows) >= max_items or not isinstance(offer, dict):
            return
        item_id = str(offer.get("id") or offer.get("item_id") or "").strip()
        if not item_id:
            return
        item = load_item(item_id)
        sku = _promo_item_sku(item)
        p = precifier.get(sku.upper()) if sku else None
        cost = None
        curve = ""
        description = str(item.get("title") or "")
        if p:
            cost = _promo_float(p.get("custo"), 0)
            curve = str(p.get("curva") or "").strip().upper()[:1]
            description = str(p.get("produto") or description)
        if sku and (cost is None or cost <= 0):
            try:
                ap = crm_cost_lookup(sku, "promocoes-ml")
                cost = _promo_float(ap.get("custo_medio"), 0)
                curve = str(ap.get("curva_abc") or curve).strip().upper()[:1]
                description = str(ap.get("descricao") or description)
            except Exception:
                pass
        margin_target = {"A": 20.0, "B": 20.0, "C": 17.0, "D": 15.0}.get(curve, 20.0)
        mlcfg = ((p or {}).get("marketplaces") or {}).get("ml") or {}
        commission = _promo_float(mlcfg.get("comissao"), 0.12)
        if commission > 1:
            commission /= 100.0
        fixed_fee = _promo_float(mlcfg.get("taxaFixa"), 0)
        freight = _promo_float(mlcfg.get("frete"), 0)
        original = _promo_float(offer.get("original_price") or item.get("price"), 0)
        buyer_price = _promo_float(offer.get("total_price_for_boosted_offer") or offer.get("price"), 0)
        if buyer_price <= 0:
            buyer_price = _promo_float(offer.get("suggested_discounted_price") or offer.get("max_discounted_price"), 0)
        seller_pct = offer.get("seller_percentage")
        meli_pct = offer.get("meli_percentage")
        if seller_pct is None:
            benefits = campaign.get("benefits") or {}
            seller_pct = benefits.get("seller_percent") if isinstance(benefits, dict) else None
            meli_pct = benefits.get("meli_percent") if isinstance(benefits, dict) else meli_pct
        seller_pct_f = _promo_float(seller_pct, 0)
        meli_pct_f = _promo_float(meli_pct, 0)
        economic_price = original * (1 - seller_pct_f / 100.0) if original > 0 and seller_pct is not None else buyer_price
        if economic_price <= 0:
            economic_price = buyer_price or original
        tax = economic_price * max(0.0, tax_percent) / 100.0
        fee = economic_price * commission + fixed_fee
        profit = None if not cost or economic_price <= 0 else economic_price - cost - fee - freight - tax
        margin = None if profit is None or economic_price <= 0 else profit / economic_price * 100.0
        if margin is None:
            decision = "SEM_CUSTO"
        elif margin < 0:
            decision = "PREJUIZO"
        elif margin + 1e-9 >= margin_target:
            decision = "RECOMENDADA"
        else:
            decision = "ATENCAO"
        denom = 1 - commission - max(0.0, tax_percent) / 100.0 - margin_target / 100.0
        min_safe = (cost + fixed_fee + freight) / denom if cost and denom > 0 else None
        max_discount = max(0.0, (1 - min_safe / original) * 100.0) if min_safe is not None and original > 0 else None
        status = str(offer.get("status") or campaign.get("status") or "").lower()
        promotion_id = str(offer.get("promotion_id") or campaign.get("id") or "").strip()
        promotion_type = str(offer.get("type") or offer.get("promotion_type") or campaign.get("type") or "").strip()
        campaign_name = str(offer.get("name") or campaign.get("name") or promotion_id or promotion_type)
        rows.append({
            "campaign_id": promotion_id, "campaign": campaign_name,
            "promotion_type": promotion_type, "campaign_status": str(campaign.get("status") or ""),
            "item_status": status, "item_id": item_id, "sku": sku, "product": description,
            "original_price": round(original, 2), "buyer_price": round(buyer_price, 2),
            "economic_price": round(economic_price, 2), "seller_percentage": seller_pct_f,
            "meli_percentage": meli_pct_f, "boosted_offer": bool(offer.get("boosted_offer")),
            "boost_amount": round(_promo_float(offer.get("discount_meli_boost_amount"), 0), 2),
            "cost": round(cost, 2) if cost is not None else None, "curve": curve,
            "commission_percent": round(commission * 100, 2), "fixed_fee": round(fixed_fee, 2),
            "freight": round(freight, 2), "tax_percent": round(tax_percent, 2), "tax": round(tax, 2),
            "estimated_fee": round(fee, 2), "profit": round(profit, 2) if profit is not None else None,
            "margin": round(margin, 2) if margin is not None else None, "target_margin": margin_target,
            "min_safe_price": round(min_safe, 2) if min_safe is not None else None,
            "max_safe_discount": round(max_discount, 2) if max_discount is not None else None,
            "decision": decision, "start_date": str(offer.get("start_date") or campaign.get("start_date") or ""),
            "finish_date": str(offer.get("end_date") or campaign.get("finish_date") or ""),
            "candidate_price_min": offer.get("min_discounted_price"), "candidate_price_max": offer.get("max_discounted_price"),
            "suggested_price": offer.get("suggested_discounted_price"),
        })

    # Caminho principal: campanhas do vendedor.
    try:
        campaigns_payload = ml_api_get(f"/seller-promotions/users/{quote(str(seller_id))}?app_version=v2")
        campaigns = campaigns_payload.get("results") if isinstance(campaigns_payload, dict) else []
        campaigns = campaigns if isinstance(campaigns, list) else []
    except Exception as exc:
        msg = str(exc)
        if "PA_UNAUTHORIZED_RESULT_FROM_POLICIES" not in msg and "HTTP 403" not in msg:
            raise
        source_mode = "items_fallback"
        errors.append("Consulta geral de campanhas bloqueada pelo PolicyAgent; usando consulta individual por anúncio.")

    if source_mode == "campaigns":
        for campaign in campaigns:
            if len(rows) >= max_items or not isinstance(campaign, dict):
                break
            promotion_id = str(campaign.get("id") or "").strip()
            promotion_type = str(campaign.get("type") or "").strip()
            if not promotion_id or not promotion_type:
                continue
            search_after = ""
            for _page in range(30):
                if len(rows) >= max_items:
                    break
                params = {"promotion_type": promotion_type, "app_version": "v2", "limit": "50"}
                if search_after:
                    params["search_after"] = search_after
                try:
                    page = ml_api_get(f"/seller-promotions/promotions/{quote(promotion_id)}/items?{urlencode(params)}")
                except Exception as exc:
                    errors.append(f"{promotion_id}: {str(exc)[:180]}")
                    break
                results = page.get("results") if isinstance(page, dict) else []
                results = results if isinstance(results, list) else []
                for offer in results:
                    append_offer(offer, campaign)
                if not isinstance(page, dict):
                    break
                search_after = str(page.get("search_after") or page.get("searchAfter") or "").strip()
                if not search_after or not results:
                    break
    else:
        # Fallback V16.28: anúncios ativos -> promoções associadas a cada item.
        # A API de busca do vendedor usa offset/limit. Mantemos limite pequeno para teste.
        item_ids: list[str] = []
        offset = 0
        wanted = min(max_items, 300)
        for _page in range(10):
            if len(item_ids) >= wanted:
                break
            q = urlencode({"status": "active", "limit": "50", "offset": str(offset)})
            try:
                search = ml_api_get(f"/users/{quote(str(seller_id))}/items/search?{q}")
            except Exception as exc:
                msg = str(exc)
                if "HTTP 403" in msg or "PA_UNAUTHORIZED_RESULT_FROM_POLICIES" in msg:
                    source_mode = "local_simulation"
                    errors.append("A API privada do Mercado Livre está bloqueada pelo PolicyAgent. Exibindo simulação local do Precificador.")
                    break
                raise RuntimeError(f"Fallback não conseguiu listar os anúncios ativos: {exc}") from exc
            ids = search.get("results") if isinstance(search, dict) else []
            ids = ids if isinstance(ids, list) else []
            item_ids.extend(str(x).strip() for x in ids if str(x).strip())
            if len(ids) < 50:
                break
            offset += 50
        item_ids = item_ids[:wanted]
        blocked_item_promos = 0
        for item_id in item_ids:
            if len(rows) >= max_items:
                break
            try:
                promos = ml_api_get(f"/seller-promotions/items/{quote(item_id)}?app_version=v2")
            except Exception as exc:
                msg = str(exc)
                if "HTTP 403" in msg or "PA_UNAUTHORIZED_RESULT_FROM_POLICIES" in msg:
                    blocked_item_promos += 1
                    if blocked_item_promos <= 3:
                        errors.append(f"{item_id}: Seller Promotions bloqueado pelo PolicyAgent")
                    continue
                errors.append(f"{item_id}: {msg[:160]}")
                continue
            if isinstance(promos, dict):
                promos = promos.get("results") or promos.get("promotions") or []
            promos = promos if isinstance(promos, list) else []
            for offer in promos:
                if not isinstance(offer, dict):
                    continue
                offer = dict(offer)
                offer.setdefault("id", item_id)
                pseudo_campaign = {
                    "id": offer.get("id") if str(offer.get("id") or "").startswith(("P-", "C-", "LGH-")) else "",
                    "type": offer.get("type") or "",
                    "status": offer.get("status") or "",
                    "name": offer.get("name") or offer.get("type") or "Promoção do item",
                    "start_date": offer.get("start_date") or "",
                    "finish_date": offer.get("end_date") or "",
                }
                # Em /seller-promotions/items/{ITEM_ID}, o campo id pode ser o id da promoção.
                if pseudo_campaign["id"]:
                    offer["promotion_id"] = pseudo_campaign["id"]
                offer["id"] = item_id
                append_offer(offer, pseudo_campaign)
        if blocked_item_promos and not rows:
            errors.insert(0, f"O aplicativo também foi bloqueado em {blocked_item_promos} consulta(s) individuais de promoção. A autorização do app Mercado Livre precisa liberar Seller Promotions.")
            source_mode = "local_simulation"

    # V16.29: fallback funcional para teste quando o app ML não tem permissão
    # para Seller Promotions/listagem privada. Usa somente dados locais do Precificador.
    if source_mode == "local_simulation" and not rows:
        disc = max(0.0, min(90.0, _promo_float(simulated_discount, 10.0)))
        for sku, p in list(precifier.items())[:max_items]:
            if not isinstance(p, dict):
                continue
            cost = _promo_float(p.get("custo"), 0)
            curve = str(p.get("curva") or "").strip().upper()[:1]
            target = {"A": 20.0, "B": 20.0, "C": 17.0, "D": 15.0}.get(curve, 20.0)
            mlcfg = (p.get("marketplaces") or {}).get("ml") or {}
            commission = _promo_float(mlcfg.get("comissao"), 0.12)
            if commission > 1:
                commission /= 100.0
            fixed_fee = _promo_float(mlcfg.get("taxaFixa"), 0)
            freight = _promo_float(mlcfg.get("frete"), 0)
            denom = 1 - commission - max(0.0, tax_percent)/100.0 - target/100.0
            reference = (cost + fixed_fee + freight) / denom if cost > 0 and denom > 0 else 0.0
            buyer = reference * (1 - disc/100.0) if reference > 0 else 0.0
            tax = buyer * max(0.0, tax_percent)/100.0
            fee = buyer * commission + fixed_fee
            profit = buyer - cost - fee - freight - tax if cost > 0 and buyer > 0 else None
            margin = profit / buyer * 100.0 if profit is not None and buyer > 0 else None
            if margin is None:
                decision = "SEM_CUSTO"
            elif margin < 0:
                decision = "PREJUIZO"
            elif margin + 1e-9 >= target:
                decision = "RECOMENDADA"
            else:
                decision = "ATENCAO"
            rows.append({
                "campaign_id":"SIMULACAO", "campaign":f"Simulação {disc:g}% OFF", "promotion_type":"SIMULACAO_LOCAL",
                "campaign_status":"simulation", "item_status":"candidate", "item_id":"", "sku":sku,
                "product":str(p.get("produto") or ""), "original_price":round(reference,2), "buyer_price":round(buyer,2),
                "economic_price":round(buyer,2), "seller_percentage":disc, "meli_percentage":0.0,
                "boosted_offer":False, "boost_amount":0.0, "cost":round(cost,2) if cost else None, "curve":curve,
                "commission_percent":round(commission*100,2), "fixed_fee":round(fixed_fee,2), "freight":round(freight,2),
                "tax_percent":round(tax_percent,2), "tax":round(tax,2), "estimated_fee":round(fee,2),
                "profit":round(profit,2) if profit is not None else None, "margin":round(margin,2) if margin is not None else None,
                "target_margin":target, "min_safe_price":round(reference,2) if reference else None,
                "max_safe_discount":0.0 if reference else None, "decision":decision, "start_date":"", "finish_date":"",
                "candidate_price_min":None, "candidate_price_max":None, "suggested_price":round(buyer,2) if buyer else None,
                "simulation":True
            })
        errors.append(f"Simulação local ativa: {disc:g}% de desconto sobre o preço de referência calculado pelo Precificador.")

    summary = {
        "total": len(rows), "recommended": sum(r["decision"] == "RECOMENDADA" for r in rows),
        "attention": sum(r["decision"] == "ATENCAO" for r in rows),
        "loss": sum(r["decision"] == "PREJUIZO" for r in rows),
        "missing_cost": sum(r["decision"] == "SEM_CUSTO" for r in rows),
        "candidate": sum(r["item_status"] == "candidate" for r in rows),
        "active": sum(r["item_status"] in ("started", "active") for r in rows),
    }
    return {"ok": True, "mode": "read_only", "source_mode": source_mode, "seller_id": seller_id,
            "summary": summary, "campaigns_count": len(campaigns), "rows": rows,
            "errors": errors[:30], "tax_percent": tax_percent}

def ml_oauth_authorization_url(casa: str = CASA_PRINCIPAL) -> str:
    casa = ml_casa_valida(casa)  # V18.94: a casa que está sendo conectada vai junto no state
    if not ml_credentials_configured():
        raise RuntimeError("Configure ML_CLIENT_ID e ML_CLIENT_SECRET no /home/expedicao/.env antes de conectar.")
    state = secrets.token_urlsafe(32)
    verifier = secrets.token_urlsafe(64)
    challenge = base64.urlsafe_b64encode(hashlib.sha256(verifier.encode("utf-8")).digest()).decode("ascii").rstrip("=")
    now_epoch = int(time.time())
    with DB_LOCK:
        DB.execute("DELETE FROM ml_oauth_state WHERE expires_at_epoch<?", (now_epoch,))
        DB.execute(
            "INSERT INTO ml_oauth_state(state,code_verifier,created_at,expires_at_epoch,casa) VALUES(?,?,?,?,?)",
            (state, verifier, now_iso(), now_epoch + 15 * 60, casa),
        )
        DB.commit()
    # V18.22: o scope PRECISA ir aqui, na autorização. Sem ele o Mercado Livre
    # concede só o padrão da aplicação — sem offline_access e, portanto, SEM
    # refresh_token. Era por isso que a conexão morria a cada ~6h e os pedidos
    # paravam de cair até alguém reconectar à mão. ML_OAUTH_SCOPE existia, mas
    # só era exibido no status; nunca era enviado.
    parametros = {
        "response_type": "code",
        "client_id": ML_CLIENT_ID,
        "redirect_uri": ML_REDIRECT_URI,
        "state": state,
        "code_challenge": challenge,
        "code_challenge_method": "S256",
    }
    if ML_OAUTH_SCOPE:
        parametros["scope"] = ML_OAUTH_SCOPE
    query = urlencode(parametros)
    return f"{ML_AUTH_URL}?{query}"


def ml_exchange_authorization_code(code: str, state: str) -> dict[str, Any]:
    now_epoch = int(time.time())
    with DB_LOCK:
        row = DB.execute("SELECT * FROM ml_oauth_state WHERE state=?", (state,)).fetchone()
        DB.execute("DELETE FROM ml_oauth_state WHERE expires_at_epoch<?", (now_epoch,))
        if row:
            DB.execute("DELETE FROM ml_oauth_state WHERE state=?", (state,))
        DB.commit()
    if not row or int(row["expires_at_epoch"] or 0) < now_epoch:
        raise RuntimeError("Estado OAuth inválido ou expirado. Inicie a conexão novamente.")
    # V18.94: grava o token na conta da casa que pediu a conexão.
    casa = str(row["casa"] or CASA_PRINCIPAL) if "casa" in row.keys() else CASA_PRINCIPAL
    with ml_na_casa(casa):
        status = _ml_exchange_authorization_code_na_casa(code, row)
    status["casa"] = casa
    return status


def _ml_exchange_authorization_code_na_casa(code: str, row: sqlite3.Row) -> dict[str, Any]:
    previous_integration = ml_integration_row()
    recovery_since = str(previous_integration["last_sync_at"] or "") if previous_integration else ""
    payload = ml_http_json(
        "POST",
        f"{ML_API_BASE}/oauth/token",
        data={
            "grant_type": "authorization_code",
            "client_id": ML_CLIENT_ID,
            "client_secret": ML_CLIENT_SECRET,
            "code": code,
            "redirect_uri": ML_REDIRECT_URI,
            "code_verifier": str(row["code_verifier"]),
        },
    )
    if not isinstance(payload, dict):
        raise RuntimeError("Resposta inválida do OAuth Mercado Livre.")
    ml_store_token(payload, preserve_refresh_if_missing=False, refresh_expected=True)
    token, _ = ml_access_token()
    me = ml_http_json("GET", f"{ML_API_BASE}/users/me", token=token)
    if isinstance(me, dict):
        nickname = str(me.get("nickname") or me.get("first_name") or "")
        if nickname:
            current = ml_integration_row()
            ml_store_token(
                {
                    "user_id": current["seller_id"],
                    "access_token": current["access_token"],
                    "refresh_token": current["refresh_token"],
                    "token_type": current["token_type"],
                    "scope": current["scope"],
                    "expires_in": max(0, int(current["expires_at_epoch"]) - int(time.time())),
                },
                nickname=nickname,
            )
    status = ml_status_payload()
    status["recovery_since"] = recovery_since
    return status


def _ml_parse_iso_date(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    match = re.match(r"^(\d{4})-(\d{2})-(\d{2})", text)
    return "-".join(match.groups()) if match else ""


def _ml_logistic_type(shipment: dict[str, Any] | None) -> str:
    shipment = shipment or {}
    logistic = shipment.get("logistic") if isinstance(shipment.get("logistic"), dict) else {}
    shipping_option = shipment.get("shipping_option") if isinstance(shipment.get("shipping_option"), dict) else {}
    candidates = [
        logistic.get("type"),
        shipment.get("logistic_type"),
        shipping_option.get("logistic_type"),
    ]
    for value in candidates:
        text = str(value or "").strip().lower()
        if text:
            return text
    return ""


def _ml_is_full_shipment(shipment: dict[str, Any] | None) -> bool:
    logistic_type = _ml_logistic_type(shipment)
    if logistic_type in {"fulfillment", "full"}:
        return True
    tags = shipment.get("tags") if isinstance(shipment, dict) and isinstance(shipment.get("tags"), list) else []
    return any(str(tag or "").strip().lower() in {"fulfillment", "full"} for tag in tags)



def _nfe_xml_dest_name(xml_text: str) -> str:
    """Extrai dest/xNome quando o arquivo fiscal persistido for XML NF-e."""
    text = str(xml_text or "").strip()
    if not text or "<" not in text or "xNome" not in text:
        return ""
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(text.encode("utf-8", errors="ignore"))
        for dest in root.iter():
            if str(dest.tag).split("}")[-1].lower() != "dest":
                continue
            for child in list(dest):
                if str(child.tag).split("}")[-1].lower() == "xnome":
                    return " ".join(str(child.text or "").split()).strip()
    except Exception:
        return ""
    return ""


def _zpl_decode_fh_text(value: Any) -> str:
    """Decodifica sequências ^FH do ZPL, inclusive UTF-8 (_C3_A7 etc.)."""
    text = str(value or "")
    def repl(match: re.Match[str]) -> str:
        seq = match.group(0)
        try:
            raw = bytes(int(x, 16) for x in re.findall(r"_([0-9A-Fa-f]{2})", seq))
            return raw.decode("utf-8", errors="replace")
        except Exception:
            return seq
    text = re.sub(r"(?:_[0-9A-Fa-f]{2})+", repl, text)
    return " ".join(text.replace("\\&", " ").split()).strip()


def _nfe_name_candidate(value: Any) -> str:
    text = _zpl_decode_fh_text(value)
    text = re.sub(r"^[\s:;\-–—]+|[\s:;\-–—]+$", "", text).strip()
    if not (4 <= len(text) <= 120) or not re.search(r"[A-Za-zÀ-ÿ]", text):
        return ""
    norm = normalize(text)
    blocked = (
        "DESTINATARIO", "DESTINATÁRIO", "REMETENTE", "NOME RAZAO SOCIAL", "NOME RAZÃO SOCIAL",
        "ENDERECO", "ENDEREÇO", "MUNICIPIO", "MUNICÍPIO", "CEP", "CPF", "CNPJ", "CHAVE DE ACESSO",
        "DANFE", "NOTA FISCAL", "INSCRICAO", "INSCRIÇÃO", "BAIRRO", "FONE", "UF", "DATA DE EMISSAO",
        "MERCADO LIVRE", "NOROMAK CAMINHOES E ONIBUS", "NOROMAK CAMINHÕES E ÔNIBUS"
    )
    if any(norm == normalize(x) or norm.startswith(normalize(x) + " ") for x in blocked):
        return ""
    # Nome/razão social deve ter ao menos duas partes, exceto razão social longa sem espaço incomum.
    if len(text.split()) < 2:
        return ""
    return text


def _nfe_name_from_zpl(zpl: str) -> str:
    text = str(zpl or "")
    if not text:
        return ""
    xml_name = _nfe_xml_dest_name(text)
    if xml_name:
        return xml_name
    fields = [_zpl_decode_fh_text(x) for x in re.findall(r"\^FD([\s\S]*?)\^FS", text, flags=re.IGNORECASE)]
    fields = [x for x in fields if x]
    # 1) Nome no mesmo campo do rótulo.
    for field in fields:
        m = re.search(r"(?:DESTINAT[ÁA]RIO|NOME\s*/?\s*RAZ[ÃA]O\s+SOCIAL|CLIENTE)\s*[:\-]\s*(.+)$", field, flags=re.I)
        if m:
            candidate = _nfe_name_candidate(m.group(1))
            if candidate:
                return candidate
    # 2) Nome logo após NOME/RAZÃO SOCIAL; é o padrão mais seguro em DANFE.
    label_indexes = []
    for i, field in enumerate(fields):
        norm = normalize(field)
        if ("NOME" in norm and "RAZAO" in norm and "SOCIAL" in norm) or norm in {"DESTINATARIO", "DESTINATÁRIO"}:
            label_indexes.append(i)
    for i in label_indexes:
        for field in fields[i+1:i+7]:
            candidate = _nfe_name_candidate(field)
            if candidate:
                return candidate
    return ""


def _walk_string_values(value: Any):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for child in value.values():
            yield from _walk_string_values(child)
    elif isinstance(value, list):
        for child in value:
            yield from _walk_string_values(child)


def _nfe_name_from_label_record(record: dict[str, Any]) -> str:
    """Lê o nome diretamente do arquivo fiscal/etiqueta que já está no banco."""
    if not isinstance(record, dict):
        return ""
    # Campos explícitos, caso uma versão/importador já os tenha extraído.
    meta = record.get("metadados") if isinstance(record.get("metadados"), dict) else {}
    for source in (record, meta):
        for key in ("nomeNFe", "nome_nfe", "destinatario", "destinatário", "cliente", "xNome", "razaoSocial", "razãoSocial"):
            candidate = _nfe_name_candidate(source.get(key))
            if candidate:
                return candidate
    # Prioriza DANFE/XML; depois procura qualquer string do registro que contenha XML NF-e.
    for key in ("danfe", "xml", "nfe_xml", "nota_xml", "conteudo_xml"):
        raw = record.get(key)
        if isinstance(raw, str) and raw.strip():
            name = _nfe_xml_dest_name(raw) or _nfe_name_from_zpl(raw)
            if name:
                return name
    for raw in _walk_string_values(record):
        if "<" in raw and "xNome" in raw:
            name = _nfe_xml_dest_name(raw)
            if name:
                return name
    return ""


def _ml_aliases_from_values(*values: Any) -> set[str]:
    aliases: set[str] = set()
    for raw in values:
        if isinstance(raw, (list, tuple, set)):
            aliases.update(_ml_aliases_from_values(*raw))
            continue
        text = str(raw or "").strip()
        if not text:
            continue
        aliases.add(normalize(text))
        digits = re.sub(r"\D+", "", text)
        if digits:
            aliases.update(_ml_order_aliases(digits, ""))
    return {normalize(x) for x in aliases if normalize(x)}


def ml_update_pending_names_from_uploaded_nfe() -> dict[str, Any]:
    """Reprocessa pedidos pendentes usando a NF-e/DANFE já vinculada no banco de etiquetas.

    Não depende de OAuth nem de uma nova consulta ao Mercado Livre. Somente altera
    conf_pedidos (pendentes), nunca histórico/concluídos.
    """
    orders_raw, _, _ = get_storage("conf_pedidos")
    labels_raw, _, _ = get_storage("conf_etiquetas")
    pending = _rows_from_storage_value(orders_raw)
    try:
        bank = json.loads(labels_raw or "{}")
    except Exception:
        bank = {}
    records = bank.get("registros") if isinstance(bank, dict) and isinstance(bank.get("registros"), dict) else {}

    # Indexa cada arquivo fiscal vinculado por todas as chaves conhecidas.
    nfe_by_alias: dict[str, tuple[str, str]] = {}
    records_with_name = 0
    records_examined = 0
    for rid, rec in records.items():
        if not isinstance(rec, dict):
            continue
        marketplace = normalize(rec.get("marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        records_examined += 1
        name = _nfe_name_from_label_record(rec)
        if not name:
            continue
        records_with_name += 1
        meta = rec.get("metadados") if isinstance(rec.get("metadados"), dict) else {}
        aliases = _ml_aliases_from_values(
            rec.get("pedido"), rec.get("vinculadoA"), rec.get("chaves"),
            meta.get("pedido"), meta.get("venda"), meta.get("pack_id"), meta.get("shipment_id"),
            meta.get("nf"), meta.get("chaveAcesso"), meta.get("rastreio"),
        )
        for alias in aliases:
            nfe_by_alias.setdefault(alias, (name, str(rid)))

    pending_order_keys: dict[str, list[dict[str, Any]]] = {}
    for row in pending:
        if not isinstance(row, dict):
            continue
        marketplace = normalize(row.get("Marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        order_key = normalize(order_number(row) or row.get("VendaMercadoLivre") or row.get("PackIdMercadoLivre"))
        if order_key:
            pending_order_keys.setdefault(order_key, []).append(row)

    updated_orders = 0
    updated_rows = 0
    already_equal = 0
    no_linked_nfe = 0
    details = []
    timestamp = now_iso()
    for order_key, rows in pending_order_keys.items():
        aliases: set[str] = set()
        for row in rows:
            aliases.update(_ml_aliases_from_values(
                order_number(row), row.get("VendaMercadoLivre"), row.get("PackIdMercadoLivre"),
                row.get("ShipmentIdMercadoLivre"), row.get("Código de Rastreio"),
                row.get("NF"), row.get("Nota Fiscal"), row.get("Chave de Acesso"),
            ))
        found = next((nfe_by_alias[a] for a in aliases if a in nfe_by_alias), None)
        if not found:
            no_linked_nfe += 1
            continue
        name, rid = found
        changed = 0
        for row in rows:
            if str(row.get("Cliente") or "").strip() != name:
                row["Cliente"] = name
                changed += 1
            row["NomeNFeArquivo"] = name
            row["FonteNomeClienteMercadoLivre"] = "nfe_arquivo_vinculada"
            row["NomeNFeAtualizadoEm"] = timestamp
        if changed:
            updated_orders += 1
            updated_rows += changed
        else:
            already_equal += 1
        if len(details) < 60:
            details.append({"pedido": order_number(rows[0]), "nome": name, "etiqueta": rid, "linhas": changed})

    if updated_rows:
        save_storage(
            "conf_pedidos", orders_raw, json_dumps(pending), False,
            actor="sistema", actor_role="sistema", source_screen="Admin / Integrações",
            change_method="Atualizar nomes pelas NF-e já vinculadas", client_ip="127.0.0.1",
            allow_completed_reimport=False,
        )
    return {
        "ok": True,
        "pending_orders": len(pending_order_keys),
        "invoice_records_examined": records_examined,
        "invoice_records_with_name": records_with_name,
        "updated_orders": updated_orders,
        "updated_rows": updated_rows,
        "already_equal": already_equal,
        "without_linked_invoice_name": no_linked_nfe,
        "details": details,
    }


def _ml_billing_details(order: dict[str, Any]) -> dict[str, Any]:
    """Obtém exclusivamente nome/razão social de Dados para NF-e do Mercado Livre.

    Fluxo oficial: /orders/{id} -> buyer.billing_info.id ->
    /orders/billing-info/{site_id}/{billing_info_id}.

    Durante a migração do ML algumas contas ainda devolvem billing-info em formatos
    diferentes (objeto fiscal direto na raiz, endpoint legado e headers distintos).
    Esta função aceita essas variações SEM usar nickname/username/destinatário.
    """
    buyer = order.get("buyer") if isinstance(order.get("buyer"), dict) else {}
    raw_embedded = buyer.get("billing_info")
    raw_root_billing = order.get("billing_info")
    embedded = raw_embedded if isinstance(raw_embedded, dict) else {}
    root_billing = raw_root_billing if isinstance(raw_root_billing, dict) else {}
    billing_id = str(
        embedded.get("id") or root_billing.get("id")
        or (raw_embedded if isinstance(raw_embedded, (str, int)) else "")
        or (raw_root_billing if isinstance(raw_root_billing, (str, int)) else "") or ""
    ).strip()
    site_id = str(
        order.get("site_id")
        or ((order.get("context") or {}).get("site") if isinstance(order.get("context"), dict) else "")
        or "MLB"
    ).strip().upper() or "MLB"
    order_id = str(order.get("id") or "").strip()
    errors: list[str] = []
    # V17.84: o documento fiscal já vinha no mesmo payload do nome e era descartado.
    # extract_name() preenche este dicionário ao encontrar identification.
    documento: dict[str, str] = {}

    def extract_name(payload: Any) -> str:
        if not isinstance(payload, dict):
            return ""

        fiscal_buyer = payload.get("buyer") if isinstance(payload.get("buyer"), dict) else {}
        info = fiscal_buyer.get("billing_info") if isinstance(fiscal_buyer.get("billing_info"), dict) else {}
        if not info and isinstance(payload.get("billing_info"), dict):
            info = payload["billing_info"]

        # Algumas respostas do endpoint legado/V2 entregam o próprio objeto
        # billing_info na raiz, por exemplo {"name":..., "last_name":...}.
        if not info and any(k in payload for k in (
            "name", "first_name", "last_name", "surname", "business_name",
            "corporate_name", "company_name", "additional_info", "identification"
        )):
            info = payload

        if not isinstance(info, dict) or not info:
            return ""

        additional = info.get("additional_info") if isinstance(info.get("additional_info"), list) else []
        vals: dict[str, str] = {}
        for item in additional:
            if not isinstance(item, dict):
                continue
            key = str(item.get("type") or item.get("key") or item.get("name") or "").strip().upper()
            value = str(item.get("value") or item.get("description") or "").strip()
            if key and value and key not in vals:
                vals[key] = value

        first = str(
            info.get("name") or info.get("first_name")
            or vals.get("FIRST_NAME") or vals.get("NAME") or ""
        ).strip()
        last = str(
            info.get("last_name") or info.get("surname")
            or vals.get("LAST_NAME") or vals.get("SURNAME") or ""
        ).strip()
        business = str(
            info.get("business_name") or info.get("corporate_name") or info.get("company_name")
            or vals.get("BUSINESS_NAME") or vals.get("CORPORATE_NAME") or vals.get("COMPANY_NAME") or ""
        ).strip()
        identification = info.get("identification") if isinstance(info.get("identification"), dict) else {}
        doc_type = str(identification.get("type") or vals.get("DOC_TYPE") or "").strip().upper()

        # V17.84: guarda o CPF/CNPJ do comprador. O Linx DMS localiza o cliente
        # por documento, então sem isto não há como atualizar cadastro de venda ML.
        # Só grava a primeira ocorrência: o payload oficial vem antes do legado.
        numero = re.sub(r"\D", "", str(identification.get("number") or vals.get("DOC_NUMBER") or ""))
        if numero and not documento.get("number"):
            documento["number"] = numero
            documento["type"] = doc_type or ("CNPJ" if len(numero) == 14 else "CPF")

        # No MLB pessoa jurídica vem normalmente com name=razão social.
        if doc_type == "CNPJ":
            return business or first
        if business and not (first or last):
            return business
        return " ".join(x for x in (first, last) if x).strip() or business

    # Se o próprio /orders já trouxe o objeto fiscal completo, aproveita.
    embedded_name = extract_name({"buyer": {"billing_info": embedded}}) if embedded else ""
    if embedded_name and any(k in embedded for k in (
        "name", "first_name", "business_name", "corporate_name", "identification", "additional_info"
    )):
        return {"name": embedded_name, "billing_info_id": billing_id, "source": "order_embedded",
                "doc_type": documento.get("type", ""), "doc_number": documento.get("number", ""), "errors": []}

    # Endpoint oficial atual. Testa sem header primeiro e depois as duas grafias
    # encontradas nos contratos do ML durante a migração.
    if billing_id:
        endpoint = f"/orders/billing-info/{quote(site_id)}/{quote(billing_id)}"
        for hdr, label in (
            (None, "billing_info_current"),
            ({"X-Api-Version": "2"}, "billing_info_api_v2"),
            ({"x-version": "2"}, "billing_info_x_v2"),
        ):
            try:
                payload = ml_api_get(endpoint, headers=hdr)
                name = extract_name(payload)
                if name:
                    return {"name": name, "billing_info_id": billing_id, "source": label,
                            "doc_type": documento.get("type", ""), "doc_number": documento.get("number", ""), "errors": errors}
                errors.append(f"{label} respondeu sem nome fiscal")
            except Exception as exc:
                errors.append(f"{label}: {str(exc)[:400]}")
    else:
        errors.append("buyer.billing_info.id ausente em /orders")

    # Compatibilidade temporária enquanto o endpoint legado ainda responde em
    # determinadas contas. Aceita underscore e hífen e payload fiscal direto.
    if order_id:
        legacy_paths = (
            f"/orders/{quote(order_id)}/billing_info",
            f"/orders/{quote(order_id)}/billing-info",
        )
        header_variants = (
            ({"X-Api-Version": "2"}, "api_v2"),
            ({"x-version": "2"}, "x_v2"),
            (None, "v1"),
        )
        for legacy_path in legacy_paths:
            for hdr, suffix in header_variants:
                try:
                    payload = ml_api_get(legacy_path, headers=hdr)
                    name = extract_name(payload)
                    if name:
                        # Tenta também descobrir o id se ele vier somente no fallback.
                        fallback_buyer = payload.get("buyer") if isinstance(payload, dict) and isinstance(payload.get("buyer"), dict) else {}
                        fallback_info = fallback_buyer.get("billing_info") if isinstance(fallback_buyer.get("billing_info"), dict) else {}
                        fallback_id = str(fallback_info.get("id") or (payload.get("id") if isinstance(payload, dict) else "") or "").strip()
                        return {
                            "name": name,
                            "billing_info_id": billing_id or fallback_id,
                            "source": f"legacy_{suffix}",
                            "doc_type": documento.get("type", ""),
                            "doc_number": documento.get("number", ""),
                            "errors": errors,
                        }
                    errors.append(f"legacy_{suffix} respondeu sem nome fiscal")
                except Exception as exc:
                    errors.append(f"legacy_{suffix}: {str(exc)[:400]}")

    return {"name": "", "billing_info_id": billing_id, "source": "",
            "doc_type": documento.get("type", ""), "doc_number": documento.get("number", ""), "errors": errors[-8:]}

def _ml_real_buyer_name(order: dict[str, Any]) -> str:
    """Nome real do comprador da order, sem usar nickname.

    Usado apenas enquanto Dados para NF-e ainda não estão disponíveis.
    Nunca usa destinatário/receiver_name e nunca usa nickname/username.
    """
    buyer = order.get("buyer") if isinstance(order.get("buyer"), dict) else {}
    first = str(buyer.get("first_name") or buyer.get("name") or "").strip()
    last = str(buyer.get("last_name") or buyer.get("surname") or "").strip()
    full = " ".join(x for x in (first, last) if x).strip()
    if full:
        return full

    # Algumas variantes da API encapsulam os dados pessoais em buyer.user.
    user = buyer.get("user") if isinstance(buyer.get("user"), dict) else {}
    first = str(user.get("first_name") or user.get("name") or "").strip()
    last = str(user.get("last_name") or user.get("surname") or "").strip()
    return " ".join(x for x in (first, last) if x).strip()

def _ml_dispatch_date(shipment_id: str, shipment: dict[str, Any] | None) -> str:
    """Data limite de despacho prometida pelo Mercado Livre.

    Prioriza /shipments/{id}/sla.expected_date. O campo antigo
    estimated_handling_limit permanece somente como fallback de compatibilidade.
    """
    if shipment_id and not _ml_is_full_shipment(shipment):
        try:
            sla = ml_api_get(f"/shipments/{quote(str(shipment_id))}/sla")
            if isinstance(sla, dict):
                parsed = _ml_parse_iso_date(sla.get("expected_date"))
                if parsed:
                    return parsed
        except Exception:
            pass

    shipment = shipment or {}
    shipping_option = shipment.get("shipping_option") if isinstance(shipment.get("shipping_option"), dict) else {}
    candidates = [
        shipping_option.get("estimated_handling_limit"),
        shipment.get("estimated_handling_limit"),
    ]
    for value in candidates:
        parsed = _ml_parse_iso_date(value)
        if parsed:
            return parsed
    return datetime.now().astimezone().date().isoformat()


def _kit_sku_aliases(value: Any, strip_kit_prefix: bool = True) -> list[str]:
    """Gera aliases robustos para localizar SKU de kit.

    Além das formas normal/compacta, aceita prefixos operacionais usados nos
    anúncios, como KIT-, KIT2-, KIT3-, etc. Ex.: KIT3-KS001 também procura KS001.

    V18.03: `strip_kit_prefix` só pode ser True na BUSCA (um pedido "KIT2-X" acha
    um cadastro gravado como "X"). Na INDEXAÇÃO do catálogo tem que ser False —
    senão o kit "KIT2-X" fica indexado também sob "X" e a venda do produto SIMPLES
    "X" casa com o kit e a quantidade dobra (bug do 152285-0893014105).
    """
    raw = str(value or "").strip().upper()
    if not raw:
        return []

    candidates = [raw]
    if strip_kit_prefix:
        # Prefixos operacionais comuns do marketplace não fazem parte necessariamente
        # do SKU-base usado no Cadastro de Kits.
        stripped = re.sub(r"^KIT\s*\d*\s*[-_./: ]+", "", raw, flags=re.I).strip()
        if stripped and stripped != raw:
            candidates.append(stripped)

        # Também cobre KIT3KS001 (sem separador): remove apenas quando há conteúdo
        # suficiente após o prefixo, evitando transformar SKUs curtos indevidamente.
        m = re.match(r"^KIT\s*\d+(?=[A-Z0-9])(.+)$", raw, flags=re.I)
        if m and m.group(1).strip():
            candidates.append(m.group(1).strip())

    out: list[str] = []
    for candidate in candidates:
        exact = normalize(candidate)
        compact = "".join(ch for ch in candidate if ch.isalnum())
        for key in (exact, compact):
            if key and key not in out:
                out.append(key)
    return out


def _kit_catalog_lookup(catalog: dict[str, dict[str, Any]], sku: Any) -> dict[str, Any] | None:
    for key in _kit_sku_aliases(sku):
        hit = catalog.get(key)
        if hit:
            return hit
    return None


def _infer_quantity_kit_from_sku(sku: Any) -> dict[str, Any] | None:
    """Reconhece kits homogêneos codificados como KIT2-SKU, KIT3-SKU etc.

    O Cadastro de Kits explícito continua tendo prioridade. Este fallback só é usado
    quando não há composição cadastrada e transforma, por exemplo, KIT3-KS001
    em 3 unidades do componente KS001.
    """
    raw = str(sku or "").strip()
    if not raw:
        return None
    # V18.19: o separador entre a quantidade e o SKU-base é OBRIGATÓRIO e a
    # quantidade tem teto. Sem isso, "KIT" usado como RÓTULO seguido de códigos de
    # produto (ex.: "kit27200154", "KIT10291406 - 99090203") era lido como
    # "2.720.015 unidades do 4" / "10.291.406 unidades do 99090203" e explodia a
    # Demanda de Compra e a Demanda Full. Kit homogêneo real é "KITn-BASE" (n pequeno).
    m = re.match(r"^KIT\s*(\d+)\s*[-_./: ]+\s*(.+?)\s*$", raw, flags=re.I)
    if not m:
        return None
    try:
        qty = int(m.group(1))
    except Exception:
        return None
    base = str(m.group(2) or "").strip()
    if qty < 2 or qty > 99 or not base:
        return None
    return {
        "sku_kit": raw,
        "nome": raw,
        "ativo": True,
        "componentes": [{"sku": base, "quantidade": qty}],
        "inferido_por_prefixo": True,
    }


def _load_kit_catalog() -> dict[str, dict[str, Any]]:
    """Carrega o cadastro compartilhado de kits indexado pelo SKU do kit."""
    raw, _, _ = get_storage("conf_kits")
    try:
        rows = json.loads(raw or "[]")
    except Exception:
        rows = []
    catalog: dict[str, dict[str, Any]] = {}
    if not isinstance(rows, list):
        return catalog
    for row in rows:
        if not isinstance(row, dict):
            continue
        kit_sku = str(row.get("sku_kit") or row.get("SKU Kit") or row.get("sku") or "").strip()
        if not kit_sku:
            continue
        components_raw = row.get("componentes")
        if not isinstance(components_raw, list):
            components_raw = []
        components: list[dict[str, Any]] = []
        for comp in components_raw:
            if not isinstance(comp, dict):
                continue
            sku = str(comp.get("sku") or comp.get("SKU") or "").strip()
            try:
                qty = int(comp.get("quantidade") or comp.get("qtd") or comp.get("Quantidade") or 0)
            except (TypeError, ValueError):
                qty = 0
            if sku and qty > 0:
                components.append({"sku": sku, "quantidade": qty})
        if not components:
            continue
        entry = {
            "sku_kit": kit_sku,
            "nome": str(row.get("nome") or row.get("Nome") or kit_sku).strip() or kit_sku,
            "componentes": components,
            "ativo": bool(row.get("ativo", True)),
        }
        # V18.03: indexa SÓ pelo SKU do próprio kit (sem tirar o prefixo KIT),
        # para o kit "KIT2-X" nunca vazar para a venda do produto simples "X".
        for alias in _kit_sku_aliases(kit_sku, strip_kit_prefix=False):
            catalog.setdefault(alias, entry)
    return catalog


def full_kit_compositions(skus: list[Any]) -> dict[str, dict[str, Any]]:
    """V17.96: composição dos kits presentes na planilha da Demanda Full.

    Mesma regra dos pedidos ML: Cadastro de Kits primeiro, depois o prefixo
    KIT2-/KIT3-. SKU comum fica de fora. Como o cadastro também é indexado pelo
    SKU sem o prefixo KIT, um SKU comum só vira kit quando é exatamente o SKU
    cadastrado — senão "X" herdaria a composição de "KIT2-X".
    """
    catalog = _load_kit_catalog()
    out: dict[str, dict[str, Any]] = {}
    for value in skus:
        sku = str(value or "").strip()
        if not sku or sku in out:
            continue
        entry = _kit_catalog_lookup(catalog, sku)
        fonte = "cadastro"
        if entry and (not entry.get("ativo", True) or (
            not re.match(r"^KIT", sku, flags=re.I) and normalize(entry.get("sku_kit")) != normalize(sku)
        )):
            entry = None
        if not entry:
            entry = _infer_quantity_kit_from_sku(sku)
            fonte = "prefixo"
        if not entry:
            continue
        comps = [
            {"sku": str(c.get("sku") or "").strip(), "quantidade": int(c.get("quantidade") or 0)}
            for c in entry.get("componentes") or []
            if str(c.get("sku") or "").strip() and int(c.get("quantidade") or 0) > 0
        ]
        if not comps or (len(comps) == 1 and comps[0]["quantidade"] == 1 and normalize(comps[0]["sku"]) == normalize(sku)):
            continue
        out[sku] = {"componentes": comps, "fonte": fonte, "nome": str(entry.get("nome") or sku)}
    return out


def full_anuncios_vendas(anuncios: list[Any], dias: int = 30) -> dict[str, dict[str, Any]]:
    """V18.61: vendas ML dos últimos `dias` por anúncio, para a Demanda Full.

    O relatório Full lista os anúncios de cada produto só pelo número
    ("1079290698 | 3615301139"); a tela precisa saber qual deles vende para
    montar a remessa. Aceita com ou sem o prefixo MLB. Anúncio sem venda volta
    com zero. Somente leitura de `vendas_v1799` (não distingue Full de Flex).
    """
    ids: list[str] = []
    for value in anuncios:
        digitos = re.sub(r"\D", "", str(value or ""))
        mlb = f"MLB{digitos}" if digitos else ""
        if mlb and mlb not in ids:
            ids.append(mlb)
    out = {mlb: {"unidades": 0, "pedidos": 0, "titulo": ""} for mlb in ids}
    if not ids:
        return out
    inicio = (datetime.now(BR_TZ) - timedelta(days=dias)).strftime("%Y-%m-%d")
    with DB_LOCK:
        for i in range(0, len(ids), 500):
            lote = ids[i:i + 500]
            marcas = ",".join("?" * len(lote))
            rows = DB.execute(
                f"SELECT anuncio, COALESCE(SUM(qty),0) AS unidades, COUNT(DISTINCT order_id) AS pedidos, MAX(title) AS titulo "
                f"FROM vendas_v1799 WHERE marketplace='ml' AND sale_day >= ? AND anuncio IN ({marcas}) GROUP BY anuncio",
                (inicio, *lote),
            ).fetchall()
            for r in rows:
                out[r["anuncio"]] = {"unidades": int(r["unidades"] or 0), "pedidos": int(r["pedidos"] or 0), "titulo": str(r["titulo"] or "")}
    return out


# V19.03: o ML recusa alguns produtos no Full. Tombstone do ADMIN por código:
# nenhuma rodada tira daqui, só full_nao_aceito_liberar.
def _full_codigo(valor: Any) -> str:
    return str(valor or "").strip().upper()


def full_nao_aceito_marcar(codigo: str, motivo: str, usuario: str) -> None:
    c = _full_codigo(codigo)
    if not c:
        raise ValueError("Informe o código.")
    with DB_LOCK:
        DB.execute("INSERT OR REPLACE INTO full_nao_aceito_v1903(codigo,motivo,marcado_por,marcado_em) VALUES(?,?,?,?)",
                   (c, str(motivo or "").strip()[:200], str(usuario or ""), now_iso()))
        DB.commit()
    audit(str(usuario or "sistema"), "full.nao_aceito.marcar", json.dumps({"codigo": c, "motivo": motivo}, ensure_ascii=False))


def full_nao_aceito_liberar(codigo: str, usuario: str) -> bool:
    c = _full_codigo(codigo)
    with DB_LOCK:
        n = DB.execute("DELETE FROM full_nao_aceito_v1903 WHERE codigo=?", (c,)).rowcount
        DB.commit()
    if n:
        audit(str(usuario or "sistema"), "full.nao_aceito.liberar", json.dumps({"codigo": c}, ensure_ascii=False))
    return bool(n)


def full_nao_aceito_lista() -> dict[str, dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM full_nao_aceito_v1903").fetchall()
    return {r["codigo"]: dict(r) for r in rows}


# V19.03: remessa Full automática — cálculo puro (sem Apollo, sem ML).
FULL_REMESSA_PRAZO = 30
FULL_REMESSA_MINIMO = 150
FULL_NOVO_VENDAS_MIN = 10
FULL_NOVO_QTD_MAX = 10
FULL_REVENDA = 1


def _full_a_caminho() -> dict[str, int]:
    """V19.03: unidades já agendadas (remessa 'agendada', item não removido) por anúncio."""
    with DB_LOCK:
        rows = DB.execute(
            "SELECT i.anuncio, SUM(COALESCE(i.qtd_admin, i.qtd_sugerida)) AS q FROM full_remessa_item_v1903 i "
            "JOIN full_remessa_v1903 r ON r.remessa_id=i.remessa_id "
            # V19.03: só o que vai de fato — confirmado e com quantidade.
            "WHERE r.situacao='agendada' AND i.removido=0 AND i.confirmado=1 "
            "AND COALESCE(i.qtd_admin, i.qtd_sugerida) > 0 GROUP BY i.anuncio"
        ).fetchall()
    return {r["anuncio"]: int(r["q"] or 0) for r in rows}


# V19.85: "a caminho" lido do ML (dono, 26/10). O envio da NF 57.238 saiu sem "Marcar agendada"
# e a sugestão repetiu os mesmos itens. /inventories/{id}/stock/fulfillment traz, em
# not_available_detail, o status "transfer" = unidades a caminho do armazém (conferido com a
# nota: 48/48, 12/12, 6/6). Sem resposta fica None — desconhecido, nunca zero.
FULL_ML_INVENTARIO: dict[str, str] = {}   # MLB -> inventory_id (não muda; evita reler o anúncio)
FULL_ML_PAUSA = 0.1


def full_ml_a_caminho(mlbs: list[str]) -> dict[str, int | None]:
    out: dict[str, int | None] = {m: None for m in mlbs}
    falta = [m for m in mlbs if m not in FULL_ML_INVENTARIO]
    for i in range(0, len(falta), 20):   # a API aceita 20 ids por chamada
        try:
            resp = ml_api_get("/items?ids=" + ",".join(falta[i:i + 20]) + "&attributes=id,inventory_id")
        except Exception:
            continue
        for linha in (resp if isinstance(resp, list) else []):
            corpo = (linha or {}).get("body") or {}
            mlb = str(corpo.get("id") or "").strip().upper()
            inv = str(corpo.get("inventory_id") or "").strip()
            if mlb and inv:
                FULL_ML_INVENTARIO[mlb] = inv
    erros = 0
    for m in mlbs:
        inv = FULL_ML_INVENTARIO.get(m)
        if not inv:
            continue
        try:
            corpo = ml_api_get(f"/inventories/{re.sub(r'[^A-Za-z0-9_-]', '', inv)}/stock/fulfillment")
        except Exception:
            erros += 1
            if erros >= 5:
                break   # sem conexão ou limite do ML: o resto fica desconhecido
            continue
        erros = 0
        det = corpo.get("not_available_detail") if isinstance(corpo, dict) else None
        if isinstance(det, list):
            out[m] = int(sum(d.get("quantity") for d in det if isinstance(d, dict)
                             and str(d.get("status") or "") == "transfer"
                             and isinstance(d.get("quantity"), (int, float)) and not isinstance(d.get("quantity"), bool)))
        if FULL_ML_PAUSA:
            time.sleep(FULL_ML_PAUSA)
    return out


def _full_a_caminho_ml_aplicar(cand: dict[str, Any], ml: dict[str, Any]) -> None:
    """V19.85: a caminho = o MAIOR entre o agendado no sistema e o "transfer" do ML (nunca a
    soma: o mesmo envio contaria duas vezes). ML sem resposta = fica o do sistema."""
    for a in cand.get("anuncios") or []:
        sis = int(a.get("a_caminho") or 0)
        m = (ml or {}).get(a["anuncio"])
        a["a_caminho_sis"] = sis
        a["a_caminho_ml"] = None if m is None else int(m)
        a["a_caminho"] = sis if m is None else max(sis, int(m))


def full_remessa_candidatos(hoje: date | None = None) -> dict[str, Any]:
    """V19.03: anúncios Full (estoque dia a dia, últimos 7 dias) com venda de 30 dias,
    código Apollo/componentes e o que já está a caminho; mais os produtos novos."""
    hoje = hoje or datetime.now(BR_TZ).date()
    desde_full = (hoje - timedelta(days=7)).isoformat()
    desde_venda = (hoje - timedelta(days=FULL_REMESSA_PRAZO - 1)).isoformat()
    ate = hoje.isoformat()
    conhecidos = _compras_produtos_precificador()
    nao_aceito = full_nao_aceito_lista()
    with DB_LOCK:
        full_rows = DB.execute(
            "SELECT e.item_id, e.estoque_full_ultimo, e.logistica FROM ml_estoque_dia_v1872 e "
            "JOIN (SELECT item_id, MAX(dia) AS dia FROM ml_estoque_dia_v1872 WHERE dia >= ? GROUP BY item_id) m "
            "ON m.item_id=e.item_id AND m.dia=e.dia ORDER BY e.item_id", (desde_full,)
        ).fetchall()
        full_rows = [r for r in full_rows if str(r["logistica"] or "") == "fulfillment"]
        info: dict[str, Any] = {}
        ids = [r["item_id"] for r in full_rows]
        for i in range(0, len(ids), 500):
            lote = ids[i:i + 500]
            for r in DB.execute(f"SELECT item_id, sku, titulo FROM ml_visitas_item_v1868 WHERE item_id IN ({','.join('?' * len(lote))})", lote).fetchall():
                info[r["item_id"]] = r
        venda_anuncio = {r["anuncio"]: int(r["q"] or 0) for r in DB.execute(
            "SELECT anuncio, SUM(qty) AS q FROM vendas_v1799 WHERE marketplace='ml' AND sale_day >= ? AND sale_day <= ? GROUP BY anuncio",
            (desde_venda, ate)).fetchall()}
        venda_sku = DB.execute(
            "SELECT sku, SUM(qty) AS q, MAX(title) AS t FROM vendas_v1799 WHERE marketplace='ml' AND sale_day >= ? AND sale_day <= ? GROUP BY sku",
            (desde_venda, ate)).fetchall()
    a_caminho = _full_a_caminho()
    skus = [str(info[r["item_id"]]["sku"] or "").strip() if r["item_id"] in info else "" for r in full_rows]
    kits = full_kit_compositions(skus + [r["sku"] for r in venda_sku])
    anuncios: list[dict[str, Any]] = []
    fora: list[dict[str, Any]] = []
    codigos: set[str] = set()
    for r, sku in zip(full_rows, skus):
        mlb = r["item_id"]
        titulo = str(info[mlb]["titulo"] or "") if mlb in info else ""
        base = {"anuncio": mlb, "sku": sku, "titulo": titulo}
        if not sku:
            fora.append({**base, "codigo": "", "motivo": "anúncio sem SKU"})
            continue
        kit = (kits.get(sku) or {}).get("componentes")
        comps: list[dict[str, Any]] = []
        if kit:
            for c in kit:
                cod = _compras_codigo(c["sku"], conhecidos)
                if not cod:
                    comps = []
                    break
                comps.append({"codigo": _full_codigo(cod), "qtd": int(c["quantidade"])})
        elif "/" in sku:
            # V19.03: "A/B" = um de cada (conta 1); qualquer parte sem código = fora.
            for parte in [p.strip() for p in sku.split("/") if p.strip()]:
                cod = _compras_codigo(parte, conhecidos)
                if not cod:
                    comps = []
                    break
                comps.append({"codigo": _full_codigo(cod), "qtd": 1})
        else:
            cod = _compras_codigo(sku, conhecidos)
            if cod:
                comps = [{"codigo": _full_codigo(cod), "qtd": 1}]
        if not comps:
            fora.append({**base, "codigo": "", "motivo": "SKU sem código Apollo"})
            continue
        codigo = ",".join(c["codigo"] for c in comps)
        if any(c["codigo"] in nao_aceito for c in comps):
            fora.append({**base, "codigo": codigo, "motivo": "não aceito no Full"})
            continue
        codigos.update(c["codigo"] for c in comps)
        anuncios.append({**base, "codigo": codigo, "componentes": comps,
                         "venda_30d": venda_anuncio.get(mlb, 0),
                         # V19.60: o armazém do Full, não o available_quantity (soma o depósito).
                         "no_full": None if r["estoque_full_ultimo"] is None else int(r["estoque_full_ultimo"]),
                         "a_caminho": a_caminho.get(mlb, 0)})
    # V19.03: novos = código vendido no ML (kit e "A/B" fora) sem anúncio Full.
    por_codigo: dict[str, dict[str, Any]] = {}
    for r in venda_sku:
        sku = str(r["sku"] or "").strip()
        if not sku or sku in kits or "/" in sku:
            continue
        cod = _full_codigo(_compras_codigo(sku, conhecidos))
        if not cod:
            continue
        alvo = por_codigo.setdefault(cod, {"venda": 0, "sku": sku, "titulo": str(r["t"] or "")})
        alvo["venda"] += int(r["q"] or 0)
    novos: list[dict[str, Any]] = []
    for cod, v in sorted(por_codigo.items()):
        if v["venda"] < FULL_NOVO_VENDAS_MIN or cod in codigos:
            continue
        base = {"anuncio": f"NOVO:{cod}", "codigo": cod, "sku": v["sku"], "titulo": v["titulo"]}
        if cod in nao_aceito:
            fora.append({**base, "motivo": "não aceito no Full"})
            continue
        novos.append({**base, "componentes": [{"codigo": cod, "qtd": 1}], "venda_30d": v["venda"],
                      "no_full": None, "a_caminho": a_caminho.get(f"NOVO:{cod}", 0)})
    return {"anuncios": anuncios, "novos": novos, "codigos": codigos, "fora": fora}


def full_remessa_calcular(cand: dict[str, Any], estoque: dict[str, Any]) -> dict[str, Any]:
    """V19.03: quantidade a mandar por anúncio. `estoque` (código -> disponível no Apollo,
    None = não respondeu) vem pronto do chamador: aqui não se chama o Apollo. Saldo
    compartilhado entre anúncios e kits, o mais urgente (menor cobertura) primeiro.
    Código ausente do `estoque` = desconhecido, nunca zero."""
    saldo: dict[str, Any] = {}
    for k, v in (estoque or {}).items():
        saldo[_full_codigo(k)] = None if v is None else float(v)

    def possivel(comps: list[dict[str, Any]]) -> Any:
        valores = []
        for c in comps:
            s = saldo.get(c["codigo"])
            if s is None:
                return None
            valores.append(int(math.floor(max(0.0, s) / c["qtd"])))
        return min(valores) if valores else None

    def montar(a: dict[str, Any], nec: int, cob: Any, novo: bool) -> dict[str, Any]:
        disp = possivel(a["componentes"])
        motivo = ""
        if disp is None:
            qtd = 0
            motivo = "Apollo não respondeu"
        else:
            qtd = max(0, min(nec, disp))
            for c in a["componentes"]:
                saldo[c["codigo"]] -= qtd * c["qtd"]
        return {"anuncio": a["anuncio"], "codigo": a["codigo"], "sku": a.get("sku", ""), "titulo": a.get("titulo", ""),
                "novo": 1 if novo else 0, "confirmado": 0 if novo else 1, "venda_30d": int(a["venda_30d"]),
                "no_full": a.get("no_full"), "a_caminho": int(a.get("a_caminho") or 0), "cobertura_dias": cob,
                "a_caminho_sis": int(a.get("a_caminho_sis", a.get("a_caminho")) or 0),   # V19.85
                "a_caminho_ml": a.get("a_caminho_ml"),
                "necessidade": nec, "estoque_apollo": disp, "qtd_sugerida": qtd, "motivo": motivo,
                "componentes": a["componentes"],
                "componentes_json": json.dumps([{"codigo": c["codigo"], "qtd": c["qtd"]} for c in a["componentes"]])}

    prep = []
    for a in cand.get("anuncios") or []:
        diaria = a["venda_30d"] / FULL_REMESSA_PRAZO
        nf = a.get("no_full") or 0   # V19.03: ML sem número conta 0 na necessidade, mas fica None no item
        nec = max(0, int(math.ceil(diaria * FULL_REMESSA_PRAZO)) - nf - int(a.get("a_caminho") or 0))
        cob = round(nf / diaria, 1) if diaria > 0 else None
        prep.append((a, nec, cob))
    prep.sort(key=lambda t: (t[2] is None, t[2] or 0))
    novos = []
    fora = list(cand.get("fora") or [])
    itens = []
    for a, nec, cob in prep:
        i = montar(a, nec, cob, False)
        # V19.05: a remessa só leva o que tem no Apollo. Estoque conhecido e nada a mandar
        # (Apollo zerado ou Full já cobre) vai para fora. Sem resposta continua no item (aviso).
        if i["estoque_apollo"] is not None and i["qtd_sugerida"] <= 0:
            fora.append({"anuncio": a["anuncio"], "codigo": a["codigo"], "sku": a.get("sku", ""),
                         "titulo": a.get("titulo", ""),
                         "a_caminho": int(a.get("a_caminho") or 0),  # V20.05: a Ruptura lê daqui
                         # V19.85: o que vai a caminho também cobre
                         "motivo": ("Full + a caminho cobrem 30 dias" if int(a.get("a_caminho") or 0) > 0
                                    else "Full já cobre 30 dias") if nec <= 0 else "sem estoque no Apollo"})
            continue
        itens.append(i)
    for a in cand.get("novos") or []:
        # V19.03: novo sem estoque no Apollo (0) ou sem resposta não é sugerido: vai para fora.
        disp = possivel(a["componentes"])
        if disp is None or disp <= 0:
            fora.append({"anuncio": a["anuncio"], "codigo": a["codigo"], "sku": a.get("sku", ""),
                         "titulo": a.get("titulo", ""),
                         "motivo": "Apollo não respondeu" if disp is None else "sem estoque no Apollo"})
            continue
        novos.append(montar(a, min(int(a["venda_30d"]), FULL_NOVO_QTD_MAX), None, True))
    unidades = sum(i["qtd_sugerida"] for i in itens + novos if i["qtd_sugerida"] > 0 and i["confirmado"] == 1)
    return {"itens": itens, "novos": novos, "unidades": unidades, "fora": fora}


# V19.03: remessa Full — rodada, gravação e ajustes do ADMIN.
FULL_REMESSA_ABERTA = ("montando", "pronta")
_FULL_ITEM_COLS = ("codigo", "sku", "titulo", "novo", "venda_30d", "no_full", "a_caminho", "cobertura_dias",
                   "necessidade", "estoque_apollo", "qtd_sugerida", "motivo", "componentes_json",
                   "a_caminho_sis", "a_caminho_ml")   # V19.85


def _full_remessa_schema() -> None:
    """V19.03: garante fora_json em banco criado antes da coluna (idempotente). Chamar sob DB_LOCK."""
    cols = {r[1] for r in DB.execute("PRAGMA table_info(full_remessa_v1903)").fetchall()}
    if "fora_json" not in cols:
        DB.execute("ALTER TABLE full_remessa_v1903 ADD COLUMN fora_json TEXT NOT NULL DEFAULT '[]'")
    if "sem_apollo" not in cols:
        DB.execute("ALTER TABLE full_remessa_v1903 ADD COLUMN sem_apollo INTEGER NOT NULL DEFAULT 0")
    if "locais_json" not in cols:
        DB.execute("ALTER TABLE full_remessa_v1903 ADD COLUMN locais_json TEXT NOT NULL DEFAULT '{}'")
    if "reconferencia_json" not in cols:
        # V19.10: última reconferência do Apollo antes de agendar (disponível por código e faltas).
        DB.execute("ALTER TABLE full_remessa_v1903 ADD COLUMN reconferencia_json TEXT NOT NULL DEFAULT '{}'")
    icols = {r[1] for r in DB.execute("PRAGMA table_info(full_remessa_item_v1903)").fetchall()}
    if "componentes_json" not in icols:
        DB.execute("ALTER TABLE full_remessa_item_v1903 ADD COLUMN componentes_json TEXT NOT NULL DEFAULT '[]'")
    # V19.85: de onde veio o a caminho (agendado no sistema / "transfer" do ML; None = ML sem resposta).
    if "a_caminho_sis" not in icols:
        DB.execute("ALTER TABLE full_remessa_item_v1903 ADD COLUMN a_caminho_sis INTEGER NOT NULL DEFAULT 0")
    if "a_caminho_ml" not in icols:
        DB.execute("ALTER TABLE full_remessa_item_v1903 ADD COLUMN a_caminho_ml INTEGER")


def _full_remessa_marca() -> tuple:
    """V19.03: retrato (remessa aberta, agendadas) para descobrir agendamento durante a rodada. Sob DB_LOCK."""
    aberta = DB.execute("SELECT MAX(remessa_id) FROM full_remessa_v1903 WHERE situacao IN ('montando','pronta')").fetchone()[0]
    ag = DB.execute("SELECT COUNT(*), COALESCE(MAX(agendada_em),'') FROM full_remessa_v1903 WHERE agendada_em<>''").fetchone()
    return (aberta, int(ag[0] or 0), ag[1])


# V19.08: o CRM (mesma VPS) sofria com ~100 consultas seguidas a cada 3 s (13/10, swap e CPU
# roubada). A montagem espaça as consultas e guarda o resultado 1 h: o "Montar agora" no
# expediente reaproveita e só vai ao Apollo pelo que falta. Resposta None não é guardada.
FULL_APOLLO_INTERVALO = 10.0
FULL_APOLLO_REUSO_S = 3600
FULL_APOLLO_CACHE: dict[str, tuple[float, float, str]] = {}   # código -> (quando, disponível, localização)
FULL_APOLLO_CACHE_LOCK = threading.Lock()


# V19.11: andamento da leitura do Apollo (Montar agora / rotina / reconferência) para a tela.
FULL_ANDAMENTO: dict[str, Any] = {}
FULL_ANDAMENTO_LOCK = threading.Lock()


def full_remessa_andamento() -> dict[str, Any]:
    with FULL_ANDAMENTO_LOCK:
        a = dict(FULL_ANDAMENTO)
    if a.get("rodando"):
        falta = max(0, int(a.get("total") or 0) - int(a.get("feito") or 0))
        a["restante_s"] = int(falta * float(a.get("intervalo_s") or 0))
    return a


def _full_andamento(**campos: Any) -> None:
    with FULL_ANDAMENTO_LOCK:
        FULL_ANDAMENTO.update(campos)


def full_remessa_estoque_apollo(codigos: set[str], prazo_s: float = 600,
                                locais: dict[str, str] | None = None, intervalo_s: float = FULL_APOLLO_INTERVALO,
                                reusar_s: float = 0, etapa: str = "Montando a remessa") -> dict[str, Any]:
    """V19.03: disponível na revenda 1 (Araçatuba) por código. Fora do DB_LOCK.
    Casa sem resposta / erro / prazo estourado = None, nunca zero.
    V19.08: `intervalo_s` entre consultas reais; `reusar_s` > 0 aproveita o lido há menos que isso."""
    out: dict[str, Any] = {}
    fim = time.monotonic() + max(0.0, float(prazo_s))
    lista = sorted({_full_codigo(c) for c in codigos if _full_codigo(c)})
    with FULL_ANDAMENTO_LOCK:
        FULL_ANDAMENTO.clear()
        FULL_ANDAMENTO.update({"rodando": True, "etapa": etapa, "total": len(lista), "feito": 0, "codigo": "",
                               "sem_resposta": 0, "inicio": now_iso(), "fim": "", "intervalo_s": float(intervalo_s)})
    try:
        _full_estoque_apollo_laco(lista, out, fim, intervalo_s, reusar_s, locais)
    finally:
        sem = sum(1 for v in out.values() if v is None)
        _full_andamento(rodando=False, fim=now_iso(), codigo="", sem_resposta=sem, feito=len(out))
    return out


def _full_estoque_apollo_laco(lista: list[str], out: dict[str, Any], fim: float, intervalo_s: float,
                              reusar_s: float, locais: dict[str, str] | None) -> None:
    primeira = True
    for n, cod in enumerate(lista):
        _full_andamento(feito=n, codigo=cod)
        out[cod] = None
        if reusar_s > 0:
            with FULL_APOLLO_CACHE_LOCK:
                guardado = FULL_APOLLO_CACHE.get(cod)
            if guardado and time.monotonic() - guardado[0] <= reusar_s:
                out[cod] = guardado[1]
                if locais is not None and guardado[2]:
                    locais[cod] = guardado[2]
                continue
        if not primeira:
            espera = min(float(intervalo_s), max(0.0, fim - time.monotonic()))
            if espera > 0:
                time.sleep(espera)
        primeira = False
        try:
            stock = crm_stock_lookup(cod, "remessa-full", max(0.0, fim - time.monotonic()))
        except CrmLimiteAtingido:
            continue   # V19.03: prazo acabou: o resto fica None
        except Exception:
            continue
        rows = stock.get("estoques") if isinstance(stock.get("estoques"), list) else []
        missing = []
        for x in stock.get("casas_sem_resposta") or []:
            try:
                missing.append(int(x))
            except (TypeError, ValueError):
                pass
        sel = [r for r in rows if int(r.get("revenda") or 0) == FULL_REVENDA]
        if locais is not None:
            # V19.07: localização da mesma resposta ("...." = casa sem prateleira cadastrada).
            loc = next((str(r.get("localizacao") or "").strip() for r in sel
                        if str(r.get("localizacao") or "").strip().strip(".")), "")
            if loc:
                locais[cod] = loc
        if sel and FULL_REVENDA not in missing and all(r.get("disponivel") is not None for r in sel):
            out[cod] = sum(float(r.get("disponivel") or 0) for r in sel)
            loc_c = next((str(r.get("localizacao") or "").strip() for r in sel
                          if str(r.get("localizacao") or "").strip().strip(".")), "")
            with FULL_APOLLO_CACHE_LOCK:
                FULL_APOLLO_CACHE[cod] = (time.monotonic(), out[cod], loc_c)


_FULL_CONTA = "removido=0 AND confirmado=1 AND COALESCE(qtd_admin, qtd_sugerida) > 0"


def _full_remessa_recontar(remessa_id: int) -> dict[str, Any]:
    """V19.03: total (COALESCE(qtd_admin, qtd_sugerida) das confirmadas e não removidas) e situação. Sob DB_LOCK.
    Pronta quando as unidades de itens com estoque do Apollo CONHECIDO chegam ao mínimo: Apollo
    parcial não trava a remessa para sempre; sem resposta nenhuma, fica montando."""
    cab = DB.execute("SELECT * FROM full_remessa_v1903 WHERE remessa_id=?", (remessa_id,)).fetchone()
    r = DB.execute(f"SELECT COALESCE(SUM(COALESCE(qtd_admin, qtd_sugerida)),0) AS t, COUNT(*) AS n, "
                   f"COALESCE(SUM(CASE WHEN estoque_apollo IS NOT NULL THEN COALESCE(qtd_admin, qtd_sugerida) ELSE 0 END),0) AS k "
                   f"FROM full_remessa_item_v1903 WHERE remessa_id=? AND {_FULL_CONTA}", (remessa_id,)).fetchone()
    total = int(r["t"] or 0)
    conhecidas = int(r["k"] or 0)
    situacao = cab["situacao"]
    if situacao in FULL_REMESSA_ABERTA:
        if total >= FULL_REMESSA_MINIMO and conhecidas >= FULL_REMESSA_MINIMO:
            situacao = "pronta"
        else:
            situacao = "montando"
    DB.execute("UPDATE full_remessa_v1903 SET unidades=?, itens=?, situacao=? WHERE remessa_id=?",
               (total, int(r["n"] or 0), situacao, remessa_id))
    return {"remessa_id": remessa_id, "situacao": situacao, "unidades": total}


def _full_remessa_conferir_recebidas(hoje: date) -> None:
    """V19.03: agendada vira recebida quando todo anúncio (não novo, não removido, confirmado,
    qtd > 0) tem no_full atual >= no_full do agendamento + 50% da qtd. Sob DB_LOCK."""
    agendadas = DB.execute("SELECT remessa_id, agendada_para FROM full_remessa_v1903 WHERE situacao='agendada'").fetchall()
    if not agendadas:
        return
    limite = (hoje - timedelta(days=10)).isoformat()
    desde = (hoje - timedelta(days=7)).isoformat()
    atual = {r["item_id"]: r["estoque_full_ultimo"] for r in DB.execute(
        "SELECT e.item_id, e.estoque_full_ultimo FROM ml_estoque_dia_v1872 e "
        "JOIN (SELECT item_id, MAX(dia) AS dia FROM ml_estoque_dia_v1872 WHERE dia >= ? GROUP BY item_id) m "
        "ON m.item_id=e.item_id AND m.dia=e.dia", (desde,)).fetchall()}
    for cab in agendadas:
        # V19.03: "a caminho" não fica para sempre: 10 dias depois da data agendada vira recebida.
        if str(cab["agendada_para"] or "") and str(cab["agendada_para"]) < limite:
            DB.execute("UPDATE full_remessa_v1903 SET situacao='recebida', obs=? WHERE remessa_id=?",
                       ("recebida por prazo (10 dias após a data agendada)", cab["remessa_id"]))
            continue
        itens = DB.execute(
            f"SELECT anuncio, no_full, COALESCE(qtd_admin, qtd_sugerida) AS q FROM full_remessa_item_v1903 "
            f"WHERE remessa_id=? AND novo=0 AND {_FULL_CONTA}", (cab["remessa_id"],)).fetchall()
        if not itens:
            continue   # V19.03: só novos — sem anúncio para conferir; fica para o manual
        if all(atual.get(i["anuncio"]) is not None
               and float(atual[i["anuncio"]]) >= float(i["no_full"] or 0) + 0.5 * float(i["q"] or 0) for i in itens):
            DB.execute("UPDATE full_remessa_v1903 SET situacao='recebida', obs=? WHERE remessa_id=?",
                       ("Recebida automaticamente (estoque Full subiu).", cab["remessa_id"]))


def full_remessa_rodada(hoje: date | None = None, estoque: dict | None = None, prazo_s: float = 600,
                        reusar_s: float = 0) -> dict[str, Any]:
    """V19.03: recalcula (ou abre) a única remessa aberta. Ajuste humano (qtd_admin,
    removido, confirmado de novo) nunca é desfeito. Apollo lido fora do DB_LOCK."""
    hoje = hoje or datetime.now(BR_TZ).date()
    with DB_LOCK:
        _full_remessa_schema()
        _full_remessa_conferir_recebidas(hoje)
        DB.commit()
        marca = _full_remessa_marca()
    cand = full_remessa_candidatos(hoje)
    # V19.85: fora do DB_LOCK, como o Apollo.
    _full_a_caminho_ml_aplicar(cand, full_ml_a_caminho([a["anuncio"] for a in cand.get("anuncios") or []]))
    locais: dict[str, str] = {}
    if estoque is None:
        cods = set(cand.get("codigos") or set())
        for a in (cand.get("anuncios") or []) + (cand.get("novos") or []):
            cods.update(c["codigo"] for c in a.get("componentes") or [])
        estoque = full_remessa_estoque_apollo(cods, prazo_s=prazo_s, locais=locais, reusar_s=reusar_s)
    calc = full_remessa_calcular(cand, estoque)
    linhas = calc["itens"] + calc["novos"]
    sem_apollo = len({i["codigo"] for i in linhas if i["necessidade"] > 0 and i["estoque_apollo"] is None})
    obs = f"Apollo não respondeu para {sem_apollo} códigos." if sem_apollo else ""
    with DB_LOCK:
        if _full_remessa_marca() != marca:
            # V19.03: ADMIN agendou durante a leitura — o cálculo (a caminho) ficou velho.
            atual = DB.execute("SELECT remessa_id, situacao, unidades FROM full_remessa_v1903 "
                               "ORDER BY (situacao IN ('montando','pronta')) DESC, remessa_id DESC LIMIT 1").fetchone()
            res = dict(atual) if atual else {"remessa_id": None, "situacao": "", "unidades": 0}
            res["obs"] = "rodada descartada: remessa agendada durante a leitura"
            return res
        cab = DB.execute("SELECT * FROM full_remessa_v1903 WHERE situacao IN ('montando','pronta') "
                         "ORDER BY remessa_id DESC LIMIT 1").fetchone()
        if cab is None:
            rid = DB.execute("INSERT INTO full_remessa_v1903(situacao,montada_em) VALUES('montando',?)", (now_iso(),)).lastrowid
        else:
            rid = cab["remessa_id"]
        existentes = {r["anuncio"]: r for r in DB.execute(
            "SELECT * FROM full_remessa_item_v1903 WHERE remessa_id=?", (rid,)).fetchall()}
        vistos = set()
        sets = ",".join(f"{c}=?" for c in _FULL_ITEM_COLS)
        for i in linhas:
            vistos.add(i["anuncio"])
            vals = [i[c] for c in _FULL_ITEM_COLS]
            if i["anuncio"] in existentes:
                extra = ", confirmado=1" if not i["novo"] else ""   # V19.03: não-novo é sempre confirmado
                DB.execute(f"UPDATE full_remessa_item_v1903 SET {sets}{extra} WHERE remessa_id=? AND anuncio=?",
                           (*vals, rid, i["anuncio"]))
            else:
                DB.execute(f"INSERT INTO full_remessa_item_v1903(remessa_id,anuncio,confirmado,{','.join(_FULL_ITEM_COLS)}) "
                           f"VALUES(?,?,?,{','.join('?' * len(_FULL_ITEM_COLS))})",
                           (rid, i["anuncio"], i["confirmado"], *vals))
        for anuncio, r in existentes.items():
            if anuncio in vistos:
                continue
            humano = r["qtd_admin"] is not None or r["removido"] or (r["novo"] and r["confirmado"])
            if humano:
                DB.execute("UPDATE full_remessa_item_v1903 SET qtd_sugerida=0, motivo=? WHERE remessa_id=? AND anuncio=?",
                           ("Fora do cálculo desta rodada (mantido pelo ajuste do ADMIN).", rid, anuncio))
            else:
                DB.execute("DELETE FROM full_remessa_item_v1903 WHERE remessa_id=? AND anuncio=?", (rid, anuncio))
        try:
            loc_ant = json.loads(DB.execute("SELECT locais_json FROM full_remessa_v1903 WHERE remessa_id=?", (rid,)).fetchone()[0] or "{}")
        except Exception:
            loc_ant = {}
        loc_ant.update(locais)   # V19.07: Apollo sem resposta nesta rodada não apaga a prateleira já vista
        DB.execute("UPDATE full_remessa_v1903 SET montada_em=?, obs=?, fora_json=?, sem_apollo=?, locais_json=? WHERE remessa_id=?",
                   (now_iso(), obs, json.dumps(calc["fora"], ensure_ascii=False), sem_apollo,
                    json.dumps(loc_ant, ensure_ascii=False), rid))
        res = _full_remessa_recontar(rid)
        DB.commit()
    res["obs"] = obs
    return res


def full_remessa_atual() -> dict[str, Any] | None:
    """V19.03: a remessa aberta (senão a mais recente) com itens, novos, fora e não aceitos."""
    with DB_LOCK:
        _full_remessa_schema()
        cab = DB.execute("SELECT * FROM full_remessa_v1903 WHERE situacao IN ('montando','pronta') "
                         "ORDER BY remessa_id DESC LIMIT 1").fetchone()
        if cab is None:
            cab = DB.execute("SELECT * FROM full_remessa_v1903 ORDER BY remessa_id DESC LIMIT 1").fetchone()
        if cab is None:
            return None
        rows = [dict(r) for r in DB.execute(
            "SELECT * FROM full_remessa_item_v1903 WHERE remessa_id=? "
            "ORDER BY novo, cobertura_dias IS NULL, cobertura_dias, anuncio", (cab["remessa_id"],)).fetchall()]
    try:
        fora = json.loads(cab["fora_json"] or "[]")
    except Exception:
        fora = []
    try:
        locais = json.loads(cab["locais_json"] or "{}")
    except Exception:
        locais = {}
    return {"remessa_id": cab["remessa_id"], "separacao": full_remessa_separacao(rows, locais), "situacao": cab["situacao"], "unidades": cab["unidades"],
            "itens": [r for r in rows if not r["novo"]], "novos": [r for r in rows if r["novo"]],
            "fora": fora, "nao_aceito": list(full_nao_aceito_lista().values()),
            "montada_em": cab["montada_em"], "obs": cab["obs"], "agendada_para": cab["agendada_para"],
            "sem_apollo": int(cab["sem_apollo"] or 0), "reconferencia": _full_json(cab["reconferencia_json"], {})}


def _full_json(texto: Any, padrao: Any) -> Any:
    try:
        return json.loads(texto or "") if texto else padrao
    except Exception:
        return padrao


def _full_loc_chave(loc: str) -> tuple:
    """V19.07: ZZ.9.14.A.99 parte a parte, números como números (ZZ.9.9 antes de ZZ.9.14)."""
    partes = [p for p in re.split(r"[.\-\s/]+", str(loc or "").upper()) if p]
    return tuple((0, int(p), "") if p.isdigit() else (1, 0, p) for p in partes)


def full_remessa_separacao(rows: list[dict[str, Any]], locais: dict[str, str]) -> list[dict[str, Any]]:
    """V19.07: lista de separação da remessa (Araçatuba) — itens confirmados, não removidos e
    com quantidade; kit abre em cada peça; por código Apollo, em ordem de prateleira
    (sem localização no fim). Mesma regra da lista da planilha (V17.96)."""
    pick: dict[str, dict[str, Any]] = {}
    for r in rows:
        q = r.get("qtd_admin") if r.get("qtd_admin") is not None else r.get("qtd_sugerida")
        q = int(q or 0)
        if r.get("removido") or not r.get("confirmado") or q <= 0:
            continue
        try:
            comps = json.loads(r.get("componentes_json") or "[]")
        except Exception:
            comps = []
        if not comps:
            comps = [{"codigo": r.get("codigo") or "", "qtd": 1}]
        kit = len(comps) > 1 or float(comps[0].get("qtd") or 1) != 1
        for c in comps:
            cod = _full_codigo(c.get("codigo"))
            if not cod:
                continue
            p = pick.setdefault(cod, {"codigo": cod, "localizacao": str(locais.get(cod) or ""),
                                      "descricao": "", "qtd": 0, "anuncios": []})
            p["qtd"] += int(round(q * float(c.get("qtd") or 1)))
            if not p["descricao"] or not kit:
                p["descricao"] = ("Peça do kit: " if kit else "") + str(r.get("titulo") or "")
            if r.get("anuncio") not in p["anuncios"]:
                p["anuncios"].append(r.get("anuncio"))
    return sorted(pick.values(), key=lambda p: (not p["localizacao"], _full_loc_chave(p["localizacao"]), p["codigo"]))


FULL_REMESSA_MONTAR_LOCK = threading.Lock()  # V19.03: uma montagem manual por vez


def full_remessa_historico() -> list[dict[str, Any]]:
    """V19.03: últimas 10 remessas agendadas/recebidas, com itens."""
    with DB_LOCK:
        _full_remessa_schema()
        out = []
        for c in DB.execute("SELECT * FROM full_remessa_v1903 WHERE situacao IN ('agendada','recebida') "
                            "ORDER BY remessa_id DESC LIMIT 10").fetchall():
            itens = [dict(r) for r in DB.execute(
                "SELECT * FROM full_remessa_item_v1903 WHERE remessa_id=? ORDER BY anuncio", (c["remessa_id"],)).fetchall()]
            out.append({"remessa_id": c["remessa_id"], "situacao": c["situacao"], "unidades": c["unidades"],
                        "agendada_para": c["agendada_para"], "itens": itens})
    return out


def full_remessa_avisar(hoje: date | None = None) -> bool:
    """V19.03: avisa (popup + push) uma vez por dia que a remessa Full está pronta."""
    hoje = hoje or datetime.now(BR_TZ).date()
    dia = hoje.isoformat()
    with DB_LOCK:
        _full_remessa_schema()
        r = DB.execute("SELECT * FROM full_remessa_v1903 WHERE situacao='pronta' "
                       "ORDER BY remessa_id DESC LIMIT 1").fetchone()
        if r is None or r["avisado_dia"] == dia:
            return False
        titulo = f"Remessa Full pronta: {int(r['unidades'] or 0)} un. em {int(r['itens'] or 0)} itens"
        DB.execute("INSERT OR IGNORE INTO aviso_venda_v1893(marketplace,venda_id,venda_em,valor,titulo,qtd,itens,silencioso,criado_em) "
                   "VALUES('full',?,?,NULL,?,0,0,0,?)",
                   (f"remessa:{r['remessa_id']}:{dia}", now_iso(), titulo, now_iso()))
        DB.execute("UPDATE full_remessa_v1903 SET avisado_dia=? WHERE remessa_id=?", (dia, r["remessa_id"]))
        DB.commit()
    AVISOS_VENDA_EVENT.set()
    return True


def full_remessa_resumo_email() -> str:
    """V19.03: linha do relatório das 08:00 (vazia quando não há remessa pronta)."""
    with DB_LOCK:
        _full_remessa_schema()
        r = DB.execute("SELECT unidades,itens FROM full_remessa_v1903 WHERE situacao='pronta' "
                       "ORDER BY remessa_id DESC LIMIT 1").fetchone()
    if r is None:
        return ""
    return f"Remessa Full pronta: {int(r['unidades'] or 0)} un. em {int(r['itens'] or 0)} itens"


def full_remessa_loop(stop_event: threading.Event) -> None:
    """V19.03: uma rodada por dia depois das 05:00 (Brasília); depois avisa."""
    if stop_event.wait(240):
        return
    while not stop_event.is_set():
        try:
            agora = datetime.now(BR_TZ)
            hoje = agora.date().isoformat()
            if agora.hour >= 5:
                with DB_LOCK:
                    _full_remessa_schema()
                    ult = DB.execute("SELECT montada_em FROM full_remessa_v1903 ORDER BY remessa_id DESC LIMIT 1").fetchone()
                if ult is None or str(ult[0] or "")[:10] != hoje:
                    # V19.03: worker sem nginx, dá tempo ao Apollo. V19.08: 1 consulta a cada 10 s, leitura nova.
                    res = full_remessa_rodada(prazo_s=3000)
                    print(f"[remessa-full] rodada: {res.get('situacao')} {res.get('unidades')} un.", flush=True)
                full_remessa_avisar()
        except Exception as exc:
            print(f"[remessa-full] erro: {exc}", file=sys.stderr, flush=True)
        if stop_event.wait(1800):
            break


def _full_remessa_aberta_ou_erro(remessa_id: int) -> Any:
    cab = DB.execute("SELECT * FROM full_remessa_v1903 WHERE remessa_id=?", (int(remessa_id),)).fetchone()
    if cab is None:
        raise ValueError("Remessa não encontrada.")
    if cab["situacao"] not in FULL_REMESSA_ABERTA:
        raise ValueError("Remessa já agendada.")
    return cab


_FULL_SEM_MUDANCA = object()   # V19.03: qtd ausente = não mexe; qtd None = volta à sugestão


def full_remessa_ajustar(remessa_id: int, anuncio: str, *, qtd: Any = _FULL_SEM_MUDANCA, removido: bool | None = None,
                         confirmado: bool | None = None, usuario: str) -> dict[str, Any]:
    """V19.03: ajuste do ADMIN numa linha; a rodada nunca desfaz. qtd=None limpa o qtd_admin."""
    if qtd is not _FULL_SEM_MUDANCA and qtd is not None:
        if isinstance(qtd, bool) or not isinstance(qtd, int) or qtd < 0:
            raise ValueError("Quantidade inválida.")
    anuncio = str(anuncio or "").strip()
    rid = int(remessa_id)
    with DB_LOCK:
        _full_remessa_aberta_ou_erro(rid)
        linha = DB.execute("SELECT * FROM full_remessa_item_v1903 WHERE remessa_id=? AND anuncio=?", (rid, anuncio)).fetchone()
        if linha is None:
            raise ValueError("Anúncio não está na remessa.")
        if qtd is not _FULL_SEM_MUDANCA:
            DB.execute("UPDATE full_remessa_item_v1903 SET qtd_admin=? WHERE remessa_id=? AND anuncio=?", (qtd, rid, anuncio))
        if removido is not None:
            DB.execute("UPDATE full_remessa_item_v1903 SET removido=? WHERE remessa_id=? AND anuncio=?",
                       (1 if removido else 0, rid, anuncio))
        if confirmado is not None and linha["novo"]:
            DB.execute("UPDATE full_remessa_item_v1903 SET confirmado=? WHERE remessa_id=? AND anuncio=?",
                       (1 if confirmado else 0, rid, anuncio))
        res = _full_remessa_recontar(rid)
        DB.commit()
    audit(str(usuario or "sistema"), "full.remessa.ajustar", json.dumps(
        {"remessa_id": rid, "anuncio": anuncio, "qtd": None if qtd is _FULL_SEM_MUDANCA else qtd,
         "qtd_volta_sugestao": qtd is None, "removido": removido, "confirmado": confirmado},
        ensure_ascii=False))
    return res


# V19.10: P10031 (13/10) — a remessa mostrava Apollo 3 de uma leitura antiga; o Disponível já
# era 1 (negociação de 2 peças aberta depois). Antes de agendar, o Apollo é lido de novo.
FULL_RECONFERIR_INTERVALO = 3.0
FULL_RECONFERIR_VALIDADE_S = 1800
FULL_REMESSA_RECONFERIR_LOCK = threading.Lock()   # uma reconferência por vez


def _full_item_comps(r: Any) -> list[dict[str, Any]]:
    return _full_json(r["componentes_json"], []) or [{"codigo": r["codigo"], "qtd": 1}]


def _full_item_conta(r: Any) -> int:
    """V19.10: quantidade que vai na remessa (0 = removido, não confirmado ou sem quantidade)."""
    q = r["qtd_admin"] if r["qtd_admin"] is not None else r["qtd_sugerida"]
    return 0 if r["removido"] or not r["confirmado"] else max(0, int(q or 0))


def _full_remessa_faltas(rows: list[Any], disp: dict[str, Any]) -> list[dict[str, Any]]:
    """V19.10: com o disponível de agora (código -> número; ausente/None = não respondeu), quanto
    cabe em cada item contado, o mais urgente (menor cobertura) primeiro — regra do cálculo.
    Devolve só os itens cuja quantidade passa do que cabe. Pura."""
    saldo = {_full_codigo(k): (None if v is None else float(v)) for k, v in disp.items()}
    faltas = []
    for r in rows:
        q = _full_item_conta(r)
        if q <= 0:
            continue
        comps = _full_item_comps(r)
        valores: list[int] | None = []
        for c in comps:
            s_ = saldo.get(_full_codigo(c.get("codigo")))
            if s_ is None:
                valores = None
                break
            valores.append(int(math.floor(max(0.0, s_) / float(c.get("qtd") or 1))))
        if not valores:
            continue   # Apollo sem resposta: nunca vira falta (nem zero)
        cabe = min(valores)
        usa = min(q, cabe)
        for c in comps:
            saldo[_full_codigo(c.get("codigo"))] -= usa * float(c.get("qtd") or 1)
        if q > cabe:
            faltas.append({"anuncio": r["anuncio"], "codigo": r["codigo"], "titulo": r["titulo"], "qtd": q, "cabe": cabe})
    return faltas


def _full_remessa_itens_ordem(rid: int) -> list[Any]:
    return DB.execute("SELECT * FROM full_remessa_item_v1903 WHERE remessa_id=? "
                      "ORDER BY novo, cobertura_dias IS NULL, cobertura_dias, anuncio", (rid,)).fetchall()


def full_remessa_reconferir(remessa_id: int, prazo_s: float = 600,
                            intervalo_s: float = FULL_RECONFERIR_INTERVALO) -> dict[str, Any]:
    """V19.10: lê o Apollo de novo (sem reaproveitar) para os itens contados, atualiza o
    estoque_apollo da tela e guarda as faltas. A quantidade não muda: quem baixa é o ADMIN."""
    rid = int(remessa_id)
    with DB_LOCK:
        _full_remessa_schema()
        _full_remessa_aberta_ou_erro(rid)
        rows = _full_remessa_itens_ordem(rid)
    cods = {_full_codigo(c.get("codigo")) for r in rows if _full_item_conta(r) > 0 for c in _full_item_comps(r)}
    cods.discard("")
    disp = full_remessa_estoque_apollo(cods, prazo_s=prazo_s, intervalo_s=intervalo_s, reusar_s=0,
                                      etapa="Conferindo o Apollo antes de agendar")
    with DB_LOCK:
        _full_remessa_aberta_ou_erro(rid)
        rows = _full_remessa_itens_ordem(rid)
        faltas = _full_remessa_faltas(rows, disp)
        for r in rows:
            comps = _full_item_comps(r)
            vals = [disp.get(_full_codigo(c.get("codigo"))) for c in comps]
            if not vals or any(v is None for v in vals):
                continue   # sem resposta não apaga o que se sabia
            novo = min(int(math.floor(max(0.0, float(v)) / float(c.get("qtd") or 1))) for v, c in zip(vals, comps))
            DB.execute("UPDATE full_remessa_item_v1903 SET estoque_apollo=? WHERE remessa_id=? AND anuncio=?",
                       (novo, rid, r["anuncio"]))
        rec = {"em": now_iso(), "disponivel": {k: v for k, v in disp.items() if v is not None},
               "sem_resposta": sorted(k for k, v in disp.items() if v is None), "falta": faltas}
        DB.execute("UPDATE full_remessa_v1903 SET reconferencia_json=? WHERE remessa_id=?",
                   (json.dumps(rec, ensure_ascii=False), rid))
        DB.commit()
    return rec


def full_remessa_agendar(remessa_id: int, data: str, usuario: str) -> dict[str, Any]:
    """V19.03: congela a remessa; os itens viram 'a caminho' e a próxima rodada abre outra."""
    data = str(data or "").strip()
    try:
        date.fromisoformat(data)
    except ValueError:
        raise ValueError("Data inválida (use AAAA-MM-DD).")
    rid = int(remessa_id)
    with DB_LOCK:
        _full_remessa_schema()
        cab = _full_remessa_aberta_ou_erro(rid)
        # V19.10: com reconferência recente, quantidade acima do Disponível de agora não agenda.
        rec = _full_json(cab["reconferencia_json"], {})
        try:
            idade = (datetime.now(timezone.utc) - datetime.fromisoformat(str(rec.get("em")))).total_seconds()
        except Exception:
            idade = None
        if idade is not None and idade <= FULL_RECONFERIR_VALIDADE_S:
            faltas = _full_remessa_faltas(_full_remessa_itens_ordem(rid), rec.get("disponivel") or {})
            if faltas:
                raise ValueError("Quantidade acima do disponível no Apollo: " + ", ".join(
                    f"{f['codigo']} ({f['qtd']} > {f['cabe']})" for f in faltas[:5]))
        res = _full_remessa_recontar(rid)
        DB.execute("UPDATE full_remessa_v1903 SET situacao='agendada', agendada_para=?, agendada_em=?, agendada_por=? "
                   "WHERE remessa_id=?", (data, now_iso(), str(usuario or ""), rid))
        DB.commit()
    audit(str(usuario or "sistema"), "full.remessa.agendar", json.dumps({"remessa_id": rid, "data": data}, ensure_ascii=False))
    res["situacao"] = "agendada"
    return res


def full_remessa_situacao(remessa_id: int, situacao: str, usuario: str) -> dict[str, Any]:
    """V19.03: marcar 'recebida' à mão (só de agendada)."""
    if situacao != "recebida":
        raise ValueError("Situação inválida.")
    rid = int(remessa_id)
    with DB_LOCK:
        cab = DB.execute("SELECT situacao FROM full_remessa_v1903 WHERE remessa_id=?", (rid,)).fetchone()
        if cab is None:
            raise ValueError("Remessa não encontrada.")
        if cab["situacao"] != "agendada":
            raise ValueError("Só remessa agendada pode virar recebida.")
        DB.execute("UPDATE full_remessa_v1903 SET situacao='recebida' WHERE remessa_id=?", (rid,))
        DB.commit()
    audit(str(usuario or "sistema"), "full.remessa.recebida", json.dumps({"remessa_id": rid}, ensure_ascii=False))
    return {"remessa_id": rid, "situacao": "recebida"}


def _expand_ml_order_item(item_data: dict[str, Any], kit_catalog: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    """Expande um item ML cadastrado como kit em seus componentes.

    Retorna uma ou mais linhas lógicas. A quantidade do componente é:
    quantidade comprada do kit × quantidade cadastrada do componente.
    """
    item = item_data.get("item") if isinstance(item_data.get("item"), dict) else {}
    sku_raw = _ml_order_item_sku_raw(item_data)
    sku = _ml_normalize_api_sku(sku_raw)
    try:
        sold_qty = max(1, int(item_data.get("quantity") or 1))
    except (TypeError, ValueError):
        sold_qty = 1
    title = str(item.get("title") or "").strip()

    # V17.46: identificação de KIT usa SOMENTE o SKU real recebido do ML.
    # Nunca removemos prefixos numéricos (ex.: 150922-0893764272) para procurar
    # cadastro de kit, pois isso transformava anúncios normais em kits incorretos.
    # _kit_catalog_lookup continua aceitando apenas aliases próprios de KIT
    # (KIT2-, KIT3- etc.), sem tratar prefixos numéricos como descartáveis.
    kit = _kit_catalog_lookup(kit_catalog, sku)
    if not kit:
        kit = _infer_quantity_kit_from_sku(sku)
    if not kit or not kit.get("ativo", True):
        return [{
            "sku": sku,
            "sku_raw": sku_raw,
            "quantity": sold_qty,
            "description": title,
            "is_kit": False,
            "kit_sku": "",
            "kit_name": "",
            "kits_sold": 0,
            "qty_per_kit": 0,
            "kit_unregistered": ("KIT" in normalize(sku) or "KIT" in normalize(title)),
        }]

    expanded: list[dict[str, Any]] = []
    for component in kit.get("componentes") or []:
        component_sku = str(component.get("sku") or "").strip()
        qty_per_kit = max(1, int(component.get("quantidade") or 1))
        expanded.append({
            "sku": component_sku,
            "sku_raw": sku_raw,
            "quantity": sold_qty * qty_per_kit,
            "description": title,
            "is_kit": True,
            "kit_sku": str(kit.get("sku_kit") or sku).strip(),
            "kit_name": str(kit.get("nome") or kit.get("sku_kit") or sku).strip(),
            "kits_sold": sold_qty,
            "qty_per_kit": qty_per_kit,
            "kit_unregistered": False,
        })
    return expanded


def _ml_find_product(products: list[dict[str, Any]], sku: str) -> dict[str, Any] | None:
    key = normalize(sku)
    if not key:
        return None
    for product in products:
        if normalize(product.get("SKU")) == key:
            return product
    return None


def _ml_normalize_api_sku(value: Any) -> str:
    """Retorna o SKU operacional usado pela Noromak.

    O Mercado Livre pode prefixar o SKU real com um código numérico interno do
    anúncio, por exemplo ``158529-0893117732``. Para conferência/cadastro o SKU
    efetivo é ``0893117732``. Prefixos semânticos como KIT2-/KIT3- são mantidos.
    O valor bruto da integração continua preservado separadamente em
    ``SkuOrigemImportacao`` para auditoria/restauração.
    """
    raw = str(value or "").strip()
    if "-" in raw:
        prefix, remainder = raw.split("-", 1)
        if prefix.strip().isdigit() and remainder.strip():
            return remainder.strip()
    return raw


def _ml_sku_lookup_candidates(value: Any) -> list[str]:
    """Candidatos de cadastro a partir do SKU operacional, sem heurística ampla."""
    effective = _ml_normalize_api_sku(value)
    return [effective] if effective else []


def _ml_order_item_sku_raw(item_data: dict[str, Any]) -> str:
    item = item_data.get("item") if isinstance(item_data.get("item"), dict) else {}
    for value in (
        item.get("seller_sku"),
        item.get("seller_custom_field"),
        item_data.get("seller_sku"),
    ):
        if str(value or "").strip():
            return str(value).strip()
    for attr in item.get("variation_attributes") or []:
        if not isinstance(attr, dict):
            continue
        if str(attr.get("id") or "").upper() == "SELLER_SKU" and str(attr.get("value_name") or "").strip():
            return str(attr["value_name"]).strip()
    return ""


def _ml_order_item_sku(item_data: dict[str, Any]) -> str:
    return _ml_normalize_api_sku(_ml_order_item_sku_raw(item_data))


def ml_order_shipments(order_id: str) -> tuple[str, dict[str, Any] | None]:
    """Resolve o shipment real da order aceitando contratos antigos e novos."""
    shipment_id = ""
    shipment_detail: dict[str, Any] | None = None
    errors: list[str] = []

    def pick_forward(payload: Any) -> str:
        shipments = payload if isinstance(payload, list) else ([payload] if isinstance(payload, dict) and payload.get("id") else [])
        if not shipments:
            return ""
        for item in shipments:
            if not isinstance(item, dict):
                continue
            typ = str(item.get("type") or "").strip().lower()
            direction = str(item.get("direction") or "").strip().lower()
            if typ == "forward" or direction == "forward":
                return str(item.get("id") or "").strip()
        if len(shipments) == 1 and isinstance(shipments[0], dict):
            typ = str(shipments[0].get("type") or "").strip().lower()
            direction = str(shipments[0].get("direction") or "").strip().lower()
            if typ not in {"return", "return_to_buyer", "reverse"} and direction not in {"return", "reverse"}:
                return str(shipments[0].get("id") or "").strip()
        for item in shipments:
            if not isinstance(item, dict):
                continue
            marker = " ".join([
                str(item.get("type") or ""), str(item.get("direction") or ""),
                str(item.get("status") or ""), str(item.get("substatus") or ""),
                " ".join(str(x) for x in (item.get("tags") or []) if x is not None),
            ]).lower()
            if not any(x in marker for x in ("return", "reverse", "devol")):
                sid = str(item.get("id") or "").strip()
                if sid:
                    return sid
        return ""

    attempts = [
        (f"/orders/{quote(str(order_id))}/shipments", None),
        (f"/orders/{quote(str(order_id))}/shipments", {"x-format-new": "true"}),
        (f"/orders/{quote(str(order_id))}/shipments?list_all=true", None),
        (f"/orders/{quote(str(order_id))}/shipments?list_all=true", {"x-format-new": "true"}),
    ]
    for path, headers in attempts:
        if shipment_id:
            break
        try:
            result = ml_api_get(path, headers=headers)
            shipment_id = pick_forward(result)
        except Exception as exc:
            errors.append(f"{path}:{exc}")

    if shipment_id:
        try:
            detail = ml_api_get(
                f"/shipments/{quote(shipment_id)}?views=destination",
                headers={"x-format-new": "true", "X-Api-Version": "2"},
            )
            if isinstance(detail, dict):
                shipment_detail = detail
        except Exception as exc:
            errors.append(f"detail:{exc}")

    if not shipment_id and errors:
        try:
            ml_log_event("shipment_resolver", f"/orders/{order_id}/shipments", "", ML_CLIENT_ID,
                         "SEM SHIPMENT", " | ".join(errors)[:1200])
        except Exception:
            pass
    return shipment_id, shipment_detail


def _ml_pack_shipment(pack_id: str) -> tuple[str, dict[str, Any] | None, list[str]]:
    """Resolve shipment e orders pelo pack, que é o número exibido em várias telas do ML."""
    pack_id = str(pack_id or "").strip()
    if not pack_id:
        return "", None, []
    payload = ml_api_get(f"/packs/{quote(pack_id)}")
    if not isinstance(payload, dict):
        return "", None, []
    shipment_obj = payload.get("shipment") if isinstance(payload.get("shipment"), dict) else {}
    shipment_id = str(shipment_obj.get("id") or "").strip()
    order_ids: list[str] = []
    for item in payload.get("orders") or []:
        if isinstance(item, dict):
            oid = str(item.get("id") or "").strip()
            if oid and oid not in order_ids:
                order_ids.append(oid)
    detail = None
    if shipment_id:
        try:
            got = ml_api_get(
                f"/shipments/{quote(shipment_id)}?views=destination",
                headers={"x-format-new": "true", "X-Api-Version": "2"},
            )
            if isinstance(got, dict):
                detail = got
        except Exception:
            detail = None
    return shipment_id, detail, order_ids


def _ml_orders_for_shipment(shipment_id: str) -> list[str]:
    shipment_id = str(shipment_id or "").strip()
    if not shipment_id:
        return []
    try:
        payload = ml_api_get(f"/shipments/{quote(shipment_id)}/orders", headers={"X-New-Domain": "true"})
    except Exception:
        return []
    items = payload if isinstance(payload, list) else ([payload] if isinstance(payload, dict) else [])
    out: list[str] = []
    for item in items:
        if isinstance(item, dict):
            oid = str(item.get("order_id") or item.get("id") or "").strip()
            if oid and oid not in out:
                out.append(oid)
    return out


def _ml_resolve_forward_shipment(order_id: str, order_hint: dict[str, Any] | None = None) -> tuple[str, dict[str, Any] | None]:
    """Order -> shipment; se falhar, usa o pack oficial; por último shipping.id legado."""
    shipment_id, shipment = ml_order_shipments(order_id)
    if shipment_id:
        return shipment_id, shipment

    order_hint = order_hint if isinstance(order_hint, dict) else {}
    pack_id = str(order_hint.get("pack_id") or "").strip()
    if pack_id:
        try:
            sid, detail, _ = _ml_pack_shipment(pack_id)
            if sid:
                return sid, detail
        except Exception as exc:
            try:
                ml_log_event("shipment_resolver", f"/packs/{pack_id}", "", ML_CLIENT_ID,
                             "PACK FALLBACK ERRO", str(exc)[:1200])
            except Exception:
                pass

    shipping = order_hint.get("shipping") if isinstance(order_hint.get("shipping"), dict) else {}
    hinted_id = str(shipping.get("id") or "").strip()
    if hinted_id:
        try:
            detail = ml_api_get(
                f"/shipments/{quote(hinted_id)}?views=destination",
                headers={"x-format-new": "true", "X-Api-Version": "2"},
            )
            return hinted_id, detail if isinstance(detail, dict) else None
        except Exception:
            return hinted_id, None
    return "", None

def _ml_invoice_available(invoice: dict[str, Any] | None) -> bool:
    if not isinstance(invoice, dict):
        return False
    status = str(invoice.get("status") or "").strip().lower()
    return bool(str(invoice.get("fiscal_key") or "").strip()
                or str(invoice.get("invoice_number") or "").strip()
                or status in {"approved", "authorized", "authorized_to_use"})


def _ml_extract_zpl_from_label_response(raw: bytes) -> str:
    if not raw:
        return ""
    if raw[:2] == b"PK":
        try:
            with zipfile.ZipFile(io.BytesIO(raw)) as archive:
                names = [n for n in archive.namelist() if n.lower().endswith((".txt",".zpl",".prn"))]
                chunks = []
                for name in sorted(names):
                    text = archive.read(name).decode("utf-8", errors="replace").strip()
                    if text:
                        chunks.append(text)
                return "\n".join(chunks).strip()
        except zipfile.BadZipFile:
            return ""
    text = raw.decode("utf-8", errors="replace").strip()
    return text if "^XA" in text or "~DG" in text else ""


def _ml_only_shipping_label_zpl(zpl: str) -> str:
    """Remove a DANFE simplificada quando o Mercado Livre devolve mais de um documento ZPL.

    Alguns shipments retornam, no mesmo payload zpl2, uma etiqueta fiscal (DANFE
    simplificada) seguida da etiqueta logística. A expedição Noromak deve imprimir
    apenas a etiqueta de envio. Quando não conseguimos identificar com segurança
    uma DANFE, preservamos o ZPL original para não descartar uma etiqueta válida.
    """
    text = str(zpl or "").strip()
    if not text:
        return ""

    docs = re.findall(r"\^XA[\s\S]*?\^XZ", text, flags=re.IGNORECASE)
    if len(docs) <= 1:
        return text

    fiscal_markers = (
        "DANFE SIMPLIFICADO",
        "DANFE SIMPLIFICADA",
        "PROTOCOLO DE AUTORIZACAO DE USO",
        "PROTOCOLO DE AUTORIZAÇÃO DE USO",
    )

    def normalized(doc: str) -> str:
        return unicodedata.normalize("NFKD", doc).encode("ascii", "ignore").decode("ascii").upper()

    kept = []
    removed = 0
    for doc in docs:
        ndoc = normalized(doc)
        if any(marker in ndoc for marker in fiscal_markers):
            removed += 1
            continue
        kept.append(doc.strip())

    # Só altera o arquivo quando uma DANFE foi realmente identificada e ainda
    # resta ao menos um documento de envio.
    if removed and kept:
        return "\n".join(kept).strip()
    return text


def _ml_fetch_shipping_zpl(shipment_id: str) -> str:
    query = urlencode({"shipment_ids": str(shipment_id), "response_type": "zpl2"})
    raw, _ = ml_api_get_bytes(f"/shipment_labels?{query}")
    return _ml_only_shipping_label_zpl(_ml_extract_zpl_from_label_response(raw))


def _ml_store_linked_label(*, operational_order_id: str, order_id: str, pack_id: str,
                           shipment_id: str, tracking: str, zpl: str,
                           invoice: dict[str, Any] | None) -> bool:
    if not operational_order_id or not shipment_id or not zpl.strip():
        return False
    # Limpa a trava-raiz legada que podia esconder a etiqueta recém-baixada.
    with DB_LOCK:
        DB.execute(
            "DELETE FROM admin_manual_overrides WHERE storage_key=? AND entity_id='__ROOT__'",
            ("conf_etiquetas",),
        )
        DB.commit()
    raw, _, _ = get_storage("conf_etiquetas")
    try:
        bank = json.loads(raw) if raw else {}
    except Exception:
        bank = {}
    if not isinstance(bank, dict):
        bank = {}
    bank["version"] = max(8, int(bank.get("version") or 0))
    bank.setdefault("registros", {})
    bank.setdefault("ordem", [])
    bank.setdefault("porChave", {})
    bank.setdefault("avisos", [])
    bank.setdefault("auditoria", [])
    bank.setdefault("resumo", {})
    bank.setdefault("vinculados", {})

    existing_id = ""
    for rid, rec in bank["registros"].items():
        if not isinstance(rec, dict) or rec.get("marketplace") != "mercado_livre":
            continue
        meta = rec.get("metadados") if isinstance(rec.get("metadados"), dict) else {}
        if str(meta.get("shipment_id") or "") == str(shipment_id) or (
            str(rec.get("pedido") or "") == str(operational_order_id)
            and str(rec.get("origem") or "").startswith("api_mercadolivre")
        ):
            existing_id = str(rid)
            break

    fiscal_key = str((invoice or {}).get("fiscal_key") or "").strip()
    invoice_number = str((invoice or {}).get("invoice_number") or "").strip()
    keys = [operational_order_id, order_id, pack_id, shipment_id, tracking, fiscal_key, invoice_number]
    keys = [str(x).strip() for x in keys if str(x or "").strip()]
    rid = existing_id or ("etq_ml_api_" + hashlib.sha1(str(shipment_id).encode("utf-8")).hexdigest()[:18])

    record = {
        "id": rid, "marketplace": "mercado_livre", "envio": zpl, "danfe": "",
        "arquivo": f"Mercado Livre API · shipment {shipment_id}",
        "metadados": {"pedido": operational_order_id, "venda": order_id, "pack_id": pack_id,
                      "shipment_id": shipment_id, "rastreio": tracking,
                      "nf": invoice_number, "chaveAcesso": fiscal_key},
        "chaves": keys, "vinculadoA": [operational_order_id], "pedido": operational_order_id,
        "vinculo": "api_mercadolivre_ready_to_print", "origem": "api_mercadolivre",
        "adicionadaEm": now_iso(), "adicionadaPor": "mercadolivre-api",
        "casa": ml_casa_atual(),  # V18.95: filial da etiqueta sem pedido na fila = a da conta
    }
    bank["registros"][rid] = record
    if rid not in bank["ordem"]:
        bank["ordem"].append(rid)
    bank["porChave"] = {}
    for record_id in bank["ordem"]:
        rec = bank["registros"].get(record_id)
        if not isinstance(rec, dict):
            continue
        for key in rec.get("chaves") or []:
            key = str(key or "").strip()
            if not key:
                continue
            bank["porChave"].setdefault(key, [])
            if record_id not in bank["porChave"][key]:
                bank["porChave"][key].append(record_id)
    bank["atualizadoEm"] = now_iso()
    if not any(isinstance(a, dict) and a.get("etiqueta")==rid and a.get("pedido")==operational_order_id
               for a in bank["auditoria"]):
        bank["auditoria"].append({"marketplace":"mercado_livre","pedido":operational_order_id,
                                  "criterio":"api_ready_to_print","etiqueta":rid,"arquivo":record["arquivo"]})
        bank["auditoria"] = bank["auditoria"][-250:]
    save_storage("conf_etiquetas", raw, json_dumps(bank), False,
                 actor="mercadolivre-api", actor_role="sistema",
                 source_screen="API Mercado Livre", change_method="Etiqueta automática após NF",
                 client_ip="127.0.0.1")
    return True


def _ml_fiscal_and_label_state(*, order: dict[str, Any], order_id: str, operational_order_id: str,
                               pack_id: str, shipment_id: str, shipment: dict[str, Any] | None,
                               tracking: str) -> dict[str, Any]:
    site_id = str(order.get("site_id") or "MLB").strip().upper() or "MLB"
    status = str((shipment or {}).get("status") or "").strip().lower()
    substatus = str((shipment or {}).get("substatus") or "").strip().lower()

    invoice: dict[str, Any] = {}
    invoice_available = False
    invoice_unavailable_reason = ""

    # Dados fiscais são apenas enriquecimento. Nesta aplicação o Mercado Livre
    # pode responder HTTP 403 / PolicyAgent; isso não bloqueia o fluxo operacional.
    if shipment_id:
        try:
            payload = ml_api_get(
                f"/shipments/{quote(str(shipment_id))}/invoice_data?siteId={quote(site_id)}"
            )
            if isinstance(payload, dict):
                invoice = payload
                invoice_available = _ml_invoice_available(invoice)
        except Exception as exc:
            msg = str(exc)
            if "HTTP 403" in msg or "PA_UNAUTHORIZED_RESULT_FROM_POLICIES" in msg or "PolicyAgent" in msg:
                invoice_unavailable_reason = "Dados fiscais indisponíveis para esta aplicação (HTTP 403 / PolicyAgent)."
            else:
                invoice_unavailable_reason = msg[:500]

    invoice_pending = status == "ready_to_ship" and substatus == "invoice_pending"

    # V14.4: o substatus invoice_pending pode ficar defasado por alguns minutos
    # mesmo depois de a etiqueta já estar disponível na interface do Mercado Livre.
    # A fonte de verdade operacional passa a ser o próprio endpoint de etiquetas:
    # se o shipment está ready_to_ship, tentamos buscar o ZPL.
    should_try_label = bool(shipment_id) and status == "ready_to_ship"

    label_stored = False
    label_error = ""
    if should_try_label:
        try:
            zpl = _ml_fetch_shipping_zpl(shipment_id)
            if zpl:
                label_stored = _ml_store_linked_label(
                    operational_order_id=operational_order_id,
                    order_id=order_id,
                    pack_id=pack_id,
                    shipment_id=shipment_id,
                    tracking=tracking,
                    zpl=zpl,
                    invoice=invoice,
                )
            else:
                label_error = "Mercado Livre respondeu sem ZPL de etiqueta."
        except Exception as exc:
            label_error = str(exc)[:1200]

    if label_stored:
        fiscal_status = "DISPONÍVEL"
    elif invoice_pending:
        fiscal_status = "AGUARDANDO"
    elif status == "ready_to_ship":
        fiscal_status = "PROCESSANDO"
    else:
        fiscal_status = "AGUARDANDO"

    return {
        "invoice": invoice,
        "invoice_available": invoice_available,
        "invoice_unavailable_reason": invoice_unavailable_reason,
        "invoice_pending": invoice_pending,
        "fiscal_ready": bool(label_stored) or not invoice_pending,
        "fiscal_status": fiscal_status,
        "shipment_status": status,
        "shipment_substatus": substatus,
        "label_stored": label_stored,
        "label_error": label_error,
        "ready_for_conference": bool(label_stored),
    }


def _ml_order_aliases(order_id: str, pack_id: str = "") -> set[str]:
    """Identificadores equivalentes usados pela API e pela tela do Mercado Livre.

    A tela/print pode exibir a venda sem o prefixo técnico 20000 do order_id.
    """
    aliases: set[str] = set()
    for raw in (order_id, pack_id):
        value = re.sub(r"\D+", "", str(raw or ""))
        if not value:
            continue
        aliases.add(value)
        if value.startswith("20000") and len(value) > 5:
            aliases.add(value[5:])
        # Fallback tolerante para números copiados da interface: últimos 11/12 dígitos.
        if len(value) > 12:
            aliases.add(value[-11:])
            aliases.add(value[-12:])
    return {normalize(x) for x in aliases if x}


def _ml_venda_da_linha(row: dict[str, Any]) -> str:
    """V19.85: venda real da linha. A chave da API (`MercadoLivreLinhaKey` = venda|item|variação|i)
    nasce com a venda e não era remarcada; o campo `VendaMercadoLivre` o vínculo antigo trocava
    pela última venda importada do carrinho. Sem a chave, o campo."""
    chave = str(row.get("MercadoLivreLinhaKey") or "").strip()
    if chave and "|" in chave:
        return chave.split("|", 1)[0].strip()
    return str(row.get("VendaMercadoLivre") or "").strip()


def _ml_linha_de_outra_venda(row: dict[str, Any], order_id: str, pack_id: str) -> bool:
    """V19.85: linha da API que é de outra venda do carrinho (só quem tem a chave da API)."""
    if not str(row.get("MercadoLivreLinhaKey") or "").strip():
        return False
    return _ml_venda_da_linha(row) not in {order_id, pack_id}


def _ml_bind_manual_pending_rows(
    pending: list[dict[str, Any]],
    *, order_id: str, pack_id: str, shipment_id: str, shipment: dict[str, Any] | None,
) -> int:
    """Vincula e também corrige linhas que gravaram PACK no campo VendaMercadoLivre."""
    aliases = _ml_order_aliases(order_id, pack_id)
    if not aliases:
        return 0
    operational_order_id = pack_id or order_id
    logistic = _ml_logistic_type(shipment)
    bound = 0
    for row in pending:
        if not isinstance(row, dict):
            continue
        marketplace = normalize(row.get("Marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        row_aliases: set[str] = set()
        for raw in (order_number(row), row.get("VendaMercadoLivre"), row.get("PackIdMercadoLivre")):
            digits = re.sub(r"\D+", "", str(raw or ""))
            if digits:
                row_aliases.update(_ml_order_aliases(digits, ""))
        if not row_aliases.intersection(aliases):
            continue
        # V19.85: a linha da API de OUTRA venda do mesmo carrinho não é tomada por esta.
        # Antes, importar a venda do pano avulso remarcava as linhas do kit (outra venda do
        # carrinho 2000015699983821, 26/10) e a limpeza a seguir apagava o hidratante.
        # Linha sem a chave da API (print, extensão, TXT) segue como antes.
        if _ml_linha_de_outra_venda(row, order_id, pack_id):
            continue
        old = (str(row.get("VendaMercadoLivre") or ""), str(row.get("PackIdMercadoLivre") or ""), str(row.get("ShipmentIdMercadoLivre") or ""))
        row["Pedido"] = operational_order_id
        row["VendaMercadoLivre"] = order_id
        row["Casa"] = ml_casa_atual()  # V18.94: o pedido manual passa a ser da casa da conta que o achou
        row["ContaMercadoLivre"] = ml_casa_atual()  # V18.95
        row["PackIdMercadoLivre"] = pack_id
        row["ShipmentIdMercadoLivre"] = shipment_id
        row["LogisticaMercadoLivre"] = logistic
        row["MercadoLivreAtualizadoEm"] = now_iso()
        original_source = str(row.get("OrigemCadastro") or "").strip()
        if "reconciliado mercado livre" not in original_source.lower():
            row["OrigemCadastro"] = (original_source + " / " if original_source else "") + "Reconciliado Mercado Livre"
        new = (order_id, pack_id, shipment_id)
        if old != new:
            bound += 1
    return bound

def _ml_manual_pending_numbers() -> set[str]:
    linked = _ml_linked_order_ids()
    result: set[str] = set()
    casa = ml_casa_atual()
    for row in _ml_fila_leitura():  # V20.04
        if not isinstance(row, dict):
            continue
        marketplace = normalize(row.get("Marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        if ml_casa_da_linha(row) != casa:  # V18.94: cada casa reconcilia só os pedidos dela
            continue
        sale_id = str(row.get("VendaMercadoLivre") or "").strip()
        if sale_id and sale_id in linked:
            continue
        # V18.78: linha que a API já reconheceu (venda E envio preenchidos por
        # _ml_bind_manual_pending_rows) não precisa ser reconciliada de novo a cada
        # 60 s — quem acompanha a etiqueta dela é o vigia de etiquetas pendentes
        # (_ml_all_pending_label_candidates). Antes, 71 pedidos eram reimportados
        # ~168 vezes em 12 h sem nada mudar.
        # Exceção: envio Full também fica fora do vigia de etiquetas — se a linha
        # sobreviveu (ADMIN protegeu), a reconciliação continua sendo quem a revê.
        if (sale_id and str(row.get("ShipmentIdMercadoLivre") or "").strip()
                and str(row.get("LogisticaMercadoLivre") or "").strip().lower() != "fulfillment"):
            continue
        for raw_id in (order_number(row), sale_id, row.get("PackIdMercadoLivre")):
            digits = re.sub(r"\D+", "", str(raw_id or ""))
            if digits:
                result.add(normalize(digits))
    return result

def ml_reconcile_manual_orders_once() -> dict[str, int]:
    """Reconcilia pedidos de print/extensão com a API e os coloca no watcher de etiqueta."""
    if not ML_MANUAL_RECONCILE_LOCK.acquire(blocking=False):
        return {"manual": 0, "matched": 0, "ready": 0, "errors": 0}
    try:
        manual_numbers = _ml_manual_pending_numbers()
        if not manual_numbers:
            return {"manual": 0, "matched": 0, "ready": 0, "errors": 0}

        _, seller_id = ml_access_token()
        cutoff = datetime.now(timezone.utc) - timedelta(days=ML_MANUAL_RECONCILE_DAYS)
        matched = ready = errors = 0
        remaining = set(manual_numbers)

        for page in range(ML_CATCHUP_MAX_PAGES):
            query = urlencode({
                "seller": seller_id,
                "order.status": "paid",
                "sort": "date_desc",
                "limit": str(ML_CATCHUP_PAGE_SIZE),
                "offset": str(page * ML_CATCHUP_PAGE_SIZE),
            })
            result = _ml_profitability_api_get(f"/orders/search?{query}", attempts=3)
            orders = result.get("results") if isinstance(result, dict) else []
            if not orders:
                break

            stop_by_date = False
            for order in orders:
                if not isinstance(order, dict):
                    continue
                created = _ml_parse_datetime(order.get("date_created"))
                if created is not None and created < cutoff:
                    stop_by_date = True
                    break

                order_id = str(order.get("id") or "").strip()
                pack_id = str(order.get("pack_id") or "").strip()
                aliases = _ml_order_aliases(order_id, pack_id)
                if not aliases.intersection(remaining):
                    continue

                try:
                    detail = ml_import_order(order_id, source="API Mercado Livre / reconciliação pedido manual")
                    matched += 1
                    remaining.difference_update(aliases)
                    if detail.get("ready_for_conference"):
                        ready += 1
                    # V18.78: "VINCULADO" só quando o vínculo foi criado agora; e só
                    # grava no log quando o resultado mudou.
                    ml_log_event_se_mudou(
                        "manual_reconcile", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                        "PEDIDO MANUAL VINCULADO" if int(detail.get("manual_rows_bound") or 0) > 0
                        else "PEDIDO MANUAL REVISTO / AGUARDANDO ETIQUETA",
                        json_dumps({
                            "order_id": order_id,
                            "pack_id": detail.get("pack_id") or "",
                            "shipment_id": detail.get("shipment_id") or "",
                            "ready_for_conference": bool(detail.get("ready_for_conference")),
                        })
                    )
                except Exception as exc:
                    errors += 1
                    ml_log_event_se_mudou(
                        "manual_reconcile", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                        "ERRO", str(exc)[:1200]
                    )
                if not remaining:
                    break

            if not remaining or stop_by_date or len(orders) < ML_CATCHUP_PAGE_SIZE:
                break

        return {"manual": len(manual_numbers), "matched": matched, "ready": ready, "errors": errors}
    finally:
        ML_MANUAL_RECONCILE_LOCK.release()


def ml_reconcile_manual_orders_loop(stop_event: threading.Event) -> None:
    """Roda inteiramente na VPS; navegador/PC pode ficar desligado."""
    # Primeira tentativa poucos segundos após o servidor iniciar.
    if stop_event.wait(5):
        return
    while not stop_event.is_set():
        try:
            # V14.6: reconcilia enquanto houver access_token utilizável. A ausência
            # de refresh_token impede apenas a renovação futura, não o uso do token atual.
            # V18.94: cada casa reconcilia só os pedidos manuais dela.
            for casa in ml_casas_conectadas():
                with ml_na_casa(casa):
                    ml_reconcile_manual_orders_once()
        except Exception as exc:
            try:
                ml_log_event_se_mudou("manual_reconcile", "/orders/search", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])
            except Exception:
                pass
        if stop_event.wait(ML_MANUAL_RECONCILE_INTERVAL):
            break


# V18.97: envio que já saiu — a venda não tem mais o que conferir nem etiqueta para imprimir.
ML_ENVIO_JA_DESPACHADO = frozenset({"shipped", "delivered", "not_delivered"})


def _ml_remove_cancelled_from_pending(
    pending: list[dict[str, Any]],
    *,
    order_id: str,
    pack_id: str = "",
) -> tuple[list[dict[str, Any]], int]:
    """Remove da fila pendente qualquer linha pertencente a uma venda ML cancelada."""
    order_id = str(order_id or "").strip()
    pack_id = str(pack_id or "").strip()
    removed = 0
    kept: list[dict[str, Any]] = []

    for row in pending:
        if not isinstance(row, dict):
            kept.append(row)
            continue

        marketplace = normalize(row.get("Marketplace"))
        is_ml = (
            "MERCADO LIVRE" in marketplace
            or "MERCADOLIVRE" in marketplace
            or bool(str(row.get("VendaMercadoLivre") or "").strip())
            or "mercado livre" in str(row.get("OrigemCadastro") or "").lower()
        )
        if not is_ml:
            kept.append(row)
            continue

        identifiers = {
            str(row.get("VendaMercadoLivre") or "").strip(),
            str(row.get("PackIdMercadoLivre") or "").strip(),
            str(order_number(row) or "").strip(),
        }
        identifiers.discard("")

        matched = bool(order_id and order_id in identifiers) or bool(pack_id and pack_id in identifiers)
        # V19.85: no carrinho, a linha da API de OUTRA venda fica (cancelar a venda do pano avulso
        # tirava também o kit da outra venda). Linha sem a chave da API segue como antes.
        if matched and _ml_linha_de_outra_venda(row, order_id, pack_id):
            matched = False
        # V18.52: ADMIN > integração — pedido incluído/protegido pelo ADMIN fica.
        if matched and not _admin_manual_pending_protected(row):
            removed += 1
            continue
        kept.append(row)

    return kept, removed



def _pending_removed_identities_v1852(before: list[Any], after: list[Any]) -> set[str]:
    """Identidades das linhas que saíram de `before` para `after` (V18.52)."""
    kept = {id(r) for r in after}
    return {
        _pending_identity_v1714(r, i)
        for i, r in enumerate(before)
        if isinstance(r, dict) and id(r) not in kept
    }


def _ml_row_manual_kit_override(row: dict[str, Any] | None) -> bool:
    if not isinstance(row, dict):
        return False
    return normalize(row.get("KitManualOverride")) in {"SIM", "YES", "TRUE", "1"}


def _ml_same_pending_sale(row: dict[str, Any], order_id: str, pack_id: str) -> bool:
    if not isinstance(row, dict):
        return False
    row_order = str(row.get("VendaMercadoLivre") or "").strip()
    row_pack = str(row.get("PackIdMercadoLivre") or "").strip()
    visible_order = str(order_number(row) or "").strip()
    return bool(
        (order_id and order_id in {row_order, visible_order})
        or (pack_id and pack_id in {row_pack, visible_order})
    )


def ml_import_order(order_id: str, *, source: str = "API Mercado Livre") -> dict[str, Any]:
    order_id = str(order_id or "").strip()
    if not order_id:
        raise RuntimeError("Order ID vazio.")
    order = ml_api_get(f"/orders/{quote(order_id)}")
    if not isinstance(order, dict):
        raise RuntimeError(f"Pedido {order_id}: resposta inválida.")

    # V14.20: em algumas contas MLB o order padrão chega sem buyer.billing_info.id,
    # embora a tela do Mercado Livre mostre os Dados para NF-e. Nesse caso refaz a
    # leitura no contrato v2 e incorpora SOMENTE o identificador fiscal do comprador.
    buyer0 = order.get("buyer") if isinstance(order.get("buyer"), dict) else {}
    billing0 = buyer0.get("billing_info")
    billing0_id = (billing0.get("id") if isinstance(billing0, dict) else billing0) or ""
    if not str(billing0_id).strip():
        try:
            try:
                order_v2 = ml_api_get(f"/orders/{quote(order_id)}", headers={"X-Api-Version": "2"})
            except Exception:
                order_v2 = ml_api_get(f"/orders/{quote(order_id)}", headers={"x-version": "2"})
            if isinstance(order_v2, dict):
                buyer_v2 = order_v2.get("buyer") if isinstance(order_v2.get("buyer"), dict) else {}
                billing_v2 = buyer_v2.get("billing_info")
                billing_v2_id = (billing_v2.get("id") if isinstance(billing_v2, dict) else billing_v2) or ""
                if str(billing_v2_id).strip():
                    buyer_merged = dict(buyer0)
                    buyer_merged["billing_info"] = billing_v2
                    order["buyer"] = buyer_merged
                # Se o contrato v2 trouxer site_id e o padrão não, aproveita também.
                if not str(order.get("site_id") or "").strip() and str(order_v2.get("site_id") or "").strip():
                    order["site_id"] = order_v2.get("site_id")
        except Exception as exc:
            try:
                ml_log_event("billing_info", f"/orders/{order_id}", "", ML_CLIENT_ID, "FALLBACK_V2_ERRO", str(exc)[:1200])
            except Exception:
                pass
    _, seller_id = ml_access_token()
    seller = order.get("seller") if isinstance(order.get("seller"), dict) else {}
    order_seller = str(seller.get("id") or "")
    if order_seller and seller_id and order_seller != seller_id:
        raise RuntimeError(f"Pedido {order_id} pertence a outro seller.")

    status = str(order.get("status") or "")
    shipment_id, shipment = _ml_resolve_forward_shipment(order_id, order)
    pack_id = str(order.get("pack_id") or "").strip()
    operational_order_id = pack_id or order_id

    current_raw, _, _ = get_storage("conf_pedidos")
    pending = _rows_from_storage_value(current_raw)

    # Antes de criar qualquer linha da API, tenta reconhecer pedidos que entraram
    # por print/extensão usando o número de venda visível do Mercado Livre.
    manual_rows_bound = _ml_bind_manual_pending_rows(
        pending,
        order_id=order_id,
        pack_id=pack_id,
        shipment_id=shipment_id,
        shipment=shipment,
    )

    # V16.74: se este pedido foi corrigido manualmente no Admin, a composição
    # e as quantidades locais passam a ser a fonte de verdade. Notificações,
    # refresh manual e sincronizações do Mercado Livre não podem desfazer isso.
    manual_kit_override = any(
        _ml_same_pending_sale(row, order_id, pack_id) and _ml_row_manual_kit_override(row)
        # V19.85: o kit corrigido pelo ADMIN numa venda não trava a outra venda do carrinho.
        and not _ml_linha_de_outra_venda(row, order_id, pack_id)
        for row in pending if isinstance(row, dict)
    )

    # V16.36: vendas canceladas não podem continuar aparecendo em Pedidos pendentes.
    # O Mercado Livre pode enviar "cancelled" ou "canceled" conforme o recurso.
    if status.strip().lower() in {"cancelled", "canceled"}:
        before_rows = pending
        pending, removed = _ml_remove_cancelled_from_pending(
            pending, order_id=order_id, pack_id=pack_id
        )
        if removed:
            save_storage(
                "conf_pedidos", current_raw, json_dumps(pending), False,
                actor="mercadolivre-api", actor_role="sistema",
                source_screen="API Mercado Livre",
                change_method="Pedido cancelado no Mercado Livre",
                client_ip="127.0.0.1", allow_completed_reimport=False,
                remove_pending_identities=_pending_removed_identities_v1852(before_rows, pending),
            )
        ml_log_event(
            "order_cancelled", f"/orders/{order_id}", "", ML_CLIENT_ID,
            "REMOVIDO DOS PENDENTES",
            json_dumps({"order_id": order_id, "pack_id": pack_id, "removed_rows": removed}),
        )
        return {
            "order_id": order_id,
            "pack_id": pack_id,
            "shipment_id": shipment_id,
            "status": status,
            "cancelled": True,
            "removed_pending_rows": removed,
            "manual_rows_bound": manual_rows_bound,
            "ready_for_conference": False,
            "fiscal_ready": False,
            "label_stored": False,
        }

    # Full/Fulfillment é preparado e expedido pelo próprio Mercado Livre.
    # Não deve entrar na fila operacional da Expedição Noromak. Se a linha já
    # tiver sido criada por uma versão anterior da API, removemos somente as
    # linhas originadas pela própria API ao reencontrar esse pedido.
    if _ml_is_full_shipment(shipment):
        before_rows = pending
        before = len(pending)
        pending = [
            row for row in pending
            if not (
                isinstance(row, dict)
                and not _admin_manual_pending_protected(row)
                and (
                    str(row.get("VendaMercadoLivre") or "").strip() == order_id
                    or (pack_id and str(row.get("PackIdMercadoLivre") or "").strip() == pack_id)
                )
                and (
                    str(row.get("VendaMercadoLivre") or "").strip()
                    or "mercado livre" in str(row.get("OrigemCadastro") or "").lower()
                )
            )
        ]
        removed = before - len(pending)
        if removed:
            save_storage(
                "conf_pedidos", current_raw, json_dumps(pending), False,
                actor="mercadolivre-api", actor_role="sistema",
                source_screen="API Mercado Livre",
                change_method="Ignorado - Mercado Envios Full",
                client_ip="127.0.0.1", allow_completed_reimport=False,
                remove_pending_identities=_pending_removed_identities_v1852(before_rows, pending),
            )
        _ml_full_ignorado_registrar(order_id, source)  # V18.78: o vigia e o catch-up não voltam a este pedido
        return {
            "order_id": order_id,
            "pack_id": pack_id,
            "shipment_id": shipment_id,
            "status": status,
            "ignored": True,
            "reason": "FULL",
            "logistic_type": _ml_logistic_type(shipment),
            "removed_existing_api_rows": removed,
            "inserted": 0,
            "updated": 0,
            "items": 0,
        }

    # V18.97: venda cujo envio JÁ SAIU (despachado, entregue, não entregue) não é trabalho de
    # expedição. Produção 10/10: ao conectar a conta de Bauru o vigia trouxe as vendas pagas de
    # setembro/outubro já entregues e o dono teve de excluir uma a uma. Mesma regra do Full: não
    # entra na fila, a linha que a integração criou sai (pedido protegido pelo ADMIN fica) e o
    # pedido vai para a memória do vigia (não volta a ser importado a cada 20 s).
    status_envio = str((shipment or {}).get("status") or "").strip().lower() if isinstance(shipment, dict) else ""
    if status_envio in ML_ENVIO_JA_DESPACHADO:
        before_rows = pending
        before = len(pending)
        pending = [
            row for row in pending
            if not (
                isinstance(row, dict)
                and not _admin_manual_pending_protected(row)
                and (
                    str(row.get("VendaMercadoLivre") or "").strip() == order_id
                    or (pack_id and str(row.get("PackIdMercadoLivre") or "").strip() == pack_id)
                )
                and (
                    str(row.get("VendaMercadoLivre") or "").strip()
                    or "mercado livre" in str(row.get("OrigemCadastro") or "").lower()
                )
            )
        ]
        removed = before - len(pending)
        if removed:
            save_storage(
                "conf_pedidos", current_raw, json_dumps(pending), False,
                actor="mercadolivre-api", actor_role="sistema",
                source_screen="API Mercado Livre",
                change_method=f"Ignorado - envio já {status_envio}",
                client_ip="127.0.0.1", allow_completed_reimport=False,
                remove_pending_identities=_pending_removed_identities_v1852(before_rows, pending),
            )
        _ml_full_ignorado_registrar(order_id, source)  # memória do vigia (a tabela é a do Full)
        return {
            "order_id": order_id,
            "pack_id": pack_id,
            "shipment_id": shipment_id,
            "status": status,
            "ignored": True,
            "reason": "DESPACHADO",
            "shipment_status": status_envio,
            "removed_existing_api_rows": removed,
            "inserted": 0,
            "updated": 0,
            "items": 0,
        }

    # V18.78: o pedido chegou aqui como NÃO-Full. Se um dia entrou na memória de Full
    # (leitura errada do envio, mudança de logística), o dado ao vivo desfaz — cache
    # nunca é fonte de verdade (CLAUDE.md, seção 1).
    _ml_full_ignorado_esquecer(order_id)

    receiver = ""
    if isinstance(shipment, dict):
        # Contrato Hosted/New Format (2026): o destinatário vem em
        # destination.receiver_name. Mantém receiver_address como fallback
        # para compatibilidade com a vista anterior.
        destination = shipment.get("destination") if isinstance(shipment.get("destination"), dict) else {}
        addr = shipment.get("receiver_address") if isinstance(shipment.get("receiver_address"), dict) else {}
        receiver = str(
            destination.get("receiver_name")
            or addr.get("receiver_name")
            or addr.get("receiver")
            or ""
        ).strip()
    buyer = order.get("buyer") if isinstance(order.get("buyer"), dict) else {}

    # V14.27: prioriza sempre Dados para NF-e. Em pedidos recém-criados o
    # billing-info pode ainda não existir; nesse intervalo usa somente o NOME REAL
    # do comprador da própria order (first_name + last_name). Nunca usa nickname,
    # username, receiver_name ou "Quem recebe". Assim Cliente não fica vazio e,
    # quando o fiscal aparecer, um refresh posterior o substitui automaticamente.
    billing_details = _ml_billing_details(order)
    fiscal_name = str(billing_details.get("name") or "").strip()
    buyer_real_name = _ml_real_buyer_name(order)
    client = fiscal_name or buyer_real_name
    client_name_source = "dados_fiscais_nf" if fiscal_name else ("comprador_order" if buyer_real_name else "")
    # V17.84: CPF/CNPJ do comprador, usado para localizar o cliente no Linx DMS.
    fiscal_doc_type = str(billing_details.get("doc_type") or "").strip().upper()
    fiscal_doc_number = re.sub(r"\D", "", str(billing_details.get("doc_number") or ""))
    billing_info_id = str(billing_details.get("billing_info_id") or "").strip()
    billing_errors = billing_details.get("errors") if isinstance(billing_details.get("errors"), list) else []

    date_for_dispatch = _ml_dispatch_date(shipment_id, shipment)
    tracking = ""
    if isinstance(shipment, dict):
        tracking = str(shipment.get("tracking_number") or shipment.get("tracking_id") or "").strip()

    fiscal_state = _ml_fiscal_and_label_state(
        order=order, order_id=order_id, operational_order_id=operational_order_id,
        pack_id=pack_id, shipment_id=shipment_id, shipment=shipment, tracking=tracking
    )
    invoice = fiscal_state.get("invoice") if isinstance(fiscal_state.get("invoice"), dict) else {}
    invoice_number = str(invoice.get("invoice_number") or "").strip()
    fiscal_key = str(invoice.get("fiscal_key") or "").strip()

    products_raw, _, _ = get_storage("conf_produtos")
    products = _rows_from_storage_value(products_raw)
    lines: list[dict[str, Any]] = []

    kit_catalog = _load_kit_catalog()
    kit_applied = 0
    kit_unregistered = 0

    for item_data in order.get("order_items") or []:
        if not isinstance(item_data, dict):
            continue
        item = item_data.get("item") if isinstance(item_data.get("item"), dict) else {}

        for expanded_index, expanded in enumerate(_expand_ml_order_item(item_data, kit_catalog)):
            sku_raw = str(expanded.get("sku_raw") or "")
            sku = str(expanded.get("sku") or "").strip()
            quantity = max(1, int(expanded.get("quantity") or 1))
            is_kit = bool(expanded.get("is_kit"))
            if is_kit:
                kit_applied += 1
            if expanded.get("kit_unregistered"):
                kit_unregistered += 1

            description = str(expanded.get("description") or item.get("title") or "").strip()
            kit_name = str(expanded.get("kit_name") or "").strip()
            kit_sku = str(expanded.get("kit_sku") or "").strip()
            warning = ""
            if expanded.get("kit_unregistered"):
                warning = "KIT NÃO CADASTRADO — VERIFICAR COMPOSIÇÃO"

            row = {
                "Pedido": operational_order_id,
                "Marketplace": "MERCADO LIVRE",
                "Data do Pedido": date_for_dispatch,
                "Kit": "SIM" if is_kit else ("VERIFICAR" if warning else ""),
                "Nome do Kit": kit_name,
                "Quantidade de Kits": str(expanded.get("kits_sold") or "") if is_kit else "",
                "Quantidade por Kit": str(expanded.get("qty_per_kit") or "") if is_kit else "",
                "SkuKitOrigem": kit_sku,
                "Observação": warning,
                "Cliente": client,
                "SKU": sku,
                "Quantidade": str(quantity),
                "Código de Barras": "",
                "Descrição": description,
                "Rua": "",
                "Módulo": "",
                "Prateleira": "",
                "Nível": "",
                "Posição": "",
                "Foto": "",
                "Código de Rastreio": tracking,
                "NF": invoice_number,
                "Nota Fiscal": invoice_number,
                "Chave de Acesso": fiscal_key,
                "Status NF Mercado Livre": str(fiscal_state.get("fiscal_status") or "AGUARDANDO"),
                "Etiqueta API Mercado Livre": "VINCULADA" if fiscal_state.get("label_stored") else "AGUARDANDO",
                # V17.47: identidade da linha ML independe do SKU. O SKU pode
                # mudar/corrigir sem criar uma segunda venda no banco.
                "MercadoLivreLinhaKey": f"{order_id}|{item.get('id')}|{item.get('variation_id')}|{expanded_index}",
                "MercadoLivreItemId": str(item.get("id") or ""),
                "MercadoLivreVariationId": str(item.get("variation_id") or ""),
                "__uidLinha": "MLAPI_" + hashlib.sha1(
                    f"{order_id}|{item.get('id')}|{item.get('variation_id')}|{expanded_index}".encode("utf-8")
                ).hexdigest()[:20],
                "OrigemCadastro": source,
                "SkuOrigemImportacao": sku_raw,
                "VendaMercadoLivre": order_id,
                "PackIdMercadoLivre": pack_id,
                "ShipmentIdMercadoLivre": shipment_id,
                "StatusMercadoLivre": status,
                # V18.94: casa da expedição = conta do ML de onde o pedido veio.
                # V18.95: a filial (Casa) pode ser mudada pelo ADMIN ("Mover de filial",
                # protegida pelo override); a conta (ContaMercadoLivre) não muda.
                "Casa": ml_casa_atual(),
                "ContaMercadoLivre": ml_casa_atual(),
                "LogisticaMercadoLivre": _ml_logistic_type(shipment),
                "NomeFiscalMercadoLivre": fiscal_name,
                "CPFMercadoLivre": fiscal_doc_number if fiscal_doc_type == "CPF" else "",
                "CNPJMercadoLivre": fiscal_doc_number if fiscal_doc_type == "CNPJ" else "",
                "DataLimiteDespachoMercadoLivre": date_for_dispatch,
                "MercadoLivreAtualizadoEm": now_iso(),
            }
            product = None
            for candidate in _ml_sku_lookup_candidates(sku):
                product = _ml_find_product(products, candidate)
                if product:
                    break
            if product:
                # O cadastro interno pode enriquecer EAN/localização, mas nunca
                # substituir o SKU real recebido do Mercado Livre.
                for field in ("Código de Barras","Descrição","Rua","Módulo","Prateleira","Nível","Posição","Foto"):
                    value = product.get(field)
                    if str(value or "").strip():
                        row[field] = value
            lines.append(row)

    # Consolida componentes repetidos do mesmo pedido/SKU. Isso também permite
    # somar um item avulso com o mesmo SKU de um componente de kit.
    consolidated: dict[str, dict[str, Any]] = {}
    for row in lines:
        key = normalize(row.get("SKU"))
        if not key:
            key = str(row.get("__uidLinha") or "")
        if key not in consolidated:
            consolidated[key] = row
            continue
        target = consolidated[key]
        target["Quantidade"] = str(int(target.get("Quantidade") or 0) + int(row.get("Quantidade") or 0))
        if row.get("Kit") == "SIM":
            target["Kit"] = "SIM"
            names = [str(target.get("Nome do Kit") or "").strip(), str(row.get("Nome do Kit") or "").strip()]
            target["Nome do Kit"] = " + ".join(dict.fromkeys(x for x in names if x))
        if row.get("Observação"):
            target["Observação"] = str(row.get("Observação"))
    lines = list(consolidated.values())

    if not lines:
        raise RuntimeError(f"Pedido {order_id} não trouxe itens.")

    if manual_kit_override:
        # Mantém EXATAMENTE SKU, Quantidade e metadados do kit corrigidos manualmente.
        # Atualiza apenas informações operacionais/fiscais vindas do Mercado Livre.
        inserted = 0
        updated = 0
        safe_fields = (
            "Marketplace","Data do Pedido","Cliente","Código de Rastreio",
            "NF","Nota Fiscal","Chave de Acesso","Status NF Mercado Livre",
            "Etiqueta API Mercado Livre","Observação"
        )
        api_fields = (
            "OrigemCadastro","VendaMercadoLivre","PackIdMercadoLivre",
            "ShipmentIdMercadoLivre","StatusMercadoLivre","LogisticaMercadoLivre",
            "NomeFiscalMercadoLivre","CPFMercadoLivre","CNPJMercadoLivre",
            "DataLimiteDespachoMercadoLivre","MercadoLivreAtualizadoEm"
        )

        # Dados operacionais são iguais por venda; usa a primeira linha importada
        # e preserva o cadastro manual de cada componente.
        reference = lines[0] if lines else {}
        for existing in pending:
            if not isinstance(existing, dict) or not _ml_same_pending_sale(existing, order_id, pack_id):
                continue
            if _ml_linha_de_outra_venda(existing, order_id, pack_id):   # V19.85
                continue
            if not _ml_row_manual_kit_override(existing):
                continue

            lido = int(existing.get("Lido") or 0)
            for field in safe_fields:
                value = reference.get(field)
                if str(value or "").strip():
                    existing[field] = value
            for field in api_fields:
                existing[field] = reference.get(field, existing.get(field, ""))

            # Reafirma explicitamente os campos protegidos.
            existing["KitManualOverride"] = "SIM"
            existing["Lido"] = lido
            if int(existing.get("Quantidade") or 0) < lido:
                existing["Quantidade"] = str(lido)
            updated += 1

        stale_removed = 0
    else:
        # Remove linhas antigas deste pedido que não existem mais na composição atual.
        # Isso permite cadastrar um kit depois e, na sincronização seguinte, substituir
        # a antiga linha KITxxxx pelos componentes corretos sem duplicação.
        desired_keys = {normalize(row.get("SKU")) for row in lines if normalize(row.get("SKU"))}
        cleaned_pending: list[dict[str, Any]] = []
        stale_removed = 0
        for existing in pending:
            if not isinstance(existing, dict):
                cleaned_pending.append(existing)
                continue
            same_ml_order = _ml_venda_da_linha(existing) == order_id
            manual_sku = normalize(existing.get("SkuManualOverride")) == "sim"
            existing_sku = _ml_normalize_api_sku(str(existing.get("SKU") or existing.get("Código de Barras") or "").strip())
            source_sku = _ml_normalize_api_sku(str(existing.get("SkuOrigemImportacao") or "").strip())
            if same_ml_order and not manual_sku and normalize(existing_sku) not in desired_keys and normalize(source_sku) not in desired_keys:
                stale_removed += 1
                continue
            cleaned_pending.append(existing)
        pending = cleaned_pending

        # Atualiza pela combinação Pedido + SKU; quando não existe, cria nova linha.
        by_key: dict[tuple[str, str], dict[str, Any]] = {}
        for existing in pending:
            # V19.85: no carrinho o Pedido é o número do carrinho; a linha da API de OUTRA venda
            # com o mesmo SKU (pano avulso x pano do kit, carrinho 2000015699983821) não é esta.
            if _ml_linha_de_outra_venda(existing, order_id, pack_id):
                continue
            existing_sku = str(existing.get("SKU") or existing.get("Código de Barras") or "").strip()
            is_ml_api_row = bool(
                str(existing.get("VendaMercadoLivre") or "").strip()
                or "mercado livre" in str(existing.get("OrigemCadastro") or "").lower()
            )
            if is_ml_api_row:
                existing_sku = _ml_normalize_api_sku(existing_sku)
            pedido_key = normalize(order_number(existing))
            keys = [normalize(existing_sku)]
            # Quando o SKU foi corrigido manualmente, o SKU original da API vira
            # a chave de reconciliação. Assim a sincronização encontra a mesma linha
            # sem desfazer a correção do operador.
            if normalize(existing.get("SkuManualOverride")) == "sim":
                original = _ml_normalize_api_sku(existing.get("SkuOrigemImportacao"))
                if normalize(original):
                    keys.append(normalize(original))
            for sku_key in keys:
                key = (pedido_key, sku_key)
                if sku_key and key not in by_key:
                    by_key[key] = existing

        inserted = updated = 0
        fields = (
            "Pedido","Marketplace","Data do Pedido","Cliente","SKU","Quantidade","Código de Barras",
            "Descrição","Rua","Módulo","Prateleira","Nível","Posição","Foto","Código de Rastreio",
            "NF","Nota Fiscal","Chave de Acesso","Status NF Mercado Livre","Etiqueta API Mercado Livre",
            "Kit","Nome do Kit","Quantidade de Kits","Quantidade por Kit","SkuKitOrigem","Observação"
        )
        uids_na_fila = {str(r.get("__uidLinha") or "") for r in pending if isinstance(r, dict)}
        for imported in lines:
            key = (normalize(imported["Pedido"]), normalize(imported.get("SKU") or imported.get("Código de Barras")))
            existing = by_key.get(key)
            if existing is None:
                # V19.85: o UID depende só da posição do item. Se já há na fila outra linha com
                # ele (linha fundida pela regra antiga do carrinho), a nova ganha um UID próprio:
                # UID repetido passa o bip de uma para a outra e a exclusão do ADMIN derruba as duas.
                # Sem colisão o UID não muda (o tombstone de linha do ADMIN é por UID).
                if str(imported.get("__uidLinha") or "") in uids_na_fila:
                    imported["__uidLinha"] = "MLAPI_" + hashlib.sha1(
                        f"{imported.get('MercadoLivreLinhaKey')}|C:{normalize(imported.get('SKU'))}".encode("utf-8")
                    ).hexdigest()[:20]
                uids_na_fila.add(str(imported.get("__uidLinha") or ""))
                pending.append(imported)
                by_key[key] = imported
                inserted += 1
                continue
            lido = int(existing.get("Lido") or 0)
            manual_sku = normalize(existing.get("SkuManualOverride")) == "sim"
            protected_when_manual = {"SKU","Código de Barras","Descrição","Rua","Módulo","Prateleira","Nível","Posição","Foto"}
            for field in fields:
                if manual_sku and field in protected_when_manual:
                    continue
                value = imported.get(field)
                if str(value or "").strip():
                    existing[field] = value
            for field in (
                "OrigemCadastro","VendaMercadoLivre","PackIdMercadoLivre",
                "ShipmentIdMercadoLivre","StatusMercadoLivre","LogisticaMercadoLivre",
                "NomeFiscalMercadoLivre","CPFMercadoLivre","CNPJMercadoLivre",
                "DataLimiteDespachoMercadoLivre","MercadoLivreAtualizadoEm",
                "MercadoLivreLinhaKey","MercadoLivreItemId","MercadoLivreVariationId"
            ):
                existing[field] = imported.get(field, "")
            # O SKU original da integração é mantido como referência de reconciliação.
            if not str(existing.get("SkuOrigemImportacao") or "").strip():
                existing["SkuOrigemImportacao"] = imported.get("SkuOrigemImportacao", "")
            existing["Lido"] = lido
            if int(existing.get("Quantidade") or 0) < lido:
                existing["Quantidade"] = str(lido)
            updated += 1

    # V14.18: o nome do cliente pertence ao pedido, não ao SKU.
    # Força a atualização em TODAS as linhas ligadas à mesma venda ML, mesmo quando
    # Pedido+SKU mudou (kit, SKU normalizado, linha manual antiga etc.). Isso evita
    # que uma linha velha preserve nickname/nome incorreto após o refresh.
    forced_client_rows = 0
    if client:
        for existing in pending:
            if not isinstance(existing, dict):
                continue
            same_order = str(existing.get("VendaMercadoLivre") or "").strip() == order_id
            same_pack = bool(pack_id) and str(existing.get("PackIdMercadoLivre") or "").strip() == pack_id
            if same_order or same_pack:
                if str(existing.get("Cliente") or "").strip() != client:
                    forced_client_rows += 1
                existing["Cliente"] = client
                existing["NomeFiscalMercadoLivre"] = fiscal_name
                if fiscal_doc_number:
                    existing["CPFMercadoLivre"] = fiscal_doc_number if fiscal_doc_type == "CPF" else ""
                    existing["CNPJMercadoLivre"] = fiscal_doc_number if fiscal_doc_type == "CNPJ" else ""
                existing["FonteNomeClienteMercadoLivre"] = client_name_source
                existing["MercadoLivreAtualizadoEm"] = now_iso()

    # Cancelamentos não apagam o pedido; apenas ficam marcados para auditoria/ação manual.
    new_json = json_dumps(pending)
    save_storage(
        "conf_pedidos",
        current_raw,
        new_json,
        False,
        actor="mercadolivre-api",
        actor_role="sistema",
        source_screen="API Mercado Livre",
        change_method="Notificação / sincronização",
        client_ip="127.0.0.1",
        allow_completed_reimport=False,
    )
    _ml_conta_atualizar("last_sync_at=?, updated_at=?, last_error=''", (now_iso(), now_iso()))  # V18.94: conta da casa
    return {
        "order_id": order_id,
        "pack_id": pack_id,
        "shipment_id": shipment_id,
        "status": status,
        "inserted": inserted,
        "updated": updated,
        "items": len(lines),
        "invoice_available": bool(fiscal_state.get("invoice_available")),
        "invoice_unavailable_reason": str(fiscal_state.get("invoice_unavailable_reason") or ""),
        "fiscal_ready": bool(fiscal_state.get("fiscal_ready")),
        "fiscal_status": str(fiscal_state.get("fiscal_status") or ""),
        "label_stored": bool(fiscal_state.get("label_stored")),
        "ready_for_conference": bool(fiscal_state.get("ready_for_conference")),
        "shipment_substatus": str(fiscal_state.get("shipment_substatus") or ""),
        "label_error": str(fiscal_state.get("label_error") or ""),
        "fiscal_name": fiscal_name,
        "fiscal_name_updated": bool(fiscal_name),
        "buyer_real_name": buyer_real_name,
        "client_name": client,
        "client_name_source": client_name_source,
        "billing_info_id": billing_info_id,
        "billing_info_errors": billing_errors,
        "fiscal_name_available": bool(fiscal_name),
        "forced_client_rows": forced_client_rows,
        "kit_components_applied": kit_applied,
        "kit_unregistered": kit_unregistered,
        "stale_rows_removed": stale_removed,
        "manual_rows_bound": manual_rows_bound,
        "manual_kit_override_preserved": bool(manual_kit_override),
    }


# V20.18: reforço do aviso do ML (revisão de segurança de 08/10). O endereço é aberto (quem chama é
# o ML) e aceitava aviso sem application_id/user_id, de qualquer recurso, abrindo uma tarefa por aviso
# sem limite. Desde a V20.16 o aviso é quem traz pedido e etiqueta. Agora: só pedido/envio com número,
# do nosso aplicativo e de conta conectada; recusa registrada uma vez por motivo e por hora; avisos numa
# fila de tamanho fixo com poucas tarefas. Em produção (04/11) todos os 2.244 avisos de pedido e envio
# das duas contas vieram com application_id e user_id.
ML_AVISO_MAX_BYTES = 64 * 1024
ML_AVISO_TAREFAS = 3
ML_AVISO_FILA_MAX = 500
_ML_AVISO_RECURSO = {
    "orders_v2": re.compile(r"/orders/(\d{1,20})/?"),
    "orders": re.compile(r"/orders/(\d{1,20})/?"),
    "shipments": re.compile(r"/shipments/(\d{1,20})/?"),
}
_ML_AVISO_FILA: "queue.Queue[tuple[str, dict[str, Any]]]" = queue.Queue(maxsize=ML_AVISO_FILA_MAX)
_ML_AVISO_NA_FILA: set[str] = set()
_ML_AVISO_LOCK = threading.Lock()
_ML_AVISO_TAREFAS_INICIADAS = False


def _ml_aviso_conferir(topic: str, resource: str, user_id: str, app_id: str) -> tuple[str, str | None]:
    """V20.18: (motivo da recusa, casa). Motivo vazio = o aviso pode ir ao ML, na casa devolvida."""
    padrao = _ML_AVISO_RECURSO.get(topic)
    if padrao is None:
        return "tópico sem ação configurada", None
    if not padrao.fullmatch(resource):
        return "recurso fora do formato esperado", None
    if ML_CLIENT_ID and app_id != ML_CLIENT_ID:
        return ("aviso sem application_id" if not app_id
                else "application_id diferente do aplicativo configurado"), None
    if not user_id.isdigit():
        return "aviso sem user_id", None
    # V18.94: o aviso vai para a casa dona do user_id.
    casa = ml_casa_do_seller(user_id)
    if casa is None:
        return "user_id de conta que não está conectada", None
    return "", casa


def _ml_aviso_recusado(topic: str, resource: str, user_id: str, app_id: str, motivo: str) -> None:
    # Um registro por motivo e por hora: aviso falso em massa não vira um INSERT por aviso.
    hora = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H")
    if _log_se_mudou(("ml-aviso", motivo), (hora, "")):
        ml_log_event(topic[:60], resource[:200], user_id[:40], app_id[:40], "IGNORADO", motivo)


def ml_process_notification(payload: dict[str, Any]) -> None:
    topic = str(payload.get("topic") or "").strip()
    resource = str(payload.get("resource") or "").strip()
    user_id = str(payload.get("user_id") or "").strip()
    app_id = str(payload.get("application_id") or "").strip()
    motivo, casa = _ml_aviso_conferir(topic, resource, user_id, app_id)
    if motivo:
        _ml_aviso_recusado(topic, resource, user_id, app_id, motivo)
        return
    with ml_na_casa(casa):
        _ml_process_notification_na_casa(payload, topic, resource, user_id, app_id)


def ml_aviso_enfileirar(payload: dict[str, Any]) -> str:
    """V20.18: põe o aviso na fila. 'na_fila', 'repetido' (o mesmo recurso ainda não foi pego, e a
    tarefa vai ler o dado atual no ML) ou 'fila_cheia' (descartado: o vigia de 5 min cobre)."""
    chave = f"{str(payload.get('topic') or '')[:40]}|{str(payload.get('resource') or '')[:200]}"
    with _ML_AVISO_LOCK:
        if chave in _ML_AVISO_NA_FILA:
            return "repetido"
        try:
            _ML_AVISO_FILA.put_nowait((chave, payload))
        except queue.Full:
            cheia = True
        else:
            cheia = False
            _ML_AVISO_NA_FILA.add(chave)
    if cheia:
        _ml_aviso_recusado("webhook", "", "", "", "fila de avisos cheia")
        return "fila_cheia"
    _ml_aviso_iniciar_tarefas()
    return "na_fila"


def _ml_aviso_saiu_da_fila(item: tuple[str, dict[str, Any]]) -> None:
    # Sai do conjunto quando a tarefa PEGA o aviso: um aviso novo do mesmo pedido durante o
    # tratamento ainda entra (a leitura em andamento pode ser anterior à mudança).
    with _ML_AVISO_LOCK:
        _ML_AVISO_NA_FILA.discard(item[0])


def _ml_aviso_tarefa() -> None:
    while True:
        item = _ML_AVISO_FILA.get()
        try:
            _ml_aviso_saiu_da_fila(item)
            ml_process_notification(item[1])
        except Exception as exc:
            print(f"[ml-aviso] erro ao tratar {item[0]}: {exc}", flush=True)
        finally:
            _ML_AVISO_FILA.task_done()


def _ml_aviso_iniciar_tarefas() -> None:
    global _ML_AVISO_TAREFAS_INICIADAS
    if _ML_AVISO_TAREFAS_INICIADAS:
        return
    with _ML_AVISO_LOCK:
        if _ML_AVISO_TAREFAS_INICIADAS:
            return
        for i in range(ML_AVISO_TAREFAS):
            threading.Thread(target=_ml_aviso_tarefa, daemon=True, name=f"ml-aviso-{i + 1}").start()
        _ML_AVISO_TAREFAS_INICIADAS = True


def _ml_process_notification_na_casa(payload: dict[str, Any], topic: str, resource: str, user_id: str, app_id: str) -> None:
    try:
        if topic in {"orders_v2", "orders"} and "/orders/" in resource:
            order_id = resource.rstrip("/").split("/")[-1]
            result = ml_import_order(order_id, source="API Mercado Livre / orders_v2")
            if result.get("cancelled"):
                event_result, prefix = "CANCELADO / REMOVIDO DOS PENDENTES", ""
            elif result.get("ignored"):
                event_result, prefix = "FULL IGNORADO", ""
            elif result.get("ready_for_conference"):
                event_result, prefix = "PRONTO PARA CONFERÊNCIA", "Etiqueta vinculada automaticamente · "
            elif result.get("fiscal_status") == "PROCESSANDO":
                event_result, prefix = "NF LIBERADA / ETIQUETA AGUARDANDO", ""
            elif result.get("fiscal_name_updated"):
                event_result, prefix = "NOME FISCAL ATUALIZADO", ""
            else:
                event_result, prefix = "NF AGUARDANDO", ""
            ml_log_event(topic, resource, user_id, app_id, event_result, prefix + json_dumps(result))
            return
        if topic == "shipments" and "/shipments/" in resource:
            shipment_id = resource.rstrip("/").split("/")[-1]
            orders = ml_api_get(
                f"/shipments/{quote(shipment_id)}/orders",
                headers={"X-New-Domain": "true"},
            )
            results = []
            if isinstance(orders, list):
                for item in orders:
                    if isinstance(item, dict) and item.get("order_id"):
                        results.append(ml_import_order(str(item["order_id"]), source="API Mercado Livre / shipments"))
            all_ignored = bool(results) and all(bool(item.get("ignored")) for item in results if isinstance(item, dict))
            any_ready = any(bool(item.get("ready_for_conference")) for item in results if isinstance(item, dict))
            any_fiscal = any(bool(item.get("fiscal_ready")) for item in results if isinstance(item, dict))
            if all_ignored:
                event_result, prefix = "FULL IGNORADO", ""
            elif any_ready:
                event_result, prefix = "PRONTO PARA CONFERÊNCIA", "Etiqueta vinculada automaticamente · "
            elif any_fiscal:
                event_result, prefix = "NF LIBERADA / ETIQUETA AGUARDANDO", ""
            else:
                event_result, prefix = "NF AGUARDANDO", ""
            ml_log_event(topic, resource, user_id, app_id, event_result, prefix + json_dumps(results))
            return
        ml_log_event(topic, resource, user_id, app_id, "IGNORADO", "Tópico/recurso sem ação configurada")
    except Exception as exc:
        ml_log_event(topic, resource, user_id, app_id, "ERRO", str(exc))
        _ml_conta_atualizar("last_error=?,updated_at=?", (str(exc)[:2000], now_iso()))  # V18.94: conta da casa


def _ml_all_pending_label_candidates() -> list[tuple[str, str]]:
    """Retorna todos os pares únicos ainda aguardando etiqueta."""
    rows = _ml_fila_leitura()  # V20.04
    seen: set[tuple[str, str]] = set()
    candidates: list[tuple[str, str]] = []
    casa = ml_casa_atual()
    for row in rows:
        if not isinstance(row, dict):
            continue
        marketplace = normalize(row.get("Marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        if ml_casa_da_linha(row) != casa:  # V18.94: a etiqueta é buscada com a conta da casa do pedido
            continue
        if str(row.get("Etiqueta API Mercado Livre") or "").strip().upper() == "VINCULADA":
            continue
        if str(row.get("LogisticaMercadoLivre") or "").strip().lower() == "fulfillment":
            continue
        order_id = str(row.get("VendaMercadoLivre") or "").strip()
        shipment_id = str(row.get("ShipmentIdMercadoLivre") or "").strip()
        if not order_id or not shipment_id:
            continue
        key = (order_id, shipment_id)
        if key in seen:
            continue
        seen.add(key)
        candidates.append(key)
    return candidates


_ML_PENDING_WATCH_CURSOR_CASA: dict[str, int] = {}  # V18.94: posição do lote de cada casa (fora a principal)


def _ml_pending_label_candidates() -> list[tuple[str, str]]:
    """Retorna um lote circular; os primeiros 20 nunca bloqueiam os seguintes."""
    global ML_PENDING_WATCH_CURSOR
    all_candidates = _ml_all_pending_label_candidates()
    total = len(all_candidates)
    casa = ml_casa_atual()
    with ML_PENDING_WATCH_CURSOR_LOCK:
        cursor = ML_PENDING_WATCH_CURSOR if casa == CASA_PRINCIPAL else _ML_PENDING_WATCH_CURSOR_CASA.get(casa, 0)
        if total <= ML_PENDING_WATCH_BATCH:
            novo, batch = 0, all_candidates
        else:
            start = cursor % total
            count = min(ML_PENDING_WATCH_BATCH, total)
            batch = [all_candidates[(start + i) % total] for i in range(count)]
            novo = (start + count) % total
        if casa == CASA_PRINCIPAL:
            ML_PENDING_WATCH_CURSOR = novo
        else:
            _ML_PENDING_WATCH_CURSOR_CASA[casa] = novo
    return batch


ML_SUBSTATUS_JA_POSTADO = {"dropped_off", "picked_up", "in_hub"}  # V20.15


def ml_pending_label_watch_once() -> dict[str, int]:
    """Reconsulta somente shipments pendentes; importa o pedido só quando há chance de etiqueta."""
    checked = triggered = ready = errors = 0
    for order_id, shipment_id in _ml_pending_label_candidates():
        checked += 1
        try:
            shipment = ml_api_get(
                f"/shipments/{quote(shipment_id)}?views=destination",
                headers={"x-format-new": "true", "X-Api-Version": "2"},
            )
            if not isinstance(shipment, dict):
                continue
            status = str(shipment.get("status") or "").strip().lower()
            substatus = str(shipment.get("substatus") or "").strip().lower()

            # V16.36: se o shipment foi cancelado, reconsulta a order para retirar
            # imediatamente a venda da fila de pendentes.
            if status in {"cancelled", "canceled"}:
                triggered += 1
                result = ml_import_order(order_id, source="API Mercado Livre / watcher cancelamento")
                ml_log_event(
                    "shipment_watcher", f"/shipments/{shipment_id}",
                    "", ML_CLIENT_ID, "CANCELAMENTO PROCESSADO",
                    json_dumps({"order_id": order_id, "shipment_id": shipment_id,
                                "removed": result.get("removed_pending_rows", 0)})
                )
                continue

            # V18.97: esperava etiqueta mas o envio já saiu (despachado/entregue por fora):
            # reimporta, e a importação tira da fila a linha que a integração criou.
            if status in ML_ENVIO_JA_DESPACHADO:
                triggered += 1
                result = ml_import_order(order_id, source="API Mercado Livre / watcher envio já despachado")
                ml_log_event_se_mudou(
                    "shipment_watcher", f"/shipments/{shipment_id}",
                    "", ML_CLIENT_ID, "JÁ DESPACHADO / FORA DA FILA",
                    json_dumps({"order_id": order_id, "shipment_id": shipment_id, "status": status,
                                "removed": result.get("removed_existing_api_rows", 0)})
                )
                continue

            # V20.15: pacote já postado/coletado continua ready_to_ship, mas a etiqueta não
            # imprime mais (NOT_PRINTABLE_STATUS). Reimportar a cada ciclo só regravava a fila
            # (03/11: 2 pedidos de Bauru, 127x cada em 3 h). Fica na fila para o ADMIN decidir.
            if status == "ready_to_ship" and substatus in ML_SUBSTATUS_JA_POSTADO:
                ml_log_event_se_mudou(
                    "shipment_watcher", f"/shipments/{shipment_id}",
                    "", ML_CLIENT_ID, "JÁ POSTADO / ETIQUETA NÃO IMPRIME",
                    json_dumps({"order_id": order_id, "shipment_id": shipment_id, "substatus": substatus})
                )
                continue

            # V14.4: invoice_pending pode estar atrasado em relação à disponibilidade
            # real da etiqueta. Para não fazer uma reimportação pesada desnecessária,
            # quando esse substatus aparece fazemos primeiro uma sondagem direta do ZPL.
            # Se o endpoint já devolver a etiqueta, reimportamos e vinculamos o pedido.
            if status == "ready_to_ship" and substatus == "invoice_pending":
                try:
                    if not _ml_fetch_shipping_zpl(shipment_id):
                        continue
                except Exception:
                    continue

            # Em ready_to_ship, reimporta: a rotina tenta o ZPL e só libera a
            # conferência quando o vínculo da etiqueta for realmente gravado.
            if status == "ready_to_ship":
                triggered += 1
                result = ml_import_order(order_id, source="API Mercado Livre / watcher etiqueta")
                if result.get("ready_for_conference"):
                    ready += 1
                    ml_log_event(
                        "shipment_watcher", f"/shipments/{shipment_id}",
                        "", ML_CLIENT_ID, "PRONTO PARA CONFERÊNCIA",
                        json_dumps({"order_id": order_id, "shipment_id": shipment_id,
                                    "substatus": substatus, "fiscal_name": result.get("fiscal_name") or ""})
                    )
                elif result.get("fiscal_name_updated"):
                    ml_log_event(
                        "shipment_watcher", f"/orders/{order_id}",
                        "", ML_CLIENT_ID, "NOME FISCAL ATUALIZADO",
                        json_dumps({"order_id": order_id, "shipment_id": shipment_id,
                                    "nome": result.get("fiscal_name") or ""})
                    )
        except Exception as exc:
            errors += 1
            ml_log_event_se_mudou(
                "shipment_watcher", f"/shipments/{shipment_id}",
                "", ML_CLIENT_ID, "ERRO", str(exc)[:1200]
            )
    return {"checked": checked, "triggered": triggered, "ready": ready, "errors": errors}


def _ml_recover_one_identifier(identifier: str, *, source: str) -> dict[str, Any]:
    """Trata o número como order, pack e busca q; importa todas as orders relacionadas."""
    ident = re.sub(r"\D+", "", str(identifier or ""))
    out: dict[str, Any] = {"identifier": ident, "orders": [], "imported": 0, "ready": 0, "errors": []}
    if not ident:
        return out
    order_ids: list[str] = []
    try:
        order = ml_api_get(f"/orders/{quote(ident)}")
        if isinstance(order, dict):
            oid = str(order.get("id") or "").strip()
            if oid:
                order_ids.append(oid)
    except Exception as exc:
        out["errors"].append(f"order:{str(exc)[:220]}")
    if not order_ids:
        try:
            _, _, pack_orders = _ml_pack_shipment(ident)
            order_ids.extend(x for x in pack_orders if x not in order_ids)
        except Exception as exc:
            out["errors"].append(f"pack:{str(exc)[:220]}")
    if not order_ids:
        try:
            _, seller_id = ml_access_token()
            query = urlencode({"seller": seller_id, "q": ident, "limit": "50", "offset": "0"})
            found = ml_api_get(f"/orders/search?{query}")
            for item in (found.get("results") if isinstance(found, dict) else []) or []:
                if not isinstance(item, dict):
                    continue
                oid = str(item.get("id") or "").strip()
                pid = str(item.get("pack_id") or "").strip()
                if ident in {oid, pid} and oid and oid not in order_ids:
                    order_ids.append(oid)
        except Exception as exc:
            out["errors"].append(f"search:{str(exc)[:220]}")
    out["orders"] = order_ids
    for oid in order_ids:
        try:
            detail = ml_import_order(oid, source=source)
            out["imported"] += 1
            if detail.get("ready_for_conference"):
                out["ready"] += 1
        except Exception as exc:
            out["errors"].append(f"import {oid}:{str(exc)[:300]}")
    return out


def _ml_recover_local_pending_identifiers_once(*, max_identifiers: int = 80) -> dict[str, Any]:
    """Recupera pedidos locais presos por IDs salvos em campos errados ou migração de API."""
    linked = _ml_linked_order_ids()
    completed = _ml_completed_order_ids()
    identifiers: list[str] = []
    shipment_ids: list[str] = []
    casa = ml_casa_atual()
    for row in _ml_fila_leitura():  # V20.04
        if not isinstance(row, dict):
            continue
        marketplace = normalize(row.get("Marketplace"))
        if "MERCADO LIVRE" not in marketplace and "MERCADOLIVRE" not in marketplace:
            continue
        if ml_casa_da_linha(row) != casa:  # V18.94
            continue
        oid = str(row.get("VendaMercadoLivre") or "").strip()
        if oid and (oid in linked or oid in completed):
            continue
        sid = re.sub(r"\D+", "", str(row.get("ShipmentIdMercadoLivre") or ""))
        if sid and sid not in shipment_ids:
            shipment_ids.append(sid)
        for raw_id in (order_number(row), oid, row.get("PackIdMercadoLivre")):
            ident = re.sub(r"\D+", "", str(raw_id or ""))
            if ident and ident not in identifiers:
                identifiers.append(ident)

    imported = ready = errors = resolved_by_shipment = 0
    details: list[dict[str, Any]] = []
    for sid in shipment_ids[:max_identifiers]:
        order_ids = _ml_orders_for_shipment(sid)
        if order_ids:
            resolved_by_shipment += 1
        for oid in order_ids:
            try:
                detail = ml_import_order(oid, source="API Mercado Livre / recuperação por shipment")
                imported += 1
                if detail.get("ready_for_conference"):
                    ready += 1
            except Exception as exc:
                errors += 1
                details.append({"shipment_id": sid, "order_id": oid, "error": str(exc)[:300]})
    for ident in identifiers[:max_identifiers]:
        result = _ml_recover_one_identifier(ident, source="API Mercado Livre / recuperação identificador local")
        imported += int(result.get("imported") or 0)
        ready += int(result.get("ready") or 0)
        if result.get("errors") and not result.get("orders"):
            errors += 1
        if result.get("orders") or result.get("errors"):
            details.append(result)
    summary = {"local_identifiers": len(identifiers), "local_shipments": len(shipment_ids),
               "resolved_by_shipment": resolved_by_shipment, "imported": imported,
               "ready": ready, "errors": errors, "details": details[:20]}
    try:
        ml_log_event("stuck_order_recovery", "/local-pending", "", ML_CLIENT_ID,
                     "RECUPERAÇÃO CONCLUÍDA", json_dumps(summary))
    except Exception:
        pass
    return summary


def _ml_discover_untracked_ready_labels_once(*, days: int | None = None, max_pages: int | None = None) -> dict[str, int]:
    """V14.11: descobre na própria API pedidos com etiqueta que ainda não existem localmente.

    A V14.10 conseguia recuperar apenas pedidos já presentes em conf_pedidos ou
    reconciliáveis por número. Aqui percorremos /orders/search dentro da janela
    configurada e inspecionamos somente pedidos cujo order_id ainda não está na
    base local/concluída. Se o shipment estiver ready_to_ship e o ZPL existir,
    importamos o pedido diretamente.
    """
    _, seller_id = ml_access_token()
    scan_days = max(1, min(90, int(days or ML_MANUAL_RECONCILE_DAYS)))
    page_limit = max(1, min(ML_CATCHUP_MAX_PAGES, int(max_pages or ML_CATCHUP_MAX_PAGES)))
    cutoff = datetime.now(timezone.utc) - timedelta(days=scan_days)
    completed = _ml_completed_order_ids()
    linked_local = _ml_linked_order_ids()
    checked = discovered = available = linked = errors = 0
    stop_by_date = False

    for page in range(page_limit):
        query = urlencode({
            "seller": seller_id,
            "order.status": "paid",
            "sort": "date_desc",
            "limit": str(ML_CATCHUP_PAGE_SIZE),
            "offset": str(page * ML_CATCHUP_PAGE_SIZE),
        })
        result = ml_api_get(f"/orders/search?{query}")
        orders = result.get("results") if isinstance(result, dict) else []
        if not orders:
            break

        for order in orders:
            if not isinstance(order, dict):
                continue
            created = _ml_parse_datetime(order.get("date_created"))
            if created is not None and created < cutoff:
                stop_by_date = True
                break

            order_id = str(order.get("id") or "").strip()
            if not order_id or order_id in completed or order_id in linked_local:
                continue
            # Mesmo que o pedido já exista localmente, ele precisa ser reconsultado
            # quando ainda não possui etiqueta vinculada. Isso corrige linhas
            # incompletas que antes eram ignoradas para sempre.
            discovered += 1

            try:
                shipment_id, shipment = _ml_resolve_forward_shipment(order_id, order)

                checked += 1
                if not shipment_id or not isinstance(shipment, dict):
                    continue
                if str(shipment.get("status") or "").strip().lower() != "ready_to_ship":
                    continue

                try:
                    zpl = _ml_fetch_shipping_zpl(shipment_id)
                except Exception:
                    zpl = ""
                if not zpl:
                    continue
                available += 1

                detail = ml_import_order(order_id, source="API Mercado Livre / descoberta etiqueta não rastreada")
                if detail.get("ready_for_conference"):
                    linked_local.add(order_id)
                    linked += 1
                    ml_log_event(
                        "manual_label_discovery", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                        "PEDIDO DESCOBERTO / PRONTO PARA CONFERÊNCIA",
                        json_dumps({"order_id": order_id, "shipment_id": shipment_id})
                    )
            except Exception as exc:
                errors += 1
                ml_log_event(
                    "manual_label_discovery", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                    "ERRO", str(exc)[:1200]
                )

        if stop_by_date or len(orders) < ML_CATCHUP_PAGE_SIZE:
            break

    return {
        "api_discovered": discovered,
        "api_checked": checked,
        "api_available": available,
        "api_linked": linked,
        "api_errors": errors,
    }


def ml_check_all_available_labels_once() -> dict[str, int]:
    """Varredura manual completa usada pelo botão do Admin.

    V14.11: reconcilia os pedidos locais e também consulta /orders/search para
    encontrar pedidos pagos com etiqueta pronta que nunca chegaram à base local.
    """
    local_recovery: dict[str, Any] = {"imported": 0, "ready": 0, "errors": 0}
    try:
        local_recovery = _ml_recover_local_pending_identifiers_once()
    except Exception as exc:
        local_recovery = {"imported": 0, "ready": 0, "errors": 1, "details": [{"error": str(exc)[:400]}]}
        ml_log_event("manual_label_check", "/local-recovery", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])

    reconcile = {"manual": 0, "matched": 0, "ready": 0, "errors": 0}
    try:
        reconcile = ml_reconcile_manual_orders_once()
    except Exception as exc:
        reconcile = {"manual": 0, "matched": 0, "ready": 0, "errors": 1}
        ml_log_event("manual_label_check", "/reconcile", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])

    checked = triggered = ready = errors = 0
    for order_id, shipment_id in _ml_all_pending_label_candidates():
        checked += 1
        try:
            shipment = ml_api_get(
                f"/shipments/{quote(shipment_id)}?views=destination",
                headers={"x-format-new": "true", "X-Api-Version": "2"},
            )
            if not isinstance(shipment, dict):
                continue
            status = str(shipment.get("status") or "").strip().lower()
            if status != "ready_to_ship":
                continue
            try:
                zpl = _ml_fetch_shipping_zpl(shipment_id)
            except Exception:
                zpl = ""
            if not zpl:
                continue
            triggered += 1
            result = ml_import_order(order_id, source="API Mercado Livre / verificação manual etiquetas")
            if result.get("ready_for_conference"):
                ready += 1
        except Exception as exc:
            errors += 1
            ml_log_event("manual_label_check", f"/shipments/{shipment_id}", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])

    discovery = {"api_discovered": 0, "api_checked": 0, "api_available": 0, "api_linked": 0, "api_errors": 0}
    try:
        discovery = _ml_discover_untracked_ready_labels_once()
    except Exception as exc:
        discovery["api_errors"] = 1
        ml_log_event("manual_label_discovery", "/orders/search", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])

    total_errors = errors + int(reconcile.get("errors") or 0) + int(discovery.get("api_errors") or 0) + int(local_recovery.get("errors") or 0)
    summary = {
        "reconciled_pending": int(reconcile.get("manual") or 0),
        "reconciled_matched": int(reconcile.get("matched") or 0),
        "reconciled_ready": int(reconcile.get("ready") or 0),
        "checked": checked + int(discovery.get("api_checked") or 0),
        "available": triggered + int(discovery.get("api_available") or 0),
        "linked": ready + int(discovery.get("api_linked") or 0),
        "api_discovered": int(discovery.get("api_discovered") or 0),
        "local_recovery_imported": int(local_recovery.get("imported") or 0),
        "local_recovery_ready": int(local_recovery.get("ready") or 0),
        "errors": total_errors,
    }
    ml_log_event("manual_label_check", "/pending", "", ML_CLIENT_ID, "CONCLUÍDO", json_dumps(summary))
    return {"ok": total_errors == 0, **summary}


def ml_pending_label_watch_loop(stop_event: threading.Event) -> None:
    """Watcher de etiquetas locais + descoberta periódica direta na API.

    Além de revisar shipments já conhecidos, a cada ~60 s varre pedidos pagos
    recentes no Mercado Livre. Assim um pedido que entrou localmente incompleto
    (ou que perdeu webhook) volta a ser sincronizado quando a etiqueta surgir.
    """
    cycles = 0
    discovery_every = max(1, int(round(120 / max(1, ML_PENDING_WATCH_INTERVAL))))
    while not stop_event.wait(ML_PENDING_WATCH_INTERVAL):
        casas = ml_casas_conectadas()
        if not casas:
            continue
        cycles += 1
        # V18.94: cada casa revê as etiquetas dos pedidos DELA, com a conta dela.
        for casa in casas:
            with ml_na_casa(casa):
                _ml_pending_label_watch_ciclo(cycles % discovery_every == 0)


def _ml_pending_label_watch_ciclo(descobrir: bool) -> None:
    """Um ciclo do vigia de etiquetas na casa atual (V18.94: era o corpo do laço)."""
    try:
        ml_pending_label_watch_once()
        if descobrir:
            try:
                # Varredura automática curta: até 3 dias / 4 páginas (200 pedidos).
                # A verificação manual continua usando a janela completa configurada.
                recovery = _ml_recover_local_pending_identifiers_once(max_identifiers=30)
                if recovery.get("ready"):
                    ml_log_event("shipment_watcher", "/local-recovery", "", ML_CLIENT_ID,
                                 "PEDIDOS PRESOS RECUPERADOS", json_dumps(recovery))
                result = _ml_discover_untracked_ready_labels_once(days=3, max_pages=4)
                if result.get("api_linked"):
                    ml_log_event("shipment_watcher", "/orders/search", "", ML_CLIENT_ID,
                                 "ETIQUETAS RECUPERADAS", json_dumps(result))
            except Exception as discovery_exc:
                ml_log_event("shipment_watcher", "/orders/search", "", ML_CLIENT_ID,
                             "ERRO DESCOBERTA", str(discovery_exc)[:1200])
    except Exception as exc:
        try:
            ml_log_event_se_mudou("shipment_watcher", "/pending", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])
        except Exception:
            pass


ML_FULL_IGNORADO_DIAS = 45  # V18.78: cobre a janela que o vigia e o catch-up consultam
# V18.78: cópia em memória da tabela, para o vigia de 20 s não tomar o DB_LOCK só
# para isso. Alimentada por registrar/esquecer; relida do banco a cada hora (expiração).
_ML_FULL_IGNORADOS_CACHE: set[str] | None = None
_ML_FULL_IGNORADOS_CARREGADO_EM = 0.0
_ML_FULL_IGNORADOS_TTL = 3600.0
_ML_FULL_IGNORADOS_LOCK = threading.Lock()


def _ml_full_ignorados_cache_limpar() -> None:
    global _ML_FULL_IGNORADOS_CACHE
    with _ML_FULL_IGNORADOS_LOCK:
        _ML_FULL_IGNORADOS_CACHE = None


def _ml_full_ignorado_registrar(order_id: str, origem: str = "") -> None:
    """V18.78: lembra que este pedido é Mercado Envios Full (não passa pela expedição)."""
    oid = str(order_id or "").strip()
    if not oid:
        return
    with DB_LOCK:
        DB.execute(
            "INSERT OR REPLACE INTO ml_full_ignorado_v1878(order_id,visto_em,origem) VALUES(?,?,?)",
            (oid, now_iso(), str(origem or "")[:200]),
        )
        DB.commit()
    with _ML_FULL_IGNORADOS_LOCK:
        if _ML_FULL_IGNORADOS_CACHE is not None:
            _ML_FULL_IGNORADOS_CACHE.add(oid)


def _ml_full_ignorado_esquecer(order_id: str) -> bool:
    """V18.78: o pedido foi importado como NÃO-Full — sai da memória na hora."""
    oid = str(order_id or "").strip()
    if not oid:
        return False
    with DB_LOCK:
        try:
            cur = DB.execute("DELETE FROM ml_full_ignorado_v1878 WHERE order_id=?", (oid,))
            DB.commit()
            removido = int(cur.rowcount or 0) > 0
        except Exception:
            removido = False
    with _ML_FULL_IGNORADOS_LOCK:
        if _ML_FULL_IGNORADOS_CACHE is not None:
            _ML_FULL_IGNORADOS_CACHE.discard(oid)
    return removido


def _ml_full_ignorados_do_banco(dias: int) -> set[str]:
    corte = (datetime.now(timezone.utc).astimezone() - timedelta(days=dias)).isoformat(timespec="milliseconds")
    with DB_LOCK:
        try:
            rows = DB.execute("SELECT order_id FROM ml_full_ignorado_v1878 WHERE visto_em >= ?", (corte,)).fetchall()
        except Exception:
            rows = []
    return {str(r[0]) for r in rows}


def _ml_full_ignorados(dias: int = ML_FULL_IGNORADO_DIAS) -> set[str]:
    """V18.78: pedidos Full já classificados nos últimos `dias`. O vigia de 20 s e o
    catch-up pulam estes — antes reimportavam cada um a cada ciclo. O webhook e o
    botão Atualizar do Admin chamam ml_import_order direto e NÃO passam por aqui."""
    global _ML_FULL_IGNORADOS_CACHE, _ML_FULL_IGNORADOS_CARREGADO_EM
    if dias != ML_FULL_IGNORADO_DIAS:
        return _ml_full_ignorados_do_banco(dias)
    agora = time.time()
    with _ML_FULL_IGNORADOS_LOCK:
        atual = _ML_FULL_IGNORADOS_CACHE
        vencido = atual is None or (agora - _ML_FULL_IGNORADOS_CARREGADO_EM) > _ML_FULL_IGNORADOS_TTL
    if vencido:
        # Lê o banco FORA da trava do cache (ordem fixa: nunca DB_LOCK dentro dela).
        ids = _ml_full_ignorados_do_banco(dias)
        with _ML_FULL_IGNORADOS_LOCK:
            _ML_FULL_IGNORADOS_CACHE = ids
            _ML_FULL_IGNORADOS_CARREGADO_EM = agora
            atual = ids
    with _ML_FULL_IGNORADOS_LOCK:
        return set(atual or ())


# V20.04: os vigias do ML (15–20 s, por conta) remontavam a fila, decodificavam 1,4 MB de
# etiquetas e abriam o JSON de todos os concluídos a cada ciclo: ~40% de CPU 24 h e banco
# ocupado 39,7% do tempo (produção, 30/10). A cópia abaixo é só para DECIDIR o que olhar;
# vale enquanto a versão não muda e nunca mais que ML_CACHE_LEITURA_S. Quem grava continua
# passando pelo get_storage/save_storage, com todas as barreiras do ADMIN.
ML_CACHE_LEITURA_S = 60.0
_ML_FILA_CACHE: dict[str, Any] = {}
_ML_ETIQUETAS_CACHE: dict[str, Any] = {}
_ML_CONCLUIDOS_CACHE: dict[str, tuple[str, frozenset[str]]] = {}


def _ml_cache_leitura_limpar() -> None:
    global _ML_CONCLUIDOS_CACHE
    _ML_FILA_CACHE.clear()
    _ANUNCIO_PEND_CACHE.clear()  # V20.26 (revisao): o pendente dos anuncios vem desta mesma leitura
    _ML_ETIQUETAS_CACHE.clear()
    _ML_CONCLUIDOS_CACHE = {}


def _ml_versoes_storage(*chaves: str) -> list[tuple[str, int]]:
    marcas = ",".join("?" for _ in chaves)
    return [(str(r[0]), int(r[1])) for r in DB.execute(
        f"SELECT key,version FROM storage WHERE key IN ({marcas}) ORDER BY key", chaves
    ).fetchall()]


def _ml_fila_leitura() -> list[dict[str, Any]]:
    """Fila já com as regras do ADMIN, SÓ para leitura: não alterar as linhas devolvidas."""
    # Tombstone do pedido fica em outra chave. Conclusão sobe a versão de conf_pedidos.
    with DB_LOCK:
        versoes = _ml_versoes_storage("conf_pedidos", PENDING_ORDER_DELETE_KEY_V1766)
        agora = time.monotonic()
        if (_ML_FILA_CACHE.get("versoes") == versoes
                and agora - float(_ML_FILA_CACHE.get("em") or 0) < ML_CACHE_LEITURA_S):
            return _ML_FILA_CACHE["linhas"]
        raw, _, _ = get_storage("conf_pedidos")
        linhas = _rows_from_storage_value(raw)
        _ML_FILA_CACHE.update(versoes=versoes, em=agora, linhas=linhas)
        return linhas


def _ml_etiquetas_validas() -> tuple[set[str], set[str]]:
    """(vendas, envios) com etiqueta ML de verdade no banco. Não alterar os conjuntos."""
    with DB_LOCK:
        versoes = _ml_versoes_storage("conf_etiquetas")
        agora = time.monotonic()
        if (_ML_ETIQUETAS_CACHE.get("versoes") == versoes
                and agora - float(_ML_ETIQUETAS_CACHE.get("em") or 0) < ML_CACHE_LEITURA_S):
            return _ML_ETIQUETAS_CACHE["vendas"], _ML_ETIQUETAS_CACHE["envios"]
        label_raw, _, _ = get_storage("conf_etiquetas")
    try:
        label_bank = json.loads(label_raw) if isinstance(label_raw, str) and label_raw.strip() else {}
    except Exception:
        label_bank = {}
    registros = label_bank.get("registros") if isinstance(label_bank, dict) and isinstance(label_bank.get("registros"), dict) else {}
    valid_orders: set[str] = set()
    valid_shipments: set[str] = set()
    for rec in registros.values():
        if not isinstance(rec, dict):
            continue
        if str(rec.get("origem") or "").strip().lower() != "api_mercadolivre":
            continue
        envio = rec.get("envio")
        if not isinstance(envio, str) or not envio.strip():
            continue
        meta = rec.get("metadados") if isinstance(rec.get("metadados"), dict) else {}
        oid = str(meta.get("venda") or "").strip()
        sid = str(meta.get("shipment_id") or "").strip()
        if oid: valid_orders.add(oid)
        if sid: valid_shipments.add(sid)
    _ML_ETIQUETAS_CACHE.update(versoes=versoes, em=agora, vendas=valid_orders, envios=valid_shipments)
    return valid_orders, valid_shipments


def _ml_linked_order_ids() -> set[str]:
    """Pedidos cuja etiqueta ML realmente existe no banco de etiquetas.

    Não confia apenas no texto VINCULADA da linha: versões antigas podiam deixar
    esse marcador sem um registro ZPL correspondente, fazendo o watcher ignorar
    o pedido indefinidamente.
    """
    valid_orders, valid_shipments = _ml_etiquetas_validas()
    ids: set[str] = set()
    for row in _ml_fila_leitura():
        if not isinstance(row, dict):
            continue
        if str(row.get("Etiqueta API Mercado Livre") or "").strip().upper() != "VINCULADA":
            continue
        oid = str(row.get("VendaMercadoLivre") or "").strip()
        sid = str(row.get("ShipmentIdMercadoLivre") or "").strip()
        if oid and (oid in valid_orders or (sid and sid in valid_shipments)):
            ids.add(oid)
    return ids


def _ml_completed_order_ids() -> set[str]:
    """Pedidos já concluídos, que não devem voltar para pendentes."""
    # V20.04: a lista (chave + data) é lida sempre, do banco; o JSON só de quem é novo ou
    # foi concluído de novo. Sem trava própria: duas threads no máximo refazem o trabalho.
    global _ML_CONCLUIDOS_CACHE
    with DB_LOCK:
        try:
            marcas = DB.execute("SELECT order_key,completed_at FROM completed_orders").fetchall()
        except Exception:
            marcas = []
    anterior = _ML_CONCLUIDOS_CACHE
    novo: dict[str, tuple[str, frozenset[str]]] = {}
    faltam: list[str] = []
    for marca in marcas:
        chave, em = str(marca[0]), str(marca[1] or "")
        guardado = anterior.get(chave)
        if guardado and guardado[0] == em:
            novo[chave] = guardado
        else:
            faltam.append(chave)
    for inicio in range(0, len(faltam), 400):
        lote = faltam[inicio:inicio + 400]
        with DB_LOCK:
            try:
                rows = DB.execute(
                    f"SELECT order_key,completed_at,payload FROM completed_orders "
                    f"WHERE order_key IN ({','.join('?' for _ in lote)})", lote
                ).fetchall()
            except Exception:
                rows = []
        for dbrow in rows:
            try:
                payload = json.loads(dbrow[2])
            except Exception:
                payload = []
            candidates = payload if isinstance(payload, list) else [payload]
            vendas = {str(row.get("VendaMercadoLivre") or "").strip() for row in candidates if isinstance(row, dict)}
            novo[str(dbrow[0])] = (str(dbrow[1] or ""), frozenset(v for v in vendas if v))
    _ML_CONCLUIDOS_CACHE = novo
    ids: set[str] = set()
    for _, vendas in novo.values():
        ids.update(vendas)
    return ids


def _ml_existing_order_ids() -> set[str]:
    ids: set[str] = set()
    for row in _ml_fila_leitura():
        if isinstance(row, dict):
            oid = str(row.get("VendaMercadoLivre") or "").strip()
            if oid:
                ids.add(oid)
    # Pedidos já concluídos também não devem voltar para pendentes.
    ids.update(_ml_completed_order_ids())
    return ids


def _ml_parse_datetime(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        # Mercado Livre e o próprio banco podem usar Z ou offset ISO.
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    except Exception:
        return None


def _ml_update_last_sync(marker: str, *, error: str = "") -> None:
    # V18.94: grava na conta da casa atual.
    _ml_conta_atualizar("last_sync_at=?,updated_at=?,last_error=?", (str(marker or now_iso()), now_iso(), str(error or "")[:3000]))


def ml_catchup_orders(recovery_since: str = "", *, source: str = "reconexão") -> dict[str, Any]:
    """Recupera pedidos pagos perdidos desde o último ponto confiável.

    Pagina /orders/search até alcançar recovery_since. O mesmo lock do watcher
    impede que o poller de 20 s importe em paralelo durante a recuperação.
    """
    if not ML_CATCHUP_LOCK.acquire(blocking=False):
        return {"ok": True, "running": True, "imported": 0, "ignored_full": 0, "errors": []}

    watcher_locked = False
    scan_started_at = now_iso()
    try:
        ML_NEW_ORDER_WATCH_LOCK.acquire()
        watcher_locked = True

        _, seller_id = ml_access_token()
        since_dt = _ml_parse_datetime(recovery_since)
        if since_dt is None:
            row = ml_integration_row()
            since_dt = _ml_parse_datetime(row["last_sync_at"] if row else "")
        if since_dt is None:
            since_dt = datetime.now(timezone.utc) - timedelta(days=ML_CATCHUP_FALLBACK_DAYS)

        # Pequena sobreposição evita perder pedidos exatamente na borda do marcador.
        since_dt = since_dt - timedelta(minutes=5)
        existing = _ml_existing_order_ids()
        existing |= _ml_full_ignorados()  # V18.78: Full já classificado não é reimportado

        imported = 0
        ignored_full = 0
        checked = 0
        errors: list[dict[str, str]] = []
        reached_marker = False
        exhausted = False

        for page in range(ML_CATCHUP_MAX_PAGES):
            offset = page * ML_CATCHUP_PAGE_SIZE
            query = urlencode({
                "seller": seller_id,
                "order.status": "paid",
                "sort": "date_desc",
                "limit": str(ML_CATCHUP_PAGE_SIZE),
                "offset": str(offset),
            })
            result = ml_api_get(f"/orders/search?{query}")
            orders = result.get("results") if isinstance(result, dict) else []
            if not orders:
                exhausted = True
                break

            for order in orders:
                if not isinstance(order, dict):
                    continue
                created_dt = _ml_parse_datetime(order.get("date_created"))
                if created_dt is not None and created_dt < since_dt:
                    reached_marker = True
                    break

                order_id = str(order.get("id") or "").strip()
                if not order_id:
                    continue
                checked += 1
                if order_id in existing:
                    continue
                try:
                    detail = ml_import_order(order_id, source=f"API Mercado Livre / catch-up {source}")
                    if detail.get("ignored") and detail.get("reason") == "FULL":
                        ignored_full += 1
                        existing.add(order_id)
                        ml_log_event_se_mudou(
                            "catchup", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                            "FULL IGNORADO", json_dumps({"order_id": order_id, "source": source})
                        )
                    else:
                        imported += 1
                        existing.add(order_id)
                        ml_log_event(
                            "catchup", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                            "PEDIDO RECUPERADO",
                            json_dumps({
                                "order_id": order_id,
                                "source": source,
                                "ready_for_conference": bool(detail.get("ready_for_conference")),
                                "fiscal_name": detail.get("fiscal_name") or "",
                            })
                        )
                except Exception as exc:
                    errors.append({"order_id": order_id, "error": str(exc)[:700]})

            if reached_marker:
                break
            if len(orders) < ML_CATCHUP_PAGE_SIZE:
                exhausted = True
                break

        completed_scan = reached_marker or exhausted
        if completed_scan and not errors:
            _ml_update_last_sync(scan_started_at)
        else:
            # Mantém o marcador antigo para uma futura tentativa não saltar pedidos.
            _ml_conta_atualizar("updated_at=?,last_error=?", (now_iso(), "" if not errors else json_dumps(errors[:5])))

        result_payload = {
            "ok": completed_scan and not errors,
            "checked": checked,
            "imported": imported,
            "ignored_full": ignored_full,
            "errors": errors,
            "reached_marker": reached_marker,
            "exhausted": exhausted,
            "since": since_dt.isoformat(),
            "scan_started_at": scan_started_at,
        }
        ml_log_event(
            "catchup", "/orders/search", seller_id, ML_CLIENT_ID,
            "CATCH-UP CONCLUÍDO" if result_payload["ok"] else "CATCH-UP PARCIAL",
            json_dumps(result_payload),
        )
        return result_payload
    except Exception as exc:
        try:
            ml_log_event_se_mudou("catchup", "/orders/search", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])
        except Exception:
            pass
        return {"ok": False, "checked": 0, "imported": 0, "ignored_full": 0, "errors": [{"error": str(exc)}]}
    finally:
        if watcher_locked:
            ML_NEW_ORDER_WATCH_LOCK.release()
        ML_CATCHUP_LOCK.release()


def ml_catchup_after_reconnect(recovery_since: str = "") -> None:
    # Executa fora do callback HTTP para devolver o navegador imediatamente.
    time.sleep(0.5)
    ml_catchup_orders(recovery_since, source="reconexão OAuth")



def ml_safety_catchup_once() -> dict[str, Any]:
    """Varredura de segurança independente do last_sync.

    Reconsulta uma janela fixa recente para recuperar pedidos que o webhook/poller
    não tenha importado. Como pedidos já existentes são ignorados, a rotina é
    idempotente e pode rodar 24/7 no servidor.
    """
    since = (datetime.now(timezone.utc) - timedelta(hours=ML_SAFETY_CATCHUP_HOURS)).isoformat()
    result = ml_catchup_orders(since, source=f"segurança {ML_SAFETY_CATCHUP_HOURS}h")
    _ml_worker_state_update(
        last_catchup_at=now_iso(),
        last_catchup_result=result,
        last_error="" if result.get("ok") else str((result.get("errors") or [{}])[0].get("error") or "catch-up parcial")[:1200],
    )
    return result


def ml_safety_catchup_loop(stop_event: threading.Event) -> None:
    # Após o boot, deixa o poller curto rodar primeiro e então recupera a janela maior.
    if stop_event.wait(20):
        return
    while not stop_event.is_set():
        try:
            # V18.94: varredura de segurança de cada casa conectada.
            for casa in ml_casas_conectadas():
                with ml_na_casa(casa):
                    ml_safety_catchup_once()
        except Exception as exc:
            _ml_worker_state_update(last_catchup_at=now_iso(), last_error=str(exc)[:1200])
            try:
                ml_log_event_se_mudou("safety_catchup", "/orders/search", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])
            except Exception:
                pass
        if stop_event.wait(ML_SAFETY_CATCHUP_INTERVAL):
            break


def ml_new_order_watch_once() -> dict[str, int]:
    """Contingência do webhook: busca somente os pedidos pagos mais recentes."""
    poll_started_at = now_iso()
    if not ML_NEW_ORDER_WATCH_LOCK.acquire(blocking=False):
        return {"checked": 0, "imported": 0, "ignored_full": 0, "errors": 0}
    try:
        _, seller_id = ml_access_token()
        query = urlencode({
            "seller": seller_id,
            "order.status": "paid",
            "sort": "date_desc",
            "limit": str(ML_NEW_ORDER_WATCH_LIMIT),
            "offset": "0",
        })
        result = ml_api_get(f"/orders/search?{query}")
        orders = result.get("results") if isinstance(result, dict) else []
        # V18.93: aviso de venda com o mesmo resultado (sem chamada a mais). Nunca
        # atrapalha a entrada de pedidos.
        try:
            avisos_venda_registrar("ml", avisos_vendas_do_ml(orders))
        except Exception as exc:
            print(f"[avisos-venda] ml: {exc}", file=sys.stderr, flush=True)
        completed = _ml_completed_order_ids()
        linked_local = _ml_linked_order_ids()
        local_or_completed = _ml_existing_order_ids()
        # V18.78: pedido Full nunca entrava em `completed` nem em `linked_local`, então
        # cada Full da primeira página era reimportado a cada 20 s, o dia inteiro.
        full_ignorados = _ml_full_ignorados()
        # V20.15: pedido da fila com venda + envio já é acompanhado pelo vigia de etiquetas
        # (15 s, em rodízio). Aqui ele relia o envio e baixava a etiqueta a cada 20 s de cada
        # pedido esperando NF-e (~70 em 03/11). Fica só o que entrou sem envio (extensão/manual).
        acompanhados = {oid for oid, _ in _ml_all_pending_label_candidates()}
        checked = imported = refreshed_pending = ignored_full = errors = 0
        for order in orders or []:
            if not isinstance(order, dict):
                continue
            order_id = str(order.get("id") or "").strip()
            if not order_id:
                continue
            checked += 1
            if order_id in completed or order_id in linked_local or order_id in full_ignorados:
                continue
            if order_id in acompanhados:
                continue
            try:
                # Pedido já existe localmente, mas ainda sem etiqueta: não fazemos
                # uma reimportação pesada a cada 20 s. Só reimportamos quando o
                # shipment estiver ready_to_ship e o ZPL estiver realmente liberado.
                if order_id in local_or_completed:
                    shipment_id, shipment = _ml_resolve_forward_shipment(order_id, order)
                    if not shipment_id or not isinstance(shipment, dict):
                        continue
                    if str(shipment.get("status") or "").strip().lower() != "ready_to_ship":
                        continue
                    try:
                        if not _ml_fetch_shipping_zpl(shipment_id):
                            continue
                    except Exception:
                        continue
                detail = ml_import_order(order_id, source="API Mercado Livre / entrada automática")
                if detail.get("ignored") and detail.get("reason") == "DESPACHADO":
                    ignored_full += 1  # V18.97: venda já despachada/entregue, fora da fila
                elif detail.get("ignored") and detail.get("reason") == "FULL":
                    ignored_full += 1
                    ml_log_event_se_mudou("new_order_watcher", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                                          "FULL IGNORADO", json_dumps({"order_id": order_id}))
                else:
                    imported += 1
                    if detail.get("ready_for_conference"):
                        linked_local.add(order_id)
                    else:
                        refreshed_pending += 1
                    ml_log_event_se_mudou("new_order_watcher", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                                 "PEDIDO IMPORTADO/ATUALIZADO",
                                 json_dumps({"order_id": order_id,
                                             "ready_for_conference": bool(detail.get("ready_for_conference")),
                                             "fiscal_name": detail.get("fiscal_name") or "",
                                             "kit_components_applied": detail.get("kit_components_applied") or 0}))
            except Exception as exc:
                errors += 1
                ml_log_event_se_mudou("new_order_watcher", f"/orders/{order_id}", seller_id, ML_CLIENT_ID,
                                      "ERRO", str(exc)[:1200])
        if errors == 0:
            _ml_update_last_sync(poll_started_at)
        return {"checked": checked, "imported": imported, "refreshed_pending": refreshed_pending, "ignored_full": ignored_full, "errors": errors}
    finally:
        ML_NEW_ORDER_WATCH_LOCK.release()


def _ml_new_order_espera(erros_seguidos: int) -> int:
    """V20.16: o recuo por erro era limitado a 120 s — com o intervalo de 300 s, erro faria rodar mais."""
    return min(max(120, ML_NEW_ORDER_WATCH_INTERVAL), ML_NEW_ORDER_WATCH_INTERVAL * (2 ** erros_seguidos))


def ml_new_order_watch_loop(stop_event: threading.Event) -> None:
    """Busca pedidos novos periodicamente quando webhook orders_v2 atrasar/falhar."""
    consecutive_errors = 0
    # Faz uma primeira busca logo após o servidor subir.
    while not stop_event.is_set():
        try:
            # V18.94: uma busca por casa conectada; o estado da tela mostra a principal.
            casas = ml_casas_conectadas()
            if CASA_PRINCIPAL in casas:
                result = ml_new_order_watch_once()
                _ml_worker_state_update(
                    last_order_poll_at=now_iso(),
                    last_order_poll_result=result,
                    last_error="" if not result.get("errors") else f"poller: {result.get('errors')} erro(s)",
                )
                consecutive_errors = 0 if not result.get("errors") else min(consecutive_errors + 1, 4)
            else:
                consecutive_errors = 0
            for casa in casas:
                if casa == CASA_PRINCIPAL:
                    continue
                try:
                    with ml_na_casa(casa):
                        ml_new_order_watch_once()
                except Exception as exc_casa:
                    ml_log_event_se_mudou("new_order_watcher", "/orders/search", casa, ML_CLIENT_ID, "ERRO", str(exc_casa)[:1200])
        except Exception as exc:
            consecutive_errors = min(consecutive_errors + 1, 4)
            _ml_worker_state_update(last_order_poll_at=now_iso(), last_error=str(exc)[:1200])
            try:
                ml_log_event_se_mudou("new_order_watcher", "/orders/search", "", ML_CLIENT_ID, "ERRO", str(exc)[:1200])
            except Exception:
                pass
        wait_seconds = _ml_new_order_espera(consecutive_errors)
        if stop_event.wait(wait_seconds):
            break


def ml_manual_sync() -> dict[str, Any]:
    _, seller_id = ml_access_token()
    query = urlencode(
        {
            "seller": seller_id,
            "order.status": "paid",
            "sort": "date_desc",
            "limit": str(ML_MANUAL_SYNC_LIMIT),
            "offset": "0",
        }
    )
    result = ml_api_get(f"/orders/search?{query}")
    orders = result.get("results") if isinstance(result, dict) else []
    imported = []
    ignored_full = []
    errors = []
    for order in orders or []:
        order_id = str(order.get("id") or "") if isinstance(order, dict) else ""
        if not order_id:
            continue
        try:
            detail = ml_import_order(order_id, source="API Mercado Livre / sincronização manual")
            if detail.get("ignored") and detail.get("reason") == "FULL":
                ignored_full.append(detail)
            else:
                imported.append(detail)
        except Exception as exc:
            errors.append({"order_id": order_id, "error": str(exc)})
    _ml_conta_atualizar("last_sync_at=?,updated_at=?,last_error=?", (now_iso(), now_iso(), (json_dumps(errors[:5]) if errors else "")))
    ml_log_event(
        "manual_sync", "/orders/search", seller_id, ML_CLIENT_ID,
        "OK" if not errors else "PARCIAL",
        json_dumps({
            "imported": len(imported),
            "ignored_full": len(ignored_full),
            "ready_for_conference": sum(1 for item in imported if item.get("ready_for_conference")),
            "label_waiting": sum(1 for item in imported if item.get("fiscal_status") == "PROCESSANDO" and not item.get("ready_for_conference")),
            "nf_waiting": sum(1 for item in imported if item.get("fiscal_status") == "AGUARDANDO"),
            "errors": errors[:10],
        })
    )
    return {
        "ok": not errors,
        "imported": len(imported),
        "ignored_full": len(ignored_full),
        "processed": len(imported) + len(ignored_full),
        "ready_for_conference": sum(1 for item in imported if item.get("ready_for_conference")),
        "label_waiting": sum(1 for item in imported if item.get("fiscal_status") == "PROCESSANDO" and not item.get("ready_for_conference")),
        "nf_waiting": sum(1 for item in imported if item.get("fiscal_status") == "AGUARDANDO"),
        "errors": errors,
        "details": imported,
        "ignored_details": ignored_full,
    }



# ---------------------------------------------------------------------------
# V17.83 — Vendas do período: o que entrou dos marketplaces, item a item.
#
# Serve à Central de Pedidos do Dia. A agregação é feita no SERVIDOR porque ela
# precisa enxergar duas fontes ao mesmo tempo — a fila atual (conf_pedidos) e o
# que já foi concluído (completed_orders.payload) — e porque o cruzamento futuro
# com o custo do Apollo só pode acontecer aqui: a CHAVE_CRM nunca vai ao
# navegador. Somente leitura: nenhuma rota daqui grava.
# ---------------------------------------------------------------------------

# V17.84 — documento fiscal do comprador, para localizar o cliente no Linx DMS.
# Cada marketplace guarda o dado com um nome próprio; quem consome não precisa saber.
DOCUMENTO_CAMPOS_CPF = ("CPFMercadoLivre", "CPFShopee", "CPF", "Cpf", "cpf")
DOCUMENTO_CAMPOS_CNPJ = ("CNPJMercadoLivre", "CNPJShopee", "CNPJ", "Cnpj", "cnpj")


def documento_do_pedido(row: dict[str, Any]) -> dict[str, str]:
    """Devolve {"tipo": "CPF"|"CNPJ"|"", "numero": "<só dígitos>"}.

    O Linx DMS localiza o cliente por documento (ProcurarCliente/CnpjCpf), então
    esta é a chave que liga um pedido de marketplace ao cadastro do ERP.
    """
    if not isinstance(row, dict):
        return {"tipo": "", "numero": ""}
    for campos, tipo in ((DOCUMENTO_CAMPOS_CNPJ, "CNPJ"), (DOCUMENTO_CAMPOS_CPF, "CPF")):
        for campo in campos:
            numero = re.sub(r"\D", "", str(row.get(campo) or ""))
            if numero:
                # O comprimento manda: campo trocado é erro comum de integração.
                if len(numero) == 14:
                    return {"tipo": "CNPJ", "numero": numero}
                if len(numero) == 11:
                    return {"tipo": "CPF", "numero": numero}
                return {"tipo": tipo, "numero": numero}
    return {"tipo": "", "numero": ""}


# V17.84 — nome fiscal: o que está em "Dados para a NF-e" do marketplace.
# É o nome que DEVE ir para o cadastro do Linx DMS. Nunca o apelido da conta,
# nunca o destinatário da entrega — eles divergem com frequência, e o cadastro
# do ERP precisa bater com a nota.
NOME_FISCAL_CAMPOS = ("NomeFiscalMercadoLivre", "NomeFiscalShopee", "NomeFiscal")


def nome_fiscal_do_pedido(row: dict[str, Any]) -> str:
    """Nome de Dados para NF-e. Vazio quando o marketplace ainda não devolveu.

    Devolve vazio de propósito em vez de cair para `Cliente`: `Cliente` pode
    conter o nome do comprador da conta, e gravar isso no ERP produziria uma
    nota no nome errado. Quem chama decide o que fazer com o vazio.
    """
    if not isinstance(row, dict):
        return ""
    # V17.88: pedidos Shopee importados antes da correção têm o nome de
    # usuário gravado em NomeFiscalShopee. Usuário nunca é nome fiscal.
    usuarios = {normalize(row.get(c)) for c in ("UsuarioShopee", "UsuarioMercadoLivre") if str(row.get(c) or "").strip()}
    for campo in NOME_FISCAL_CAMPOS:
        nome = str(row.get(campo) or "").strip()
        if nome and normalize(nome) in usuarios:
            continue
        # normalize() também remove os espaços, então o marcador da Shopee
        # precisa passar pela mesma função dos dois lados da comparação.
        if nome and normalize(nome) != normalize("NOME NÃO DISPONÍVEL"):
            return nome
    return ""


# V17.85 — botão "Cliente" da Central de Pedidos do Dia.
# O servidor NÃO fala com o Linx DMS (a VPS não enxerga a rede do escritório).
# Ele só entrega CPF/CNPJ e nome de "Dados para a NF-e" do pedido; quem grava
# no Linx é a extensão "Noromak - Cadastro de Cliente no Linx", no Chrome de
# quem clicou. Somente leitura: nada aqui grava no banco.
CLIENTE_FISCAL_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
CLIENTE_FISCAL_CACHE_SEGUNDOS = 600
CLIENTE_FISCAL_CACHE_MAX = 5000


def _linhas_do_pedido(pedido: str) -> list[dict[str, Any]]:
    """Linhas do pedido na fila atual; se já foi concluído, as do snapshot."""
    alvo = normalize(pedido)
    if not alvo:
        return []
    pendentes, _, _ = get_storage("conf_pedidos")
    linhas = [
        row for row in _rows_from_storage_value(pendentes)
        if isinstance(row, dict) and normalize(order_number(row)) == alvo
    ]
    if linhas:
        return linhas
    for db_row in DB.execute("SELECT order_key,payload FROM completed_orders").fetchall():
        if normalize(db_row["order_key"]) != alvo:
            continue
        try:
            payload = json.loads(str(db_row["payload"] or "[]"))
        except Exception:
            continue
        return [r for r in (payload if isinstance(payload, list) else [payload]) if isinstance(r, dict)]
    return []


def _ml_billing_do_pedido(order_id: str) -> dict[str, Any]:
    """Relê Dados para NF-e direto da API do ML. Mesmo caminho do import
    (ml_import_order), inclusive o contrato v2 quando o padrão vem sem billing."""
    order = ml_api_get(f"/orders/{quote(order_id)}")
    if not isinstance(order, dict):
        return {}
    buyer = order.get("buyer") if isinstance(order.get("buyer"), dict) else {}
    billing = buyer.get("billing_info")
    billing_id = (billing.get("id") if isinstance(billing, dict) else billing) or ""
    if not str(billing_id).strip():
        try:
            order_v2 = ml_api_get(f"/orders/{quote(order_id)}", headers={"X-Api-Version": "2"})
            if isinstance(order_v2, dict):
                buyer_v2 = order_v2.get("buyer") if isinstance(order_v2.get("buyer"), dict) else {}
                if buyer_v2.get("billing_info"):
                    order["buyer"] = {**buyer, "billing_info": buyer_v2.get("billing_info")}
        except Exception:
            pass
    return _ml_billing_details(order)


def _nome_fiscal_valido(nome: str) -> bool:
    """Pelo menos duas palavras e quase sem número. Barra texto de tela lido
    por engano (a extensão já pegou "Observações" uma vez, em 18/09/2026).
    V20.09: o sobrenome pode vir abreviado na NF-e ("NAYARA C"); uma palavra precisa ter 2+ letras.
    Asterisco é nome mascarado, não abreviado."""
    nome = str(nome or "").strip()
    if not (5 <= len(nome) <= 150) or len(re.findall(r"\d", nome)) > 2 or "*" in nome:
        return False
    palavras = [p for p in nome.split() if re.search(r"[A-Za-zÀ-ÿ]", p)]
    return len(palavras) >= 2 and any(re.search(r"[A-Za-zÀ-ÿ]{2,}", p) for p in palavras)


def _nome_unico_valido(nome: str) -> bool:
    """V20.10: uma palavra só de letras ("Jeoacaz"). Vale só na Shopee com CPF (salvar_cliente_fiscal):
    lá o nome vem de um campo da venda, e no ML a extensão lê a página, que pode trazer rótulo."""
    nome = str(nome or "").strip()
    return bool(re.fullmatch(r"[A-Za-zÀ-ÿ'’-]{3,40}", nome)) and not EXP_NOME_ROTULO.match(_exp_limpo(nome))


def salvar_cliente_fiscal(pedido: str, documento: str, nome: str, *, linx_cliente: str = "",
                          fonte: str = "", usuario: str = "", so_se_vazio: bool = False) -> dict[str, Any]:
    """V17.86 — guarda o que a extensão leu na venda (e o código no Linx).
    V20.30 (revisão 06/11): `so_se_vazio` = só grava se o pedido ainda não tem nada (conferido na mesma vez
    do DB_LOCK da gravação; o que outra extensão gravou nunca é sobrescrito)."""
    pedido = str(pedido or "").strip()
    numero = re.sub(r"\D", "", str(documento or ""))
    nome = re.sub(r"\s+", " ", str(nome or "")).strip()
    linx_cliente = re.sub(r"\D", "", str(linx_cliente or ""))
    if not pedido:
        return {"ok": False, "error": "Informe o pedido."}
    if len(numero) not in (11, 14):
        return {"ok": False, "error": "CPF precisa ter 11 dígitos e CNPJ, 14."}
    uma_palavra = len(numero) == 11 and _nome_unico_valido(nome)
    if not _nome_fiscal_valido(nome) and not uma_palavra:
        return {"ok": False, "error": "Nome da NF-e inválido: precisa de nome e sobrenome."}
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
        if not linhas:
            return {"ok": False, "error": f"Pedido {pedido} não encontrado."}
        if not _nome_fiscal_valido(nome) and not any(_linha_shopee_v1866(r) for r in linhas):
            return {"ok": False, "error": "Nome da NF-e inválido: precisa de nome e sobrenome."}
        if so_se_vazio and DB.execute("SELECT 1 FROM cliente_fiscal WHERE order_key=?",
                                      (normalize(pedido),)).fetchone():
            return {"ok": False, "ja_existia": True, "error": "O pedido já tem nome/CPF da NF-e guardado."}
        agora = now_iso()
        DB.execute(
            """INSERT INTO cliente_fiscal(order_key,pedido,documento_tipo,documento_numero,nome_fiscal,
                   fonte,linx_cliente,linx_atualizado_em,atualizado_em,atualizado_por)
               VALUES(?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(order_key) DO UPDATE SET
                   pedido=excluded.pedido, documento_tipo=excluded.documento_tipo,
                   documento_numero=excluded.documento_numero, nome_fiscal=excluded.nome_fiscal,
                   fonte=excluded.fonte,
                   linx_cliente=CASE WHEN excluded.linx_cliente<>'' THEN excluded.linx_cliente ELSE cliente_fiscal.linx_cliente END,
                   linx_atualizado_em=CASE WHEN excluded.linx_cliente<>'' THEN excluded.linx_atualizado_em ELSE cliente_fiscal.linx_atualizado_em END,
                   atualizado_em=excluded.atualizado_em, atualizado_por=excluded.atualizado_por""",
            (normalize(pedido), pedido, "CNPJ" if len(numero) == 14 else "CPF", numero, nome,
             str(fonte or "")[:40], linx_cliente, agora if linx_cliente else "", agora, str(usuario or "")[:80]),
        )
        DB.commit()
    # V17.87: o nome da NF-e vira o Nome Conferência, se ainda não houver um.
    conferencia = preencher_nome_conferencia_se_vazio(pedido, nome, actor=str(usuario or "extensao-nfe"))
    return {"ok": True, "pedido": pedido, "conferencia_preenchida": conferencia}


CAMPOS_NOME_CONFERENCIA = ("Nome Conferência", "NomeConferencia", "ConferenciaNome", "Conferência")


def preencher_nome_conferencia_se_vazio(pedido: str, nome: str, actor: str = "extensao-nfe") -> int:
    """V17.87 — Nome Conferência = nome de "Dados para a NF-e", só onde está vazio.

    Diferente de /api/order-conference-name (V17.73), que é ação humana e cria
    override ADMIN: aqui é preenchimento automático, então NUNCA sobrescreve um
    nome já existente e NÃO cria override — quem quiser pode corrigir à mão
    depois. preserve_conference_names() já impede que a sincronização limpe o
    nome preenchido. Devolve quantas linhas foram preenchidas.
    """
    nome = " ".join(str(nome or "").split())
    pedido_key = normalize(pedido)
    if not pedido_key or not (_nome_fiscal_valido(nome) or _nome_unico_valido(nome)) or len(nome) > 180:
        return 0
    preenchidas = 0
    with DB_LOCK:
        DB.execute("BEGIN IMMEDIATE")
        try:
            for storage_key in ("conf_pedidos", "conf_pedidos_rascunhos"):
                raw_row = DB.execute("SELECT value,version FROM storage WHERE key=?", (storage_key,)).fetchone()
                if not raw_row:
                    continue
                rows = json.loads(str(raw_row["value"] or "[]"))
                if not isinstance(rows, list):
                    continue
                linhas = [r for r in rows if isinstance(r, dict) and normalize(order_number(r)) == pedido_key]
                # Se QUALQUER linha do pedido já tem nome, o pedido já tem dono: não mexe.
                if not linhas or any(str(r.get(c) or "").strip() for r in linhas for c in CAMPOS_NOME_CONFERENCIA):
                    continue
                for r in linhas:
                    for c in CAMPOS_NOME_CONFERENCIA:
                        r[c] = nome
                    r["NomeConferenciaFonte"] = "nfe_extensao"
                    preenchidas += 1
                DB.execute(
                    "UPDATE storage SET value=?,version=?,updated_at=? WHERE key=?",
                    (json_dumps(rows), int(raw_row["version"] or 0) + 1, now_iso(), storage_key),
                )
            if preenchidas:
                map_row = DB.execute(
                    "SELECT value,version FROM storage WHERE key='conf_nomes_conferencia_v1'"
                ).fetchone()
                try:
                    mapa = json.loads(str(map_row["value"] or "{}")) if map_row else {}
                except Exception:
                    mapa = {}
                if isinstance(mapa, dict) and not str(mapa.get(pedido_key) or "").strip():
                    mapa[pedido_key] = nome
                    if map_row:
                        DB.execute(
                            "UPDATE storage SET value=?,version=?,updated_at=? WHERE key='conf_nomes_conferencia_v1'",
                            (json_dumps(mapa), int(map_row["version"] or 0) + 1, now_iso()),
                        )
                    else:
                        DB.execute(
                            "INSERT INTO storage(key,value,version,updated_at) VALUES('conf_nomes_conferencia_v1',?,?,?)",
                            (json_dumps(mapa), 1, now_iso()),
                        )
            DB.commit()
        except Exception:
            DB.rollback()
            raise
    if preenchidas:
        audit(actor, "order.conference_name.auto_nfe", f"{pedido}|{nome}")
    return preenchidas


def _cliente_fiscal_guardado(pedido: str) -> dict[str, Any] | None:
    with DB_LOCK:
        row = DB.execute("SELECT * FROM cliente_fiscal WHERE order_key=?", (normalize(pedido),)).fetchone()
    return dict(row) if row else None


def pedidos_sem_nome_fiscal(dias: int = 10, limite: int = 40) -> dict[str, Any]:
    """V17.93 — pedidos pendentes do Mercado Livre e da Shopee que ainda não têm
    nome/CPF da nota guardados. A extensão lê esta lista em segundo plano, sem
    depender de uma aba do admin aberta (a leitura pela tela parava em silêncio
    quando a aba era fechada, congelada ou não recarregada)."""
    corte = (datetime.now() - timedelta(days=dias)).strftime("%Y-%m-%d")
    with DB_LOCK:
        pendentes, _, _ = get_storage("conf_pedidos")
        feitos = {
            r["order_key"] for r in DB.execute(
                "SELECT order_key FROM cliente_fiscal WHERE nome_fiscal<>'' AND documento_numero<>''"
            ).fetchall()
        }
    saida: list[dict[str, str]] = []
    vistos: set[str] = set()
    for row in _rows_from_storage_value(pendentes):
        if not isinstance(row, dict):
            continue
        marketplace = _vendas_marketplace(row.get("Marketplace") or row.get("Origem"))
        if marketplace not in ("Mercado Livre", "Shopee"):
            continue
        pedido = str(order_number(row) or "").strip()
        chave = normalize(pedido)
        if not pedido or chave in vistos or chave in feitos:
            continue
        if _vendas_data_iso(row.get("Data do Pedido")) < corte:
            continue
        vistos.add(chave)
        saida.append({"pedido": pedido, "marketplace": marketplace})
        if len(saida) >= limite:
            break
    return {"ok": True, "pedidos": saida}


def lista_cliente_fiscal(dias: int = 45) -> dict[str, Any]:
    """Tudo o que já foi lido nos últimos dias, por pedido. Para a Central."""
    limite = (datetime.now(timezone.utc) - timedelta(days=dias)).isoformat()
    with DB_LOCK:
        rows = DB.execute(
            "SELECT * FROM cliente_fiscal WHERE atualizado_em>=? ORDER BY atualizado_em", (limite,)
        ).fetchall()
        # V19.41: situação do cadastro automático (feito / aguardando / não encontrado).
        auto = {r["order_key"]: {"situacao": r["situacao"], "tentativas": r["tentativas"], "detalhe": r["detalhe"],
                                 "atualizado_em": r["atualizado_em"]}
                for r in DB.execute("SELECT * FROM cadastro_auto_v1941").fetchall()}
    return {"ok": True, "clientes": {
        r["pedido"]: {
            "documento": {"tipo": r["documento_tipo"], "numero": r["documento_numero"]},
            "nome_fiscal": r["nome_fiscal"],
            "linx_cliente": r["linx_cliente"],
            "linx_atualizado_em": r["linx_atualizado_em"],
            # V18.60: consulta automática na Linx Smart API (só leitura). Resultado
            # de outro documento (CPF corrigido depois) não vale: volta a pendente.
            "linx_api": {
                "status": r["linx_api_status"] if r["linx_api_documento"] == r["documento_numero"] else "",
                "cliente": r["linx_api_cliente"],
                "nome": r["linx_api_nome"],
                "erro": r["linx_api_erro"],
                "consultado_em": r["linx_api_consultado_em"],
                "credito": _json_obj(r["linx_api_credito"]),
            },
            "cadastro_auto": auto.get(r["order_key"]),
        } for r in rows
    }}


def cliente_fiscal_do_pedido(pedido: str) -> dict[str, Any]:
    """CPF/CNPJ e nome fiscal de um pedido, para atualizar o cliente no Linx.

    1. O que o pedido já guarda (V17.84 em diante).
    2. Mercado Livre sem o dado guardado (pedidos anteriores à V17.84): relê o
       billing-info na API do ML. Nunca cai para apelido nem para quem recebe.
    """
    pedido = str(pedido or "").strip()
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
    if not linhas:
        return {"ok": False, "error": f"Pedido {pedido} não encontrado."}

    marketplace = _vendas_marketplace(linhas[0].get("Marketplace") or linhas[0].get("Origem"))
    documento = {"tipo": "", "numero": ""}
    nome = ""
    for row in linhas:
        if not documento["numero"]:
            documento = documento_do_pedido(row)
        if not nome:
            nome = nome_fiscal_do_pedido(row)
    fonte = "pedido" if (documento["numero"] and nome) else ""
    aviso = ""
    linx_cliente = ""

    # V17.86: o que a extensão já leu na página da venda vale mais que o pedido
    # (que a sincronização do ML reescreve com vazio) e evita outra leitura.
    guardado = _cliente_fiscal_guardado(pedido)
    if guardado:
        linx_cliente = guardado.get("linx_cliente") or ""
        if guardado.get("documento_numero") and guardado.get("nome_fiscal"):
            documento = {"tipo": guardado["documento_tipo"], "numero": guardado["documento_numero"]}
            nome = guardado["nome_fiscal"]
            fonte = "noromak"

    if (not documento["numero"] or not nome) and marketplace == "Mercado Livre":
        order_id = ""
        for row in linhas:
            order_id = re.sub(r"\D", "", str(row.get("VendaMercadoLivre") or ""))
            if order_id:
                break
        order_id = order_id or re.sub(r"\D", "", pedido)
        agora = time.time()
        guardado = CLIENTE_FISCAL_CACHE.get(order_id)
        if guardado and agora - guardado[0] < CLIENTE_FISCAL_CACHE_SEGUNDOS:
            billing = guardado[1]
        else:
            try:
                billing = _ml_billing_do_pedido(order_id) if order_id else {}
            except Exception as exc:
                billing = {}
                aviso = f"Não consegui ler Dados para a NF-e no Mercado Livre: {str(exc)[:200]}"
            if billing.get("name") or billing.get("doc_number"):
                CLIENTE_FISCAL_CACHE[order_id] = (agora, billing)
                _cache_podar(CLIENTE_FISCAL_CACHE, CLIENTE_FISCAL_CACHE_SEGUNDOS, CLIENTE_FISCAL_CACHE_MAX)
        numero_api = re.sub(r"\D", "", str(billing.get("doc_number") or ""))
        if not documento["numero"] and len(numero_api) in (11, 14):
            documento = {"tipo": "CNPJ" if len(numero_api) == 14 else "CPF", "numero": numero_api}
        if not nome:
            nome = str(billing.get("name") or "").strip()
        if documento["numero"] or nome:
            fonte = "mercado_livre"

    if not aviso and marketplace == "Shopee" and not documento["numero"]:
        aviso = "A Shopee não informa o CPF do comprador. Digite o CPF e o nome da nota."
    elif not aviso and (not documento["numero"] or not nome):
        aviso = "Faltou dado da NF-e neste pedido. Confira e complete antes de consultar."

    return {
        "ok": True,
        "pedido": pedido,
        "marketplace": marketplace,
        "documento": documento,
        "nome_fiscal": nome,
        "fonte": fonte,
        "aviso": aviso,
        "linx_cliente": linx_cliente,
    }


# ---------------------------------------------------------------------------
# V18.60 — Linx Smart API (a API oficial do Linx DMS, na nuvem da Linx).
# Etapa 1: conexão + "este cliente já está cadastrado no Linx?".
#
# SOMENTE LEITURA. Esta seção só pede token e consulta cliente por CPF/CNPJ
# (ConsultaClientes, catálogo V01 Veículos CRM). Nenhuma função daqui grava no
# Linx — cadastro, atendimento e romaneio ficam para etapas com confirmação.
#
# Diferente do botão Cliente (V17.85), que fala com o Linx LOCAL (10.1.15.1) pela
# extensão: o gateway da Smart API é público, então quem chama é o servidor.
# Chave da assinatura, usuário e senha só no .env; nunca vão ao navegador nem ao log.
# Contrato: INTEGRACAO_LINX_SMART_API.md.
# ---------------------------------------------------------------------------
LINX_API_BASE = os.getenv("LINX_API_BASE", "https://auto-gwsmartapi.linx.com.br").strip().rstrip("/")
LINX_API_CHAVE = os.getenv("LINX_API_CHAVE", "").strip()
LINX_API_USUARIO = os.getenv("LINX_API_USUARIO", "").strip()
LINX_API_SENHA = os.getenv("LINX_API_SENHA", "").strip()
LINX_API_CNPJ = re.sub(r"\D", "", os.getenv("LINX_API_CNPJ", ""))
LINX_EMPRESA = int(os.getenv("LINX_EMPRESA", "1") or 1)
LINX_REVENDA = int(os.getenv("LINX_REVENDA", "1") or 1)
LINX_USUARIO_CODIGO = int(os.getenv("LINX_USUARIO_CODIGO", "0") or 0)
LINX_CODIGO_ORIGEM = int(os.getenv("LINX_CODIGO_ORIGEM", "32") or 32)
LINX_PATH_SEGURANCA = os.getenv("LINX_PATH_SEGURANCA", "/api-seguranca").strip().rstrip("/")
LINX_PATH_CLIENTES = os.getenv("LINX_PATH_CLIENTES", "/api-veiculos-crm").strip().rstrip("/")
# V18.85: cada produto assinado tem a SUA chave no portal — a chave de um produto dá
# 401 em outro (medido pelo NoromakWeb no F02, 08/10/2026). LINX_API_CHAVE_<produto>
# no .env; vazio = usa a LINX_API_CHAVE geral (como era até a V18.84).
LINX_PATH_GERENCIAL = os.getenv("LINX_PATH_GERENCIAL", "/api-gerencial-pecas").strip().rstrip("/")
LINX_PATH_FATURAMENTO = os.getenv("LINX_PATH_FATURAMENTO", "/api-faturamento").strip().rstrip("/")
LINX_PATH_FINANCEIRO = os.getenv("LINX_PATH_FINANCEIRO", "/api-financeiro").strip().rstrip("/")
LINX_PRODUTOS_NOMES = {
    "S01": "Segurança (token)",
    "V01": "Veículos CRM (cliente e crédito)",
    "P02": "Peças Balcão (romaneio e caixa)",
    "G03": "Gerencial Peças (atendimentos abertos)",
    "F01": "Faturamento (condições de pagamento, XML da nota)",
    "F02": "Financeiro (títulos)",
}
LINX_API_CHAVES = {cod: os.getenv(f"LINX_API_CHAVE_{cod}", "").strip() for cod in LINX_PRODUTOS_NOMES}
# O portal não diz como o token vai nas chamadas; "Bearer" é o mais provável.
LINX_AUTH_ESQUEMA = os.getenv("LINX_AUTH_ESQUEMA", "Bearer").strip()
LINX_HTTP_TIMEOUT = max(5, min(60, int(os.getenv("LINX_HTTP_TIMEOUT", "25") or 25)))
LINX_CLIENTES_INTERVALO = max(60, int(os.getenv("LINX_CLIENTES_INTERVALO", "120") or 120))
LINX_CLIENTES_LOTE = 10
LINX_CLIENTES_DIAS = 45
# "Não cadastrado" é consultado de novo: alguém (ou o robô) pode ter cadastrado.
LINX_RECONSULTA_SEM_CADASTRO = 6 * 3600
LINX_RECONSULTA_ERRO = 15 * 60

LINX_TOKEN_LOCK = threading.Lock()
LINX_TOKEN: dict[str, Any] = {"access_token": "", "expira": 0.0}
LINX_ESTADO: dict[str, str] = {"ultimo_ok": "", "ultimo_erro": "", "ultimo_erro_em": ""}


class LinxErro(RuntimeError):
    def __init__(self, mensagem: str, status: int = 0):
        self.status = status
        super().__init__(mensagem)


def linx_configuracao_faltando() -> list[str]:
    """Nomes (nunca valores) das variáveis do .env que faltam."""
    return [nome for nome, valor in (
        # V18.85: o token sai com a chave da S01 (ou a geral).
        ("LINX_API_CHAVE", linx_chave_do_produto("S01")),
        ("LINX_API_USUARIO", LINX_API_USUARIO),
        ("LINX_API_SENHA", LINX_API_SENHA),
    ) if not valor]


def linx_chave_do_produto(produto: str) -> str:
    return LINX_API_CHAVES.get(produto) or LINX_API_CHAVE


def _linx_produto_do_caminho(caminho: str) -> str:
    """V18.85: qual produto assinado atende este caminho (pelo prefixo /api-...)."""
    prefixos = {LINX_PATH_SEGURANCA: "S01", LINX_PATH_CLIENTES: "V01", LINX_PATH_PECAS: "P02",
                LINX_PATH_GERENCIAL: "G03", LINX_PATH_FATURAMENTO: "F01", LINX_PATH_FINANCEIRO: "F02"}
    for prefixo, produto in prefixos.items():
        if prefixo and (caminho == prefixo or caminho.startswith(prefixo + "/")):
            return produto
    return ""


def linx_chaves_status() -> list[dict[str, str]]:
    """De onde sai a chave de cada produto — nunca o valor."""
    saida = []
    for produto, nome in LINX_PRODUTOS_NOMES.items():
        origem = "propria" if LINX_API_CHAVES.get(produto) else ("geral" if LINX_API_CHAVE else "falta")
        saida.append({"produto": produto, "nome": nome, "chave": origem,
                      "variavel": f"LINX_API_CHAVE_{produto}"})
    return saida


def _linx_registrar(erro: str = "") -> None:
    if erro:
        LINX_ESTADO["ultimo_erro"] = erro[:500]
        LINX_ESTADO["ultimo_erro_em"] = now_iso()
    else:
        LINX_ESTADO["ultimo_ok"] = now_iso()


def _linx_http(metodo: str, caminho: str, *, corpo: Any = None, form: dict[str, str] | None = None,
               com_token: bool = True) -> Any:
    return _linx_http_status(metodo, caminho, corpo=corpo, form=form, com_token=com_token)[1]


def _linx_http_status(metodo: str, caminho: str, *, corpo: Any = None, form: dict[str, str] | None = None,
                      com_token: bool = True) -> tuple[int, Any]:
    """Devolve (status, json). O status importa: a Linx responde 208 quando quer
    uma confirmação do usuário (diálogo), e isso NUNCA é respondido sozinho."""
    produto = _linx_produto_do_caminho(caminho)
    chave = linx_chave_do_produto(produto) if produto else LINX_API_CHAVE
    if not chave:
        variavel = f"LINX_API_CHAVE_{produto} ou LINX_API_CHAVE" if produto else "LINX_API_CHAVE"
        raise LinxErro(f"Falta a chave da assinatura {produto} no .env do servidor ({variavel}).".replace("  ", " "))
    headers = {
        "Ocp-Apim-Subscription-Key": chave,
        "Accept": "application/json",
        "User-Agent": f"NoromakExpedicao/{APP_VERSION}",
    }
    dados = None
    if form is not None:
        # /token pede multipart/form-data (contrato do portal).
        limite = "----noromak" + secrets.token_hex(12)
        partes = []
        for nome, valor in form.items():
            partes.append(
                f'--{limite}\r\nContent-Disposition: form-data; name="{nome}"\r\n\r\n{valor}\r\n'
            )
        partes.append(f"--{limite}--\r\n")
        dados = "".join(partes).encode("utf-8")
        headers["Content-Type"] = f"multipart/form-data; boundary={limite}"
    elif corpo is not None:
        dados = json.dumps(corpo).encode("utf-8")
        headers["Content-Type"] = "application/json"
    if com_token:
        token = linx_obter_token()
        headers["Authorization"] = f"{LINX_AUTH_ESQUEMA} {token}".strip()
    req = urllib.request.Request(LINX_API_BASE + caminho, data=dados, headers=headers, method=metodo)
    try:
        with urllib.request.urlopen(req, timeout=LINX_HTTP_TIMEOUT) as resp:
            bruto = resp.read().decode("utf-8", errors="replace")
            status = int(getattr(resp, "status", 200) or 200)
    except urllib.error.HTTPError as exc:
        texto = ""
        try:
            texto = exc.read().decode("utf-8", errors="replace")
        except Exception:
            pass
        detalhe = ""
        try:
            erro = json.loads(texto or "{}")
            if isinstance(erro, dict):
                detalhe = str(erro.get("MensagemDeErro") or erro.get("message") or erro.get("Message")
                              or erro.get("error_description") or erro.get("error") or "")
        except Exception:
            detalhe = texto[:200]
        raise LinxErro(f"Linx respondeu HTTP {exc.code}" + (f": {detalhe[:300]}" if detalhe else "."), exc.code) from exc
    except urllib.error.URLError as exc:
        raise LinxErro(f"Linx Smart API indisponível: {exc.reason}") from exc
    if not bruto.strip():
        return status, None
    try:
        return status, json.loads(bruto)
    except Exception as exc:
        raise LinxErro("Linx Smart API devolveu resposta que não é JSON.") from exc


def linx_obter_token(forcar: bool = False) -> str:
    faltando = linx_configuracao_faltando()
    if faltando:
        raise LinxErro("Linx Smart API não configurada no servidor: falta " + ", ".join(faltando) + ".")
    with LINX_TOKEN_LOCK:
        if not forcar and LINX_TOKEN["access_token"] and time.time() < LINX_TOKEN["expira"] - 60:
            return LINX_TOKEN["access_token"]
        form = {"grant_type": "client_credentials", "username": LINX_API_USUARIO, "password": LINX_API_SENHA}
        if LINX_API_CNPJ:
            form["cnpjEmpresa"] = LINX_API_CNPJ
        resposta = _linx_http("POST", f"{LINX_PATH_SEGURANCA}/token", form=form, com_token=False)
        dados = resposta if isinstance(resposta, dict) else {}
        if isinstance(dados.get("Token"), dict):
            dados = dados["Token"]
        token = str(dados.get("access_token") or "").strip()
        if not token:
            raise LinxErro("A Linx não devolveu o token (confira usuário, senha e chave da assinatura).")
        try:
            validade = float(dados.get("expires_in") or 3600)
        except (TypeError, ValueError):
            validade = 3600.0
        LINX_TOKEN["access_token"] = token
        LINX_TOKEN["expira"] = time.time() + max(120.0, validade)
        return token


def linx_chamar(metodo: str, caminho: str, corpo: Any = None) -> Any:
    return linx_chamar_status(metodo, caminho, corpo)[1]


def linx_chamar_status(metodo: str, caminho: str, corpo: Any = None) -> tuple[int, Any]:
    """Chamada autenticada. Token recusado (401) → pede outro e tenta uma vez."""
    try:
        return _linx_http_status(metodo, caminho, corpo=corpo)
    except LinxErro as exc:
        if exc.status != 401:
            raise
        linx_obter_token(forcar=True)
        return _linx_http_status(metodo, caminho, corpo=corpo)


def _linx_documento_do_registro(reg: dict[str, Any]) -> str:
    cgc = re.sub(r"\D", "", str(reg.get("Cgc") or reg.get("CgcCpf") or ""))
    if cgc and int(cgc or 0):
        return cgc.zfill(14) if len(cgc) > 11 else cgc.zfill(11)
    cpf = re.sub(r"\D", "", str(reg.get("Cpf") or ""))
    if cpf and int(cpf or 0):
        return cpf.zfill(11)
    return ""


def _linx_registros_do_documento(documento: str) -> list[dict[str, Any]]:
    """Registros CRUS da ConsultaClientes para o CPF/CNPJ. Só leitura.
    V18.70: separado de linx_consultar_cliente para o teste do crédito, que
    precisa do cadastro inteiro (o Simplificado regrava todos os campos)."""
    numero = re.sub(r"\D", "", str(documento or ""))
    if len(numero) not in (11, 14):
        raise ValueError("CPF precisa ter 11 dígitos e CNPJ, 14.")
    corpo = {
        "CgcOuCpf": numero,
        "PessoaFisica": len(numero) == 11,
        "Empresa": LINX_EMPRESA,
        "Revenda": LINX_REVENDA,
        "Usuario": LINX_USUARIO_CODIGO,
        "CodigoOrigem": LINX_CODIGO_ORIGEM,
    }
    resposta = linx_chamar("POST", f"{LINX_PATH_CLIENTES}/Geral/ConsultaClientes/ConsultaClientes", corpo)
    if isinstance(resposta, dict):
        resposta = resposta.get("Registros") or resposta.get("Clientes") or ([resposta] if resposta.get("Cliente") else [])
    registros = [r for r in (resposta or []) if isinstance(r, dict) and str(r.get("Cliente") or "").strip() not in ("", "0")]
    com_documento = [r for r in registros if _linx_documento_do_registro(r)]
    if com_documento:
        # A busca já filtra pelo documento; a conferência aqui só evita aceitar
        # um cliente de outro CPF caso a Linx devolva resultado aproximado.
        registros = [r for r in com_documento if _linx_documento_do_registro(r) == numero]
    return registros


def linx_consultar_cliente(documento: str) -> dict[str, Any]:
    """Procura o cliente pelo CPF/CNPJ. Só leitura.

    status: "encontrado" (um código só), "varios" (mais de um código para o
    mesmo documento — nunca escolhe sozinho) ou "nao_cadastrado".
    """
    registros = _linx_registros_do_documento(documento)
    codigos: dict[str, str] = {}
    creditos: dict[str, dict[str, str]] = {}
    for r in registros:
        codigo = str(r.get("Cliente")).strip()
        codigos.setdefault(codigo, str(r.get("Nome") or "").strip())
        creditos.setdefault(codigo, _linx_credito_do_registro(r))
    _linx_registrar()
    if not codigos:
        return {"status": "nao_cadastrado", "cliente": "", "nome": "", "credito": {}, "candidatos": []}
    candidatos = [{"cliente": c, "nome": n} for c, n in codigos.items()]
    if len(candidatos) == 1:
        return {"status": "encontrado", "cliente": candidatos[0]["cliente"], "nome": candidatos[0]["nome"],
                "credito": creditos[candidatos[0]["cliente"]], "candidatos": candidatos}
    return {"status": "varios", "cliente": "", "nome": "", "credito": {}, "candidatos": candidatos}


def _linx_credito_do_registro(reg: dict[str, Any]) -> dict[str, str]:
    """V18.60: situação de crédito como a Linx devolve (texto cru — o significado de
    cada código ainda não foi confirmado). A API NÃO altera crédito; só mostra."""
    return {campo: str(reg.get(origem) or "").strip() for campo, origem in (
        ("situacao", "SituacaoCredito"), ("bloqueio", "BloqueioCredito"),
        ("disponibilidade", "DisponibilidadeCredito"), ("conceito", "Conceito"),
    ) if str(reg.get(origem) or "").strip()}


def ensure_cliente_fiscal_linx_api_schema() -> None:
    """V18.60: resultado da consulta automática ao Linx, separado de linx_cliente.

    linx_cliente continua sendo o que a extensão GRAVOU no Linx (cadastro
    atualizado com o nome da nota). As colunas linx_api_* só dizem se o
    cliente já existe lá — a consulta nunca apaga nem troca o que a extensão guardou.
    """
    colunas = {
        "linx_api_documento": "TEXT NOT NULL DEFAULT ''",
        "linx_api_status": "TEXT NOT NULL DEFAULT ''",
        "linx_api_cliente": "TEXT NOT NULL DEFAULT ''",
        "linx_api_nome": "TEXT NOT NULL DEFAULT ''",
        "linx_api_erro": "TEXT NOT NULL DEFAULT ''",
        "linx_api_consultado_em": "TEXT NOT NULL DEFAULT ''",
        "linx_api_consultado_epoch": "INTEGER NOT NULL DEFAULT 0",
        "linx_api_credito": "TEXT NOT NULL DEFAULT ''",
    }
    with DB_LOCK:
        existentes = {str(r["name"]) for r in DB.execute("PRAGMA table_info(cliente_fiscal)").fetchall()}
        if not existentes:
            return
        for nome, tipo in colunas.items():
            if nome not in existentes:
                DB.execute(f"ALTER TABLE cliente_fiscal ADD COLUMN {nome} {tipo}")
        DB.commit()


def linx_clientes_pendentes(limite: int = LINX_CLIENTES_LOTE) -> list[dict[str, str]]:
    """Pedidos com CPF/CNPJ guardado que ainda não sabem se o cliente existe no Linx."""
    agora = int(time.time())
    corte = (datetime.now(timezone.utc) - timedelta(days=LINX_CLIENTES_DIAS)).isoformat()
    with DB_LOCK:
        rows = DB.execute(
            """SELECT order_key, documento_numero FROM cliente_fiscal
               WHERE documento_numero<>'' AND linx_cliente='' AND atualizado_em>=?
                 AND (linx_api_documento<>documento_numero OR linx_api_status=''
                      OR (linx_api_status IN ('nao_cadastrado','varios') AND linx_api_consultado_epoch<?)
                      OR (linx_api_status='erro' AND linx_api_consultado_epoch<?))
               ORDER BY linx_api_consultado_epoch, atualizado_em DESC LIMIT ?""",
            (corte, agora - LINX_RECONSULTA_SEM_CADASTRO, agora - LINX_RECONSULTA_ERRO, int(limite)),
        ).fetchall()
    return [{"order_key": r["order_key"], "documento": r["documento_numero"]} for r in rows]


def _linx_guardar_consulta(order_key: str, documento: str, resultado: dict[str, Any] | None, erro: str = "") -> None:
    with DB_LOCK:
        DB.execute(
            """UPDATE cliente_fiscal SET linx_api_documento=?, linx_api_status=?, linx_api_cliente=?,
                   linx_api_nome=?, linx_api_erro=?, linx_api_consultado_em=?, linx_api_consultado_epoch=?,
                   linx_api_credito=?
               WHERE order_key=? AND documento_numero=?""",
            (documento, "erro" if erro else str(resultado.get("status") or ""),
             "" if erro else str(resultado.get("cliente") or ""),
             "" if erro else str(resultado.get("nome") or "")[:150],
             erro[:300], now_iso(), int(time.time()),
             "" if erro else json_dumps(resultado.get("credito") or {}), order_key, documento),
        )
        DB.commit()


def linx_clientes_sincronizar(limite: int = LINX_CLIENTES_LOTE) -> dict[str, Any]:
    """Consulta no Linx os clientes pendentes. Só leitura no Linx."""
    resumo = {"ok": True, "consultados": 0, "encontrados": 0, "nao_cadastrados": 0, "varios": 0, "erros": 0}
    faltando = linx_configuracao_faltando()
    if faltando:
        return {**resumo, "ok": False, "error": "Linx Smart API não configurada: falta " + ", ".join(faltando) + "."}
    for item in linx_clientes_pendentes(limite):
        try:
            resultado = linx_consultar_cliente(item["documento"])
        except LinxErro as exc:
            _linx_registrar(str(exc))
            _linx_guardar_consulta(item["order_key"], item["documento"], None, str(exc))
            resumo["erros"] += 1
            if exc.status in (0, 401, 403, 429) or exc.status >= 500:
                # Credencial, limite ou Linx fora do ar: parar o lote em vez de insistir.
                resumo.update(ok=False, error=str(exc))
                break
            continue
        except ValueError as exc:
            _linx_guardar_consulta(item["order_key"], item["documento"], None, str(exc))
            resumo["erros"] += 1
            continue
        _linx_guardar_consulta(item["order_key"], item["documento"], resultado)
        resumo["consultados"] += 1
        chave = {"encontrado": "encontrados", "nao_cadastrado": "nao_cadastrados", "varios": "varios"}.get(resultado["status"])
        if chave:
            resumo[chave] += 1
    return resumo


def linx_clientes_loop(stop_event: threading.Event) -> None:
    """V18.60: consulta sozinha os clientes novos. Sem .env da Linx, não faz nada."""
    if stop_event.wait(90):
        return
    while not stop_event.is_set():
        if not linx_configuracao_faltando():
            try:
                linx_clientes_sincronizar()
            except Exception as exc:
                _linx_registrar(str(exc))
                print(f"[linx-clientes] falhou: {exc}", file=sys.stderr, flush=True)
        if stop_event.wait(LINX_CLIENTES_INTERVALO):
            break


def linx_status_payload() -> dict[str, Any]:
    with DB_LOCK:
        contagem = {
            r["s"] or "pendente": int(r["n"]) for r in DB.execute(
                """SELECT CASE WHEN linx_api_documento<>documento_numero THEN '' ELSE linx_api_status END AS s,
                          COUNT(*) AS n FROM cliente_fiscal
                   WHERE documento_numero<>'' AND linx_cliente='' GROUP BY s"""
            ).fetchall()
        }
    faltando = linx_configuracao_faltando()
    return {
        "ok": True,
        "configurado": not faltando,
        "faltando": faltando,
        "gateway": LINX_API_BASE,
        "empresa": LINX_EMPRESA,
        "revenda": LINX_REVENDA,
        "token_valido": bool(LINX_TOKEN["access_token"]) and time.time() < LINX_TOKEN["expira"],
        "escrita_ativa": LINX_ESCRITA_ATIVA,
        "chaves": linx_chaves_status(),
        "ultimo_ok": LINX_ESTADO["ultimo_ok"],
        "ultimo_erro": LINX_ESTADO["ultimo_erro"],
        "ultimo_erro_em": LINX_ESTADO["ultimo_erro_em"],
        "clientes": contagem,
    }


def linx_testar_conexao(documento: str = "") -> dict[str, Any]:
    """Pede um token novo e, se vier documento, consulta o cliente. Não grava nada."""
    try:
        linx_obter_token(forcar=True)
        _linx_registrar()
        saida: dict[str, Any] = {"ok": True, "token": True}
        if re.sub(r"\D", "", str(documento or "")):
            saida["consulta"] = linx_consultar_cliente(documento)
        return saida
    except (LinxErro, ValueError) as exc:
        _linx_registrar(str(exc))
        return {"ok": False, "error": str(exc)}


# ---------------------------------------------------------------------------
# V18.85 — diagnóstico da Smart API, SOMENTE LEITURA, por uma lista FECHADA.
# Responde o que falta saber para ligar romaneio, caixa e crédito pelo servidor:
#   - a chave de cada produto funciona? (S01, V01, P02, G03, F01, F02)
#   - a Agenda lista os atendimentos do cliente? (romaneio sem a extensão)
#   - os atendimentos abertos (G03) trazem vendedor e valor? (caixa sem a extensão)
#   - as condições 213/971/983 aparecem? (F01)
#   - os títulos do cliente vêm do F02? (conferir o faturamento depois)
# Devolve contagens e NOMES de campos — nunca valores (CPF, nome, telefone vêm
# nessas respostas). Nenhuma função daqui grava: nenhuma entra em LINX_DIAGNOSTICO
# sem ser consulta (o teste confere a lista).
# ---------------------------------------------------------------------------
LINX_DIAGNOSTICO = (
    ("S01", "POST", "/token"),
    ("V01", "POST", "/Geral/ConsultaClientes/ConsultaClientes"),
    ("P02", "GET", "/VendaExternaPecas/Contatos/Agenda/{empresa}/{revenda}/{usuario}"),
    ("G03", "POST", "/ConsultaGerencial/Pecas/AtendimentosAbertos"),
    ("F01", "GET", "/Faturamento/Cadastros/CondicoesPagamento/ObterListaCondicoesPagamento/{empresa}"),
    ("F02", "GET", "/Alcadas/GetRevendas"),
    ("F02", "POST", "/Titulos/ConsultarTitulos"),
)
LINX_CONDICOES_MARKETPLACE = {213: "Mercado Livre", 971: "Shopee", 983: "Magalu"}


def _linx_lista_da_resposta(resposta: Any) -> list[Any]:
    if isinstance(resposta, list):
        return resposta
    if isinstance(resposta, dict):
        for valor in resposta.values():
            if isinstance(valor, list):
                return valor
        return [resposta] if resposta else []
    return []


def _linx_campos(itens: list[Any]) -> list[str]:
    campos: set[str] = set()
    for item in itens[:50]:
        if isinstance(item, dict):
            campos.update(str(k) for k in item.keys())
    return sorted(campos)[:80]


def linx_diagnostico(documento: str = "") -> dict[str, Any]:
    """V18.85: roda cada consulta da lista e diz o que funcionou. Só leitura."""
    numero = re.sub(r"\D", "", str(documento or ""))
    hoje = datetime.now(timezone(timedelta(hours=-3))).date()
    testes: list[dict[str, Any]] = []
    contexto: dict[str, Any] = {"cliente": ""}

    def rodar(produto: str, funcao: str, executar) -> None:
        inicio = time.time()
        item: dict[str, Any] = {"produto": produto, "nome": LINX_PRODUTOS_NOMES.get(produto, ""),
                                "funcao": funcao, "ok": False, "status": 0, "resumo": "", "campos": []}
        try:
            resumo, campos = executar()
            item.update(ok=True, status=200, resumo=resumo, campos=campos)
        except _LinxPulo as exc:
            item.update(pulado=True, resumo=str(exc))
        except LinxErro as exc:
            if exc.status == 412:
                # 412 = "não achei" nesta API: a chamada funcionou.
                item.update(ok=True, status=412, resumo="Nada encontrado (412).")
            else:
                item.update(status=exc.status, erro=str(exc)[:300])
        except Exception as exc:  # resposta em formato inesperado não derruba o resto
            item.update(erro=f"{type(exc).__name__}: {str(exc)[:200]}")
        item["ms"] = int((time.time() - inicio) * 1000)
        testes.append(item)

    def token():
        linx_obter_token(forcar=True)
        return "Token recebido.", []

    def cliente():
        if len(numero) not in (11, 14):
            raise _LinxPulo("Informe um CPF/CNPJ para testar a consulta de cliente e os títulos.")
        registros = _linx_registros_do_documento(numero)
        codigos = sorted({str(r.get("Cliente")).strip() for r in registros})
        if len(codigos) == 1:
            contexto["cliente"] = codigos[0]
        credito = sorted({c for r in registros for c in LINX_CAMPOS_CREDITO if c in r})
        return (f"{len(codigos)} cadastro(s) para o documento. Campos de crédito na resposta: "
                f"{', '.join(credito) or 'nenhum'}.", _linx_campos(registros))

    def agenda():
        usuario = LINX_USUARIO_ATENDIMENTOS or LINX_USUARIO_CODIGO
        itens = _linx_lista_da_resposta(linx_chamar(
            "GET", f"{LINX_PATH_PECAS}/VendaExternaPecas/Contatos/Agenda/{LINX_EMPRESA}/{LINX_REVENDA}/{usuario}"))
        resumo = f"{len(itens)} contato(s) na Agenda do usuário {usuario}."
        if contexto["cliente"]:
            do_cliente = [i for i in itens if isinstance(i, dict)
                          and str(i.get("Cliente") or "").strip() == contexto["cliente"]]
            resumo += f" {len(do_cliente)} deste cliente."
        return resumo, _linx_campos(itens)

    def atendimentos_abertos():
        corpo = {"codigoUsuario": LINX_USUARIO_CODIGO, "codigoFilial": LINX_REVENDA,
                 "dataInicio": (hoje - timedelta(days=30)).isoformat() + "T00:00:00",
                 "dataFim": hoje.isoformat() + "T23:59:59", "marca": "",
                 "empresaRevenda": f"{LINX_EMPRESA}-{LINX_REVENDA}"}
        itens = _linx_lista_da_resposta(linx_chamar(
            "POST", f"{LINX_PATH_GERENCIAL}/ConsultaGerencial/Pecas/AtendimentosAbertos", corpo))
        campos = _linx_campos(itens)
        minusculos = [c.lower() for c in campos]
        tem_vendedor = any("vendedor" in c for c in minusculos)
        tem_valor = any("valor" in c or c.startswith("val") for c in minusculos)
        return (f"{len(itens)} atendimento(s) aberto(s) nos últimos 30 dias. Vendedor: "
                f"{'sim' if tem_vendedor else 'não'} · valor: {'sim' if tem_valor else 'não'}.", campos)

    def condicoes():
        itens = _linx_lista_da_resposta(linx_chamar(
            "GET", f"{LINX_PATH_FATURAMENTO}/Faturamento/Cadastros/CondicoesPagamento/"
                   f"ObterListaCondicoesPagamento/{LINX_EMPRESA}"))
        achadas = set()
        for item in itens:
            if not isinstance(item, dict):
                continue
            for campo, valor in item.items():
                if "condicao" in str(campo).lower():
                    try:
                        codigo = int(str(valor).strip())
                    except ValueError:
                        continue
                    if codigo in LINX_CONDICOES_MARKETPLACE:
                        achadas.add(codigo)
        marcas = " · ".join(f"{c} {m}: {'sim' if c in achadas else 'não'}"
                            for c, m in LINX_CONDICOES_MARKETPLACE.items())
        return f"{len(itens)} condição(ões). {marcas}.", _linx_campos(itens)

    def revendas():
        itens = _linx_lista_da_resposta(linx_chamar("GET", f"{LINX_PATH_FINANCEIRO}/Alcadas/GetRevendas"))
        codigos = sorted({str(i.get("Revenda")) for i in itens if isinstance(i, dict) and i.get("Revenda") is not None})
        return f"{len(itens)} revenda(s): {', '.join(codigos) or '—'}.", _linx_campos(itens)

    def titulos():
        if not contexto["cliente"]:
            raise _LinxPulo("Precisa de um CPF/CNPJ com um cadastro só no Linx.")
        # Revenda obrigatória; sem Status só vem o que está em aberto (manual do F02).
        itens = _linx_lista_da_resposta(linx_chamar(
            "POST", f"{LINX_PATH_FINANCEIRO}/Titulos/ConsultarTitulos",
            {"Empresa": LINX_EMPRESA, "Revenda": LINX_REVENDA, "Cliente": int(contexto["cliente"])}))
        tipos: dict[str, int] = {}
        for i in itens:
            if isinstance(i, dict):
                tipos[str(i.get("Tipo") or "?")] = tipos.get(str(i.get("Tipo") or "?"), 0) + 1
        detalhe = ", ".join(f"{n} {t}" for t, n in sorted(tipos.items()))
        return (f"{len(itens)} título(s) em aberto na revenda {LINX_REVENDA}" + (f" ({detalhe})." if detalhe else "."),
                _linx_campos(itens))

    if linx_configuracao_faltando():
        return {"ok": False, "error": "Linx Smart API não configurada no servidor: falta "
                                      + ", ".join(linx_configuracao_faltando()) + "."}
    rodar("S01", "Token", token)
    if not testes[-1]["ok"]:
        _linx_registrar(testes[-1].get("erro") or "token")
        return {"ok": True, "testes": testes, "chaves": linx_chaves_status()}
    rodar("V01", "Consulta de cliente (ConsultaClientes)", cliente)
    rodar("P02", "Agenda de atendimentos", agenda)
    rodar("G03", "Atendimentos abertos", atendimentos_abertos)
    rodar("F01", "Condições de pagamento", condicoes)
    rodar("F02", "Revendas (GetRevendas)", revendas)
    rodar("F02", "Títulos do cliente (ConsultarTitulos)", titulos)
    _linx_registrar()
    return {"ok": True, "testes": testes, "chaves": linx_chaves_status()}


class _LinxPulo(Exception):
    """Teste do diagnóstico que não roda sem um dado (ex.: CPF)."""


def linx_clientes_sem_cadastro() -> dict[str, Any]:
    """Fila de cadastro: pedidos cujo cliente a Linx diz que não existe."""
    corte = (datetime.now(timezone.utc) - timedelta(days=LINX_CLIENTES_DIAS)).isoformat()
    with DB_LOCK:
        rows = DB.execute(
            """SELECT pedido, documento_tipo, documento_numero, nome_fiscal, linx_api_consultado_em
               FROM cliente_fiscal
               WHERE linx_cliente='' AND linx_api_status='nao_cadastrado'
                 AND linx_api_documento=documento_numero AND atualizado_em>=?
               ORDER BY atualizado_em""",
            (corte,),
        ).fetchall()
    return {"ok": True, "pedidos": [{
        "pedido": r["pedido"],
        "documento": {"tipo": r["documento_tipo"], "numero": r["documento_numero"]},
        "nome_fiscal": r["nome_fiscal"],
        "consultado_em": r["linx_api_consultado_em"],
    } for r in rows]}


def _json_obj(texto: Any) -> dict[str, Any]:
    try:
        valor = json.loads(str(texto or "") or "{}")
    except Exception:
        return {}
    return valor if isinstance(valor, dict) else {}


# ---------------------------------------------------------------------------
# V18.60 — romaneio e cadastro pela Smart API (catálogos P02/P03 e V01).
#
# O atendimento (Contato) JÁ EXISTE: a integração do Mercado Livre com o Linx cria
# sozinha. O Noromak não cria contato nem item; ele só acha o contato do pedido,
# grava a Observação (marketplace + data do pedido) e confirma o romaneio.
#
# ConfirmaRomaneio MOVIMENTA ESTOQUE e imprime no depósito em até ~1 min — não
# volta atrás. Por isso:
#   - toda gravação exige LINX_ESCRITA_ATIVA=1 no .env (desligada por padrão,
#     até a leitura real ser conferida com o dono);
#   - só roda por clique humano depois de ver atendimento, itens e observação;
#   - relê a lista na hora (nunca confia na lista que a tela mostrou);
#   - registra cada operação em linx_operacoes_v1860 e recusa repetir;
#   - resposta 208 (a Linx perguntando algo) NUNCA é respondida sozinha.
# NÃO coberto pela API assinada: liberar crédito, trocar condição de pagamento
# (Shopee 971 / Magalu 983) e achar atendimentos pelo cliente diretamente.
# ---------------------------------------------------------------------------
LINX_ESCRITA_ATIVA = os.getenv("LINX_ESCRITA_ATIVA", "0").strip().lower() in {"1", "true", "sim"}
LINX_PATH_PECAS = os.getenv("LINX_PATH_PECAS", "/api-pecas-balcao-premium").strip().rstrip("/")
# Usuário dono dos atendimentos que a integração do ML cria (a Agenda é por usuário).
LINX_USUARIO_ATENDIMENTOS = int(os.getenv("LINX_USUARIO_ATENDIMENTOS", "0") or 0)
LINX_ROMANEIO_MAX_CONTATOS = 6
# Regra do dono (17/09/2026) para o cadastro de cliente de marketplace.
LINX_CADASTRO_EMAIL = "lojavirtual@noromak.com.br"
LINX_CADASTRO_DDD = 11
LINX_CADASTRO_TELEFONE = 111111111
LINX_OBSERVACAO_MARKETPLACE = {"Mercado Livre": "MERCADO LIVRE", "Shopee": "SHOPEE", "Magalu": "MAGALU"}


def ensure_linx_operacoes_schema() -> None:
    with DB_LOCK:
        DB.execute(
            """CREATE TABLE IF NOT EXISTS linx_operacoes_v1860 (
                   id INTEGER PRIMARY KEY AUTOINCREMENT,
                   order_key TEXT NOT NULL,
                   pedido TEXT NOT NULL DEFAULT '',
                   etapa TEXT NOT NULL,
                   contato TEXT NOT NULL DEFAULT '',
                   situacao TEXT NOT NULL,
                   detalhe TEXT NOT NULL DEFAULT '',
                   em TEXT NOT NULL,
                   por TEXT NOT NULL DEFAULT ''
               )"""
        )
        DB.execute("CREATE INDEX IF NOT EXISTS idx_linx_operacoes_pedido ON linx_operacoes_v1860(order_key, etapa)")
        DB.commit()


def _linx_operacao_registrar(pedido: str, etapa: str, situacao: str, detalhe: Any = "",
                             contato: Any = "", por: str = "") -> None:
    texto = detalhe if isinstance(detalhe, str) else json_dumps(detalhe)
    with DB_LOCK:
        DB.execute(
            "INSERT INTO linx_operacoes_v1860(order_key,pedido,etapa,contato,situacao,detalhe,em,por) VALUES(?,?,?,?,?,?,?,?)",
            (normalize(pedido), str(pedido), etapa, str(contato or ""), situacao, texto[:4000], now_iso(), str(por or "")[:80]),
        )
        DB.commit()


def linx_operacoes_do_pedido(pedido: str) -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute(
            "SELECT etapa,contato,situacao,detalhe,em,por FROM linx_operacoes_v1860 WHERE order_key=? ORDER BY id",
            (normalize(pedido),),
        ).fetchall()
    return [dict(r) for r in rows]


def _linx_identificacao(contato: int) -> dict[str, Any]:
    return {"Contato": int(contato), "Empresa": LINX_EMPRESA, "Revenda": LINX_REVENDA,
            "Usuario": LINX_USUARIO_CODIGO, "CodigoOrigem": LINX_CODIGO_ORIGEM}


def _linx_lista_romaneio(contato: int) -> dict[str, Any]:
    """GeraListaRomaneio: o que falta separar no atendimento. Só leitura."""
    corpo = {**_linx_identificacao(contato), "CodigoItemEstoque": None, "Ordem": None, "IdentificadorOrigem": ""}
    resposta = linx_chamar("POST", f"{LINX_PATH_PECAS}/Pecas/ManutencaoRomaneio/PecRomaneio/GeraListaRomaneio", corpo)
    return resposta if isinstance(resposta, dict) else {}


def _linx_itens_resumo(lista: dict[str, Any]) -> list[dict[str, Any]]:
    itens = []
    for i in lista.get("ItensRomaneio") or []:
        if isinstance(i, dict):
            itens.append({
                "item": str(i.get("ItemEstoquePub") or "").strip(),
                "descricao": str(i.get("DescricaoItemEstoque") or "").strip(),
                "quantidade": i.get("QuantidadeParaImprimir", i.get("QuantidadeSaldo")),
                "requisitada": i.get("QuantidadeRequisitada"),
            })
    return itens


def _linx_contatos_do_cliente(cliente: str) -> list[dict[str, Any]]:
    """Atendimentos do cliente pela Agenda do usuário da integração. A Smart API
    não tem 'atendimentos do cliente' (ObterAtendimentosDoCliente é só do Linx local)."""
    usuario = LINX_USUARIO_ATENDIMENTOS or LINX_USUARIO_CODIGO
    resposta = linx_chamar(
        "GET", f"{LINX_PATH_PECAS}/VendaExternaPecas/Contatos/Agenda/{LINX_EMPRESA}/{LINX_REVENDA}/{usuario}"
    )
    registros = resposta if isinstance(resposta, list) else (
        (resposta or {}).get("Registros") or (resposta or {}).get("Contatos") or [] if isinstance(resposta, dict) else []
    )
    vistos: dict[str, dict[str, Any]] = {}
    for r in registros:
        if not isinstance(r, dict) or str(r.get("Cliente") or "").strip() != str(cliente):
            continue
        contato = str(r.get("Contato") or "").strip()
        if contato and contato != "0" and contato not in vistos:
            vistos[contato] = {
                "contato": contato,
                "situacao": str(r.get("DescricaoSituacaoContato") or r.get("SituacaoCon") or "").strip(),
                "data": str(r.get("DataContato") or "").strip(),
            }
    return sorted(vistos.values(), key=lambda c: c["data"], reverse=True)


def _linx_codigos_do_pedido(linhas: list[dict[str, Any]]) -> set[str]:
    """SKUs do pedido nas formas em que o código Apollo pode aparecer
    (puro, prefixo-código, A/B)."""
    codigos: set[str] = set()
    for row in linhas:
        sku = str(row.get("SKU") or row.get("Sku") or "").upper()
        for parte in re.split(r"[/\-\s]+", sku):
            parte = re.sub(r"[^0-9A-Z]", "", parte)
            if parte:
                codigos.add(parte)
    return codigos


def _linx_observacao(marketplace: str, linhas: list[dict[str, Any]]) -> str:
    data = _vendas_data_da_linha(linhas[0]) if linhas else ""
    nome = LINX_OBSERVACAO_MARKETPLACE.get(marketplace, str(marketplace or "").upper())
    return f"{nome} {data[8:10]}/{data[5:7]}".strip() if data else nome


def _linx_documento_do_pedido(pedido: str, linhas: list[dict[str, Any]]) -> tuple[str, str]:
    guardado = _cliente_fiscal_guardado(pedido) or {}
    if guardado.get("documento_numero"):
        return guardado["documento_numero"], str(guardado.get("nome_fiscal") or "")
    for row in linhas:
        doc = documento_do_pedido(row)
        if doc["numero"]:
            return doc["numero"], nome_fiscal_do_pedido(row)
    return "", ""


def linx_romaneio_preparar(pedido: str, contatos: list[Any] | None = None) -> dict[str, Any]:
    """Mostra o que o romaneio faria. Só leitura no Linx.

    `contatos`: atendimentos que a extensão achou no Linx local
    (ObterAtendimentosDoCliente) — usados no lugar da Agenda quando vierem."""
    pedido = str(pedido or "").strip()
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
    if not linhas:
        return {"ok": False, "error": f"Pedido {pedido} não encontrado."}
    marketplace = _vendas_marketplace(linhas[0].get("Marketplace") or linhas[0].get("Origem"))
    saida: dict[str, Any] = {
        "ok": True, "pedido": pedido, "marketplace": marketplace,
        "observacao": _linx_observacao(marketplace, linhas),
        "escrita_ativa": LINX_ESCRITA_ATIVA,
        "precisa_condicao": marketplace in ("Shopee", "Magalu"),
        "operacoes": linx_operacoes_do_pedido(pedido),
        "cadastro": _linx_cadastro_situacao(pedido),
        "robo": linx_robo_fila_do_pedido(pedido),
        "cliente": None, "candidatos": [], "escolhido": "",
    }
    documento, nome = _linx_documento_do_pedido(pedido, linhas)
    if not documento:
        return {**saida, "situacao": "sem_documento",
                "aviso": "Este pedido ainda não tem CPF/CNPJ da nota. Puxe nome e CPF primeiro."}
    consulta = linx_consultar_cliente(documento)
    saida["cliente"] = {"documento": documento, "nome_fiscal": nome, **consulta}
    if consulta["status"] != "encontrado":
        return {**saida, "situacao": consulta["status"],
                "aviso": "Cliente não cadastrado no Linx." if consulta["status"] == "nao_cadastrado"
                else "Mais de um cliente com este CPF/CNPJ no Linx — confira no Linx."}
    codigos = _linx_codigos_do_pedido(linhas)
    candidatos = []
    informados = []
    for c in contatos or []:
        numero = re.sub(r"\D", "", str(c or ""))
        if numero and numero != "0" and numero not in [x["contato"] for x in informados]:
            informados.append({"contato": numero, "situacao": "informado pelo Linx", "data": ""})
    saida["fonte_contatos"] = "extensao" if informados else "agenda"
    lista_contatos = informados or _linx_contatos_do_cliente(consulta["cliente"])
    for c in lista_contatos[:LINX_ROMANEIO_MAX_CONTATOS]:
        itens = _linx_itens_resumo(_linx_lista_romaneio(int(c["contato"])))
        if not itens:
            continue  # nada a separar: romaneio já feito ou atendimento sem peça
        bate = sum(1 for i in itens if re.sub(r"[^0-9A-Z]", "", i["item"].upper()) in codigos)
        candidatos.append({**c, "itens": itens, "itens_do_pedido": bate})
    saida["candidatos"] = candidatos
    # Escolhe sozinho só quando não há dúvida: um atendimento com itens, ou um
    # único cujas peças batem com o pedido. Senão, quem escolhe é a pessoa.
    if len(candidatos) == 1:
        saida["escolhido"] = candidatos[0]["contato"]
    else:
        batem = [c for c in candidatos if c["itens_do_pedido"]]
        if len(batem) == 1:
            saida["escolhido"] = batem[0]["contato"]
    if not candidatos:
        return {**saida, "situacao": "sem_atendimento",
                "aviso": "Nenhum atendimento deste cliente com peças a separar (o romaneio pode já ter sido feito)."}
    return {**saida, "situacao": "pronto" if saida["escolhido"] else "escolher"}


def _linx_escrita_bloqueada() -> str:
    if linx_configuracao_faltando():
        return "Linx Smart API não configurada no servidor."
    if not LINX_ESCRITA_ATIVA:
        return ("Gravação no Linx desligada (LINX_ESCRITA_ATIVA=0). Ela é ligada depois que a "
                "consulta real for conferida.")
    return ""


def _linx_dialogo(resposta: Any) -> str:
    if isinstance(resposta, dict):
        return str(resposta.get("TextoDeConfirmacao") or resposta.get("MensagemErro") or "").strip()
    return ""


def _linx_cadastro_situacao(pedido: str) -> dict[str, bool]:
    """V18.60: o cadastro vem ANTES do romaneio (regra do dono, 02/10/2026).
    feito = o Noromak tem o código do cliente gravado (pela extensão, robô ou API).
    pela_api = a última atualização foi pela Smart API.
    credito_api = V18.70: a API gravou e a releitura confirmou 420, 421 e validade."""
    guardado = _cliente_fiscal_guardado(pedido) or {}
    cadastros = [o for o in linx_operacoes_do_pedido(pedido)
                 if o["etapa"] in ("cadastro", "cadastro_robo") and o["situacao"] == "ok"]
    ultimo = cadastros[-1] if cadastros else None
    creditos = [o for o in linx_operacoes_do_pedido(pedido) if o["etapa"] == "credito"]
    return {"feito": bool(str(guardado.get("linx_cliente") or "").strip()) or ultimo is not None,
            "pela_api": bool(ultimo and ultimo["etapa"] == "cadastro"),
            "credito_api": bool(creditos and creditos[-1]["situacao"] == "ok")}


def linx_romaneio_confirmar(pedido: str, contato: Any, observacao: str, *, condicao_conferida: bool = False,
                            credito_conferido: bool = False, usuario: str = "") -> dict[str, Any]:
    """Grava a Observação e confirma o romaneio (IMPRIME e movimenta estoque)."""
    pedido = str(pedido or "").strip()
    observacao = re.sub(r"\s+", " ", str(observacao or "")).strip().upper()
    bloqueio = _linx_escrita_bloqueada()
    if bloqueio:
        return {"ok": False, "error": bloqueio}
    try:
        contato_num = int(str(contato or "").strip())
    except ValueError:
        contato_num = 0
    if contato_num <= 0:
        return {"ok": False, "error": "Escolha o atendimento (Contato)."}
    if not observacao or len(observacao) > 120:
        return {"ok": False, "error": "Informe a observação do romaneio (ex.: MERCADO LIVRE 21/09)."}
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
    if not linhas:
        return {"ok": False, "error": f"Pedido {pedido} não encontrado."}
    marketplace = _vendas_marketplace(linhas[0].get("Marketplace") or linhas[0].get("Origem"))
    condicao_pela_extensao = any(o["etapa"] == "condicao" and o["situacao"] == "ok"
                                 for o in linx_operacoes_do_pedido(pedido))
    if marketplace in ("Shopee", "Magalu") and not (condicao_conferida or condicao_pela_extensao):
        return {"ok": False, "error": f"Confira no Linx a condição de pagamento do {marketplace} "
                                      "(Shopee 971, Magalu 983) antes do romaneio. A API não troca a condição."}
    if any(o["etapa"] == "romaneio" and o["situacao"] == "ok" for o in linx_operacoes_do_pedido(pedido)):
        return {"ok": False, "error": "O romaneio deste pedido já foi impresso pelo Noromak."}
    cadastro = _linx_cadastro_situacao(pedido)
    if not cadastro["feito"]:
        return {"ok": False, "error": "Atualize o cadastro do cliente no Linx antes do romaneio."}
    if cadastro["pela_api"] and not cadastro["credito_api"] and not credito_conferido:
        return {"ok": False, "error": "O crédito não foi confirmado pela API. Libere no Linx (Aprovado + "
                                      "Crédito normal + validade) e marque que conferiu."}
    try:
        lista = _linx_lista_romaneio(contato_num)
        itens = _linx_itens_resumo(lista)
        if not itens:
            return {"ok": False, "error": "Este atendimento não tem itens a separar — o romaneio pode já ter sido feito."}
        lista["Observacao"] = observacao
        atualizada = linx_chamar(
            "POST", f"{LINX_PATH_PECAS}/Pecas/ManutencaoRomaneio/PecRomaneio/AtualizaListaRomaneio/AtualizaQuantidades",
            {"Empresa": LINX_EMPRESA, "ListaRomaneio": lista, "ItensParaAjuste": []},
        )
        if isinstance(atualizada, dict) and isinstance(atualizada.get("ItensRomaneio"), list):
            lista = atualizada
            lista["Observacao"] = observacao
        status, resposta = linx_chamar_status(
            "POST", f"{LINX_PATH_PECAS}/Pecas/ManutencaoRomaneio/PecRomaneio/ConfirmaRomaneio",
            {"IdentificacaoAtendimento": _linx_identificacao(contato_num), "ListaRomaneio": lista},
        )
    except LinxErro as exc:
        _linx_registrar(str(exc))
        _linx_operacao_registrar(pedido, "romaneio", "erro", str(exc), contato_num, usuario)
        return {"ok": False, "error": str(exc)}
    if status == 208:
        pergunta = _linx_dialogo(resposta) or "A Linx pediu uma confirmação."
        _linx_operacao_registrar(pedido, "romaneio", "pergunta", resposta, contato_num, usuario)
        return {"ok": False, "situacao": "pergunta", "error": f"A Linx perguntou: {pergunta} Resolva no Linx; nada foi respondido."}
    _linx_operacao_registrar(pedido, "romaneio", "ok", {"observacao": observacao, "itens": itens, "resposta": resposta},
                             contato_num, usuario)
    audit(usuario, "linx.romaneio", f"{pedido}|{contato_num}|{observacao}")
    mensagens = [str(m) for m in resposta] if isinstance(resposta, list) else []
    return {"ok": True, "situacao": "impresso", "pedido": pedido, "contato": contato_num,
            "observacao": observacao, "itens": itens, "mensagens": mensagens}


# ---------------------------------------------------------------------------
# V19.30 — Romaneio, caixa e cadastro pelas PORTAS DA EXPEDIÇÃO do NoromakWeb
# (127.0.0.1:8000/api/v1/expedicao/*, X-Chave-Expedicao = CHAVE_CRM; contrato no
# /openapi.json dele). Testado de ponta a ponta em 15/10/2026 (787700, 787601).
# A Expedição nunca recebe credencial da Linx: quem fala com o Apollo é a porta.
# Regras que os testes ensinaram:
#   - caixa: o código do CLIENTE vai sempre (sem ele a UF vai vazia → Erro 2619);
#   - caixa: a condição de pagamento é escolhida no Apollo (sem ela, 412);
#   - cadastro: e-mail + telefone + celular juntos (sem telefone o Apollo
#     recusa com "falta o celular do cliente").
# O botão do romaneio/caixa fica ativo; o do cadastro só com EXP_CADASTRO_API=1
# (espera cliente/buscar, cliente/criar, nome e Endereço 1 na porta).
# ---------------------------------------------------------------------------
EXP_PORTA_BASE = os.getenv(
    "EXP_PORTA_BASE", re.sub(r"/custo/?$", "", CRM_COST_API_URL) or "http://127.0.0.1:8000/api/v1/expedicao"
).strip().rstrip("/")
EXP_PORTA_TIMEOUT = max(30, min(300, int(os.getenv("EXP_PORTA_TIMEOUT", "180") or 180)))
EXP_CADASTRO_API = os.getenv("EXP_CADASTRO_API", "1")  # V19.32: portas ligadas pelo Guilherme (15/10)
EXP_CADASTRO_API = EXP_CADASTRO_API.strip().lower() in {"1", "true", "sim"}
EXP_REVENDA = 1  # Araçatuba


def _exp_revenda_das_linhas(linhas: list[dict[str, Any]]) -> int:
    """V20.33 (dono, 06/11): o pedido usa a revenda do Apollo em que o atendimento dele está (Bauru = 3).
    revisar-antes-de-subir (06/11): pela CONTA que vendeu, não pela filial que confere (o "Mover de filial" muda o
    `Casa`, e o atendimento continua onde a integração criou): ML = `ContaMercadoLivre` (`ml_casa_da_linha`);
    TikTok = Bauru; Shopee/Magalu = Araçatuba (as contas são de lá); o resto (manual) = a filial da linha.
    Sem linha = Araçatuba (como sempre foi)."""
    for row in linhas or []:
        if not isinstance(row, dict):
            continue
        mp = normalize(_vendas_marketplace(row.get("Marketplace") or row.get("Origem")))
        if "TIKTOK" in mp:
            return SEPARACAO_REVENDA[TIKTOK_CASA]
        if mp == normalize("Mercado Livre"):
            return SEPARACAO_REVENDA.get(ml_casa_da_linha(row), EXP_REVENDA)
        if mp in (normalize("Shopee"), normalize("Magalu")):
            return EXP_REVENDA
        return SEPARACAO_REVENDA.get(filial_da_linha(row), EXP_REVENDA)
    return EXP_REVENDA


def _exp_revenda(pedido: str) -> int:
    """Leve: a fila; fora dela, só a conclusão DESTE pedido (nunca varre completed_orders)."""
    chave = str(pedido or "").strip()
    alvo = normalize(chave)
    # revisar-antes-de-subir (06/11): a leitura guardada da fila (V20.04, pela versão), não a fila remontada a cada etapa
    linhas = [r for r in _ml_fila_leitura() if isinstance(r, dict) and normalize(order_number(r)) == alvo]
    with DB_LOCK:
        if not linhas and alvo:
            row = DB.execute("SELECT payload FROM completed_orders WHERE order_key IN (?,?) LIMIT 1",
                             (chave, alvo)).fetchone()
            try:
                payload = json.loads(str(row["payload"] or "[]")) if row else []
            except (TypeError, ValueError):
                payload = []
            linhas = [r for r in (payload if isinstance(payload, list) else [payload]) if isinstance(r, dict)]
    return _exp_revenda_das_linhas(linhas)
EXP_MAX_ATENDIMENTOS = 4  # cada um custa uma prévia (teto da porta: 12 leituras/min)
EXP_PORTA_LOCK = threading.Lock()  # uma escrita por vez (a porta devolve 409 se repetir)
EXP_CLIQUE_ESPERA_S = 40  # revisar-antes-de-subir (06/11): clique espera a vez da porta no máximo isto (nginx corta em 60)


class _ExpVezDaPorta:
    """A vez da porta (EXP_PORTA_LOCK) com espera limitada: `espera` None = espera o quanto for."""

    def __init__(self, espera: float | None):
        self.ok = EXP_PORTA_LOCK.acquire() if espera is None else EXP_PORTA_LOCK.acquire(timeout=espera)

    def __enter__(self) -> "_ExpVezDaPorta":
        return self

    def __exit__(self, *exc: Any) -> None:
        if self.ok:
            EXP_PORTA_LOCK.release()
            self.ok = False


class PortaErro(Exception):
    """A porta respondeu com erro (ou não respondeu). `incerto` = a chamada saiu e a
    resposta não voltou: conferir no Apollo antes de repetir."""

    def __init__(self, mensagem: str, incerto: bool = False, passageiro: bool = False):
        super().__init__(mensagem)
        self.incerto = incerto
        # V20.12: limite por minuto (429) ou leitura sem resposta — passa sozinho, tentar de novo.
        self.passageiro = passageiro


# V19.72: aviso do Guilherme (22/10) — cadastro que vai ao Apollo não pode ter acento,
# ç nem caractere especial (travessão, aspas curvas, º/ª). A porta também limpa, mas o
# filtro fica aqui, antes de qualquer cliente/criar, cliente/atualizar e cliente/credito.
EXP_ROTAS_SEM_ACENTO = ("cliente/criar", "cliente/atualizar", "cliente/credito")
EXP_TROCA_ESPECIAIS = str.maketrans({"–": "-", "—": "-", "‒": "-", "―": "-", "“": "", "”": "",
                                     "„": "", "‘": "", "’": "", "‚": "", "´": "", "`": "", "«": "", "»": ""})


def _exp_texto_sem_acento(texto: str) -> str:
    base = unicodedata.normalize("NFKD", texto.translate(EXP_TROCA_ESPECIAIS))
    base = base.encode("ascii", "ignore").decode("ascii")
    return re.sub(r"\s+", " ", base).strip()


def _exp_corpo_sem_acento(rota: str, corpo: Any) -> Any:
    if rota not in EXP_ROTAS_SEM_ACENTO:
        return corpo
    if isinstance(corpo, dict):
        return {k: (v if k == "email" else _exp_corpo_sem_acento(rota, v)) for k, v in corpo.items()}
    if isinstance(corpo, list):
        return [_exp_corpo_sem_acento(rota, v) for v in corpo]
    return _exp_texto_sem_acento(corpo) if isinstance(corpo, str) else corpo


def _exp_porta(rota: str, corpo: dict[str, Any], *, escrita: bool = False) -> dict[str, Any]:
    if not CHAVE_CRM:
        raise PortaErro("CHAVE_CRM não está configurada no servidor.")
    corpo = _exp_corpo_sem_acento(rota, corpo)
    req = urllib.request.Request(
        f"{EXP_PORTA_BASE}/{rota}", data=json.dumps(corpo).encode("utf-8"), method="POST",
        headers={"X-Chave-Expedicao": CHAVE_CRM, "Content-Type": "application/json",
                 "Accept": "application/json", "User-Agent": f"NoromakExpedicao/{APP_VERSION}"},
    )
    return _exp_porta_resposta(req, escrita)


def _exp_porta_get(rota: str, params: dict[str, Any]) -> dict[str, Any]:
    """V20.00: leitura por GET (a porta /demanda). Mesmas mensagens de erro do POST."""
    if not CHAVE_CRM:
        raise PortaErro("CHAVE_CRM não está configurada no servidor.")
    req = urllib.request.Request(
        f"{EXP_PORTA_BASE}/{rota}?{urlencode(params)}", method="GET",
        headers={"X-Chave-Expedicao": CHAVE_CRM, "Accept": "application/json",
                 "User-Agent": f"NoromakExpedicao/{APP_VERSION}"},
    )
    return _exp_porta_resposta(req, False)


def _exp_porta_resposta(req: urllib.request.Request, escrita: bool, timeout: float | None = None) -> dict[str, Any]:
    try:  # V20.42: `timeout` opcional (o lote do estoque espera menos); o padrao nao mudou
        with urllib.request.urlopen(req, timeout=timeout or EXP_PORTA_TIMEOUT) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as exc:
        texto = exc.read().decode("utf-8", errors="replace")[:600]
        if exc.code == 404:
            raise PortaErro("A porta do Apollo para esta etapa ainda não está liberada (404).") from exc
        if exc.code == 401:
            raise PortaErro("A porta do Apollo recusou a chave de serviço (401).") from exc
        if exc.code == 409:
            raise PortaErro("Este cliente/atendimento já está sendo mexido agora. Espere e atualize.") from exc
        if exc.code == 429:
            raise PortaErro("Muitas chamadas ao Apollo neste minuto. Espere um minuto e tente de novo.",
                            passageiro=True) from exc
        raise PortaErro(f"A porta do Apollo respondeu HTTP {exc.code}: {texto}") from exc
    except Exception as exc:  # timeout, conexão caída
        if escrita:
            raise PortaErro("A chamada saiu e a resposta não voltou. Confira no Apollo antes de repetir.",
                            incerto=True) from exc
        raise PortaErro(f"O Apollo não respondeu: {exc}", passageiro=True) from exc
    try:
        dados = json.loads(raw or "{}")
    except Exception:
        raise PortaErro(f"Resposta inválida da porta: {raw[:200]}", incerto=escrita)
    return dados if isinstance(dados, dict) else {}


def _exp_cliente_do_pedido(pedido: str) -> dict[str, str]:
    """Código no Apollo + CPF/CNPJ + nome da NF-e que o Noromak já conhece."""
    guardado = _cliente_fiscal_guardado(pedido) or {}
    documento = re.sub(r"\D", "", str(guardado.get("documento_numero") or ""))
    codigo = re.sub(r"\D", "", str(guardado.get("linx_cliente") or ""))
    if not codigo and guardado.get("linx_api_status") == "encontrado" \
            and guardado.get("linx_api_documento") == guardado.get("documento_numero"):
        codigo = re.sub(r"\D", "", str(guardado.get("linx_api_cliente") or ""))
    return {"codigo": codigo, "documento": documento, "nome_fiscal": str(guardado.get("nome_fiscal") or "")}


def _exp_estado_operacoes(pedido: str) -> dict[str, Any]:
    ops = linx_operacoes_do_pedido(pedido)
    rom = next((o for o in reversed(ops) if o["etapa"] == "romaneio" and o["situacao"] == "ok"), None)
    caixa = [o for o in ops if o["etapa"] == "caixa"]
    caixa_ok = next((o for o in reversed(caixa) if o["situacao"] == "ok"), None)
    ultima_caixa = caixa[-1] if caixa else None
    travado = bool(ultima_caixa and ultima_caixa["situacao"] in ("pergunta", "incerto"))
    return {"operacoes": ops, "romaneio": rom, "caixa": caixa_ok, "caixa_ultima": ultima_caixa,
            "caixa_travado": travado and not caixa_ok}


def _exp_norm_codigo(texto: Any) -> str:
    return re.sub(r"[^0-9A-Z]", "", str(texto or "").upper())


def _exp_componentes_do_pedido(linhas: list[dict[str, Any]]) -> dict[str, str]:
    """V19.37: peças que o pedido precisa no atendimento {código normalizado: como aparece}.
    Kit "A/B" = cada peça; "KIT-" sai; "151490-0893270212" (anúncio-código do ML) = o código.
    Caso real 15/10, Shopee 261015P6NPQQHV: SKU 0893600022/0893764272 e o atendimento só
    tinha o 0893764272 — antes "1 peça bate" já escolhia e soltava o romaneio incompleto."""
    saida: dict[str, str] = {}
    for row in linhas:
        sku = str(row.get("SKU") or row.get("Sku") or "").strip().upper()
        for parte in sku.split("/"):
            parte = re.sub(r"^KIT\d*-", "", parte.strip())
            if re.match(r"^\d{5,}-.+", parte):
                parte = parte.split("-", 1)[1]
            chave = _exp_norm_codigo(parte)
            if chave:
                saida.setdefault(chave, parte)
    return saida


def _exp_codigos_inteiros(linhas: list[dict[str, Any]]) -> dict[str, list[str]]:
    """V19.48: SKU com barra pode ser UM produto ("PSH367/80"), não um kit "A/B".
    {código inteiro normalizado: peças em que ele foi quebrado}. Se o código inteiro está
    no atendimento, as peças dele não faltam (pedido real 2000019012332882, 16/10)."""
    saida: dict[str, list[str]] = {}
    for row in linhas:
        sku = re.sub(r"^KIT\d*-", "", str(row.get("SKU") or row.get("Sku") or "").strip().upper())
        if "/" not in sku:
            continue
        if re.match(r"^\d{5,}-.+", sku):
            sku = sku.split("-", 1)[1]
        partes = [_exp_norm_codigo(re.sub(r"^KIT\d*-", "", p.strip())) for p in sku.split("/")]
        saida[_exp_norm_codigo(sku)] = [p for p in partes if p]
    return saida


# V19.67: o painel do romaneio demorava 4–7 s em "Carregando…" (21/10): 3 a 6 consultas à
# porta, uma depois da outra, ~1 s cada. Agora: o nome do cliente no Apollo (filtro dos
# atendimentos) fica guardado por código, e a situação do cliente e a lista de atendimentos
# saem JUNTAS; as prévias dos atendimentos também saem juntas. Mesmo número de consultas
# (o teto da porta é por minuto). Se o nome mudou no Apollo, a lista é refeita com o novo.
_EXP_NOME_APOLLO: dict[str, str] = {}


def _exp_em_paralelo(tarefas: list[Any]) -> list[Any]:
    """Roda as funções juntas e devolve os resultados na ordem (o erro sobe como antes)."""
    if len(tarefas) <= 1:
        return [t() for t in tarefas]
    with ThreadPoolExecutor(max_workers=len(tarefas)) as ex:
        futuros = [ex.submit(t) for t in tarefas]
        return [f.result() for f in futuros]


def _exp_nome_abreviado(nome: Any) -> bool:
    """V20.09: sobrenome de uma letra no fim ("NAYARA C"). "MARIA E SILVA" não é abreviado.
    V20.10: uma palavra só ("JEOACAZ") também não identifica a pessoa."""
    limpo = _exp_limpo(nome)
    if len(limpo.split()) == 1:   # pelos espaços: "ANA-PAULA" é uma palavra só
        return True
    palavras = re.findall(r"[A-Z]+", limpo)
    return len(palavras) >= 2 and len(palavras[-1]) == 1


def _exp_nome_encurta(novo: Any, atual: Any) -> bool:
    """V20.09: "NAYARA C" por cima de "NAYARA CRISTINA SOUZA" só perderia o nome completo."""
    n, a = re.findall(r"[A-Z]+", _exp_limpo(novo)), re.findall(r"[A-Z]+", _exp_limpo(atual))
    if not _exp_nome_abreviado(novo) or len(a) < 2:
        return False
    # V20.10: uma palavra nunca troca nome de duas ou mais; o campo da Shopee é o destinatário ("Portaria").
    if len(_exp_limpo(novo).split()) == 1:
        return True
    if n[0] != a[0] or not set(n[:-1]) <= set(a):
        return False
    return any(len(p) > 1 and p[0] == n[-1] for p in a[1:])


def exp_romaneio_preparar(pedido: str, atendimento: Any = "", cliente: Any = "") -> dict[str, Any]:
    """Mostra o que o botão do romaneio faria. Só leitura no Apollo."""
    pedido = str(pedido or "").strip()
    if not pedido:
        return {"ok": False, "error": "Informe o pedido."}
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
    marketplace = _vendas_marketplace(linhas[0].get("Marketplace") or linhas[0].get("Origem")) if linhas else ""
    revenda = _exp_revenda_das_linhas(linhas)  # V20.33: Bauru = revenda 3
    conhecido = _exp_cliente_do_pedido(pedido)
    codigo = re.sub(r"\D", "", str(cliente or "")) or conhecido["codigo"]
    numero = re.sub(r"\D", "", str(atendimento or ""))
    saida: dict[str, Any] = {
        "ok": True, "pedido": pedido, "marketplace": marketplace, "no_noromak": bool(linhas),
        "cliente": {"codigo": codigo, "documento": conhecido["documento"], "nome_fiscal": conhecido["nome_fiscal"],
                    "nome_apollo": ""},
        "revenda": revenda,
        "atendimento_tiktok": tiktok_atendimento_do_pedido(pedido),  # V20.33
        "precisa_condicao": True, "candidatos": [], "escolhido": "", "nome_abreviado": False,
        **_exp_estado_operacoes(pedido),
        "cadastro_auto": cadastro_auto_do_pedido(pedido),  # V19.41
        # V20.00: a extensão compara com o atendimento ("≠"); sem isto o romaneio era solto sem ver
        # a diferença e a correção do valor (Faturamento, V19.99) só vale antes de soltar. Sem venda = None.
        "valor_pedido": _exp_valor_pedido(pedido),
    }
    try:
        filtro: dict[str, Any] = {}
        # V19.32: sem o código mas com o CPF/CNPJ, o cliente/buscar dá o código exato
        # (o nome da NF-e vira só reserva). Achado, fica guardado no pedido.
        if not numero and not codigo and conhecido["documento"]:
            try:
                b = exp_buscar_cliente(conhecido["documento"], revenda=revenda)
            except PortaErro:
                b = {"situacao": ""}
            if b["situacao"] == "encontrado" and b["cliente"]:
                codigo = b["cliente"]
                saida["cliente"]["codigo"] = codigo
                salvar_cliente_fiscal(pedido, conhecido["documento"], conhecido["nome_fiscal"],
                                      linx_cliente=codigo, fonte="porta-buscar", usuario="noromak")
            elif b["situacao"] == "nao_cadastrado":
                saida["cliente"]["nao_cadastrado"] = True
        if numero:
            filtro = {"atendimento": int(numero)}
        elif codigo and conhecido["documento"]:
            def _situacao() -> dict[str, Any]:
                return _exp_porta("cliente/situacao", {"revenda": revenda, "cliente": int(codigo),
                                                       "documento": conhecido["documento"], "operador": "noromak"})

            def _abertos(nome: str) -> dict[str, Any]:
                return _exp_porta("atendimentos/abertos", {"revenda": revenda, "dias": 90,
                                                           "operador": "noromak", "cliente_nome": nome})
            nome_guardado = _EXP_NOME_APOLLO.get(codigo, "")
            if nome_guardado:   # V19.67: situação e atendimentos juntos
                sit, abertos_cedo = _exp_em_paralelo([_situacao, lambda: _abertos(nome_guardado)])
            else:
                sit, abertos_cedo = _situacao(), None
            if not sit.get("ok"):
                return {**saida, "situacao": "cliente", "aviso": sit.get("erro") or "O Apollo não confirmou o cliente."}
            saida["cliente"]["nome_apollo"] = str(sit.get("nome") or "")
            if saida["cliente"]["nome_apollo"]:
                _EXP_NOME_APOLLO[codigo] = saida["cliente"]["nome_apollo"]
            saida["credito"] = {"veredito": sit.get("veredito"), "situacao": sit.get("situacao_credito"),
                                "cadastro": sit.get("cadastro"), "motivos": sit.get("motivos") or []}
            filtro = {"cliente_nome": saida["cliente"]["nome_apollo"]}
            if abertos_cedo is not None and nome_guardado == saida["cliente"]["nome_apollo"]:
                abertos, filtro = abertos_cedo, {}
        else:
            # V19.31: sem o código, busca pelo NOME DA NF-e (a porta ignora acento e
            # caixa e exige todas as palavras); não achando, primeiro + último nome
            # ("MARCIO COSTA DE ARAUJO" → "MARCIO ARAUJO"). Pode trazer homônimo: só
            # escolhe sozinho com peças batendo. Exato só com cliente/buscar (CPF).
            palavras = re.sub(r"[^A-Z ]", " ", unicodedata.normalize("NFKD", conhecido["nome_fiscal"])
                              .encode("ascii", "ignore").decode().upper()).split()
            tentativas = [" ".join(palavras)] if len(palavras) >= 2 else []
            if len(palavras) > 2:
                tentativas.append(f"{palavras[0]} {palavras[-1]}")
            if not tentativas:
                return {**saida, "situacao": "informar_atendimento",
                        "aviso": "Sem o código do cliente nem o nome da NF-e. Informe o número do atendimento."}
            abertos = {}
            for nome_busca in tentativas:
                abertos = _exp_porta("atendimentos/abertos", {"revenda": revenda, "dias": 90,
                                                              "operador": "noromak", "cliente_nome": nome_busca})
                if abertos.get("ok") and abertos.get("atendimentos"):
                    saida["busca_por_nome"] = nome_busca
                    break
            filtro = {}
        if filtro:
            abertos = _exp_porta("atendimentos/abertos", {"revenda": revenda, "dias": 90, "operador": "noromak", **filtro})
        if not abertos.get("ok"):
            return {**saida, "situacao": "erro", "aviso": abertos.get("erro") or "O Apollo não listou os atendimentos."}
        codigos = _linx_codigos_do_pedido(linhas)
        componentes = _exp_componentes_do_pedido(linhas)
        # V19.46: código com hífen (Schulz "816.3279-0") — o SKU inteiro do anúncio também
        # vale, senão "124656-816.3279-0" virava "8163279"+"0" e nunca batia.
        codigos = codigos | set(componentes)
        inteiros = _exp_codigos_inteiros(linhas)                # V19.48
        codigos = codigos | set(inteiros)
        lista = (abertos.get("atendimentos") or [])[:EXP_MAX_ATENDIMENTOS]
        previas = _exp_em_paralelo([  # V19.67: prévias juntas
            (lambda n=int(a["atendimento"]): _exp_porta("romaneio/previa", {"revenda": revenda, "atendimento": n,
                                                                            "operador": "noromak"}))
            for a in lista])
        for a, prev in zip(lista, previas):
            itens = [{"codigo": str(i.get("codigo") or ""), "descricao": str(i.get("descricao") or ""),
                      "quantidade": i.get("requisitada"), "a_soltar": i.get("a_soltar")}
                     for i in (prev.get("itens") or []) if isinstance(i, dict)]
            bate = sum(1 for i in itens if re.sub(r"[^0-9A-Z]", "", i["codigo"].upper()) in codigos)
            no_atendimento = {_exp_norm_codigo(i["codigo"]) for i in itens}
            # V19.48: código com barra presente inteiro no atendimento cobre as "peças" dele.
            for inteiro, partes in inteiros.items():
                if inteiro in no_atendimento:
                    no_atendimento.update(partes)
            faltam = [orig for chave, orig in componentes.items() if chave not in no_atendimento]
            saida["candidatos"].append({
                "atendimento": str(a.get("atendimento")), "cliente": a.get("cliente"), "valor": a.get("valor"),
                "aberto_em": a.get("aberto_em"), "vendedor": (a.get("vendedor") or {}).get("nome"),
                "itens": itens, "total_a_soltar": prev.get("total_a_soltar") or 0, "bate": bate,
                "faltam": faltam,
            })
    except PortaErro as exc:
        return {**saida, "situacao": "erro", "aviso": str(exc), "apollo_ocupado": exc.passageiro}
    soltar = [c for c in saida["candidatos"] if c["total_a_soltar"]]
    # V19.30 (decisão do dono): escolhe sozinho só um atendimento, com peças batendo
    # (ou o número digitado); senão quem escolhe é a pessoa.
    # V20.09: a busca é pelo nome; com sobrenome de uma letra pode vir outra pessoa, a pessoa confere.
    # V20.10: só CPF; razão social ("ACME", "... S/A") não é nome abreviado.
    saida["nome_abreviado"] = len(conhecido["documento"]) == 11 and _exp_nome_abreviado(
        saida["cliente"]["nome_apollo"] or conhecido["nome_fiscal"])
    if numero and soltar:
        saida["escolhido"] = soltar[0]["atendimento"]
    elif (len(soltar) == 1 and (soltar[0]["bate"] or not codigos) and not soltar[0]["faltam"]
          and not saida["nome_abreviado"]):
        saida["escolhido"] = soltar[0]["atendimento"]
    if not saida["candidatos"]:
        return {**saida, "situacao": "sem_atendimento", "aviso": "Nenhum atendimento aberto para este cliente no Apollo."}
    # V19.38: romaneio já solto por fora do botão (no Apollo): o atendimento tem as peças
    # do pedido mas nada a soltar. Antes caía em "peças que não batem" e travava o caixa
    # (caso real 15/10, Shopee 261015M126M9WD, atendimento 787596).
    if not soltar and not saida["romaneio"]:
        prontos = [c for c in saida["candidatos"] if (c["bate"] or not codigos) and not c["faltam"]]
        if len(prontos) == 1:
            saida["romaneio_fora"] = prontos[0]["atendimento"]
            return {**saida, "situacao": "romaneio_fora"}
    return {**saida, "situacao": "pronto" if saida["escolhido"] else "escolher"}


def exp_romaneio_soltar(pedido: str, atendimento: Any, observacao: str, usuario: str) -> dict[str, Any]:
    pedido = str(pedido or "").strip()
    observacao = re.sub(r"\s+", " ", str(observacao or "")).strip().upper()
    numero = re.sub(r"\D", "", str(atendimento or ""))
    if not pedido or not numero:
        return {"ok": False, "error": "Informe o pedido e o atendimento."}
    if not observacao or len(observacao) > 100:
        return {"ok": False, "error": "Escreva a observação do romaneio (até 100 caracteres)."}
    if _exp_estado_operacoes(pedido)["romaneio"]:
        return {"ok": False, "error": "O romaneio deste pedido já foi solto pelo Noromak."}
    revenda = _exp_revenda(pedido)  # V20.33: fora da vez da porta
    # revisar-antes-de-subir (06/11): o clique não espera a rotina do TikTok (ou outra escrita longa) além do nginx
    # (60 s = 504 e a thread soltava depois, sem a tela saber); e confere de novo, já na vez, que ninguém soltou.
    if not EXP_PORTA_LOCK.acquire(timeout=EXP_CLIQUE_ESPERA_S):
        return {"ok": False, "situacao": "ocupado",
                "error": "O Apollo está ocupado com outra gravação agora. Espere alguns segundos e tente de novo."}
    try:
        if _exp_estado_operacoes(pedido)["romaneio"]:
            return {"ok": False, "error": "O romaneio deste pedido já foi solto pelo Noromak."}
        try:
            r = _exp_porta("romaneio/soltar", {"revenda": revenda, "atendimento": int(numero),
                                                "operador": usuario[:60] or "noromak", "observacao": observacao},
                           escrita=True)
        except PortaErro as exc:
            _linx_operacao_registrar(pedido, "romaneio", "incerto" if exc.incerto else "erro", str(exc), numero, usuario)
            return {"ok": False, "situacao": "incerto" if exc.incerto else "erro", "error": str(exc)}
        if not r.get("ok") or r.get("situacao") != "solto":
            motivo = r.get("erro") or r.get("mensagem") or json_dumps(r)[:300]
            _linx_operacao_registrar(pedido, "romaneio", "erro", motivo, numero, usuario)
            return {"ok": False, "situacao": r.get("situacao") or "erro", "error": motivo}
        mensagens = [str(m) for m in (r.get("mensagens") or [])]
        _linx_operacao_registrar(pedido, "romaneio", "ok", {"observacao": observacao, "soltos": r.get("soltos"),
                                                           "mensagens": mensagens, "via": "porta",
                                                           "revenda": revenda}, numero, usuario)  # V20.33
    finally:
        EXP_PORTA_LOCK.release()
    audit(usuario, "expedicao.romaneio", f"{pedido}|{numero}|{observacao}")
    return {"ok": True, "situacao": "solto", "pedido": pedido, "atendimento": numero,
            "observacao": observacao, "soltos": r.get("soltos") or [], "mensagens": mensagens}


def romaneio_do_pedido(pedido: str) -> dict[str, Any]:
    """V19.87: o romaneio solto pela porta, para a Conferência reemitir (extensão
    NOROMAK_REEMISSAO_ROMANEIO, no Linx web). O número vem da mensagem do Apollo
    ("Romaneio 125245 do contato ..."). Só lê o banco."""
    estado = _exp_estado_operacoes(pedido)
    rom = estado["romaneio"]
    if not rom:
        romaneios = [o for o in estado["operacoes"] if o["etapa"] == "romaneio"]
        return {"ok": True, "solto": False, "pedido": pedido,
                "ultima_situacao": romaneios[-1]["situacao"] if romaneios else ""}
    try:
        detalhe = json.loads(rom["detalhe"] or "{}")
    except (TypeError, ValueError):
        detalhe = {}
    if not isinstance(detalhe, dict):
        detalhe = {}
    # Revisão 27/10: o mesmo soltar pode gerar mais de um romaneio (um por departamento).
    romaneios: list[str] = []
    for numero in re.findall(r"Romaneio\s+(\d+)", " ".join(str(m) for m in (detalhe.get("mensagens") or []))):
        if numero not in romaneios:
            romaneios.append(numero)
    pecas = [{"codigo": str(p.get("codigo") or ""), "quantidade": p.get("quantidade")}
             for p in (detalhe.get("soltos") or []) if isinstance(p, dict)]
    # Sem o login de quem soltou (a tela não usa).
    return {"ok": True, "solto": True, "pedido": pedido, "romaneios": romaneios,
            "romaneio": romaneios[0] if len(romaneios) == 1 else "",
            # V20.33: a revenda em que o romaneio saiu (gravada ao soltar; sem ela, Araçatuba). Sem reler a fila:
            # esta rota roda a cada pedido aberto na Conferência.
            "atendimento": str(rom["contato"] or ""), "revenda": int(detalhe.get("revenda") or EXP_REVENDA),
            "observacao": str(detalhe.get("observacao") or ""), "pecas": pecas, "em": rom["em"]}


def _pedido_filial_e_fila(pedido: str, filial: str) -> tuple[bool, bool]:
    """V19.87: (pode ver, está na fila) com UMA leitura de conf_pedidos — roda a cada pedido
    aberto na Conferência, sob o DB_LOCK. Mesma regra do `pedido_da_filial`; fora da fila só
    quem vê todas as filiais lê (não dá para saber de quem é). Chamar sob o DB_LOCK."""
    if filial == FILIAL_TODAS:
        return True, True
    numero = normalize(pedido)
    bruto, _, _ = get_storage("conf_pedidos")
    achou = False
    for row in _rows_from_storage_value(bruto):
        if isinstance(row, dict) and numero in {normalize(order_number(row)), normalize(row.get("VendaMercadoLivre")),
                                                normalize(row.get("PackIdMercadoLivre"))}:
            achou = True
            if filial_da_linha(row) == filial:
                return True, True
    return not achou, achou


def _exp_caixa_corpo(pedido: str, atendimento: Any, cliente: Any) -> tuple[dict[str, Any] | None, str]:
    numero = re.sub(r"\D", "", str(atendimento or ""))
    estado = _exp_estado_operacoes(pedido)
    if not numero:
        numero = str((estado["romaneio"] or {}).get("contato") or "")
    codigo = re.sub(r"\D", "", str(cliente or "")) or _exp_cliente_do_pedido(pedido)["codigo"]
    if not numero:
        return None, "Solte o romaneio primeiro (ou informe o atendimento)."
    if not codigo:
        return None, "Informe o código do cliente no Apollo: sem ele o caixa não acha a UF (Erro 2619)."
    # revisar-antes-de-subir (06/11): o caixa vai na revenda em que o romaneio saiu (gravada ao soltar); sem ela, a do pedido.
    revenda = _exp_revenda(pedido)
    try:
        rom_det = json.loads((estado["romaneio"] or {}).get("detalhe") or "{}")
        if isinstance(rom_det, dict) and int(rom_det.get("revenda") or 0) in SEPARACAO_REVENDA.values():
            revenda = int(rom_det["revenda"])
    except (TypeError, ValueError):
        pass
    return {"revenda": revenda, "atendimento": int(numero), "cliente": int(codigo)}, ""


def exp_caixa_previa(pedido: str, atendimento: Any, cliente: Any, usuario: str) -> dict[str, Any]:
    pedido = str(pedido or "").strip()
    corpo, erro = _exp_caixa_corpo(pedido, atendimento, cliente)
    if not corpo:
        return {"ok": False, "error": erro}
    try:
        r = _exp_porta("caixa/previa", {**corpo, "operador": usuario[:60] or "noromak", "validar": True})
    except PortaErro as exc:
        return {"ok": False, "error": str(exc)}
    val = r.get("validacoes") or {}
    falhas = [f"{k}: {(val.get(k) or {}).get('texto') or 'não passou'}" for k in ("validacoes", "ipi")
              if not (val.get(k) or {}).get("passou")]
    pode = bool(r.get("ok") and r.get("pode_enviar") and not r.get("impedimentos") and not falhas)
    return {"ok": bool(r.get("ok")), "pode": pode, "atendimento": str(corpo["atendimento"]),
            "cliente": str(corpo["cliente"]), "valor": r.get("valor"), "itens": r.get("itens") or [],
            "impedimentos": r.get("impedimentos") or [], "falhas": falhas, "error": r.get("erro") or ""}


def exp_caixa_enviar(pedido: str, atendimento: Any, cliente: Any, valor_visto: Any, usuario: str,
                     conferido: bool = False) -> dict[str, Any]:
    pedido = str(pedido or "").strip()
    estado = _exp_estado_operacoes(pedido)
    if estado["caixa"]:
        return {"ok": False, "error": "Este pedido já foi enviado ao caixa pelo Noromak."}
    if estado["caixa_travado"] and not conferido:
        return {"ok": False, "situacao": "travado",
                "error": "A última tentativa ficou sem resposta certa. Confira no Apollo e marque que conferiu."}
    corpo, erro = _exp_caixa_corpo(pedido, atendimento, cliente)
    if not corpo:
        return {"ok": False, "error": erro}
    try:
        valor = round(float(valor_visto), 2)
    except (TypeError, ValueError):
        return {"ok": False, "error": "Rode a prévia do caixa antes de enviar (valor visto)."}
    if valor <= 0:
        return {"ok": False, "error": "Valor do atendimento inválido."}
    numero = corpo["atendimento"]
    # revisar-antes-de-subir (06/11): espera a vez da porta só até EXP_CLIQUE_ESPERA_S (nginx = 60 s) e confere de
    # novo, já na vez, que nenhum outro clique enviou; o registro também fica dentro da vez.
    if not EXP_PORTA_LOCK.acquire(timeout=EXP_CLIQUE_ESPERA_S):
        return {"ok": False, "situacao": "ocupado",
                "error": "O Apollo está ocupado com outra gravação agora. Espere alguns segundos e tente de novo."}
    try:
        estado = _exp_estado_operacoes(pedido)
        if estado["caixa"]:
            return {"ok": False, "error": "Este pedido já foi enviado ao caixa pelo Noromak."}
        if estado["caixa_travado"] and not conferido:
            return {"ok": False, "situacao": "travado",
                    "error": "A última tentativa ficou sem resposta certa. Confira no Apollo e marque que conferiu."}
        try:
            r = _exp_porta("caixa/enviar", {**corpo, "operador": usuario[:60] or "noromak", "valor_visto": valor},
                           escrita=True)
        except PortaErro as exc:
            _linx_operacao_registrar(pedido, "caixa", "incerto" if exc.incerto else "erro", str(exc), numero, usuario)
            return {"ok": False, "situacao": "incerto" if exc.incerto else "erro", "error": str(exc)}
        situacao = str(r.get("situacao") or "")
        texto = str(r.get("erro") or r.get("mensagem_do_erp") or r.get("mensagem") or "")
        if situacao == "enviado":
            _linx_operacao_registrar(pedido, "caixa", "ok", f"valor {valor} {texto}".strip(), numero, usuario)
        else:
            marca = situacao if situacao in ("pergunta", "incerto") else "erro"
            if "412" in texto or "forma(s) de pagamento" in texto.lower():
                texto = "Escolha a condição de pagamento do atendimento no Apollo e clique de novo. " + texto
            _linx_operacao_registrar(pedido, "caixa", marca, texto or json_dumps(r)[:300], numero, usuario)
    finally:
        EXP_PORTA_LOCK.release()
    if situacao == "enviado":
        audit(usuario, "expedicao.caixa", f"{pedido}|{numero}|{valor}")
        return {"ok": True, "situacao": "enviado", "atendimento": str(numero), "valor": valor, "mensagem": texto}
    return {"ok": False, "situacao": situacao or "erro", "error": texto or "O Apollo não confirmou o envio."}


# V19.32: celular padrão do cadastro. O cliente/criar só aceita celular de 9 dígitos
# começando com 9 (o 111111111 de antes é recusado); o mesmo número vale para todos.
EXP_CELULAR_PADRAO = int(os.getenv("EXP_CELULAR_PADRAO", "999999999") or 999999999)


def _exp_limpo(texto: Any) -> str:
    base = unicodedata.normalize("NFKD", str(texto or "")).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", base).strip().upper()


def exp_buscar_cliente(documento: str, operador: str = "noromak", revenda: int = EXP_REVENDA) -> dict[str, Any]:
    """cliente/buscar pelo CPF/CNPJ: {situacao: encontrado|nao_cadastrado|mais_de_um, cliente, nome, lista}.
    Pesquisa que falha volta ok:false (nunca vira "não cadastrado")."""
    b = _exp_porta("cliente/buscar", {"revenda": revenda, "documento": documento, "operador": operador[:60] or "noromak"})
    if not b.get("ok"):
        raise PortaErro(b.get("erro") or "O Apollo não respondeu a busca do cliente.")
    lista = next((v for v in b.values() if isinstance(v, list)), [])
    return {"situacao": str(b.get("situacao") or ""), "cliente": re.sub(r"\D", "", str(b.get("cliente") or "")),
            "nome": str(b.get("nome") or ""), "lista": lista}


EXP_BAIRRO_PADRAO_SHOPEE = "CENTRO"
EXP_UF_POR_NOME = {
    "ACRE": "AC", "ALAGOAS": "AL", "AMAPA": "AP", "AMAZONAS": "AM", "BAHIA": "BA", "CEARA": "CE",
    "DISTRITO FEDERAL": "DF", "ESPIRITO SANTO": "ES", "GOIAS": "GO", "MARANHAO": "MA", "MATO GROSSO": "MT",
    "MATO GROSSO DO SUL": "MS", "MINAS GERAIS": "MG", "PARA": "PA", "PARAIBA": "PB", "PARANA": "PR",
    "PERNAMBUCO": "PE", "PIAUI": "PI", "RIO DE JANEIRO": "RJ", "RIO GRANDE DO NORTE": "RN",
    "RIO GRANDE DO SUL": "RS", "RONDONIA": "RO", "RORAIMA": "RR", "SANTA CATARINA": "SC", "SAO PAULO": "SP",
    "SERGIPE": "SE", "TOCANTINS": "TO",
}


def _exp_endereco_shopee(order_sn: str) -> dict[str, Any]:
    """V19.35 (pedido do dono, 15/10): endereço da Shopee pela API (get_order_detail →
    recipient_address), sem acento como no ML. A página não mostra o bairro; a API traz
    em `district`. Texto mascarado ("****") conta como faltando — nunca vai ao Apollo."""
    detalhes = shopee_order_details([order_sn])
    pedido = detalhes[0] if detalhes else {}
    a = pedido.get("recipient_address") if isinstance(pedido.get("recipient_address"), dict) else {}
    real = lambda v: "" if "*" in str(v or "") else _exp_limpo(v)
    cidade, estado, bairro = real(a.get("city")), real(a.get("state")), real(a.get("district") or a.get("town"))
    # Decisão do dono (15/10): a Shopee não informa o bairro → padrão "CENTRO".
    bairro_padrao = not bairro
    bairro = bairro or EXP_BAIRRO_PADRAO_SHOPEE
    partes = [p.strip() for p in str(a.get("full_address") or "").split(",") if p.strip()]
    rua = real(partes[0]) if partes else ""
    numero = ""
    complemento = ""
    if len(partes) > 1 and re.fullmatch(r"\d+[A-Za-z]?|S/?N", partes[1].strip(), re.I):
        numero = "" if partes[1].strip().upper() in ("SN", "S/N") else partes[1].strip()
        resto = [real(p) for p in partes[2:]]
        # o que sobra até o bairro/cidade é complemento ("Casa", "Apartamento 202")
        for p in resto:
            if not p or p in (bairro, cidade, estado) or re.fullmatch(r"\d{5}-?\d{3}", p):
                break
            complemento = p
            break
    uf = estado if len(estado) == 2 else EXP_UF_POR_NOME.get(estado, "")
    endereco = {"rua": rua[:120], "numero": numero[:10], "complemento": complemento[:60], "bairro": bairro[:50],
                "cep": re.sub(r"\D", "", str(a.get("zipcode") or "")), "cidade": cidade[:50], "uf": uf}
    faltando = [k for k in ("rua", "bairro", "cep", "cidade", "uf") if not endereco[k]]
    if faltando:
        return {"endereco": None, "falta": "a Shopee não mandou " + ", ".join(faltando)}
    if not endereco["complemento"]:
        del endereco["complemento"]
    return {"endereco": endereco, "falta": "", "bairro_padrao": bairro_padrao}


def exp_endereco_do_texto(texto: Any, bairro: Any = "") -> dict[str, Any]:
    """V19.36: endereço como a página da Shopee mostra (a API devolve mascarado):
    "R Jesuíno Antônio, 342, Casa, Osasco, São Paulo, 06045080" → rua, número,
    complemento, cidade, estado e CEP (o fim é sempre cidade, estado, CEP). Sem
    bairro na página → CENTRO (decisão do dono). Sem acento, como no ML.
    V20.33: o TikTok traz o bairro (detalhe do pedido) e a extensão Linx 0.49 manda à parte;
    mascarado ou vazio = CENTRO, como antes."""
    texto = str(texto or "").strip()
    bairro_lido = "" if "*" in str(bairro or "") else _exp_limpo(bairro)[:50]
    if not texto or "*" in texto:
        return {"endereco": None, "falta": "a página não mostrou o endereço"}
    partes = [p.strip() for p in texto.split(",") if p.strip()]
    cep = re.sub(r"\D", "", partes[-1]) if partes else ""
    if len(partes) < 4 or len(cep) != 8:
        return {"endereco": None, "falta": "não entendi o endereço da página"}
    estado, cidade = _exp_limpo(partes[-2]), _exp_limpo(partes[-3])
    meio = partes[1:-3]
    numero = ""
    if meio and re.fullmatch(r"\d+[A-Za-z]?|S/?N", meio[0], re.I):
        numero = "" if meio[0].upper().replace("/", "") == "SN" else meio[0]
        meio = meio[1:]
    endereco = {"rua": _exp_limpo(partes[0])[:120], "numero": numero[:10],
                "complemento": _exp_limpo(", ".join(meio))[:60], "bairro": bairro_lido or EXP_BAIRRO_PADRAO_SHOPEE,
                "cep": cep, "cidade": cidade[:50],
                "uf": estado if len(estado) == 2 else EXP_UF_POR_NOME.get(estado, "")}
    if not (endereco["rua"] and endereco["cidade"] and endereco["uf"]):
        return {"endereco": None, "falta": "não entendi o endereço da página"}
    if not endereco["complemento"]:
        del endereco["complemento"]
    return {"endereco": endereco, "falta": "", "bairro_padrao": not bairro_lido}


def exp_endereco_entrega(pedido: str) -> dict[str, Any]:
    """V19.32 (decisão do dono): endereço do cadastro = Dados do envio da venda.
    Mercado Livre: /shipments/{id} com a conta do pedido. Devolve {endereco} só quando
    vem inteiro (rua, bairro, CEP, cidade, UF) — a porta é tudo ou nada; senão {falta}."""
    with DB_LOCK:
        linhas = _linhas_do_pedido(pedido)
    if not linhas:
        return {"endereco": None, "falta": "pedido não está no Noromak"}
    row = linhas[0]
    marketplace = _vendas_marketplace(row.get("Marketplace") or row.get("Origem"))
    if marketplace == "Shopee":
        return _exp_endereco_shopee(str(order_number(row) or pedido))
    if marketplace != "Mercado Livre":
        return {"endereco": None, "falta": f"endereço automático ainda não existe para {marketplace or 'este marketplace'}"}
    envio = re.sub(r"\D", "", str(row.get("ShipmentIdMercadoLivre") or ""))
    if not envio:
        return {"endereco": None, "falta": "pedido sem número de envio do ML"}
    with ml_na_casa(ml_casa_da_linha(row)):
        ship = ml_api_get(f"/shipments/{envio}")
    ship = ship if isinstance(ship, dict) else {}
    a = ship.get("receiver_address") if isinstance(ship.get("receiver_address"), dict) else {}
    if not a:
        dest = ship.get("destination") if isinstance(ship.get("destination"), dict) else {}
        a = dest.get("shipping_address") if isinstance(dest.get("shipping_address"), dict) else {}

    def nome_de(v: Any) -> Any:
        return (v.get("name") if isinstance(v, dict) else v) or ""

    estado = a.get("state")
    uf = str((estado.get("id") if isinstance(estado, dict) else estado) or "").split("-")[-1][:2]
    numero = str(a.get("street_number") or "").strip()
    endereco = {
        "rua": _exp_limpo(a.get("street_name"))[:120],
        "numero": "" if numero.upper() in ("SN", "S/N", "0") else numero[:10],
        "complemento": _exp_limpo(a.get("comment") or a.get("complement"))[:60],
        "bairro": _exp_limpo(nome_de(a.get("neighborhood")))[:50],
        "cep": re.sub(r"\D", "", str(a.get("zip_code") or "")),
        "cidade": _exp_limpo(nome_de(a.get("city")))[:50],
        "uf": uf.upper(),
    }
    faltando = [k for k in ("rua", "bairro", "cep", "cidade", "uf") if not endereco[k]]
    if faltando:
        return {"endereco": None, "falta": "o ML não mandou " + ", ".join(faltando)}
    if not endereco["complemento"]:
        del endereco["complemento"]
    return {"endereco": endereco, "falta": ""}


# V19.33: rótulos da tela do ML que já foram lidos como nome (CNPJ, 15/10: "TIPO DE CONTRIBUINTE").
EXP_NOME_ROTULO = re.compile(r"^(TIPO DE CONTRIBUINTE|NAO CONTRIBUINTE|CONTRIBUINTE|ISENTO|RAZAO SOCIAL|NOME COMPLETO"
                             r"|INSCRICAO ESTADUAL.*|DADOS D.*|OBSERVAC.*)$")


def exp_cadastro_atualizar(pedido: str, usuario: str, cliente: Any = "", ie: Any = "",
                           endereco_texto: Any = "", criar: bool = True, bairro: Any = "") -> dict[str, Any]:
    """Botão do cadastro pela porta (V19.32, contrato real do Guilherme de 15/10):
    buscar pelo CPF -> (não cadastrado) criar -> atualizar nome + contatos + endereço -> crédito.
    Ligado com EXP_CADASTRO_API=1."""
    if not EXP_CADASTRO_API:
        return {"ok": False, "situacao": "desligado",
                "error": "Cadastro pela API ainda desligado no servidor (EXP_CADASTRO_API)."}
    pedido = str(pedido or "").strip()
    conhecido = _exp_cliente_do_pedido(pedido)
    documento, nome = conhecido["documento"], conhecido["nome_fiscal"]
    if not documento:
        return {"ok": False, "error": "Este pedido ainda não tem CPF/CNPJ da nota. Puxe nome e CPF primeiro."}
    codigo = re.sub(r"\D", "", str(cliente or "")) or conhecido["codigo"]
    nome_limpo = _exp_limpo(nome)[:70]
    if nome_limpo and EXP_NOME_ROTULO.match(nome_limpo):
        return {"ok": False, "situacao": "nome_invalido",
                "error": f'O nome lido da NF-e ("{nome_limpo}") é um rótulo da tela, não o nome. Leia de novo na venda.'}
    ie_isento = normalize(ie) == "ISENTO"
    ie = re.sub(r"\D", "", str(ie or ""))
    operador = usuario[:60] or "noromak"
    revenda = _exp_revenda(pedido)  # V20.33: Bauru = revenda 3
    # V19.44: categoria (351) e I.E. pela porta, no criar e no atualizar (Guilherme, 16/10).
    # CPF = 1; CNPJ com I.E. = 3 + número; CNPJ sem I.E. = 2 + ISENTO. O automático não lê a
    # I.E. da NF-e: para CNPJ ele não mexe (vazio não apaga a I.E. de quem tem).
    fiscal: dict[str, Any] = {}
    if len(documento) == 11:
        fiscal = {"categoria": 1}
    elif len(documento) == 14 and ie:
        fiscal = {"categoria": 3, "inscricao_estadual": ie[:20]}
    elif len(documento) == 14 and (ie_isento or usuario != "automatico"):
        fiscal = {"categoria": 2, "inscricao_estadual": "ISENTO"}
    avisos: list[str] = []
    try:
        end = exp_endereco_entrega(pedido)
    except Exception as exc:  # ML fora do ar não impede nome/contatos
        end = {"endereco": None, "falta": f"não consegui ler o envio no ML ({exc})"}
    if not end["endereco"] and endereco_texto:
        # V19.36: a API (Shopee) mascarou; vale o endereço que a página mostrou.
        end = exp_endereco_do_texto(endereco_texto, bairro)
    endereco = end["endereco"]
    if not endereco:
        avisos.append("Endereço não enviado: " + end["falta"] + ".")
    elif end.get("bairro_padrao"):
        avisos.append(f"Bairro gravado como {EXP_BAIRRO_PADRAO_SHOPEE}: a página não informou o bairro.")
    criado = False
    nome_apollo = ""
    # V20.33 (2ª revisão): o botão espera a vez da porta no máximo EXP_CLIQUE_ESPERA_S (a rotina do TikTok pode
    # estar gravando); as rotinas automáticas esperam o quanto for preciso.
    vez = _ExpVezDaPorta(None if usuario == "automatico" else EXP_CLIQUE_ESPERA_S)
    if not vez.ok:
        return {"ok": False, "situacao": "ocupado",
                "error": "O Apollo está ocupado com outra gravação agora. Espere alguns segundos e tente de novo."}
    with vez:
        try:
            if codigo and _exp_nome_abreviado(nome_limpo):   # V20.09: só o nome abreviado gasta a busca
                nome_apollo = exp_buscar_cliente(documento, operador, revenda)["nome"]
            if not codigo:
                b = exp_buscar_cliente(documento, operador, revenda)
                if b["situacao"] == "encontrado" and b["cliente"]:
                    codigo = b["cliente"]
                    nome_apollo = b["nome"]
                elif b["situacao"] == "mais_de_um":
                    return {"ok": False, "situacao": "mais_de_um", "lista": b["lista"],
                            "error": "Mais de um cliente com este CPF/CNPJ no Apollo: informe o código certo."}
                elif b["situacao"] == "nao_cadastrado":
                    # V19.41: o cadastro automático NUNCA cria (o cliente da venda demora
                    # para cair no Apollo; criar na hora duplicaria). Volta e tenta depois.
                    if not criar:
                        return {"ok": False, "situacao": "nao_cadastrado",
                                "error": "Cliente ainda não está no Apollo."}
                    if not endereco:
                        return {"ok": False, "situacao": "sem_endereco",
                                "error": "Cliente novo precisa do endereço inteiro: " + end["falta"] + "."}
                    if not nome_limpo:
                        return {"ok": False, "error": "Cliente novo precisa do nome da NF-e."}
                    c = _exp_porta("cliente/criar", {
                        "revenda": revenda, "documento": documento, "operador": operador, "nome": nome_limpo,
                        "email": LINX_CADASTRO_EMAIL, "ddd_celular": LINX_CADASTRO_DDD, "celular": EXP_CELULAR_PADRAO,
                        "endereco": endereco,
                        **fiscal}, escrita=True)
                    novo = re.sub(r"\D", "", str(c.get("cliente") or ""))
                    if c.get("situacao") not in ("criado", "ja_cadastrado") or not novo:
                        return {"ok": False, "situacao": c.get("situacao") or "erro",
                                "error": c.get("erro") or "O Apollo não criou o cliente."}
                    codigo, criado = novo, c.get("situacao") == "criado"
                else:
                    return {"ok": False, "error": "Resposta inesperada da busca do cliente."}
            base = {"revenda": revenda, "cliente": int(codigo), "documento": documento, "operador": operador}
            corpo = {**base, "email": LINX_CADASTRO_EMAIL, "ddd_telefone": LINX_CADASTRO_DDD,
                     "telefone": LINX_CADASTRO_TELEFONE, "ddd_celular": LINX_CADASTRO_DDD, "celular": EXP_CELULAR_PADRAO}
            if _exp_nome_encurta(nome_limpo, nome_apollo):
                avisos.append(f'Nome mantido no Apollo: {" ".join(_exp_limpo(nome_apollo).split())} (a NF-e veio abreviada).')
            elif _exp_nome_abreviado(nome_limpo) and not nome_apollo and not criado:
                # V20.10: sem saber o nome de lá, o abreviado não grava por cima.
                avisos.append("Nome não enviado ao Apollo: veio abreviado e o Apollo não informou o nome atual.")
            elif nome_limpo:
                corpo["nome"] = nome_limpo
            if endereco:
                corpo["endereco"] = endereco
            corpo.update(fiscal)
            at = _exp_porta("cliente/atualizar", corpo, escrita=True)
            if at.get("situacao") != "atualizado":
                return {"ok": False, "situacao": at.get("situacao") or "erro", "cliente": codigo,
                        "error": at.get("erro") or "O Apollo não confirmou a atualização."}
            avisos += [str(x) for x in (at.get("avisos") or [])]
            if at.get("categoria") is not None or at.get("inscricao_estadual"):
                avisos.append(f"Categoria {at.get('categoria') or '-'}, I.E. {at.get('inscricao_estadual') or '-'} no Apollo.")
            elif len(documento) == 14 and not fiscal:
                avisos.append("CNPJ: categoria e I.E. não enviadas (I.E. da NF-e não lida). Confira no Apollo.")
            cr = _exp_porta("cliente/credito", {**base, "situacao_credito": "1"}, escrita=True)
        except PortaErro as exc:
            return {"ok": False, "situacao": "incerto" if exc.incerto else "erro", "cliente": codigo, "error": str(exc)}
    # V19.39: crédito que o Apollo não gravou (descarte em silêncio da Linx: os clientes
    # criados pela API em 15/10 voltaram "nao_gravou") trava o caixa na função 257.
    if cr.get("situacao") in ("nao_gravou", "recusado", "incerto"):
        avisos.insert(0, "CRÉDITO NÃO LIBERADO no Apollo (" + str(cr.get("situacao")) + "): libere a Situação de "
                         "Crédito e o Cadastro no Apollo antes do caixa, senão ele pede a autorização da função 257.")
    salvar_cliente_fiscal(pedido, documento, nome, linx_cliente=codigo, fonte="porta", usuario=usuario)
    # V19.42: cadastro feito pelo BOTÃO também fica registrado como feito — o painel da
    # extensão pula a etapa em qualquer computador (antes só no navegador que clicou) e
    # a rotina automática não refaz o mesmo pedido.
    if usuario != "automatico":
        agora = time.time()
        _cadastro_auto_registrar(pedido, agora, agora, 0, "feito", "pelo botão (" + usuario[:40] + ")", codigo)
    audit(usuario, "expedicao.cadastro", f"{pedido}|{codigo}|{'criado' if criado else 'atualizado'}|{cr.get('situacao')}")
    return {"ok": True, "situacao": "criado" if criado else "atualizado", "cliente": codigo,
            "nome": nome_limpo, "endereco": endereco, "cidade_apollo": at.get("cidade"),
            "credito": cr.get("situacao"), "avisos": avisos + [str(x) for x in (cr.get("avisos") or [])],
            "bloqueado": cr.get("situacao") == "bloqueado_pelo_financeiro"}


# ---------------------------------------------------------------------------
# V19.41 — Cadastro automático do cliente no Apollo (decisões do dono, 16/10).
# Uma rotina no servidor atualiza sozinha o cadastro dos pedidos novos do Mercado Livre
# e da Shopee, com a MESMA gravação do botão (nome, e-mail e celular padrão, endereço
# sem acento e crédito) — exp_cadastro_atualizar(..., criar=False). Regras:
#   - NUNCA cria cliente: da venda até o cliente cair no Apollo leva um tempo incerto;
#     criar na hora duplicaria. Não achou → tenta de novo a cada 10 min por até 1 h,
#     contada de quando o Noromak recebeu o nome/CPF da NF-e (vale fora do expediente);
#     depois fica "não encontrado no Apollo" e quem resolve é o botão.
#   - só pedidos que chegaram DEPOIS de ligar; "mais de um cliente" ou erro não mexe;
#   - cada pedido é feito uma vez; interruptor no Admin (perfil Admin), começa desligado.
# ---------------------------------------------------------------------------
CADASTRO_AUTO_INTERVALO = 600      # 10 min entre tentativas do mesmo pedido
CADASTRO_AUTO_JANELA = 3600        # 1 h tentando
CADASTRO_AUTO_POR_RODADA = 5       # a porta aceita 6 escritas/min; cada pedido = 2
CADASTRO_AUTO_FINAIS = ("feito", "nao_encontrado", "mais_de_um", "erro")
CADASTRO_AUTO_MARKETPLACES = ("Mercado Livre", "Shopee")


def ensure_cadastro_auto_schema() -> None:
    with DB_LOCK:
        DB.execute(
            """CREATE TABLE IF NOT EXISTS cadastro_auto_v1941 (
                   order_key TEXT PRIMARY KEY,
                   pedido TEXT NOT NULL DEFAULT '',
                   inicio_epoch REAL NOT NULL DEFAULT 0,
                   ultima_epoch REAL NOT NULL DEFAULT 0,
                   tentativas INTEGER NOT NULL DEFAULT 0,
                   situacao TEXT NOT NULL DEFAULT 'aguardando',
                   detalhe TEXT NOT NULL DEFAULT '',
                   cliente TEXT NOT NULL DEFAULT '',
                   atualizado_em TEXT NOT NULL DEFAULT ''
               )"""
        )
        DB.execute(
            """CREATE TABLE IF NOT EXISTS cadastro_auto_config_v1941 (
                   id INTEGER PRIMARY KEY CHECK (id = 1),
                   ligado INTEGER NOT NULL DEFAULT 0,
                   ligado_em TEXT NOT NULL DEFAULT '',
                   por TEXT NOT NULL DEFAULT ''
               )"""
        )
        DB.commit()


def cadastro_auto_config() -> dict[str, Any]:
    with DB_LOCK:
        row = DB.execute("SELECT ligado, ligado_em, por FROM cadastro_auto_config_v1941 WHERE id=1").fetchone()
    return {"ligado": bool(row and row["ligado"]), "ligado_em": (row["ligado_em"] if row else ""),
            "por": (row["por"] if row else "")}


def cadastro_auto_ligar(ligado: bool, usuario: str) -> dict[str, Any]:
    atual = cadastro_auto_config()
    # Ligar marca a hora: só entram pedidos cujo nome/CPF chegou depois disso.
    ligado_em = (atual["ligado_em"] if atual["ligado"] else now_iso()) if ligado else atual["ligado_em"]
    with DB_LOCK:
        DB.execute(
            """INSERT INTO cadastro_auto_config_v1941(id, ligado, ligado_em, por) VALUES(1,?,?,?)
               ON CONFLICT(id) DO UPDATE SET ligado=excluded.ligado, ligado_em=excluded.ligado_em, por=excluded.por""",
            (1 if ligado else 0, ligado_em, str(usuario or "")[:80]),
        )
        DB.commit()
    audit(usuario, "expedicao.cadastro_auto", "ligado" if ligado else "desligado")
    return {"ok": True, **cadastro_auto_config()}


def cadastro_auto_do_pedido(pedido: str) -> dict[str, Any] | None:
    with DB_LOCK:
        row = DB.execute("SELECT * FROM cadastro_auto_v1941 WHERE order_key=?", (normalize(pedido),)).fetchone()
    return dict(row) if row else None


def _cadastro_auto_registrar(pedido: str, inicio: float, agora: float, tentativas: int, situacao: str,
                             detalhe: str, cliente: str = "") -> None:
    with DB_LOCK:
        DB.execute(
            """INSERT INTO cadastro_auto_v1941(order_key,pedido,inicio_epoch,ultima_epoch,tentativas,situacao,detalhe,cliente,atualizado_em)
               VALUES(?,?,?,?,?,?,?,?,?)
               ON CONFLICT(order_key) DO UPDATE SET ultima_epoch=excluded.ultima_epoch, tentativas=excluded.tentativas,
                   situacao=excluded.situacao, detalhe=excluded.detalhe,
                   cliente=CASE WHEN excluded.cliente<>'' THEN excluded.cliente ELSE cadastro_auto_v1941.cliente END,
                   atualizado_em=excluded.atualizado_em""",
            (normalize(pedido), pedido, inicio, agora, tentativas, situacao, str(detalhe or "")[:400], cliente, now_iso()),
        )
        DB.commit()


def _cadastro_auto_candidatos(ligado_em: str) -> list[dict[str, Any]]:
    """Pedidos pendentes (ML/Shopee) cujo nome/CPF da NF-e chegou depois de ligar e que
    ainda não terminaram. O início da contagem de 1 h é a chegada do nome/CPF."""
    with DB_LOCK:
        pendentes, _, _ = get_storage("conf_pedidos")
        fiscais = DB.execute(
            "SELECT pedido, atualizado_em FROM cliente_fiscal WHERE documento_numero<>'' AND nome_fiscal<>'' AND atualizado_em>=?",
            (ligado_em,),
        ).fetchall()
        estados = {r["order_key"]: dict(r) for r in DB.execute("SELECT * FROM cadastro_auto_v1941").fetchall()}
    na_fila: dict[str, str] = {}
    for row in _rows_from_storage_value(pendentes):
        if isinstance(row, dict):
            mp = _vendas_marketplace(row.get("Marketplace") or row.get("Origem"))
            if mp in CADASTRO_AUTO_MARKETPLACES:
                na_fila.setdefault(normalize(order_number(row)), mp)
    saida = []
    for f in fiscais:
        chave = normalize(f["pedido"])
        if chave not in na_fila:
            continue
        estado = estados.get(chave)
        if estado and estado["situacao"] in CADASTRO_AUTO_FINAIS:
            continue
        try:
            chegou = datetime.fromisoformat(str(f["atualizado_em"])).timestamp()
        except Exception:
            chegou = time.time()
        saida.append({"pedido": f["pedido"], "inicio": (estado or {}).get("inicio_epoch") or chegou,
                      "ultima": (estado or {}).get("ultima_epoch") or 0, "tentativas": (estado or {}).get("tentativas") or 0})
    return saida


def cliente_fiscal_da_api_ml() -> int:
    """V19.47: o ML voltou a liberar o billing-info (conferido em 16/10) e a importação já
    grava NomeFiscalMercadoLivre/CPFMercadoLivre/CNPJMercadoLivre na linha do pedido. Copia
    para cliente_fiscal (fonte api_ml) SÓ quando o pedido ainda não tem nada lá — o que a
    extensão gravou nunca é sobrescrito. Assim o automático anda sem ninguém clicar."""
    with DB_LOCK:
        pendentes, _, _ = get_storage("conf_pedidos")
        ja = {r["order_key"] for r in DB.execute("SELECT order_key FROM cliente_fiscal").fetchall()}
    novos = 0
    for row in _rows_from_storage_value(pendentes):
        if not isinstance(row, dict) or _vendas_marketplace(row.get("Marketplace") or row.get("Origem")) != "Mercado Livre":
            continue
        pedido = str(order_number(row) or "").strip()
        doc = re.sub(r"\D", "", str(row.get("CNPJMercadoLivre") or row.get("CPFMercadoLivre") or ""))
        nome = str(row.get("NomeFiscalMercadoLivre") or "").strip()
        if not pedido or normalize(pedido) in ja or len(doc) not in (11, 14) or not nome:
            continue
        r = salvar_cliente_fiscal(pedido, doc, nome, fonte="api_ml", usuario="automatico")
        if r.get("ok"):
            ja.add(normalize(pedido))
            novos += 1
    return novos


def cadastro_auto_rodada(agora: float | None = None, esperar=None) -> dict[str, int]:
    """Uma volta da rotina. `esperar(segundos)` espaça as chamadas à porta (teto de
    escritas por minuto); nos testes não espera."""
    cfg = cadastro_auto_config()
    contagem = {"feito": 0, "aguardando": 0, "nao_encontrado": 0, "mais_de_um": 0, "erro": 0}
    if not cfg["ligado"] or not EXP_CADASTRO_API:
        return contagem
    agora = float(agora if agora is not None else time.time())
    try:
        cliente_fiscal_da_api_ml()                      # V19.47
    except Exception as exc:
        print(f"[cadastro-auto] nome/CPF da API do ML: {exc}", flush=True)
    feitos = 0
    for c in _cadastro_auto_candidatos(cfg["ligado_em"]):
        if c["ultima"] and agora - c["ultima"] < CADASTRO_AUTO_INTERVALO:
            continue                                   # tenta de 10 em 10 min
        if feitos >= CADASTRO_AUTO_POR_RODADA:
            break
        if feitos and esperar:
            esperar(25)
        feitos += 1
        tent = int(c["tentativas"]) + 1
        try:
            r = exp_cadastro_atualizar(c["pedido"], "automatico", criar=False)
        except Exception as exc:                       # nunca derruba a rodada
            r = {"ok": False, "situacao": "erro", "error": str(exc)}
        sit = str(r.get("situacao") or "")
        vencido = agora - float(c["inicio"]) >= CADASTRO_AUTO_JANELA
        if r.get("ok"):
            final, det = "feito", "; ".join(r.get("avisos") or []) or f"crédito: {r.get('credito')}"
        elif sit == "nao_cadastrado":
            final, det = ("nao_encontrado" if vencido else "aguardando"), "Cliente ainda não está no Apollo."
        elif sit == "mais_de_um":
            final, det = "mais_de_um", "Mais de um cliente com este CPF/CNPJ no Apollo."
        elif sit == "desligado":
            break
        else:
            final, det = ("erro" if vencido else "aguardando"), str(r.get("error") or sit or "erro")
        _cadastro_auto_registrar(c["pedido"], float(c["inicio"]), agora, tent, final, det, str(r.get("cliente") or ""))
        contagem[final] = contagem.get(final, 0) + 1
    return contagem


def cadastro_auto_loop(stop_event: threading.Event) -> None:
    while not stop_event.is_set():
        try:
            cadastro_auto_rodada(esperar=lambda s: stop_event.wait(s))
        except Exception as exc:
            print(f"[cadastro-auto] {exc}", flush=True)
        stop_event.wait(120)


# ---------------------------------------------------------------------------
# V19.43 — Fila de faturamento em lote (decisões do dono, 16/10). Tela /faturamento.
# Cada pedido pendente do ML/Shopee/Magalu é conferido em segundo plano (de 10 em 10
# min) e classificado. Só fica PRONTO com: cadastro atualizado (automático ou botão),
# crédito liberado, UM atendimento, peças conferindo (kit inteiro) e valor do
# atendimento IGUAL ao da venda (vendas_v1799: soma de amount do pedido/carrinho). O
# resto fica "aguardando cadastro" ou "atenção" com o motivo. Na hora de executar, o
# pedido é conferido DE NOVO (o Apollo pode ter mudado) — quem solta romaneio e envia
# ao caixa são as rotas de sempre (exp_romaneio_soltar / exp_caixa_*).
# ---------------------------------------------------------------------------
FATURAMENTO_INTERVALO = 600
# V20.12 (dono, 03/11; Shopee 2610312SXXXGJE): 429/sem resposta do Apollo = "aguardando_apollo",
# conferido de novo em 2 min (o worker roda a cada 2 min), e a rodada para de ir ao Apollo na hora.
FATURAMENTO_REPETIR_APOLLO = 120
# Revisão 03/11: Apollo sem resposta há 30 min seguidos (porta fora do ar) = atenção, alguém olha.
FATURAMENTO_APOLLO_ATENCAO_S = 1800
FATURAMENTO_POR_RODADA = 4          # porta: 12 leituras/min; cada pedido ~3
FATURAMENTO_MARKETPLACES = ("Mercado Livre", "Shopee", "Magalu")
FATURAMENTO_OBS = {"Mercado Livre": "MERCADO LIVRE", "Shopee": "SHOPEE", "Magalu": "MAGALU"}


def ensure_faturamento_schema() -> None:
    with DB_LOCK:
        DB.execute(
            """CREATE TABLE IF NOT EXISTS faturamento_v1943 (
                   order_key TEXT PRIMARY KEY,
                   pedido TEXT NOT NULL DEFAULT '',
                   marketplace TEXT NOT NULL DEFAULT '',
                   situacao TEXT NOT NULL DEFAULT '',
                   motivo TEXT NOT NULL DEFAULT '',
                   cliente TEXT NOT NULL DEFAULT '',
                   nome TEXT NOT NULL DEFAULT '',
                   atendimento TEXT NOT NULL DEFAULT '',
                   valor_pedido REAL,
                   valor_atendimento REAL,
                   conferido_epoch REAL NOT NULL DEFAULT 0,
                   conferido_em TEXT NOT NULL DEFAULT ''
               )"""
        )
        # V20.12 (revisão 03/11): desde quando o Apollo não responde para este pedido (0 = respondeu).
        cols = {str(r["name"]) for r in DB.execute("PRAGMA table_info(faturamento_v1943)").fetchall()}
        if "apollo_desde" not in cols:
            DB.execute("ALTER TABLE faturamento_v1943 ADD COLUMN apollo_desde REAL NOT NULL DEFAULT 0")
        # V19.99 (revisão 28/10): correção de valor em andamento OU pela metade. Fica até a senha voltar
        # (corrigido / nada alterado) ou alguém conferir no Linx e liberar — nunca vence sozinha: uma
        # correção pela metade (peça descomprometida) aparecia como "romaneio já solto" e ia ao caixa.
        DB.execute(
            """CREATE TABLE IF NOT EXISTS faturamento_correcao_v1999 (
                   order_key TEXT PRIMARY KEY,
                   pedido TEXT NOT NULL DEFAULT '',
                   token TEXT NOT NULL DEFAULT '',
                   usuario TEXT NOT NULL DEFAULT '',
                   epoch REAL NOT NULL DEFAULT 0,
                   em TEXT NOT NULL DEFAULT '',
                   atendimento TEXT NOT NULL DEFAULT '',
                   valor_certo REAL,
                   valor_atual REAL
               )"""
        )
        DB.commit()


def _exp_valor_pedido(pedido: str) -> float | None:
    """Valor da venda (produtos, sem frete) = soma de amount das linhas do pedido ou do
    carrinho em vendas_v1799 (+ vendas das outras contas). Sem linha = None (desconhecido)."""
    chave = str(pedido or "").strip()
    with DB_LOCK:
        total = None
        for tabela in ("vendas_v1799", "vendas_conta_v1898"):
            try:
                r = DB.execute(f"SELECT COUNT(*) AS n, SUM(amount) AS s FROM {tabela} WHERE order_id=? OR pack_id=?",
                               (chave, chave)).fetchone()
            except sqlite3.OperationalError:
                continue
            if r and r["n"]:
                total = (total or 0.0) + float(r["s"] or 0)
        if total is None:
            # V20.33: TikTok sem API não está nas vendas — vale o valor do atendimento criado pelo Noromak
            # (o mesmo que foi enviado), senão o lido no detalhe do Seller Center.
            # revisar-antes-de-subir (06/11): a venda é a do TikTok AGORA (cancelou uma unidade depois do atendimento =
            # valor diferente, e o painel/Faturamento barram). O valor enviado só vale para os centavos da divisão.
            try:
                row = DB.execute("SELECT venda_json FROM tiktok_sc_pedido_v2030 WHERE pedido=?", (chave,)).fetchone()
                venda = json.loads(row["venda_json"]) if row and row["venda_json"] else None
                if isinstance(venda, dict) and not venda.get("erro") and venda.get("itens"):
                    total = sum(float(i.get("valor") or 0) for i in venda["itens"])
                    unidades = sum(int(i.get("qtd") or 0) for i in venda["itens"])
                    row = DB.execute("SELECT valor FROM tiktok_atendimento_v2033 WHERE pedido=? AND valor IS NOT NULL",
                                     (chave,)).fetchone()
                    if row and abs(float(row["valor"]) - total) < 0.01 * max(1, unidades):
                        total = float(row["valor"])
            except (sqlite3.OperationalError, TypeError, ValueError):
                pass
    return round(total, 2) if total is not None else None


# V19.99 (decisões do dono, 28/10): o atendimento que a integração cria no Apollo vem com outro valor.
# Shopee: o que o comprador pagou (preço − cupom da loja − cupom da Shopee − moedas); o certo é a venda
# (preço da unidade × qtd). ML: centavos a mais no kit. Só manda corrigir (situação "corrigir_valor",
# a extensão Linx Cliente troca o preço no Linx web) quando a diferença tem explicação; senão barra.
FATURAMENTO_TOLERANCIA_SHOPEE = 0.05
FATURAMENTO_TOLERANCIA_ML = 0.10


def _faturamento_diferenca_explicada(pedido: str, marketplace: str, valor_pedido: float, valor_atendimento: float) -> str:
    """Pura no banco: o porquê da diferença ("" = sem explicação, continua barrando)."""
    dif = round(float(valor_pedido) - float(valor_atendimento), 2)
    if _vendas_marketplace(marketplace) == "Shopee":
        with DB_LOCK:
            row = DB.execute("SELECT order_income_json FROM shopee_escrow_v1810 WHERE order_sn=?",
                             (str(pedido or "").strip(),)).fetchone()
        try:
            inc = json.loads(row["order_income_json"]) if row and row["order_income_json"] else {}
        except Exception:
            inc = {}
        if not isinstance(inc, dict):
            return ""
        partes = [("cupom da loja", inc.get("voucher_from_seller")), ("cupom da Shopee", inc.get("voucher_from_shopee")),
                  ("moedas", inc.get("coins"))]
        partes = [(t, round(float(v), 2)) for t, v in partes if isinstance(v, (int, float)) and float(v) > 0]
        desconto = round(sum(v for _, v in partes), 2)
        if desconto > 0 and abs(dif - desconto) <= FATURAMENTO_TOLERANCIA_SHOPEE + 1e-9:
            return " + ".join(f"{t} R$ {v:.2f}".replace(".", ",") for t, v in partes)
        return ""
    if _vendas_marketplace(marketplace) == "Mercado Livre" and 0 < abs(dif) <= FATURAMENTO_TOLERANCIA_ML + 1e-9:
        return "arredondamento do kit"
    return ""


def faturamento_classificar(pedido: str, d: dict[str, Any], valor_pedido: float | None,
                            explicar: Any = None) -> dict[str, Any]:
    """Pura: a resposta do exp_romaneio_preparar + valor da venda → situação na fila."""
    base = {"atendimento": "", "valor_atendimento": None}
    if d.get("caixa"):
        return {**base, "situacao": "feito", "motivo": "Enviado ao caixa."}
    if d.get("apollo_ocupado"):   # V20.12: passa sozinho, nunca "atenção"
        return {**base, "situacao": "aguardando_apollo",
                "motivo": f"Apollo ocupado ({d.get('aviso') or 'sem resposta'}). Confere de novo em 2 min sozinho."}
    if not d.get("ok", True) or d.get("situacao") == "erro":
        return {**base, "situacao": "atencao", "motivo": d.get("aviso") or d.get("error") or "Apollo não respondeu."}
    cred = ((d.get("credito") or {}).get("situacao") or {}).get("codigo")
    if cred is not None and str(cred) not in ("0", "1"):
        return {**base, "situacao": "atencao", "motivo": "Crédito bloqueado no Apollo."}
    # V20.09: atendimento achado por nome de uma letra pode ser de outra pessoa: nada de lote.
    if d.get("nome_abreviado") and not d.get("romaneio"):
        return {**base, "situacao": "atencao", "motivo": "Nome abreviado no Apollo: confira o cliente do atendimento no painel."}
    rom = d.get("romaneio") or ({"contato": d["romaneio_fora"]} if d.get("romaneio_fora") else None)
    if rom:
        a = next((c for c in d.get("candidatos") or [] if str(c.get("atendimento")) == str(rom.get("contato"))), {})
        # V19.99 (revisão 28/10): romaneio já solto não dispensa o valor — uma correção de preço
        # interrompida (peça descomprometida) aparecia como "nada a soltar" e ia ao caixa errada.
        if valor_pedido is not None and a.get("valor") is None:
            return {"situacao": "atencao", "atendimento": str(rom.get("contato") or ""), "valor_atendimento": None,
                    "motivo": "Romaneio já solto, mas o Apollo não informou o valor do atendimento: confira antes do caixa."}
        if valor_pedido is not None and abs(float(valor_pedido) - float(a["valor"])) > 0.009:
            return {"situacao": "atencao", "atendimento": str(rom.get("contato") or ""), "valor_atendimento": a.get("valor"),
                    "motivo": f"Romaneio já solto, mas o atendimento está com R$ {float(a['valor']):.2f} e a venda é "
                              f"R$ {float(valor_pedido):.2f}: confira no Apollo antes do caixa.".replace(".", ",")}
        return {"situacao": "pronto_caixa", "motivo": "Romaneio já solto: falta o caixa.",
                "atendimento": str(rom.get("contato") or ""), "valor_atendimento": a.get("valor")}
    soltar = [c for c in d.get("candidatos") or [] if c.get("total_a_soltar")]
    if not soltar:
        return {**base, "situacao": "atencao", "motivo": d.get("aviso") or "Nenhum atendimento aberto com peça a soltar."}
    if len(soltar) > 1:
        return {**base, "situacao": "atencao", "motivo": f"{len(soltar)} atendimentos abertos: escolha no painel."}
    a = soltar[0]
    info = {"atendimento": str(a.get("atendimento")), "valor_atendimento": a.get("valor")}
    if a.get("faltam"):
        return {**info, "situacao": "atencao", "motivo": "Falta no atendimento: " + ", ".join(a["faltam"])}
    if not a.get("bate"):
        return {**info, "situacao": "atencao", "motivo": "Peça do atendimento diferente do pedido."}
    if valor_pedido is None:
        return {**info, "situacao": "atencao", "motivo": "Valor da venda ainda não sincronizado."}
    if a.get("valor") is None:   # V19.99 (revisão 28/10): valor desconhecido nunca vira zero
        return {**info, "situacao": "atencao", "motivo": "O Apollo não informou o valor do atendimento."}
    if abs(float(valor_pedido) - float(a.get("valor") or 0)) > 0.009:
        porque = explicar(float(valor_pedido), float(a.get("valor") or 0)) if explicar else ""
        if porque:   # V19.99
            return {**info, "situacao": "corrigir_valor", "valor_certo": round(float(valor_pedido), 2),
                    "motivo": f"Corrigir no Apollo: R$ {float(a.get('valor') or 0):.2f} → R$ {float(valor_pedido):.2f} ({porque})".replace(".", ",")}
        return {**info, "situacao": "atencao",
                "motivo": f"Valor diferente: venda R$ {valor_pedido:.2f} × atendimento R$ {float(a.get('valor') or 0):.2f}".replace(".", ",")}
    return {**info, "situacao": "pronto", "motivo": ""}


def faturamento_conferir(pedido: str, marketplace: str = "", agora: float | None = None) -> dict[str, Any]:
    """Confere um pedido agora (Apollo) e grava a situação."""
    agora = float(agora if agora is not None else time.time())
    estado_cad = cadastro_auto_do_pedido(pedido) or {}
    conhecido = _exp_cliente_do_pedido(pedido)
    valor = _exp_valor_pedido(pedido)
    if estado_cad.get("situacao") != "feito":
        res = {"situacao": "aguardando_cadastro", "atendimento": "", "valor_atendimento": None,
               "motivo": {"nao_encontrado": "Cliente não apareceu no Apollo em 1 h: use o botão do painel.",
                          "mais_de_um": "Mais de um cliente com este CPF/CNPJ no Apollo."}.get(
                   estado_cad.get("situacao"), "Aguardando o cadastro do cliente.")}
        d = {}
    else:
        d = exp_romaneio_preparar(pedido)
        mp_explicar = marketplace or d.get("marketplace") or ""
        res = faturamento_classificar(pedido, d, valor, explicar=lambda v, a: _faturamento_diferenca_explicada(
            pedido, mp_explicar, v, a))
    cliente = str(((d.get("cliente") or {}).get("codigo")) or estado_cad.get("cliente") or conhecido["codigo"] or "")
    nome = str(conhecido["nome_fiscal"] or ((d.get("cliente") or {}).get("nome_apollo")) or "")
    with DB_LOCK:
        # V20.12 (revisão 03/11): falhas seguidas contam desde a primeira; resposta do Apollo zera.
        desde = 0.0
        if res["situacao"] == "aguardando_apollo":
            ant = DB.execute("SELECT apollo_desde FROM faturamento_v1943 WHERE order_key=?", (normalize(pedido),)).fetchone()
            desde = float(ant["apollo_desde"] or 0) if ant else 0.0
            desde = desde or agora
            if agora - desde >= FATURAMENTO_APOLLO_ATENCAO_S:
                res = {**res, "situacao": "atencao",
                       "motivo": f"Apollo sem resposta há {int((agora - desde) // 60)} min ({d.get('aviso') or 'sem resposta'}). "
                                 f"Confira a porta do Apollo; o pedido continua sendo conferido."}
        DB.execute(
            """INSERT INTO faturamento_v1943(order_key,pedido,marketplace,situacao,motivo,cliente,nome,atendimento,
                   valor_pedido,valor_atendimento,conferido_epoch,conferido_em,apollo_desde) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(order_key) DO UPDATE SET marketplace=excluded.marketplace, situacao=excluded.situacao,
                   motivo=excluded.motivo, cliente=excluded.cliente, nome=excluded.nome, atendimento=excluded.atendimento,
                   valor_pedido=excluded.valor_pedido, valor_atendimento=excluded.valor_atendimento,
                   conferido_epoch=excluded.conferido_epoch, conferido_em=excluded.conferido_em,
                   apollo_desde=excluded.apollo_desde""",
            (normalize(pedido), pedido, marketplace or (d.get("marketplace") or ""), res["situacao"], str(res.get("motivo") or "")[:300],
             cliente, nome[:120], str(res.get("atendimento") or ""), valor, res.get("valor_atendimento"), agora, now_iso(), desde),
        )
        DB.commit()
    return {"pedido": pedido, "marketplace": marketplace or d.get("marketplace") or "", "cliente": cliente, "nome": nome,
            "valor_pedido": valor, **res}


def _faturamento_prazo_dia(row: dict[str, Any]) -> str:
    """V19.73: prazo de despacho (AAAA-MM-DD, Brasília). ML já vem com -03:00; a Magalu manda
    em UTC ("...T02:59:59Z" = 23h59 do dia anterior em Brasília) e é convertida."""
    ml = _ml_parse_iso_date(row.get("DataLimiteDespachoMercadoLivre"))
    if ml:
        return ml
    texto = str(row.get("PrazoEnvioMagalu") or "").strip()
    try:
        dt = datetime.fromisoformat(texto.replace("Z", "+00:00"))
        # Meia-noite UTC exata = data pura (sem hora): converter jogaria para o dia anterior.
        meia_noite = (dt.hour, dt.minute, dt.second, dt.microsecond) == (0, 0, 0, 0)
        if dt.tzinfo is not None and not (meia_noite and dt.utcoffset() == timedelta(0)):
            dt = dt.astimezone(timezone(timedelta(hours=-3)))
        return dt.date().isoformat()
    except (ValueError, OverflowError):  # data absurda (ano 0001...) não derruba a tela
        return _ml_parse_iso_date(texto)


def _faturamento_fila() -> tuple[list[tuple[str, str]], dict[str, str]]:
    """(pedido, marketplace) dos pedidos na fila de pendentes, uma vez cada, e o prazo de
    despacho de cada um (o menor entre as linhas). Uma leitura só da fila (V19.73)."""
    with DB_LOCK:
        pendentes, _, _ = get_storage("conf_pedidos")
    vistos: dict[str, tuple[str, str]] = {}
    prazos: dict[str, str] = {}
    for row in _rows_from_storage_value(pendentes):
        if not isinstance(row, dict):
            continue
        mp = _vendas_marketplace(row.get("Marketplace") or row.get("Origem"))
        pedido = str(order_number(row) or "").strip()
        if pedido and mp in FATURAMENTO_MARKETPLACES:
            chave = normalize(pedido)
            vistos.setdefault(chave, (pedido, mp))
            dia = _faturamento_prazo_dia(row)
            if dia and (chave not in prazos or dia < prazos[chave]):
                prazos[chave] = dia
    return list(vistos.values()), prazos


# V19.85: lista de separação do dia (pedido do dono, 26/10). Todos os pendentes da fila da
# filial, kit aberto em peças, somados por código e na ordem da prateleira do Apollo da filial.
# A prateleira quase não muda: fica guardada 12 h; o que falta é lido em segundo plano, devagar
# (o Apollo divide 20 chamadas/min com o resto), e a tela recarrega até completar.
SEPARACAO_REVENDA = {"aracatuba": 1, "bauru": 3}
SEPARACAO_LOCAIS: dict[tuple[int, str], tuple[float, str]] = {}   # (revenda, código) -> (quando, prateleira)
SEPARACAO_LOCK = threading.Lock()
SEPARACAO_REUSO_S = 12 * 3600
# Revisão 26/10: o Apollo divide 20 chamadas/min com a operação (Faturamento, Demanda, TikTok):
# uma leitura por vez para as duas filiais, 1 a cada 12 s (5/min), sem esperar vaga; limite
# cheio = para e deixa a vez por 1 min.
SEPARACAO_INTERVALO = 12.0
SEPARACAO_PAUSA_S = 60
SEPARACAO_PAUSA_ATE = [0.0]
SEPARACAO_LENDO: set[str] = set()
SEPARACAO_SEM_RESPOSTA: dict[str, set[str]] = {}
SEPARACAO_ULTIMA_LEITURA: dict[str, float] = {}
SEPARACAO_REPETIR_S = 300   # peça sem resposta do Apollo é tentada de novo depois disso
# Dono, 26/10: a lista de 26/10 já foi emitida à mão; antes desta data a tela não monta nada
# (nem lê o Apollo) e só avisa quando começa.
SEPARACAO_INICIO = "2026-10-27"


def _separacao_pecas(filial: str) -> tuple[dict[str, dict[str, Any]], int]:
    """Peças de todos os marketplaces juntos (leitura do Apollo)."""
    grupos = _separacao_grupos(filial)
    pecas: dict[str, dict[str, Any]] = {}
    for g in grupos.values():
        for cod, p in g["pecas"].items():
            q = pecas.setdefault(cod, {**p, "qtd": 0})
            q["qtd"] += p["qtd"]
    return pecas, sum(len(g["pedidos"]) for g in grupos.values())


# Pedido do dono (26/10): a lista sai separada por marketplace, nesta ordem.
SEPARACAO_ORDEM_GRUPOS = ["Mercado Livre", "Shopee", "Magalu", "TikTok"]
SEPARACAO_FUTUROS: dict[str, int] = {}   # pedidos com despacho depois de hoje (fora da lista), por filial


def _separacao_grupo(row: dict[str, Any]) -> str:
    nome = _vendas_marketplace(row.get("Marketplace") or row.get("Origem"))
    return "TikTok" if "TIKTOK" in normalize(nome) else nome


def _separacao_hoje() -> str:
    return datetime.now(timezone(timedelta(hours=-3))).strftime("%Y-%m-%d")


def _separacao_grupos(filial: str) -> dict[str, dict[str, Any]]:
    if filial not in SEPARACAO_REVENDA:
        raise ValueError("Escolha a filial (Araçatuba ou Bauru) no seletor do menu.")
    with DB_LOCK:
        bruto, _, _ = get_storage("conf_pedidos")
    conhecidos = _separacao_codigos_conhecidos()
    hoje = _separacao_hoje()
    grupos: dict[str, dict[str, Any]] = {}
    futuros: set[str] = set()
    for row in _rows_from_storage_value(bruto):
        if not isinstance(row, dict) or filial_da_linha(row) != filial:
            continue
        # 26/10 (dono): despacho em outro dia (coleta de 28/10) não entra na separação de hoje.
        # Mesma regra do Faturamento (V19.73): hoje + atrasados; sem prazo (Shopee) entra.
        prazo = _faturamento_prazo_dia(row)
        if prazo and prazo > hoje:
            futuros.add(normalize(order_number(row)))
            continue
        try:   # revisão 26/10: "3,00" de planilha não vira 1
            qtd = max(0, int(float(str(row.get("Quantidade") or 1).strip().replace(",", "."))))
        except (TypeError, ValueError, OverflowError):
            qtd = 1
        partes = _separacao_partes(row.get("SKU") or row.get("Sku"), conhecidos)
        if not partes or not qtd:
            continue
        grupo = grupos.setdefault(_separacao_grupo(row), {"pecas": {}, "pedidos": set()})
        pecas = grupo["pecas"]
        numero = normalize(order_number(row))
        if numero:
            grupo["pedidos"].add(numero)
        kit = len(partes) > 1 or partes[0][1] != 1
        desc = str(row.get("Descrição") or row.get("Descricao") or "").strip()
        for cod, un in partes:
            p = pecas.setdefault(cod, {"codigo": cod, "descricao": "", "qtd": 0})
            p["qtd"] += qtd * un
            if desc and (not p["descricao"] or (not kit and p["descricao"].startswith("Peça do kit"))):
                p["descricao"] = ("Peça do kit: " if kit else "") + desc
    SEPARACAO_FUTUROS[filial] = len(futuros - {""})
    return grupos


def _separacao_codigos_conhecidos() -> set[str]:
    dados = precificador_dados()
    produtos = dados.get("products") if isinstance(dados, dict) else None
    if not isinstance(produtos, list):
        return set()
    return {str(p.get("sku") or "").strip().upper() for p in produtos if isinstance(p, dict)}


def _separacao_partes(sku: Any, conhecidos: set[str]) -> list[tuple[str, int]]:
    """Revisão 26/10 (regra da V19.48): SKU com barra que é UM produto do Precificador
    ("PSH367/80") fica inteiro; senão "A/B" = uma de cada (`_tiktok_pecas`)."""
    texto = str(sku or "").strip().upper()
    # Lista real de 26/10: "KIT-1/10405594-1/10405569" = quantidade/código de cada peça (par de lanternas).
    m = re.match(r"^KIT-(\d+/[^-/\s]+(?:-\d+/[^-/\s]+)+)$", texto)
    if m:
        return [(c, max(1, int(q))) for q, c in re.findall(r"(\d+)/([^-/\s]+)", m.group(1))]
    m = re.match(r"^KIT(\d*)-(.+)$", texto)
    unidades, inteiro = (max(1, int(m.group(1) or 1)), m.group(2).strip()) if m else (1, texto)
    if re.match(r"^\d{5,}-.+", inteiro):
        inteiro = inteiro.split("-", 1)[1].strip()
    # Kit cadastrado como produto comum no Precificador (V18.80: "A/B" com A e B também lá) abre em
    # peças; "KIT2-PSH367/80" vale também quando só o kit está no Precificador.
    pecas = [p.strip() for p in inteiro.split("/")]
    if "/" in inteiro and (inteiro in conhecidos or texto in conhecidos) \
            and not all(p in conhecidos for p in pecas):
        return [(inteiro, unidades)]
    # "WAP103/S": parte com menos de 3 caracteres é variação do produto, não outra peça.
    if "/" in inteiro and any(len(p) < 3 for p in pecas):
        return [(inteiro, unidades)]
    return _tiktok_pecas(texto)


def _separacao_local(revenda: int, cod: str) -> str | None:
    with SEPARACAO_LOCK:
        g = SEPARACAO_LOCAIS.get((revenda, cod))
    return g[1] if g and time.time() - g[0] <= SEPARACAO_REUSO_S else None


def separacao_ler_apollo(filial: str) -> None:
    """Lê no Apollo a prateleira das peças que ainda não tem. Fora do DB_LOCK."""
    revenda = SEPARACAO_REVENDA[filial]
    pecas, _ = _separacao_pecas(filial)
    sem: set[str] = set()
    primeira = True
    for cod in sorted(pecas):
        if _separacao_local(revenda, cod) is not None:
            continue
        if not primeira and SEPARACAO_INTERVALO:
            time.sleep(SEPARACAO_INTERVALO)
        primeira = False
        try:
            stock = crm_stock_lookup(cod, "separacao", 0)
        except CrmLimiteAtingido:
            # Limite cheio: a operação vem antes. Para e tenta depois (o que falta não é "sem resposta").
            with SEPARACAO_LOCK:
                SEPARACAO_PAUSA_ATE[0] = time.time() + SEPARACAO_PAUSA_S
            break
        except Exception:
            sem.add(cod)
            continue
        # Revisão 26/10: a filial que não respondeu vem na lista com respondeu=False — não é "sem prateleira".
        rows = [r for r in (stock.get("estoques") or [])
                if int(r.get("revenda") or 0) == revenda and r.get("respondeu") is not False]
        if not rows:
            sem.add(cod)
            continue
        # "...." = sem prateleira cadastrada (V19.07): guarda vazio, não lê de novo.
        loc = next((str(r.get("localizacao") or "").strip() for r in rows
                    if str(r.get("localizacao") or "").strip().strip(".")), "")
        with SEPARACAO_LOCK:
            SEPARACAO_LOCAIS[(revenda, cod)] = (time.time(), loc)
    with SEPARACAO_LOCK:
        SEPARACAO_SEM_RESPOSTA[filial] = sem
        SEPARACAO_ULTIMA_LEITURA[filial] = time.time()


def separacao_iniciar_leitura(filial: str) -> None:
    with SEPARACAO_LOCK:
        if SEPARACAO_LENDO or time.time() < SEPARACAO_PAUSA_ATE[0]:   # uma leitura por vez, as duas filiais
            return
        SEPARACAO_LENDO.add(filial)

    def _rodar() -> None:
        try:
            separacao_ler_apollo(filial)
        except Exception as exc:
            print(f"[separacao] erro lendo o Apollo: {exc}", flush=True)
        finally:
            with SEPARACAO_LOCK:
                SEPARACAO_LENDO.discard(filial)

    try:
        threading.Thread(target=_rodar, name=f"separacao-{filial}", daemon=True).start()
    except Exception as exc:   # sem thread (memória cheia): não deixa as duas filiais presas em "lendo"
        print(f"[separacao] não iniciou a leitura: {exc}", flush=True)
        with SEPARACAO_LOCK:
            SEPARACAO_LENDO.discard(filial)


def separacao_lista(filial: str) -> dict[str, Any]:
    if SEPARACAO_INICIO and _separacao_hoje() < SEPARACAO_INICIO:
        if filial not in SEPARACAO_REVENDA:
            raise ValueError("Escolha a filial (Araçatuba ou Bauru) no seletor do menu.")
        return {"ok": True, "filial": filial, "filial_nome": CASAS.get(filial, filial), "gerada_em": now_iso(),
                "pedidos": 0, "unidades": 0, "itens": [], "grupos": [], "futuros": 0, "faltam": 0,
                "lendo": False, "sem_resposta": [], "inicio": SEPARACAO_INICIO}
    revenda = SEPARACAO_REVENDA.get(filial)
    por_grupo = _separacao_grupos(filial)
    pecas: dict[str, dict[str, Any]] = {}
    for g in por_grupo.values():
        for cod, p in g["pecas"].items():
            pecas.setdefault(cod, {**p, "qtd": 0})["qtd"] += p["qtd"]
    n_pedidos = sum(len(g["pedidos"]) for g in por_grupo.values())
    with SEPARACAO_LOCK:
        sem = set(SEPARACAO_SEM_RESPOSTA.get(filial) or ())
        lendo = filial in SEPARACAO_LENDO
        ultima = SEPARACAO_ULTIMA_LEITURA.get(filial, 0.0)
        pausa = time.time() < SEPARACAO_PAUSA_ATE[0]
    itens, faltam, sem_local = [], 0, 0
    for p in pecas.values():
        loc = _separacao_local(revenda, p["codigo"])
        if loc is None:
            sem_local += 1
            faltam += p["codigo"] not in sem
        itens.append({**p, "localizacao": loc or ""})
    if not lendo and not pausa and (faltam or (sem_local and time.time() - ultima > SEPARACAO_REPETIR_S)):
        separacao_iniciar_leitura(filial)
        lendo = True
    ordem = lambda p: (not p["localizacao"], _full_loc_chave(p["localizacao"]), p["codigo"])
    itens.sort(key=ordem)
    locais = {p["codigo"]: p["localizacao"] for p in itens}
    grupos = []
    for nome in sorted(por_grupo, key=lambda n: (SEPARACAO_ORDEM_GRUPOS.index(n)
                                                 if n in SEPARACAO_ORDEM_GRUPOS else 99, n)):
        g_itens = sorted(({**p, "localizacao": locais.get(p["codigo"], "")}
                          for p in por_grupo[nome]["pecas"].values()), key=ordem)
        grupos.append({"nome": nome, "pedidos": len(por_grupo[nome]["pedidos"]),
                       "unidades": sum(p["qtd"] for p in g_itens), "itens": g_itens})
    return {"ok": True, "filial": filial, "filial_nome": CASAS.get(filial, filial), "gerada_em": now_iso(),
            "pedidos": n_pedidos, "unidades": sum(p["qtd"] for p in itens), "itens": itens, "grupos": grupos,
            "futuros": SEPARACAO_FUTUROS.get(filial, 0),
            "faltam": faltam, "lendo": faltam > 0,   # pausa/outra filial lendo: a tela segue esperando
            "sem_resposta": sorted(c for c in sem if c in pecas)}


# ---------------------------------------------------------------------------------------------
# V19.88 — Devoluções (decisões do dono, 27/10; desenho em
# docs/superpowers/specs/2026-10-27-devolucoes-design.md).
# O operador (módulo conferencia, /devolucoes) acha o pedido CONCLUÍDO, confere a peça com a venda
# e marca bom/ruim; o admin (/devolucoes-admin) trata no Apollo e marca "tratada" com o documento.
# É só registro: nunca mexe em completed_orders, na fila, no Apollo nem no marketplace.
# ---------------------------------------------------------------------------------------------
DEVOLUCAO_DIAS = 180            # busca nos pedidos concluídos dos últimos 180 dias
DEVOLUCAO_INDICE_LOTE = 200     # linhas do histórico indexadas por vez (JSON lido fora do DB_LOCK)
DEVOLUCAO_MOTIVOS = {
    "avariado": "Avariado",
    "usado": "Usado",
    "faltando": "Faltando peça ou acessório",
    "embalagem": "Embalagem violada",
    "veio_outra": "Veio outra peça",
}
DEVOLUCAO_SITUACOES = ("a_tratar", "tratada")
DEVOLUCAO_MAX_ITENS = 200       # revisão 27/10: peças por registro (cada uma é um INSERT sob o DB_LOCK)
DEVOLUCAO_MAX_CODIGO = 60
DEVOLUCAO_INDICE_LOCK = threading.Lock()   # uma indexação por vez (busca e worker)
_DEVOLUCAO_EAN_LOCK = threading.Lock()
_DEVOLUCAO_EAN_CACHE: dict[str, Any] = {}


class DevolucaoConflito(Exception):
    """Outra pessoa gravou a devolução depois que a tela carregou (409)."""

    def __init__(self, atual: dict[str, Any] | None):
        super().__init__("A devolução foi alterada por outra pessoa. Confira e tente de novo.")
        self.atual = atual


def ensure_devolucoes_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """
            CREATE TABLE IF NOT EXISTS devolucao_v1988 (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                filial TEXT NOT NULL DEFAULT '',
                marketplace TEXT NOT NULL DEFAULT '',
                pedido TEXT NOT NULL DEFAULT '',
                order_key TEXT NOT NULL DEFAULT '',
                cliente TEXT NOT NULL DEFAULT '',
                sem_pedido INTEGER NOT NULL DEFAULT 0,
                situacao TEXT NOT NULL DEFAULT 'a_tratar',
                obs TEXT NOT NULL DEFAULT '',
                recebido_por TEXT NOT NULL DEFAULT '',
                recebido_em TEXT NOT NULL DEFAULT '',
                documento_apollo TEXT NOT NULL DEFAULT '',
                tratada_por TEXT NOT NULL DEFAULT '',
                tratada_em TEXT NOT NULL DEFAULT '',
                versao INTEGER NOT NULL DEFAULT 1,
                token TEXT NOT NULL DEFAULT ''
            );
            CREATE INDEX IF NOT EXISTS idx_devolucao_pedido ON devolucao_v1988(order_key);
            CREATE INDEX IF NOT EXISTS idx_devolucao_situacao ON devolucao_v1988(situacao, recebido_em);
            CREATE TABLE IF NOT EXISTS devolucao_item_v1988 (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                devolucao_id INTEGER NOT NULL,
                sku TEXT NOT NULL DEFAULT '',
                descricao TEXT NOT NULL DEFAULT '',
                ean TEXT NOT NULL DEFAULT '',
                qtd_vendida INTEGER,
                qtd INTEGER NOT NULL DEFAULT 0,
                estado TEXT NOT NULL DEFAULT '',
                motivo TEXT NOT NULL DEFAULT '',
                obs TEXT NOT NULL DEFAULT '',
                fora_da_venda INTEGER NOT NULL DEFAULT 0
            );
            CREATE INDEX IF NOT EXISTS idx_devolucao_item ON devolucao_item_v1988(devolucao_id);
            CREATE TABLE IF NOT EXISTS devolucao_evento_v1988 (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                devolucao_id INTEGER NOT NULL,
                quando TEXT NOT NULL DEFAULT '',
                quem TEXT NOT NULL DEFAULT '',
                acao TEXT NOT NULL DEFAULT '',
                detalhe TEXT NOT NULL DEFAULT '{}'
            );
            CREATE INDEX IF NOT EXISTS idx_devolucao_evento ON devolucao_evento_v1988(devolucao_id);
            -- Índice de busca: uma linha por peça de pedido concluído (o payload do histórico é lido
            -- uma vez só, fora do DB_LOCK; o bip consulta só esta tabela pequena).
            CREATE TABLE IF NOT EXISTS devolucao_busca_v1988 (
                order_key TEXT NOT NULL,
                pedido TEXT NOT NULL DEFAULT '',
                filial TEXT NOT NULL DEFAULT '',
                marketplace TEXT NOT NULL DEFAULT '',
                concluido_em TEXT NOT NULL DEFAULT '',
                sku TEXT NOT NULL DEFAULT '',
                ean TEXT NOT NULL DEFAULT '',
                cliente TEXT NOT NULL DEFAULT '',
                cliente_busca TEXT NOT NULL DEFAULT '',
                ml_ids TEXT NOT NULL DEFAULT ''
            );
            CREATE INDEX IF NOT EXISTS idx_devolucao_busca_pedido ON devolucao_busca_v1988(order_key);
            CREATE INDEX IF NOT EXISTS idx_devolucao_busca_sku ON devolucao_busca_v1988(sku);
            CREATE INDEX IF NOT EXISTS idx_devolucao_busca_ean ON devolucao_busca_v1988(ean);
            CREATE INDEX IF NOT EXISTS idx_devolucao_busca_data ON devolucao_busca_v1988(concluido_em);
            -- Revisão 27/10: indexa do mais novo para o mais antigo. Tudo até o piso está no índice;
            -- acima dele, as conclusões já indexadas ficam marcadas até o piso subir.
            CREATE TABLE IF NOT EXISTS devolucao_indice_v1988 (
                id INTEGER PRIMARY KEY CHECK (id = 1),
                piso_hist_id INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS devolucao_indexado_v1988 (
                hist_id INTEGER PRIMARY KEY
            );
            """
        )
        # V19.95: devoluções no lucro — destino, custo e frete (desenho 2026-10-27-devolucoes-lucro-design.md).
        cols_item = {r[1] for r in DB.execute("PRAGMA table_info(devolucao_item_v1988)").fetchall()}
        for nome, ddl in (("destino", "TEXT NOT NULL DEFAULT ''"), ("custo_unit", "REAL"),
                          ("custo_origem", "TEXT NOT NULL DEFAULT ''")):
            if nome not in cols_item:
                DB.execute(f"ALTER TABLE devolucao_item_v1988 ADD COLUMN {nome} {ddl}")
        cols_dev = {r[1] for r in DB.execute("PRAGMA table_info(devolucao_v1988)").fetchall()}
        for nome, ddl in (("frete", "REAL"), ("frete_origem", "TEXT NOT NULL DEFAULT ''"),
                          ("motivo_dev", "TEXT NOT NULL DEFAULT ''"),   # V19.97
                          ("exportacao_id", "INTEGER")):                # V19.97: lote em que foi exportada
            if nome not in cols_dev:
                DB.execute(f"ALTER TABLE devolucao_v1988 ADD COLUMN {nome} {ddl}")
        # V19.97: lotes de exportação (cada devolução tratada entra em um só lote).
        DB.execute("""CREATE TABLE IF NOT EXISTS devolucao_exportacao_v1997 (
                id INTEGER PRIMARY KEY AUTOINCREMENT, criado_em TEXT NOT NULL, criado_por TEXT NOT NULL,
                filial TEXT NOT NULL DEFAULT '', devolucoes INTEGER NOT NULL DEFAULT 0)""")
        # V19.95: NF de venda do ML lida uma vez por pedido.
        DB.execute("""CREATE TABLE IF NOT EXISTS devolucao_nf_v1995 (
                order_key TEXT PRIMARY KEY, nf_json TEXT NOT NULL, lido_em TEXT NOT NULL)""")
        # V19.94: venda do ML lida na hora (cancelada some de vendas_v1799; a devolução ainda precisa dela).
        DB.execute("""CREATE TABLE IF NOT EXISTS devolucao_venda_ml_v1994 (
                order_id TEXT PRIMARY KEY, pack_id TEXT NOT NULL DEFAULT '', conta TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT '', linhas_json TEXT NOT NULL DEFAULT '[]', lido_em TEXT NOT NULL DEFAULT '')""")
        DB.execute("CREATE INDEX IF NOT EXISTS idx_devolucao_venda_ml_pack ON devolucao_venda_ml_v1994(pack_id)")
        # Banco que rodou a 1ª versão do ramo (antes da revisão de 27/10).
        if "token" not in {r[1] for r in DB.execute("PRAGMA table_info(devolucao_v1988)").fetchall()}:
            DB.execute("ALTER TABLE devolucao_v1988 ADD COLUMN token TEXT NOT NULL DEFAULT ''")
        if "piso_hist_id" not in {r[1] for r in DB.execute("PRAGMA table_info(devolucao_indice_v1988)").fetchall()}:
            DB.execute("ALTER TABLE devolucao_indice_v1988 ADD COLUMN piso_hist_id INTEGER NOT NULL DEFAULT 0")
        # Revisão 27/10: o "Concluir" repetido depois de perder a resposta não duplica.
        DB.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_devolucao_token ON devolucao_v1988(token) WHERE token<>''")
        # Envio da devolução do ML (etiqueta de volta), lido na mesma chamada do Pós-venda.
        colunas = {r[1] for r in DB.execute("PRAGMA table_info(ml_reclamacao_v1888)").fetchall()}
        if colunas and "devolucao_envios" not in colunas:
            DB.execute("ALTER TABLE ml_reclamacao_v1888 ADD COLUMN devolucao_envios TEXT NOT NULL DEFAULT ''")
        DB.commit()


def _devolucao_texto_busca(valor: Any) -> str:
    texto = unicodedata.normalize("NFKD", str(valor or "")).encode("ascii", "ignore").decode().upper()
    return " ".join(re.sub(r"[^A-Z0-9]+", " ", texto).split())


def _devolucao_like(valor: str) -> str:
    """Revisão 27/10: "%" e "_" bipados não viram curinga (listavam os clientes da filial)."""
    return valor.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


def _devolucao_qtd(valor: Any) -> int:
    try:   # "3,00" de planilha não vira 1 (mesma regra da separação)
        return max(0, int(float(str(valor if valor is not None else 1).strip().replace(",", "."))))
    except (TypeError, ValueError, OverflowError):
        return 1


def _devolucao_cliente(rows: list[dict[str, Any]]) -> str:
    for campo in ("Cliente", "Nome Conferência", "NomeFiscalMercadoLivre"):
        for r in rows:
            texto = str(r.get(campo) or "").strip()
            if texto:
                return texto
    return ""


def _devolucao_conhecidos(rows: list[dict[str, Any]]) -> set[str]:
    """Códigos do Precificador só quando algum SKU tem barra (revisão 27/10: uma leitura por lote)."""
    if any("/" in str(r.get("SKU") or r.get("Sku") or "") for r in rows):
        return _separacao_codigos_conhecidos()
    return set()


def _devolucao_pecas(rows: list[dict[str, Any]], conhecidos: set[str] | None = None,
                     kits: list[dict[str, Any]] | None = None) -> dict[str, dict[str, Any]]:
    """Peças vendidas no pedido: kit aberto (regra da separação), somadas por código. O código
    passa pelo normalize (revisão 27/10: "ABC 123" perdia o vínculo com o que a tela manda).
    `kits` recebe cada linha de kit (código do anúncio/EAN da embalagem → peças), para o kit
    devolvido fechado ser achado e bipado."""
    if conhecidos is None:
        conhecidos = _devolucao_conhecidos(rows)
    pecas: dict[str, dict[str, Any]] = {}
    for r in rows:
        qtd = _devolucao_qtd(r.get("Quantidade"))
        sku_linha = r.get("SKU") or r.get("Sku")
        partes = [(normalize(c), un) for c, un in _separacao_partes(sku_linha, conhecidos) if normalize(c)]
        if not partes or not qtd:
            continue
        kit = len(partes) > 1 or partes[0][1] != 1
        desc = str(r.get("Descrição") or r.get("Descricao") or "").strip()
        ean_linha = normalize(r.get("Código de Barras") or r.get("EAN"))
        ean = "" if kit else ean_linha
        for cod, un in partes:
            p = pecas.setdefault(cod, {"sku": cod, "descricao": "", "ean": "", "qtd_vendida": 0})
            p["qtd_vendida"] += qtd * un
            p["descricao"] = p["descricao"] or (("Peça do kit: " if kit else "") + desc if desc else "")
            p["ean"] = p["ean"] or ean
        if kit and kits is not None:
            kits.append({"sku": normalize(sku_linha), "ean": ean_linha, "descricao": desc,
                         "pecas": [[c, un] for c, un in partes]})
    return pecas


def _devolucao_ml_ids(rows: list[dict[str, Any]]) -> str:
    ids = {normalize(r.get(c)) for r in rows
           for c in ("VendaMercadoLivre", "PackIdMercadoLivre", "ShipmentIdMercadoLivre")}
    ids.discard("")
    return ("," + ",".join(sorted(ids)) + ",") if ids else ""


# Revisão da correção (27/10): a cada boot o migrate_completion_history recria, a partir do audit_log,
# uma conclusão com as linhas vazias ("[]") e outro horário — com id maior que a real. Ela nunca é
# "a conclusão mais nova" do pedido para as Devoluções.
DEVOLUCAO_COM_LINHAS = "payload NOT IN ('', '[]')"


def _devolucao_ultima_conclusao(order_key: str) -> int | None:
    """Id da conclusão mais nova do pedido que tem as linhas. Chamar sob o DB_LOCK."""
    r = DB.execute(f"SELECT MAX(id) FROM order_completion_history WHERE order_key=? AND {DEVOLUCAO_COM_LINHAS}",
                   (order_key,)).fetchone()
    return int(r[0]) if r and r[0] is not None else None


def _devolucao_corte() -> str:
    return (datetime.now(timezone.utc) - timedelta(days=DEVOLUCAO_DIAS)).isoformat()


def devolucao_indexar() -> int:
    """Põe no índice de busca um lote de conclusões ainda não indexadas, **da mais nova para a
    mais antiga** (revisão 27/10: logo depois do deploy o pedido de ontem não era achado e virava
    "sem pedido"). Uma indexação por vez; quem acha a vez ocupada não espera. Devolve quantas
    conclusões leu (menos que o lote = em dia)."""
    if not DEVOLUCAO_INDICE_LOCK.acquire(blocking=False):
        return 0
    try:
        return _devolucao_indexar_lote()
    finally:
        DEVOLUCAO_INDICE_LOCK.release()


def _devolucao_indexar_lote() -> int:
    corte = _devolucao_corte()
    lote = DEVOLUCAO_INDICE_LOTE
    with DB_LOCK:
        r = DB.execute("SELECT piso_hist_id FROM devolucao_indice_v1988 WHERE id=1").fetchone()
        piso = int(r[0]) if r else 0
        topo = int(DB.execute("SELECT COALESCE(MAX(id),0) FROM order_completion_history").fetchone()[0])
        # Tudo até o piso já está no índice; acima dele, o que falta, mais novo primeiro.
        hist = [dict(x) for x in DB.execute(
            "SELECT h.id, h.order_key, h.order_id, h.completed_at FROM order_completion_history h "
            "WHERE h.id>? AND h.id<=? AND h.completed_at>=? "
            "AND NOT EXISTS (SELECT 1 FROM devolucao_indexado_v1988 x WHERE x.hist_id=h.id) "
            "ORDER BY h.id DESC LIMIT ?", (piso, topo, corte, lote)).fetchall()]
        # Só a conclusão mais nova de cada pedido vale (o pedido concluído de novo troca as peças).
        validos = [h for h in hist if _devolucao_ultima_conclusao(h["order_key"]) == h["id"]]
        payloads = {int(x[0]): x[1] for x in DB.execute(
            f"SELECT id, payload FROM order_completion_history WHERE id IN ({','.join('?' * len(validos))})",
            [h["id"] for h in validos]).fetchall()} if validos else {}
    linhas_por_hist = {h["id"]: _rows_from_storage_value(payloads.get(h["id"])) for h in validos}
    todas = [r for rows in linhas_por_hist.values() for r in rows]
    conhecidos = _devolucao_conhecidos(todas)   # uma leitura do Precificador por lote
    por_pedido: dict[str, tuple[int, list[tuple]]] = {}
    for h in validos:
        rows = linhas_por_hist[h["id"]]
        if not rows:
            continue   # conclusão antiga reconstruída do audit_log (sem as linhas): não apaga nada
        try:
            kits: list[dict[str, Any]] = []
            pecas = _devolucao_pecas(rows, conhecidos, kits)
        except Exception as exc:
            print(f"[devolucoes] índice {h['order_key']}: {exc}", flush=True)
            continue
        cliente = _devolucao_cliente(rows)
        nomes = _devolucao_texto_busca(" ".join(
            str(r.get(c) or "") for r in rows for c in ("Cliente", "Nome Conferência", "NomeFiscalMercadoLivre")))
        filial = filial_da_linha(rows[0])
        mp = _vendas_marketplace(rows[0].get("Marketplace") or rows[0].get("Origem"))
        ml_ids = _devolucao_ml_ids(rows)
        codigos = {(p["sku"], p["ean"]) for p in pecas.values()} | {(k["sku"], k["ean"]) for k in kits}
        por_pedido[h["order_key"]] = (h["id"], [
            (h["order_key"], h["order_id"], filial, mp, h["completed_at"], sku, ean, cliente, nomes, ml_ids)
            for sku, ean in sorted(codigos) if sku])
    with DB_LOCK:
        DB.execute("BEGIN IMMEDIATE")
        try:
            for chave, (hist_id, linhas) in por_pedido.items():
                # Relido sob a trava: uma conclusão mais nova chegou no meio? ela é que indexa.
                if _devolucao_ultima_conclusao(chave) != hist_id:
                    continue
                DB.execute("DELETE FROM devolucao_busca_v1988 WHERE order_key=?", (chave,))
                DB.executemany(
                    "INSERT INTO devolucao_busca_v1988(order_key,pedido,filial,marketplace,concluido_em,sku,ean,"
                    "cliente,cliente_busca,ml_ids) VALUES(?,?,?,?,?,?,?,?,?,?)", linhas)
            DB.executemany("INSERT OR IGNORE INTO devolucao_indexado_v1988(hist_id) VALUES(?)",
                           [(h["id"],) for h in hist])
            if len(hist) < lote:
                # Em dia até o topo: o piso sobe, as marcas abaixo dele e o que passou dos 180 dias saem.
                DB.execute("INSERT INTO devolucao_indice_v1988(id,piso_hist_id) VALUES(1,?) "
                           "ON CONFLICT(id) DO UPDATE SET piso_hist_id=MAX(piso_hist_id, excluded.piso_hist_id)",
                           (topo,))
                DB.execute("DELETE FROM devolucao_indexado_v1988 WHERE hist_id<=?", (topo,))
                DB.execute("DELETE FROM devolucao_busca_v1988 WHERE concluido_em<?", (corte,))
            DB.commit()
        except Exception:
            DB.rollback()
            raise
    return len(hist)


def _devolucao_indexar_tudo(maximo: int = 5) -> None:
    for _ in range(maximo):
        if devolucao_indexar() < DEVOLUCAO_INDICE_LOTE:
            return


def devolucoes_indice_loop(stop_event: threading.Event) -> None:
    """Mantém o índice de busca em dia (a busca também indexa um lote antes de procurar)."""
    while not stop_event.is_set():
        try:
            _devolucao_indexar_tudo(maximo=20)
        except Exception as exc:
            print(f"[devolucoes] índice: {exc}", flush=True)
        stop_event.wait(300)


def _devolucao_mapa_ean() -> dict[str, dict[str, set[str]]]:
    """EAN → SKU e SKU → EAN pelo cadastro de produtos (refeito só quando o cadastro muda).
    Revisão 27/10: sob trava própria — duas buscas juntas não leem o mapa pela metade."""
    with DB_LOCK:
        r = DB.execute("SELECT version FROM storage WHERE key='conf_produtos'").fetchone()
    versao = int(r[0]) if r else 0
    with _DEVOLUCAO_EAN_LOCK:
        if _DEVOLUCAO_EAN_CACHE.get("versao") != versao:
            with DB_LOCK:
                bruto, _, _ = get_storage("conf_produtos")
            mapa: dict[str, set[str]] = {}
            por_sku: dict[str, set[str]] = {}
            for p in _rows_from_storage_value(bruto):
                codigo, sku = normalize(p.get("Código de Barras") or p.get("EAN")), normalize(p.get("SKU"))
                if codigo and sku:
                    mapa.setdefault(codigo, set()).add(sku)
                    por_sku.setdefault(sku, set()).add(codigo)
            _DEVOLUCAO_EAN_CACHE.clear()
            _DEVOLUCAO_EAN_CACHE.update({"versao": versao, "ean": mapa, "sku": por_sku})
        return {"ean": _DEVOLUCAO_EAN_CACHE["ean"], "sku": _DEVOLUCAO_EAN_CACHE["sku"]}


def _devolucao_skus_do_ean(ean: str) -> set[str]:
    return set(_devolucao_mapa_ean()["ean"].get(ean, set()))


def _devolucao_codigo_do_qr(q: Any) -> Any:
    """O QR da etiqueta do Mercado Envios traz um JSON ({"id": "4455...", ...}): vale o id."""
    texto = str(q or "").strip()
    if texto.startswith("{"):
        try:
            dados = json.loads(texto)
        except ValueError:
            return texto
        if isinstance(dados, dict):
            for campo in ("id", "shipment_id", "tracking_number"):
                if dados.get(campo):
                    return str(dados[campo])
    return texto


DEVOLUCAO_BUSCA_LIMITE = 30


def devolucao_buscar(q: Any, filial: str) -> dict[str, Any]:
    """Pedidos concluídos que batem com o bip: nº do pedido, EAN, SKU, nome do cliente ou a
    etiqueta de devolução do ML. Só a filial de quem busca ("todas" = as duas)."""
    if not DEVOLUCAO_INDICE_LOCK.locked():   # um lote só; o worker faz o resto
        devolucao_indexar()
    q = _devolucao_codigo_do_qr(q)
    r = _devolucao_buscar(q, filial, combinar=True)
    if r.get("combinada") and not r["pedidos"]:
        # "ABC 123" pode ser um código com espaço (revisão 27/10): sem resultado, vale o texto inteiro.
        r = _devolucao_buscar(q, filial, combinar=False)
    r.pop("combinada", None)
    if not r["pedidos"]:
        # V19.91: etiqueta de devolução do ML sem reclamação gravada — pergunta ao ML de qual venda é o envio.
        venda = _devolucao_venda_do_envio_ml(q)
        if venda:
            r = _devolucao_buscar(venda, filial, combinar=False)
            r.pop("combinada", None)
            r["etiqueta_ml"] = normalize(q)
            r["codigo"] = ""   # a etiqueta não é peça: nada de +1 automático
        if not r["pedidos"]:
            # V19.93: retorno do Full (venda que nunca passou pela Conferência) — só por número, nunca por nome/peça.
            pedidos = _devolucao_vendas_sem_conferencia([normalize(q), venda], filial)
            numero = normalize(q)
            alvo = venda or (numero if numero.isdigit() and len(numero) == 16 else "")
            if not pedidos and alvo and _devolucao_ler_venda_ml(alvo):   # V19.94: venda cancelada
                pedidos = _devolucao_vendas_sem_conferencia([alvo], filial)
            if pedidos:
                r = {"ok": True, "pedidos": pedidos, "mais": False, "codigo": "",
                     **({"etiqueta_ml": normalize(q)} if venda else {})}
    return r


# V19.93 (dono, 27/10): devolução de venda do Full. A venda Full sai do armazém do ML e nunca é concluída na
# Conferência, então não está no índice. A venda vem das vendas do ML já copiadas (vendas_v1799 = Araçatuba,
# vendas_conta_v1898 = outras contas), sem o nome do cliente. Chave própria (prefixo) para nunca colidir com um
# pedido da fila; pedido conferido (pela venda ou pelo carrinho) nunca aparece de novo por aqui.
DEVOLUCAO_VENDA_PREFIXO = "VENDAML"


def _devolucao_linhas_venda_ml(numero: str) -> list[dict[str, Any]]:
    """Linhas de venda do ML pelo nº da venda ou do carrinho. Chamar sob o DB_LOCK."""
    linhas = [dict(r, conta=CASA_PRINCIPAL) for r in DB.execute(
        "SELECT order_id, pack_id, sale_at, sku, anuncio, title, qty FROM vendas_v1799 "
        "WHERE marketplace='ml' AND (order_id=? OR pack_id=?)", (numero, numero)).fetchall()]
    linhas += [dict(r) for r in DB.execute(
        "SELECT conta, order_id, pack_id, sale_at, sku, anuncio, title, qty FROM vendas_conta_v1898 "
        "WHERE marketplace='ml' AND (order_id=? OR pack_id=?)", (numero, numero)).fetchall()]
    vistas = {str(l["order_id"]) for l in linhas}
    for r in DB.execute("SELECT order_id, conta, status, linhas_json FROM devolucao_venda_ml_v1994 "
                        "WHERE order_id=? OR (pack_id<>'' AND pack_id=?)", (numero, numero)).fetchall():
        if str(r["order_id"]) in vistas:
            continue   # a cópia das vendas manda quando existe
        try:
            guardadas = json.loads(r["linhas_json"] or "[]")
        except ValueError:
            guardadas = []
        linhas += [dict(l, conta=r["conta"], status=r["status"]) for l in guardadas if isinstance(l, dict)]
    return linhas


# V19.94 (caso real 27/10): devolução com reembolso costuma CANCELAR a venda, e a venda cancelada some de
# vendas_v1799 (a janela é regravada). Etiqueta 48323000393 → venda Full 2000019080231218 cancelada: nada achava.
# Só para número que já é uma venda (o da etiqueta, ou 16 dígitos sem resultado): lê /orders/{id} nas contas
# conectadas uma vez e guarda em devolucao_venda_ml_v1994; "não existe" fica 30 min na memória. Erro = não achou.
_DEVOLUCAO_PEDIDO_FALTA: dict[str, float] = {}


def _devolucao_ler_venda_ml(order_id: str) -> bool:
    order_id = normalize(order_id)
    if not (order_id.isdigit() and len(order_id) >= 10):
        return False
    with DB_LOCK:
        if DB.execute("SELECT 1 FROM devolucao_venda_ml_v1994 WHERE order_id=?", (order_id,)).fetchone():
            return True
    agora = time.time()
    with _DEVOLUCAO_ENVIO_LOCK:
        if _DEVOLUCAO_PEDIDO_FALTA.get(order_id, 0) > agora:
            return False
    try:
        casas = ml_casas_conectadas()
    except Exception:
        casas = []
    for casa in casas:
        try:
            with ml_na_casa(casa):
                d = ml_api_get(f"/orders/{quote(order_id)}")
        except Exception:
            continue
        if not (isinstance(d, dict) and str(d.get("id") or "") == order_id):
            continue
        linhas = []
        for it in d.get("order_items") or []:
            if not isinstance(it, dict):
                continue
            item = it.get("item") if isinstance(it.get("item"), dict) else {}
            sku = str(item.get("seller_sku") or item.get("seller_custom_field") or "").strip()
            if not sku:
                continue
            linhas.append({"order_id": order_id, "pack_id": str(d.get("pack_id") or ""),
                           "sale_at": str(d.get("date_created") or ""), "sku": sku, "anuncio": str(item.get("id") or ""),
                           "title": str(item.get("title") or ""), "qty": it.get("quantity") or 0,
                           "preco": it.get("unit_price")})   # V19.97: valor da devolução
        if not linhas:
            break
        with DB_LOCK:
            DB.execute("INSERT OR REPLACE INTO devolucao_venda_ml_v1994(order_id,pack_id,conta,status,linhas_json,lido_em) "
                       "VALUES(?,?,?,?,?,?)", (order_id, str(d.get("pack_id") or ""), casa, str(d.get("status") or ""),
                                               json.dumps(linhas, ensure_ascii=False), now_iso()))
            DB.commit()
        return True
    with _DEVOLUCAO_ENVIO_LOCK:
        if len(_DEVOLUCAO_PEDIDO_FALTA) > 2000:
            _DEVOLUCAO_PEDIDO_FALTA.clear()
        _DEVOLUCAO_PEDIDO_FALTA[order_id] = agora + DEVOLUCAO_ENVIO_CACHE_SEG
    return False


def _devolucao_venda_full(anuncios: set[str]) -> bool:
    """Chamar sob o DB_LOCK."""
    anuncios = {a for a in anuncios if a}
    if not anuncios:
        return False
    return DB.execute(f"SELECT 1 FROM ml_estoque_dia_v1872 WHERE logistica='fulfillment' AND item_id IN "
                      f"({','.join('?' * len(anuncios))}) LIMIT 1", sorted(anuncios)).fetchone() is not None


def _devolucao_vendas_sem_conferencia(numeros: list[Any], filial: str) -> list[dict[str, Any]]:
    vistos: set[str] = set()
    pedidos: list[dict[str, Any]] = []
    with DB_LOCK:
        for numero in numeros:
            numero = normalize(numero)
            if not (numero.isdigit() and len(numero) >= 10):
                continue
            por_venda: dict[str, list[dict[str, Any]]] = {}
            for l in _devolucao_linhas_venda_ml(numero):
                por_venda.setdefault(str(l["order_id"]), []).append(l)
            for order_id, linhas in por_venda.items():
                if order_id in vistos:
                    continue
                vistos.add(order_id)
                pack = str(linhas[0]["pack_id"] or "")
                conferido = DB.execute("SELECT 1 FROM completed_orders WHERE order_key IN (?,?)",
                                       (order_id, pack or order_id)).fetchone()
                if conferido:
                    continue
                conta = str(linhas[0]["conta"] or CASA_PRINCIPAL)
                if filial != FILIAL_TODAS and conta != filial:
                    continue
                chave = DEVOLUCAO_VENDA_PREFIXO + order_id
                devolvidas = DB.execute("SELECT COUNT(*) FROM devolucao_v1988 WHERE order_key=?", (chave,)).fetchone()[0]
                pedidos.append({
                    "chave": chave, "pedido": order_id, "marketplace": "Mercado Livre", "filial": conta,
                    "concluido_em": str(linhas[0]["sale_at"] or ""), "cliente": "",
                    "skus": sorted({normalize(l["sku"]) for l in linhas if l["sku"]}),
                    "devolucoes": int(devolvidas or 0), "venda_sem_conferencia": True,
                    "full": _devolucao_venda_full({str(l["anuncio"] or "") for l in linhas}), "carrinho": pack,
                    "cancelada": any(str(l.get("status") or "") == "cancelled" for l in linhas)})
    return pedidos


def _devolucao_pedido_venda_ml(key: str, filial: str) -> dict[str, Any]:
    order_id = key[len(DEVOLUCAO_VENDA_PREFIXO):]
    with DB_LOCK:
        linhas = [l for l in _devolucao_linhas_venda_ml(order_id) if str(l["order_id"]) == order_id]
        full = _devolucao_venda_full({str(l["anuncio"] or "") for l in linhas})
    if not linhas:
        raise ValueError("Venda não encontrada.")
    conta = str(linhas[0]["conta"] or CASA_PRINCIPAL)
    if filial != FILIAL_TODAS and conta != filial:
        raise PermissionError(f"A venda {order_id} é de outra filial.")
    rows = [{"Pedido": order_id, "SKU": l["sku"], "Quantidade": l["qty"], "Descrição": l["title"] or "",
             "Marketplace": "MERCADO LIVRE", "Casa": conta} for l in linhas]
    kits: list[dict[str, Any]] = []
    pecas = _devolucao_pecas(rows, kits=kits)
    with DB_LOCK:
        ja = _devolucao_ja_devolvido(key)
    eans = _devolucao_mapa_ean()["sku"]
    itens = [{**p, "qtd_devolvida": ja.get(p["sku"], 0),
              "eans": sorted({normalize(p["ean"])} - {""} | eans.get(p["sku"], set()))} for p in pecas.values()]
    kits_tela = [{"sku": k["sku"], "descricao": k["descricao"], "pecas": k["pecas"],
                  "codigos": sorted({k["sku"], k["ean"]} - {""} | eans.get(k["sku"], set()))} for k in kits]
    return {"ok": True, "chave": key, "pedido": order_id, "filial": conta, "marketplace": "Mercado Livre",
            "cliente": "", "data": str(linhas[0]["sale_at"] or "")[:10], "concluido_em": str(linhas[0]["sale_at"] or ""),
            "itens": itens, "kits": kits_tela, "venda_sem_conferencia": True, "full": full,
            "cancelada": any(str(l.get("status") or "") == "cancelled" for l in linhas),
            "carrinho": str(linhas[0]["pack_id"] or "")}


# V19.91 (dono, 27/10): a etiqueta de devolução traz o nº do envio de volta (11 dígitos). O /shipments/{id} desse
# envio responde type=return com o order_id (conferido em produção com 48308414462); não depende das reclamações.
# Só número com cara de envio (10 a 12 dígitos: EAN-13, EAN-8 e nº de venda de 16 ficam de fora), uma consulta por
# conta conectada, resposta (e "não existe") guardada 30 min. Erro do ML = não achou; nunca trava a busca.
DEVOLUCAO_ENVIO_CACHE_SEG = 1800
_DEVOLUCAO_ENVIO_CACHE: dict[str, tuple[float, str]] = {}
_DEVOLUCAO_ENVIO_LOCK = threading.Lock()


def _devolucao_venda_do_envio_ml(q: Any) -> str:
    numero = normalize(q)
    if not (numero.isdigit() and 10 <= len(numero) <= 12):
        return ""
    agora = time.time()
    with _DEVOLUCAO_ENVIO_LOCK:
        guardado = _DEVOLUCAO_ENVIO_CACHE.get(numero)
        if guardado and guardado[0] > agora:
            return guardado[1]
    venda = ""
    try:
        casas = ml_casas_conectadas()
    except Exception:
        casas = []
    for casa in casas:
        try:
            with ml_na_casa(casa):
                d = ml_api_get(f"/shipments/{quote(numero)}")
        except Exception:
            continue
        if isinstance(d, dict) and d.get("order_id"):
            venda = str(d["order_id"])
            break
    with _DEVOLUCAO_ENVIO_LOCK:
        if len(_DEVOLUCAO_ENVIO_CACHE) > 2000:
            _DEVOLUCAO_ENVIO_CACHE.clear()
        _DEVOLUCAO_ENVIO_CACHE[numero] = (agora + DEVOLUCAO_ENVIO_CACHE_SEG, venda)
    return venda


def _devolucao_buscar(q: Any, filial: str, combinar: bool) -> dict[str, Any]:
    # V19.90 (dono, 27/10): peça que vende muito enche os 30 da lista em poucos dias. "Código + nome"
    # ("0893117732 rafael", em qualquer ordem) exige os dois: a peça bipada E o nome do cliente.
    partes = str(q or "").split()
    codigos = [x for x in partes if any(ch.isdigit() for ch in x) and len(normalize(x)) >= 2]
    nomes = [x for x in partes if x not in codigos]
    combinada = combinar and len(partes) > 1 and bool(codigos) and any(
        len(w) >= 3 and w.isalpha() for w in _devolucao_texto_busca(" ".join(nomes)).split())
    chave = normalize(codigos[0] if combinada else q)
    texto = _devolucao_texto_busca(" ".join(nomes) if combinada else q)
    if len(chave) < 2:
        return {"ok": True, "pedidos": [], "mais": False, "codigo": ""}
    skus = {chave}
    if chave.isdigit():
        skus |= _devolucao_skus_do_ean(chave)
    corte = _devolucao_corte()
    filtro_filial = "" if filial == FILIAL_TODAS else " AND filial=?"
    base = [corte] + ([] if filial == FILIAL_TODAS else [filial])
    with DB_LOCK:
        envios = [str(r[0]) for r in DB.execute(
            "SELECT order_id FROM ml_reclamacao_v1888 WHERE devolucao_envios LIKE ? ESCAPE '\\' AND order_id<>''",
            (f"%,{_devolucao_like(chave)},%",)).fetchall()] if chave.isalnum() else []
        ml = {chave} | {normalize(x) for x in envios}
        conds = ["order_key=?", "ean=?", f"sku IN ({','.join('?' * len(skus))})"]
        params: list[Any] = [chave, chave, *sorted(skus)]
        for x in sorted(ml):
            conds.append("ml_ids LIKE ? ESCAPE '\\'")
            params.append(f"%,{_devolucao_like(x)},%")
        # Nome: só palavras de 3+ letras (revisão 27/10: "a e i" casava com quase todo cliente).
        palavras = [p for p in texto.split() if len(p) >= 3]
        nome_cond = ""
        if palavras and any(ch.isalpha() for ch in "".join(palavras)):
            nome_cond = "(" + " AND ".join("cliente_busca LIKE ? ESCAPE '\\'" for _ in palavras) + ")"
        if combinada:   # V19.90: peça E nome
            onde = f"({' OR '.join(conds)}) AND {nome_cond}"
            params.extend(f"%{_devolucao_like(p)}%" for p in palavras)
        else:
            if nome_cond:
                conds.append(nome_cond)
                params.extend(f"%{_devolucao_like(p)}%" for p in palavras)
            onde = f"({' OR '.join(conds)})"
        # Pedido reaberto (voltou para a Conferência) não aparece até ser concluído de novo.
        chaves = [r[0] for r in DB.execute(
            f"SELECT DISTINCT order_key FROM devolucao_busca_v1988 WHERE concluido_em>=?{filtro_filial} "
            f"AND {onde} AND order_key IN (SELECT order_key FROM completed_orders) "
            f"ORDER BY concluido_em DESC LIMIT {DEVOLUCAO_BUSCA_LIMITE + 1}",
            (*base, *params)).fetchall()]
        mais = len(chaves) > DEVOLUCAO_BUSCA_LIMITE   # V19.90: a tela pede o nome do cliente
        chaves = chaves[:DEVOLUCAO_BUSCA_LIMITE]
        if not chaves:
            return {"ok": True, "pedidos": [], "mais": False, "codigo": chave, "combinada": combinada}
        marcas = ",".join("?" * len(chaves))
        linhas = [dict(r) for r in DB.execute(
            f"SELECT * FROM devolucao_busca_v1988 WHERE order_key IN ({marcas})", chaves).fetchall()]
        devolvidos = {r[0]: int(r[1] or 0) for r in DB.execute(
            f"SELECT order_key, COUNT(*) FROM devolucao_v1988 WHERE order_key IN ({marcas}) GROUP BY order_key",
            chaves).fetchall()}
    pedidos: dict[str, dict[str, Any]] = {}
    for r in linhas:
        p = pedidos.setdefault(r["order_key"], {
            "chave": r["order_key"], "pedido": r["pedido"], "marketplace": r["marketplace"],
            "filial": r["filial"], "concluido_em": r["concluido_em"], "cliente": r["cliente"],
            "skus": [], "devolucoes": devolvidos.get(r["order_key"], 0)})
        p["skus"].append(r["sku"])
    return {"ok": True, "pedidos": sorted(pedidos.values(), key=lambda p: p["concluido_em"], reverse=True),
            "mais": mais, "codigo": chave, "combinada": combinada}


def _devolucao_ja_devolvido(order_key: str, ignorar_itens: set[int] | None = None) -> dict[str, int]:
    """Unidades que já voltaram por peça (todas as devoluções do pedido). Chamar sob o DB_LOCK."""
    soma: dict[str, int] = {}
    for r in DB.execute(
            "SELECT i.id, i.sku, i.qtd FROM devolucao_item_v1988 i JOIN devolucao_v1988 d ON d.id=i.devolucao_id "
            "WHERE d.order_key=? AND d.sem_pedido=0 AND i.fora_da_venda=0", (order_key,)).fetchall():
        if ignorar_itens and int(r["id"]) in ignorar_itens:
            continue
        soma[r["sku"]] = soma.get(r["sku"], 0) + int(r["qtd"] or 0)
    return soma


def devolucao_pedido(chave: Any, filial: str) -> dict[str, Any]:
    """A venda do pedido concluído, peça por peça, com o que já voltou."""
    key = normalize(chave)
    if key.startswith(DEVOLUCAO_VENDA_PREFIXO):   # V19.93: venda do ML que não passou pela Conferência (Full)
        return _devolucao_pedido_venda_ml(key, filial)
    with DB_LOCK:
        h = DB.execute("SELECT order_key,order_id,completed_at,completed_by,payload FROM order_completion_history "
                       f"WHERE order_key=? AND {DEVOLUCAO_COM_LINHAS} ORDER BY id DESC LIMIT 1", (key,)).fetchone()
        concluido = DB.execute("SELECT 1 FROM completed_orders WHERE order_key=?", (key,)).fetchone()
    rows = _rows_from_storage_value(h["payload"]) if h else []
    if not rows or not concluido:   # revisão 27/10: reaberto (de volta na Conferência) não recebe devolução
        raise ValueError("Pedido concluído não encontrado.")
    filial_pedido = filial_da_linha(rows[0])
    if filial != FILIAL_TODAS and filial_pedido != filial:
        raise PermissionError(f"O pedido {h['order_id']} é de outra filial.")
    kits: list[dict[str, Any]] = []
    pecas = _devolucao_pecas(rows, kits=kits)
    with DB_LOCK:
        ja = _devolucao_ja_devolvido(key)
    eans = _devolucao_mapa_ean()["sku"]   # para o bip na tela achar a peça pelo código de barras
    itens = [{**p, "qtd_devolvida": ja.get(p["sku"], 0),
              "eans": sorted({normalize(p["ean"])} - {""} | eans.get(p["sku"], set()))} for p in pecas.values()]
    # Revisão 27/10: kit devolvido fechado — bipar a embalagem (código do anúncio ou EAN do kit) soma as peças.
    kits_tela = [{"sku": k["sku"], "descricao": k["descricao"], "pecas": k["pecas"],
                  "codigos": sorted({k["sku"], k["ean"]} - {""} | eans.get(k["sku"], set()))} for k in kits]
    primeira = rows[0]
    return {"ok": True, "chave": key, "pedido": h["order_id"], "filial": filial_pedido,
            "marketplace": _vendas_marketplace(primeira.get("Marketplace") or primeira.get("Origem")),
            "cliente": _devolucao_cliente(rows), "data": str(primeira.get("Data do Pedido") or ""),
            "concluido_em": h["completed_at"], "itens": itens, "kits": kits_tela}


def _devolucao_itens_validos(itens: Any, corrigir: bool = False) -> list[dict[str, Any]]:
    if not isinstance(itens, list) or not itens:
        raise ValueError("Informe as peças que voltaram.")
    if len(itens) > DEVOLUCAO_MAX_ITENS:
        raise ValueError(f"No máximo {DEVOLUCAO_MAX_ITENS} peças por devolução.")
    saida = []
    for it in itens:
        if not isinstance(it, dict):
            raise ValueError("Peça inválida.")
        sku = normalize(it.get("sku"))
        if not sku and not corrigir:
            raise ValueError("Peça sem código.")
        if len(sku) > DEVOLUCAO_MAX_CODIGO:
            raise ValueError("Código da peça grande demais.")
        try:
            qtd = int(it.get("qtd"))
        except (TypeError, ValueError):
            raise ValueError(f"{sku}: quantidade inválida.")
        # Revisão 27/10: na correção o admin zera a peça lançada por engano (a cota volta).
        if qtd < (0 if corrigir else 1) or qtd > 9999:
            raise ValueError(f"{sku}: quantidade inválida.")
        estado = str(it.get("estado") or "").strip().lower()
        if estado not in ("bom", "ruim"):
            raise ValueError(f"{sku}: marque o estado da peça (bom ou ruim).")
        motivo = str(it.get("motivo") or "").strip().lower() if estado == "ruim" else ""
        if estado == "ruim" and motivo not in DEVOLUCAO_MOTIVOS:
            raise ValueError(f"{sku}: peça ruim precisa do motivo.")
        saida.append({"id": it.get("id"), "sku": sku, "qtd": qtd, "estado": estado, "motivo": motivo,
                      "obs": str(it.get("obs") or "").strip()[:300]})
    return saida


def _devolucao_evento(dev_id: int, quem: str, acao: str, detalhe: dict[str, Any]) -> None:
    DB.execute("INSERT INTO devolucao_evento_v1988(devolucao_id,quando,quem,acao,detalhe) VALUES(?,?,?,?,?)",
               (dev_id, now_iso(), quem, acao, json_dumps(detalhe)))


def _devolucao_repetida(dev_id: int) -> dict[str, Any]:
    """O mesmo "Concluir" chegou de novo. Devolve o que FOI gravado na 1ª vez — a tela avisa se o
    operador acrescentou peça depois da falha (essa não entrou). Chamar sob o DB_LOCK."""
    d = _devolucao_ler(dev_id) or {"itens": []}
    return {"ok": True, "id": dev_id, "repetida": True,
            "itens": [{"sku": i["sku"], "qtd": i["qtd"], "estado": i["estado"]} for i in d["itens"]]}


def devolucao_registrar(req: dict[str, Any], usuario: str, filial: str) -> dict[str, Any]:
    """O operador concluiu a conferência da devolução. Nunca toca no pedido nem na fila."""
    token = str(req.get("token") or "").strip()[:80]
    if token:   # antes da venda: o pedido pode ter sido reaberto entre as duas tentativas
        with DB_LOCK:
            ja_feita = DB.execute("SELECT id FROM devolucao_v1988 WHERE token=?", (token,)).fetchone()
            if ja_feita:
                return _devolucao_repetida(int(ja_feita[0]))
    itens = _devolucao_itens_validos(req.get("itens"))
    obs = str(req.get("obs") or "").strip()[:500]
    if req.get("sem_pedido"):
        cliente = str(req.get("cliente") or "").strip()[:120]
        if not cliente:
            raise ValueError("Sem pedido: informe o nome do cliente.")
        destino = filial if filial in CASAS else str(req.get("filial") or "").strip().lower()
        if destino not in CASAS:   # revisão 27/10: quem vê "todas" escolhe (antes caía sempre em Araçatuba)
            raise ValueError("Sem pedido: escolha a filial que recebeu a devolução.")
        cab = {"filial": destino, "marketplace": "",
               "pedido": str(req.get("pedido") or "").strip()[:60], "order_key": "", "cliente": cliente,
               "sem_pedido": 1}
        venda: dict[str, dict[str, Any]] = {}
    else:
        v = devolucao_pedido(req.get("chave"), filial)
        cab = {"filial": v["filial"], "marketplace": v["marketplace"], "pedido": v["pedido"],
               "order_key": v["chave"], "cliente": v["cliente"], "sem_pedido": 0}
        venda = {i["sku"]: i for i in v["itens"]}
    agora = now_iso()
    with DB_LOCK:
        DB.execute("BEGIN IMMEDIATE")
        try:
            if token:   # revisão 27/10: "Concluir" repetido depois de perder a resposta = a mesma devolução
                ja_feita = DB.execute("SELECT id FROM devolucao_v1988 WHERE token=?", (token,)).fetchone()
                if ja_feita:
                    DB.rollback()
                    return _devolucao_repetida(int(ja_feita[0]))
            # Relido sob a trava: dois operadores ao mesmo tempo não passam do vendido.
            ja = _devolucao_ja_devolvido(cab["order_key"]) if venda else {}
            novo: dict[str, int] = {}
            for it in itens:
                if it["sku"] in venda:
                    novo[it["sku"]] = novo.get(it["sku"], 0) + it["qtd"]
            for sku, qtd in novo.items():
                vendida = int(venda[sku]["qtd_vendida"])
                if ja.get(sku, 0) + qtd > vendida:
                    raise ValueError(f"{sku}: voltou mais do que foi vendido (vendido {vendida}, "
                                     f"já devolvido {ja.get(sku, 0)}).")
            cur = DB.execute(
                "INSERT INTO devolucao_v1988(filial,marketplace,pedido,order_key,cliente,sem_pedido,situacao,obs,"
                "recebido_por,recebido_em,versao,token) VALUES(?,?,?,?,?,?,'a_tratar',?,?,?,1,?)",
                (cab["filial"], cab["marketplace"], cab["pedido"], cab["order_key"], cab["cliente"],
                 cab["sem_pedido"], obs, usuario, agora, token))
            dev_id = int(cur.lastrowid)
            for it in itens:
                p = venda.get(it["sku"])
                DB.execute(
                    "INSERT INTO devolucao_item_v1988(devolucao_id,sku,descricao,ean,qtd_vendida,qtd,estado,motivo,obs,"
                    "fora_da_venda) VALUES(?,?,?,?,?,?,?,?,?,?)",
                    (dev_id, it["sku"], (p or {}).get("descricao", ""), (p or {}).get("ean", ""),
                     (p or {}).get("qtd_vendida"), it["qtd"], it["estado"], it["motivo"], it["obs"],
                     0 if (p or cab["sem_pedido"]) else 1))
            _devolucao_evento(dev_id, usuario, "registrada", {"itens": itens})
            DB.commit()
        except Exception:
            DB.rollback()
            raise
    audit(usuario, "devolucao.registrar", f"{dev_id}|{cab['pedido']}")
    return {"ok": True, "id": dev_id}


def _devolucao_ler(dev_id: int) -> dict[str, Any] | None:
    """Chamar sob o DB_LOCK."""
    d = DB.execute("SELECT * FROM devolucao_v1988 WHERE id=?", (dev_id,)).fetchone()
    if d is None:
        return None
    d = dict(d)
    d["sem_pedido"] = bool(d["sem_pedido"])
    d["filial_nome"] = CASAS.get(d["filial"], d["filial"])
    d["itens"] = [{**dict(i), "fora_da_venda": bool(i["fora_da_venda"]),
                   "motivo_nome": DEVOLUCAO_MOTIVOS.get(i["motivo"], ""),
                   # V19.95: destino escolhido pelo admin; sem escolha, vem do estado (bom = estoque, ruim = perda)
                   "destino": i["destino"] or ("perda" if i["estado"] == "ruim" else "estoque"),
                   "destino_escolhido": bool(i["destino"])}
                  for i in DB.execute("SELECT * FROM devolucao_item_v1988 WHERE devolucao_id=? ORDER BY id",
                                      (dev_id,)).fetchall()]
    d["eventos"] = [{**dict(e), "detalhe": _filial_json(e["detalhe"], {})}
                    for e in DB.execute("SELECT * FROM devolucao_evento_v1988 WHERE devolucao_id=? ORDER BY id",
                                        (dev_id,)).fetchall()]
    return d


def devolucoes_lista(filtros: dict[str, Any], filial: str) -> dict[str, Any]:
    conds, params = [], []
    if filial != FILIAL_TODAS:
        conds.append("filial=?")
        params.append(filial)
    situacao = str(filtros.get("situacao") or "").strip()
    if situacao in DEVOLUCAO_SITUACOES:
        conds.append("situacao=?")
        params.append(situacao)
    mp = str(filtros.get("marketplace") or "").strip()
    if mp:
        conds.append("marketplace=?")
        params.append(mp)
    estado = str(filtros.get("estado") or "").strip().lower()
    if estado in ("bom", "ruim"):
        conds.append("id IN (SELECT devolucao_id FROM devolucao_item_v1988 WHERE estado=? AND qtd>0)")
        params.append(estado)
    mes = _devolucao_mes_valido(filtros.get("mes"))   # V19.95: devoluções que chegaram no mês
    if mes:
        ini, fim = _devolucao_faixa_mes(mes)
        conds.append("recebido_em >= ? AND recebido_em < ?")
        params += [ini, fim]
    onde = (" WHERE " + " AND ".join(conds)) if conds else ""
    with DB_LOCK:
        ids = [int(r[0]) for r in DB.execute(
            f"SELECT id FROM devolucao_v1988{onde} ORDER BY situacao='tratada', recebido_em DESC LIMIT 500",
            params).fetchall()]
        devolucoes = [_devolucao_ler(i) for i in ids]
    devolucoes = [d for d in devolucoes if d and (not mes or _devolucao_mes_br(d["recebido_em"]) == mes)][:300]
    custos_ctx = _financeiro_custos_aracatuba() if devolucoes else {}
    for d in devolucoes:
        d["valores"] = devolucao_valores(d, custos_ctx)
        cod, rot, origem = devolucao_motivo(d)   # V19.97
        d["motivo_devolucao"] = {"codigo": cod, "rotulo": rot, "origem": origem}
        d["valor_venda"] = devolucao_valor_venda(d)
    with DB_LOCK:
        contagem = {r[0]: int(r[1]) for r in DB.execute(
            "SELECT situacao, COUNT(*) FROM devolucao_v1988"
            + (" WHERE filial=?" if filial != FILIAL_TODAS else "") + " GROUP BY situacao",
            [] if filial == FILIAL_TODAS else [filial]).fetchall()}
        # V19.97: tratadas que ainda não entraram em nenhum lote de exportação
        a_exportar = int(DB.execute(
            "SELECT COUNT(*) FROM devolucao_v1988 WHERE situacao='tratada' AND exportacao_id IS NULL"
            + (" AND filial=?" if filial != FILIAL_TODAS else ""), [] if filial == FILIAL_TODAS else [filial]).fetchone()[0])
    return {"ok": True, "devolucoes": devolucoes,
            "resumo": {"a_tratar": contagem.get("a_tratar", 0), "tratada": contagem.get("tratada", 0)},
            "motivos": DEVOLUCAO_MOTIVOS, "destinos": DEVOLUCAO_DESTINOS, "motivos_dev": DEVOLUCAO_MOTIVOS_DEV,
            "a_exportar": a_exportar}


def _devolucao_para_mudar(dev_id: Any, versao: Any, filial: str) -> dict[str, Any]:
    """Relê a devolução sob o DB_LOCK (transação aberta) e confere filial e versão."""
    try:
        dev_id = int(dev_id)
    except (TypeError, ValueError):
        raise ValueError("Devolução não informada.")
    d = _devolucao_ler(dev_id)
    if d is None:
        raise ValueError("Devolução não encontrada.")
    if filial != FILIAL_TODAS and d["filial"] != filial:
        raise PermissionError("Esta devolução é de outra filial.")
    if str(versao) != str(d["versao"]):
        raise DevolucaoConflito(d)
    return d


def _devolucao_mudar(dev_id: Any, versao: Any, filial: str, usuario: str, mudar) -> dict[str, Any]:
    with DB_LOCK:
        DB.execute("BEGIN IMMEDIATE")
        try:
            d = _devolucao_para_mudar(dev_id, versao, filial)
            acao = mudar(d)
            DB.execute("UPDATE devolucao_v1988 SET versao=versao+1 WHERE id=?", (d["id"],))
            DB.commit()
        except Exception:
            DB.rollback()
            raise
        atual = _devolucao_ler(d["id"])
    audit(usuario, f"devolucao.{acao}", str(d["id"]))
    return {"ok": True, "devolucao": atual}


def devolucao_tratar(dev_id: Any, documento: Any, versao: Any, usuario: str,
                     filial: str = FILIAL_TODAS) -> dict[str, Any]:
    documento = str(documento or "").strip()[:80]
    custos_ctx = _financeiro_custos_aracatuba()   # V19.95: lido fora da trava; o custo fica congelado ao tratar

    def mudar(d: dict[str, Any]) -> str:
        nonlocal documento
        if d["situacao"] == "tratada":
            raise ValueError("Esta devolução já foi tratada.")
        if not documento:
            # Revisão da correção (27/10): peças todas zeradas (lançada por engano) = nada a lançar no Apollo.
            if any(int(i["qtd"] or 0) > 0 for i in d["itens"]):
                raise ValueError("Informe o nº do documento do Apollo.")
            documento = "nada voltou (peças zeradas)"
        DB.execute("UPDATE devolucao_v1988 SET situacao='tratada', documento_apollo=?, tratada_por=?, tratada_em=? "
                   "WHERE id=?", (documento, usuario, now_iso(), d["id"]))
        _devolucao_congelar_valores(d, custos_ctx)   # V19.95
        _devolucao_evento(d["id"], usuario, "tratada", {"documento": documento})
        return "tratar"
    return _devolucao_mudar(dev_id, versao, filial, usuario, mudar)


# V19.95 — devoluções no lucro (decisões do dono, 27/10). Perda = custo de Araçatuba das peças com destino "perda"
# + frete da devolução. O valor da venda NÃO entra (a venda cancelada já sai do faturamento). Desconhecido nunca vira
# zero: sem custo ou sem frete a perda é "incompleta" (perda=None; o Financeiro soma só a parte conhecida e conta as
# incompletas). Conta no mês em que a peça chegou; só a partir de 01/11/2026; só Araçatuba no Financeiro.
DEVOLUCAO_DESTINOS = {"estoque": "Volta ao estoque", "perda": "Perda", "garantia": "Garantia com fornecedor",
                      "desconto": "Venda com desconto"}
DEVOLUCAO_FINANCEIRO_INICIO = "2026-11-01"
DEVOLUCAO_MP_FINANCEIRO = {"Mercado Livre": "ml", "Shopee": "shopee"}


def _devolucao_mes_valido(mes: Any) -> str:
    mes = str(mes or "").strip()
    try:
        datetime.strptime(mes + "-01", "%Y-%m-%d")
        return mes
    except ValueError:
        return ""


def _devolucao_mes_seguinte(mes: str) -> str:
    a, m = int(mes[:4]), int(mes[5:7])
    return f"{a + (m == 12)}-{(m % 12) + 1:02d}"


def _devolucao_mes_anterior(mes: str) -> str:
    a, m = int(mes[:4]), int(mes[5:7])
    return f"{a - (m == 1)}-{(m - 2) % 12 + 1:02d}"


def _devolucao_faixa_mes(mes: str) -> tuple[str, str]:
    """Faixa larga em texto (um dia de folga de cada lado: o fuso do texto gravado varia); o corte certo é
    _devolucao_mes_br."""
    ini = (datetime.strptime(mes + "-01", "%Y-%m-%d") - timedelta(days=1)).date().isoformat()
    fim = (datetime.strptime(_devolucao_mes_seguinte(mes) + "-01", "%Y-%m-%d") + timedelta(days=1)).date().isoformat()
    return ini, fim


def _devolucao_dia_br(quando: Any) -> str:
    try:
        dt = datetime.fromisoformat(str(quando or "").replace("Z", "+00:00"))
    except ValueError:
        return str(quando or "")[:10]
    if dt.tzinfo is None:
        return dt.date().isoformat()
    return dt.astimezone(BR_TZ).date().isoformat()


def _devolucao_mes_br(quando: Any) -> str:
    return _devolucao_dia_br(quando)[:7]


def _devolucao_ids_venda(d: dict[str, Any]) -> list[str]:
    """Nº do pedido, da venda, do carrinho e do envio ligados à devolução (para achar reclamação, venda e NF)."""
    chave = str(d.get("order_key") or "")
    if not chave:
        return []
    ids = {chave, normalize(d.get("pedido"))}
    if chave.startswith(DEVOLUCAO_VENDA_PREFIXO):
        ids.add(chave[len(DEVOLUCAO_VENDA_PREFIXO):])
    with DB_LOCK:
        for (ml_ids,) in DB.execute("SELECT DISTINCT ml_ids FROM devolucao_busca_v1988 WHERE order_key=?",
                                    (chave,)).fetchall():
            ids |= {x for x in str(ml_ids or "").split(",") if x}
    ids.discard("")
    return sorted(ids)


def _devolucao_frete_ml(d: dict[str, Any]) -> float | None:
    """Frete da devolução cobrado pelo ML (reclamação lida pelo Pós-venda), pelas vendas ligadas ao pedido."""
    ids = _devolucao_ids_venda(d)
    if not ids:
        return None
    with DB_LOCK:
        r = DB.execute(f"SELECT MAX(frete_devolucao) FROM ml_reclamacao_v1888 WHERE frete_devolucao IS NOT NULL "
                       f"AND order_id IN ({','.join('?' * len(ids))})", sorted(ids)).fetchone()
    return round(float(r[0]), 2) if r and r[0] is not None else None


def devolucao_valores(d: dict[str, Any], custos_ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    """Perda da devolução. custos_ctx = _financeiro_custos_aracatuba() (passar um só para uma lista)."""
    if custos_ctx is None:
        custos_ctx = _financeiro_custos_aracatuba()
    itens = []
    perda_pecas: float | None = 0.0
    perda_conhecida = 0.0
    falta = []
    for i in d["itens"]:
        qtd = int(i["qtd"] or 0)
        if i.get("custo_unit") is not None:
            custo, origem = float(i["custo_unit"]), i.get("custo_origem") or "congelado"
        else:
            custo, origem = _financeiro_custo_aracatuba(i["sku"], custos_ctx)
        perda = None
        if i["destino"] == "perda" and qtd > 0:
            if custo is None:
                perda_pecas = None
                falta.append(f"custo de {i['sku']}")
            else:
                perda = round(custo * qtd, 2)
                perda_conhecida += perda
                if perda_pecas is not None:
                    perda_pecas = round(perda_pecas + perda, 2)
        itens.append({"id": i["id"], "sku": i["sku"], "qtd": qtd, "destino": i["destino"],
                      "custo": round(custo, 4) if custo is not None else None, "custo_origem": origem or "",
                      "perda": perda})
    if d.get("frete") is not None:
        frete, frete_origem = round(float(d["frete"]), 2), d.get("frete_origem") or "digitado"
    else:
        frete = _devolucao_frete_ml(d)
        frete_origem = "ml" if frete is not None else ""
    if frete is None:
        falta.append("frete")
    else:
        perda_conhecida += frete
    total = round(perda_pecas + frete, 2) if (perda_pecas is not None and frete is not None) else None
    return {"itens": itens, "perda_pecas": perda_pecas, "frete": frete, "frete_origem": frete_origem,
            "perda": total, "perda_conhecida": round(perda_conhecida, 2), "incompleta": total is None,
            "falta": falta, "confirmada": d["situacao"] == "tratada"}


def _devolucao_congelar_valores(d: dict[str, Any], custos_ctx: dict[str, Any]) -> None:
    """Ao tratar: custo de cada peça e o frete do ML ficam gravados (o número tratado não muda depois).
    Chamar sob o DB_LOCK (dentro da transação)."""
    for i in d["itens"]:
        if not i.get("destino_escolhido"):
            DB.execute("UPDATE devolucao_item_v1988 SET destino=? WHERE id=?", (i["destino"], i["id"]))
        if i.get("custo_unit") is None:
            custo, origem = _financeiro_custo_aracatuba(i["sku"], custos_ctx)
            if custo is not None:
                DB.execute("UPDATE devolucao_item_v1988 SET custo_unit=?, custo_origem=? WHERE id=?",
                           (round(float(custo), 4), origem or "apollo", i["id"]))
    if d.get("frete") is None:
        frete = _devolucao_frete_ml(d)
        if frete is not None:
            DB.execute("UPDATE devolucao_v1988 SET frete=?, frete_origem='ml' WHERE id=?", (frete, d["id"]))


def _devolucao_valor_ou_vazio(valor: Any, nome: str) -> float | None:
    if valor is None or str(valor).strip() == "":
        return None
    try:
        v = round(float(str(valor).replace(",", ".")), 4)
    except ValueError:
        raise ValueError(f"{nome} inválido.")
    if v < 0 or v > 1_000_000:
        raise ValueError(f"{nome} inválido.")
    return v


def devolucao_salvar_valores(dev_id: Any, req: dict[str, Any], versao: Any, usuario: str,
                             filial: str = FILIAL_TODAS) -> dict[str, Any]:
    """Admin: frete da devolução e, por peça, destino e custo. Vale também na tratada (fica no histórico)."""
    req = req if isinstance(req, dict) else {}
    tem_motivo = "motivo_dev" in req   # V19.97
    motivo_dev = str(req.get("motivo_dev") or "").strip().lower() if tem_motivo else ""
    if tem_motivo and motivo_dev and motivo_dev not in DEVOLUCAO_MOTIVOS_DEV:
        raise ValueError("Motivo da devolução inválido.")
    tem_frete = "frete" in req
    frete = _devolucao_valor_ou_vazio(req.get("frete"), "Frete") if tem_frete else None
    pedidos_itens = req.get("itens") if isinstance(req.get("itens"), list) else []
    if len(pedidos_itens) > DEVOLUCAO_MAX_ITENS:
        raise ValueError("Peças demais.")
    novos = []
    for it in pedidos_itens:
        if not isinstance(it, dict):
            raise ValueError("Peça inválida.")
        n: dict[str, Any] = {"id": it.get("id")}
        if "destino" in it:
            destino = str(it.get("destino") or "").strip().lower()
            if destino not in DEVOLUCAO_DESTINOS:
                raise ValueError("Destino da peça inválido.")
            n["destino"] = destino
        if "custo" in it:
            n["custo"] = _devolucao_valor_ou_vazio(it.get("custo"), "Custo")
        novos.append(n)

    def mudar(d: dict[str, Any]) -> str:
        atuais = {int(i["id"]): i for i in d["itens"]}
        antes: dict[str, Any] = {}
        depois: dict[str, Any] = {}
        if tem_motivo:
            antes["motivo"] = d.get("motivo_dev") or ""
            depois["motivo"] = motivo_dev
            DB.execute("UPDATE devolucao_v1988 SET motivo_dev=? WHERE id=?", (motivo_dev, d["id"]))
        if tem_frete:
            antes["frete"] = d.get("frete")
            depois["frete"] = frete
            DB.execute("UPDATE devolucao_v1988 SET frete=?, frete_origem=? WHERE id=?",
                       (frete, "digitado" if frete is not None else "", d["id"]))
        for n in novos:
            try:
                item = atuais[int(n["id"])]
            except (TypeError, ValueError, KeyError):
                raise ValueError("Peça não encontrada nesta devolução.")
            if "destino" in n:
                antes[f"{item['sku']}.destino"] = item["destino"]
                depois[f"{item['sku']}.destino"] = n["destino"]
                DB.execute("UPDATE devolucao_item_v1988 SET destino=? WHERE id=?", (n["destino"], item["id"]))
            if "custo" in n:
                antes[f"{item['sku']}.custo"] = item.get("custo_unit")
                depois[f"{item['sku']}.custo"] = n["custo"]
                DB.execute("UPDATE devolucao_item_v1988 SET custo_unit=?, custo_origem=? WHERE id=?",
                           (n["custo"], "manual" if n["custo"] is not None else "", item["id"]))
        _devolucao_evento(d["id"], usuario, "valores", {"antes": antes, "depois": depois})
        return "valores"
    return _devolucao_mudar(dev_id, versao, filial, usuario, mudar)


# V19.97 (dono, 27/10): relatório no formato da planilha da equipe — NF | NFD | NOME | SKU E QUANTIDADE | VALOR | MOTIVO.
DEVOLUCAO_MOTIVOS_DEV = {
    "arrependimento": "Comprador se arrependeu",
    "quebrado": "Produto chegou quebrado ou danificado",
    "defeito": "Produto com defeito",
    "incompativel": "Incompatível com o veículo",
    "faltando": "Pacote chegou com itens faltando",
    "produto_errado": "Produto diferente do anunciado",
    "falha_entrega": "Falha na entrega",
    "outro": "Outro",
}
# nome do motivo da reclamação do ML (ml_reclamacao_motivo_v1888.nome) → motivo da devolução, por palavra
_DEVOLUCAO_MOTIVO_ML = (("repent", "arrependimento"), ("regret", "arrependimento"), ("compat", "incompativel"),
                        ("broken", "quebrado"), ("damage", "quebrado"), ("missing", "faltando"),
                        ("incomplete", "faltando"), ("different", "produto_errado"), ("wrong", "produto_errado"),
                        ("not_as_described", "produto_errado"), ("defect", "defeito"), ("not_work", "defeito"),
                        ("doesnt_work", "defeito"), ("not_delivered", "falha_entrega"), ("delivery", "falha_entrega"))


def _devolucao_motivo_do_ml(nome: str) -> tuple[str, str]:
    nome = str(nome or "").lower()
    for chave, codigo in _DEVOLUCAO_MOTIVO_ML:
        if chave in nome:
            return codigo, DEVOLUCAO_MOTIVOS_DEV[codigo]
    return "outro", DEVOLUCAO_MOTIVOS_DEV["outro"]


def devolucao_motivo(d: dict[str, Any]) -> tuple[str, str, str]:
    """(código, rótulo, origem): o escolhido pelo admin vence; sem ele, o da reclamação do ML."""
    if d.get("motivo_dev"):
        cod = str(d["motivo_dev"])
        return cod, DEVOLUCAO_MOTIVOS_DEV.get(cod, cod), "admin"
    ids = _devolucao_ids_venda(d)
    if ids:
        with DB_LOCK:
            r = DB.execute(f"SELECT m.nome FROM ml_reclamacao_v1888 r JOIN ml_reclamacao_motivo_v1888 m "
                           f"ON m.motivo_id=r.motivo_id WHERE r.order_id IN ({','.join('?' * len(ids))}) "
                           f"ORDER BY r.aberta_em DESC LIMIT 1", ids).fetchone()
        if r and r[0]:
            cod, rot = _devolucao_motivo_do_ml(r[0])
            return cod, rot, "ml"
    return "", "", ""


def _devolucao_linhas_preco(d: dict[str, Any]) -> list[tuple[str, float]]:
    """(SKU vendido, preço unitário) da venda: reclamação do ML > vendas copiadas > venda lida no ML."""
    ids = _devolucao_ids_venda(d)
    if not ids:
        return []
    marcas = ",".join("?" * len(ids))
    linhas: list[tuple[str, float]] = []
    with DB_LOCK:
        for (itens_json,) in DB.execute(f"SELECT itens_json FROM ml_reclamacao_v1888 WHERE order_id IN ({marcas}) "
                                        f"AND itens_json<>''", ids).fetchall():
            for it in _filial_json(itens_json, []) or []:
                if isinstance(it, dict) and it.get("sku") and it.get("preco") is not None:
                    linhas.append((str(it["sku"]), float(it["preco"])))
        if not linhas:
            for tabela in ("vendas_v1799", "vendas_conta_v1898"):
                for sku, qty, amount in DB.execute(f"SELECT sku, qty, amount FROM {tabela} WHERE order_id IN ({marcas})",
                                                   ids).fetchall():
                    if sku and qty and amount is not None:
                        linhas.append((str(sku), float(amount) / float(qty)))
        if not linhas:
            for (lj,) in DB.execute(f"SELECT linhas_json FROM devolucao_venda_ml_v1994 WHERE order_id IN ({marcas})",
                                    ids).fetchall():
                for it in _filial_json(lj, []) or []:
                    if isinstance(it, dict) and it.get("sku") and it.get("preco") is not None:
                        linhas.append((str(it["sku"]), float(it["preco"])))
    return linhas


def devolucao_valor_venda(d: dict[str, Any], nf: dict[str, Any] | None = None) -> dict[str, Any]:
    """Valor de venda das peças que voltaram (preço × quantidade devolvida). Kit: o preço dividido pelas peças.
    Sem preço nenhum, o valor da NF de venda (guardada)."""
    preco_peca: dict[str, float] = {}
    for sku, unit in _devolucao_linhas_preco(d):
        pecas = _devolucao_pecas([{"SKU": sku, "Quantidade": 1}])
        unidades = sum(int(p["qtd_vendida"]) for p in pecas.values()) or 1
        for cod, p in pecas.items():
            preco_peca.setdefault(cod, unit / unidades)
    por_item: dict[str, float] = {}
    for i in d["itens"]:
        q = int(i["qtd"] or 0)
        if q > 0 and i["sku"] in preco_peca:
            por_item[i["sku"]] = round(por_item.get(i["sku"], 0.0) + preco_peca[i["sku"]] * q, 2)
    if por_item:
        return {"total": round(sum(por_item.values()), 2), "por_item": por_item, "origem": "venda"}
    if nf is None and d.get("order_key"):
        with DB_LOCK:
            r = DB.execute("SELECT nf_json FROM devolucao_nf_v1995 WHERE order_key=?", (d["order_key"],)).fetchone()
        nf = json.loads(r[0]) if r else None
    if nf and nf.get("valor") is not None:
        return {"total": round(float(nf["valor"]), 2), "por_item": {}, "origem": "nf"}
    return {"total": None, "por_item": {}, "origem": ""}


def devolucoes_relatorio_linhas(ids: list[int]) -> tuple[list[str], list[list[Any]]]:
    """Uma linha por peça que voltou, das devoluções do lote."""
    cab = ["NF", "NFD", "NOME", "SKU E QUANTIDADE", "VALOR", "MOTIVO"]
    return cab, [[r["nf"], r["nfd"], r["nome"], f"{r['sku']} / {r['qtd']} {'UNIDADE' if r['qtd'] == 1 else 'UNIDADES'}",
                  r["valor"], r["motivo"]] for r in devolucoes_relatorio_dados(ids)]


def devolucao_exportar(usuario: str, filial: str) -> dict[str, Any]:
    """V19.97 (dono, 27/10): um lote com as devoluções TRATADAS que ainda não foram exportadas (de qualquer mês).
    Cada uma fica marcada com o lote: clicar de novo não duplica. Sem desfazer; o lote pode ser baixado de novo."""
    with DB_LOCK:
        DB.execute("BEGIN IMMEDIATE")
        try:
            ids = [int(r[0]) for r in DB.execute(
                "SELECT id FROM devolucao_v1988 WHERE situacao='tratada' AND exportacao_id IS NULL"
                + ("" if filial == FILIAL_TODAS else " AND filial=?") + " ORDER BY recebido_em, id",
                [] if filial == FILIAL_TODAS else [filial]).fetchall()]
            if not ids:
                DB.rollback()
                raise ValueError("Nenhuma devolução tratada para exportar: todas já foram exportadas.")
            cur = DB.execute("INSERT INTO devolucao_exportacao_v1997(criado_em,criado_por,filial,devolucoes) "
                             "VALUES(?,?,?,?)", (now_iso(), usuario, filial, len(ids)))
            lote = int(cur.lastrowid)
            DB.execute(f"UPDATE devolucao_v1988 SET exportacao_id=? WHERE id IN ({','.join('?' * len(ids))})",
                       (lote, *ids))
            for i in ids:
                _devolucao_evento(i, usuario, "exportada", {"lote": lote})
            DB.commit()
        except ValueError:
            raise
        except Exception:
            DB.rollback()
            raise
    audit(usuario, "devolucao.exportar", f"lote {lote}: {len(ids)}")
    return {"ok": True, "id": lote, "devolucoes": ids}


def _devolucao_lote(lote_id: Any, filial: str) -> dict[str, Any]:
    try:
        lote_id = int(lote_id)
    except (TypeError, ValueError):
        raise ValueError("Lote não informado.")
    with DB_LOCK:
        r = DB.execute("SELECT * FROM devolucao_exportacao_v1997 WHERE id=?", (lote_id,)).fetchone()
    if r is None:
        raise ValueError("Lote não encontrado.")
    if filial != FILIAL_TODAS and r["filial"] != filial:
        raise PermissionError("Este lote é de outra filial.")
    return dict(r)


def devolucoes_lote_ids(lote_id: Any, filial: str) -> list[int]:
    lote = _devolucao_lote(lote_id, filial)
    with DB_LOCK:
        return [int(r[0]) for r in DB.execute("SELECT id FROM devolucao_v1988 WHERE exportacao_id=? ORDER BY recebido_em, id",
                                              (lote["id"],)).fetchall()]


def devolucoes_exportacoes(filial: str) -> list[dict[str, Any]]:
    """Histórico de lotes, o mais novo primeiro."""
    with DB_LOCK:
        return [dict(r) for r in DB.execute(
            "SELECT * FROM devolucao_exportacao_v1997" + ("" if filial == FILIAL_TODAS else " WHERE filial=?")
            + " ORDER BY id DESC LIMIT 200", [] if filial == FILIAL_TODAS else [filial]).fetchall()]


def devolucoes_relatorio_dados(ids: list[int]) -> list[dict[str, Any]]:
    """Dados de cada linha do relatório (uma por peça que voltou), na ordem em que chegaram."""
    with DB_LOCK:
        devs = sorted((d for d in (_devolucao_ler(int(i)) for i in ids) if d), key=lambda d: (d["recebido_em"], d["id"]))
    linhas: list[dict[str, Any]] = []
    for d in devs:
        nf = None
        if not d["sem_pedido"]:
            try:
                nf = _devolucao_nf_ler(d["order_key"], d["marketplace"], d["filial"], d["pedido"]).get("nf")
            except Exception:
                nf = None
        valor = devolucao_valor_venda(d, nf)
        motivo = devolucao_motivo(d)[1]
        itens = [i for i in d["itens"] if int(i["qtd"] or 0) > 0]
        for n, i in enumerate(itens):
            q = int(i["qtd"])
            if valor["origem"] == "venda":
                v: Any = valor["por_item"].get(i["sku"], "")
            else:
                v = valor["total"] if (n == 0 and valor["total"] is not None) else ""
            linhas.append({"devolucao": d["id"], "nf": (nf or {}).get("numero", ""), "nfd": d.get("documento_apollo") or "",
                           "nome": d.get("cliente") or "", "sku": i["sku"], "qtd": q, "valor": v, "motivo": motivo,
                           "descricao": i.get("descricao") or "", "marketplace": d.get("marketplace") or "",
                           "pedido": d.get("pedido") or "", "chegou": _devolucao_dia_br(d["recebido_em"])})
    return linhas


_MESES_PT = ("janeiro", "fevereiro", "março", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro",
             "novembro", "dezembro")


def devolucoes_relatorio_xlsx(lote_id: Any, filial: str) -> bytes:
    """V19.97: planilha no formato da equipe (NF | NFD | NOME | SKU E QUANTIDADE | VALOR | MOTIVO), com título,
    cabeçalho fixo com filtro, linhas alternadas, total e a aba "Resumo por motivo". Só biblioteca padrão."""
    import io
    import zipfile
    lote = _devolucao_lote(lote_id, filial)
    dados = devolucoes_relatorio_dados(devolucoes_lote_ids(lote["id"], filial))
    esc = html_module.escape
    agora = datetime.now(BR_TZ)
    filial_nome = "todas as filiais" if lote["filial"] == FILIAL_TODAS else CASAS.get(lote["filial"], lote["filial"])
    try:
        quando = datetime.fromisoformat(lote["criado_em"]).astimezone(BR_TZ).strftime("%d/%m/%Y %H:%M")
    except ValueError:
        quando = lote["criado_em"]
    subtitulo = (f"Lote {lote['id']} · devoluções tratadas · {filial_nome} · exportado em {quando} "
                 f"por {lote['criado_por']}")
    _ = agora

    def cel(col: int, lin: int, valor: Any, estilo: int) -> str:
        ref = f"{_xlsx_col(col)}{lin}"
        if valor is None or valor == "":
            return f'<c r="{ref}" s="{estilo}"/>'
        if isinstance(valor, (int, float)) and not isinstance(valor, bool):
            return f'<c r="{ref}" s="{estilo}"><v>{valor}</v></c>'
        if isinstance(valor, str) and valor.startswith("="):
            return f'<c r="{ref}" s="{estilo}"><f>{esc(valor[1:])}</f></c>'
        return f'<c r="{ref}" s="{estilo}" t="inlineStr"><is><t xml:space="preserve">{esc(str(valor))}</t></is></c>'

    def folha(titulo: str, cab: list[str], linhas: list[list[Any]], larguras: list[float], alinhar: list[str],
              total: list[Any] | None) -> str:
        """alinhar por coluna: t = texto, c = centro, m = moeda, n = número."""
        ncol = len(cab)
        ult = _xlsx_col(ncol - 1)
        base = {"t": (4, 7), "c": (5, 8), "m": (6, 9), "n": (12, 13)}
        rows = [f'<row r="1" ht="26" customHeight="1">{cel(0, 1, titulo, 1)}</row>',
                f'<row r="2" ht="18" customHeight="1">{cel(0, 2, subtitulo, 2)}</row>',
                '<row r="3" ht="8" customHeight="1"/>',
                '<row r="4" ht="22" customHeight="1">' + "".join(cel(k, 4, c, 3) for k, c in enumerate(cab)) + "</row>"]
        r = 4
        for n, l in enumerate(linhas):
            r += 1
            zebra = n % 2
            rows.append(f'<row r="{r}" ht="18" customHeight="1">' +
                        "".join(cel(k, r, v, base[alinhar[k]][zebra]) for k, v in enumerate(l)) + "</row>")
        fim = r
        if total is not None:
            r += 1
            rows.append(f'<row r="{r}" ht="20" customHeight="1">' + "".join(
                cel(k, r, (v.replace("{fim}", str(fim)) if isinstance(v, str) else v),
                    11 if alinhar[k] == "m" else (14 if alinhar[k] == "n" else 10)) for k, v in enumerate(total)) + "</row>")
        cols = "".join(f'<col min="{k + 1}" max="{k + 1}" width="{w}" customWidth="1"/>' for k, w in enumerate(larguras))
        filtro = f'<autoFilter ref="A4:{ult}{max(fim, 4)}"/>' if linhas else ""
        return ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
                'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
                '<sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>'
                '<sheetViews><sheetView workbookViewId="0" showGridLines="0">'
                '<pane ySplit="4" topLeftCell="A5" activePane="bottomLeft" state="frozen"/>'
                '<selection pane="bottomLeft" activeCell="A5" sqref="A5"/></sheetView></sheetViews>'
                '<sheetFormatPr defaultRowHeight="15"/>'
                f'<cols>{cols}</cols><sheetData>{"".join(rows)}</sheetData>{filtro}'
                f'<mergeCells count="2"><mergeCell ref="A1:{ult}1"/><mergeCell ref="A2:{ult}2"/></mergeCells>'
                '<pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.3" footer="0.3"/>'
                '<pageSetup paperSize="9" orientation="landscape" fitToWidth="1" fitToHeight="0"/>'
                '</worksheet>')

    numero = lambda v: int(v) if isinstance(v, str) and v.isdigit() and len(v) <= 15 else v   # sem o aviso de "número como texto"
    linhas = [[numero(r["nf"]), numero(r["nfd"]), r["nome"], f"{r['sku']} / {r['qtd']} {'UNIDADE' if r['qtd'] == 1 else 'UNIDADES'}",
               r["valor"] if isinstance(r["valor"], (int, float)) else "", r["motivo"]] for r in dados]
    devolucoes = len({r["devolucao"] for r in dados})
    pecas = sum(r["qtd"] for r in dados)
    aba1 = folha(f"Relatório de devoluções · lote {lote['id']}", ["NF", "NFD", "NOME", "SKU E QUANTIDADE", "VALOR", "MOTIVO"], linhas,
                 [12, 12, 44, 30, 16, 42], ["c", "c", "t", "t", "m", "t"],
                 [f"TOTAL · {devolucoes} {'devolução' if devolucoes == 1 else 'devoluções'}", "", "", f"{pecas} peças", "=SUM(E5:E{fim})", ""] if dados else None)
    por_motivo: dict[str, dict[str, Any]] = {}
    for r in dados:
        m = por_motivo.setdefault(r["motivo"] or "Sem motivo", {"devs": set(), "pecas": 0, "valor": 0.0})
        m["devs"].add(r["devolucao"])
        m["pecas"] += r["qtd"]
        if isinstance(r["valor"], (int, float)):
            m["valor"] = round(m["valor"] + r["valor"], 2)
    total_valor = sum(m["valor"] for m in por_motivo.values()) or 0
    resumo = [[mot, len(m["devs"]), m["pecas"], m["valor"], round(m["valor"] / total_valor, 4) if total_valor else ""]
              for mot, m in sorted(por_motivo.items(), key=lambda x: -x[1]["valor"])]
    aba2 = folha("Resumo por motivo", ["MOTIVO", "DEVOLUÇÕES", "PEÇAS", "VALOR", "% DO VALOR"], resumo,
                 [44, 16, 12, 17, 15], ["t", "n", "n", "m", "n"],
                 ["TOTAL", devolucoes, pecas, "=SUM(D5:D{fim})", ""] if resumo else None)
    # a coluna "% do valor" usa o estilo de percentual
    aba2 = re.sub(r'<c r="E(\d+)" s="1[23]"', lambda m_: f'<c r="E{m_.group(1)}" s="{15 if int(m_.group(1)) % 2 else 16}"', aba2)
    folhas = [("Devoluções", aba1), ("Resumo por motivo", aba2)]

    borda = '<border><left style="thin"><color rgb="FFDCE5EF"/></left><right style="thin"><color rgb="FFDCE5EF"/></right>' \
            '<top style="thin"><color rgb="FFDCE5EF"/></top><bottom style="thin"><color rgb="FFDCE5EF"/></bottom><diagonal/></border>'
    borda_total = '<border><left/><right/><top style="medium"><color rgb="FF12345B"/></top><bottom style="medium"><color rgb="FF12345B"/></bottom><diagonal/></border>'
    al = lambda h: f'<alignment horizontal="{h}" vertical="center"/>'
    def xf(font: int, fill: int, border: int, h: str, num: int = 0) -> str:
        aplica_num = ' applyNumberFormat="1"' if num else ""
        return (f'<xf numFmtId="{num}" fontId="{font}" fillId="{fill}" borderId="{border}" '
                f'applyFont="1" applyFill="1" applyBorder="1" applyAlignment="1"{aplica_num}>{al(h)}</xf>')
    estilos = [
        '<xf numFmtId="0" fontId="0" fillId="0" borderId="0"/>',                    # 0
        xf(2, 0, 0, "left"),                                                       # 1 título
        xf(3, 0, 0, "left"),                                                       # 2 subtítulo
        '<xf numFmtId="0" fontId="1" fillId="2" borderId="1" applyFont="1" applyFill="1" applyBorder="1" '
        'applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf>',  # 3 cabeçalho
        xf(0, 0, 1, "left"), xf(0, 0, 1, "center"), xf(0, 0, 1, "right", 164),    # 4 5 6
        xf(0, 3, 1, "left"), xf(0, 3, 1, "center"), xf(0, 3, 1, "right", 164),    # 7 8 9 (zebra)
        xf(4, 4, 2, "left"), xf(4, 4, 2, "right", 164),                           # 10 11 total
        xf(0, 0, 1, "center", 3), xf(0, 3, 1, "center", 3), xf(4, 4, 2, "center", 3),  # 12 13 14 número
        xf(0, 0, 1, "center", 10), xf(0, 3, 1, "center", 10),                     # 15 16 percentual
    ]
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
              '<numFmts count="1"><numFmt numFmtId="164" formatCode="&quot;R$&quot;\\ #,##0.00"/></numFmts>'
              '<fonts count="5"><font><sz val="10"/><color rgb="FF18324A"/><name val="Calibri"/></font>'
              '<font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font>'
              '<font><b/><sz val="16"/><color rgb="FF12345B"/><name val="Calibri"/></font>'
              '<font><sz val="10"/><color rgb="FF586A7D"/><name val="Calibri"/></font>'
              '<font><b/><sz val="10"/><color rgb="FF12345B"/><name val="Calibri"/></font></fonts>'
              '<fills count="5"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>'
              '<fill><patternFill patternType="solid"><fgColor rgb="FF12345B"/></patternFill></fill>'
              '<fill><patternFill patternType="solid"><fgColor rgb="FFF4F7FB"/></patternFill></fill>'
              '<fill><patternFill patternType="solid"><fgColor rgb="FFE7EEF7"/></patternFill></fill></fills>'
              f'<borders count="3"><border><left/><right/><top/><bottom/><diagonal/></border>{borda}{borda_total}</borders>'
              '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
              f'<cellXfs count="{len(estilos)}">{"".join(estilos)}</cellXfs>'
              '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>')
    n = len(folhas)
    ct = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
          + "".join(f'<Override PartName="/xl/worksheets/sheet{i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                    for i in range(n))
          + '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>')
    rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
    nomes_def = "".join(
        f'<definedName name="_xlnm._FilterDatabase" localSheetId="{i}" hidden="1">\'{esc(nome)}\'!$A$4:${_xlsx_col(ncols - 1)}${fim}</definedName>'
        for i, (nome, ncols, fim) in enumerate([("Devoluções", 6, 4 + len(linhas)), ("Resumo por motivo", 5, 4 + len(resumo))])
        if fim > 4)
    wb = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'
          + "".join(f'<sheet name="{esc(nome)}" sheetId="{i + 1}" r:id="rId{i + 1}"/>' for i, (nome, _) in enumerate(folhas))
          + "</sheets>" + (f"<definedNames>{nomes_def}</definedNames>" if nomes_def else "") + "</workbook>")
    wbrels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              + "".join(f'<Relationship Id="rId{i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{i + 1}.xml"/>'
                        for i in range(n))
              + f'<Relationship Id="rId{n + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>')
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("[Content_Types].xml", ct)
        z.writestr("_rels/.rels", rels)
        z.writestr("xl/workbook.xml", wb)
        z.writestr("xl/_rels/workbook.xml.rels", wbrels)
        z.writestr("xl/styles.xml", styles)
        for i, (_, conteudo) in enumerate(folhas):
            z.writestr(f"xl/worksheets/sheet{i + 1}.xml", conteudo)
    return buf.getvalue()


def _devolucao_vendidas_por_peca(mes: str, filial: str) -> dict[str, int]:
    """Unidades vendidas no mês por código de peça (kit aberto), para a taxa de devolução."""
    ini = mes + "-01"
    fim = (datetime.strptime(_devolucao_mes_seguinte(mes) + "-01", "%Y-%m-%d") - timedelta(days=1)).date().isoformat()
    linhas: list[dict[str, Any]] = []
    with DB_LOCK:
        if filial in (FILIAL_TODAS, CASA_PRINCIPAL):
            linhas += [{"SKU": r[0], "Quantidade": r[1]} for r in DB.execute(
                "SELECT sku, qty FROM vendas_v1799 WHERE sale_day BETWEEN ? AND ?", (ini, fim)).fetchall()]
        conta = [] if filial == CASA_PRINCIPAL else ([] if filial == FILIAL_TODAS else [filial])
        linhas += [{"SKU": r[0], "Quantidade": r[1]} for r in DB.execute(
            "SELECT sku, qty FROM vendas_conta_v1898 WHERE sale_day BETWEEN ? AND ?"
            + (" AND conta=?" if conta else ""), (ini, fim, *conta)).fetchall()] if filial != CASA_PRINCIPAL else []
    return {k: int(v["qtd_vendida"]) for k, v in _devolucao_pecas(linhas).items()}


def _devolucao_indicadores(devs: list[dict[str, Any]], vendidas: int) -> dict[str, Any]:
    pecas = sum(int(i["qtd"] or 0) for d in devs for i in d["itens"])
    return {"devolucoes": len(devs), "pecas": pecas,
            "perda": round(sum(d["valores"]["perda_conhecida"] for d in devs), 2),
            "perda_confirmada": round(sum(d["valores"]["perda_conhecida"] for d in devs if d["situacao"] == "tratada"), 2),
            "perda_a_confirmar": round(sum(d["valores"]["perda_conhecida"] for d in devs if d["situacao"] != "tratada"), 2),
            "incompletas": sum(1 for d in devs if d["valores"]["incompleta"]),
            "a_tratar": sum(1 for d in devs if d["situacao"] != "tratada"),
            "pecas_ruins": sum(int(i["qtd"] or 0) for d in devs for i in d["itens"] if i["estado"] == "ruim"),
            "vendidas": vendidas, "taxa": round(pecas / vendidas * 100, 2) if vendidas else None}


def devolucoes_resumo(mes: Any, filial: str) -> dict[str, Any]:
    """Painel do mês (pela data em que a peça chegou), comparado ao mês anterior, e ranking por peça."""
    mes = _devolucao_mes_valido(mes) or datetime.now(BR_TZ).strftime("%Y-%m")
    anterior = _devolucao_mes_anterior(mes)
    atual_l = devolucoes_lista({"mes": mes}, filial)["devolucoes"]
    ant_l = devolucoes_lista({"mes": anterior}, filial)["devolucoes"]
    vend_atual = _devolucao_vendidas_por_peca(mes, filial)
    vend_ant = _devolucao_vendidas_por_peca(anterior, filial)
    ranking: dict[str, dict[str, Any]] = {}
    for d in atual_l:
        perdas = {v["id"]: v["perda"] for v in d["valores"]["itens"]}
        for i in d["itens"]:
            if not int(i["qtd"] or 0):
                continue
            r = ranking.setdefault(i["sku"], {"sku": i["sku"], "descricao": i["descricao"] or "", "devolvidas": 0,
                                              "ruins": 0, "perda": 0.0, "devolucoes": 0, "motivos": {}})
            r["devolvidas"] += int(i["qtd"])
            r["devolucoes"] += 1
            if i["estado"] == "ruim":
                r["ruins"] += int(i["qtd"])
                r["motivos"][i["motivo"]] = r["motivos"].get(i["motivo"], 0) + int(i["qtd"])
            if perdas.get(i["id"]) is not None:
                r["perda"] = round(r["perda"] + perdas[i["id"]], 2)
    for r in ranking.values():
        r["vendidas"] = vend_atual.get(r["sku"], 0)
        r["taxa"] = round(r["devolvidas"] / r["vendidas"] * 100, 2) if r["vendidas"] else None
        r["motivo_principal"] = DEVOLUCAO_MOTIVOS.get(max(r["motivos"], key=r["motivos"].get), "") if r["motivos"] else ""
    lista = sorted(ranking.values(), key=lambda r: (-r["perda"], -r["devolvidas"]))
    return {"ok": True, "periodo": mes,
            "mes": {"periodo": mes, **_devolucao_indicadores(atual_l, sum(vend_atual.values()))},
            "anterior": {"periodo": anterior, **_devolucao_indicadores(ant_l, sum(vend_ant.values()))},
            "ranking": lista[:50], "financeiro_inicio": DEVOLUCAO_FINANCEIRO_INICIO}


def financeiro_devolucoes(d1: date, d2: date, canal: str, custos_ctx: dict[str, Any]) -> list[dict[str, Any]]:
    """Perdas de devolução de Araçatuba que chegaram no período (a partir de 01/11/2026), para o Financeiro."""
    ini = max(d1.isoformat(), DEVOLUCAO_FINANCEIRO_INICIO)
    if ini > d2.isoformat():
        return []
    faixa_ini = (datetime.strptime(ini, "%Y-%m-%d") - timedelta(days=1)).date().isoformat()
    faixa_fim = (d2 + timedelta(days=2)).isoformat()
    with DB_LOCK:
        ids = [int(r[0]) for r in DB.execute(
            "SELECT id FROM devolucao_v1988 WHERE filial=? AND recebido_em >= ? AND recebido_em < ?",
            (CASA_PRINCIPAL, faixa_ini, faixa_fim)).fetchall()]
        devs = [x for x in (_devolucao_ler(i) for i in ids) if x]
    saida = []
    for d in devs:
        dia = _devolucao_dia_br(d["recebido_em"])
        if not (ini <= dia <= d2.isoformat()):
            continue
        mp = DEVOLUCAO_MP_FINANCEIRO.get(d["marketplace"], normalize(d["marketplace"]).lower() or "outros")
        if canal and mp != canal:
            continue
        v = devolucao_valores(d, custos_ctx)
        saida.append({"id": d["id"], "dia": dia, "marketplace": mp, "perda": v["perda_conhecida"],
                      "incompleta": v["incompleta"], "confirmada": v["confirmada"]})
    return saida


# V19.95 (dono, 27/10): NF de venda na devolução. /users/{seller}/invoices/orders/{order} responde número, série,
# chave e data para toda venda do ML (conferido em produção: Full série 2, emitida pelo ML; Coleta série 1). Sem PDF da
# DANFE por essa API. Lida uma vez e guardada (devolucao_nf_v1995); "sem nota" fica 30 min em memória. Erro = sem nota.
_DEVOLUCAO_NF_FALTA: dict[str, float] = {}


def _devolucao_nf_ler(order_key: str, marketplace: str, filial: str, pedido: str = "") -> dict[str, Any]:
    order_key = normalize(order_key)
    if not order_key:
        return {"ok": True, "nf": None, "motivo": "Devolução sem pedido."}
    if marketplace not in ("Mercado Livre", "Shopee"):
        return {"ok": True, "nf": None,
                "motivo": f"A nota de venda da {marketplace or 'venda'} não vem pela API: veja no Apollo."}
    with DB_LOCK:
        r = DB.execute("SELECT nf_json FROM devolucao_nf_v1995 WHERE order_key=?", (order_key,)).fetchone()
    if r:
        return {"ok": True, "nf": json.loads(r[0])}
    agora = time.time()
    with _DEVOLUCAO_ENVIO_LOCK:
        if _DEVOLUCAO_NF_FALTA.get(order_key, 0) > agora:
            return {"ok": True, "nf": None, "motivo": f"{'A Shopee' if marketplace == 'Shopee' else 'O Mercado Livre'} "
                                                      "ainda não tem a nota desta venda."}
    if marketplace == "Shopee":
        nf = _devolucao_nf_shopee(normalize(pedido) or order_key)
        if nf:
            with DB_LOCK:
                DB.execute("INSERT OR REPLACE INTO devolucao_nf_v1995(order_key,nf_json,lido_em) VALUES(?,?,?)",
                           (order_key, json.dumps(nf, ensure_ascii=False), now_iso()))
                DB.commit()
            return {"ok": True, "nf": nf}
        with _DEVOLUCAO_ENVIO_LOCK:
            _DEVOLUCAO_NF_FALTA[order_key] = agora + DEVOLUCAO_ENVIO_CACHE_SEG
        return {"ok": True, "nf": None, "motivo": "A Shopee ainda não tem a nota desta venda."}
    ids: list[str] = []
    if order_key.startswith(DEVOLUCAO_VENDA_PREFIXO):
        ids.append(order_key[len(DEVOLUCAO_VENDA_PREFIXO):])
    with DB_LOCK:
        for (ml_ids,) in DB.execute("SELECT DISTINCT ml_ids FROM devolucao_busca_v1988 WHERE order_key=?",
                                    (order_key,)).fetchall():
            ids += [x for x in str(ml_ids or "").split(",") if x.isdigit()]
    ids += [x for x in (order_key, normalize(pedido)) if x.isdigit()]
    vistos: list[str] = []
    for x in ids:
        if x not in vistos:
            vistos.append(x)
    casa = filial if filial in CASAS else CASA_PRINCIPAL
    nf = None
    try:
        with ml_na_casa(casa):
            linha = ml_integration_row()
            seller = str(linha["seller_id"] if linha else "").strip()
            for oid in vistos[:4]:
                if not seller:
                    break
                try:
                    d = ml_api_get(f"/users/{quote(seller)}/invoices/orders/{quote(oid)}")
                except Exception:
                    continue
                if isinstance(d, dict) and d.get("invoice_number") and str(d.get("status") or "authorized") == "authorized":
                    atr = d.get("attributes") if isinstance(d.get("attributes"), dict) else {}
                    nf = {"numero": str(d.get("invoice_number")), "serie": str(d.get("invoice_series") or ""),
                          "chave": str(atr.get("invoice_key") or ""), "emitida_em": str(d.get("issued_date") or ""),
                          "valor": d.get("amount"), "venda": oid,
                          "emitente": "Mercado Livre (Full)" if str(d.get("invoice_series") or "") == "2" else ""}
                    break
    except Exception:
        nf = None
    if nf:
        with DB_LOCK:
            DB.execute("INSERT OR REPLACE INTO devolucao_nf_v1995(order_key,nf_json,lido_em) VALUES(?,?,?)",
                       (order_key, json.dumps(nf, ensure_ascii=False), now_iso()))
            DB.commit()
        return {"ok": True, "nf": nf}
    with _DEVOLUCAO_ENVIO_LOCK:
        if len(_DEVOLUCAO_NF_FALTA) > 2000:
            _DEVOLUCAO_NF_FALTA.clear()
        _DEVOLUCAO_NF_FALTA[order_key] = agora + DEVOLUCAO_ENVIO_CACHE_SEG
    return {"ok": True, "nf": None, "motivo": "O Mercado Livre não devolveu a nota desta venda."}


def _devolucao_nf_shopee(order_sn: str) -> dict[str, Any] | None:
    """V19.96: a Shopee traz a NF no get_order_detail (invoice_data; conferido em produção 27/10, 261012CNWJPV5F)."""
    try:
        detalhes = shopee_order_details([order_sn])
    except Exception:
        return None
    for o in detalhes or []:
        inv = o.get("invoice_data") if isinstance(o, dict) else None
        if not isinstance(inv, dict) or not inv.get("number"):
            continue
        emitida = inv.get("issue_date")
        try:
            emitida = datetime.fromtimestamp(int(emitida), timezone.utc).isoformat() if emitida else ""
        except (TypeError, ValueError, OSError):
            emitida = str(emitida or "")
        return {"numero": str(inv.get("number")), "serie": str(inv.get("series_number") or ""),
                "chave": str(inv.get("access_key") or ""), "emitida_em": emitida, "valor": inv.get("total_value"),
                "venda": str(o.get("order_sn") or order_sn), "emitente": ""}
    return None


def devolucao_nf(dev_id: Any, filial: str = FILIAL_TODAS) -> dict[str, Any]:
    """NF de venda de uma devolução registrada (tela do admin)."""
    try:
        dev_id = int(dev_id)
    except (TypeError, ValueError):
        raise ValueError("Devolução não informada.")
    with DB_LOCK:
        d = _devolucao_ler(dev_id)
    if d is None:
        raise ValueError("Devolução não encontrada.")
    if filial != FILIAL_TODAS and d["filial"] != filial:
        raise PermissionError("Esta devolução é de outra filial.")
    if d["sem_pedido"]:
        return {"ok": True, "nf": None, "motivo": "Devolução sem pedido."}
    return _devolucao_nf_ler(d["order_key"], d["marketplace"], d["filial"], d["pedido"])


def devolucao_nf_da_venda(chave: Any, filial: str) -> dict[str, Any]:
    """NF de venda do pedido aberto na tela do operador (antes de registrar)."""
    v = devolucao_pedido(chave, filial)
    return _devolucao_nf_ler(v["chave"], v["marketplace"], v["filial"], v["pedido"])


def devolucao_reabrir(dev_id: Any, versao: Any, usuario: str, filial: str = FILIAL_TODAS) -> dict[str, Any]:
    def mudar(d: dict[str, Any]) -> str:
        if d["situacao"] != "tratada":
            raise ValueError("Só uma devolução tratada pode ser reaberta.")
        DB.execute("UPDATE devolucao_v1988 SET situacao='a_tratar', documento_apollo='', tratada_por='', "
                   "tratada_em='' WHERE id=?", (d["id"],))
        _devolucao_evento(d["id"], usuario, "reaberta", {"documento": d["documento_apollo"],
                                                         "tratada_por": d["tratada_por"]})
        return "reabrir"
    return _devolucao_mudar(dev_id, versao, filial, usuario, mudar)


def devolucao_corrigir(dev_id: Any, itens: Any, versao: Any, usuario: str,
                       filial: str = FILIAL_TODAS) -> dict[str, Any]:
    """O admin corrige quantidade, estado e motivo. O que o operador marcou fica no histórico."""
    novos = _devolucao_itens_validos(itens, corrigir=True)

    def mudar(d: dict[str, Any]) -> str:
        if d["situacao"] == "tratada":   # revisão 27/10: o documento do Apollo é dos números de quando tratou
            raise ValueError("Devolução já tratada: reabra antes de corrigir.")
        atuais = {int(i["id"]): i for i in d["itens"]}
        trocas = []
        for n in novos:
            try:
                item = atuais[int(n["id"])]
            except (TypeError, ValueError, KeyError):
                raise ValueError("Peça não encontrada nesta devolução.")
            trocas.append((item, n))
        if d["order_key"] and not d["sem_pedido"]:
            ja = _devolucao_ja_devolvido(d["order_key"], {int(i["id"]) for i, _ in trocas})
            soma: dict[str, int] = {}
            for item, n in trocas:
                if not item["fora_da_venda"]:
                    soma[item["sku"]] = soma.get(item["sku"], 0) + n["qtd"]
            for item, _ in trocas:
                sku = item["sku"]
                if sku in soma and item["qtd_vendida"] is not None and ja.get(sku, 0) + soma[sku] > int(item["qtd_vendida"]):
                    raise ValueError(f"{sku}: voltou mais do que foi vendido (vendido {item['qtd_vendida']}).")
        campos = ("qtd", "estado", "motivo", "obs")
        for item, n in trocas:
            DB.execute("UPDATE devolucao_item_v1988 SET qtd=?, estado=?, motivo=?, obs=? WHERE id=?",
                       (n["qtd"], n["estado"], n["motivo"], n["obs"], item["id"]))
        _devolucao_evento(d["id"], usuario, "corrigida", {
            "antes": [{"id": i["id"], "sku": i["sku"], **{c: i[c] for c in campos}} for i, _ in trocas],
            "depois": [{"id": i["id"], "sku": i["sku"], **{c: n[c] for c in campos}} for i, n in trocas]})
        return "corrigir"
    return _devolucao_mudar(dev_id, versao, filial, usuario, mudar)


def _faturamento_pendentes() -> list[tuple[str, str]]:
    """(pedido, marketplace) dos pedidos na fila de pendentes, uma vez cada."""
    return _faturamento_fila()[0]


def faturamento_rodada(agora: float | None = None, esperar=None) -> int:
    """Confere os pedidos que ainda não estão prontos (nem feitos), de 10 em 10 min."""
    agora = float(agora if agora is not None else time.time())
    with DB_LOCK:
        estado = {r["order_key"]: dict(r) for r in DB.execute("SELECT * FROM faturamento_v1943").fetchall()}
    feitos = 0
    # V19.48: primeiro quem estava "aguardando cadastro" e já teve o cadastro feito, depois o
    # que foi conferido há mais tempo — antes a rodada começava sempre pelo topo da fila e,
    # com o teto por rodada, os do fim nunca chegavam (261016S2NU71S0, 16/10).
    def _vez(item: tuple[str, str]) -> tuple[int, float]:
        e = estado.get(normalize(item[0])) or {}
        destravou = e.get("situacao") == "aguardando_cadastro" and             (cadastro_auto_do_pedido(item[0]) or {}).get("situacao") == "feito"
        return (0 if destravou else 1, float(e.get("conferido_epoch") or 0))
    apollo_cheio = False
    for pedido, mp in sorted(_faturamento_pendentes(), key=_vez):
        e = estado.get(normalize(pedido))
        intervalo = FATURAMENTO_REPETIR_APOLLO if e and e["situacao"] == "aguardando_apollo" else FATURAMENTO_INTERVALO
        if e and (e["situacao"] == "feito" or agora - float(e["conferido_epoch"] or 0) < intervalo):
            continue
        aguardando = (cadastro_auto_do_pedido(pedido) or {}).get("situacao") != "feito"
        if not aguardando:                      # só quem vai ao Apollo conta no teto
            if feitos >= FATURAMENTO_POR_RODADA or apollo_cheio:
                continue
            if feitos and esperar:
                esperar(15)
            feitos += 1
        try:
            r = faturamento_conferir(pedido, mp, agora)
            apollo_cheio = apollo_cheio or r.get("situacao") == "aguardando_apollo"
        except Exception as exc:
            print(f"[faturamento] {pedido}: {exc}", flush=True)
    return feitos


def faturamento_loop(stop_event: threading.Event) -> None:
    while not stop_event.is_set():
        try:
            faturamento_rodada(esperar=lambda s: stop_event.wait(s))
        except Exception as exc:
            print(f"[faturamento] {exc}", flush=True)
        stop_event.wait(120)


def faturamento_payload() -> dict[str, Any]:
    """A tela: pedidos da fila de pendentes com a última conferência de cada um."""
    pend, prazos = _faturamento_fila()
    with DB_LOCK:
        estado = {r["order_key"]: dict(r) for r in DB.execute("SELECT * FROM faturamento_v1943").fetchall()}
        correcoes = {r["order_key"]: dict(r) for r in DB.execute("SELECT * FROM faturamento_correcao_v1999").fetchall()}
    itens = []
    for pedido, mp in pend:
        e = estado.get(normalize(pedido))
        dia = prazos.get(normalize(pedido), "")
        if not e:
            itens.append({"pedido": pedido, "marketplace": mp, "situacao": "nao_conferido", "motivo": "Ainda não conferido.",
                          "prazo": dia})
            continue
        corr = correcoes.get(normalize(pedido))
        if corr:   # V19.99: correção de valor em andamento ou pela metade — só sai pelo Liberar
            em = str(corr["em"])
            e = {**e, "situacao": "em_correcao", "motivo": f"Correção do valor em andamento ou pela metade "
                 f"({corr['usuario']}, {em[8:10]}/{em[5:7]} {em[11:16]}): confira o atendimento "
                 f"{corr['atendimento']} no Linx e clique em Liberar."}
        itens.append({"pedido": pedido, "marketplace": mp, "situacao": e["situacao"], "motivo": e["motivo"], "prazo": dia,
                      "cliente": e["cliente"], "nome": e["nome"], "atendimento": e["atendimento"],
                      "valor_pedido": e["valor_pedido"], "valor_atendimento": e["valor_atendimento"],
                      "conferido_em": e["conferido_em"], "observacao": FATURAMENTO_OBS.get(mp, mp.upper())})
    return {"ok": True, "itens": itens, "observacoes": FATURAMENTO_OBS}


# V19.99 (revisão 28/10): uma correção de preço por pedido. Duas abas/PCs (ou o lote refeito depois
# que a tela desistiu de esperar) corrigiam o mesmo atendimento juntas: peça excluída/inserida duas
# vezes. Quem recebe a etapa "preco" leva uma senha (`trava`) de uso único; sem ela, ninguém mexe no
# pedido até a senha voltar (corrigido / nada alterado) ou alguém conferir no Linx e LIBERAR
# (faturamento_correcao_liberar) — a reserva fica no banco e não vence sozinha. A extensão lê o
# atendimento e os valores AQUI pela senha (faturamento_correcao), nunca os números da página.
def _faturamento_correcao_ler(chave: str) -> dict[str, Any] | None:
    with DB_LOCK:
        row = DB.execute("SELECT * FROM faturamento_correcao_v1999 WHERE order_key=?", (chave,)).fetchone()
    return dict(row) if row else None


def faturamento_correcao(pedido: str, trava: str) -> dict[str, Any]:
    """Para a extensão: o que corrigir, só com a senha da reserva."""
    r = _faturamento_correcao_ler(normalize(pedido))
    if not r or not trava or not secrets.compare_digest(str(r["token"]), str(trava)):
        return {"ok": False, "error": "Nenhuma correção de valor liberada para este pedido."}
    return {"ok": True, "pedido": r["pedido"], "atendimento": r["atendimento"], "valor_certo": r["valor_certo"],
            "valor_atual": r["valor_atual"]}


def faturamento_correcao_liberar(pedido: str, usuario: str) -> dict[str, Any]:
    """Alguém conferiu o atendimento no Linx: o pedido volta à fila (a próxima conferência decide)."""
    chave = normalize(pedido)
    with DB_LOCK:
        cur = DB.execute("DELETE FROM faturamento_correcao_v1999 WHERE order_key=?", (chave,))
        DB.commit()
    if not cur.rowcount:
        return {"ok": False, "error": "Este pedido não tem correção de valor pendente."}
    audit(usuario or "?", "faturamento.correcao_liberar", json.dumps({"pedido": pedido}))
    return {"ok": True}


def _faturamento_correcao_reservar(pedido: str, usuario: str, atendimento: Any, certo: Any, atual: Any) -> str:
    """A senha da reserva; vazio = outra pessoa já reservou."""
    token = secrets.token_urlsafe(16)
    with DB_LOCK:
        cur = DB.execute(
            "INSERT OR IGNORE INTO faturamento_correcao_v1999(order_key,pedido,token,usuario,epoch,em,atendimento,"
            "valor_certo,valor_atual) VALUES(?,?,?,?,?,?,?,?,?)",
            (normalize(pedido), pedido, token, usuario or "?", time.time(), now_iso(), str(atendimento), certo, atual))
        DB.commit()
    return token if cur.rowcount else ""


def faturamento_correcao_concluir(pedido: str, trava: str, usuario: str) -> dict[str, Any]:
    """V20.11: o painel devolve a senha (corrigido ou nada alterado). Quem confere o valor é a próxima
    leitura do Apollo. Correção pela metade NÃO passa por aqui: fica reservada até o Liberar."""
    chave = normalize(pedido)
    r = _faturamento_correcao_ler(chave)
    if not r or not trava or not secrets.compare_digest(str(r["token"]), str(trava)):
        return {"ok": False, "error": "Nenhuma correção de valor com esta senha."}
    with DB_LOCK:
        DB.execute("DELETE FROM faturamento_correcao_v1999 WHERE order_key=?", (chave,))
        DB.commit()
    audit(usuario or "?", "faturamento.correcao_concluir", json.dumps({"pedido": pedido}))
    return {"ok": True}


# V20.11 (dono, 02/11): a correção do valor também pelo painel do pedido. Antes o painel só avisava e
# soltava o romaneio com o valor errado, e romaneio solto com valor diferente sai da correção. Agora o
# romaneio do painel confere o valor no servidor: diferença explicada corrige primeiro (mesma reserva e
# mesma extensão do Faturamento); sem explicação ou sem valor do Apollo só sai com "conferi".
def exp_romaneio_painel(pedido: str, atendimento: Any = "", cliente: Any = "") -> dict[str, Any]:
    d = exp_romaneio_preparar(pedido, atendimento, cliente)
    r = _faturamento_correcao_ler(normalize(pedido))
    d["correcao_pendente"] = {"usuario": r["usuario"], "em": r["em"]} if r else None
    valor = d.get("valor_pedido")
    mp = d.get("marketplace") or ""
    if not mp and valor is not None:   # venda fora da fila: o marketplace vem da própria venda
        with DB_LOCK:
            row = DB.execute("SELECT marketplace FROM vendas_v1799 WHERE order_id=? LIMIT 1", (str(pedido or "").strip(),)).fetchone()
        mp = str(row["marketplace"]) if row else ""
    for a in d.get("candidatos") or []:
        v = a.get("valor")
        difere = valor is not None and v is not None and abs(float(valor) - float(v)) > 0.009
        a["valor_explicacao"] = _faturamento_diferenca_explicada(pedido, mp, float(valor), float(v)) if difere else ""
    return d


def _exp_valor_conferir(pedido: str, numero: str) -> dict[str, Any]:
    """O valor do atendimento agora. `atual` nulo = o Apollo não informou (nunca vira zero)."""
    d = exp_romaneio_painel(pedido, numero)
    a = next((c for c in d.get("candidatos") or [] if str(c.get("atendimento")) == numero), None)
    falhou = not d.get("ok", True) or d.get("situacao") == "erro"
    return {"a": a, "atual": a.get("valor") if a else None, "valor": d.get("valor_pedido"),
            "erro": (d.get("error") or d.get("aviso") or "Apollo não respondeu.") if falhou else ""}


def exp_romaneio_soltar_painel(pedido: str, atendimento: Any, observacao: str, usuario: str,
                               valor_conferido: bool = False) -> dict[str, Any]:
    pedido = str(pedido or "").strip()
    numero = re.sub(r"\D", "", str(atendimento or ""))
    r = _faturamento_correcao_ler(normalize(pedido))
    if r:
        return {"ok": False, "situacao": "em_correcao", "error": f"Correção do valor em andamento ou pela metade "
                f"({r['usuario']}, {str(r['em'])[11:16]}). Confira o atendimento no Linx e use Liberar no painel da venda."}
    mudou = _tiktok_venda_mudou(pedido)  # V20.33 (2ª revisão)
    if mudou and not valor_conferido:
        return {"ok": False, "situacao": "valor_diferente", "explicada": False, "error": mudou}
    if numero and _exp_valor_pedido(pedido) is not None:
        c = _exp_valor_conferir(pedido, numero)
        if c["erro"]:
            return {"ok": False, "situacao": "erro", "error": c["erro"]}
        atual, valor = c["atual"], c["valor"]
        explicacao = (c["a"] or {}).get("valor_explicacao") or ""
        if valor is not None and (atual is None or abs(float(valor) - float(atual)) > 0.009):
            if explicacao or not valor_conferido:   # diferença explicada corrige, nunca sai com "conferi"
                texto = "não informado pelo Apollo" if atual is None else f"R$ {float(atual):.2f}".replace(".", ",")
                base = f"Valor diferente: venda R$ {float(valor):.2f}".replace(".", ",") + f" × atendimento {texto}"
                return {"ok": False, "situacao": "valor_diferente", "explicada": bool(explicacao),
                        "error": base + (". Corrija o valor antes de soltar (painel da venda ou tela Faturamento)."
                                         if explicacao else ", sem explicação. Confira no Apollo.")}
            audit(usuario or "?", "expedicao.romaneio_valor_conferido", f"{pedido}|{numero}|{valor}|{atual}")
    return exp_romaneio_soltar(pedido, numero or atendimento, observacao, usuario)


def _exp_correcao_aberta(pedido: str) -> str:
    r = _faturamento_correcao_ler(normalize(pedido))
    return (f"Correção do valor em andamento ou pela metade ({r['usuario']}, {str(r['em'])[11:16]}): "
            f"confira o atendimento no Linx e libere antes do caixa.") if r else ""


def _reais_br(valor: Any) -> str:
    return f"R$ {float(valor):.2f}".replace(".", ",")


def _tiktok_venda_mudou(pedido: str) -> str:
    """V20.33 (2ª revisão, 06/11): atendimento do TikTok já criado e a venda mudou depois (cancelamento com desconto da
    loja = preço ilegível, ou o pedido saiu/foi cancelado inteiro): o valor da venda some (None) e a regra "venda sem
    valor não trava" deixaria o caixa sair com o valor antigo. Aqui vira barreira com o motivo."""
    try:
        with DB_LOCK:
            at = DB.execute("SELECT situacao FROM tiktok_atendimento_v2033 WHERE pedido=?", (str(pedido),)).fetchone()
            tt = DB.execute("SELECT status, saiu_epoch, venda_json FROM tiktok_sc_pedido_v2030 WHERE pedido=?",
                            (str(pedido),)).fetchone()
    except sqlite3.Error:
        return ""
    if not at or str(at["situacao"]) not in TIKTOK_ATEND_FINAIS or not tt:
        return ""
    try:
        venda = json.loads(tt["venda_json"]) if tt["venda_json"] else {}
    except (TypeError, ValueError):
        venda = {}
    if str(tt["status"] or "") in TIKTOK_SC_SAIU or float(tt["saiu_epoch"] or 0) or (isinstance(venda, dict) and venda.get("erro")):
        return ("O pedido mudou no TikTok depois do atendimento (cancelamento). Confira o atendimento no Apollo "
                "antes de seguir.")
    return ""


def _exp_caixa_valor_diferente(pedido: str, valor_apollo: Any) -> str:
    """V20.11: mesma barreira do lote (faturamento_classificar). Venda sem valor sincronizado não trava."""
    mudou = _tiktok_venda_mudou(pedido)  # V20.33 (2ª revisão): o TikTok mudou o pedido depois do atendimento
    if mudou:
        return mudou
    venda = _exp_valor_pedido(pedido)
    if venda is None:
        return ""
    try:
        atual = float(valor_apollo)
    except (TypeError, ValueError):
        return f"O Apollo não informou o valor do atendimento e a venda é {_reais_br(venda)}: confira antes do caixa."
    if abs(float(venda) - atual) <= 0.009:
        return ""
    return f"Valor diferente: venda {_reais_br(venda)} × atendimento {_reais_br(atual)}. Acerte no Linx ou confirme que conferiu."


def exp_caixa_previa_painel(pedido: str, atendimento: Any, cliente: Any, usuario: str,
                            valor_conferido: bool = False) -> dict[str, Any]:
    aberta = _exp_correcao_aberta(pedido)
    if aberta:
        return {"ok": False, "situacao": "em_correcao", "error": aberta}
    p = exp_caixa_previa(pedido, atendimento, cliente, usuario)
    if not p.get("pode") or valor_conferido:
        return p
    motivo = _exp_caixa_valor_diferente(pedido, p.get("valor"))
    if motivo:
        return {**p, "pode": False, "valor_diferente": True, "impedimentos": list(p.get("impedimentos") or []) + [motivo]}
    return p


def exp_caixa_enviar_painel(pedido: str, atendimento: Any, cliente: Any, valor_visto: Any, usuario: str,
                            conferido: bool = False, valor_conferido: bool = False) -> dict[str, Any]:
    aberta = _exp_correcao_aberta(pedido)
    if aberta:
        return {"ok": False, "situacao": "em_correcao", "error": aberta}
    motivo = _exp_caixa_valor_diferente(pedido, valor_visto)
    if motivo and not valor_conferido:
        return {"ok": False, "situacao": "valor_diferente", "error": motivo}
    r = exp_caixa_enviar(pedido, atendimento, cliente, valor_visto, usuario, conferido=conferido)
    if motivo and r.get("ok"):
        audit(usuario or "?", "expedicao.caixa_valor_conferido", f"{pedido}|{atendimento}|{valor_visto}")
    return r


def exp_valor_reservar(pedido: str, atendimento: Any, usuario: str) -> dict[str, Any]:
    """Painel: reserva a correção e devolve a senha. A extensão lê atendimento e valores pela senha."""
    pedido = str(pedido or "").strip()
    numero = re.sub(r"\D", "", str(atendimento or ""))
    if not pedido or not numero:
        return {"ok": False, "error": "Informe o pedido e o atendimento."}
    if _faturamento_correcao_ler(normalize(pedido)):
        return {"ok": False, "situacao": "em_correcao", "error": "Correção do valor em andamento ou pela metade."}
    c = _exp_valor_conferir(pedido, numero)
    a, valor = c["a"], c["valor"]
    if c["erro"]:
        return {"ok": False, "error": c["erro"]}
    if not a or not a.get("total_a_soltar") or a.get("faltam") or not a.get("bate"):
        return {"ok": False, "error": "Este atendimento não confere com o pedido: nada a corrigir."}
    if valor is None or c["atual"] is None:
        return {"ok": False, "error": "Sem o valor da venda ou do atendimento: confira no Apollo."}
    if abs(float(valor) - float(c["atual"])) <= 0.009:
        return {"ok": True, "ja_certo": True}
    if not a.get("valor_explicacao"):
        return {"ok": False, "error": "Diferença sem explicação: confira no Apollo."}
    trava = _faturamento_correcao_reservar(pedido, usuario, numero, round(float(valor), 2), c["atual"])
    if not trava:
        return {"ok": False, "situacao": "em_correcao", "error": "Correção do valor em andamento. Aguarde."}
    return {"ok": True, "trava": trava, "atendimento": numero, "valor_certo": round(float(valor), 2), "valor_atual": c["atual"]}


def faturamento_executar(pedido: str, usuario: str, condicao_ok: bool = False, trava: str = "",
                         liberar: bool = False) -> dict[str, Any]:
    """Um pedido do lote: confere DE NOVO, solta o romaneio e envia ao caixa. Shopee/Magalu
    param em "condicao" (a troca da condição de pagamento só existe pelo Linx web, na
    extensão do Chrome de quem clicou) e voltam com condicao_ok=True para o caixa."""
    pedido = str(pedido or "").strip()
    chave = normalize(pedido)
    trava = str(trava or "")
    with DB_LOCK:
        row = DB.execute("SELECT token, usuario, em FROM faturamento_correcao_v1999 WHERE order_key=?", (chave,)).fetchone()
        dono = bool(row and trava and secrets.compare_digest(str(row["token"]), trava))
        if row and not dono:
            return {"ok": False, "etapa": "preco", "error": f"Correção do valor em andamento ou pela metade "
                    f"({row['usuario']}, {str(row['em'])[11:16]}). Confira o atendimento no Linx e use Liberar."}
        if dono:
            DB.execute("DELETE FROM faturamento_correcao_v1999 WHERE order_key=?", (chave,))
            DB.commit()
    if liberar:
        return {"ok": False, "etapa": "preco", "error": "Correção do valor não feita."}
    mp = next((m for p, m in _faturamento_pendentes() if normalize(p) == chave), "")
    if not mp:
        return {"ok": False, "etapa": "conferencia", "error": "Pedido não está mais na fila."}
    c = faturamento_conferir(pedido, mp)
    if c["situacao"] == "corrigir_valor":
        # V19.99: a tela pede à extensão (Linx web) para trocar o preço e chama de novo — a próxima
        # conferência é que libera o romaneio (nunca confia que a correção deu certo).
        if dono:   # acabou de corrigir e o Apollo ainda não mostra: não pede outra correção
            return {"ok": False, "etapa": "preco", "error": f"Depois da correção o Apollo ainda mostra "
                    f"R$ {float(c.get('valor_atendimento') or 0):.2f} (venda R$ {float(c.get('valor_certo') or 0):.2f}). "
                    f"Confira no Linx.".replace(".", ",")}
        token = _faturamento_correcao_reservar(pedido, usuario, c["atendimento"], c.get("valor_certo"), c.get("valor_atendimento"))
        if not token:   # outra aba reservou no meio da conferência
            return {"ok": False, "etapa": "preco", "error": "Correção do valor em andamento. Aguarde."}
        return {"ok": True, "etapa": "preco", "atendimento": c["atendimento"], "marketplace": mp, "trava": token,
                "valor_certo": c.get("valor_certo"), "valor_atual": c.get("valor_atendimento")}
    if c["situacao"] not in ("pronto", "pronto_caixa"):
        return {"ok": False, "etapa": "conferencia", "situacao": c["situacao"], "error": c.get("motivo") or "Não está pronto."}
    if c["situacao"] == "pronto":
        r = exp_romaneio_soltar(pedido, c["atendimento"], FATURAMENTO_OBS.get(mp, mp.upper()), usuario)
        if not r.get("ok"):
            if r.get("situacao") == "ocupado":  # V20.33: porta ocupada, nada foi feito — a tela tenta de novo
                return {"ok": False, "etapa": "romaneio", "situacao": "ocupado", "error": r.get("error")}
            faturamento_conferir(pedido, mp)
            return {"ok": False, "etapa": "romaneio", "error": r.get("error") or "Romaneio não saiu."}
    if mp in ("Shopee", "Magalu") and not condicao_ok:
        return {"ok": True, "etapa": "condicao", "atendimento": c["atendimento"], "marketplace": mp}
    p = exp_caixa_previa(pedido, c["atendimento"], c["cliente"], usuario)
    if not p.get("pode"):
        motivo = "; ".join((p.get("impedimentos") or []) + (p.get("falhas") or [])) or p.get("error") or "Apollo recusou a prévia."
        faturamento_conferir(pedido, mp)
        return {"ok": False, "etapa": "caixa", "error": motivo}
    e = exp_caixa_enviar(pedido, p["atendimento"], p["cliente"], p.get("valor"), usuario)
    faturamento_conferir(pedido, mp)
    if not e.get("ok"):
        return {"ok": False, "etapa": "caixa", "situacao": e.get("situacao"), "error": e.get("error") or "Caixa não confirmou."}
    return {"ok": True, "etapa": "feito", "atendimento": p["atendimento"], "valor": p.get("valor")}


# ---------------------------------------------------------------------------
# V19.45 — Cadastro do cliente das vendas do FULL (decisões do dono, 16/10).
# Venda Full não passa pela fila (V18.78), mas a integração ML → Apollo cria o cliente
# com o nome da CONTA do comprador ("Premium Flex") em vez da razão social da nota
# ("M2 SOLUCOES GRAFICAS LTDA"). No Full quem emite a NF-e é o próprio ML (série 2), em
# nome da Noromak: os dados certos estão na nota. Regras (as mesmas do automático):
#   - NUNCA cria cliente: acha pelo CPF/CNPJ exato e só atualiza (nome, endereço sem
#     acento, e-mail/telefones padrão, categoria e I.E. da nota). Mais de um = não mexe.
#   - vendas Full dos últimos 30 dias: as de até 2 dias a qualquer hora; as mais antigas
#     só à noite (21h–6h), devagar, para não pesar na porta do Guilherme;
#   - nota ainda não disponível ou cliente fora do Apollo: tenta de hora em hora por 1
#     dia; depois fica "sem nota" / "não encontrado" na lista do cartão (corrige à mão);
#   - interruptor próprio, começa desligado; a 1ª resposta da API de notas fica guardada
#     (cadastro_full_amostra_v1945) para conferir os campos antes de ligar.
# Venda Full = anúncio com logística fulfillment (ml_estoque_dia_v1872) e que não passou
# pela expedição (não está em completed_orders). Só Araçatuba por enquanto.
# ---------------------------------------------------------------------------
FULL_CAD_DIAS = 30
FULL_CAD_RECENTE_DIAS = 2
FULL_CAD_INTERVALO = 3600          # 1 h entre tentativas da mesma venda
FULL_CAD_JANELA = 86400            # 1 dia tentando
FULL_CAD_POR_RODADA = 4
FULL_CAD_FINAIS = ("feito", "sem_nota", "nao_encontrado", "mais_de_um", "erro")


def ensure_cadastro_full_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """CREATE TABLE IF NOT EXISTS cadastro_full_v1945 (
                   order_id TEXT PRIMARY KEY,
                   inicio_epoch REAL NOT NULL DEFAULT 0,
                   ultima_epoch REAL NOT NULL DEFAULT 0,
                   tentativas INTEGER NOT NULL DEFAULT 0,
                   situacao TEXT NOT NULL DEFAULT 'aguardando',
                   detalhe TEXT NOT NULL DEFAULT '',
                   documento TEXT NOT NULL DEFAULT '',
                   nome TEXT NOT NULL DEFAULT '',
                   cliente TEXT NOT NULL DEFAULT '',
                   venda_dia TEXT NOT NULL DEFAULT '',
                   atualizado_em TEXT NOT NULL DEFAULT ''
               );
               CREATE TABLE IF NOT EXISTS cadastro_full_config_v1945 (
                   id INTEGER PRIMARY KEY CHECK (id = 1),
                   ligado INTEGER NOT NULL DEFAULT 0,
                   ligado_em TEXT NOT NULL DEFAULT '',
                   por TEXT NOT NULL DEFAULT ''
               );
               CREATE TABLE IF NOT EXISTS cadastro_full_amostra_v1945 (
                   tipo TEXT PRIMARY KEY,
                   recebido_em TEXT NOT NULL,
                   corpo TEXT NOT NULL
               );"""
        )
        DB.commit()


def cadastro_full_config() -> dict[str, Any]:
    with DB_LOCK:
        row = DB.execute("SELECT ligado, ligado_em, por FROM cadastro_full_config_v1945 WHERE id=1").fetchone()
    return {"ligado": bool(row and row["ligado"]), "ligado_em": (row["ligado_em"] if row else ""),
            "por": (row["por"] if row else "")}


def cadastro_full_ligar(ligado: bool, usuario: str) -> dict[str, Any]:
    with DB_LOCK:
        DB.execute(
            """INSERT INTO cadastro_full_config_v1945(id, ligado, ligado_em, por) VALUES(1,?,?,?)
               ON CONFLICT(id) DO UPDATE SET ligado=excluded.ligado, ligado_em=excluded.ligado_em, por=excluded.por""",
            (1 if ligado else 0, now_iso() if ligado else "", str(usuario or "")[:80]),
        )
        DB.commit()
    audit(usuario, "expedicao.cadastro_full", "ligado" if ligado else "desligado")
    return {"ok": True, **cadastro_full_config()}


def _full_cad_amostra(tipo: str, corpo: Any) -> None:
    with DB_LOCK:
        DB.execute("INSERT OR IGNORE INTO cadastro_full_amostra_v1945(tipo, recebido_em, corpo) VALUES(?,?,?)",
                   (tipo, now_iso(), (corpo if isinstance(corpo, str) else json.dumps(corpo, ensure_ascii=False))[:60000]))
        DB.commit()


def _nfe_tag(no: Any, nome: str) -> str:
    """Texto do 1º filho com esse nome (ignora o namespace da NF-e)."""
    if no is None:
        return ""
    for el in no.iter():
        if str(el.tag).rsplit("}", 1)[-1] == nome:
            return str(el.text or "").strip()
    return ""


def _nfe_bloco(raiz: Any, nome: str) -> Any:
    for el in raiz.iter():
        if str(el.tag).rsplit("}", 1)[-1] == nome:
            return el
    return None


def nfe_destinatario_do_xml(xml: str) -> dict[str, Any] | None:
    """Destinatário da NF-e (layout nacional: dest/CNPJ|CPF, xNome, IE, indIEDest, enderDest)."""
    import xml.etree.ElementTree as ET
    try:
        raiz = ET.fromstring(xml.encode("utf-8") if isinstance(xml, str) else xml)
    except ET.ParseError:
        return None
    dest = _nfe_bloco(raiz, "dest")
    if dest is None:
        return None
    end = _nfe_bloco(dest, "enderDest")
    numero = _nfe_tag(end, "nro")
    return {
        "documento": re.sub(r"\D", "", _nfe_tag(dest, "CNPJ") or _nfe_tag(dest, "CPF")),
        "nome": _nfe_tag(dest, "xNome"),
        "ie": _nfe_tag(dest, "IE"),
        "contribuinte": _nfe_tag(dest, "indIEDest"),
        "endereco": {"rua": _nfe_tag(end, "xLgr"), "numero": "" if numero.upper() in ("SN", "S/N", "0") else numero,
                     "complemento": _nfe_tag(end, "xCpl"), "bairro": _nfe_tag(end, "xBairro"),
                     "cep": re.sub(r"\D", "", _nfe_tag(end, "CEP")), "cidade": _nfe_tag(end, "xMun"),
                     "uf": _nfe_tag(end, "UF")},
    }


def _full_cad_procurar_xml(dado: Any, profundidade: int = 0) -> str:
    """Leitura tolerante: a resposta da API de notas pode trazer o XML inteiro em algum campo."""
    if profundidade > 6:
        return ""
    if isinstance(dado, str):
        return dado if "<dest" in dado or "<nfeProc" in dado else ""
    itens = dado.values() if isinstance(dado, dict) else dado if isinstance(dado, list) else []
    for v in itens:
        achado = _full_cad_procurar_xml(v, profundidade + 1)
        if achado:
            return achado
    return ""


def _full_cad_destinatario_json(dado: Any) -> dict[str, Any] | None:
    """Reserva: destinatário em JSON (nomes de campo a confirmar na amostra)."""
    if not isinstance(dado, dict):
        return None
    for chave in ("receiver", "recipient", "destinatario", "buyer", "customer"):
        d = dado.get(chave)
        if isinstance(d, dict):
            ident = d.get("identification") if isinstance(d.get("identification"), dict) else {}
            doc = re.sub(r"\D", "", str(d.get("document") or ident.get("number") or d.get("doc_number") or ""))
            nome = str(d.get("name") or d.get("business_name") or d.get("legal_name") or "")
            a = d.get("address") if isinstance(d.get("address"), dict) else {}
            if doc and nome:
                return {"documento": doc, "nome": nome, "ie": str(d.get("state_registration") or d.get("ie") or ""),
                        "contribuinte": "",
                        "endereco": {"rua": a.get("street_name") or a.get("street") or "", "numero": str(a.get("street_number") or a.get("number") or ""),
                                     "complemento": a.get("comment") or a.get("complement") or "",
                                     "bairro": (a.get("neighborhood") or {}).get("name") if isinstance(a.get("neighborhood"), dict) else a.get("neighborhood") or "",
                                     "cep": re.sub(r"\D", "", str(a.get("zip_code") or "")),
                                     "cidade": (a.get("city") or {}).get("name") if isinstance(a.get("city"), dict) else a.get("city") or "",
                                     "uf": str(((a.get("state") or {}).get("id") if isinstance(a.get("state"), dict) else a.get("state")) or "").split("-")[-1]}}
    for v in dado.values():
        if isinstance(v, dict):
            achado = _full_cad_destinatario_json(v)
            if achado:
                return achado
        elif isinstance(v, list):
            for x in v:
                achado = _full_cad_destinatario_json(x)
                if achado:
                    return achado
    return None


def _full_cad_destinatario_ml(dado: Any) -> dict[str, Any] | None:
    """Formato REAL de /users/{seller}/invoices/orders/{order} (conferido em 16/10, venda
    2000018994767276): recipient.name, recipient.address{street_name, street_number,
    complement, neighborhood, city, zip_code, state}, recipient.identifications{cnpj|cpf, ie, ie_type}."""
    r = dado.get("recipient") if isinstance(dado, dict) else None
    if not isinstance(r, dict):
        return None
    ids = r.get("identifications") if isinstance(r.get("identifications"), dict) else {}
    a = r.get("address") if isinstance(r.get("address"), dict) else {}
    complemento = re.split(r"\s*Refer[eê]ncia\s*:", str(a.get("complement") or ""), flags=re.I)[0]
    ie_tipo = str(ids.get("ie_type") or "").lower()
    return {"documento": re.sub(r"\D", "", str(ids.get("cnpj") or ids.get("cpf") or "")),
            "nome": str(r.get("name") or ""),
            "ie": str(ids.get("ie") or "") if ie_tipo in ("", "contribuinte") else "",
            "contribuinte": ie_tipo,
            "endereco": {"rua": a.get("street_name") or "", "numero": str(a.get("street_number") or ""),
                         "complemento": complemento, "bairro": a.get("neighborhood") or "",
                         "cep": re.sub(r"\D", "", str(a.get("zip_code") or "")), "cidade": a.get("city") or "",
                         "uf": str(a.get("state") or "")[-2:]}}


def ml_nota_da_venda(order_id: str) -> dict[str, Any] | None:
    """NF-e que o ML emitiu para a venda (Full). None = nota ainda não disponível."""
    row = ml_integration_row()
    seller = str(row["seller_id"] if row else "").strip()
    if not seller:
        raise RuntimeError("Mercado Livre sem conta conectada.")
    try:
        dado = ml_api_get(f"/users/{seller}/invoices/orders/{quote(str(order_id))}")
    except RuntimeError as exc:
        if "HTTP 404" in str(exc):
            return None
        raise
    _full_cad_amostra("nota", dado)
    if isinstance(dado, dict) and str(dado.get("status") or "authorized") != "authorized":
        return None                                  # nota ainda não autorizada
    nota = _full_cad_destinatario_ml(dado)
    if not nota:
        xml = _full_cad_procurar_xml(dado)
        nota = (nfe_destinatario_do_xml(xml) if xml else None) or _full_cad_destinatario_json(dado)
    return nota


def full_cadastro_atualizar(order_id: str, nota: dict[str, Any], usuario: str = "automatico") -> dict[str, Any]:
    """Atualiza no Apollo o cliente da venda Full com os dados da nota. NUNCA cria."""
    documento = re.sub(r"\D", "", str(nota.get("documento") or ""))
    nome = _exp_limpo(nota.get("nome"))[:70]
    if len(documento) not in (11, 14) or not nome:
        return {"ok": False, "situacao": "erro", "error": "Nota sem CPF/CNPJ ou nome do destinatário."}
    e = nota.get("endereco") or {}
    endereco = {"rua": _exp_limpo(e.get("rua"))[:120], "numero": str(e.get("numero") or "").strip()[:10],
                "complemento": _exp_limpo(e.get("complemento"))[:60], "bairro": _exp_limpo(e.get("bairro"))[:50],
                "cep": re.sub(r"\D", "", str(e.get("cep") or "")), "cidade": _exp_limpo(e.get("cidade"))[:50],
                "uf": _exp_limpo(e.get("uf"))[:2]}
    avisos: list[str] = []
    if any(not endereco[k] for k in ("rua", "bairro", "cep", "cidade", "uf")):
        endereco = None
        avisos.append("Endereço da nota incompleto: não enviado.")
    elif not endereco["complemento"]:
        del endereco["complemento"]
    ie = re.sub(r"\D", "", str(nota.get("ie") or ""))
    # Categoria pela nota (V19.44): CPF 1; CNPJ com I.E. 3; CNPJ sem I.E. 2 + ISENTO.
    if len(documento) == 11:
        fiscal: dict[str, Any] = {"categoria": 1}
    elif ie:
        fiscal = {"categoria": 3, "inscricao_estadual": ie[:20]}
    else:
        fiscal = {"categoria": 2, "inscricao_estadual": "ISENTO"}
    operador = usuario[:60] or "noromak"
    with EXP_PORTA_LOCK:
        try:
            b = exp_buscar_cliente(documento, operador)
            if b["situacao"] == "mais_de_um":
                return {"ok": False, "situacao": "mais_de_um", "error": "Mais de um cliente com este CPF/CNPJ no Apollo."}
            if b["situacao"] != "encontrado" or not b["cliente"]:
                return {"ok": False, "situacao": "nao_cadastrado", "error": "Cliente ainda não está no Apollo."}
            codigo = b["cliente"]
            corpo = {"revenda": EXP_REVENDA, "cliente": int(codigo), "documento": documento, "operador": operador,
                     "email": LINX_CADASTRO_EMAIL, "ddd_telefone": LINX_CADASTRO_DDD, "telefone": LINX_CADASTRO_TELEFONE,
                     "ddd_celular": LINX_CADASTRO_DDD, "celular": EXP_CELULAR_PADRAO, "nome": nome, **fiscal}
            if endereco:
                corpo["endereco"] = endereco
            at = _exp_porta("cliente/atualizar", corpo, escrita=True)
        except PortaErro as exc:
            return {"ok": False, "situacao": "erro", "error": str(exc)}
    if at.get("situacao") != "atualizado":
        return {"ok": False, "situacao": "erro", "cliente": codigo, "error": at.get("erro") or "O Apollo não confirmou."}
    avisos += [str(x) for x in (at.get("avisos") or [])]
    audit(usuario, "expedicao.cadastro_full", f"{order_id}|{codigo}|{b.get('nome', '')[:40]} -> {nome[:40]}")
    return {"ok": True, "situacao": "atualizado", "cliente": codigo, "nome": nome, "nome_antes": b.get("nome", ""),
            "avisos": avisos}


def _full_cad_vendas(hoje: date | None = None) -> list[dict[str, str]]:
    """Vendas Full (Araçatuba) dos últimos 30 dias que não passaram pela expedição."""
    hoje = hoje or datetime.now(BR_TZ).date()
    desde = (hoje - timedelta(days=FULL_CAD_DIAS)).isoformat()
    with DB_LOCK:
        full = {r["item_id"] for r in DB.execute(
            "SELECT DISTINCT item_id FROM ml_estoque_dia_v1872 WHERE logistica='fulfillment' AND dia >= ?",
            ((hoje - timedelta(days=FULL_CAD_DIAS + 7)).isoformat(),)).fetchall()}
        vendas = DB.execute(
            "SELECT order_id, MIN(sale_day) AS dia, GROUP_CONCAT(DISTINCT anuncio) AS anuncios FROM vendas_v1799 "
            "WHERE marketplace='ml' AND sale_day >= ? GROUP BY order_id ORDER BY dia DESC", (desde,)).fetchall()
        concluidos = {r["order_id"] for r in DB.execute("SELECT order_id FROM completed_orders").fetchall()}
    saida = []
    for v in vendas:
        anuncios = set(str(v["anuncios"] or "").split(","))
        if anuncios & full and v["order_id"] not in concluidos:
            saida.append({"order_id": str(v["order_id"]), "dia": str(v["dia"])})
    return saida


def _full_cad_registrar(order_id: str, dia: str, inicio: float, agora: float, tentativas: int, situacao: str,
                        detalhe: str, documento: str = "", nome: str = "", cliente: str = "") -> None:
    with DB_LOCK:
        DB.execute(
            """INSERT INTO cadastro_full_v1945(order_id,inicio_epoch,ultima_epoch,tentativas,situacao,detalhe,documento,nome,cliente,venda_dia,atualizado_em)
               VALUES(?,?,?,?,?,?,?,?,?,?,?)
               ON CONFLICT(order_id) DO UPDATE SET ultima_epoch=excluded.ultima_epoch, tentativas=excluded.tentativas,
                   situacao=excluded.situacao, detalhe=excluded.detalhe,
                   documento=CASE WHEN excluded.documento<>'' THEN excluded.documento ELSE cadastro_full_v1945.documento END,
                   nome=CASE WHEN excluded.nome<>'' THEN excluded.nome ELSE cadastro_full_v1945.nome END,
                   cliente=CASE WHEN excluded.cliente<>'' THEN excluded.cliente ELSE cadastro_full_v1945.cliente END,
                   atualizado_em=excluded.atualizado_em""",
            (order_id, inicio, agora, tentativas, situacao, str(detalhe or "")[:400], documento, nome[:120], cliente, dia, now_iso()),
        )
        DB.commit()


def cadastro_full_rodada(agora: float | None = None, esperar=None, hoje: date | None = None) -> dict[str, int]:
    cfg = cadastro_full_config()
    contagem: dict[str, int] = {}
    if not cfg["ligado"] or not EXP_CADASTRO_API:
        return contagem
    agora = float(agora if agora is not None else time.time())
    hoje = hoje or datetime.fromtimestamp(agora, BR_TZ).date()
    hora = datetime.fromtimestamp(agora, BR_TZ).hour
    noite = hora >= 21 or hora < 6
    recente = (hoje - timedelta(days=FULL_CAD_RECENTE_DIAS)).isoformat()
    with DB_LOCK:
        estados = {r["order_id"]: dict(r) for r in DB.execute("SELECT * FROM cadastro_full_v1945").fetchall()}
    feitos = 0
    for v in _full_cad_vendas(hoje):
        e = estados.get(v["order_id"]) or {}
        if e.get("situacao") in FULL_CAD_FINAIS:
            continue
        if e.get("ultima_epoch") and agora - float(e["ultima_epoch"]) < FULL_CAD_INTERVALO:
            continue
        if v["dia"] < recente and not noite:          # antigas só à noite
            continue
        if feitos >= FULL_CAD_POR_RODADA:
            break
        if feitos and esperar:
            esperar(25)
        feitos += 1
        inicio = float(e.get("inicio_epoch") or agora)
        tent = int(e.get("tentativas") or 0) + 1
        vencido = agora - inicio >= FULL_CAD_JANELA
        nota: dict[str, Any] | None = None
        try:
            nota = ml_nota_da_venda(v["order_id"])
            if not nota:
                r = {"ok": False, "situacao": "sem_nota", "error": "Nota do ML ainda não disponível."}
            else:
                r = full_cadastro_atualizar(v["order_id"], nota)
        except Exception as exc:
            r = {"ok": False, "situacao": "erro", "error": str(exc)}
        sit = str(r.get("situacao") or "")
        if r.get("ok"):
            final = "feito"
            det = f"{r.get('nome_antes') or '?'} → {r.get('nome')}" + ("; " + "; ".join(r["avisos"]) if r.get("avisos") else "")
        elif sit == "mais_de_um":
            final, det = "mais_de_um", r["error"]
        elif sit == "sem_nota":
            final, det = ("sem_nota" if vencido else "aguardando"), r["error"]
        elif sit == "nao_cadastrado":
            final, det = ("nao_encontrado" if vencido else "aguardando"), r["error"]
        else:
            final, det = ("erro" if vencido else "aguardando"), str(r.get("error") or "erro")
        _full_cad_registrar(v["order_id"], v["dia"], inicio, agora, tent, final, det,
                            str((nota or {}).get("documento") or ""), _exp_limpo((nota or {}).get("nome")),
                            str(r.get("cliente") or ""))
        contagem[final] = contagem.get(final, 0) + 1
    return contagem


def cadastro_full_loop(stop_event: threading.Event) -> None:
    while not stop_event.is_set():
        try:
            cadastro_full_rodada(esperar=lambda s: stop_event.wait(s))
        except Exception as exc:
            print(f"[cadastro-full] {exc}", flush=True)
        stop_event.wait(300)


def cadastro_full_payload() -> dict[str, Any]:
    with DB_LOCK:
        cont = {r["situacao"]: int(r["n"]) for r in DB.execute(
            "SELECT situacao, COUNT(*) AS n FROM cadastro_full_v1945 GROUP BY situacao").fetchall()}
        pendencias = [dict(r) for r in DB.execute(
            "SELECT order_id, venda_dia, situacao, detalhe, documento, nome, cliente FROM cadastro_full_v1945 "
            "WHERE situacao IN ('sem_nota','nao_encontrado','mais_de_um','erro') ORDER BY venda_dia DESC LIMIT 100").fetchall()]
        feitos = [dict(r) for r in DB.execute(
            "SELECT order_id, venda_dia, detalhe, nome, cliente FROM cadastro_full_v1945 WHERE situacao='feito' "
            "ORDER BY ultima_epoch DESC LIMIT 20").fetchall()]
        amostra = DB.execute("SELECT COUNT(*) AS n FROM cadastro_full_amostra_v1945").fetchone()["n"]
    return {"ok": True, **cadastro_full_config(), "contagem": cont, "pendencias": pendencias, "feitos": feitos,
            "tem_amostra": bool(amostra)}


