def ensure_posvenda_contas_schema() -> None:
    """V20.01: conta (Araçatuba/Bauru) em perguntas e reclamações; tudo o que já existia era da
    principal. A reputação antiga (uma linha por dia) é copiada para a tabela por conta."""
    with DB_LOCK:
        for tabela in ("ml_reclamacao_v1888", "ml_pergunta_v1888"):
            if "conta" not in {r[1] for r in DB.execute(f"PRAGMA table_info({tabela})")}:
                DB.execute(f"ALTER TABLE {tabela} ADD COLUMN conta TEXT NOT NULL DEFAULT '{CASA_PRINCIPAL}'")
        DB.executescript(
            """
            CREATE INDEX IF NOT EXISTS idx_ml_pergunta_conta ON ml_pergunta_v1888(conta, status);
            CREATE INDEX IF NOT EXISTS idx_ml_pergunta_item ON ml_pergunta_v1888(item_id, status);
            CREATE INDEX IF NOT EXISTS idx_ml_reclamacao_conta ON ml_reclamacao_v1888(conta, status);
            CREATE TABLE IF NOT EXISTS ml_reputacao_conta_v2001 (
                conta TEXT NOT NULL,
                dia TEXT NOT NULL,
                nivel TEXT NOT NULL DEFAULT '',
                mercado_lider TEXT NOT NULL DEFAULT '',
                vendas_periodo INTEGER,
                periodo TEXT NOT NULL DEFAULT '',
                reclamacoes_taxa REAL,
                reclamacoes_qtd INTEGER,
                atrasos_taxa REAL,
                atrasos_qtd INTEGER,
                cancelamentos_taxa REAL,
                cancelamentos_qtd INTEGER,
                atualizado_em TEXT NOT NULL DEFAULT '',
                PRIMARY KEY (conta, dia)
            );
            CREATE TABLE IF NOT EXISTS posvenda_resposta_pronta_v2001 (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                titulo TEXT NOT NULL DEFAULT '',
                texto TEXT NOT NULL DEFAULT '',
                atualizado_por TEXT NOT NULL DEFAULT '',
                atualizado_em TEXT NOT NULL DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS posvenda_config_v2001 (
                chave TEXT PRIMARY KEY,
                valor TEXT NOT NULL DEFAULT '',
                atualizado_por TEXT NOT NULL DEFAULT '',
                atualizado_em TEXT NOT NULL DEFAULT ''
            );
            """
        )
        DB.execute(
            "INSERT OR IGNORE INTO ml_reputacao_conta_v2001(conta,dia,nivel,mercado_lider,vendas_periodo,periodo,"
            "reclamacoes_taxa,reclamacoes_qtd,atrasos_taxa,atrasos_qtd,cancelamentos_taxa,cancelamentos_qtd,atualizado_em) "
            "SELECT ?,dia,nivel,mercado_lider,vendas_periodo,periodo,reclamacoes_taxa,reclamacoes_qtd,atrasos_taxa,"
            "atrasos_qtd,cancelamentos_taxa,cancelamentos_qtd,atualizado_em FROM ml_reputacao_dia_v1888", (CASA_PRINCIPAL,))
        DB.commit()


def _posvenda_trava_conta(conta: str) -> threading.Lock:
    """Revisão 29/10: a trava das reclamações é por conta — com uma só, o "Buscar agora" no meio da
    rodada de Araçatuba pulava também Bauru (e o worker pulava Bauru enquanto o manual rodava)."""
    with POSVENDA_LOCK:
        return POSVENDA_CONTA_LOCKS.setdefault(conta, threading.Lock())


def _posvenda_estado_conta(conta: str, parte: str, resultado: dict[str, Any]) -> None:
    """Guarda o resultado da leitura daquela conta; a principal também nas chaves antigas."""
    _POSVENDA_ESTADO.setdefault("contas", {}).setdefault(conta, {})[parte] = resultado
    if conta == CASA_PRINCIPAL:
        _POSVENDA_ESTADO["ultimo" if parte == "reclamacoes" else "perguntas"] = resultado


def _posvenda_iso_ml(dt: datetime) -> str:
    """Data no formato que a busca de reclamações exige (com milissegundos)."""
    return dt.astimezone(BR_TZ).strftime("%Y-%m-%dT%H:%M:%S.000-03:00")


def _posvenda_dt(valor: Any) -> datetime | None:
    texto = str(valor or "").strip()
    if not texto:
        return None
    try:
        dt = datetime.fromisoformat(texto.replace("Z", "+00:00"))
    except ValueError:
        return None
    return dt if dt.tzinfo else dt.replace(tzinfo=BR_TZ)


def _posvenda_float(valor: Any) -> float | None:
    if isinstance(valor, bool) or valor is None or valor == "":
        return None
    try:
        return float(valor)
    except (TypeError, ValueError):
        return None


def _posvenda_vendedor(claim: dict[str, Any]) -> dict[str, Any]:
    for p in claim.get("players") or []:
        if isinstance(p, dict) and (p.get("role") == "respondent" or p.get("type") == "seller"):
            return p
    return {}


def _posvenda_acao_vendedor(claim: dict[str, Any]) -> tuple[str, str]:
    """(ação, prazo) que o vendedor precisa cumprir: a obrigatória com o prazo mais curto."""
    melhor: tuple[str, str] = ("", "")
    for a in _posvenda_vendedor(claim).get("available_actions") or []:
        if not isinstance(a, dict) or not a.get("mandatory"):
            continue
        prazo = str(a.get("due_date") or "")
        if not melhor[0] or (prazo and (not melhor[1] or prazo < melhor[1])):
            melhor = (str(a.get("action") or ""), prazo)
    return melhor


def _posvenda_prazo(r: dict[str, Any]) -> str:
    """Prazo do vendedor: o da ação obrigatória (busca); sem ela, o do detalhe quando a
    vez é do vendedor. Guardados em colunas separadas para a busca não apagar o do detalhe."""
    if r.get("prazo"):
        return str(r["prazo"])
    if r.get("responsavel") == "seller" and r.get("prazo_detalhe"):
        return str(r["prazo_detalhe"])
    return ""


def _posvenda_base_da_busca(claim: dict[str, Any]) -> dict[str, Any]:
    """Campos que a própria busca já traz."""
    res = claim.get("resolution") if isinstance(claim.get("resolution"), dict) else {}
    acao, prazo = _posvenda_acao_vendedor(claim)
    recurso = str(claim.get("resource") or "")
    relacionados = [str(x) for x in (claim.get("related_entities") or [])]
    tipo = str(claim.get("type") or "")
    entregue = claim.get("fulfilled")
    return {
        "claim_id": str(claim.get("id") or ""),
        "order_id": str(claim.get("resource_id") or "") if recurso == "order" else "",
        "recurso": recurso,
        "tipo": tipo,
        "etapa": str(claim.get("stage") or ""),
        "status": str(claim.get("status") or ""),
        "motivo_id": str(claim.get("reason_id") or ""),
        "entregue": None if entregue is None else (1 if entregue else 0),
        "aberta_em": str(claim.get("date_created") or ""),
        "atualizada_ml": str(claim.get("last_updated") or ""),
        "fechada_em": str(res.get("date_created") or "") if res else "",
        "resolucao": str(res.get("reason") or "") if res else "",
        "beneficiado": ",".join(str(x) for x in (res.get("benefited") or [])) if res else "",
        "fechada_por": str(res.get("closed_by") or "") if res else "",
        "cobertura": (1 if res.get("applied_coverage") else 0) if res and res.get("applied_coverage") is not None else None,
        "acao": acao,
        "prazo": prazo,
        "tem_devolucao": 1 if ("return" in relacionados or tipo in ("return", "returns")) else 0,
    }


def _posvenda_gravar_base(base: dict[str, Any]) -> bool:
    """Grava/atualiza a reclamação. Devolve True quando é nova ou mudou no ML."""
    agora = now_iso()
    with DB_LOCK:
        atual = DB.execute("SELECT atualizada_ml, status, detalhado_em FROM ml_reclamacao_v1888 WHERE claim_id=?",
                           (base["claim_id"],)).fetchone()
        mudou = atual is None or str(atual["atualizada_ml"]) != base["atualizada_ml"] or str(atual["status"]) != base["status"]
        if atual is None:
            DB.execute(
                "INSERT INTO ml_reclamacao_v1888(claim_id,order_id,recurso,tipo,etapa,status,motivo_id,entregue,aberta_em,"
                "atualizada_ml,fechada_em,resolucao,beneficiado,fechada_por,cobertura,acao,prazo,tem_devolucao,"
                "precisa_detalhe,updated_at,conta) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,?,?)",
                (base["claim_id"], base["order_id"], base["recurso"], base["tipo"], base["etapa"], base["status"],
                 base["motivo_id"], base["entregue"], base["aberta_em"], base["atualizada_ml"], base["fechada_em"],
                 base["resolucao"], base["beneficiado"], base["fechada_por"], base["cobertura"], base["acao"],
                 base["prazo"], base["tem_devolucao"], agora, ml_casa_atual()))   # V20.01: conta que leu
        else:
            DB.execute(
                "UPDATE ml_reclamacao_v1888 SET order_id=CASE WHEN ?<>'' THEN ? ELSE order_id END,recurso=?,tipo=?,etapa=?,"
                "status=?,motivo_id=?,entregue=?,aberta_em=?,atualizada_ml=?,fechada_em=?,resolucao=?,beneficiado=?,"
                "fechada_por=?,cobertura=?,acao=?,prazo=?,tem_devolucao=MAX(tem_devolucao,?),"
                "precisa_detalhe=CASE WHEN ? THEN 1 ELSE precisa_detalhe END,updated_at=? WHERE claim_id=?",
                (base["order_id"], base["order_id"], base["recurso"], base["tipo"], base["etapa"], base["status"],
                 base["motivo_id"], base["entregue"], base["aberta_em"], base["atualizada_ml"], base["fechada_em"],
                 base["resolucao"], base["beneficiado"], base["fechada_por"], base["cobertura"], base["acao"],
                 base["prazo"], base["tem_devolucao"], 1 if mudou else 0, agora, base["claim_id"]))
        DB.commit()
    return mudou


def _posvenda_pedido_valores(order: dict[str, Any]) -> dict[str, Any]:
    """Valor da venda, quanto foi devolvido ao comprador e os itens (SKU, qtd, preço)."""
    itens = []
    total_itens = 0.0
    for oi in order.get("order_items") or []:
        if not isinstance(oi, dict):
            continue
        item = oi.get("item") if isinstance(oi.get("item"), dict) else {}
        qtd = _posvenda_float(oi.get("quantity")) or 0.0
        preco = _posvenda_float(oi.get("unit_price")) or 0.0
        total_itens += qtd * preco
        itens.append({"item_id": str(item.get("id") or ""), "titulo": str(item.get("title") or ""),
                      "sku": str(item.get("seller_sku") or item.get("seller_custom_field") or ""),
                      "qtd": qtd, "preco": preco})
    total = _posvenda_float(order.get("total_amount"))
    if total is None and itens:
        total = round(total_itens, 2)
    reembolsado: float | None = None
    pagamentos = [p for p in (order.get("payments") or []) if isinstance(p, dict)]
    if pagamentos:
        reembolsado = round(sum(_posvenda_float(p.get("transaction_amount_refunded")) or 0.0 for p in pagamentos), 2)
    return {"pedido_total": total, "reembolsado": reembolsado, "itens": itens}


def _posvenda_motivo(motivo_id: str) -> None:
    """Nome do motivo (PDD/PNR...), uma vez por motivo."""
    if not motivo_id:
        return
    with DB_LOCK:
        if DB.execute("SELECT 1 FROM ml_reclamacao_motivo_v1888 WHERE motivo_id=?", (motivo_id,)).fetchone():
            return
    try:
        r = ml_api_get(f"/post-purchase/v1/claims/reasons/{quote(motivo_id)}")
    except Exception:
        return
    if not isinstance(r, dict):
        return
    with DB_LOCK:
        DB.execute("INSERT OR REPLACE INTO ml_reclamacao_motivo_v1888(motivo_id,nome,detalhe,buscado_em) VALUES(?,?,?,?)",
                   (motivo_id, str(r.get("name") or ""), str(r.get("detail") or ""), now_iso()))
        DB.commit()


def _posvenda_detalhar(claim_id: str) -> dict[str, Any]:
    """Busca no ML os detalhes de uma reclamação. Cada parte que falha fica em branco
    (desconhecido nunca vira zero) e o erro é guardado na linha."""
    with DB_LOCK:
        r = DB.execute("SELECT * FROM ml_reclamacao_v1888 WHERE claim_id=?", (claim_id,)).fetchone()
    if r is None:
        return {"ok": False, "erro": "reclamação não encontrada"}
    row = dict(r)
    upd: dict[str, Any] = {}
    erros: list[str] = []
    aberta = row["status"] == "opened"
    cid = quote(claim_id)

    def tentar(nome: str, funcao: Any) -> Any:
        try:
            return funcao()
        except Exception as exc:
            msg = str(exc)
            # 404 = o ML não tem esse dado para a reclamação (sem devolução, sem custo...)
            if "HTTP 404" not in msg:
                erros.append(f"{nome}: {msg[:160]}")
            return None

    if aberta:
        det = tentar("detalhe", lambda: ml_api_get(f"/post-purchase/v1/claims/{cid}/detail"))
        if isinstance(det, dict):
            upd["responsavel"] = str(det.get("action_responsible") or "")
            upd["titulo_ml"] = str(det.get("title") or "")
            upd["problema"] = str(det.get("problem") or "")
            upd["prazo_detalhe"] = str(det.get("due_date") or "")
        rep = tentar("reputação", lambda: ml_api_get(f"/post-purchase/v1/claims/{cid}/affects-reputation"))
        if isinstance(rep, dict):
            upd["afeta_reputacao"] = str(rep.get("affects_reputation") or "")
    _posvenda_motivo(row["motivo_id"])

    order_id = row["order_id"]
    if row["tem_devolucao"]:
        dev = tentar("devolução", lambda: ml_api_get(f"/post-purchase/v2/claims/{cid}/returns"))
        if isinstance(dev, dict) and dev:
            upd["devolucao_status"] = str(dev.get("status") or "")
            upd["devolucao_subtipo"] = str(dev.get("subtype") or "")
            upd["dinheiro_status"] = str(dev.get("status_money") or "")
            destinos = [str(((s.get("destination") or {}).get("name")) or "") for s in (dev.get("shipments") or [])
                        if isinstance(s, dict) and s.get("type") == "return"]
            upd["devolucao_destino"] = destinos[0] if destinos else ""
            # V19.88: o código da etiqueta de volta (envio e rastreio) para o bip das Devoluções.
            envios = {normalize(s.get(c)) for s in (dev.get("shipments") or [])
                      if isinstance(s, dict) and s.get("type") == "return"
                      for c in ("shipment_id", "tracking_number")}
            envios.discard("")
            if envios:
                upd["devolucao_envios"] = "," + ",".join(sorted(envios)) + ","
            if not order_id:
                pedidos = [o for o in (dev.get("orders") or []) if isinstance(o, dict) and o.get("order_id")]
                if pedidos:
                    order_id = upd["order_id"] = str(pedidos[0]["order_id"])
            if "reviews" in [str(x) for x in (dev.get("related_entities") or [])] and dev.get("id"):
                rev = tentar("revisão", lambda: ml_api_get(f"/post-purchase/v1/returns/{quote(str(dev['id']))}/reviews"))
                for rv in (rev or {}).get("reviews") or [] if isinstance(rev, dict) else []:
                    for rr in rv.get("resource_reviews") or []:
                        if isinstance(rr, dict) and rr.get("product_condition"):
                            upd["produto_condicao"] = str(rr["product_condition"])
        custo = tentar("frete da devolução", lambda: ml_api_get(f"/post-purchase/v1/claims/{cid}/charges/return-cost"))
        if isinstance(custo, dict) and _posvenda_float(custo.get("amount")) is not None:
            upd["frete_devolucao"] = round(float(custo["amount"]), 2)
    if order_id:
        order = tentar("pedido", lambda: ml_api_get(f"/orders/{quote(order_id)}"))
        if isinstance(order, dict) and order:
            v = _posvenda_pedido_valores(order)
            upd["pedido_total"] = v["pedido_total"]
            upd["reembolsado"] = v["reembolsado"]
            upd["itens_json"] = json_dumps(v["itens"])
    upd["erro"] = "; ".join(erros)[:600]
    upd["detalhado_em"] = now_iso()
    upd["precisa_detalhe"] = 0
    upd["updated_at"] = now_iso()
    with DB_LOCK:
        DB.execute(f"UPDATE ml_reclamacao_v1888 SET {', '.join(k + '=?' for k in upd)} WHERE claim_id=?",
                   tuple(upd.values()) + (claim_id,))
        DB.commit()
    return {"ok": not erros, "erros": erros}


def _posvenda_buscar(seller_id: str, filtros: dict[str, str], stop_event: threading.Event | None = None,
                     maximo: int = 3000) -> list[dict[str, Any]]:
    achados: list[dict[str, Any]] = []
    offset = 0
    while offset < maximo:
        params = {"players.role": "respondent", "players.user_id": seller_id, "limit": "100", "offset": str(offset),
                  "sort": "last_updated:desc", **filtros}
        r = ml_api_get("/post-purchase/v1/claims/search?" + urlencode(params))
        dados = (r.get("data") if isinstance(r, dict) else None) or []
        achados += [c for c in dados if isinstance(c, dict) and c.get("id")]
        total = int(((r.get("paging") or {}).get("total") or 0) if isinstance(r, dict) else 0)
        offset += 100
        if not dados or offset >= total or offset + 100 >= 10000:
            break
        if stop_event is not None and stop_event.wait(POSVENDA_PAUSA):
            break
    return achados


def posvenda_reclamacoes_rodada(stop_event: threading.Event | None = None, *, agora: datetime | None = None,
                                pausa: float | None = None) -> dict[str, Any]:
    """Busca as reclamações abertas e as que mudaram, e detalha as novas/alteradas.
    V20.01: da conta da casa atual (ml_na_casa); cada conta tem o seu ponto de partida e a sua fila."""
    conta = ml_casa_atual()
    trava = _posvenda_trava_conta(conta)
    if not trava.acquire(blocking=False):
        return {"ok": True, "pulado": "já está rodando"}
    pausa = POSVENDA_PAUSA if pausa is None else pausa
    agora = agora or datetime.now(timezone.utc)
    try:
        _POSVENDA_ESTADO.update(rodando=True, inicio=now_iso(), fim="")
        linha = ml_integration_row()
        if not linha or not str(linha["access_token"] or "").strip():
            resultado = {"ok": True, "pulado": "Mercado Livre não conectado"}
            _posvenda_estado_conta(conta, "reclamacoes", resultado)
            return resultado
        seller_id = str(linha["seller_id"] or "")
        with DB_LOCK:
            ultima = DB.execute("SELECT MAX(atualizada_ml) AS m FROM ml_reclamacao_v1888 WHERE conta=?",
                                (conta,)).fetchone()["m"]
        try:
            achados = _posvenda_buscar(seller_id, {"status": "opened"}, stop_event)
            ultima_dt = _posvenda_dt(ultima)
            if ultima_dt is None:
                desde = agora - timedelta(days=POSVENDA_HISTORICO_DIAS)
                faixa = f"date_created:after:{_posvenda_iso_ml(desde)}"
            else:
                # um dia de folga: relógio do ML e reclamação que mudou no meio da rodada anterior
                desde = ultima_dt - timedelta(days=1)
                faixa = f"last_updated:after:{_posvenda_iso_ml(desde)}"
            # V19.92: o ML recusa o range sozinho (HTTP 400 atLeastOneFilterProvided, visto em produção 27/10 —
            # a tabela nunca tinha sido preenchida): uma busca por situação.
            for situacao in ("opened", "closed"):
                achados += _posvenda_buscar(seller_id, {"status": situacao, "range": faixa}, stop_event)
        except Exception as exc:
            msg = str(exc)[:500]
            ml_log_event_se_mudou("posvenda", "/post-purchase/v1/claims/search", seller_id, ML_CLIENT_ID, "ERRO", msg)
            resultado = {"ok": False, "erro": msg, "sem_permissao": ("HTTP 403" in msg or "HTTP 401" in msg), "em": now_iso()}
            _posvenda_estado_conta(conta, "reclamacoes", resultado)
            return resultado
        vistos: set[str] = set()
        novas = 0
        for c in achados:
            base = _posvenda_base_da_busca(c)
            if not base["claim_id"] or base["claim_id"] in vistos:
                continue
            vistos.add(base["claim_id"])
            if _posvenda_gravar_base(base):
                novas += 1
        # aberta que não veio na busca de abertas (fechou e a busca por data ainda não pegou)
        # ou aberta sem leitura há mais de 1 h: detalha de novo (o prazo muda).
        # mesmo formato do now_iso() (fuso local), senão a comparação de texto erra
        limite = (datetime.now(timezone.utc) - timedelta(seconds=POSVENDA_REVISITAR_ABERTA)).astimezone().isoformat(timespec="milliseconds")
        with DB_LOCK:
            DB.execute("UPDATE ml_reclamacao_v1888 SET precisa_detalhe=1 WHERE status='opened' AND detalhado_em < ? "
                       "AND conta=?", (limite, conta))
            DB.commit()
            # V20.01: só as da conta da volta — o detalhe é lido com o token dela.
            fila = [str(r["claim_id"]) for r in DB.execute(
                "SELECT claim_id FROM ml_reclamacao_v1888 WHERE precisa_detalhe=1 AND conta=? "
                "ORDER BY CASE WHEN status='opened' THEN 0 ELSE 1 END, aberta_em DESC LIMIT ?",
                (conta, POSVENDA_DETALHES_POR_RODADA)).fetchall()]
        detalhadas = falhas = 0
        for cid in fila:
            if stop_event is not None and stop_event.is_set():
                break
            r = _posvenda_detalhar(cid)
            detalhadas += 1
            falhas += 0 if r.get("ok") else 1
            if pausa > 0:
                if stop_event is not None:
                    if stop_event.wait(pausa):
                        break
                else:
                    time.sleep(pausa)
        resultado = {"ok": True, "encontradas": len(vistos), "novas_ou_alteradas": novas,
                     "detalhadas": detalhadas, "com_erro": falhas, "em": now_iso()}
        ml_log_event_se_mudou("posvenda", "/post-purchase/v1/claims/search", seller_id, ML_CLIENT_ID, "OK", "")
        _posvenda_estado_conta(conta, "reclamacoes", resultado)
        return resultado
    finally:
        _POSVENDA_ESTADO.update(rodando=False, fim=now_iso())
        trava.release()


def posvenda_reputacao_rodada(dia: str | None = None) -> dict[str, Any]:
    """Retrato do termômetro do vendedor (/users/{id}), um por dia (o último do dia vale)."""
    linha = ml_integration_row()
    if not linha or not str(linha["access_token"] or "").strip():
        return {"ok": True, "pulado": "Mercado Livre não conectado"}
    seller_id = str(linha["seller_id"] or "")
    u = ml_api_get(f"/users/{quote(seller_id)}")
    rep = (u.get("seller_reputation") if isinstance(u, dict) else None) or {}
    met = rep.get("metrics") if isinstance(rep.get("metrics"), dict) else {}

    def m(chave: str, campo: str) -> Any:
        bloco = met.get(chave) if isinstance(met.get(chave), dict) else {}
        return bloco.get(campo)

    vendas = m("sales", "completed")
    dia = dia or datetime.now(BR_TZ).date().isoformat()
    with DB_LOCK:
        # V20.01: uma linha por conta e dia (a ml_reputacao_dia_v1888 era só da principal).
        DB.execute(
            "INSERT OR REPLACE INTO ml_reputacao_conta_v2001(conta,dia,nivel,mercado_lider,vendas_periodo,periodo,reclamacoes_taxa,"
            "reclamacoes_qtd,atrasos_taxa,atrasos_qtd,cancelamentos_taxa,cancelamentos_qtd,atualizado_em) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",
            (ml_casa_atual(), dia, str(rep.get("level_id") or ""), str(rep.get("power_seller_status") or ""),
             int(vendas) if isinstance(vendas, (int, float)) else None, str(m("sales", "period") or ""),
             _posvenda_float(m("claims", "rate")), m("claims", "value"),
             _posvenda_float(m("delayed_handling_time", "rate")), m("delayed_handling_time", "value"),
             _posvenda_float(m("cancellations", "rate")), m("cancellations", "value"), now_iso()))
        DB.commit()
    _POSVENDA_ESTADO["reputacao_em"] = time.time()
    return {"ok": True, "nivel": str(rep.get("level_id") or "")}


def _posvenda_gravar_pergunta(q: dict[str, Any], respondida_por: str = "") -> bool:
    """Grava a pergunta (conta = casa atual, só ao criar). Devolve True quando é nova."""
    ans = q.get("answer") if isinstance(q.get("answer"), dict) else {}
    de = q.get("from") if isinstance(q.get("from"), dict) else {}
    status = str(q.get("status") or "")
    with DB_LOCK:
        atual = DB.execute("SELECT status, respondida_em, respondida_por FROM ml_pergunta_v1888 WHERE pergunta_id=?",
                           (str(q.get("id") or ""),)).fetchone()
        nova = atual is None
        # V20.01: respondida por aqui não volta a "sem resposta" porque a busca do ML, atrasada, ainda a trouxe —
        # mas só nos primeiros minutos (revisão 29/10): depois disso o "sem resposta" do ML vale (resposta apagada
        # pela moderação do ML), e a pergunta volta para a fila em vez de sumir para sempre.
        if atual is not None and status == "UNANSWERED" and str(atual["status"]) == "ANSWERED":
            quando = _posvenda_dt(atual["respondida_em"])
            recente = quando is not None and (datetime.now(timezone.utc) - quando) < timedelta(minutes=POSVENDA_PROTEGE_RESPOSTA_MIN)
            if recente and str(atual["respondida_por"] or ""):
                status = "ANSWERED"
            else:
                DB.execute("UPDATE ml_pergunta_v1888 SET resposta='', respondida_em='', respondida_por='' WHERE pergunta_id=?",
                           (str(q.get("id") or ""),))
        DB.execute(
            "INSERT INTO ml_pergunta_v1888(pergunta_id,item_id,texto,status,criada_em,comprador_id,resposta,respondida_em,"
            "respondida_por,updated_at,conta) VALUES(?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(pergunta_id) DO UPDATE SET "
            "item_id=excluded.item_id,texto=excluded.texto,status=excluded.status,criada_em=excluded.criada_em,"
            "comprador_id=excluded.comprador_id,"
            "resposta=CASE WHEN excluded.resposta<>'' THEN excluded.resposta ELSE ml_pergunta_v1888.resposta END,"
            "respondida_em=CASE WHEN excluded.respondida_em<>'' THEN excluded.respondida_em ELSE ml_pergunta_v1888.respondida_em END,"
            "respondida_por=CASE WHEN ml_pergunta_v1888.respondida_por<>'' THEN ml_pergunta_v1888.respondida_por "
            "ELSE excluded.respondida_por END,updated_at=excluded.updated_at",
            (str(q.get("id") or ""), str(q.get("item_id") or ""), str(q.get("text") or ""), status,
             str(q.get("date_created") or ""), str(de.get("id") or ""), str(ans.get("text") or ""),
             str(ans.get("date_created") or ""), respondida_por, now_iso(), ml_casa_atual()))
        DB.commit()
    return nova


def _posvenda_avisar_perguntas(conta: str, novas: list[dict[str, Any]]) -> int:
    """V20.01: pergunta nova vira aviso (popup/push dos Avisos de venda). A 1ª leitura de cada
    conta só marca o que existe; pergunta com mais de 48 h entra calada. Uma vez por pergunta."""
    chave_base = f"base_pergunta@{conta}"
    limite = datetime.now(timezone.utc) - timedelta(hours=AVISOS_VENDA_RECENTE_HORAS)
    agora = now_iso()
    avisadas = 0
    with DB_LOCK:
        primeira = DB.execute("SELECT 1 FROM aviso_config_v1893 WHERE chave=?", (chave_base,)).fetchone() is None
        for q in novas:
            quando = _posvenda_dt(q.get("date_created"))
            silencioso = 1 if (primeira or quando is None or quando < limite) else 0
            cur = DB.execute(
                "INSERT OR IGNORE INTO aviso_venda_v1893(marketplace,venda_id,venda_em,valor,titulo,qtd,itens,silencioso,"
                "criado_em,casa) VALUES('pergunta',?,?,NULL,?,0,0,?,?,?)",
                (f"pergunta:{q.get('id')}", str(q.get("date_created") or ""), str(q.get("text") or "")[:200],
                 silencioso, agora, conta))
            avisadas += 1 if (cur.rowcount and not silencioso) else 0
        if primeira:
            DB.execute("INSERT OR IGNORE INTO aviso_config_v1893(chave,valor) VALUES(?,?)", (chave_base, agora))
        DB.commit()
    if avisadas:
        AVISOS_VENDA_EVENT.set()
    return avisadas


def posvenda_perguntas_rodada(stop_event: threading.Event | None = None) -> dict[str, Any]:
    """Perguntas sem resposta. As que saíram da lista (respondidas no ML, apagadas) são relidas.
    V20.01: da conta da casa atual (ml_na_casa)."""
    conta = ml_casa_atual()
    linha = ml_integration_row()
    if not linha or not str(linha["access_token"] or "").strip():
        resultado = {"ok": True, "pulado": "Mercado Livre não conectado"}
        _posvenda_estado_conta(conta, "perguntas", resultado)
        return resultado
    seller_id = str(linha["seller_id"] or "")
    abertas: dict[str, dict[str, Any]] = {}
    try:
        offset = 0
        while offset < 1000:
            r = ml_api_get("/questions/search?" + urlencode({"seller_id": seller_id, "status": "UNANSWERED",
                                                             "api_version": "4", "limit": "50", "offset": str(offset)}))
            lista = (r.get("questions") if isinstance(r, dict) else None) or []
            for q in lista:
                if isinstance(q, dict) and q.get("id"):
                    abertas[str(q["id"])] = q
            offset += 50
            if not lista or offset >= int((r.get("total") if isinstance(r, dict) else 0) or 0):
                break
    except Exception as exc:
        msg = str(exc)[:500]
        ml_log_event_se_mudou("posvenda", "/questions/search", seller_id, ML_CLIENT_ID, "ERRO", msg)
        resultado = {"ok": False, "erro": msg, "sem_permissao": ("HTTP 403" in msg or "HTTP 401" in msg), "em": now_iso()}
        _posvenda_estado_conta(conta, "perguntas", resultado)
        return resultado
    novas = [q for q in abertas.values() if _posvenda_gravar_pergunta(q)]
    _posvenda_avisar_perguntas(conta, novas)
    with DB_LOCK:
        sumiram = [str(r["pergunta_id"]) for r in DB.execute(
            "SELECT pergunta_id FROM ml_pergunta_v1888 WHERE status='UNANSWERED' AND conta=?", (conta,)).fetchall()
            if str(r["pergunta_id"]) not in abertas]
    relidas = 0
    for qid in sumiram[:30]:
        if stop_event is not None and stop_event.is_set():
            break
        try:
            q = ml_api_get(f"/questions/{quote(qid)}?api_version=4")
            if isinstance(q, dict) and q.get("id"):
                _posvenda_gravar_pergunta(q, respondida_por="Mercado Livre" if q.get("status") == "ANSWERED" else "")
                relidas += 1
        except Exception as exc:
            if "HTTP 404" in str(exc):   # apagada pelo comprador/ML
                with DB_LOCK:
                    DB.execute("UPDATE ml_pergunta_v1888 SET status='DELETED', updated_at=? WHERE pergunta_id=?",
                               (now_iso(), qid))
                    DB.commit()
    corte = (datetime.now(timezone.utc) - timedelta(days=POSVENDA_PERGUNTAS_GUARDAR_DIAS)).astimezone().isoformat(timespec="milliseconds")
    with DB_LOCK:
        DB.execute("DELETE FROM ml_pergunta_v1888 WHERE status<>'UNANSWERED' AND updated_at < ?", (corte,))
        DB.commit()
    ml_log_event_se_mudou("posvenda", "/questions/search", seller_id, ML_CLIENT_ID, "OK", "")
    resultado = {"ok": True, "sem_resposta": len(abertas), "relidas": relidas, "em": now_iso()}
    _posvenda_estado_conta(conta, "perguntas", resultado)
    return resultado


def posvenda_config() -> dict[str, str]:
    """V20.01: saudação e assinatura de cada conta (vazio = nada)."""
    with DB_LOCK:
        gravado = {str(r["chave"]): str(r["valor"]) for r in DB.execute("SELECT chave, valor FROM posvenda_config_v2001")}
    return {f"{parte}@{conta}": gravado.get(f"{parte}@{conta}", "") for conta in CASAS for parte in ("saudacao", "assinatura")}


def posvenda_config_salvar(dados: dict[str, Any], ator: str) -> dict[str, Any]:
    validas = set(posvenda_config())
    mudou = {}
    for chave, valor in (dados or {}).items():
        if chave not in validas:
            raise ValueError(f"Opção desconhecida: {chave}")
        texto = " ".join(str(valor or "").split())
        if len(texto) > POSVENDA_TEXTO_CONFIG_MAX:
            raise ValueError(f"Saudação/assinatura passa de {POSVENDA_TEXTO_CONFIG_MAX} caracteres.")
        mudou[chave] = texto
    agora = now_iso()
    with DB_LOCK:
        for chave, texto in mudou.items():
            DB.execute("INSERT OR REPLACE INTO posvenda_config_v2001(chave,valor,atualizado_por,atualizado_em) VALUES(?,?,?,?)",
                       (chave, texto, ator, agora))
        DB.commit()
    audit(ator, "posvenda_config", json_dumps(mudou)[:500])
    return {"ok": True, "config": posvenda_config()}


def posvenda_respostas_prontas() -> list[dict[str, Any]]:
    with DB_LOCK:
        return [dict(r) for r in DB.execute(
            "SELECT id, titulo, texto, atualizado_por, atualizado_em FROM posvenda_resposta_pronta_v2001 "
            "ORDER BY titulo COLLATE NOCASE, id")]


def posvenda_resposta_salvar(dados: dict[str, Any], ator: str) -> dict[str, Any]:
    """Cria, edita (com id) ou apaga (id + excluir) uma resposta pronta."""
    rid = dados.get("id")
    if rid not in (None, ""):
        try:
            rid = int(rid)
        except (TypeError, ValueError):
            raise ValueError("Resposta pronta inválida.")
    else:
        rid = None
    agora = now_iso()
    if dados.get("excluir"):
        if rid is None:
            raise ValueError("Resposta pronta inválida.")
        with DB_LOCK:
            DB.execute("DELETE FROM posvenda_resposta_pronta_v2001 WHERE id=?", (rid,))
            DB.commit()
        audit(ator, "posvenda_resposta_pronta", f"apagou {rid}")
        return {"ok": True, "apagada": rid}
    titulo = " ".join(str(dados.get("titulo") or "").split())[:60]
    texto = str(dados.get("texto") or "").strip()
    if not texto:
        raise ValueError("Escreva o texto da resposta pronta.")
    if len(texto) > POSVENDA_RESPOSTA_MAX:
        raise ValueError(f"A resposta pronta passa de {POSVENDA_RESPOSTA_MAX} caracteres.")
    titulo = titulo or texto[:40]
    with DB_LOCK:
        if rid is None:
            if DB.execute("SELECT COUNT(*) FROM posvenda_resposta_pronta_v2001").fetchone()[0] >= POSVENDA_PRONTA_MAX:
                raise ValueError(f"Limite de {POSVENDA_PRONTA_MAX} respostas prontas. Apague alguma antes.")
            rid = DB.execute("INSERT INTO posvenda_resposta_pronta_v2001(titulo,texto,atualizado_por,atualizado_em) "
                             "VALUES(?,?,?,?)", (titulo, texto, ator, agora)).lastrowid
        elif not DB.execute("UPDATE posvenda_resposta_pronta_v2001 SET titulo=?,texto=?,atualizado_por=?,atualizado_em=? "
                            "WHERE id=?", (titulo, texto, ator, agora, rid)).rowcount:
            raise ValueError("Resposta pronta não encontrada. Atualize a tela.")
        DB.commit()
    audit(ator, "posvenda_resposta_pronta", f"{rid}: {titulo}")
    return {"ok": True, "resposta": {"id": rid, "titulo": titulo, "texto": texto}}


def posvenda_texto_final(texto: str, conta: str) -> str:
    """Saudação + texto + assinatura da conta, sem repetir o que a pessoa já escreveu."""
    cfg = posvenda_config()
    saud, assin = cfg.get(f"saudacao@{conta}", ""), cfg.get(f"assinatura@{conta}", "")
    partes = [texto]
    if saud and not texto.lower().startswith(saud.lower()):
        partes.insert(0, saud)
    if assin and not texto.lower().endswith(assin.lower()):
        partes.append(assin)
    return " ".join(partes)


def posvenda_responder(pergunta_id: str, texto: str, ator: str) -> dict[str, Any]:
    """Responde a pergunta no ML (POST /answers). Só pergunta conhecida e ainda sem resposta.
    V20.01: pela conta dona da pergunta, com a saudação/assinatura dela; uma pessoa por vez."""
    pergunta_id = str(pergunta_id or "").strip()
    texto = str(texto or "").strip()
    if not pergunta_id.isdigit():
        raise ValueError("Pergunta inválida.")
    if not texto:
        raise ValueError("Escreva a resposta.")
    with DB_LOCK:
        r = DB.execute("SELECT status, conta FROM ml_pergunta_v1888 WHERE pergunta_id=?", (pergunta_id,)).fetchone()
    if r is None:
        raise ValueError("Pergunta não encontrada. Atualize a tela.")
    conta = str(r["conta"] or CASA_PRINCIPAL)
    final = posvenda_texto_final(texto, conta)
    if len(final) > POSVENDA_RESPOSTA_MAX:
        raise ValueError(f"A resposta passa de {POSVENDA_RESPOSTA_MAX} caracteres (limite do Mercado Livre), "
                         "contando a saudação e a assinatura.")
    with POSVENDA_RESPONDENDO_LOCK:
        if pergunta_id in _POSVENDA_RESPONDENDO:
            raise ValueError("Outra pessoa está respondendo esta pergunta agora. Atualize a tela em instantes.")
        _POSVENDA_RESPONDENDO.add(pergunta_id)
    try:
        # relida já com a vez: quem respondeu um instante antes já gravou ANSWERED
        with DB_LOCK:
            r = DB.execute("SELECT status FROM ml_pergunta_v1888 WHERE pergunta_id=?", (pergunta_id,)).fetchone()
        if r is None or str(r["status"]) != "UNANSWERED":
            raise ValueError("Esta pergunta já foi respondida ou não está mais disponível.")
        with ml_na_casa(conta):
            resposta = _ml_promo_http("POST", "/answers", {"question_id": int(pergunta_id), "text": final})
        agora = now_iso()
        resp = resposta.get("answer") if isinstance(resposta, dict) and isinstance(resposta.get("answer"), dict) else {}
        with DB_LOCK:
            DB.execute("UPDATE ml_pergunta_v1888 SET status='ANSWERED', resposta=?, respondida_em=?, respondida_por=?, "
                       "updated_at=? WHERE pergunta_id=?",
                       (str(resp.get("text") or final), str(resp.get("date_created") or agora), ator, agora, pergunta_id))
            DB.commit()
    finally:
        with POSVENDA_RESPONDENDO_LOCK:
            _POSVENDA_RESPONDENDO.discard(pergunta_id)
    audit(ator, "ml_pergunta_responder", f"{pergunta_id} [{conta}]: {final[:500]}")
    return {"ok": True, "pergunta_id": pergunta_id, "texto": final}


# ---------------------------------------------------------------------------
# V19.74: Monitor de catálogo do ML (decisões do dono, 22/10). SÓ LÊ o ML.
# Para cada anúncio de catálogo (Araçatuba e Bauru, de hora em hora): situação na vitrine
# (/items/{MLB}/price_to_win), concorrentes do produto (/products/{id}/items) e se o preço
# para ganhar ainda dá a margem mínima da promoção (mesma conta das Promoções automáticas:
# custo de _promo_produto, comissão/frete do anúncio, imposto). Sem custo = nulo, nunca zero.
# Aviso (popup/push, canal dos avisos de venda) só na VIRADA de ganhando/compartilhando para
# perdendo e só quando o preço para ganhar dá margem; a 1ª leitura de um anúncio só marca.
# A resposta real foi construída pela documentação: a 1ª de cada tipo fica em
# catalogo_ml_amostra_v1974 (GET /api/catalogo-ml/amostra) para conferir.
# ---------------------------------------------------------------------------
CATALOGO_ML_INTERVALO = 3600
CATALOGO_ML_PAUSA = 0.3
# Revisão de 22/10: o frete do anúncio (shipping_options/free) é o do preço ATUAL. Quando o preço
# para ganhar cruza a faixa do frete grátis, a margem nele é só aproximada: não afirma "dá margem"
# no aviso e a tela diz por quê.
CATALOGO_ML_FAIXA_FRETE = 79.0
CATALOGO_ML_FRETE_INCERTO = ("Frete calculado no preço atual: o preço para ganhar cruza a faixa de R$ 79 "
                             "do frete grátis, confira a margem antes de baixar")
CATALOGO_ML_LOCK = threading.Lock()
CATALOGO_ML_SITUACAO = {"winning": "ganhando", "sharing_first_place": "compartilhando",
                        "competing": "perdendo", "listed": "nao_elegivel"}
_CATALOGO_ML_ESTADO: dict[str, Any] = {"rodando": False, "inicio": "", "fim": "", "erro": ""}


def ensure_catalogo_ml_schema() -> None:
    with DB_LOCK:
        DB.executescript(
            """
            CREATE TABLE IF NOT EXISTS catalogo_ml_v1974 (
                conta TEXT NOT NULL, item_id TEXT NOT NULL, produto_id TEXT NOT NULL DEFAULT '',
                titulo TEXT NOT NULL DEFAULT '', sku TEXT NOT NULL DEFAULT '', status_anuncio TEXT NOT NULL DEFAULT '',
                situacao TEXT NOT NULL DEFAULT '', preco REAL, preco_ganhar REAL,
                ganhador_item TEXT NOT NULL DEFAULT '', ganhador_preco REAL, concorrentes INTEGER,
                motivos TEXT NOT NULL DEFAULT '[]', margem_atual REAL, margem_ganhar REAL, lucro_ganhar REAL,
                da_margem INTEGER, taxas_origem TEXT NOT NULL DEFAULT '', frete_incerto INTEGER NOT NULL DEFAULT 0,
                lido_em TEXT NOT NULL DEFAULT '', mudou_em TEXT NOT NULL DEFAULT '', avisado_em TEXT NOT NULL DEFAULT '',
                erro TEXT NOT NULL DEFAULT '',
                PRIMARY KEY (conta, item_id)
            );
            CREATE TABLE IF NOT EXISTS catalogo_ml_concorrente_v1974 (
                conta TEXT NOT NULL, produto_id TEXT NOT NULL, item_id TEXT NOT NULL,
                vendedor TEXT NOT NULL DEFAULT '', preco REAL, frete_gratis INTEGER, logistica TEXT NOT NULL DEFAULT '',
                tipo TEXT NOT NULL DEFAULT '', loja_oficial INTEGER NOT NULL DEFAULT 0, lido_em TEXT NOT NULL DEFAULT '',
                PRIMARY KEY (conta, produto_id, item_id)
            );
            CREATE TABLE IF NOT EXISTS catalogo_ml_hist_v1974 (
                id INTEGER PRIMARY KEY AUTOINCREMENT, conta TEXT NOT NULL, item_id TEXT NOT NULL, em TEXT NOT NULL,
                situacao TEXT NOT NULL, preco REAL, preco_ganhar REAL, ganhador_preco REAL
            );
            CREATE INDEX IF NOT EXISTS idx_catalogo_ml_hist ON catalogo_ml_hist_v1974(conta, item_id, id);
            CREATE TABLE IF NOT EXISTS catalogo_ml_amostra_v1974 (
                tipo TEXT PRIMARY KEY, em TEXT NOT NULL, json TEXT NOT NULL
            );
            """
        )
        if "frete_incerto" not in {r[1] for r in DB.execute("PRAGMA table_info(catalogo_ml_v1974)")}:
            DB.execute("ALTER TABLE catalogo_ml_v1974 ADD COLUMN frete_incerto INTEGER NOT NULL DEFAULT 0")
        DB.commit()


def _catalogo_ml_amostra(tipo: str, dados: Any) -> None:
    try:
        with DB_LOCK:
            DB.execute("INSERT OR IGNORE INTO catalogo_ml_amostra_v1974(tipo,em,json) VALUES(?,?,?)",
                       (tipo, now_iso(), json.dumps(dados, ensure_ascii=False)[:200000]))
            DB.commit()
    except Exception:
        pass


def catalogo_ml_anuncios() -> list[str]:
    """Anúncios ativos de catálogo da conta da casa atual (filtro catalog_listing do /items/search).

    Revisão de 22/10: a rodada APAGA do monitor o que não está nesta lista, então ela só vale
    COMPLETA. Paginação por scroll_id (offset estoura em 1000, V18.28); resposta estranha ou
    menos anúncios que o paging.total = RuntimeError, e a rodada da conta não apaga nada."""
    linha = ml_integration_row()
    seller = str((linha["seller_id"] if linha else "") or "").strip()
    if not seller:
        raise RuntimeError("Mercado Livre não está conectado.")
    base = f"/users/{seller}/items/search?catalog_listing=true&status=active&search_type=scan&limit=100"
    ids: list[str] = []
    total: int | None = None
    scroll = ""
    for _ in range(60):   # teto de segurança: 6.000 anúncios
        dados = ml_api_get(base + ("&scroll_id=" + quote(scroll) if scroll else ""))
        if not isinstance(dados, dict) or not isinstance(dados.get("results"), list):
            raise RuntimeError("Lista de anúncios de catálogo veio em formato inesperado do Mercado Livre.")
        try:
            total = int((dados.get("paging") or {}).get("total"))
        except (TypeError, ValueError):
            pass
        resultados = [str(x) for x in dados["results"] if x]
        if not resultados:
            break
        ids.extend(resultados)
        scroll = str(dados.get("scroll_id") or "")
        if not scroll or (total is not None and len(ids) >= total):
            break
    vistos: set[str] = set()
    unicos = [x for x in ids if not (x in vistos or vistos.add(x))]
    if total is None or len(unicos) < total:
        raise RuntimeError(f"Lista de catálogo incompleta ({len(unicos)} de {total if total is not None else '?'}): "
                           "nada foi apagado do monitor.")
    return unicos


def catalogo_ml_avaliar(ptw: dict[str, Any], prod_atual: dict[str, Any] | None,
                        prod_ganhar: dict[str, Any] | None, cfg: dict[str, Any]) -> dict[str, Any]:
    """Pura: situação + margem no preço atual e no preço para ganhar. Não chama o ML."""
    ptw = ptw if isinstance(ptw, dict) else {}
    winner = ptw.get("winner") if isinstance(ptw.get("winner"), dict) else {}
    preco = _money_number(ptw.get("current_price"))
    ganhar = _money_number(ptw.get("price_to_win"))
    out: dict[str, Any] = {
        "situacao": CATALOGO_ML_SITUACAO.get(str(ptw.get("status") or "").lower(), str(ptw.get("status") or "")),
        "preco": preco, "preco_ganhar": ganhar,
        "ganhador_item": str(winner.get("item_id") or ""), "ganhador_preco": _money_number(winner.get("price")),
        "produto_id": str(ptw.get("catalog_product_id") or ""),
        "motivos": [str(x) for x in (ptw.get("reason") or []) if x] if isinstance(ptw.get("reason"), list) else [],
        "margem_atual": None, "margem_ganhar": None, "lucro_ganhar": None, "da_margem": None,
    }
    if prod_atual and float(prod_atual.get("custo") or 0) > 0 and preco:
        out["margem_atual"] = promo_conta(prod_atual, preco)["margem"]
    if prod_ganhar and float(prod_ganhar.get("custo") or 0) > 0 and ganhar:
        c = promo_conta(prod_ganhar, ganhar)
        out["margem_ganhar"], out["lucro_ganhar"] = c["margem"], c["lucro"]
        out["da_margem"] = c["margem"] >= _promo_margem_minima(cfg)
    return out


def _catalogo_ml_gravar(conta: str, item_id: str, det: dict[str, Any], sku: str, a: dict[str, Any],
                        taxas_origem: str) -> bool:
    """Grava a leitura. Devolve True quando gerou aviso (virada para perdendo com margem)."""
    agora = now_iso()
    with DB_LOCK:
        ant = DB.execute("SELECT situacao FROM catalogo_ml_v1974 WHERE conta=? AND item_id=?", (conta, item_id)).fetchone()
        anterior = ant["situacao"] if ant else ""
        mudou = anterior != a["situacao"]
        avisar = (ant is not None and anterior in ("ganhando", "compartilhando")
                  and a["situacao"] == "perdendo" and a["da_margem"] is True and not a.get("frete_incerto"))
        DB.execute(
            """INSERT INTO catalogo_ml_v1974(conta,item_id,produto_id,titulo,sku,status_anuncio,situacao,preco,preco_ganhar,
                   ganhador_item,ganhador_preco,motivos,margem_atual,margem_ganhar,lucro_ganhar,da_margem,taxas_origem,
                   lido_em,mudou_em,erro,frete_incerto)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'',?)
               ON CONFLICT(conta,item_id) DO UPDATE SET produto_id=excluded.produto_id, titulo=excluded.titulo,
                   sku=excluded.sku, status_anuncio=excluded.status_anuncio, situacao=excluded.situacao,
                   preco=excluded.preco, preco_ganhar=excluded.preco_ganhar, ganhador_item=excluded.ganhador_item,
                   ganhador_preco=excluded.ganhador_preco, motivos=excluded.motivos, margem_atual=excluded.margem_atual,
                   margem_ganhar=excluded.margem_ganhar, lucro_ganhar=excluded.lucro_ganhar, da_margem=excluded.da_margem,
                   taxas_origem=excluded.taxas_origem, lido_em=excluded.lido_em, frete_incerto=excluded.frete_incerto,
                   mudou_em=CASE WHEN catalogo_ml_v1974.situacao<>excluded.situacao THEN excluded.lido_em
                                 ELSE catalogo_ml_v1974.mudou_em END, erro=''""",
            (conta, item_id, a["produto_id"] or str(det.get("produto_catalogo") or ""), str(det.get("titulo") or ""),
             sku, str(det.get("status") or ""), a["situacao"], a["preco"] if a["preco"] is not None else _money_number(det.get("preco")),
             a["preco_ganhar"], a["ganhador_item"], a["ganhador_preco"], json.dumps(a["motivos"], ensure_ascii=False),
             a["margem_atual"], a["margem_ganhar"], a["lucro_ganhar"],
             None if a["da_margem"] is None else int(bool(a["da_margem"])), taxas_origem, agora, agora,
             int(bool(a.get("frete_incerto")))),
        )
        if mudou or ant is None:
            DB.execute("INSERT INTO catalogo_ml_hist_v1974(conta,item_id,em,situacao,preco,preco_ganhar,ganhador_preco) "
                       "VALUES(?,?,?,?,?,?,?)", (conta, item_id, agora, a["situacao"], a["preco"], a["preco_ganhar"],
                                                  a["ganhador_preco"]))
        if avisar:
            titulo = (f"{item_id} perdeu a vitrine: ganha com {_brl_srv(a['preco_ganhar'])} "
                      f"(margem {_pct_br(a['margem_ganhar'])}) · {str(det.get('titulo') or '')[:80]}")
            DB.execute("INSERT OR IGNORE INTO aviso_venda_v1893(marketplace,venda_id,venda_em,valor,titulo,qtd,itens,"
                       "silencioso,criado_em,casa) VALUES('catalogo',?,?,NULL,?,0,0,0,?,?)",
                       (f"catalogo:{conta}:{item_id}:{agora}", agora, titulo, agora, conta))
            DB.execute("UPDATE catalogo_ml_v1974 SET avisado_em=? WHERE conta=? AND item_id=?", (agora, conta, item_id))
        DB.commit()
    if avisar:
        AVISOS_VENDA_EVENT.set()
    return avisar


def _catalogo_ml_concorrentes(conta: str, produto_id: str) -> int | None:
    dados = ml_api_get(f"/products/{quote(produto_id)}/items")
    _catalogo_ml_amostra("produto_itens", dados)
    # Revisão de 22/10: sem "results" (ou vazio: o próprio anúncio sempre está no produto) é resposta
    # que não dá para usar. Mantém a leitura anterior, nunca vira "0 concorrentes".
    brutos = dados.get("results") if isinstance(dados, dict) else None
    linhas = [r for r in brutos if isinstance(r, dict)] if isinstance(brutos, list) else []
    if not linhas:
        raise RuntimeError("Concorrentes do catálogo vieram em formato inesperado do Mercado Livre.")
    agora = now_iso()
    with DB_LOCK:
        DB.execute("DELETE FROM catalogo_ml_concorrente_v1974 WHERE conta=? AND produto_id=?", (conta, produto_id))
        for r in linhas:
            envio = r.get("shipping") if isinstance(r.get("shipping"), dict) else {}
            DB.execute(
                "INSERT OR REPLACE INTO catalogo_ml_concorrente_v1974(conta,produto_id,item_id,vendedor,preco,frete_gratis,"
                "logistica,tipo,loja_oficial,lido_em) VALUES(?,?,?,?,?,?,?,?,?,?)",
                (conta, produto_id, str(r.get("item_id") or ""), str(r.get("seller_id") or ""), _money_number(r.get("price")),
                 None if envio.get("free_shipping") is None else int(bool(envio.get("free_shipping"))),
                 str(envio.get("logistic_type") or ""), str(r.get("listing_type_id") or ""),
                 int(bool(r.get("official_store_id"))), agora))
        DB.commit()
    return len(linhas)


def _catalogo_ml_rodada_conta(conta: str, stop_event: threading.Event | None, pausa: float) -> dict[str, Any]:
    ids = catalogo_ml_anuncios()
    det_todos = ml_itens_detalhe(ids) if ids else {}
    produtos = _promo_produtos()
    vinculos = _ml_vinculos_mlb_sku()
    cfg = promo_auto_config()
    avisos = lidos = erros = 0
    concorrentes: dict[str, int | None] = {}
    for mlb in ids:
        if stop_event is not None and stop_event.is_set():
            break
        det = det_todos.get(mlb) or {}
        try:
            ptw = ml_api_get(f"/items/{mlb}/price_to_win?siteId=MLB&version=v2")
            _catalogo_ml_amostra("price_to_win", ptw)
            sku = _promo_resolver_sku(mlb, det.get("sku_ml"), produtos, vinculos)
            prod = _promo_produto(produtos, sku) if sku else None
            preco = _money_number((ptw or {}).get("current_price")) or _money_number(det.get("preco"))
            ganhar = _money_number((ptw or {}).get("price_to_win"))
            prod_a, origem = _promo_prod_com_ml(prod, mlb, preco, det) if prod and preco else (prod, "")
            prod_g = _promo_prod_com_ml(prod, mlb, ganhar, det)[0] if prod and ganhar else prod
            a = catalogo_ml_avaliar(ptw, prod_a, prod_g, cfg)
            if preco and ganhar and (preco >= CATALOGO_ML_FAIXA_FRETE) != (ganhar >= CATALOGO_ML_FAIXA_FRETE):
                a["frete_incerto"] = True
                origem = "; ".join(x for x in (origem, CATALOGO_ML_FRETE_INCERTO) if x)
            pid = a["produto_id"] or str(det.get("produto_catalogo") or "")
            if pid and pid not in concorrentes:
                try:
                    concorrentes[pid] = _catalogo_ml_concorrentes(conta, pid)
                except Exception:
                    concorrentes[pid] = None   # mantém o número e a lista da leitura anterior
            avisos += int(_catalogo_ml_gravar(conta, mlb, det, sku, a, origem))
            if concorrentes.get(pid) is not None:
                with DB_LOCK:
                    DB.execute("UPDATE catalogo_ml_v1974 SET concorrentes=? WHERE conta=? AND item_id=?",
                               (concorrentes[pid], conta, mlb))
                    DB.commit()
            lidos += 1
        except Exception as exc:
            erros += 1
            with DB_LOCK:
                # erro não apaga a leitura anterior: só registra
                DB.execute("INSERT INTO catalogo_ml_v1974(conta,item_id,titulo,erro) VALUES(?,?,?,?) "
                           "ON CONFLICT(conta,item_id) DO UPDATE SET erro=excluded.erro",
                           (conta, mlb, str(det.get("titulo") or ""), str(exc)[:300]))
                DB.commit()
        if pausa:
            time.sleep(pausa)
    # anúncio que saiu do catálogo sai da lista (a lista veio inteira, sem erro)
    with DB_LOCK:
        if ids:
            marcas = ",".join("?" * len(ids))
            DB.execute(f"DELETE FROM catalogo_ml_v1974 WHERE conta=? AND item_id NOT IN ({marcas})", (conta, *ids))
        else:
            DB.execute("DELETE FROM catalogo_ml_v1974 WHERE conta=?", (conta,))
        DB.commit()
    return {"conta": conta, "anuncios": len(ids), "lidos": lidos, "erros": erros, "avisos": avisos}


def catalogo_ml_rodada(stop_event: threading.Event | None = None, *, pausa: float | None = None) -> dict[str, Any]:
    if not CATALOGO_ML_LOCK.acquire(blocking=False):
        return {"ok": True, "pulado": "já está rodando"}
    pausa = CATALOGO_ML_PAUSA if pausa is None else pausa
    _CATALOGO_ML_ESTADO.update(rodando=True, inicio=now_iso(), erro="")
    contas: list[dict[str, Any]] = []
    try:
        for casa in ml_casas_conectadas():
            try:
                with ml_na_casa(casa):
                    contas.append(_catalogo_ml_rodada_conta(casa, stop_event, pausa))
            except Exception as exc:
                contas.append({"conta": casa, "erro": str(exc)[:300]})
                _CATALOGO_ML_ESTADO["erro"] = f"{CASAS.get(casa, casa)}: {exc}"[:300]
    finally:
        _CATALOGO_ML_ESTADO.update(rodando=False, fim=now_iso())
        CATALOGO_ML_LOCK.release()
    return {"ok": True, "contas": contas}


def catalogo_ml_loop(stop_event: threading.Event) -> None:
    """V19.74: lê o catálogo das contas conectadas de hora em hora."""
    if stop_event.wait(180):
        return
    while not stop_event.is_set():
        try:
            catalogo_ml_rodada(stop_event)
        except Exception as exc:
            print(f"[catalogo-ml] rodada falhou: {exc}", file=sys.stderr, flush=True)
        if stop_event.wait(CATALOGO_ML_INTERVALO):
            return


def _catalogo_ml_linha(r: sqlite3.Row) -> dict[str, Any]:
    d = dict(r)
    try:
        d["motivos"] = json.loads(d.get("motivos") or "[]")
    except Exception:
        d["motivos"] = []
    d["da_margem"] = None if d["da_margem"] is None else bool(d["da_margem"])
    d["frete_incerto"] = bool(d.get("frete_incerto"))
    d["conta_nome"] = CASAS.get(d["conta"], d["conta"])
    return d


def catalogo_ml_payload(conta: str = "") -> dict[str, Any]:
    conta = str(conta or "").strip().lower()
    with DB_LOCK:
        if conta in CASAS:
            rows = DB.execute("SELECT * FROM catalogo_ml_v1974 WHERE conta=? ORDER BY item_id", (conta,)).fetchall()
        else:
            rows = DB.execute("SELECT * FROM catalogo_ml_v1974 ORDER BY conta, item_id").fetchall()
    itens = [_catalogo_ml_linha(r) for r in rows]
    resumo = {"total": len(itens), "ganhando": 0, "compartilhando": 0, "perdendo_com_margem": 0,
              "perdendo_sem_margem": 0, "sem_custo": 0, "nao_elegivel": 0, "com_erro": 0}
    for i in itens:
        s = i["situacao"]
        if i["erro"]:
            resumo["com_erro"] += 1
        if s in ("ganhando", "compartilhando", "nao_elegivel"):
            resumo[s] += 1
        elif s == "perdendo":
            chave = {True: "perdendo_com_margem", False: "perdendo_sem_margem"}.get(i["da_margem"], "sem_custo")
            resumo[chave] += 1
    cfg = promo_auto_config()
    return {"ok": True, "itens": itens, "resumo": resumo,
            "coleta": dict(_CATALOGO_ML_ESTADO),
            "regras": {"margem_min_promo": cfg.get("margem_min_promo"), "intervalo_min": CATALOGO_ML_INTERVALO // 60,
                       "duracao_dias": cfg.get("duracao_dias")},
            "contas": {c: CASAS[c] for c in CASAS}}


def catalogo_ml_item(conta: str, item_id: str) -> dict[str, Any]:
    conta, item_id = str(conta or "").strip().lower(), str(item_id or "").strip().upper()
    with DB_LOCK:
        r = DB.execute("SELECT * FROM catalogo_ml_v1974 WHERE conta=? AND item_id=?", (conta, item_id)).fetchone()
        if r is None:
            raise LookupError("Anúncio não está no monitor de catálogo.")
        conc = DB.execute("SELECT * FROM catalogo_ml_concorrente_v1974 WHERE conta=? AND produto_id=? "
                          "ORDER BY preco IS NULL, preco", (conta, r["produto_id"])).fetchall()
        hist = DB.execute("SELECT em,situacao,preco,preco_ganhar,ganhador_preco FROM catalogo_ml_hist_v1974 "
                          "WHERE conta=? AND item_id=? ORDER BY id DESC LIMIT 60", (conta, item_id)).fetchall()
    return {"ok": True, "item": _catalogo_ml_linha(r),
            "concorrentes": [dict(c, meu=c["item_id"] == item_id) for c in conc],
            "historico": [dict(h) for h in hist]}


CATALOGO_PROMO_ESPERA = 20.0   # V19.76: espera a vez do anúncio; responde antes dos 60 s do nginx


def _catalogo_campanha_valendo(promos: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Campanha do ML (não o nosso desconto próprio nem o desconto do Pix) valendo agora.
    Prazo passado = acabou, mesmo com o ML ainda dizendo "started" (V19.75)."""
    agora = datetime.now(timezone.utc)
    for x in promos or []:
        fim_dt = _promo_fim_dt(x.get("finish_date"))
        if (str(x.get("status") or "").lower() == "started"
                and str(x.get("type") or "") not in (ML_PROMO_TIPO, "BANK")
                and not (fim_dt and fim_dt <= agora)):
            return x
    return None


def catalogo_ml_trocar_promocao(conta: str, mlb: Any, preco: Any, ator: str,
                                encerrar: bool = False) -> dict[str, Any]:
    """V19.76: troca o desconto próprio (PRICE_DISCOUNT) do anúncio NA HORA, pela gaveta do
    Catálogo (decisões do dono, 22/10). Clique do ADMIN = ação explícita, como o Lote.

    Mesma ml_promocao_aplicar das Promoções automáticas (trava do preço mínimo e piso/teto do ML
    no servidor), de hoje até hoje + duracao_dias, na conta do anúncio. Deu certo: o anúncio fica
    marcado na renovação com o preço novo e "renovado hoje" (a rodada não cria outra no mesmo dia).
    Revisão de 22/10:
      - tudo sob a vez do anúncio (_promo_vez, a mesma da renovação, V18.92): a rodada não recria o
        preço antigo entre o encerrar e o criar; ocupado = PromoOcupado (409 na rota);
      - as travas são conferidas ANTES de encerrar (so_validar); se ainda assim a criação falhar
        depois de encerrar — inclusive por trava —, avisa que o anúncio ficou sem desconto;
      - recusa do ML: com campanha do ML valendo ('em_campanha') nunca oferece nem faz o encerrar
        (regra da V18.73: espera a campanha acabar); só com o nosso desconto próprio valendo a tela
        pergunta ('ml_recusou'); sem nenhum dos dois é só o erro ('ml_erro')."""
    conta = str(conta or "").strip().lower()
    if conta not in CASAS:
        raise ValueError("Conta do Mercado Livre inválida.")
    mlb = _mlb_normalizar(mlb)
    if not mlb:
        raise ValueError("Anúncio (MLB) inválido.")
    try:   # a gaveta manda "205,00" ou 205
        valor = round(float(str(preco).strip().replace("R$", "").replace(".", "").replace(",", "."))
                      if isinstance(preco, str) and "," in preco else float(preco), 2)
    except (TypeError, ValueError):
        valor = 0.0
    if valor <= 0:
        raise ValueError("Informe um preço válido.")
    hoje = datetime.now(BR_TZ).date()
    inicio = hoje.isoformat() + "T00:00:00"
    with _promo_vez(CATALOGO_PROMO_ESPERA), ml_na_casa(conta):
        cfg = promo_auto_config()
        fim = (hoje + timedelta(days=int(cfg["duracao_dias"]))).isoformat() + "T00:00:00"
        if encerrar:
            campanha = _catalogo_campanha_valendo(ml_promocoes_do_item(mlb))
            if campanha:
                return _catalogo_em_campanha(campanha)
            ml_promocao_aplicar(mlb, valor, inicio, fim, ator, so_validar=True)   # trava antes de encerrar
            ml_promocao_remover(mlb, ator)
            _promo_log(mlb, "encerrada", ator, "Encerrada pela gaveta do Catálogo para trocar o preço", valor)
        try:
            r = ml_promocao_aplicar(mlb, valor, inicio, fim, ator)
        except Exception as exc:
            if not encerrar and isinstance(exc, ValueError):
                raise
            _promo_log(mlb, "falhou", ator, f"Catálogo: {exc}", valor, None, inicio, fim, hoje.isoformat())
            if encerrar:
                return {"ok": False, "code": "sem_desconto",
                        "error": (f"A promoção anterior foi encerrada, mas a nova não foi criada: {exc}. "
                                  "O anúncio está sem desconto: confira no Mercado Livre.")}
            try:
                promos = ml_promocoes_do_item(mlb)
            except Exception:
                promos = []
            campanha = _catalogo_campanha_valendo(promos)
            if campanha:
                return _catalogo_em_campanha(campanha)
            proprio = any(str(x.get("type") or "") == ML_PROMO_TIPO
                          and str(x.get("status") or "").lower() in ("started", "pending") for x in promos)
            return {"ok": False, "code": "ml_recusou" if proprio else "ml_erro", "error": str(exc)}
        agora = now_iso()
        with DB_LOCK:
            # mesma gravação do promo_renovacao_marcar (que pegaria a vez de novo) + renovado hoje
            DB.execute("DELETE FROM promo_removidos_v1876 WHERE mlb=?", (mlb,))
            DB.execute("INSERT INTO promo_renovacao_v1873(mlb,marcado,preco,marcado_por,marcado_em,conta,renovado_dia,renovado_em,fim) "
                       "VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(mlb) DO UPDATE SET marcado=1,preco=excluded.preco,"
                       "marcado_por=excluded.marcado_por,marcado_em=excluded.marcado_em,"
                       "renovado_dia=excluded.renovado_dia,renovado_em=excluded.renovado_em,fim=excluded.fim",
                       (mlb, 1, valor, ator, agora, conta, hoje.isoformat(), agora, fim))
            DB.execute("UPDATE catalogo_ml_v1974 SET preco=? WHERE conta=? AND item_id=?", (valor, conta, mlb))
            DB.commit()
    _promo_log(mlb, "renovada", ator, f"Preço trocado pela gaveta do Catálogo para {_brl_srv(valor)}",
               valor, r.get("margem"), inicio, fim, hoje.isoformat())
    return {"ok": True, "mlb": mlb, "preco": valor, "fim": fim, "margem": r.get("margem")}


def _catalogo_em_campanha(campanha: dict[str, Any]) -> dict[str, Any]:
    nome = str(campanha.get("name") or ML_PROMO_TIPO_NOME.get(str(campanha.get("type") or ""), campanha.get("type") or ""))
    return {"ok": False, "code": "em_campanha",
            "error": (f"O anúncio está na campanha do Mercado Livre \"{nome}\". O desconto próprio só volta quando ela "
                      "acabar: nada foi encerrado.")}


def catalogo_ml_amostras() -> dict[str, Any]:
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM catalogo_ml_amostra_v1974").fetchall()
    out = {}
    for r in rows:
        try:
            out[r["tipo"]] = {"em": r["em"], "resposta": json.loads(r["json"])}
        except Exception:
            out[r["tipo"]] = {"em": r["em"], "resposta": r["json"]}
    return {"ok": True, "amostras": out}


def posvenda_rodada_contas(stop_event: threading.Event | None = None, *, reclamacoes: bool = True,
                           pausa: float | None = None) -> dict[str, Any]:
    """V20.01: perguntas (e, quando pedido, reclamações e reputação) de cada conta conectada,
    cada uma com o próprio token. O erro de uma conta não impede a outra."""
    feito: dict[str, Any] = {}
    casas = ml_casas_conectadas()
    # Revisão 29/10: as perguntas de TODAS as contas primeiro (rápidas e com aviso); as reclamações (até 150
    # detalhes por conta) depois — antes a pergunta de Bauru esperava todas as reclamações de Araçatuba.
    for casa in casas:
        if stop_event is not None and stop_event.is_set():
            break
        with ml_na_casa(casa):
            try:
                posvenda_perguntas_rodada(stop_event)
            except Exception as exc:
                _posvenda_estado_conta(casa, "perguntas", {"ok": False, "erro": str(exc)[:300], "em": now_iso()})
                print(f"[posvenda] perguntas ({casa}) falharam: {exc}", file=sys.stderr, flush=True)
    for casa in casas if reclamacoes else []:
        if stop_event is not None and stop_event.is_set():
            break
        with ml_na_casa(casa):
            try:
                posvenda_reclamacoes_rodada(stop_event, pausa=pausa)
            except Exception as exc:
                _posvenda_estado_conta(casa, "reclamacoes", {"ok": False, "erro": str(exc)[:300], "em": now_iso()})
                print(f"[posvenda] reclamações ({casa}) falharam: {exc}", file=sys.stderr, flush=True)
            try:
                posvenda_reputacao_rodada()
            except Exception as exc:
                print(f"[posvenda] reputação ({casa}) falhou: {exc}", file=sys.stderr, flush=True)
    for casa in casas:
        feito[casa] = dict((_POSVENDA_ESTADO.get("contas") or {}).get(casa) or {})
    return feito


def posvenda_loop(stop_event: threading.Event) -> None:
    """Perguntas a cada 5 min; reclamações e reputação a cada 15 min. V20.01: de cada conta."""
    if stop_event.wait(120):
        return
    proxima_reclamacao = 0.0
    while not stop_event.is_set():
        fazer = time.time() >= proxima_reclamacao
        if fazer:
            proxima_reclamacao = time.time() + POSVENDA_INTERVALO
        posvenda_rodada_contas(stop_event, reclamacoes=fazer)
        if stop_event.wait(POSVENDA_PERGUNTAS_INTERVALO):
            break


def _posvenda_valores(r: dict[str, Any], custo_unit: Any) -> dict[str, Any]:
    """Quanto a reclamação custou. Só com o que o ML informa; o que falta fica None.

    - venda_desfeita: dinheiro devolvido ao comprador que saiu do vendedor (com
      cobertura do ML, quem paga é o ML: 0).
    - frete_devolucao: o que o ML cobra do vendedor pelo envio da devolução.
    - produto_perdido: custo do produto que não voltou (comprador ficou, devolução
      de baixo custo) ou voltou sem condição de venda (triagem: inservível,
      descartado, não chegou). Produto que voltou bom = 0.
    - reembolso_parcial: comprador ficou com o produto e recebeu parte do dinheiro.
    perda = frete_devolucao + produto_perdido + reembolso_parcial.
    Reclamação aberta ainda não tem perda (fica "em aberto").
    """
    itens = []
    try:
        itens = json.loads(r.get("itens_json") or "[]")
    except Exception:
        itens = []
    total = _posvenda_float(r.get("pedido_total"))
    reemb = _posvenda_float(r.get("reembolsado"))
    coberto = r.get("cobertura") == 1
    fechada = r.get("status") == "closed"
    venceu_vendedor = "respondent" in str(r.get("beneficiado") or "").split(",") and "complainant" not in str(r.get("beneficiado") or "")
    out: dict[str, Any] = {"venda_desfeita": None, "frete_devolucao": None, "produto_perdido": None,
                           "reembolso_parcial": None, "perda": None, "produto": "", "pendente": [], "custo_produto": None}
    # custo do que foi vendido (para o produto perdido)
    custo = 0.0
    sem_custo = not itens
    for i in itens:
        unit = custo_unit(str(i.get("sku") or ""))
        if unit is None:
            sem_custo = True
            continue
        custo += unit * (_posvenda_float(i.get("qtd")) or 0.0)
    out["custo_produto"] = None if sem_custo else round(custo, 2)
    if not fechada:
        out["produto"] = "em_aberto"
        return out
    # frete da devolução
    if r.get("tem_devolucao"):
        out["frete_devolucao"] = _posvenda_float(r.get("frete_devolucao"))
        if out["frete_devolucao"] is None and str(r.get("devolucao_subtipo")) == "low_cost":
            out["frete_devolucao"] = 0.0   # baixo custo: não gera envio de devolução
        if out["frete_devolucao"] is None:
            out["pendente"].append("frete da devolução")
    else:
        out["frete_devolucao"] = 0.0
    # venda desfeita
    if coberto or venceu_vendedor:
        out["venda_desfeita"] = 0.0
    elif reemb is None:
        out["pendente"].append("reembolso")
    else:
        out["venda_desfeita"] = reemb
    # o produto
    condicao = str(r.get("produto_condicao") or "")
    dev_status = str(r.get("devolucao_status") or "")
    parcial = (reemb is not None and total and 0 < reemb < total * 0.98)
    if coberto or venceu_vendedor or (reemb is not None and reemb == 0):
        out["produto"], out["produto_perdido"], out["reembolso_parcial"] = "sem_perda", 0.0, 0.0
    elif condicao in ("unsaleable", "discard", "missing"):
        out["produto"] = "inservivel"
        out["produto_perdido"], out["reembolso_parcial"] = out["custo_produto"], 0.0
    elif r.get("tem_devolucao") and dev_status == "delivered" and str(r.get("devolucao_subtipo")) != "low_cost":
        out["produto"], out["produto_perdido"], out["reembolso_parcial"] = "voltou", 0.0, 0.0
    elif parcial and not (r.get("tem_devolucao") and dev_status == "delivered"):
        out["produto"], out["produto_perdido"], out["reembolso_parcial"] = "ficou_parcial", 0.0, reemb
    elif reemb is not None and r.get("entregue") == 1 and (not r.get("tem_devolucao") or str(r.get("devolucao_subtipo")) == "low_cost"
                                                           or dev_status in ("expired", "cancelled", "not_delivered")):
        out["produto"] = "nao_voltou"
        out["produto_perdido"], out["reembolso_parcial"] = out["custo_produto"], 0.0
    else:
        out["produto"] = "conferir"   # não entregue, devolução em andamento, ou sem dado
        out["pendente"].append("situação do produto")
    if out["produto"] in ("inservivel", "nao_voltou") and out["produto_perdido"] is None:
        out["pendente"].append("custo do produto")
    partes = [out["frete_devolucao"], out["produto_perdido"], out["reembolso_parcial"]]
    if all(p is not None for p in partes):
        out["perda"] = round(sum(partes), 2)
    return out


POSVENDA_DEVOLUCAO_CAMINHO_DIAS = 60   # V20.01: devoluções do ML mostradas na tela (abertas nesse prazo)
POSVENDA_DEVOLUCAO_ENCERRADA = ("cancelled", "expired", "failed", "return_to_buyer")


def _posvenda_devolucoes_recebidas(dias: int = 180) -> dict[str, dict[str, Any]]:
    """V20.01: nº de venda/carrinho/pedido → devolução recebida na tela de Devoluções (V19.88)."""
    corte = (datetime.now(timezone.utc) - timedelta(days=dias)).astimezone().isoformat(timespec="milliseconds")
    achadas: dict[str, dict[str, Any]] = {}
    with DB_LOCK:
        linhas = [dict(r) for r in DB.execute(
            "SELECT d.id, d.order_key, d.pedido, d.recebido_em, d.situacao, "
            "(SELECT GROUP_CONCAT(DISTINCT b.ml_ids) FROM devolucao_busca_v1988 b WHERE b.order_key=d.order_key) AS ml_ids "
            "FROM devolucao_v1988 d WHERE d.recebido_em>=? AND d.order_key<>''", (corte,))]
    for d in linhas:
        ids = {str(d["order_key"]), normalize(d["pedido"])}
        if str(d["order_key"]).startswith(DEVOLUCAO_VENDA_PREFIXO):
            ids.add(str(d["order_key"])[len(DEVOLUCAO_VENDA_PREFIXO):])
        ids |= {x for x in str(d.get("ml_ids") or "").split(",") if x}
        for i in ids - {""}:
            achadas.setdefault(i, {"id": d["id"], "recebido_em": d["recebido_em"], "situacao": d["situacao"]})
    return achadas


def posvenda_resumo() -> dict[str, Any]:
    """V20.01: selo do menu — perguntas sem resposta e as que passaram de 1 h."""
    limite = datetime.now(timezone.utc) - timedelta(hours=POSVENDA_PERGUNTA_ATRASO_H)
    # Revisão 29/10: só as contas conectadas — a de uma conta que caiu não é mais relida e deixaria o selo vermelho.
    conectadas = set(ml_casas_conectadas())
    with DB_LOCK:
        rows = [r for r in DB.execute("SELECT conta, criada_em FROM ml_pergunta_v1888 WHERE status='UNANSWERED'").fetchall()
                if str(r["conta"] or CASA_PRINCIPAL) in conectadas]
    por_conta: dict[str, int] = {}
    atrasadas = 0
    for r in rows:
        por_conta[str(r["conta"] or CASA_PRINCIPAL)] = por_conta.get(str(r["conta"] or CASA_PRINCIPAL), 0) + 1
        c = _posvenda_dt(r["criada_em"])
        atrasadas += 1 if (c and c < limite) else 0
    return {"ok": True, "sem_resposta": len(rows), "atrasadas": atrasadas, "por_conta": por_conta,
            "atraso_horas": POSVENDA_PERGUNTA_ATRASO_H}


def posvenda_payload(dias: int = 30, hoje: date | None = None, com_relatorio: bool = True) -> dict[str, Any]:
    """Tela de Pós-venda. Só lê o banco (a coleta é do worker).
    V20.01: a tela não mostra mais o relatório de perdas (a perda fica no Financeiro, V19.95):
    com_relatorio=False pula a conta de custo, que é a parte pesada."""
    dias = max(1, min(int(dias), 365))
    hoje = hoje or datetime.now(BR_TZ).date()
    d1 = hoje - timedelta(days=dias - 1)
    agora = datetime.now(timezone.utc)
    with DB_LOCK:
        recl = [dict(r) for r in DB.execute(
            "SELECT r.*, m.detalhe AS motivo_txt FROM ml_reclamacao_v1888 r "
            "LEFT JOIN ml_reclamacao_motivo_v1888 m ON m.motivo_id=r.motivo_id").fetchall()]
        perguntas = [dict(r) for r in DB.execute(
            "SELECT p.*, i.titulo AS item_titulo, i.preco AS item_preco, i.estoque AS item_estoque, i.sku AS item_sku, "
            "i.status AS item_status FROM ml_pergunta_v1888 p "
            "LEFT JOIN ml_visitas_item_v1868 i ON i.item_id=p.item_id "
            "WHERE p.status='UNANSWERED' ORDER BY p.criada_em").fetchall()]
        respondidas = [dict(r) for r in DB.execute(
            "SELECT criada_em, respondida_em, respondida_por FROM ml_pergunta_v1888 "
            "WHERE status='ANSWERED' AND respondida_em<>''").fetchall()]
        # V20.01: as últimas respostas de cada anúncio que tem pergunta esperando
        itens_espera = sorted({str(p["item_id"]) for p in perguntas if p["item_id"]})
        anteriores: dict[str, list[dict[str, Any]]] = {}
        for item_id in itens_espera:
            anteriores[item_id] = [dict(r) for r in DB.execute(
                "SELECT pergunta_id, texto, resposta, respondida_em, respondida_por FROM ml_pergunta_v1888 "
                "WHERE item_id=? AND status='ANSWERED' AND resposta<>'' ORDER BY respondida_em DESC LIMIT 5", (item_id,))]
        reput_todas = [dict(r) for r in DB.execute(
            "SELECT * FROM ml_reputacao_conta_v2001 WHERE dia>=? ORDER BY dia DESC",
            ((hoje - timedelta(days=60)).isoformat(),)).fetchall()]
        fat = DB.execute("SELECT COALESCE(SUM(amount),0) AS v, COUNT(DISTINCT order_id) AS n FROM vendas_v1799 "
                         "WHERE marketplace='ml' AND sale_day BETWEEN ? AND ?", (d1.isoformat(), hoje.isoformat())).fetchone()
    reput_por_conta: dict[str, list[dict[str, Any]]] = {}
    for r in reput_todas:
        reput_por_conta.setdefault(str(r["conta"]), []).append(r)
    reput = reput_por_conta.get(CASA_PRINCIPAL, [])

    if com_relatorio:
        produtos = _compras_produtos_precificador()
        reservas = _compras_custos_reserva(produtos)
        skus = []
        for r in recl:
            try:
                skus += [str(i.get("sku") or "") for i in json.loads(r.get("itens_json") or "[]")]
            except Exception:
                pass
        kits = full_kit_compositions([s for s in skus if s])
    cache: dict[str, Any] = {}

    def custo_unit(sku: str) -> float | None:
        return _financeiro_custo_unitario(sku, produtos, reservas, kits, cache)[0] if sku else None

    abertas, fechadas = [], []
    for r in recl:
        try:
            itens = json.loads(r.get("itens_json") or "[]")
        except Exception:
            itens = []
        prazo_txt = _posvenda_prazo(r) if r["status"] == "opened" else ""
        prazo = _posvenda_dt(prazo_txt)
        horas = round((prazo - agora).total_seconds() / 3600, 1) if prazo else None
        item = {
            "claim_id": r["claim_id"], "order_id": r["order_id"], "tipo": r["tipo"], "etapa": r["etapa"],
            "status": r["status"], "motivo_id": r["motivo_id"], "motivo": r.get("motivo_txt") or "",
            "aberta_em": r["aberta_em"], "fechada_em": r["fechada_em"], "resolucao": r["resolucao"],
            "resolucao_txt": POSVENDA_RESOLUCAO_TXT.get(r["resolucao"], r["resolucao"]),
            "beneficiado": r["beneficiado"], "cobertura": r["cobertura"], "acao": r["acao"],
            "acao_txt": POSVENDA_ACAO_TXT.get(r["acao"], r["acao"]), "prazo": prazo_txt, "horas_restantes": horas,
            "responsavel": r["responsavel"], "titulo_ml": r["titulo_ml"], "problema": r["problema"],
            "afeta_reputacao": r["afeta_reputacao"], "tem_devolucao": bool(r["tem_devolucao"]),
            "devolucao_status": r["devolucao_status"], "devolucao_subtipo": r["devolucao_subtipo"],
            "devolucao_destino": r["devolucao_destino"], "dinheiro_status": r["dinheiro_status"],
            "produto_condicao": r["produto_condicao"], "pedido_total": r["pedido_total"],
            "reembolsado": r["reembolsado"], "itens": itens, "erro": r["erro"],
            "detalhado": bool(r["detalhado_em"]),
            "sku": ", ".join(sorted({str(i.get("sku") or "") for i in itens if i.get("sku")})),
            "anuncio": (itens[0].get("item_id") if itens else ""),
            "titulo": (itens[0].get("titulo") if itens else ""),
            "conta": str(r.get("conta") or CASA_PRINCIPAL),   # V20.01
            "devolucao_envios": [x for x in str(r.get("devolucao_envios") or "").split(",") if x],
        }
        if com_relatorio:
            item.update(_posvenda_valores(r, custo_unit))
        if r["status"] == "opened":
            abertas.append(item)
        else:
            fechadas.append(item)
    abertas.sort(key=lambda x: (x["horas_restantes"] is None, x["horas_restantes"] if x["horas_restantes"] is not None else 0,
                                x["aberta_em"]))

    # relatório: reclamações ABERTAS no período (as abertas entram como "em aberto")
    def no_periodo(x: dict[str, Any]) -> bool:
        return d1.isoformat() <= str(x["aberta_em"])[:10] <= hoje.isoformat()

    periodo = [x for x in fechadas + abertas if no_periodo(x)]
    fech_p = [x for x in periodo if x["status"] != "opened"]

    def soma(campo: str, lista: list[dict[str, Any]]) -> float:
        return round(sum(float(x[campo]) for x in lista if x.get(campo) is not None), 2)

    def agrupar(chave_fn: Any) -> list[dict[str, Any]]:
        g: dict[str, dict[str, Any]] = {}
        for x in periodo:
            k, rot = chave_fn(x)
            a = g.setdefault(k, {"chave": k, "rotulo": rot, "reclamacoes": 0, "devolucoes": 0, "abertas": 0,
                                 "venda_desfeita": 0.0, "frete_devolucao": 0.0, "produto_perdido": 0.0,
                                 "reembolso_parcial": 0.0, "perda": 0.0, "incompletas": 0})
            a["reclamacoes"] += 1
            a["devolucoes"] += 1 if x["tem_devolucao"] else 0
            if x["status"] == "opened":
                a["abertas"] += 1
                continue
            for c in ("venda_desfeita", "frete_devolucao", "produto_perdido", "reembolso_parcial", "perda"):
                a[c] = round(a[c] + float(x.get(c) or 0), 2)
            a["incompletas"] += 1 if x["perda"] is None else 0
        return sorted(g.values(), key=lambda a: (-a["perda"], -a["reclamacoes"]))

    respondidas_30 = []
    corte_30 = agora - timedelta(days=30)
    for p in respondidas:
        c, rsp = _posvenda_dt(p["criada_em"]), _posvenda_dt(p["respondida_em"])
        if c and rsp and rsp >= corte_30 and rsp >= c:
            respondidas_30.append((rsp - c).total_seconds() / 3600)
    respondidas_30.sort()
    for p in perguntas:
        c = _posvenda_dt(p["criada_em"])
        p["horas_esperando"] = round((agora - c).total_seconds() / 3600, 1) if c else None
        # V20.01: o anúncio pelo retrato diário (sem chamar o ML; Bauru ainda não tem retrato) e as respostas anteriores
        p["conta"] = str(p.get("conta") or CASA_PRINCIPAL)
        p["anuncio"] = {"titulo": p.pop("item_titulo", None) or "", "preco": p.pop("item_preco", None),
                        "estoque": p.pop("item_estoque", None), "sku": p.pop("item_sku", None) or "",
                        "status": p.pop("item_status", None) or ""}
        p["anteriores"] = anteriores.get(str(p["item_id"]), [])
        p.pop("comprador_id", None)

    # V20.01: devoluções do ML (reclamação com envio de volta) e se a peça já chegou na tela de Devoluções
    recebidas = _posvenda_devolucoes_recebidas()
    corte_dev = (hoje - timedelta(days=POSVENDA_DEVOLUCAO_CAMINHO_DIAS)).isoformat()
    devolucoes = []
    for x in abertas + fechadas:
        if not x["tem_devolucao"] or not x["order_id"] or str(x["aberta_em"])[:10] < corte_dev:
            continue
        if x["devolucao_status"] in POSVENDA_DEVOLUCAO_ENCERRADA:
            continue
        rec = recebidas.get(normalize(x["order_id"])) or recebidas.get(str(x["order_id"]))
        devolucoes.append({
            "claim_id": x["claim_id"], "order_id": x["order_id"], "conta": x["conta"], "aberta_em": x["aberta_em"],
            "status_reclamacao": x["status"], "devolucao_status": x["devolucao_status"],
            "devolucao_subtipo": x["devolucao_subtipo"], "destino": x["devolucao_destino"], "motivo": x["motivo"],
            "titulo": x["titulo"], "sku": x["sku"], "pedido_total": x["pedido_total"], "envios": x["devolucao_envios"],
            "recebida": bool(rec), "recebida_em": (rec or {}).get("recebido_em", ""), "devolucao_id": (rec or {}).get("id"),
        })
    devolucoes.sort(key=lambda d: (d["recebida"], d["aberta_em"]))

    estado_contas = _POSVENDA_ESTADO.get("contas") or {}
    conectadas = set(ml_casas_conectadas())
    contas = [{"conta": c, "nome": CASAS[c], "conectada": c in conectadas,
               "perguntas": (estado_contas.get(c) or {}).get("perguntas") or {},
               "reclamacoes": (estado_contas.get(c) or {}).get("reclamacoes") or {}} for c in CASAS]

    saida = {
        "ok": True,
        "periodo": {"inicio": d1.isoformat(), "fim": hoje.isoformat(), "dias": dias},
        "coleta": {"reclamacoes": _POSVENDA_ESTADO.get("ultimo") or {}, "perguntas": _POSVENDA_ESTADO.get("perguntas") or {},
                   "rodando": bool(_POSVENDA_ESTADO.get("rodando")), "total_guardadas": len(recl),
                   "pendentes_detalhe": sum(1 for r in recl if r["precisa_detalhe"])},
        "contas": contas,
        "abertas": abertas,
        "perguntas": perguntas,
        "perguntas_resumo": {
            "sem_resposta": len(perguntas),
            "respondidas_30d": len(respondidas_30),
            "mediana_horas": round(respondidas_30[len(respondidas_30) // 2], 1) if respondidas_30 else None,
        },
        "devolucoes": devolucoes,
        "reputacao": reput,
        "reputacao_por_conta": reput_por_conta,
        "respostas_prontas": posvenda_respostas_prontas(),
        "config": posvenda_config(),
        "regras": {"prazo_critico_horas": POSVENDA_PRAZO_CRITICO_H, "historico_dias": POSVENDA_HISTORICO_DIAS,
                   "intervalo_min": POSVENDA_INTERVALO // 60, "perguntas_intervalo_min": POSVENDA_PERGUNTAS_INTERVALO // 60,
                   "resposta_max": POSVENDA_RESPOSTA_MAX, "pergunta_atraso_horas": POSVENDA_PERGUNTA_ATRASO_H,
                   "devolucao_dias": POSVENDA_DEVOLUCAO_CAMINHO_DIAS},
    }
    if not com_relatorio:
        return saida
    faturamento = round(float(fat["v"] or 0), 2)
    perda_total = soma("perda", fech_p)
    saida["relatorio"] = {
            "reclamacoes": len(periodo),
            "devolucoes": sum(1 for x in periodo if x["tem_devolucao"]),
            "em_aberto": sum(1 for x in periodo if x["status"] == "opened"),
            "fechadas": len(fech_p),
            "incompletas": sum(1 for x in fech_p if x["perda"] is None),
            "venda_desfeita": soma("venda_desfeita", fech_p),
            "frete_devolucao": soma("frete_devolucao", fech_p),
            "produto_perdido": soma("produto_perdido", fech_p),
            "reembolso_parcial": soma("reembolso_parcial", fech_p),
            "perda": perda_total,
            "faturamento_ml": faturamento,
            "pedidos_ml": int(fat["n"] or 0),
            "perda_sobre_faturamento": round(perda_total / faturamento * 100, 2) if faturamento else None,
            "taxa_reclamacao": round(len(periodo) / int(fat["n"]) * 100, 2) if int(fat["n"] or 0) else None,
            "por_motivo": agrupar(lambda x: (x["motivo_id"] or "?", x["motivo"] or x["motivo_id"] or "Sem motivo")),
            "por_anuncio": agrupar(lambda x: (x["anuncio"] or x["order_id"] or x["claim_id"],
                                              (x["titulo"] or x["anuncio"] or "Sem anúncio") + (f" · SKU {x['sku']}" if x["sku"] else ""))),
            "por_mes": sorted(agrupar(lambda x: (str(x["aberta_em"])[:7], str(x["aberta_em"])[:7])), key=lambda a: a["chave"]),
            "itens": sorted(periodo, key=lambda x: x["aberta_em"], reverse=True),
    }
    return saida


def _saude_posvenda() -> list[dict[str, Any]]:
    """V18.88: reclamação do ML com prazo do vendedor vencendo (< 24 h) = crítico (vira e-mail)."""
    g = "Operação"
    if not ml_status_payload().get("configured"):
        return []
    # V20.01: as duas contas; a falha de leitura de cada uma aparece com o nome dela.
    # Revisão 29/10: só as contas conectadas (a reclamação de uma conta que caiu não é mais relida: o prazo
    # "vencido" congelado mandaria e-mail a cada 6 h).
    conectadas = set(ml_casas_conectadas())
    falhas = [(c, (e or {}).get("reclamacoes") or {}) for c, e in (_POSVENDA_ESTADO.get("contas") or {}).items()
              if c in conectadas]
    falhas = [(c, u) for c, u in falhas if u.get("ok") is False]
    if not falhas and (_POSVENDA_ESTADO.get("ultimo") or {}).get("ok") is False:
        falhas = [(CASA_PRINCIPAL, _POSVENDA_ESTADO["ultimo"])]
    agora = datetime.now(timezone.utc)
    with DB_LOCK:
        abertas = [dict(r) for r in DB.execute(
            "SELECT claim_id, order_id, acao, prazo, prazo_detalhe, responsavel, conta FROM ml_reclamacao_v1888 "
            "WHERE status='opened'").fetchall() if str(r["conta"] or CASA_PRINCIPAL) in conectadas]
    vencendo = []
    com_acao = 0
    for r in abertas:
        prazo = _posvenda_dt(_posvenda_prazo(r))
        if r["acao"] or prazo:
            com_acao += 1
        if prazo and (prazo - agora).total_seconds() < POSVENDA_PRAZO_CRITICO_H * 3600:
            vencendo.append((prazo, r))
    if vencendo:
        vencendo.sort(key=lambda x: x[0])
        prazo, r = vencendo[0]
        horas = (prazo - agora).total_seconds() / 3600
        quando = f"vence em {_saude_idade_txt(horas * 3600)}" if horas > 0 else f"venceu há {_saude_idade_txt(-horas * 3600)}"
        return [_saude_item("posvenda_prazo", g, "Reclamações do Mercado Livre", "critico",
                            f"{len(vencendo)} reclamação(ões) com prazo do vendedor em menos de {POSVENDA_PRAZO_CRITICO_H} h",
                            f"A mais urgente ({POSVENDA_ACAO_TXT.get(r['acao'], r['acao']) or 'ação do vendedor'}, "
                            f"{CASAS.get(str(r.get('conta') or CASA_PRINCIPAL), '')}, "
                            f"pedido {r['order_id'] or r['claim_id']}) {quando}.", "/posvenda", "Abrir Pós-venda")]
    if falhas:
        conta, ultimo = falhas[0]
        nomes = ", ".join(CASAS.get(c, c) for c, _ in falhas)
        return [_saude_item("posvenda_prazo", g, "Reclamações do Mercado Livre", "atencao",
                            f"Não foi possível ler as reclamações no ML ({nomes})",
                            ("Falta a permissão de pós-venda: reconecte a conta em Integrações. " if ultimo.get("sem_permissao") else "")
                            + str(ultimo.get("erro") or "")[:200], "/posvenda", "Abrir Pós-venda")]
    if com_acao:
        return [_saude_item("posvenda_prazo", g, "Reclamações do Mercado Livre", "atencao",
                            f"{com_acao} reclamação(ões) esperando ação do vendedor", "", "/posvenda", "Abrir Pós-venda")]
    return [_saude_item("posvenda_prazo", g, "Reclamações do Mercado Livre", "ok",
                        f"{len(abertas)} reclamação(ões) aberta(s), nenhuma esperando o vendedor" if abertas
                        else "Nenhuma reclamação aberta")]


def _financeiro_custos_venda_ml(order_ids: list[str]) -> dict[str, dict[str, Any]]:
    """Tarifa e frete como o ML mostrou NO ATO DA VENDA, por pedido.

    Tarifa: soma do sale_fee das linhas do pedido (é o "Tarifa de venda total").
    Frete: custo do envio; quando o mesmo envio cobre vários pedidos (pack), o
    custo é dividido entre eles — senão o frete apareceria duplicado.
    """
    alvo = [str(o).strip() for o in order_ids if str(o).strip()]
    if not alvo:
        return {}
    linhas: list[dict[str, Any]] = []
    for lote in _financeiro_chunks(alvo):
        ph = ",".join("?" for _ in lote)
        with DB_LOCK:
            linhas.extend(dict(r) for r in DB.execute(
                f"SELECT order_id, line_key, sale_fee, shipment_id FROM ml_venda_custo_v1830 WHERE order_id IN ({ph})",
                tuple(lote)).fetchall())
    if not linhas:
        return {}
    envios = sorted({str(l["shipment_id"] or "") for l in linhas if l["shipment_id"]})
    custo_envio: dict[str, float] = {}
    pedidos_por_envio: dict[str, int] = {}
    for lote in _financeiro_chunks(envios):
        ph = ",".join("?" for _ in lote)
        with DB_LOCK:
            for r in DB.execute(f"SELECT shipment_id, cost FROM ml_frete_envio_v1830 WHERE shipment_id IN ({ph}) AND cost IS NOT NULL",
                                tuple(lote)).fetchall():
                custo_envio[str(r["shipment_id"])] = float(r["cost"] or 0)
            for r in DB.execute(
                    f"SELECT shipment_id, COUNT(DISTINCT order_id) AS pedidos FROM ml_venda_custo_v1830 "
                    f"WHERE shipment_id IN ({ph}) GROUP BY shipment_id", tuple(lote)).fetchall():
                pedidos_por_envio[str(r["shipment_id"])] = max(1, int(r["pedidos"] or 1))

    out: dict[str, dict[str, Any]] = {}
    envios_do_pedido: dict[str, set[str]] = {}
    for l in linhas:
        oid = str(l["order_id"])
        alvo_pedido = out.setdefault(oid, {"taxa": None, "frete": None, "linhas": 0})
        alvo_pedido["linhas"] += 1
        fee = _money_number(l["sale_fee"])
        if fee is not None:
            alvo_pedido["taxa"] = round((alvo_pedido["taxa"] or 0.0) + abs(fee), 2)
        sid = str(l["shipment_id"] or "")
        if sid:
            envios_do_pedido.setdefault(oid, set()).add(sid)
    for oid, sids in envios_do_pedido.items():
        total = 0.0
        achou = False
        for sid in sids:
            if sid in custo_envio:
                achou = True
                total += custo_envio[sid] / pedidos_por_envio.get(sid, 1)
        if achou:
            out[oid]["frete"] = round(total, 2)
    return out


def _financeiro_billing_ml(period_keys: list[str], order_ids: list[str],
                           dia_inicio: str = "", dia_fim: str = "") -> dict[str, Any]:
    """Concilia a fatura do ML do período: por pedido e o que não tem pedido.

    Usa a MESMA regra do cálculo por venda (_ml_billing_consolidar_lancamentos).
    O raw_json é truncado no SELECT porque aqui são milhares de lançamentos de
    uma vez; a classificação por sub_type e por transaction_detail não depende
    dele — ele é só o último fallback para reconhecer envio.
    """
    vazio = {"por_pedido": {},
             "sem_pedido": {"publicidade": 0.0, "outros": 0.0, "credito": 0.0, "itens": [], "por_dia": {}},
             "periodos": period_keys, "lancamentos": 0}
    if not period_keys:
        return vazio
    colunas = ("detail_id,order_id,detail_amount,detail_type,detail_sub_type,transaction_detail,"
               "debited_from_operation,sale_fee_net,is_credit,detail_date,"
               "substr(raw_json,1,1200) AS raw_json")
    ph_periodos = ",".join("?" for _ in period_keys)
    por_pedido_entries: dict[str, list[dict[str, Any]]] = {}
    alvo = {str(o).strip() for o in order_ids if str(o).strip()}
    total = 0
    for lote in _financeiro_chunks(sorted(alvo)):
        ph_ids = ",".join("?" for _ in lote)
        with DB_LOCK:
            rows = DB.execute(
                f"SELECT {colunas} FROM ml_billing_period_detail "
                f"WHERE period_key IN ({ph_periodos}) AND order_id IN ({ph_ids})",
                tuple(period_keys) + tuple(lote),
            ).fetchall()
        for r in rows:
            total += 1
            por_pedido_entries.setdefault(str(r["order_id"]), []).append(dict(r))
    por_pedido = {oid: _ml_billing_consolidar_lancamentos(ents) for oid, ents in por_pedido_entries.items()}

    # Lançamentos sem pedido: publicidade, mensalidades, ajustes do período.
    pub = 0.0
    outros = 0.0
    credito = 0.0
    itens: dict[str, float] = {}
    pub_por_dia: dict[str, float] = {}
    with DB_LOCK:
        rows = DB.execute(
            f"SELECT {colunas} FROM ml_billing_period_detail WHERE period_key IN ({ph_periodos}) AND order_id=''",
            tuple(period_keys),
        ).fetchall()
    for r in _ml_billing_dedupe([dict(x) for x in rows]):
        total += 1
        valor = _money_number(r["detail_amount"])
        if valor is None or abs(valor) <= 0:
            continue
        valor = abs(valor)
        # V18.37: fora da janela escolhida, o lançamento é de outro período. Sem
        # data (fatura antiga, antes do backfill) ele entra, para não sumir.
        dia_lanc = str(r["detail_date"] or "")
        if dia_lanc and dia_inicio and dia_fim and not (dia_inicio <= dia_lanc <= dia_fim):
            continue
        descricao = str(r["transaction_detail"] or r["detail_sub_type"] or r["detail_type"] or "Outros")[:120]
        if _ml_billing_credito_do_lancamento(str(r["detail_type"] or ""), str(r["detail_sub_type"] or "")):
            credito += valor
            continue
        if _ml_billing_is_neutro(str(r["detail_sub_type"] or "")):
            continue
        if _ml_billing_is_publicidade(str(r["detail_sub_type"] or ""), str(r["detail_type"] or ""), str(r["transaction_detail"] or "")):
            pub += valor
            if dia_lanc:
                pub_por_dia[dia_lanc] = round(pub_por_dia.get(dia_lanc, 0.0) + valor, 2)
        else:
            outros += valor
        itens[descricao] = round(itens.get(descricao, 0.0) + valor, 2)
    ordenados = sorted(itens.items(), key=lambda kv: -kv[1])[:20]
    return {"por_pedido": por_pedido,
            "sem_pedido": {"publicidade": round(pub, 2), "outros": round(outros, 2), "credito": round(credito, 2),
                           "itens": [{"descricao": k, "valor": v} for k, v in ordenados],
                           "por_dia": pub_por_dia},
            "periodos": period_keys, "lancamentos": total}


def _financeiro_custo_unitario(sku: str, produtos: dict[str, Any], reservas: dict[str, Any],
                               kits: dict[str, Any], cache: dict[str, Any]) -> tuple[float | None, str]:
    """Custo de UMA unidade do que foi vendido nesse anúncio (kit = soma dos
    componentes). Devolve (custo, origem); custo None = não sabemos, e aí a linha
    entra como pendência em vez de virar lucro inventado."""
    chave = str(sku or "").strip().upper()
    if chave in cache:
        return cache[chave]
    if not chave:
        cache[chave] = (None, "")
        return cache[chave]
    comps = (kits.get(str(sku or "").strip()) or {}).get("componentes")
    if not comps:
        partes = [x for x in chave.split("/") if x.strip()] if "/" in chave else [chave]
        comps = [{"sku": x, "quantidade": 1} for x in partes]
    total = 0.0
    origens: list[str] = []
    completo = True
    for c in comps:
        codigo = _compras_codigo(str(c.get("sku") or ""), produtos)
        if not codigo:
            completo = False
            continue
        base = (produtos.get(codigo) or {}).get("custo")
        custo, origem, _data = _compras_resolver_custo(base, reservas.get(codigo, {}))
        if custo is None:
            completo = False
            continue
        try:
            unidades = max(1, int(c.get("quantidade") or 1))
        except (TypeError, ValueError):
            unidades = 1
        total += float(custo) * unidades
        origens.append(origem)
    resultado = (round(total, 4), ("kit" if len(comps) > 1 else (origens[0] if origens else ""))) if (completo and total > 0) else (None, "")
    cache[chave] = resultado
    return resultado


def _financeiro_ads_periodo(d1: date, d2: date) -> dict[str, Any]:
    """Gasto com Product Ads no período: total, por dia e por SKU."""
    with DB_LOCK:
        dias = DB.execute("SELECT dia, cost FROM ml_ads_dia_v1830 WHERE dia BETWEEN ? AND ?",
                          (d1.isoformat(), d2.isoformat())).fetchall()
        por_sku = DB.execute(
            "SELECT UPPER(sku) AS sku, SUM(cost) AS cost FROM ml_ads_item_dia_v1830 "
            "WHERE dia BETWEEN ? AND ? AND sku<>'' GROUP BY UPPER(sku)",
            (d1.isoformat(), d2.isoformat())).fetchall()
        sem_sku = DB.execute(
            "SELECT COALESCE(SUM(cost),0) AS cost FROM ml_ads_item_dia_v1830 "
            "WHERE dia BETWEEN ? AND ? AND sku=''", (d1.isoformat(), d2.isoformat())).fetchone()
    return {
        "total": round(sum(float(r["cost"] or 0) for r in dias), 2),
        "por_dia": {str(r["dia"]): round(float(r["cost"] or 0), 2) for r in dias},
        "por_sku": {str(r["sku"] or ""): round(float(r["cost"] or 0), 2) for r in por_sku},
        "sem_sku": round(float((sem_sku["cost"] if sem_sku else 0) or 0), 2),
        "dias_com_dado": len(dias),
        "status": ml_ads_status(),
    }


# ---------------------------------------------------------------------------
# V19.77: custo do produto no Financeiro (decisões do dono, 22/10).
# 6007.003.315.00.8 foi vendido com custo de R$ 13,02 em Araçatuba; o estoque zerou, o Precificador
# ficou com 0 e o Financeiro puxou R$ 39,41 — o último custo visto, lido no Apollo de BAURU
# (custos_conhecidos_v1807 mistura as filiais). Agora:
#   * custo = sempre o de ARAÇATUBA (revenda 1): custosFiliais do Precificador, senão o custo do
#     Precificador quando a filial dele é Araçatuba, senão o último custo de Araçatuba lido no Apollo
#     (custo_apollo_v1931["1"]); o custo_auto misturado NUNCA entra;
#   * a venda congela esse custo quando entra (venda_custo_v1977, até FINANCEIRO_CONGELA_DIAS depois):
#     zerar o estoque ou mudar o custo médio depois não muda o custo daquela venda;
#   * venda antiga sem custo congelado = melhor estimativa ("estimado"); o custo digitado vence;
#   * SKU com barra que é um código inteiro ("PSH367/80") não vira duas peças; código fora do
#     Precificador com custo de Araçatuba no Apollo tem custo.
# A regra antiga (_financeiro_custo_unitario) continua para o Pós-venda e a análise de kits.
# ---------------------------------------------------------------------------
FINANCEIRO_CONGELA_DIAS = 3   # revisão 22/10: venda que a sincronização traz depois também congela
FINANCEIRO_ESCROW_ERRO_ESPERA = 6 * 3600   # escrow que deu erro só é tentado de novo depois de 6 h
FINANCEIRO_SHOPEE_ESCROW_DIAS = 30
REVENDA_ARACATUBA = "1"


def ensure_venda_custo_schema() -> None:
    with DB_LOCK:
        DB.execute(
            """CREATE TABLE IF NOT EXISTS venda_custo_v1977 (
                marketplace TEXT NOT NULL, order_id TEXT NOT NULL, line_key TEXT NOT NULL,
                sku TEXT NOT NULL DEFAULT '', custo_unit REAL NOT NULL, origem TEXT NOT NULL DEFAULT '',
                capturado_em TEXT NOT NULL DEFAULT '',
                PRIMARY KEY (marketplace, order_id, line_key)
            )""")
        DB.commit()


def _financeiro_custos_aracatuba(com_vendas_ml: bool = True) -> dict[str, Any]:
    """Custos de Araçatuba por código: Precificador, último lido no Apollo, digitado e o da venda do ML."""
    dados = precificador_dados()
    produtos = dados.get("products") if isinstance(dados, dict) else None
    prec: dict[str, float | None] = {}
    prec_apollo: dict[str, float | None] = {}   # só o custosFiliais (vem do Apollo); sem o custo digitado
    so_planilha: set[str] = set()               # produto da planilha antiga que nunca foi lido do Apollo
    outra: dict[str, float] = {}                 # menor custo de outra filial (só quando Araçatuba nunca teve)
    for p in produtos if isinstance(produtos, list) else []:
        if not isinstance(p, dict) or p.get("isKit"):
            continue
        codigo = str(p.get("sku") or "").strip().upper()
        if not codigo or codigo in prec:
            continue
        ara = None
        filiais = p.get("custosFiliais")
        lido_do_apollo = isinstance(filiais, list) and any(isinstance(f, dict) for f in filiais)
        for f in filiais if isinstance(filiais, list) else []:
            if isinstance(f, dict) and str(f.get("revenda")) == REVENDA_ARACATUBA:
                v = _money_number(f.get("custo_medio"))
                ara = v if v and v > 0 else None
            elif isinstance(f, dict):
                v = _money_number(f.get("custo_medio"))
                if v and v > 0:
                    outra[codigo] = min(outra.get(codigo, v), v)
        prec_apollo[codigo] = ara
        # 22/10 (dono): o custo da planilha antiga embutida no Precificador ("_id" source-N, nunca lido do
        # Apollo) tem 30-42% a mais em quase metade dos produtos (WAP331 74,97 x 53,04; JFC217 91,00 x 64,38;
        # 10256080 965,73 x 731,64). Sem leitura do Apollo, ele NÃO vale; o digitado/cadastrado depois vale.
        da_planilha = str(p.get("_id") or "").startswith("source-")
        if da_planilha and not lido_do_apollo:
            so_planilha.add(codigo)
        if (ara is None and not lido_do_apollo and not da_planilha
                and str(p.get("filialCusto") or REVENDA_ARACATUBA) == REVENDA_ARACATUBA):
            v = _money_number(p.get("custo"))
            ara = v if v and v > 0 else None
        prec[codigo] = ara
    apollo: dict[str, float] = {}
    manual: dict[str, float] = {}
    with DB_LOCK:
        for r in DB.execute("SELECT codigo, custos_json FROM custo_apollo_v1931").fetchall():
            try:
                custos = json.loads(r["custos_json"] or "{}") or {}
            except Exception:
                custos = {}
            cod_ap = str(r["codigo"] or "").strip().upper()
            v = _money_number(custos.get(REVENDA_ARACATUBA))
            if v and v > 0:
                apollo[cod_ap] = float(v)
            for rev, c in custos.items():
                c = _money_number(c)
                if str(rev) != REVENDA_ARACATUBA and c and c > 0:
                    outra[cod_ap] = min(outra.get(cod_ap, float(c)), float(c))
        for r in DB.execute("SELECT codigo, custo_manual FROM custos_conhecidos_v1807 WHERE custo_manual > 0").fetchall():
            manual[str(r["codigo"] or "").strip().upper()] = float(r["custo_manual"])
        # 22/10 (dono): o "último custo visto" (custos_conhecidos_v1807.custo_auto) só vale quando veio do
        # PRECIFICADOR (o de origem "Apollo" mistura as filiais) e o produto não é só da planilha antiga
        # (senão é cópia do custo inflado da planilha). Produto lido do Apollo que depois zerou mantém o custo.
        ultimo_prec = {str(r["codigo"] or "").strip().upper(): float(r["custo_auto"]) for r in DB.execute(
            "SELECT codigo, custo_auto FROM custos_conhecidos_v1807 WHERE custo_auto > 0 AND origem_auto='Precificador'")}
        # só a estimativa usa o custo da venda do ML; a rotina de congelar não precisa ler a tabela
        snaps = DB.execute("SELECT sku, unit_cost FROM ml_profitability_snapshot WHERE unit_cost > 0 "
                           "ORDER BY captured_at").fetchall() if com_vendas_ml else []
    ultimo_prec = {k: v for k, v in ultimo_prec.items() if k not in so_planilha}
    conhecidos = set(prec) | set(apollo) | set(manual) | set(ultimo_prec) | set(outra)
    venda: dict[str, float] = {}
    for r in snaps:
        codigo = _compras_codigo(str(r["sku"] or ""), dict.fromkeys(conhecidos))
        if codigo:
            venda[codigo] = float(r["unit_cost"])
    return {"prec": prec, "prec_apollo": prec_apollo, "apollo": apollo, "manual": manual, "venda": venda,
            "ultimo_prec": ultimo_prec, "outra": outra,
            "conhecidos": dict.fromkeys(conhecidos), "kits": {}, "cache": {}}


def _financeiro_custo_codigo(codigo: str, ctx: dict[str, Any], congelar: bool) -> tuple[float | None, str]:
    """Custo de Araçatuba de UM código. Para congelar (a venda acabou de entrar): o custo de agora
    do Apollo (pelo Precificador) manda. Para estimar venda antiga: o digitado vence."""
    prec = ctx["prec"].get(codigo)
    if congelar:
        # revisão 22/10: o Apollo de Araçatuba (do Precificador ou o último lido) antes do custo do
        # Precificador sem filial, que pode ser um valor digitado velho
        for v in (ctx["prec_apollo"].get(codigo), ctx["apollo"].get(codigo), prec, ctx["ultimo_prec"].get(codigo),
                  ctx["manual"].get(codigo)):
            if v:
                return float(v), "venda"
        return None, ""
    if ctx["manual"].get(codigo):
        return float(ctx["manual"][codigo]), "manual"
    for v in (prec, ctx["apollo"].get(codigo), ctx["ultimo_prec"].get(codigo), ctx["venda"].get(codigo)):
        if v:
            return float(v), "estimado"
    # 22/10 (dono): vendido por Araçatuba sem custo de Araçatuba registrado -> SEM custo. O custo de outra
    # filial era palpite (6007: Bauru 39,41 x 13,02 real); o dono digita o real no Financeiro (codigo_custo).
    return None, ""


def _financeiro_custo_aracatuba(sku: str, ctx: dict[str, Any], congelar: bool = False) -> tuple[float | None, str]:
    """Custo de UMA unidade do SKU vendido (kit = soma das peças), só de Araçatuba."""
    chave = (str(sku or "").strip().upper(), congelar)
    if chave in ctx["cache"]:
        return ctx["cache"][chave]
    s = chave[0]
    if not s:
        return None, ""
    kits = ctx["kits"]
    if str(sku).strip() not in kits:
        kits.update(full_kit_compositions([str(sku).strip()]))
    comps = (kits.get(str(sku).strip()) or {}).get("componentes")
    conhecidos = ctx["conhecidos"]
    texto_partes = s
    if re.search(r"/|\s-\s", s) and re.match(r"^KIT(?!\d+-)", s):
        texto_partes = re.sub(r"^KIT[-\s]*", "", s)      # "KITRS001005 - RS000365", "KIT-A/B"
    partes = [{"sku": x.strip(), "quantidade": 1}
              for x in re.split(r"\s*/\s*|\s+-\s+", texto_partes) if x.strip()]
    tentativas = [comps] if comps else []
    # "PSH367/80" é um código inteiro; "157507-0893556005" é prefixo do ML + código. Nada além disso:
    # "KITRS001005 - RS000365" não pode virar só a RS000365 pelo traço.
    if not comps and (s in conhecidos or (re.match(r"^\d+-", s) and _compras_codigo(s, conhecidos))):
        tentativas.append([{"sku": s, "quantidade": 1}])
    # 22/10 (produção): "KIT-ACP126/0893764271" está no Precificador como produto com custo 0;
    # sem custo no código inteiro, soma as peças
    if not comps and (len(partes) > 1 or not tentativas):
        tentativas.append(partes)
    resultado: tuple[float | None, str] = (None, "")
    for lista in tentativas:
        total, origens, completo = 0.0, [], True
        for c in lista:
            codigo = _compras_codigo(str(c.get("sku") or ""), conhecidos)
            custo, origem = _financeiro_custo_codigo(codigo, ctx, congelar) if codigo else (None, "")
            if custo is None:
                completo = False
                break
            try:
                unidades = max(1, int(c.get("quantidade") or 1))
            except (TypeError, ValueError):
                unidades = 1
            total += custo * unidades
            origens.append(origem)
        if completo and total > 0:
            origem = "venda" if congelar else (
                "outra_filial" if "outra_filial" in origens
                else "manual" if all(o == "manual" for o in origens) else "estimado")
            resultado = (round(total, 4), origem)
            break
    ctx["cache"][chave] = resultado
    return resultado


def compras_custo_aracatuba(codigo: str, ctx: dict[str, Any]) -> tuple[float | None, str, str]:
    """V19.78: custo da Demanda de Compra pela regra do Financeiro (só Araçatuba; nunca a planilha antiga
    do Precificador nem o último custo de outra filial). (custo, origem, data) com os rótulos da tela:
    apollo (custo de hoje), manual (digitado), ultimo (último de Araçatuba visto), venda (custo da venda do ML)."""
    hoje = ctx["prec"].get(codigo)
    if hoje:
        return float(hoje), "apollo", ""
    if ctx["manual"].get(codigo):
        return float(ctx["manual"][codigo]), "manual", ""
    for v in (ctx["apollo"].get(codigo), ctx["ultimo_prec"].get(codigo)):
        if v:
            return float(v), "ultimo", ""
    if ctx["venda"].get(codigo):
        return float(ctx["venda"][codigo]), "venda", ""
    return None, "", ""


def _financeiro_codigo_editavel(sku: str, ctx: dict[str, Any]) -> str:
    """Código da peça para o custo digitado no Financeiro ('' em kit: o custo é a soma das peças)."""
    s = str(sku or "").strip().upper()
    if not s or (ctx["kits"].get(str(sku).strip()) or {}).get("componentes"):
        return ""
    if s in ctx["conhecidos"]:
        return s
    if re.search(r"/|\s-\s", s) or re.match(r"^KIT", s):
        return ""
    m = re.match(r"^\d+-(.+)$", s)          # prefixo do anúncio do ML: "157507-0893556005"
    return m.group(1).strip() if m else s


def financeiro_custo_congelar(dias: int = FINANCEIRO_CONGELA_DIAS) -> int:
    """Congela o custo de Araçatuba nas vendas que entraram há até `dias` e ainda não têm custo
    congelado. Sem custo conhecido não grava (tenta de novo na rodada seguinte). Devolve quantas."""
    desde = (datetime.now(BR_TZ).date() - timedelta(days=max(0, dias))).isoformat()
    with DB_LOCK:
        linhas = DB.execute(
            "SELECT v.marketplace, v.order_id, v.line_key, v.sku FROM vendas_v1799 v "
            "LEFT JOIN venda_custo_v1977 c ON c.marketplace=v.marketplace AND c.order_id=v.order_id AND c.line_key=v.line_key "
            "WHERE v.sale_day >= ? AND c.order_id IS NULL", (desde,)).fetchall()
    if not linhas:
        return 0
    ctx = _financeiro_custos_aracatuba(com_vendas_ml=False)
    novos = []
    for r in linhas:
        custo, _origem = _financeiro_custo_aracatuba(str(r["sku"] or ""), ctx, congelar=True)
        if custo:
            novos.append((r["marketplace"], r["order_id"], r["line_key"], str(r["sku"] or ""), custo, "venda", now_iso()))
    if novos:
        with DB_LOCK:
            DB.executemany("INSERT OR IGNORE INTO venda_custo_v1977(marketplace,order_id,line_key,sku,custo_unit,origem,"
                           "capturado_em) VALUES(?,?,?,?,?,?,?)", novos)
            DB.commit()
    return len(novos)


def financeiro_shopee_escrow_pendentes(limite: int | None = None, stop_event: threading.Event | None = None) -> int:
    """V19.77: o escrow da Shopee (taxa e frete reais) só vinha pelo botão "Buscar custos oficiais":
    237 de 292 pedidos de outubro ficaram "parciais". Agora a rotina do Financeiro busca sozinha os
    pedidos dos últimos FINANCEIRO_SHOPEE_ESCROW_DIAS dias que ainda não têm."""
    desde = (datetime.now(BR_TZ).date() - timedelta(days=FINANCEIRO_SHOPEE_ESCROW_DIAS)).isoformat()
    with DB_LOCK:
        # revisão 22/10: o que deu erro há menos de 6 h não é tentado de novo (limite de chamadas da Shopee)
        pendentes = [str(r["order_id"]) for r in DB.execute(
            "SELECT DISTINCT v.order_id FROM vendas_v1799 v "
            "LEFT JOIN shopee_escrow_v1810 e ON e.order_sn = v.order_id AND (e.erro='' OR e.fetched_epoch > ?) "
            "WHERE v.marketplace='shopee' AND v.sale_day >= ? AND e.order_sn IS NULL "
            "ORDER BY v.sale_day DESC", (int(time.time()) - FINANCEIRO_ESCROW_ERRO_ESPERA, desde)).fetchall()]
    buscados = 0
    for sn in pendentes[:(limite or FINANCEIRO_SHOPEE_POR_RODADA)]:
        if stop_event is not None and stop_event.is_set():
            break
        if shopee_escrow_lookup(sn):
            buscados += 1
    return buscados


def financeiro_evolucao_payload(marketplace: str = "", hoje: date | None = None) -> dict[str, Any]:
    """V20.06: faturamento, pedidos e ticket dos últimos 12 meses (mini gráficos do Financeiro).
    Rota à parte do resumo, que passa de 60 s em produção: só soma `vendas_v1799`, sem custo nem
    Precificador. Mês sem venda fica em branco, nunca zero. O mês atual sai marcado como parcial."""
    hoje = hoje or datetime.now(BR_TZ).date()
    canal = marketplace if marketplace in VENDAS_MARKETPLACES else ""
    chaves = []
    ano, m = hoje.year, hoje.month
    for _ in range(12):
        chaves.append(f"{ano:04d}-{m:02d}")
        ano, m = (ano - 1, 12) if m == 1 else (ano, m - 1)
    chaves.reverse()
    filtro = " AND marketplace=?" if canal else ""
    with DB_LOCK:
        linhas = DB.execute(
            "SELECT substr(sale_day,1,7) AS mes, SUM(amount) AS fat, "
            "COUNT(DISTINCT marketplace || '|' || order_id) AS ped FROM vendas_v1799 "
            f"WHERE sale_day >= ? AND sale_day <= ?{filtro} GROUP BY mes",
            (chaves[0] + "-01", hoje.isoformat()) + ((canal,) if canal else ())).fetchall()
    por = {str(r["mes"]): r for r in linhas}
    meses = []
    for k in chaves:
        r = por.get(k)
        fat = round(float(r["fat"] or 0), 2) if r else None
        ped = int(r["ped"] or 0) if r else None
        meses.append({"mes": k, "faturamento": fat, "pedidos": ped, "ticket": round(fat / ped, 2) if ped else None,
                      "parcial": k == chaves[-1]})
    return {"ok": True, "marketplace": canal, "meses": meses}


def financeiro_payload(date_from: str, date_to: str, marketplace: str = "", limite_pedidos: int = 400) -> dict[str, Any]:
    """Faturamento, gastos e lucro do período, com a origem de cada número."""
    d1 = datetime.strptime(date_from, "%Y-%m-%d").date()
    d2 = datetime.strptime(date_to, "%Y-%m-%d").date()
    if d1 > d2:
        d1, d2 = d2, d1
    if (d2 - d1).days > 400:
        raise ValueError("Período muito longo (máximo 400 dias).")
    canal = marketplace if marketplace in VENDAS_MARKETPLACES else ""
    filtro = " AND marketplace=?" if canal else ""
    args: tuple[Any, ...] = (d1.isoformat(), d2.isoformat()) + ((canal,) if canal else ())
    with DB_LOCK:
        vendas = [dict(r) for r in DB.execute(
            "SELECT marketplace, order_id, line_key, sale_day, sku, anuncio, title, qty, amount "
            f"FROM vendas_v1799 WHERE sale_day BETWEEN ? AND ?{filtro} ORDER BY sale_day, order_id",
            args).fetchall()]

    produtos = _compras_produtos_precificador()
    # V19.77: custo de Araçatuba, e o congelado na venda quando existe
    custos_ctx = _financeiro_custos_aracatuba()
    custos_ctx["kits"] = full_kit_compositions([v["sku"] for v in vendas])
    with DB_LOCK:
        congelados = {(r["marketplace"], r["order_id"], r["line_key"]): float(r["custo_unit"])
                      for r in DB.execute("SELECT marketplace, order_id, line_key, custo_unit FROM venda_custo_v1977 "
                                          "WHERE order_id IN (SELECT order_id FROM vendas_v1799 WHERE sale_day BETWEEN ? AND ?)",
                                          (d1.isoformat(), d2.isoformat())).fetchall()}
    imposto_rate = FINANCEIRO_IMPOSTO_PERCENT / 100.0

    # --- custos por pedido -------------------------------------------------
    pedidos_ml = sorted({str(v["order_id"]) for v in vendas if v["marketplace"] == "ml"})
    pedidos_shopee = sorted({str(v["order_id"]) for v in vendas if v["marketplace"] == "shopee"})
    billing = _financeiro_billing_ml(_financeiro_periodos_fatura(d1, d2), pedidos_ml,
                                     d1.isoformat(), d2.isoformat()) if pedidos_ml else \
        {"por_pedido": {},
         "sem_pedido": {"publicidade": 0.0, "outros": 0.0, "credito": 0.0, "itens": [], "por_dia": {}},
         "periodos": [], "lancamentos": 0}
    escrow: dict[str, dict[str, Any]] = {}
    for lote in _financeiro_chunks(pedidos_shopee):
        ph = ",".join("?" for _ in lote)
        with DB_LOCK:
            for r in DB.execute(f"SELECT * FROM shopee_escrow_v1810 WHERE order_sn IN ({ph}) AND erro=''", tuple(lote)).fetchall():
                escrow[str(r["order_sn"])] = dict(r)

    venda_custos = _financeiro_custos_venda_ml(pedidos_ml) if pedidos_ml else {}

    custos_pedido: dict[tuple[str, str], dict[str, Any]] = {}
    for oid in pedidos_ml:
        b = billing["por_pedido"].get(oid) or {}
        v = venda_custos.get(oid) or {}
        # V18.31: a tarifa e o frete já aparecem NO ATO DA VENDA (é o que o ML
        # mostra no detalhe do pedido). A fatura é a conferência: quando o
        # lançamento existe, ele manda, porque é o que foi de fato cobrado.
        taxa_fatura = _money_number(b.get("sale_fee"))
        frete_fatura = _money_number(b.get("shipping"))
        taxa_venda = _money_number(v.get("taxa"))
        frete_venda = _money_number(v.get("frete"))
        taxa = taxa_fatura if taxa_fatura is not None else taxa_venda
        # V18.53: no FRETE a ordem é a inversa. A fatura lança o envio CHEIO (parte
        # do comprador + parte do vendedor = gross_amount do /shipments/costs), e a
        # parte do comprador não está no nosso faturamento. Venda 2000015151309807:
        # fatura 128,89, comprador pagou 105,99, vendedor 22,90. O custo do envio
        # (senders[].cost) é a parte do vendedor; a fatura só vale sem ele.
        frete = frete_venda if frete_venda is not None else frete_fatura
        outros = _money_number(b.get("other_cost"))
        # V18.34: PADS (publicidade) já sai separado do consolidador e nunca entra
        # em "outros". Vira o Ads do pedido quando a API de Publicidade não responde.
        pub = float(b.get("publicidade") or 0.0)
        if taxa_fatura is not None:
            origem = str(b.get("source") or "") or "Fatura ML"
        elif taxa_venda is not None:
            origem = "Tarifa da venda (Orders ML)"
        else:
            origem = "Tarifa ainda não capturada"
        custos_pedido[("ml", oid)] = {
            "taxa": taxa, "frete": frete, "outros": outros, "ads_fatura": pub,
            "bonus": float(b.get("bonus") or 0.0), "origem": origem,
            "conciliado": taxa is not None, "na_fatura": taxa_fatura is not None,
            "taxa_venda": taxa_venda, "taxa_fatura": taxa_fatura,
            "frete_venda": frete_venda, "frete_fatura": frete_fatura,
            "divergencia_taxa": (round(taxa_fatura - taxa_venda, 2)
                                 if (taxa_fatura is not None and taxa_venda is not None) else None),
            "divergencia_frete": (round(frete_fatura - frete_venda, 2)
                                  if (frete_fatura is not None and frete_venda is not None) else None),
            "frete_so_fatura": frete_venda is None and frete_fatura is not None,
        }
    for oid in pedidos_shopee:
        e = escrow.get(oid)
        if not e:
            custos_pedido[("shopee", oid)] = {"taxa": None, "frete": None, "outros": None, "bonus": 0.0,
                                              "origem": "Escrow Shopee ainda não consultado", "conciliado": False}
            continue
        # V18.35: o escrow_amount é o que REALMENTE entra na conta — ele é a
        # autoridade, como a fatura é no ML. As colunas explicam a maior parte
        # do que a Shopee reteve; o que sobrar vira "outros" em vez de virar
        # margem. Sem isso faltavam 3,5% do preço (a comissão de afiliados/AMS,
        # R$ 654,29 em setembro, que agora entra como Ads).
        taxa = round(float(e["commission_fee"] or 0) + float(e["service_fee"] or 0) + float(e["transaction_fee"] or 0), 2)
        frete_shopee = round(float(e["shipping_net"] or 0), 2)
        ams = round(float((e["ams_commission"] if "ams_commission" in e.keys() else 0) or 0), 2)
        preco = float(e["selling_price"] or 0)
        recebido = float(e["escrow_amount"] or 0)
        retido = round(preco - recebido, 2) if (preco > 0 and recebido > 0) else None
        outros_shopee = 0.0
        if retido is not None:
            outros_shopee = round(max(0.0, retido - taxa - frete_shopee - ams), 2)
        custos_pedido[("shopee", oid)] = {"taxa": taxa, "frete": frete_shopee,
                                          "outros": outros_shopee, "ads_fatura": ams, "bonus": 0.0,
                                          "origem": "Shopee get_escrow_detail", "conciliado": True,
                                          "renda_liquida": round(recebido, 2), "retido": retido}

    # Receita por pedido para ratear a taxa/frete entre as linhas.
    receita_pedido: dict[tuple[str, str], float] = {}
    for v in vendas:
        chave = (str(v["marketplace"]), str(v["order_id"]))
        receita_pedido[chave] = receita_pedido.get(chave, 0.0) + float(v["amount"] or 0)

    ads = _financeiro_ads_periodo(d1, d2)
    # V18.34: o gasto com Ads também está na fatura do ML (sub_type PADS), lançado
    # POR PEDIDO. Quando a API de Publicidade não responde — hoje é o caso — a
    # fatura é a fonte, e ainda dá o custo por pedido e por SKU, que a API só
    # daria com muito mais chamada. Uma fonte OU a outra; nunca as duas somadas.
    ads_fatura_pedidos = round(sum(float((c or {}).get("ads_fatura") or 0.0)
                                   for k, c in custos_pedido.items() if k[0] == "ml"), 2)
    # A Shopee cobra a comissão de afiliados (AMS) dentro do escrow: é marketing
    # e entra sempre, independente da API de Publicidade do ML.
    ads_shopee = round(sum(float((c or {}).get("ads_fatura") or 0.0)
                           for k, c in custos_pedido.items() if k[0] == "shopee"), 2)
    # V18.38: o CPC do Shopee Ads é custo do PERÍODO (crédito pré-pago, fora do
    # pedido). Vem por dia e entra no dia em que foi gasto.
    ads_shopee_cpc_por_dia: dict[str, float] = {}
    if not canal or canal == "shopee":
        with DB_LOCK:
            for r in DB.execute("SELECT dia, expense FROM shopee_ads_dia_v1838 WHERE dia BETWEEN ? AND ?",
                                (d1.isoformat(), d2.isoformat())).fetchall():
                ads_shopee_cpc_por_dia[str(r["dia"])] = round(float(r["expense"] or 0), 2)
    ads_shopee_cpc = round(sum(ads_shopee_cpc_por_dia.values()), 2)
    ads_fatura_sem_pedido = round(float((billing.get("sem_pedido") or {}).get("publicidade") or 0.0), 2)
    ads_api_total = ads["total"] if (not canal or canal == "ml") else 0.0
    if ads_api_total > 0:
        ads_fonte = "api"
    elif (ads_fatura_pedidos + ads_fatura_sem_pedido) > 0 and (not canal or canal == "ml"):
        ads_fonte = "fatura"
    elif ads_shopee > 0 or ads_shopee_cpc > 0:
        ads_fonte = "shopee"
    else:
        ads_fonte = ""
    usar_ads_da_fatura = ads_fonte == "fatura"

    def bloco() -> dict[str, Any]:
        return {"faturamento": 0.0, "unidades": 0, "pedidos": set(), "cmv": 0.0, "taxas": 0.0, "frete": 0.0,
                "outros": 0.0, "imposto": 0.0, "ads": 0.0, "sem_custo": 0.0, "sem_taxa": 0.0, "sem_frete": 0.0,
                "devolucoes": 0.0}

    totais = bloco()
    por_mp: dict[str, dict[str, Any]] = {m: bloco() for m in VENDAS_MARKETPLACES}
    por_dia: dict[str, dict[str, Any]] = {}
    por_sku: dict[str, dict[str, Any]] = {}
    pedidos_detalhe: dict[tuple[str, str], dict[str, Any]] = {}

    for v in vendas:
        mp = str(v["marketplace"])
        oid = str(v["order_id"])
        chave = (mp, oid)
        receita = round(float(v["amount"] or 0), 2)
        qty = int(v["qty"] or 0)
        sku = str(v["sku"] or "").strip()
        sku_key = sku.upper() or "(sem SKU)"
        congelado = congelados.get((mp, oid, str(v["line_key"])))
        unit, origem_custo = _financeiro_custo_aracatuba(sku, custos_ctx)
        if congelado is not None and origem_custo != "manual":
            # o custo digitado na Demanda de Compra vence até o congelado (é a correção do dono)
            unit, origem_custo = congelado, "venda"
        cmv = round(unit * qty, 2) if unit is not None else None
        pc = custos_pedido.get(chave) or {}
        total_pedido = receita_pedido.get(chave, 0.0)
        fatia = (receita / total_pedido) if total_pedido > 0 else 1.0
        taxa = round(pc["taxa"] * fatia, 2) if pc.get("taxa") is not None else None
        frete = round(pc["frete"] * fatia, 2) if pc.get("frete") is not None else None
        outros = round(pc["outros"] * fatia, 2) if pc.get("outros") is not None else None
        imposto = round(receita * imposto_rate, 2)
        # Shopee: AMS sempre. ML: só quando a API de Publicidade não respondeu.
        usa_ads_desta_linha = (mp == "shopee") or usar_ads_da_fatura
        ads_linha = round(float(pc.get("ads_fatura") or 0.0) * fatia, 2) if usa_ads_desta_linha else 0.0

        alvos = [totais, por_mp.setdefault(mp, bloco()),
                 por_dia.setdefault(str(v["sale_day"]), {**bloco(), "dia": str(v["sale_day"])})]
        for alvo in alvos:
            alvo["faturamento"] = round(alvo["faturamento"] + receita, 2)
            alvo["unidades"] += qty
            alvo["pedidos"].add(chave)
            alvo["imposto"] = round(alvo["imposto"] + imposto, 2)
            if cmv is None:
                alvo["sem_custo"] = round(alvo["sem_custo"] + receita, 2)
            else:
                alvo["cmv"] = round(alvo["cmv"] + cmv, 2)
            if taxa is None:
                alvo["sem_taxa"] = round(alvo["sem_taxa"] + receita, 2)
            else:
                alvo["taxas"] = round(alvo["taxas"] + taxa, 2)
            # V18.34: frete desconhecido é pendência, não zero. Um pedido pode ter
            # frete 0 de verdade (frete grátis do comprador) — a diferença tem que
            # aparecer na tela em vez de virar margem inventada.
            if frete is None:
                alvo["sem_frete"] = round(alvo["sem_frete"] + receita, 2)
            else:
                alvo["frete"] = round(alvo["frete"] + frete, 2)
            if outros is not None:
                alvo["outros"] = round(alvo["outros"] + outros, 2)
            if ads_linha:
                alvo["ads"] = round(alvo["ads"] + ads_linha, 2)

        s = por_sku.setdefault(sku_key, {"sku": sku_key, "titulo": str(v["title"] or ""), "codigo": _compras_codigo(sku, produtos),
                                         "unidades": 0, "faturamento": 0.0, "cmv": 0.0, "taxas": 0.0, "frete": 0.0,
                                         "outros": 0.0, "imposto": 0.0, "ads": 0.0, "custo_unitario": unit,
                                         "custo_origem": origem_custo, "sem_custo": False, "pedidos": set(),
                                         "_origens": set(), "codigo_custo": _financeiro_codigo_editavel(sku, custos_ctx),
                                         "sem_taxa": 0.0, "sem_frete": 0.0})
        s["unidades"] += qty
        if origem_custo:
            s["_origens"].add(origem_custo)
        s["faturamento"] = round(s["faturamento"] + receita, 2)
        s["imposto"] = round(s["imposto"] + imposto, 2)
        s["pedidos"].add(chave)
        if cmv is None:
            s["sem_custo"] = True
        else:
            s["cmv"] = round(s["cmv"] + cmv, 2)
        if taxa is None:
            s["sem_taxa"] = round(s["sem_taxa"] + receita, 2)
        else:
            s["taxas"] = round(s["taxas"] + taxa, 2)
        if frete is None:
            s["sem_frete"] = round(s["sem_frete"] + receita, 2)
        else:
            s["frete"] = round(s["frete"] + frete, 2)
        if outros is not None:
            s["outros"] = round(s["outros"] + outros, 2)
        if ads_linha:
            s["ads"] = round(s["ads"] + ads_linha, 2)
        if not s["titulo"] and v["title"]:
            s["titulo"] = str(v["title"])

        p = pedidos_detalhe.setdefault(chave, {
            "marketplace": mp, "order_id": oid, "dia": str(v["sale_day"]), "itens": [], "unidades": 0,
            "faturamento": 0.0, "cmv": 0.0, "taxa": pc.get("taxa"), "frete": pc.get("frete"),
            "outros": pc.get("outros"), "imposto": 0.0, "origem_custo_venda": pc.get("origem", ""),
            "ads": round(float(pc.get("ads_fatura") or 0.0), 2) if usa_ads_desta_linha else 0.0,
            "conciliado": bool(pc.get("conciliado")), "sem_custo": False,
            "na_fatura": bool(pc.get("na_fatura")), "taxa_venda": pc.get("taxa_venda"),
            "taxa_fatura": pc.get("taxa_fatura"), "frete_venda": pc.get("frete_venda"),
            "frete_fatura": pc.get("frete_fatura"), "divergencia_taxa": pc.get("divergencia_taxa"),
            "divergencia_frete": pc.get("divergencia_frete"),
        })
        p["unidades"] += qty
        p["faturamento"] = round(p["faturamento"] + receita, 2)
        p["imposto"] = round(p["imposto"] + imposto, 2)
        # V18.54: o anúncio (MLB) da linha — a Análise de ADS soma o lucro por anúncio.
        p["itens"].append({"sku": sku, "titulo": str(v["title"] or ""), "qty": qty, "valor": receita,
                           "custo_unitario": unit, "cmv": cmv, "anuncio": str(v["anuncio"] or "")})
        if cmv is None:
            p["sem_custo"] = True
        else:
            p["cmv"] = round(p["cmv"] + cmv, 2)

    # --- Ads -----------------------------------------------------------------
    # Pela API de Publicidade o gasto é do PERÍODO (por dia). Pela fatura ele já
    # foi somado pedido a pedido no laço acima; aqui só entra o que a fatura
    # cobrou sem vincular a um pedido.
    ads_sem_alvo = 0.0
    if ads_shopee_cpc:
        totais["ads"] = round(totais["ads"] + ads_shopee_cpc, 2)
        if "shopee" in por_mp:
            por_mp["shopee"]["ads"] = round(por_mp["shopee"]["ads"] + ads_shopee_cpc, 2)
        for dia_cpc, valor_cpc in ads_shopee_cpc_por_dia.items():
            alvo = por_dia.get(dia_cpc)
            if alvo is not None:
                alvo["ads"] = round(alvo["ads"] + valor_cpc, 2)
        ads_sem_alvo = round(ads_sem_alvo + ads_shopee_cpc, 2)
    if usar_ads_da_fatura:
        # O Ads do ML já foi somado pedido a pedido; falta o que a fatura cobrou
        # sem vincular a nenhuma venda.
        ads_sem_alvo = ads_fatura_sem_pedido
        if ads_sem_alvo:
            totais["ads"] = round(totais["ads"] + ads_sem_alvo, 2)
            if "ml" in por_mp:
                por_mp["ml"]["ads"] = round(por_mp["ml"]["ads"] + ads_sem_alvo, 2)
            # V18.37: o PADS vem sem pedido, mas COM data — dá para pôr no dia certo.
            for dia_pub, valor_pub in ((billing.get("sem_pedido") or {}).get("por_dia") or {}).items():
                alvo = por_dia.get(dia_pub)
                if alvo is not None:
                    alvo["ads"] = round(alvo["ads"] + valor_pub, 2)
    else:
        # Pela API o gasto é do período (por dia), não do pedido.
        totais["ads"] = round(totais["ads"] + ads_api_total, 2)
        if "ml" in por_mp:
            por_mp["ml"]["ads"] = round(por_mp["ml"]["ads"] + ads_api_total, 2)
        if not canal or canal == "ml":
            for dia, valor in ads["por_dia"].items():
                alvo = por_dia.get(dia)
                if alvo is not None:
                    alvo["ads"] = round(alvo["ads"] + valor, 2)
        identificado_api = 0.0
        for sku_key, valor in ads["por_sku"].items():
            alvo = por_sku.get(sku_key)
            if alvo is not None:
                alvo["ads"] = round(alvo["ads"] + valor, 2)
                identificado_api = round(identificado_api + valor, 2)
        ads_sem_alvo = round(ads_sem_alvo + max(0.0, ads_api_total - identificado_api), 2)
    ads_total = totais["ads"]
    ads_sku_usado = round(sum(s["ads"] for s in por_sku.values()), 2)

    # V19.95: perda das devoluções (peça perdida + frete), no dia em que a peça chegou. A venda cancelada já
    # saiu do faturamento; aqui entra só o que se perdeu além dela.
    devolucoes = financeiro_devolucoes(d1, d2, canal, custos_ctx)
    for dv in devolucoes:
        if not dv["perda"]:
            continue
        for alvo in (totais, por_mp.setdefault(dv["marketplace"], bloco()),
                     por_dia.setdefault(dv["dia"], {**bloco(), "dia": dv["dia"]})):
            alvo["devolucoes"] = round(alvo["devolucoes"] + dv["perda"], 2)

    def fechar(b: dict[str, Any]) -> dict[str, Any]:
        pedidos = len(b.pop("pedidos"))
        fat = round(b["faturamento"], 2)
        bruto = round(fat - b["cmv"], 2)
        liquido = round(bruto - b["taxas"] - b["frete"] - b["outros"] - b["ads"] - b["imposto"]
                        - b.get("devolucoes", 0.0), 2)
        return {**b, "faturamento": fat, "pedidos": pedidos,
                "ticket_medio": round(fat / pedidos, 2) if pedidos else 0.0,
                "lucro_bruto": bruto, "lucro_liquido": liquido,
                "margem_bruta": round(bruto / fat * 100, 2) if fat else None,
                "margem_liquida": round(liquido / fat * 100, 2) if fat else None}

    lista_sku = []
    for s in por_sku.values():
        s["pedidos"] = len(s["pedidos"])
        # V19.77: "estimado" se alguma venda do SKU não tem custo congelado; custo médio do período
        origens = s.pop("_origens", set())
        s["custo_origem"] = next((o for o in ("outra_filial", "estimado", "manual", "venda") if o in origens),
                                 s["custo_origem"])
        if not s["sem_custo"] and s["unidades"]:
            s["custo_unitario"] = round(s["cmv"] / s["unidades"], 4)
        bruto = round(s["faturamento"] - s["cmv"], 2)
        s["lucro_bruto"] = bruto
        s["lucro_liquido"] = round(bruto - s["taxas"] - s["frete"] - s["outros"] - s["ads"] - s["imposto"], 2)
        s["margem_liquida"] = round(s["lucro_liquido"] / s["faturamento"] * 100, 2) if s["faturamento"] else None
        lista_sku.append(s)
    lista_sku.sort(key=lambda x: -x["faturamento"])

    lista_pedidos = []
    for p in pedidos_detalhe.values():
        bruto = round(p["faturamento"] - p["cmv"], 2)
        p["lucro_bruto"] = bruto
        conhecidos = sum(v for v in (p["taxa"], p["frete"], p["outros"]) if v is not None) + float(p.get("ads") or 0.0)
        p["lucro_liquido"] = round(bruto - conhecidos - p["imposto"], 2) if not p["sem_custo"] else None
        p["margem_liquida"] = round(p["lucro_liquido"] / p["faturamento"] * 100, 2) if (p["lucro_liquido"] is not None and p["faturamento"]) else None
        lista_pedidos.append(p)
    lista_pedidos.sort(key=lambda x: (x["lucro_liquido"] is None, x["lucro_liquido"] if x["lucro_liquido"] is not None else 0))
    # V18.54: limite_pedidos=0 devolve todos (uso interno da Análise de ADS; a rota
    # /api/financeiro/resumo continua com o padrão de 400).
    limite = len(lista_pedidos) if limite_pedidos == 0 else max(20, min(2000, int(limite_pedidos or 400)))

    dias_lista = []
    dia_corrente = d1
    while dia_corrente <= d2:
        chave_dia = dia_corrente.isoformat()
        vazio_do_dia = {**bloco(), "dia": chave_dia}
        if not usar_ads_da_fatura and (not canal or canal == "ml"):
            vazio_do_dia["ads"] = ads["por_dia"].get(chave_dia, 0.0)
        b = por_dia.get(chave_dia) or vazio_do_dia
        dias_lista.append({"dia": chave_dia, **fechar(b)})
        dia_corrente += timedelta(days=1)

    ml_conciliados = sum(1 for o in pedidos_ml if (custos_pedido.get(("ml", o)) or {}).get("conciliado"))
    shopee_conciliados = sum(1 for o in pedidos_shopee if (custos_pedido.get(("shopee", o)) or {}).get("conciliado"))
    ml_na_fatura = sum(1 for o in pedidos_ml if (custos_pedido.get(("ml", o)) or {}).get("na_fatura"))
    # Onde a fatura discordou do que o ML mostrou na venda: é o que precisa de olho.
    divergentes = [(o, (custos_pedido.get(("ml", o)) or {}).get("divergencia_taxa")) for o in pedidos_ml]
    divergentes = [(o, d) for o, d in divergentes if d is not None and abs(d) >= 0.01]
    totais_fechados = fechar(totais)
    return {
        "ok": True,
        "periodo": {"inicio": d1.isoformat(), "fim": d2.isoformat(), "dias": (d2 - d1).days + 1},
        "marketplace": canal or "todos",
        "imposto_percent": FINANCEIRO_IMPOSTO_PERCENT,
        "totais": totais_fechados,
        "por_marketplace": {m: fechar(b) for m, b in por_mp.items()},
        "por_dia": dias_lista,
        "por_sku": lista_sku[:300],
        "pedidos": lista_pedidos[:limite],
        "pedidos_total": len(lista_pedidos),
        "ads": {"total": ads_total, "por_sku_identificado": ads_sku_usado,
                "sem_sku": ads_sem_alvo, "dias_com_dado": ads["dias_com_dado"],
                "fonte": ads_fonte, "da_fatura": round(ads_fatura_pedidos + ads_fatura_sem_pedido, 2),
                "da_api": ads_api_total, "shopee_afiliados": ads_shopee, "shopee_cpc": ads_shopee_cpc, **ads["status"]},
        "fatura_ml": {"periodos": billing["periodos"], "lancamentos": billing["lancamentos"],
                      "sem_pedido": billing["sem_pedido"]},
        "cobertura": {
            "pedidos_ml": len(pedidos_ml), "pedidos_ml_conciliados": ml_conciliados,
            "pedidos_ml_na_fatura": ml_na_fatura,
            "pedidos_ml_taxa_da_venda": max(0, ml_conciliados - ml_na_fatura),
            # V18.53: frete só da fatura = envio ainda não consultado; pode incluir a
            # parte do comprador até o worker de frete preencher o custo do envio.
            "pedidos_ml_frete_so_fatura": sum(1 for o in pedidos_ml
                                              if (custos_pedido.get(("ml", o)) or {}).get("frete_so_fatura")),
            "pedidos_shopee": len(pedidos_shopee), "pedidos_shopee_conciliados": shopee_conciliados,
            "faturamento_sem_custo": totais_fechados["sem_custo"],
            "faturamento_sem_taxa": totais_fechados["sem_taxa"],
            "faturamento_sem_frete": totais_fechados["sem_frete"],
            "divergencias": len(divergentes),
            "divergencia_total": round(sum(d for _o, d in divergentes), 2),
            "linhas": len(vendas),
            # V19.95: devoluções do período (só a partir de 01/11/2026, só Araçatuba)
            "devolucoes_qtd": len(devolucoes),
            "devolucoes_incompletas": sum(1 for dv in devolucoes if dv["incompleta"]),
            "devolucoes_a_confirmar": round(sum(dv["perda"] for dv in devolucoes if not dv["confirmada"]), 2),
            "devolucoes_inicio": DEVOLUCAO_FINANCEIRO_INICIO,
        },
    }


def financeiro_sincronizar(date_from: str, date_to: str) -> dict[str, Any]:
    """Busca o que falta para fechar o período: fatura do ML, escrow da Shopee e Ads.

    Não recalcula nada: só preenche as fontes oficiais. Pode ser chamada de novo
    — cada rodada avança um pedaço (a Shopee tem limite de chamadas).
    """
    if not FINANCEIRO_SYNC_LOCK.acquire(blocking=False):
        return {"ok": True, "em_andamento": True}
    try:
        d1 = datetime.strptime(date_from, "%Y-%m-%d").date()
        d2 = datetime.strptime(date_to, "%Y-%m-%d").date()
        if d1 > d2:
            d1, d2 = d2, d1
        resultado: dict[str, Any] = {"ok": True, "periodo": {"inicio": d1.isoformat(), "fim": d2.isoformat()}}
        # 1) Fatura do ML (mês do período + o seguinte).
        try:
            _, seller_id = ml_access_token()
        except Exception as exc:
            seller_id = ""
            resultado["ml_token"] = str(exc)[:200]
        faturas = []
        mes_atual = _ml_billing_month_key(now_iso())
        for period_key in _financeiro_periodos_fatura(d1, d2):
            for doc in ("BILL", "CREDIT_NOTE"):
                try:
                    faturas.append(_ml_billing_v1513_sync_period(period_key, doc, str(seller_id or ""),
                                                                 force=(period_key == mes_atual)))
                except Exception as exc:
                    faturas.append({"ok": False, "period_key": period_key, "document_type": doc,
                                    "status": "error", "diagnostic": str(exc)[:300]})
        resultado["fatura_ml"] = {"periodos": len(faturas),
                                  "erros": [f for f in faturas if str(f.get("status") or "") == "error"][:5]}
        # 2) Frete por conta do vendedor dos envios ainda sem valor.
        try:
            resultado["frete_ml"] = ml_frete_envio_preencher(FINANCEIRO_FRETE_POR_RODADA)
        except Exception as exc:
            resultado["frete_ml"] = {"erro": str(exc)[:200]}
        # 3) Escrow da Shopee dos pedidos do período que ainda não temos.
        with DB_LOCK:
            pendentes = [str(r["order_id"]) for r in DB.execute(
                "SELECT DISTINCT v.order_id FROM vendas_v1799 v "
                "LEFT JOIN shopee_escrow_v1810 e ON e.order_sn = v.order_id AND e.erro='' "
                "WHERE v.marketplace='shopee' AND v.sale_day BETWEEN ? AND ? AND e.order_sn IS NULL "
                "ORDER BY v.sale_day DESC", (d1.isoformat(), d2.isoformat())).fetchall()]
        buscados = 0
        for sn in pendentes[:FINANCEIRO_SHOPEE_POR_RODADA]:
            if shopee_escrow_lookup(sn):
                buscados += 1
        resultado["shopee"] = {"pendentes": len(pendentes), "buscados": buscados,
                               "faltam": max(0, len(pendentes) - buscados)}
        # 4) Publicidade.
        try:
            resultado["ads"] = ml_ads_sync_once()
        except Exception as exc:
            resultado["ads"] = {"ok": False, "erro": str(exc)[:300]}
        try:
            resultado["ads_shopee"] = shopee_ads_sync(d1, d2)
        except Exception as exc:
            resultado["ads_shopee"] = {"ok": False, "erro": str(exc)[:300]}
        return resultado
    finally:
        FINANCEIRO_SYNC_LOCK.release()


# ---------------------------------------------------------------------------
# V18.13: Agente de RELATÓRIO DIÁRIO por e-mail. Todo dia às 00:01 monta o resumo
# do dia que fechou (tudo que vendeu, de vendas_v1799) e envia por e-mail (smtplib,
# biblioteca padrão — sem dependência externa). Só leitura; não usa IA nem grava
# em dados de operação (apenas marca o último dia enviado em vendas_meta_v1799).
# Configuração toda por .env: SMTP_* e RELATORIO_EMAILS.
# ---------------------------------------------------------------------------
_RELATORIO_MP_NOME = {"ml": "Mercado Livre", "shopee": "Shopee", "magalu": "Magalu"}


def _brl_srv(v: Any) -> str:
    try:
        return "R$ " + ("%0.2f" % float(v or 0)).replace(".", "#").replace(",", ".").replace("#", ",")
    except Exception:
        return "R$ 0,00"


def _data_br(dia_iso: str) -> str:
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})", str(dia_iso or ""))
    return f"{m.group(3)}/{m.group(2)}/{m.group(1)}" if m else str(dia_iso or "")


def relatorio_diario_config() -> dict[str, Any]:
    def _flag(nome: str, padrao: str) -> bool:
        return str(os.getenv(nome, padrao)).strip().lower() not in ("0", "", "false", "nao", "não")
    return {
        "ativo": _flag("RELATORIO_DIARIO_ATIVO", "1"),
        "host": os.getenv("SMTP_HOST", "").strip(),
        "port": int(os.getenv("SMTP_PORT", "587") or "587"),
        "user": os.getenv("SMTP_USER", "").strip(),
        "senha": os.getenv("SMTP_SENHA", "").strip(),
        "remetente": (os.getenv("SMTP_FROM", "").strip() or os.getenv("SMTP_USER", "").strip()),
        "tls": _flag("SMTP_TLS", "1"),
        "destinatarios": [e.strip() for e in os.getenv("RELATORIO_EMAILS", "").split(",") if e.strip()],
    }


def relatorio_diario_dados(dia: str) -> dict[str, Any]:
    """Resumo de tudo que vendeu num dia (vendas_v1799). dia = 'YYYY-MM-DD'."""
    with DB_LOCK:
        tot = DB.execute(
            "SELECT COUNT(DISTINCT marketplace||':'||order_id) AS pedidos, "
            "COALESCE(SUM(qty),0) AS unidades, COALESCE(SUM(amount),0) AS faturamento "
            "FROM vendas_v1799 WHERE sale_day=?",
            (dia,),
        ).fetchone()
        por_mp = DB.execute(
            "SELECT marketplace, COUNT(DISTINCT order_id) AS pedidos, COALESCE(SUM(qty),0) AS unidades, "
            "COALESCE(SUM(amount),0) AS faturamento FROM vendas_v1799 WHERE sale_day=? "
            "GROUP BY marketplace ORDER BY faturamento DESC",
            (dia,),
        ).fetchall()
        linhas = DB.execute(
            "SELECT marketplace, sku, MAX(NULLIF(title,'')) AS titulo, MAX(NULLIF(anuncio,'')) AS anuncio, "
            "SUM(qty) AS qtd, SUM(amount) AS valor, COUNT(DISTINCT order_id) AS pedidos "
            "FROM vendas_v1799 WHERE sale_day=? GROUP BY marketplace, sku ORDER BY valor DESC",
            (dia,),
        ).fetchall()
    produtos = [{
        "marketplace": r["marketplace"], "sku": r["sku"] or "(sem SKU)",
        "titulo": r["titulo"] or r["anuncio"] or r["sku"] or "(sem título)",
        "qtd": int(r["qtd"] or 0), "valor": round(float(r["valor"] or 0), 2), "pedidos": int(r["pedidos"] or 0),
    } for r in linhas]
    faturamento = round(float(tot["faturamento"] or 0), 2)
    pedidos = int(tot["pedidos"] or 0)
    return {
        "dia": dia, "faturamento": faturamento, "pedidos": pedidos, "unidades": int(tot["unidades"] or 0),
        "ticket_medio": round(faturamento / pedidos, 2) if pedidos else 0.0,
        "por_marketplace": [{
            "marketplace": r["marketplace"], "nome": _RELATORIO_MP_NOME.get(r["marketplace"], r["marketplace"]),
            "pedidos": int(r["pedidos"] or 0), "unidades": int(r["unidades"] or 0),
            "faturamento": round(float(r["faturamento"] or 0), 2),
        } for r in por_mp],
        "produtos": produtos,
    }


