# V18.14: "Enviar ao comprador" da Demanda de Compra. O cálculo de quanto comprar
# é feito no navegador (junta vendas/custo do servidor com o estoque do Apollo).
# O botão manda esse pedido montado para o comprador por e-mail (mesmo SMTP do
# relatório). Um comprador para tudo, guardado em vendas_meta_v1799.
# ---------------------------------------------------------------------------
def compras_comprador_email(email: str | None = None) -> str:
    if email is not None:
        return _vendas_meta("compras_comprador_email", str(email or "").strip())
    return _vendas_meta("compras_comprador_email")


def compras_limite_transferencia(valor: Any = None) -> float:
    """V18.17 — valor mínimo (R$) para uma transferência entre casas compensar o
    frete. Global (um para tudo). Guardado em vendas_meta_v1799."""
    if valor is not None:
        try:
            v = max(0.0, float(str(valor).replace(",", ".")))
        except Exception:
            v = 0.0
        _vendas_meta("compras_limite_transferencia", str(v))
        return v
    try:
        return float(_vendas_meta("compras_limite_transferencia") or 0)
    except Exception:
        return 0.0


def compras_pedido_email_html(p: dict[str, Any]) -> str:
    def esc(s: Any) -> str:
        return html_module.escape(str(s if s is not None else ""))
    def _qtd(it: dict) -> Any:  # V18.18: aceita 'qtd' (legado) ou 'comprar'
        return it.get("qtd") if it.get("qtd") is not None else it.get("comprar")
    itens = p.get("itens") or []
    linhas = "".join(
        f"<tr style='border-top:1px solid #eef2f7'>"
        f"<td style='padding:6px 10px'><b>{esc(it.get('descricao') or it.get('codigo'))}</b>"
        f"<br><span style='color:#748295;font-size:12px'>{esc(it.get('codigo'))}</span></td>"
        f"<td style='padding:6px 10px;text-align:right'>{esc(_qtd(it))}</td>"
        f"<td style='padding:6px 10px;text-align:right'>{_brl_srv(it.get('custo'))}</td>"
        f"<td style='padding:6px 10px;text-align:right;font-weight:700'>{_brl_srv(it.get('subtotal'))}</td></tr>"
        for it in itens
    ) or "<tr><td colspan='4' style='padding:10px;color:#888'>Sem itens no pedido.</td></tr>"
    minimo = float(p.get("minimo") or 0)
    total = float(p.get("total") or 0)
    status = ("<span style='color:#16a34a;font-weight:700'>atinge o pedido mínimo</span>"
              if p.get("atingiu_minimo") else
              f"<span style='color:#d97706;font-weight:700'>faltam {_brl_srv(max(0.0, minimo - total))} para o mínimo</span>")
    # V18.18: seções de transferência (uma por casa) que evitam compra.
    transf = p.get("transferencias") or {}
    blocos_tr = ""
    for casa in ("Ribeirão", "Bauru"):
        tr_itens = transf.get(casa) or []
        if not tr_itens:
            continue
        tot_q = sum(int(i.get("qtd") or 0) for i in tr_itens)
        tot_v = sum(float(i.get("valor") or 0) for i in tr_itens)
        tr_linhas = "".join(
            f"<tr style='border-top:1px solid #eef2f7'>"
            f"<td style='padding:5px 10px'><b>{esc(i.get('descricao') or i.get('codigo'))}</b>"
            f"<br><span style='color:#748295;font-size:12px'>{esc(i.get('codigo'))}</span></td>"
            f"<td style='padding:5px 10px;text-align:right'>{esc(i.get('qtd'))}</td>"
            f"<td style='padding:5px 10px;text-align:right;font-weight:700'>{_brl_srv(i.get('valor'))}</td></tr>"
            for i in tr_itens
        )
        blocos_tr += f"""<div style="border:1px solid #e2e8f0;border-radius:12px;overflow:hidden;margin-bottom:10px">
  <div style="background:#f2ecfd;color:#6d3fc0;font-weight:800;padding:10px 14px;display:flex;justify-content:space-between">
    <span>↔ Transferir de {esc(casa)} para Araçatuba</span><span>{tot_q} peça(s) · {_brl_srv(tot_v)}</span></div>
  <table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead><tr style="background:#eef3f8;color:#6a7a8c;font-size:11px;text-transform:uppercase">
      <th style="padding:5px 10px;text-align:left">Produto</th><th style="padding:5px 10px;text-align:right">Qtd</th>
      <th style="padding:5px 10px;text-align:right">Valor</th></tr></thead>
    <tbody>{tr_linhas}</tbody></table></div>"""
    if blocos_tr:
        blocos_tr = ('<h3 style="color:#6d3fc0;margin:22px 0 10px;font-size:15px">Transferências sugeridas → Araçatuba '
                     '<span style="color:#94a3b8;font-weight:500;font-size:12px">(evitam compra)</span></h3>' + blocos_tr)
    return f"""<div style="font-family:'Segoe UI',system-ui,sans-serif;color:#1e293b;max-width:680px;margin:auto">
<h2 style="color:#123a63;margin:0 0 4px">Pedido de compra — {esc(p.get('fornecedor'))}</h2>
<p style="color:#748295;margin:0 0 14px">Sugestão gerada pela Demanda de Compra (base: últimos {esc(p.get('periodo_dias') or 60)} dias de venda).</p>
<table style="width:100%;border-collapse:collapse;margin-bottom:16px">
  <tr>
    <td style="background:#f6f9fc;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:22px;font-weight:800;color:#123a63">{_brl_srv(total)}</div><div style="font-size:12px;color:#748295">Total do pedido</div></td>
    <td style="width:8px"></td>
    <td style="background:#f6f9fc;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:22px;font-weight:800">{len(itens)}</div><div style="font-size:12px;color:#748295">Itens</div></td>
    <td style="width:8px"></td>
    <td style="background:#f6f9fc;border:1px solid #e2e8f0;border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:14px;margin-top:4px">{status}</div><div style="font-size:12px;color:#748295">Mínimo: {_brl_srv(minimo)}</div></td>
  </tr>
</table>
<table style="width:100%;border-collapse:collapse;font-size:14px">
  <thead><tr style="background:#123a63;color:#fff;font-size:11px;text-transform:uppercase">
    <th style="padding:6px 10px;text-align:left">Produto</th><th style="padding:6px 10px;text-align:right">Qtd</th>
    <th style="padding:6px 10px;text-align:right">Custo un.</th><th style="padding:6px 10px;text-align:right">Subtotal</th></tr></thead>
  <tbody>{linhas}</tbody>
</table>
{blocos_tr}
<p style="color:#94a3b8;font-size:11px;margin-top:18px">📎 A planilha completa do pedido segue em anexo (.xlsx). Enviado pelo Sistema Noromak (Demanda de Compra). Confira as quantidades antes de fechar o pedido com o fornecedor.</p>
</div>"""


def compras_pedido_email_texto(p: dict[str, Any]) -> str:
    linhas = [
        f"Pedido de compra - {p.get('fornecedor')}",
        f"Total: {_brl_srv(p.get('total'))} | Itens: {len(p.get('itens') or [])} | Minimo: {_brl_srv(p.get('minimo'))}"
        + ("  (atinge o minimo)" if p.get("atingiu_minimo") else "  (abaixo do minimo)"),
        "",
    ]
    for it in (p.get("itens") or []):
        _q = it.get("qtd") if it.get("qtd") is not None else it.get("comprar")
        linhas.append(f"  - {it.get('descricao') or it.get('codigo')} [{it.get('codigo')}] x{_q} @ {_brl_srv(it.get('custo'))} = {_brl_srv(it.get('subtotal'))}")
    if not (p.get("itens") or []):
        linhas.append("  (sem itens)")
    # V18.18: transferências sugeridas (uma seção por casa).
    transf = p.get("transferencias") or {}
    for casa in ("Ribeirão", "Bauru"):
        tr_itens = transf.get(casa) or []
        if not tr_itens:
            continue
        tot_q = sum(int(i.get("qtd") or 0) for i in tr_itens)
        tot_v = sum(float(i.get("valor") or 0) for i in tr_itens)
        linhas.append("")
        linhas.append(f"Transferir de {casa} para Aracatuba - {tot_q} peca(s) / {_brl_srv(tot_v)}:")
        for i in tr_itens:
            linhas.append(f"  - {i.get('descricao') or i.get('codigo')} [{i.get('codigo')}] x{i.get('qtd')} = {_brl_srv(i.get('valor'))}")
    return "\n".join(linhas)


def _xlsx_col(n: int) -> str:
    s = ""; n += 1
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s


def compras_pedido_xlsx(p: dict[str, Any]) -> bytes:
    """V18.18 — planilha DESENHADA do pedido de compra (.xlsx montado à mão, com
    cabeçalho colorido e seções de transferência), sem depender de biblioteca
    externa. Estilos: 1=cabeçalho navy, 2=moeda, 3=título de seção, 4=negrito."""
    import io
    import zipfile
    esc = html_module.escape

    linhas: list[list[tuple[Any, int]]] = []
    fornecedor = str(p.get("fornecedor") or "Fornecedor")
    linhas.append([(f"Pedido de compra — {fornecedor}", 4)])
    linhas.append([("Total da compra: %s   |   %s   |   base: %s dias" % (
        _brl_srv(p.get("total")),
        "atinge o mínimo" if p.get("atingiu_minimo") else "abaixo do mínimo",
        p.get("periodo_dias") or 60), 0)])
    linhas.append([])
    heads = ["Código", "Descrição", "Curva", "Vendido", "Média/dia", "Araçatuba", "Ribeirão", "Bauru",
             "A caminho", "Cobertura (dias)", "Necessidade", "Comprar", "Custo un.", "Total"]
    linhas.append([(h, 1) for h in heads])
    for it in (p.get("itens") or []):
        def n(v):
            return v if isinstance(v, (int, float)) and not isinstance(v, bool) else ("" if v is None else v)
        linhas.append([
            (it.get("codigo"), 0), (it.get("descricao"), 0), (it.get("curva"), 0),
            (n(it.get("vendido")), 0), (n(it.get("media")), 0),
            (n(it.get("araca")), 0), (n(it.get("rib")), 0), (n(it.get("bau")), 0),
            (n(it.get("caminho")), 0), (n(it.get("cobertura")), 0),
            (n(it.get("necessidade")), 0), (n(it.get("comprar")), 4),
            (n(it.get("custo")), 2), (n(it.get("subtotal")), 2),
        ])
    transf = p.get("transferencias") or {}
    for casa in ("Ribeirão", "Bauru"):
        itens = transf.get(casa) or []
        if not itens:
            continue
        tot_q = sum(int(i.get("qtd") or 0) for i in itens)
        tot_v = sum(float(i.get("valor") or 0) for i in itens)
        linhas.append([])
        linhas.append([("Transferir de %s para Araçatuba — %s peça(s) · %s" % (casa, tot_q, _brl_srv(tot_v)), 3)])
        linhas.append([(h, 1) for h in ["Código", "Descrição", "Qtd", "Valor"]])
        for i in itens:
            linhas.append([(i.get("codigo"), 0), (i.get("descricao"), 0), (int(i.get("qtd") or 0), 0), (float(i.get("valor") or 0), 2)])

    def cell(ci: int, ri: int, value: Any, style: int) -> str:
        ref = "%s%d" % (_xlsx_col(ci), ri)
        s = ' s="%d"' % style if style else ""
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            return '<c r="%s"%s><v>%s</v></c>' % (ref, s, value)
        return '<c r="%s"%s t="inlineStr"><is><t xml:space="preserve">%s</t></is></c>' % (ref, s, esc(str(value if value is not None else "")))

    rows_xml = []
    for ri, cells in enumerate(linhas, 1):
        cs = "".join(cell(ci, ri, v, st) for ci, (v, st) in enumerate(cells))
        rows_xml.append('<row r="%d">%s</row>' % (ri, cs))
    cols = "".join('<col min="%d" max="%d" width="%d" customWidth="1"/>' % (i + 1, i + 1, w)
                   for i, w in enumerate([14, 46, 7, 9, 11, 11, 10, 9, 11, 15, 12, 9, 13, 14]))
    sheet = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
             '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
             '<cols>%s</cols><sheetData>%s</sheetData></worksheet>' % (cols, "".join(rows_xml)))
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
              '<numFmts count="1"><numFmt numFmtId="164" formatCode="&quot;R$&quot;\\ #,##0.00"/></numFmts>'
              '<fonts count="3"><font><sz val="11"/><name val="Calibri"/></font>'
              '<font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Calibri"/></font>'
              '<font><b/><sz val="11"/><name val="Calibri"/></font></fonts>'
              '<fills count="4"><fill><patternFill patternType="none"/></fill>'
              '<fill><patternFill patternType="gray125"/></fill>'
              '<fill><patternFill patternType="solid"><fgColor rgb="FF123B63"/></patternFill></fill>'
              '<fill><patternFill patternType="solid"><fgColor rgb="FFF2ECFD"/></patternFill></fill></fills>'
              '<borders count="1"><border/></borders>'
              '<cellStyleXfs count="1"><xf/></cellStyleXfs>'
              '<cellXfs count="5"><xf/>'
              '<xf fontId="1" fillId="2" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>'
              '<xf numFmtId="164" applyNumberFormat="1"/>'
              '<xf fontId="2" fillId="3" applyFont="1" applyFill="1"/>'
              '<xf fontId="2" applyFont="1"/></cellXfs>'
              '<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>')
    ct = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'
          '<Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
          '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>')
    rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>')
    wb = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
          '<sheets><sheet name="Pedido" sheetId="1" r:id="rId1"/></sheets></workbook>')
    wbrels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
              '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
              '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/>'
              '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>')
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        z.writestr("[Content_Types].xml", ct)
        z.writestr("_rels/.rels", rels)
        z.writestr("xl/workbook.xml", wb)
        z.writestr("xl/_rels/workbook.xml.rels", wbrels)
        z.writestr("xl/styles.xml", styles)
        z.writestr("xl/worksheets/sheet1.xml", sheet)
    return buf.getvalue()


def compras_enviar_comprador(p: dict[str, Any]) -> dict[str, Any]:
    comprador = compras_comprador_email()
    if not comprador:
        raise RuntimeError("E-mail do comprador não configurado. Preencha na tela da Demanda de Compra.")
    fornecedor = str(p.get("fornecedor") or "").strip() or "Fornecedor"
    assunto = f"Pedido de compra — {fornecedor}: {_brl_srv(p.get('total'))} ({len(p.get('itens') or [])} itens)"
    # V18.18: a planilha DESENHADA é montada no servidor (mesmas colunas da tela +
    # seções de transferência), sem depender do XLSX cru do navegador.
    anexos: list[dict[str, Any]] = []
    try:
        conteudo = compras_pedido_xlsx(p)
        nome_seguro = re.sub(r"[^A-Za-z0-9_-]+", "_", fornecedor).strip("_") or "fornecedor"
        anexos.append({"nome": f"pedido_compra_{nome_seguro}.xlsx", "conteudo": conteudo,
                       "subtype": "vnd.openxmlformats-officedocument.spreadsheetml.sheet"})
    except Exception:
        pass  # planilha com erro não impede o e-mail do pedido
    dest = enviar_email_smtp(assunto, compras_pedido_email_texto(p), compras_pedido_email_html(p), [comprador], anexos)
    return {"ok": True, "comprador": dest, "total": p.get("total"),
            "itens": len(p.get("itens") or []), "com_planilha": bool(anexos)}


# ---------------------------------------------------------------------------
# V18.00: Demanda de Compra (versão provisória). Enquanto o Apollo não entrega a
# rota de vendas por período (PEDIDO_ROTA_DEMANDA_APOLLO.md), a demanda usa:
#   - vendas do ML e da Shopee (vendas_v1799) — não enxerga balcão/oficina;
#   - custo e curva da lista do Precificador (código = código Apollo);
#   - estoque do Apollo pela mesma rota da Demanda Full (no navegador).
# Marca não existe no cadastro: cada fornecedor é definido por regras.
# ---------------------------------------------------------------------------
def _compras_normalizar_lista(valor: Any) -> list[str]:
    if isinstance(valor, str):
        valor = re.split(r"[\n,;]+", valor)
    if not isinstance(valor, list):
        return []
    out: list[str] = []
    for item in valor:
        texto = str(item or "").strip().upper()
        if texto and texto not in out:
            out.append(texto)
    return out[:2000]


def compras_fornecedor_config(body: dict[str, Any]) -> dict[str, Any]:
    def numero(chave: str, padrao: float, minimo: float, maximo: float) -> float:
        try:
            return max(minimo, min(maximo, float(body.get(chave, padrao))))
        except (TypeError, ValueError):
            return padrao
    return {
        "pedido_minimo": round(numero("pedido_minimo", 0, 0, 10_000_000), 2),
        "prazo": int(numero("prazo", 7, 0, 365)),
        "cobertura": int(numero("cobertura", 30, 0, 365)),
        "prefixos": _compras_normalizar_lista(body.get("prefixos")),
        "palavras": _compras_normalizar_lista(body.get("palavras")),
        "codigos": _compras_normalizar_lista(body.get("codigos")),
    }


def compras_fornecedores() -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("SELECT nome, config, updated_at, updated_by FROM compras_fornecedores_v1800 ORDER BY nome").fetchall()
    out = []
    for r in rows:
        try:
            cfg = json.loads(r["config"] or "{}")
        except Exception:
            cfg = {}
        out.append({"nome": r["nome"], **compras_fornecedor_config(cfg), "atualizado_em": r["updated_at"], "atualizado_por": r["updated_by"]})
    return out


def compras_salvar_fornecedor(nome: str, body: dict[str, Any], usuario: str) -> dict[str, Any]:
    nome = re.sub(r"\s+", " ", str(nome or "").strip().upper())[:80]
    if not nome:
        raise ValueError("Informe o nome do fornecedor/marca.")
    cfg = compras_fornecedor_config(body)
    if not (cfg["prefixos"] or cfg["palavras"] or cfg["codigos"]):
        raise ValueError("Informe ao menos uma regra: começo do código, palavra na descrição ou lista de códigos.")
    with DB_LOCK:
        DB.execute(
            "INSERT INTO compras_fornecedores_v1800(nome,config,updated_at,updated_by) VALUES(?,?,?,?) "
            "ON CONFLICT(nome) DO UPDATE SET config=excluded.config, updated_at=excluded.updated_at, updated_by=excluded.updated_by",
            (nome, json.dumps(cfg, ensure_ascii=False), now_iso(), usuario),
        )
        DB.commit()
    return {"nome": nome, **cfg}


def compras_excluir_fornecedor(nome: str) -> None:
    with DB_LOCK:
        DB.execute("DELETE FROM compras_fornecedores_v1800 WHERE nome=?", (str(nome or "").strip().upper(),))
        DB.commit()


def custos_registrar_auto(itens: list[tuple[str, float]], origem: str) -> None:
    """V18.07: guarda o último custo > 0 visto de cada código (nunca grava zero)."""
    linhas = []
    agora = now_iso()
    for codigo, custo in itens:
        codigo = str(codigo or "").strip().upper()
        try:
            valor = float(custo)
        except (TypeError, ValueError):
            continue
        if codigo and valor > 0:
            linhas.append((codigo, round(valor, 4), origem, agora))
    if not linhas:
        return
    with DB_LOCK:
        DB.executemany(
            "INSERT INTO custos_conhecidos_v1807(codigo,custo_auto,origem_auto,data_auto) VALUES(?,?,?,?) "
            "ON CONFLICT(codigo) DO UPDATE SET custo_auto=excluded.custo_auto, origem_auto=excluded.origem_auto, "
            "data_auto=excluded.data_auto",
            linhas,
        )
        DB.commit()


CUSTO_APOLLO_PROMO_DIAS = 30


def custo_apollo_registrar(codigo: Any, custos_filiais: list[dict[str, Any]], custo_topo: Any = None) -> None:
    """V19.31: guarda o custo > 0 de cada filial lido agora do Apollo (só filial com cadastro).
    Leitura sem nenhum custo > 0 (estoque zerado) não apaga a anterior."""
    codigo = str(codigo or "").strip().upper()
    custos: dict[str, float] = {}
    for c in custos_filiais or []:
        try:
            rev, valor = int(c.get("revenda") or 0), float(c.get("custo_medio") or 0)
        except (TypeError, ValueError, AttributeError):
            continue
        if rev > 0 and valor > 0 and c.get("tem_cadastro") is not False:
            custos[str(rev)] = round(valor, 4)
    if not codigo or not custos:
        return
    with DB_LOCK:
        DB.execute("INSERT INTO custo_apollo_v1931(codigo,custos_json,data) VALUES(?,?,?) "
                   "ON CONFLICT(codigo) DO UPDATE SET custos_json=excluded.custos_json, data=excluded.data",
                   (codigo, json.dumps(custos), now_iso()))
        DB.commit()


def _custos_apollo_recentes(dias: int = CUSTO_APOLLO_PROMO_DIAS) -> dict[str, dict[int, float]]:
    """V19.31: código -> {revenda: custo} das leituras do Apollo dos últimos `dias`."""
    limite = datetime.now(timezone.utc) - timedelta(days=dias)
    out: dict[str, dict[int, float]] = {}
    with DB_LOCK:
        linhas = DB.execute("SELECT codigo, custos_json, data FROM custo_apollo_v1931").fetchall()
    for r in linhas:
        try:
            quando = datetime.fromisoformat(str(r["data"]).replace("Z", "+00:00"))
            if quando.tzinfo is None:
                quando = quando.replace(tzinfo=timezone.utc)
            if quando < limite:
                continue
            out[r["codigo"]] = {int(k): float(v) for k, v in (json.loads(r["custos_json"] or "{}") or {}).items()}
        except (TypeError, ValueError):
            continue
    return out


def custo_manual_salvar(codigo: str, custo: Any, usuario: str) -> dict[str, Any]:
    """V18.07: custo digitado na Demanda de Compra. Vazio/0 apaga."""
    codigo = str(codigo or "").strip().upper()
    if not codigo:
        raise ValueError("Informe o código da peça.")
    valor = None
    if str(custo if custo is not None else "").strip():
        # Aceita "152,52" e "1.234,56", como é digitado no Brasil.
        valor = float(custo) if isinstance(custo, (int, float)) else _apollo_number(custo)
        if valor is None or valor < 0 or valor > 10_000_000:
            raise ValueError("Custo inválido.")
    valor = round(valor, 4) if valor else None
    with DB_LOCK:
        DB.execute(
            "INSERT INTO custos_conhecidos_v1807(codigo,custo_manual,data_manual,manual_por) VALUES(?,?,?,?) "
            "ON CONFLICT(codigo) DO UPDATE SET custo_manual=excluded.custo_manual, data_manual=excluded.data_manual, "
            "manual_por=excluded.manual_por",
            (codigo, valor, now_iso() if valor else "", usuario if valor else ""),
        )
        DB.commit()
    return {"codigo": codigo, "custo_manual": valor}


def _compras_custos_reserva(conhecidos: dict[str, Any]) -> dict[str, dict[str, Any]]:
    """Custos de reserva por código: manual, último custo visto e custo gravado na
    venda do ML (rentabilidade), cada um com a data."""
    out: dict[str, dict[str, Any]] = {}
    with DB_LOCK:
        for r in DB.execute("SELECT * FROM custos_conhecidos_v1807").fetchall():
            out[r["codigo"]] = {"manual": r["custo_manual"], "data_manual": r["data_manual"], "manual_por": r["manual_por"],
                                "auto": r["custo_auto"], "origem_auto": r["origem_auto"], "data_auto": r["data_auto"]}
        vendas = DB.execute(
            "SELECT sku, unit_cost, captured_at FROM ml_profitability_snapshot WHERE unit_cost > 0 ORDER BY captured_at"
        ).fetchall()
    for r in vendas:
        codigo = _compras_codigo(str(r["sku"] or ""), conhecidos)
        if codigo:
            alvo = out.setdefault(codigo, {})
            alvo["venda"] = r["unit_cost"]
            alvo["data_venda"] = r["captured_at"]
    return out


def _compras_resolver_custo(atual: float | None, reserva: dict[str, Any]) -> tuple[float | None, str, str]:
    """(custo, origem, data). O custo médio atual do Apollo manda; sem ele, vale o
    digitado, depois o último custo visto, depois o custo da última venda no ML."""
    if atual:
        return atual, "apollo", ""
    if reserva.get("manual"):
        return float(reserva["manual"]), "manual", reserva.get("data_manual") or ""
    candidatos = []
    if reserva.get("auto"):
        candidatos.append((reserva.get("data_auto") or "", float(reserva["auto"]), "ultimo"))
    if reserva.get("venda"):
        candidatos.append((reserva.get("data_venda") or "", float(reserva["venda"]), "venda"))
    if candidatos:
        data, custo, origem = max(candidatos)
        return custo, origem, data
    return None, "", ""


# ---------------------------------------------------------------------------
# V18.23: Promoções do Mercado Livre dentro do Precificador.
#
# Levantamento feito na API real em 23/09/2026 (conta 224625106):
#   GET  /seller-promotions/users/{id}      -> campanhas oferecidas ao vendedor
#   GET  /seller-promotions/items/{MLB}     -> o que se aplica ao anúncio, com
#        original_price, suggested_discounted_price e o PISO/TETO do próprio ML
#        (min_discounted_price / max_discounted_price)
#   POST /seller-promotions/items/{MLB}     -> aplica (deal_price + datas)
#   DELETE /seller-promotions/items/{MLB}   -> remove
#
# O tipo que a Noromak usa é PRICE_DISCOUNT (desconto próprio): em 23/09 havia
# 8 promoções ativas, todas de 29-30 dias. A documentação fala em "máximo 14
# dias", mas a conta real contradiz — mandamos a data que o dono escolher e
# deixamos o ML recusar se for o caso, em vez de inventar um limite.
# ---------------------------------------------------------------------------
ML_PROMO_TIPO = "PRICE_DISCOUNT"


def _ml_promo_http(method: str, path: str, payload: dict[str, Any] | None = None,
                   timeout: float | None = None) -> Any:
    """Chamada JSON à API de promoções. A ml_http_json() manda form-urlencoded,
    que esta API não aceita no POST. V20.24: `timeout` opcional (o Publicar dos anuncios usa 90 s);
    sem ele, o ML_HTTP_TIMEOUT de sempre."""
    url = ML_API_BASE + path
    espera = timeout if timeout else ML_HTTP_TIMEOUT

    def chamar(token: str) -> Any:
        body = json_dumps(payload).encode("utf-8") if payload is not None else None
        headers = {
            "Accept": "application/json",
            "Authorization": "Bearer " + token,
            "User-Agent": f"NoromakExpedicao/{APP_VERSION}",
        }
        if body is not None:
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=body, headers=headers, method=method.upper())
        with urllib.request.urlopen(req, timeout=espera) as resp:
            texto = resp.read().decode("utf-8", "replace").strip()
            return json.loads(texto) if texto else {}

    token, _ = ml_access_token()
    try:
        return chamar(token)
    except urllib.error.HTTPError as exc:
        if exc.code == 401:
            token, _ = ml_access_token(force_refresh=True)
            return chamar(token)
        detalhe = ""
        try:
            detalhe = exc.read().decode("utf-8", "replace")[:20000]
        except Exception:
            pass
        erro = RuntimeError(f"Mercado Livre respondeu HTTP {exc.code}: {detalhe[:400]}")
        # V20.24: o Publicar dos anuncios le o status e o corpo inteiro (as causas da recusa passam de 400 caracteres).
        erro.ml_status = exc.code  # type: ignore[attr-defined]
        erro.ml_corpo = detalhe  # type: ignore[attr-defined]
        raise erro from exc


def ml_promocoes_do_item(mlb: str) -> list[dict[str, Any]]:
    mlb = str(mlb or "").strip().upper()
    if not mlb.startswith("MLB"):
        mlb = "MLB" + re.sub(r"\D", "", mlb)
    try:
        dados = _ml_promo_http("GET", f"/seller-promotions/items/{mlb}?app_version=v2")
    except RuntimeError as exc:
        if "HTTP 404" in str(exc):
            return []   # anúncio sem promoção disponível
        raise
    if isinstance(dados, list):
        return [x for x in dados if isinstance(x, dict)]
    resultados = dados.get("results") if isinstance(dados, dict) else None
    if isinstance(resultados, list):
        return [x for x in resultados if isinstance(x, dict)]
    return [dados] if isinstance(dados, dict) and dados else []


def _precificador_produtos_ml() -> dict[str, dict[str, Any]]:
    """SKU -> custo/imposto e as taxas do ML, como o Precificador já calcula."""
    dados = precificador_dados()   # V19.65
    out: dict[str, dict[str, Any]] = {}
    for p in (dados.get("products") if isinstance(dados, dict) else None) or []:
        if not isinstance(p, dict) or p.get("isKit"):
            continue
        sku = str(p.get("sku") or "").strip().upper()
        if not sku or sku in out:
            continue
        ml = (p.get("marketplaces") or {}).get("ml") or {}
        custo = _money_number(p.get("custo")) or 0.0
        out[sku] = {
            "sku": sku,
            "produto": str(p.get("produto") or "").strip(),
            "curva": normalize_abc_curve_value(p.get("curva")) or "",
            "custo": float(custo),
            "imposto": float(p.get("imposto") or 0),
            "comissao": float(ml.get("comissao") or 0),
            "taxa_fixa": float(ml.get("taxaFixa") or 0) + float(ml.get("frete") or 0),
            "margem_alvo": float(ml.get("margem") or 0.15),
        }
    return out


def promo_conta(prod: dict[str, Any], preco: float) -> dict[str, Any]:
    """Mesma conta do Precificador: preço − comissão − taxa − imposto − custo."""
    preco = float(preco or 0)
    comissao = preco * prod["comissao"]
    imposto = preco * prod["imposto"]
    lucro = preco - comissao - prod["taxa_fixa"] - imposto - prod["custo"]
    return {
        "preco": round(preco, 2), "comissao": round(comissao, 2), "imposto": round(imposto, 2),
        "taxa_fixa": round(prod["taxa_fixa"], 2), "custo": round(prod["custo"], 2),
        "lucro": round(lucro, 2), "margem": round(lucro / preco, 4) if preco > 0 else 0.0,
    }


def promo_preco_minimo(prod: dict[str, Any]) -> float | None:
    """Preço em que o lucro é zero. Abaixo disso é vender no prejuízo."""
    divisor = 1 - prod["comissao"] - prod["imposto"]
    if divisor <= 0 or prod["custo"] <= 0:
        return None
    return round((prod["custo"] + prod["taxa_fixa"]) / divisor, 2)


def promo_preco_ideal(prod: dict[str, Any]) -> float | None:
    divisor = 1 - prod["comissao"] - prod["imposto"] - prod["margem_alvo"]
    if divisor <= 0 or prod["custo"] <= 0:
        return None
    return round((prod["custo"] + prod["taxa_fixa"]) / divisor, 2)


def precificador_produto_ml_atualizar(sku: Any, campos: dict[str, Any], ator: str) -> dict[str, Any]:
    """V18.77: a gaveta de preço das Promoções automáticas edita custo e taxas do ML de UM
    produto do Precificador. Grava só os campos daquele produto, pelo merge do
    precificador_online_v1 (lê -> altera -> save_storage com o lido), como a atualização
    pelo Apollo: quem estiver editando outro produto no Precificador não perde nada.
    Frações (0,12 = 12%). "Taxa fixa / frete" é a soma das duas: o frete fica e a taxa
    fixa absorve a diferença. Kit: o custo vem dos componentes e não é editado aqui."""
    sku = str(sku or "").strip().upper()
    if not sku:
        return {"ok": False, "error": "SKU não informado."}

    def numero(nome: str, minimo: float, maximo: float, aberto: bool = False) -> float | None:
        if campos.get(nome) is None or campos.get(nome) == "":
            return None
        try:
            v = float(str(campos[nome]).replace(",", "."))
        except (TypeError, ValueError):
            raise ValueError(f"Valor inválido em {nome}.")
        if v != v or v < minimo or v > maximo or (aberto and v <= minimo):
            raise ValueError(f"Valor fora do permitido em {nome}.")
        return round(v, 4)

    try:
        custo = numero("custo", 0.0, 1e7, aberto=True)
        taxa = numero("taxa_fixa", 0.0, 1e5)
        comissao = numero("comissao", 0.0, 0.9)
        imposto = numero("imposto", 0.0, 0.9)
        margem = numero("margem", 0.0, 0.9)
    except ValueError as exc:
        return {"ok": False, "error": str(exc)}
    # V18.77: custo puxado do Apollo na gaveta — guarda a filial e os custos por filial
    # no mesmo formato que o Precificador grava depois de consultar o Apollo.
    filial = campos.get("filial_custo")
    try:
        filial = int(filial) if filial not in (None, "") else None
    except (TypeError, ValueError):
        return {"ok": False, "error": "Filial do custo inválida."}
    if filial is not None and not 1 <= filial <= 99:
        return {"ok": False, "error": "Filial do custo inválida."}
    filiais = None
    if isinstance(campos.get("custos_filiais"), list):
        filiais = []
        for row in campos["custos_filiais"][:20]:
            if not isinstance(row, dict):
                continue
            try:
                revenda = int(row.get("revenda"))
            except (TypeError, ValueError):
                continue
            cm = _money_number(row.get("custo_medio"))
            tc = row.get("tem_cadastro")
            filiais.append({"revenda": revenda, "casa": str(row.get("casa") or "")[:40],
                            "custo_medio": round(cm, 2) if cm is not None else None,
                            "tem_cadastro": tc if isinstance(tc, bool) else None,
                            "erro": str(row["erro"])[:200] if row.get("erro") else None})
    raw, _, _ = get_storage("precificador_online_v1")
    try:
        dados = json.loads(raw or "{}")
    except Exception:
        dados = {}
    produtos = dados.get("products") if isinstance(dados, dict) else None
    prod = next((x for x in produtos or [] if isinstance(x, dict)
                 and str(x.get("sku") or "").strip().upper() == sku), None)
    if not prod:
        return {"ok": False, "error": f"O SKU {sku} não está no Precificador: cadastre lá primeiro."}
    if custo is not None and prod.get("isKit"):
        return {"ok": False, "error": "Kit: o custo vem dos componentes, altere no Precificador."}
    mp = prod.get("marketplaces") if isinstance(prod.get("marketplaces"), dict) else {}
    ml = dict(mp.get("ml") or {})
    if comissao is not None:
        ml["comissao"] = comissao
    if margem is not None:
        ml["margem"] = margem
    if taxa is not None:
        frete = float(ml.get("frete") or 0)
        if frete > taxa:
            ml["frete"] = 0
            frete = 0.0
        ml["taxaFixa"] = round(taxa - frete, 2)
    soma = (ml.get("comissao") or 0) + (imposto if imposto is not None else float(prod.get("imposto") or 0)) \
        + (ml.get("margem") or 0)
    if soma >= 1:
        return {"ok": False, "error": "Comissão + imposto + margem chegam a 100%: não existe preço possível."}
    if custo is not None:
        prod["custo"] = round(custo, 2)
    if filial is not None:
        prod["filialCusto"] = filial
    if filiais is not None:
        prod["custosFiliais"] = filiais
    if imposto is not None:
        prod["imposto"] = imposto
    prod["marketplaces"] = dict(mp, ml=ml)
    prod["updatedAt"] = now_iso()
    dados["products"] = produtos
    save_storage("precificador_online_v1", raw, json_dumps(dados), False,
                 actor=ator or "sistema", actor_role="admin",
                 source_screen="promocoes-auto", change_method="promocoes.auto.custo")
    audit(ator or "sistema", "precificador.produto.promocoes",
          f"{sku}|custo={custo}|filial={filial}|taxa={taxa}|comissao={comissao}|imposto={imposto}|margem={margem}")
    return {"ok": True, "sku": sku}


_ML_TARIFA_CACHE: dict[tuple[Any, ...], tuple[float, Any]] = {}
_ML_TARIFA_CACHE_LOCK = threading.Lock()
# A renovação confere os marcados de hora em hora: 3 h de cache evita repetir as mesmas
# chamadas a cada rodada. Comissão é por tipo+categoria (anúncios iguais dividem a consulta).
ML_TARIFA_CACHE_SEGUNDOS = 3 * 3600


def _ml_tarifa_cache(chave: tuple[Any, ...], buscar: Any) -> Any:
    agora = time.time()
    with _ML_TARIFA_CACHE_LOCK:
        hit = _ML_TARIFA_CACHE.get(chave)
        if hit and agora - hit[0] < ML_TARIFA_CACHE_SEGUNDOS:
            return hit[1]
    valor = buscar()
    with _ML_TARIFA_CACHE_LOCK:
        if len(_ML_TARIFA_CACHE) > 5000:
            _ML_TARIFA_CACHE.clear()
        _ML_TARIFA_CACHE[chave] = (agora, valor)
    return valor


def ml_tarifa_frete_anuncio(mlb: Any, preco: Any = None, *, tipo: str = "", categoria: str = "") -> dict[str, Any]:
    """V18.77: comissão, taxa fixa e frete do ANÚNCIO, direto do ML. Só leitura.

    Teste real em 08/10/2026 (6 anúncios): /sites/MLB/listing_prices e
    /users/{seller}/shipping_options/free bateram centavo a centavo com a tarifa e o
    frete cobrados nas vendas. A comissão depende da categoria (13% em algumas, não 12%)
    e a taxa fixa veio 0 em todas as faixas: o anúncio barato paga FRETE.
    O que o ML não devolver fica None (nunca zero) e vai em `erros`.
    `tipo`/`categoria` já lidos (ml_itens_detalhe) evitam a chamada a /items."""
    mlb = _mlb_normalizar(mlb)
    if not mlb:
        raise ValueError("Anúncio (MLB) inválido.")
    try:
        preco_f = round(float(str(preco).replace(",", ".")), 2) if preco not in (None, "") else None
    except (TypeError, ValueError):
        raise ValueError("Preço inválido.")
    item: dict[str, Any] = {}
    if not tipo or not categoria or not preco_f:
        bruto = _ml_tarifa_cache(("item", mlb), lambda: ml_api_get(
            f"/items/{mlb}?attributes=id,price,listing_type_id,category_id,shipping"))
        item = bruto if isinstance(bruto, dict) else {}
        tipo = tipo or str(item.get("listing_type_id") or "")
        categoria = categoria or str(item.get("category_id") or "")
        preco_f = preco_f or _money_number(item.get("price"))
    if not tipo or not categoria or not preco_f:
        raise ValueError("O Mercado Livre não devolveu tipo, categoria ou preço do anúncio.")
    ship = item.get("shipping") if isinstance(item.get("shipping"), dict) else {}
    out: dict[str, Any] = {"ok": True, "mlb": mlb, "preco": preco_f, "tipo": tipo, "categoria": categoria,
                           "logistica": str(ship.get("logistic_type") or ""), "frete_gratis": bool(ship.get("free_shipping")),
                           "comissao": None, "taxa_fixa": None, "tarifa": None, "frete": None, "erros": []}
    try:
        q = urlencode({"price": preco_f, "listing_type_id": tipo, "category_id": categoria})
        lp = _ml_tarifa_cache(("taxa", tipo, categoria, preco_f), lambda: ml_api_get(f"/sites/MLB/listing_prices?{q}"))
        lp = lp[0] if isinstance(lp, list) and lp else lp
        det = (lp or {}).get("sale_fee_details") or {}
        pct = _money_number(det.get("percentage_fee"))
        out["comissao"] = round(pct / 100.0, 4) if pct is not None else None
        out["taxa_fixa"] = _money_number(det.get("fixed_fee"))
        out["tarifa"] = _money_number((lp or {}).get("sale_fee_amount"))
    except Exception as exc:
        out["erros"].append(f"tarifa: {exc}")
    try:
        seller = str((ml_integration_row() or {})["seller_id"] or "")
        fr = _ml_tarifa_cache(("frete", mlb), lambda: ml_api_get(
            f"/users/{seller}/shipping_options/free?item_id={mlb}")) if seller else {}
        cov = (((fr or {}).get("coverage") or {}).get("all_country") or {}) if isinstance(fr, dict) else {}
        out["frete"] = _money_number(cov.get("list_cost"))
    except Exception as exc:
        out["erros"].append(f"frete: {exc}")
    return out


# V20.24: leituras do ML para CRIAR anuncio (so GET): categoria, atributos obrigatorios e tarifa.
ANUNCIO_CAMPO_DO_ATRIBUTO: dict[str, str] = {
    "BRAND": "marca", "MODEL": "modelo", "GTIN": "ean", "SELLER_PACKAGE_WEIGHT": "peso_g",
    "SELLER_PACKAGE_HEIGHT": "altura_cm", "SELLER_PACKAGE_WIDTH": "largura_cm",
    "SELLER_PACKAGE_LENGTH": "comprimento_cm", "SELLER_SKU": "codigo",
}
ANUNCIO_ATRIBUTOS_CACHE_S = 24 * 3600
_ANUNCIO_ATRIBUTOS_CACHE: dict[tuple[str, str], tuple[float, dict[str, Any]]] = {}
_ANUNCIO_ATRIBUTOS_LOCK = threading.Lock()
ANUNCIO_FRETE_TEXTO = "o ML informa o frete depois de publicar"


def _anuncio_amostra(tipo: str, resposta: Any) -> None:
    """V20.24: guarda a 1a resposta real de cada chamada (so se ainda nao existe), cortada em 6.000."""
    try:
        texto = json.dumps(resposta, ensure_ascii=False, default=str)[:6000]
        with DB_LOCK:
            DB.execute("INSERT OR IGNORE INTO anuncio_amostra_v2024(tipo,resposta,criado_em) VALUES(?,?,?)",
                       (str(tipo), texto, now_iso()))
            DB.commit()
    except Exception:
        pass  # amostra e so apoio: nunca derruba a leitura


def ml_categoria_sugerir(titulo: str, conta: str) -> list[dict[str, Any]]:
    titulo = str(titulo or "").strip()
    if not titulo:
        raise ValueError("Informe o título do anúncio.")
    with ml_na_casa(conta):
        bruto = ml_api_get("/sites/MLB/domain_discovery/search?" + urlencode({"limit": 5, "q": titulo[:120]}))
    _anuncio_amostra("domain_discovery", bruto)
    saida = []
    for it in (bruto if isinstance(bruto, list) else []):
        if not isinstance(it, dict) or not it.get("category_id"):
            continue
        saida.append({"categoria": str(it.get("category_id")), "categoria_nome": str(it.get("category_name") or ""),
                      "dominio": str(it.get("domain_id") or ""), "dominio_nome": str(it.get("domain_name") or "")})
    return saida


def ml_categoria_atributos(categoria: str, conta: str) -> dict[str, Any]:
    categoria = str(categoria or "").strip().upper()
    if not re.fullmatch(r"MLB\d{1,12}", categoria):
        raise ValueError("Categoria inválida.")
    agora = time.time()
    chave = (conta, categoria)
    with _ANUNCIO_ATRIBUTOS_LOCK:
        hit = _ANUNCIO_ATRIBUTOS_CACHE.get(chave)
        if hit and agora - hit[0] < ANUNCIO_ATRIBUTOS_CACHE_S:
            return hit[1]
    with ml_na_casa(conta):
        cat = ml_api_get(f"/categories/{categoria}")
        attrs = ml_api_get(f"/categories/{categoria}/attributes")
    _anuncio_amostra("categoria_atributos", {"categoria": cat, "atributos": attrs})
    caminho = [str(p.get("name") or "") for p in ((cat or {}).get("path_from_root") or []) if isinstance(p, dict)] \
        if isinstance(cat, dict) else []
    lista = []
    for a in (attrs if isinstance(attrs, list) else []):
        if not isinstance(a, dict) or not a.get("id"):
            continue
        tags = a.get("tags") if isinstance(a.get("tags"), dict) else {}
        if tags.get("hidden") or tags.get("read_only") or tags.get("fixed"):
            continue
        lista.append({
            "id": str(a["id"]), "nome": str(a.get("name") or a["id"]),
            "obrigatorio": bool(tags.get("required") or tags.get("catalog_required")),
            "condicional": bool(tags.get("conditional_required")),
            "tipo": str(a.get("value_type") or ""),
            "valores": [{"id": str(v.get("id") or ""), "nome": str(v.get("name") or "")}
                        for v in (a.get("values") or []) if isinstance(v, dict)][:200],
            "unidades": [{"id": str(u.get("id") or ""), "nome": str(u.get("name") or "")}
                         for u in (a.get("allowed_units") or []) if isinstance(u, dict)],
            "max": a.get("value_max_length"), "dica": str(a.get("hint") or a.get("tooltip") or ""),
        })
    res = {"categoria": categoria, "nome": str((cat or {}).get("name") or "") if isinstance(cat, dict) else "",
           "caminho": caminho, "atributos": lista}
    with _ANUNCIO_ATRIBUTOS_LOCK:
        if len(_ANUNCIO_ATRIBUTOS_CACHE) > 500:
            _ANUNCIO_ATRIBUTOS_CACHE.clear()
        _ANUNCIO_ATRIBUTOS_CACHE[chave] = (agora, res)
    return res


def _anuncio_numero_texto(valor: Any, unidade: str) -> str | None:
    try:
        n = float(str(valor).replace(",", "."))
    except (TypeError, ValueError):
        return None
    if n <= 0:
        return None
    return f"{int(n) if n == int(n) else round(n, 2)} {unidade}"


def anuncio_atributos_da_ficha(ficha: dict[str, Any], atributos: list[dict[str, Any]]) -> dict[str, Any]:
    """V20.24 (pura): valores da ficha para os atributos da categoria. SELLER_SKU e as medidas do pacote vao
    sempre que a ficha tem (o ML aceita em qualquer categoria); marca/modelo/GTIN so se a categoria os lista."""
    campos = ficha.get("campos") if isinstance(ficha.get("campos"), dict) else ficha
    ids = {str(a.get("id")) for a in (atributos or []) if isinstance(a, dict)}
    saida: dict[str, Any] = {}
    for attr_id, campo in ANUNCIO_CAMPO_DO_ATRIBUTO.items():
        if campo == "codigo":
            valor: Any = str(ficha.get("codigo") or "").strip()
        elif campo == "peso_g":
            valor = _anuncio_numero_texto(campos.get(campo), "g")
        elif campo.endswith("_cm"):
            valor = _anuncio_numero_texto(campos.get(campo), "cm")
        else:
            valor = str(campos.get(campo) or "").strip()
        if not valor:
            continue
        sempre = campo in ("codigo", "peso_g", "altura_cm", "largura_cm", "comprimento_cm")
        if sempre or attr_id in ids:
            saida[attr_id] = valor
    if str(ficha.get("tipo") or "") == "kit" and "GTIN" not in saida and "EMPTY_GTIN_REASON" in ids:
        # V20.24 (revisao): os valores do ML sao frases ("O produto e um kit ou pack"); vale o nome exato do UNICO
        # valor que fala de kit. Nenhum (ou mais de um) = fica vazio para o Admin escolher - nunca o texto "Kit".
        motivo = next((a for a in atributos if isinstance(a, dict) and str(a.get("id")) == "EMPTY_GTIN_REASON"), {})
        de_kit = [v for v in motivo.get("valores") or []
                  if isinstance(v, dict) and v.get("id") and "kit" in _anuncio_sem_acento(v.get("nome"))]
        if len(de_kit) == 1:
            saida["EMPTY_GTIN_REASON"] = str(de_kit[0].get("nome"))
    return saida


# V20.24: rascunho do anuncio (um por tentativa de publicar; varios por ficha/conta). So o Publicar (Task 5) escreve no ML.
ANUNCIO_RASCUNHO_EDITAVEL = ("rascunho", "validado", "erro")
ANUNCIO_TIPOS_LISTAGEM = ("gold_special", "gold_pro", "free")
ANUNCIO_RASCUNHO_CAMPOS = ("titulo", "categoria", "descricao", "preco", "tipo_anuncio", "frete_gratis", "garantia",
                           "quantidade")


def _anuncio_rascunho_de_linha(row: Any) -> dict[str, Any]:
    def _j(texto: Any, padrao: Any) -> Any:
        try:
            v = json.loads(texto or "")
        except (TypeError, ValueError):
            return padrao
        return v if isinstance(v, type(padrao)) else padrao

    d = dict(row)
    d["atributos"] = _j(d.pop("atributos_json", ""), {})
    d["fotos"] = _j(d.pop("fotos_json", ""), [])
    d["erros"] = _j(d.pop("erros_json", ""), [])
    if d.get("frete_gratis") is not None:
        d["frete_gratis"] = bool(d["frete_gratis"])
    return d


def anuncio_rascunho_ler(rid: Any) -> dict[str, Any] | None:
    try:
        n = int(rid)
    except (TypeError, ValueError):
        return None
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (n,)).fetchone()
    return _anuncio_rascunho_de_linha(row) if row else None


def anuncio_rascunhos(codigo: str) -> list[dict[str, Any]]:
    cod = normalize(codigo)
    if not cod:
        return []
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE ficha_codigo=? ORDER BY id DESC", (cod,)).fetchall()
    return [_anuncio_rascunho_de_linha(r) for r in rows]


def _anuncio_rascunho_limpar(dados: dict[str, Any]) -> dict[str, Any]:
    """V20.24 (pura): so as chaves enviadas, ja validadas e normalizadas. Vazio/desconhecido = None (nunca zero)."""
    out: dict[str, Any] = {}

    def _vazio(v: Any) -> bool:
        return v is None or (isinstance(v, str) and not v.strip())

    if "titulo" in dados:
        t = " ".join(str(dados["titulo"] or "").split())
        if len(t) > 60:
            raise ValueError("O título do Mercado Livre aceita até 60 caracteres.")
        out["titulo"] = t
    if "categoria" in dados:
        c = str(dados["categoria"] or "").strip().upper()
        if c and not re.fullmatch(r"MLB\d{1,12}", c):
            raise ValueError("Categoria inválida.")
        out["categoria"] = c
    if "descricao" in dados:
        d = str(dados["descricao"] or "").strip()
        if len(d) > 50000:
            raise ValueError("Descrição grande demais.")
        out["descricao"] = d
    if "garantia" in dados:
        g = str(dados["garantia"] or "").strip()
        if len(g) > 100:
            raise ValueError("Garantia: até 100 caracteres.")
        out["garantia"] = g
    if "preco" in dados:
        if _vazio(dados["preco"]):
            out["preco"] = None
        else:
            try:
                p = float(str(dados["preco"]).replace(",", "."))
            except (TypeError, ValueError):
                p = 0.0
            if isinstance(dados["preco"], bool) or not math.isfinite(p) or p <= 0:
                raise ValueError("Preço: informe um número maior que zero ou deixe vazio.")
            out["preco"] = round(p, 2)
    if "quantidade" in dados:
        if _vazio(dados["quantidade"]):
            out["quantidade"] = None
        else:
            try:
                q = float(str(dados["quantidade"]).replace(",", "."))
            except (TypeError, ValueError):
                q = 0.0
            if isinstance(dados["quantidade"], bool) or not math.isfinite(q) or q < 1 or q != int(q) or q > 1000000:
                raise ValueError("Quantidade: informe um número inteiro maior que zero ou deixe vazio.")
            out["quantidade"] = int(q)
    if "tipo_anuncio" in dados:
        tp = str(dados["tipo_anuncio"] or "").strip() or "gold_special"
        if tp not in ANUNCIO_TIPOS_LISTAGEM:
            raise ValueError("Tipo de anúncio inválido.")
        out["tipo_anuncio"] = tp
    if "frete_gratis" in dados:
        f = dados["frete_gratis"]
        if f is None or f == "":
            out["frete_gratis"] = None
        elif isinstance(f, bool):
            out["frete_gratis"] = f
        elif str(f).strip().lower() in ("1", "true", "sim"):
            out["frete_gratis"] = True
        elif str(f).strip().lower() in ("0", "false", "nao", "não"):
            out["frete_gratis"] = False
        else:
            raise ValueError("Frete grátis inválido.")
    if "atributos" in dados:
        a = dados["atributos"]
        if not isinstance(a, dict):
            raise ValueError("Atributos inválidos.")
        limpos: dict[str, str] = {}
        for k, v in a.items():
            k = str(k or "").strip()
            if not k or k == "_guardados":
                continue
            if len(k) > 80:
                raise ValueError("Atributo inválido.")
            if isinstance(v, (dict, list)):
                raise ValueError(f"Atributo {k}: informe um texto.")
            v = "" if v is None else str(v).strip()
            if len(v) > 1000:
                raise ValueError(f"Atributo {k}: texto grande demais.")
            if v:
                limpos[k] = v
        out["atributos"] = limpos
    if "fotos" in dados:
        f = dados["fotos"]
        if not isinstance(f, list):
            raise ValueError("Fotos inválidas.")
        ids: list[int] = []
        for x in f:
            try:
                n = int(x)
            except (TypeError, ValueError):
                raise ValueError("Foto inválida.")
            if isinstance(x, bool):
                raise ValueError("Foto inválida.")
            if n not in ids:
                ids.append(n)
        if len(ids) > 12:
            raise ValueError("O Mercado Livre aceita até 12 fotos.")
        out["fotos"] = ids
    return out


def anuncio_rascunho_salvar(dados: dict[str, Any], ator: str, versao: int | None) -> dict[str, Any]:
    """V20.24: cria (sem `id`) ou atualiza (com `id`; `versao` conferida, senao FichaConflito).
    Ordem: sem titulo nao aceita categoria; sem categoria nao aceita atributos. Trocar a categoria mantem so os
    atributos que ela tem e guarda o resto em `_guardados` (volta se a categoria anterior voltar)."""
    dados = dados if isinstance(dados, dict) else {}
    rid = dados.get("id")
    pre = None
    if rid not in (None, ""):
        pre = anuncio_rascunho_ler(rid)
        if pre is None:
            raise ValueError("Rascunho não encontrado.")
    limpos = _anuncio_rascunho_limpar(dados)
    cod = ""
    conta = ""
    if pre is None:
        cod = normalize(dados.get("codigo"))
        conta = str(dados.get("conta") or "").strip()
        if not cod:
            raise ValueError("Informe o código do produto.")
        if not conta:
            raise ValueError("Informe a conta do Mercado Livre.")
        if ficha_ler(cod) is None:
            raise ValueError("Produto não encontrado.")
    else:
        cod, conta = pre["ficha_codigo"], pre["conta"]
    # V20.24: atributos da categoria nova lidos FORA do DB_LOCK (usa o cache de 24 h); sem resposta do ML a troca
    # e recusada com tudo como estava - nunca adivinha quais atributos valem.
    ids_nova: set[str] | None = None
    if "categoria" in limpos and limpos["categoria"] and limpos["categoria"] != ((pre or {}).get("categoria") or ""):
        try:
            defs = ml_categoria_atributos(limpos["categoria"], conta)
        except RuntimeError as exc:
            raise ValueError(f"Não consegui ler os atributos da categoria no Mercado Livre ({exc}). Nada foi alterado.")
        ids_nova = {str(a.get("id")) for a in defs.get("atributos") or [] if isinstance(a, dict)}
    with DB_LOCK:
        atual = None
        if pre is not None:
            row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (pre["id"],)).fetchone()
            if row is None:
                raise ValueError("Rascunho não encontrado.")
            atual = _anuncio_rascunho_de_linha(row)
            if versao is None or int(versao) != atual["versao"]:
                raise FichaConflito(atual)
            if atual["situacao"] not in ANUNCIO_RASCUNHO_EDITAVEL:
                raise ValueError("Este rascunho já foi publicado ou está em publicação; não pode mais ser editado.")
        base = atual or {"titulo": "", "categoria": "", "descricao": "", "preco": None, "tipo_anuncio": "gold_special",
                         "frete_gratis": None, "garantia": "", "quantidade": None, "atributos": {}, "fotos": []}
        attrs = dict(base.get("atributos") or {})
        guard = attrs.pop("_guardados", None)
        guard = dict(guard) if isinstance(guard, dict) else {}
        novo = {k: base.get(k) for k in ANUNCIO_RASCUNHO_CAMPOS}
        for k in ANUNCIO_RASCUNHO_CAMPOS:
            if k in limpos:
                novo[k] = limpos[k]
        cat_antiga = str(base.get("categoria") or "")
        cat_nova = str(novo.get("categoria") or "")
        if cat_nova != cat_antiga:
            if cat_nova and ids_nova is None:  # mudou entre a leitura e o lock: recarregar e tentar de novo
                raise FichaConflito(atual or {})
            if cat_antiga:
                mantidos = {k: v for k, v in attrs.items() if ids_nova is not None and k in ids_nova}
                tirados = {k: v for k, v in attrs.items() if k not in mantidos}
                if tirados:
                    guard[cat_antiga] = {**(guard.get(cat_antiga) or {}), **tirados}
                attrs = mantidos
            if cat_nova and isinstance(guard.get(cat_nova), dict):
                sobra: dict[str, Any] = {}
                for k, v in guard.pop(cat_nova).items():
                    if ids_nova is not None and k in ids_nova:
                        attrs.setdefault(k, v)
                    else:
                        sobra[k] = v
                if sobra:
                    guard[cat_nova] = sobra
        if "atributos" in limpos:
            attrs = dict(limpos["atributos"])
        fotos = list(limpos["fotos"]) if "fotos" in limpos else list(base.get("fotos") or [])
        if not str(novo.get("titulo") or "").strip() and cat_nova:
            raise ValueError("Informe o título antes de escolher a categoria.")
        if attrs and not cat_nova:
            raise ValueError("Escolha a categoria antes de preencher os atributos.")
        if "fotos" in limpos and fotos:
            marcas = ",".join("?" * len(fotos))
            achadas = {int(r["id"]) for r in DB.execute(
                f"SELECT id FROM anuncio_foto_v2024 WHERE ficha_codigo=? AND id IN ({marcas})", (cod, *fotos))}
            if achadas != set(fotos):
                raise ValueError("Há foto que não pertence a este produto.")
        attrs_gravar = dict(attrs)
        if guard:
            attrs_gravar["_guardados"] = guard
        agora = now_iso()
        frete = None if novo["frete_gratis"] is None else (1 if novo["frete_gratis"] else 0)
        if atual is None:
            cur = DB.execute(
                "INSERT INTO anuncio_rascunho_v2024(ficha_codigo,conta,titulo,categoria,atributos_json,fotos_json,descricao,"
                "preco,tipo_anuncio,frete_gratis,garantia,quantidade,situacao,versao,criado_em,criado_por,atualizado_em,"
                "atualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'rascunho',1,?,?,?,?)",
                (cod, conta, novo["titulo"], cat_nova, json.dumps(attrs_gravar, ensure_ascii=False),
                 json.dumps(fotos), novo["descricao"], novo["preco"], novo["tipo_anuncio"] or "gold_special", frete,
                 novo["garantia"], novo["quantidade"], agora, str(ator or ""), agora, str(ator or "")))
            DB.commit()
            rid_novo = cur.lastrowid
        else:
            mudou = (any(novo[k] != base.get(k) for k in ANUNCIO_RASCUNHO_CAMPOS) or fotos != list(base.get("fotos") or [])
                     or attrs_gravar != (base.get("atributos") or {}))
            if not mudou:
                return atual
            situacao = "rascunho" if atual["situacao"] == "validado" else atual["situacao"]
            DB.execute(
                "UPDATE anuncio_rascunho_v2024 SET titulo=?,categoria=?,atributos_json=?,fotos_json=?,descricao=?,preco=?,"
                "tipo_anuncio=?,frete_gratis=?,garantia=?,quantidade=?,situacao=?,versao=versao+1,atualizado_em=?,"
                "atualizado_por=? WHERE id=?",
                (novo["titulo"], cat_nova, json.dumps(attrs_gravar, ensure_ascii=False), json.dumps(fotos),
                 novo["descricao"], novo["preco"], novo["tipo_anuncio"] or "gold_special", frete, novo["garantia"],
                 novo["quantidade"], situacao, agora, str(ator or ""), atual["id"]))
            DB.commit()
            rid_novo = atual["id"]
        row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid_novo,)).fetchone()
        return _anuncio_rascunho_de_linha(row)


def _anuncio_sem_acento(texto: Any) -> str:
    t = unicodedata.normalize("NFKD", str(texto or ""))
    return "".join(c for c in t if not unicodedata.combining(c)).strip().casefold()


def anuncio_item_corpo(rascunho: dict[str, Any], picture_ids: list[str],
                       atributos_def: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    """V20.24 (pura): corpo do POST /items. `atributos_def` = lista `atributos` de ml_categoria_atributos: atributo
    com lista de valores cujo texto bate (sem caixa/acento) com um deles vai como value_id (ex.: EMPTY_GTIN_REASON
    "Kit"); os demais, como value_name. Atributo vazio nao vai."""
    defs = {str(a.get("id")): a for a in (atributos_def or []) if isinstance(a, dict)}
    atributos = []
    so_da_lista = ("EMPTY_GTIN_REASON",)  # V20.24 (revisao): so aceita valor da lista; texto livre nao vai
    for attr_id, valor in (rascunho.get("atributos") or {}).items():
        if attr_id == "_guardados" or valor is None or not str(valor).strip():
            continue
        texto = str(valor).strip()
        value_id = None
        for v in (defs.get(attr_id) or {}).get("valores") or []:
            if isinstance(v, dict) and v.get("id") and _anuncio_sem_acento(v.get("nome")) == _anuncio_sem_acento(texto):
                value_id = str(v["id"])
                break
        if not value_id and attr_id in so_da_lista:
            continue
        atributos.append({"id": attr_id, "value_id": value_id} if value_id else {"id": attr_id, "value_name": texto})
    corpo: dict[str, Any] = {
        "title": rascunho.get("titulo"), "category_id": rascunho.get("categoria"), "price": rascunho.get("preco"),
        "currency_id": "BRL", "available_quantity": rascunho.get("quantidade"), "buying_mode": "buy_it_now",
        "listing_type_id": rascunho.get("tipo_anuncio") or "gold_special", "condition": "new",
        "pictures": [{"id": str(p)} for p in (picture_ids or [])],
        "attributes": atributos,
        "sale_terms": [],
        "shipping": {"mode": "me2", "free_shipping": bool(rascunho.get("frete_gratis"))},
    }
    garantia = anuncio_garantia_texto(rascunho.get("garantia"))
    if garantia:
        corpo["sale_terms"] = [{"id": "WARRANTY_TYPE", "value_name": "Garantia do vendedor"},
                               {"id": "WARRANTY_TIME", "value_name": garantia}]
    return corpo


ANUNCIO_GARANTIA_UNIDADE = {"dia": "dias", "dias": "dias", "mes": "meses", "meses": "meses", "ano": "anos",
                            "anos": "anos"}


def anuncio_garantia_texto(texto: Any) -> str | None:
    """V20.24 (revisao, pura): "<n> dias|meses|anos" -> "N dias"/"N meses"/"N anos". Outro texto = None (a garantia
    nao vai ao ML: sem a lista de valores do WARRANTY_TYPE offline, so o formato que o ML le com certeza)."""
    m = re.fullmatch(r"(\d{1,4})\s*([a-z]+)", _anuncio_sem_acento(" ".join(str(texto or "").split())))
    if not m or int(m.group(1)) <= 0 or m.group(2) not in ANUNCIO_GARANTIA_UNIDADE:
        return None
    return f"{int(m.group(1))} {ANUNCIO_GARANTIA_UNIDADE[m.group(2)]}"


def ml_tarifa_nova(preco: float, tipo: str, categoria: str, conta: str) -> dict[str, Any]:
    """V20.24: tarifa de um anuncio que ainda nao existe (so listing_prices). Frete = None: sem MLB nao ha cotacao."""
    try:
        preco_f = round(float(str(preco).replace(",", ".")), 2)
    except (TypeError, ValueError):
        raise ValueError("Preço inválido.")
    tipo = str(tipo or "").strip()
    categoria = str(categoria or "").strip().upper()
    if preco_f <= 0 or not tipo or not re.fullmatch(r"MLB\d{1,12}", categoria):
        raise ValueError("Informe preço, tipo de anúncio e categoria.")
    q = urlencode({"price": preco_f, "listing_type_id": tipo, "category_id": categoria})

    def _ler() -> Any:
        with ml_na_casa(conta):
            return ml_api_get(f"/sites/MLB/listing_prices?{q}")

    lp = _ml_tarifa_cache(("taxa_nova", conta, tipo, categoria, preco_f), _ler)
    _anuncio_amostra("listing_prices", lp)
    lp = lp[0] if isinstance(lp, list) and lp else lp
    lp = lp if isinstance(lp, dict) else {}
    det = lp.get("sale_fee_details") if isinstance(lp.get("sale_fee_details"), dict) else {}
    pct = _money_number(det.get("percentage_fee"))
    return {"comissao": round(pct / 100.0, 4) if pct is not None else None,
            "taxa_fixa": _money_number(det.get("fixed_fee")),
            "tarifa": _money_number(lp.get("sale_fee_amount")),
            "frete": None, "frete_texto": ANUNCIO_FRETE_TEXTO}


ANUNCIO_CUSTO_ORIGEM = {"apollo": "custo de Araçatuba no Apollo", "manual": "custo digitado (Demanda de Compra)",
                        "ultimo": "último custo de Araçatuba visto", "venda": "custo da última venda no ML"}


def _anuncio_custo_aracatuba(cod: str) -> dict[str, Any]:
    """V20.24 (revisao): {custo, custo_origem} pela regra de Aracatuba (compras_custo_aracatuba)."""
    ctx = _financeiro_custos_aracatuba()
    conhecidos = ctx["conhecidos"]
    comp = kit_composicao(cod)
    if comp:
        total, origens = 0.0, []
        for c in comp["componentes"]:
            peca = _compras_codigo(str(c["sku"]), conhecidos) or normalize(c["sku"])
            custo, origem, _ = compras_custo_aracatuba(peca, ctx)
            if not custo or custo <= 0:
                return {"custo": None, "custo_origem": f"sem custo de Araçatuba da peça {c['sku']}"}
            total += float(custo) * int(c["quantidade"])
            origens.append(origem)
        nomes = sorted({ANUNCIO_CUSTO_ORIGEM.get(o, o) for o in origens})
        return {"custo": round(total, 2), "custo_origem": "soma das peças do kit (" + "; ".join(nomes) + ")"}
    custo, origem, _ = compras_custo_aracatuba(_compras_codigo(cod, conhecidos) or cod, ctx)
    if not custo or custo <= 0:
        return {"custo": None, "custo_origem": "sem custo de Araçatuba"}
    return {"custo": round(float(custo), 2), "custo_origem": ANUNCIO_CUSTO_ORIGEM.get(origem, origem)}


def anuncio_custo_para_preco(codigo: str) -> dict[str, Any]:
    """V20.24: custo, imposto e margem-alvo para a conta do preco na tela de criar anuncio (so le).
    Revisao: custo = regra de Aracatuba (V19.77/V19.79, a do Financeiro e da Demanda) para as DUAS contas - a
    planilha antiga sem leitura do Apollo nao vale; kit = soma das pecas x quantidade do Cadastro de Kits (peca sem
    custo = kit sem custo). Desconhecido = None (sem custo nao ha lucro nem preco ideal - nunca zero); `custo_origem`
    diz de onde veio. Margem-alvo do Precificador (Promocoes). Imposto fixo do Financeiro."""
    out: dict[str, Any] = {"custo": None, "custo_origem": "sem custo de Araçatuba", "margem_alvo": None,
                           "imposto": round(FINANCEIRO_IMPOSTO_PERCENT / 100.0, 4)}
    cod = normalize(codigo)
    try:
        out.update(_anuncio_custo_aracatuba(cod))
    except Exception as exc:
        print(f"Aviso: custo de Aracatuba nao lido para {codigo}: {exc}", file=sys.stderr)
    try:
        prod = _promo_produto(_promo_produtos(), cod)
    except Exception as exc:
        print(f"Aviso: margem-alvo do Precificador nao lida para {codigo}: {exc}", file=sys.stderr)
        prod = None
    if prod:
        try:
            alvo = float(prod.get("margem_alvo"))
        except (TypeError, ValueError):
            alvo = None
        out["margem_alvo"] = alvo if alvo is not None and 0 <= alvo < 0.9 else None
    return out


# ---------------------------------------------------------------------------
# V20.24: Conferir no ML e Publicar - a UNICA escrita no Mercado Livre da plataforma de anuncios.
# Maquina do rascunho: rascunho/erro -(validar)-> validado -(publicar)-> publicando -> publicado | erro | incerto.
# - So `validado` publica, e a troca para `publicando` e feita sob o DB_LOCK (WHERE situacao='validado'):
#   dois cliques/duas abas criam UM anuncio. Alem disso a rota pega ANUNCIOS_PUBLICAR_LOCK sem esperar (409).
# - Tudo que falha ANTES do POST /items (token, Apollo, quantidade, foto) volta a `validado` com o erro: nada criado.
# - ML recusou o POST /items (4xx) = `erro` (nada criado). Sem resposta (rede, timeout, 5xx, resposta sem id)
#   = `incerto`: o ML pode ter criado, NUNCA repete sozinho; o Admin confere no ML e libera (com ou sem MLB).
# - Nunca fica preso em `publicando`: try/finally no processo e, no boot, `publicando` vira `incerto`.
# ---------------------------------------------------------------------------
ANUNCIOS_PUBLICAR_LOCK = threading.Lock()
ANUNCIO_VALIDAVEL = ("rascunho", "erro", "validado")
ANUNCIO_FOTO_UPLOAD_TIMEOUT = max(ML_HTTP_TIMEOUT, 60)  # foto de ate 10 MB
ANUNCIO_ITEM_TIMEOUT = 90  # V20.24 (revisao): POST /items e a descricao (o ML demora a criar; 20 s virava `incerto`)
ANUNCIO_INCERTO_TEXTO = ("O Mercado Livre não respondeu ao criar o anúncio: ele pode ter sido criado. Confira no ML "
                         "(Meus anúncios) e informe o MLB, ou libere sem MLB se ele não existe. Nada é repetido sozinho.")
ANUNCIO_FOTO_MIME = {"image/jpeg": "jpg", "image/png": "png", "image/webp": "webp"}


class AnuncioMLSemResposta(Exception):
    """V20.24: sem resposta (rede, timeout, 5xx, resposta ilegivel): o ML PODE ter feito."""


class AnuncioMLRecusou(Exception):
    """V20.24: o ML respondeu com recusa (4xx) ou a chamada nem saiu (token): nada foi feito no ML."""

    def __init__(self, mensagem: str, status: int | None = None, corpo: Any = None) -> None:
        super().__init__(mensagem)
        self.status = status
        self.corpo = corpo


def _anuncio_json_ou_none(texto: Any) -> Any:
    try:
        return json.loads(str(texto or ""))
    except (TypeError, ValueError):
        return None


def _anuncio_ml_chamar(method: str, path: str, payload: dict[str, Any] | None, timeout: float | None = None) -> Any:
    """V20.24: _ml_promo_http com a falha classificada. Chamar dentro de ml_na_casa(conta)."""
    try:
        if timeout:  # V20.24 (revisao): o POST /items e o da descricao levam mais que 20 s
            return _ml_promo_http(method, path, payload, timeout=timeout)
        return _ml_promo_http(method, path, payload)
    except RuntimeError as exc:
        status = getattr(exc, "ml_status", None)
        corpo_txt = getattr(exc, "ml_corpo", None)
        if status is None:
            m = re.match(r"Mercado Livre respondeu HTTP (\d{3}): ?(.*)\Z", str(exc), re.S)
            if m:
                status, corpo_txt = int(m.group(1)), m.group(2)
        # V20.24 (revisao): 408 = o ML desistiu de esperar o pedido; pode ter criado: incerto, como 5xx.
        # 429 continua recusa (o ML nao processou).
        if status is not None and (int(status) >= 500 or int(status) == 408):
            raise AnuncioMLSemResposta(str(exc)) from exc
        # status None = RuntimeError do token (a chamada nem saiu)
        raise AnuncioMLRecusou(str(exc), status, _anuncio_json_ou_none(corpo_txt)) from exc
    except urllib.error.HTTPError as exc:  # a 2a tentativa depois do 401 escapa sem embrulho
        try:
            corpo_txt = exc.read().decode("utf-8", "replace")[:20000]
        except Exception:
            corpo_txt = ""
        msg = f"Mercado Livre respondeu HTTP {exc.code}: {corpo_txt[:400]}"
        if exc.code >= 500 or exc.code == 408:  # V20.24 (revisao): 408 = incerto
            raise AnuncioMLSemResposta(msg) from exc
        raise AnuncioMLRecusou(msg, exc.code, _anuncio_json_ou_none(corpo_txt)) from exc
    except Exception as exc:  # URLError, timeout, conexao caida, JSON ilegivel de um 2xx...
        raise AnuncioMLSemResposta(f"{type(exc).__name__}: {exc}") from exc


def _anuncio_causas_ml(corpo: Any, ignorar_fotos: bool) -> tuple[list[str], int]:
    """V20.24: (mensagens das causas de erro, quantas causas de erro havia antes de tirar as de foto).
    Aviso (`type` warning) nao trava. A foto e conferida aqui (>= 1 foto); a validacao vai sem foto."""
    causas = corpo.get("cause") if isinstance(corpo, dict) else None
    out: list[str] = []
    total = 0
    for c in causas if isinstance(causas, list) else []:
        if isinstance(c, str):
            total += 1
            if not (ignorar_fotos and "picture" in c.lower()):
                out.append(c)
            continue
        if not isinstance(c, dict) or str(c.get("type") or "error").lower() != "error":
            continue
        total += 1
        codigo = str(c.get("code") or "")
        refs = " ".join(str(x) for x in (c.get("references") or []) if x is not None)
        msg = str(c.get("message") or "").strip()
        if ignorar_fotos and "picture" in f"{codigo} {refs} {msg}".lower():
            continue
        out.append(f"{msg} ({codigo})" if msg and codigo else (msg or codigo or "Recusado pelo Mercado Livre."))
    return out, total


def _anuncio_mensagens_ml(exc: AnuncioMLRecusou, ignorar_fotos: bool = False) -> list[str]:
    causas, _ = _anuncio_causas_ml(exc.corpo, ignorar_fotos)
    if causas:
        return causas
    corpo = exc.corpo if isinstance(exc.corpo, dict) else {}
    return [str(corpo.get("message") or "").strip() or str(exc)]


def _anuncio_causa_titulo(corpo: Any) -> bool:
    """V20.24: a recusa e a da categoria do modelo novo (User Products), que pede family_name no lugar do title.
    Revisao: so `family_name`/`user_product` na causa; recusa comum do titulo (tamanho, palavra proibida) nao repete."""
    if not isinstance(corpo, dict):
        return False
    partes = [str(corpo.get("message") or "")]
    for c in corpo.get("cause") if isinstance(corpo.get("cause"), list) else []:
        if isinstance(c, dict):
            partes += [str(c.get("code") or ""), " ".join(str(x) for x in (c.get("references") or [])),
                       str(c.get("message") or "")]
        else:
            partes.append(str(c))
    texto = " ".join(partes).lower()
    return "family_name" in texto or "user_product" in texto or "user product" in texto


def _anuncio_corpo_family(corpo: dict[str, Any], titulo: Any) -> dict[str, Any]:
    """V20.24 (revisao): o mesmo corpo com family_name no lugar do title (categoria User Products)."""
    novo = {k: v for k, v in corpo.items() if k != "title"}
    novo["family_name"] = titulo
    return novo


def _anuncio_erros_duas_tentativas(primeira: list[str], segunda: list[str]) -> list[str]:
    """V20.24 (revisao): as duas recusas (com title e com family_name), sem repetir a mesma mensagem."""
    return list(dict.fromkeys(list(primeira) + [f"Com family_name: {e}" for e in segunda if e not in primeira]))


def _ml_foto_upload(dados: bytes, tipo: str) -> str:
    """V20.24: sobe uma foto (multipart, campo `file`) com o token da casa atual; devolve o id da foto no ML."""
    mime = tipo if tipo in ANUNCIO_FOTO_MIME else {v: k for k, v in ANUNCIO_FOTO_MIME.items()}.get(tipo)
    if not mime or not dados:
        raise ValueError("Foto inválida.")
    limite = "----NoromakFoto" + secrets.token_hex(12)
    corpo = (f"--{limite}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"foto.{ANUNCIO_FOTO_MIME[mime]}\""
             f"\r\nContent-Type: {mime}\r\n\r\n").encode("ascii") + dados + f"\r\n--{limite}--\r\n".encode("ascii")

    def chamar(token: str) -> Any:
        req = urllib.request.Request(ML_API_BASE + "/pictures/items/upload", data=corpo, method="POST", headers={
            "Accept": "application/json", "Authorization": "Bearer " + token,
            "Content-Type": f"multipart/form-data; boundary={limite}",
            "User-Agent": f"NoromakExpedicao/{APP_VERSION}"})
        with urllib.request.urlopen(req, timeout=ANUNCIO_FOTO_UPLOAD_TIMEOUT) as resp:
            texto = resp.read().decode("utf-8", "replace").strip()
            return json.loads(texto) if texto else {}

    def recusa(exc: urllib.error.HTTPError) -> RuntimeError:
        try:
            detalhe = exc.read().decode("utf-8", "replace")[:400]
        except Exception:
            detalhe = ""
        return RuntimeError(f"Mercado Livre recusou a foto (HTTP {exc.code}): {detalhe}")

    token, _ = ml_access_token()
    try:
        resp = chamar(token)
    except urllib.error.HTTPError as exc:
        if exc.code != 401:
            raise recusa(exc) from exc
        token, _ = ml_access_token(force_refresh=True)
        try:
            resp = chamar(token)
        except urllib.error.HTTPError as exc2:
            raise recusa(exc2) from exc2
    _anuncio_amostra("foto_upload", resp)
    fid = str((resp or {}).get("id") or "").strip() if isinstance(resp, dict) else ""
    if not fid:
        raise RuntimeError("O Mercado Livre não devolveu o número da foto.")
    return fid


def _anuncio_conferir_local(r: dict[str, Any]) -> tuple[list[str], list[dict[str, Any]] | None]:
    """V20.24: o que o Noromak confere sem o ML (titulo, categoria, obrigatorios, >= 1 foto, preco, quantidade).
    Le os atributos da categoria (cache de 24 h) - chamar FORA do DB_LOCK. Devolve (erros, atributos da categoria)."""
    erros: list[str] = []
    if not str(r.get("titulo") or "").strip():
        erros.append("Informe o título do anúncio.")
    if not r.get("preco") or float(r["preco"]) <= 0:
        erros.append("Informe o preço (maior que zero).")
    if not r.get("quantidade") or int(r["quantidade"]) < 1:
        erros.append("Informe a quantidade (1 ou mais).")
    fotos = [int(f) for f in (r.get("fotos") or [])]
    if not fotos:
        erros.append("Escolha ao menos uma foto.")
    else:
        with DB_LOCK:
            achadas = {int(x["id"]) for x in DB.execute(
                f"SELECT id FROM anuncio_foto_v2024 WHERE ficha_codigo=? AND id IN ({','.join('?' * len(fotos))})",
                (r.get("ficha_codigo"), *fotos))}
        if achadas != set(fotos):
            erros.append("Há foto escolhida que foi apagada da ficha; escolha as fotos de novo.")
    defs: list[dict[str, Any]] | None = None
    cat = str(r.get("categoria") or "").strip()
    if not cat:
        erros.append("Escolha a categoria.")
    else:
        try:
            defs = list(ml_categoria_atributos(cat, str(r.get("conta") or "")).get("atributos") or [])
        except Exception as exc:
            erros.append(f"Não consegui ler os atributos da categoria no Mercado Livre ({exc}).")
        if defs is not None:
            valores = r.get("atributos") or {}
            faltam = [str(a.get("nome") or a.get("id")) for a in defs
                      if a.get("obrigatorio") and not str(valores.get(str(a.get("id"))) or "").strip()]
            if faltam:
                erros.append("Preencha os atributos obrigatórios: " + ", ".join(faltam) + ".")
    return erros, defs


def _anuncio_rascunho_trocar(rid: int, de: tuple[str, ...], para: str, erros: list[str], ator: str,
                             versao: int | None = None, mlb: str | None = None,
                             usa_family_name: int | None = None) -> dict[str, Any] | None:
    """V20.24: troca a situacao so se ela ainda e uma de `de` (e a versao bate, quando dada). Chamar SEM o DB_LOCK.
    None = o rascunho mudou no meio (nada gravado)."""
    with DB_LOCK:
        marcas = ",".join("?" * len(de))
        sql = (f"UPDATE anuncio_rascunho_v2024 SET situacao=?, erros_json=?, mlb=COALESCE(?,mlb), "
               f"usa_family_name=COALESCE(?,usa_family_name), versao=versao+1, "
               f"atualizado_em=?, atualizado_por=? WHERE id=? AND situacao IN ({marcas})")
        args: list[Any] = [para, json.dumps(list(erros), ensure_ascii=False), mlb, usa_family_name, now_iso(),
                           str(ator or ""), rid, *de]
        if versao is not None:
            sql += " AND versao=?"
            args.append(int(versao))
        cur = DB.execute(sql, args)
        DB.commit()
        if cur.rowcount != 1:
            return None
        row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid,)).fetchone()
    return _anuncio_rascunho_de_linha(row)


def _anuncio_canal_noromak(conta: str, mlb: str, r: dict[str, Any], ator: str,
                           resp: dict[str, Any] | None = None) -> None:
    """V20.24: anuncio criado pelo Noromak entra na lista como `noromak`. Chamar SOB o DB_LOCK (sem commit).
    Linha que ja existia (a puxada leu antes) passa a `noromak`; removido pelo ADMIN continua removido."""
    resp = resp if isinstance(resp, dict) else {}
    preco = _money_number(resp.get("price"))
    try:
        estoque = int(resp["available_quantity"]) if resp.get("available_quantity") is not None else None
    except (TypeError, ValueError):
        estoque = None
    agora = now_iso()
    DB.execute(
        "INSERT INTO anuncio_canal_v2023(canal,conta,anuncio_id,ficha_codigo,sku_anuncio,controle,titulo,preco,estoque,"
        "status,tipo_anuncio,categoria,user_product_id,lido_em,controle_em,controle_por) "
        "VALUES('ml',?,?,?,?,'noromak',?,?,?,?,?,?,?,?,?,?) "
        "ON CONFLICT(canal,conta,anuncio_id) DO UPDATE SET ficha_codigo=excluded.ficha_codigo,controle='noromak',"
        "controle_em=excluded.controle_em,controle_por=excluded.controle_por,"
        "titulo=COALESCE(NULLIF(titulo,''),excluded.titulo),preco=COALESCE(preco,excluded.preco),"
        "estoque=COALESCE(estoque,excluded.estoque)",
        (conta, mlb, r["ficha_codigo"], r["ficha_codigo"], str(resp.get("title") or r.get("titulo") or ""),
         preco if preco is not None else r.get("preco"),
         estoque if estoque is not None else r.get("quantidade"), str(resp.get("status") or ""),
         str(resp.get("listing_type_id") or r.get("tipo_anuncio") or ""),
         str(resp.get("category_id") or r.get("categoria") or ""), str(resp.get("user_product_id") or ""),
         agora, agora, str(ator or "")))


def _anuncio_mlb(valor: Any) -> str:
    t = str(valor or "").strip().upper().replace("-", "")
    if re.fullmatch(r"\d{6,15}", t):
        t = "MLB" + t
    return t if re.fullmatch(r"MLB\d{6,15}", t) else ""


def anuncio_validar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.24: confere localmente e no POST /items/validate (sem subir foto: pictures vazio, causas de foto
    ignoradas). Certo = `validado`; errado = `rascunho` com os erros. Nao cria nada no ML."""
    r = anuncio_rascunho_ler(rascunho_id)
    if r is None:
        raise ValueError("Rascunho não encontrado.")
    if r["situacao"] not in ANUNCIO_VALIDAVEL:
        raise ValueError("Este rascunho já foi publicado, está em publicação ou aguarda conferência no ML.")
    erros, defs = _anuncio_conferir_local(r)
    usa_family = 0
    if not erros:
        corpo = anuncio_item_corpo(r, [], defs)
        primeira: list[str] = []
        # V20.24 (revisao): categoria User Products recusa o title e pede family_name - a mesma troca unica do
        # Publicar, e o corpo aceito fica lembrado (usa_family_name) para o Publicar mandar ele primeiro.
        for tentativa in (1, 2):
            try:
                with ml_na_casa(r["conta"]):
                    resp = _anuncio_ml_chamar("POST", "/items/validate", corpo)
                _anuncio_amostra("validate", {"status": "ok", "resposta": resp})
                erros = []
                break
            except AnuncioMLRecusou as exc:
                _anuncio_amostra("validate", {"status": exc.status, "resposta": exc.corpo or str(exc)})
                causas, total = _anuncio_causas_ml(exc.corpo, ignorar_fotos=True)
                if exc.status == 400 and total and not causas:  # so causas de foto = conferido
                    erros = []
                    break
                erros = causas or _anuncio_mensagens_ml(exc, ignorar_fotos=True)
                if tentativa == 1 and "title" in corpo and _anuncio_causa_titulo(exc.corpo):
                    primeira = erros
                    corpo = _anuncio_corpo_family(corpo, r.get("titulo"))
                    usa_family = 1
                    continue
                if primeira:
                    erros = _anuncio_erros_duas_tentativas(primeira, erros)
                break
            except AnuncioMLSemResposta as exc:
                erros = [f"O Mercado Livre não respondeu à conferência ({exc}). Tente de novo."]
                break
    novo = _anuncio_rascunho_trocar(r["id"], ANUNCIO_VALIDAVEL, "rascunho" if erros else "validado", erros, ator,
                                    versao=r["versao"], usa_family_name=0 if erros else usa_family)
    if novo is None:
        atual = anuncio_rascunho_ler(r["id"])
        raise FichaConflito(atual or {})
    audit(ator, "anuncios.validar", f"{r['ficha_codigo']}|{r['id']}|{r['conta']}|{novo['situacao']}")
    return {"ok": not erros, "situacao": novo["situacao"], "erros": erros, "rascunho": novo}


def anuncio_publicar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.24: cria o anuncio no ML. A rota segura ANUNCIOS_PUBLICAR_LOCK; aqui a maquina de situacao garante
    um anuncio por rascunho mesmo assim."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _anuncio_rascunho_de_linha(row)
        sit = r["situacao"]
        if sit == "publicando":
            raise ValueError("Este rascunho já está sendo publicado.")
        if sit == "publicado":
            raise ValueError(f"Este rascunho já foi publicado ({r.get('mlb') or 'MLB'}).")
        if sit == "incerto":
            raise ValueError("A última tentativa ficou sem resposta do Mercado Livre: confira no ML e libere antes.")
        if sit != "validado":
            raise ValueError("Confira no Mercado Livre (Validar) antes de publicar.")
        cur = DB.execute("UPDATE anuncio_rascunho_v2024 SET situacao='publicando', erros_json='[]', versao=versao+1, "
                         "atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='validado'",
                         (now_iso(), str(ator or ""), rid))
        if cur.rowcount != 1:
            DB.commit()
            raise ValueError("Este rascunho já está sendo publicado.")
        DB.commit()
    conta, cod = str(r["conta"]), str(r["ficha_codigo"])
    estado: dict[str, Any] = {"etapa": "antes", "fim": None, "mlb": None}
    avisos: list[str] = []

    def fim(para: str, erros: list[str], mlb: str | None = None) -> dict[str, Any]:
        novo = _anuncio_rascunho_trocar(rid, ("publicando",), para, erros, ator, mlb=mlb)
        estado["fim"] = novo or anuncio_rascunho_ler(rid) or r
        audit(ator, "anuncios.publicar", f"{cod}|{rid}|{conta}|{para}|{mlb or ''}|{'; '.join(erros)[:500]}")
        return {"ok": para == "publicado", "situacao": para, "mlb": mlb or "", "erros": [] if para == "publicado" else erros,
                "avisos": avisos, "rascunho": estado["fim"]}

    try:
        # 1) token da conta (se falhar aqui, nada saiu)
        try:
            with ml_na_casa(conta):
                ml_access_token()
        except Exception as exc:
            return fim("validado", [f"Mercado Livre da conta {conta}: {exc}"])
        # 2) Apollo da filial: "da para montar" desconhecido nunca vira zero nem "pode"
        try:
            ficha = anuncio_ficha_payload(cod, ler_apollo=True, filiais=(conta,))  # V20.24: so a filial da conta
        except Exception as exc:
            ficha = None
            print(f"Aviso: Apollo nao lido para publicar {cod}: {exc}", file=sys.stderr)
        est = (((ficha or {}).get("estoque") or {}).get(conta) or {})
        dpm = est.get("da_para_montar") if isinstance(est, dict) else None
        qtd = int(r.get("quantidade") or 0)
        if dpm is None:
            return fim("validado", ["O Apollo não respondeu (ou a fila não foi lida) — não publicado. Tente de novo."])
        if int(dpm) <= 0:
            return fim("validado", ["Sem estoque no Apollo da filial para montar este produto — não publicado."])
        if qtd < 1 or qtd > int(dpm):
            return fim("validado", [f"Quantidade {qtd} acima do que dá para montar no Apollo ({int(dpm)}) — não publicado."])
        # 3) confere de novo (foto apagada da ficha, categoria) e sobe as fotos; erro = nada criado
        erros, defs = _anuncio_conferir_local(r)
        if erros:
            return fim("validado", erros)
        fotos_ml: list[str] = []
        for pos, fid in enumerate(r.get("fotos") or [], 1):
            try:
                dados, tipo = anuncio_foto_bytes(fid)
                with ml_na_casa(conta):
                    fotos_ml.append(_ml_foto_upload(dados, tipo))
            except Exception as exc:
                return fim("validado", [f"A foto {pos} não subiu para o Mercado Livre ({exc}). Nada foi criado."])
        # 4) cria o anuncio: daqui em diante uma falha sem resposta = incerto
        corpo = anuncio_item_corpo(r, fotos_ml, defs)
        if int(r.get("usa_family_name") or 0):  # V20.24 (revisao): o corpo que o ML aceitou na conferencia
            corpo = _anuncio_corpo_family(corpo, r.get("titulo"))
        resp: Any = None
        primeira: list[str] = []
        for tentativa in (1, 2):
            estado["etapa"] = "enviado"
            try:
                with ml_na_casa(conta):
                    resp = _anuncio_ml_chamar("POST", "/items", corpo, timeout=ANUNCIO_ITEM_TIMEOUT)
                break
            except AnuncioMLRecusou as exc:
                _anuncio_amostra("item_criar", {"status": exc.status, "resposta": exc.corpo or str(exc)})
                estado["etapa"] = "antes"  # recusa = nada criado
                if tentativa == 1 and "title" in corpo and _anuncio_causa_titulo(exc.corpo):
                    primeira = _anuncio_mensagens_ml(exc)
                    corpo = _anuncio_corpo_family(corpo, r.get("titulo"))
                    continue
                erros_ml = _anuncio_mensagens_ml(exc)
                return fim("erro", _anuncio_erros_duas_tentativas(primeira, erros_ml) if primeira else erros_ml)
            except AnuncioMLSemResposta as exc:
                return fim("incerto", [ANUNCIO_INCERTO_TEXTO, f"Detalhe: {exc}"])
        _anuncio_amostra("item_criar", resp)
        mlb = _anuncio_mlb(resp.get("id") if isinstance(resp, dict) else "")
        if not mlb:
            return fim("incerto", [ANUNCIO_INCERTO_TEXTO, "O Mercado Livre respondeu sem o número do anúncio."])
        estado["mlb"] = mlb
        # 5) descricao (falha = aviso; o anuncio ja existe e NAO e desfeito)
        descricao = str(r.get("descricao") or "").strip()
        if descricao:
            try:
                with ml_na_casa(conta):
                    rd = _anuncio_ml_chamar("POST", f"/items/{mlb}/description", {"plain_text": descricao},
                                            timeout=ANUNCIO_ITEM_TIMEOUT)
                _anuncio_amostra("descricao", rd)
            except Exception as exc:
                _anuncio_amostra("descricao", {"erro": str(exc)})
                avisos.append(f"A descrição não foi gravada no Mercado Livre ({exc}). Inclua no ML.")
        with DB_LOCK:
            try:
                cur = DB.execute("UPDATE anuncio_rascunho_v2024 SET situacao='publicado', mlb=?, erros_json=?, "
                                 "versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='publicando'",
                                 (mlb, json.dumps(avisos, ensure_ascii=False), now_iso(), str(ator or ""), rid))
                if cur.rowcount == 1:
                    _anuncio_canal_noromak(conta, mlb, r, ator, resp if isinstance(resp, dict) else None)
                DB.commit()
            except Exception:
                DB.rollback()
                raise
            row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid,)).fetchone()
        estado["fim"] = _anuncio_rascunho_de_linha(row)
        audit(ator, "anuncios.publicar", f"{cod}|{rid}|{conta}|publicado|{mlb}|{'; '.join(avisos)[:500]}")
        return {"ok": True, "situacao": "publicado", "mlb": mlb, "erros": [], "avisos": avisos,
                "rascunho": estado["fim"]}
    finally:
        if estado["fim"] is None:  # falha inesperada: nunca fica preso em `publicando`
            try:
                if estado["etapa"] == "antes":
                    fim("validado", ["Falha inesperada antes de criar o anúncio; nada foi criado no Mercado Livre."])
                else:
                    fim("incerto", [ANUNCIO_INCERTO_TEXTO], mlb=estado["mlb"])
            except Exception as exc:
                print(f"Aviso: rascunho {rid} nao saiu de publicando: {exc}", file=sys.stderr)


def anuncio_incerto_liberar(rascunho_id: Any, mlb_encontrado: Any, ator: str) -> dict[str, Any]:
    """V20.24: o Admin conferiu no ML o rascunho `incerto`: com o MLB = `publicado` (e entra na lista como
    `noromak`); sem MLB = volta a `validado` (pode publicar de novo). Nao chama o ML."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    texto = str(mlb_encontrado or "").strip()
    mlb = _anuncio_mlb(texto)
    if texto and not mlb:
        raise ValueError("MLB inválido (ex.: MLB1234567890).")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _anuncio_rascunho_de_linha(row)
        if r["situacao"] != "incerto":
            raise ValueError("Só um rascunho sem resposta do Mercado Livre (incerto) pode ser liberado.")
        if mlb:
            # V20.24 (revisao): MLB que ja esta na lista ligado a outro produto (ou sem ficha) ou controlado pela
            # Alephee/Full nunca e religado calado - um MLB digitado errado tomaria o anuncio de outro.
            for ja in DB.execute("SELECT conta, ficha_codigo, controle FROM anuncio_canal_v2023 "
                                 "WHERE canal='ml' AND anuncio_id=?", (mlb,)).fetchall():
                if str(ja["ficha_codigo"] or "") != str(r["ficha_codigo"]):
                    dono = ("o produto " + str(ja["ficha_codigo"])) if ja["ficha_codigo"] else "nenhum produto"
                    raise ValueError(f"O {mlb} já está na lista ligado a {dono}. Confira o número no Mercado Livre; "
                                     "nada foi alterado.")
                if str(ja["controle"] or "") != "noromak":
                    raise ValueError(f"O {mlb} já está na lista controlado por {ja['controle']}. Confira o número no "
                                     "Mercado Livre; se é o anúncio criado agora, passe o controle para Noromak na "
                                     "lista e libere de novo. Nada foi alterado.")
        try:
            para = "publicado" if mlb else "validado"
            DB.execute("UPDATE anuncio_rascunho_v2024 SET situacao=?, mlb=?, erros_json='[]', versao=versao+1, "
                       "atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='incerto'",
                       (para, mlb or None, now_iso(), str(ator or ""), rid))
            if mlb:
                _anuncio_canal_noromak(str(r["conta"]), mlb, r, ator)
            DB.commit()
        except Exception:
            DB.rollback()
            raise
        novo = _anuncio_rascunho_de_linha(DB.execute("SELECT * FROM anuncio_rascunho_v2024 WHERE id=?", (rid,)).fetchone())
    audit(ator, "anuncios.liberar", f"{r['ficha_codigo']}|{rid}|{r['conta']}|{para}|{mlb}")
    return {"ok": True, "situacao": para, "mlb": mlb, "rascunho": novo}


# ---------------------------------------------------------------------------
# V20.32 - Criar anuncio na Shopee (so Araçatuba) pela plataforma de anuncios. Desenho:
# docs/superpowers/specs/2026-11-06-anuncios-shopee-design.md. Leituras com cache de 24 h; a 1a resposta de cada
# chamada fica em anuncio_amostra_v2024 (tipos shopee_*: construido pela documentacao - CONFERIR no 1o uso).
# A Shopee nao tem "conferir sem criar": o Conferir e local, contra os limites/atributos/marcas/canais que ela publica.
# Publicar = a UNICA escrita na criacao (fotos + add_item); mesma maquina de situacao do ML (incerto nunca repete).
# Peso e medidas sao lidos da FICHA na hora (nunca copiados para o rascunho: a ficha corrigida depois vale).
# ---------------------------------------------------------------------------
SHOPEE_ANUNCIO_CONTA = "aracatuba"
SHOPEE_LEITURA_CACHE_S = 24 * 3600
SHOPEE_TITULO_MAX_PADRAO = 120
SHOPEE_FOTOS_MAX_PADRAO = 9
SHOPEE_ITEM_TIMEOUT = 90
SHOPEE_UPLOAD_TIMEOUT = 60
SHOPEE_MARCAS_PAGINAS = 40
SHOPEE_INCERTO_TEXTO = ("A Shopee não respondeu ao criar o anúncio: ele pode ter sido criado. Confira no Seller Center "
                        "(Meus produtos) e informe o número do item, ou libere sem número se ele não existe. Nada é "
                        "repetido sozinho.")
SHOPEE_RASCUNHO_EDITAVEL = ("rascunho", "validado", "erro")
SHOPEE_RASCUNHO_CAMPOS = ("titulo", "categoria", "categoria_nome", "descricao", "preco", "quantidade")
_SHOPEE_LEITURA_CACHE: dict[tuple[str, str], tuple[float, Any]] = {}
_SHOPEE_LEITURA_LOCK = threading.Lock()
_SHOPEE_AUTH_ERROS = {"error_auth", "error_authentication", "invalid_access_token", "invalid_acceess_token",
                      "error_token", "error_invalid_access_token"}


class ShopeeSemResposta(Exception):
    """V20.32: sem resposta (rede, timeout, 5xx, resposta ilegivel): a Shopee PODE ter feito."""


class ShopeeRecusou(Exception):
    """V20.32: a Shopee respondeu com recusa (ou a chamada nem saiu): nada foi feito na Shopee."""

    def __init__(self, mensagem: str, corpo: Any = None, status: int | None = None) -> None:
        super().__init__(mensagem)
        self.corpo = corpo
        self.status = status


# revisar-antes-de-subir (06/11): erro do lado da Shopee (interno, ocupado, tempo) numa ESCRITA pode ter feito a
# escrita: no add_item vira `incerto` (nunca "recusado", que deixaria publicar de novo e criar dois anuncios).
_SHOPEE_ERRO_TALVEZ_FEZ = re.compile(r"server|inner|internal|busy|time[ _-]?out|network|system|unknown", re.I)


def _shopee_talvez_fez(exc: Exception) -> bool:
    if isinstance(exc, ShopeeSemResposta):
        return True
    if isinstance(exc, ShopeeRecusou):
        if exc.status == 408 or (exc.status or 0) >= 500:  # 2a revisao: 429 = limite, a Shopee nao processou
            return True
        erro = str((exc.corpo or {}).get("error") or "") if isinstance(exc.corpo, dict) else ""
        return bool(_SHOPEE_ERRO_TALVEZ_FEZ.search(erro or str(exc).split(":", 1)[0]))
    return False


def _shopee_multipart(campos: dict[str, str], arquivo: tuple[str, str, bytes, str]) -> tuple[bytes, str]:
    """(corpo, content-type) multipart/form-data: os campos de texto + um arquivo (campo, nome, bytes, mime)."""
    limite = "----NoromakShopee" + secrets.token_hex(12)
    partes: list[bytes] = []
    for nome, valor in campos.items():
        partes.append((f"--{limite}\r\nContent-Disposition: form-data; name=\"{nome}\"\r\n\r\n{valor}\r\n").encode())
    campo, nome_arq, dados, mime = arquivo
    partes.append((f"--{limite}\r\nContent-Disposition: form-data; name=\"{campo}\"; filename=\"{nome_arq}\"\r\n"
                   f"Content-Type: {mime}\r\n\r\n").encode() + dados + b"\r\n")
    partes.append(f"--{limite}--\r\n".encode())
    return b"".join(partes), f"multipart/form-data; boundary={limite}"


def _shopee_chamar(method: str, path: str, params: dict[str, Any] | None = None, payload: Any = None, *,
                   multipart: tuple[dict[str, str], tuple[str, str, bytes, str]] | None = None,
                   timeout: float = 35, _renovou: bool = False, publico: bool = False) -> dict[str, Any]:
    """V20.32: chamada da Shopee que separa RECUSA (nada feito) de SEM RESPOSTA (pode ter feito). Token que nao
    renova = recusa (a chamada nem saiu). `publico` = assinatura sem a loja (partner_id+path+timestamp: rotas que
    nao pedem a loja, como a do upload de imagem em algumas versoes da doc).
    Revisao: so renova o token em erro DE TOKEN (401 ou codigo de autenticacao) — 403 de permissao nao gasta o
    refresh_token de uso unico; o status HTTP vai na recusa (408/429 = talvez feito)."""
    try:
        row = shopee_refresh_access_token(_renovou)
        shop_id = str(row["shop_id"] or "").strip()
        token = str(row["access_token"] or "").strip()
    except Exception as exc:
        raise ShopeeRecusou(f"Shopee sem conexão: {exc}")
    ts = int(time.time())
    if publico:
        query: dict[str, Any] = {"partner_id": int(SHOPEE_PARTNER_ID), "timestamp": ts, "sign": shopee_sign(path, ts)}
    else:
        query = {"partner_id": int(SHOPEE_PARTNER_ID), "timestamp": ts, "access_token": token,
                 "shop_id": int(shop_id), "sign": shopee_sign(path, ts, token, shop_id)}
    for k, v in (params or {}).items():
        if v is not None and v != "":
            query[k] = v
    url = SHOPEE_API_BASE + path + "?" + urlencode(query)
    headers = {"Accept": "application/json"}
    corpo: bytes | None = None
    if multipart is not None:
        corpo, headers["Content-Type"] = _shopee_multipart(*multipart)
    elif method == "POST":
        corpo = json.dumps(payload or {}).encode("utf-8")
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=corpo, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            texto = resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        bruto = exc.read().decode("utf-8", "replace")
        if exc.code >= 500:
            raise ShopeeSemResposta(f"Shopee HTTP {exc.code}: {bruto[:300]}")
        dados = _anuncio_json_ou_none(bruto)
        erro = str((dados or {}).get("error") or "") if isinstance(dados, dict) else ""
        if not _renovou and not publico and (exc.code == 401 or erro.lower() in _SHOPEE_AUTH_ERROS):
            return _shopee_chamar(method, path, params, payload, multipart=multipart, timeout=timeout, _renovou=True)
        msg = (f"{erro} {(dados or {}).get('message') or ''}".strip() if isinstance(dados, dict) else "") or bruto[:300]
        raise ShopeeRecusou(f"Shopee HTTP {exc.code}: {msg}", dados if isinstance(dados, dict) else bruto[:2000],
                            status=exc.code)
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise ShopeeSemResposta(f"sem resposta da Shopee ({exc})")
    dados = _anuncio_json_ou_none(texto)
    if not isinstance(dados, dict):
        raise ShopeeSemResposta("resposta ilegível da Shopee")
    erro = str(dados.get("error") or "").strip()
    if erro:
        if not _renovou and not publico and erro.lower() in _SHOPEE_AUTH_ERROS:
            return _shopee_chamar(method, path, params, payload, multipart=multipart, timeout=timeout, _renovou=True)
        raise ShopeeRecusou(f"{erro}: {dados.get('message') or ''}".strip(" :"), dados, status=200)
    return dados


def _shopee_ler(path: str, params: dict[str, Any] | None = None, amostra: str = "") -> dict[str, Any]:
    """V20.32: leitura (GET). Qualquer falha vira RuntimeError com o motivo."""
    try:
        dados = _shopee_chamar("GET", path, params)
    except (ShopeeRecusou, ShopeeSemResposta) as exc:
        if amostra:
            _anuncio_amostra(f"{amostra} [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None)})
        raise RuntimeError(str(exc))
    if amostra:
        _anuncio_amostra(amostra, dados)
    return dados


def _shopee_cache(chave: tuple[str, str], ler: Any) -> Any:
    agora = time.time()
    with _SHOPEE_LEITURA_LOCK:
        hit = _SHOPEE_LEITURA_CACHE.get(chave)
        if hit and agora - hit[0] < SHOPEE_LEITURA_CACHE_S:
            return hit[1]
    valor = ler()
    with _SHOPEE_LEITURA_LOCK:
        if len(_SHOPEE_LEITURA_CACHE) > 500:
            _SHOPEE_LEITURA_CACHE.clear()
        _SHOPEE_LEITURA_CACHE[chave] = (agora, valor)
    return valor


def _shopee_resposta(dados: Any) -> dict[str, Any]:
    r = (dados or {}).get("response") if isinstance(dados, dict) else None
    return r if isinstance(r, dict) else {}


def _shopee_limite(bloco: Any) -> tuple[int | None, int | None]:
    if not isinstance(bloco, dict):
        return None, None

    def n(v: Any) -> int | None:
        try:
            return int(v) if v is not None else None
        except (TypeError, ValueError):
            return None
    return n(bloco.get("min_limit")), n(bloco.get("max_limit"))


def shopee_item_limites(categoria: Any = None) -> dict[str, Any]:
    """V20.32: limites da loja/categoria (get_item_limit). Sem resposta = os padroes (titulo 120, 9 fotos)."""
    cid = str(categoria or "").strip()

    def ler() -> dict[str, Any]:
        r = _shopee_resposta(_shopee_ler("/api/v2/product/get_item_limit",
                                         {"category_id": int(cid)} if cid.isdigit() else None, "shopee_item_limit"))
        t_min, t_max = _shopee_limite(r.get("item_name_length_limit"))
        d_min, d_max = _shopee_limite(r.get("item_description_length_limit"))
        f_min, f_max = _shopee_limite(r.get("item_image_count_limit"))
        p_min, p_max = _shopee_limite(r.get("price_limit"))
        return {"titulo_min": t_min, "titulo_max": t_max, "desc_min": d_min, "desc_max": d_max,
                "fotos_min": f_min, "fotos_max": f_max, "preco_min": p_min, "preco_max": p_max,
                "gtin": str(r.get("gtin_validation_rule") or ""), "lido": True}
    try:
        return dict(_shopee_cache(("limite", cid), ler))
    except RuntimeError as exc:
        return {"titulo_min": None, "titulo_max": SHOPEE_TITULO_MAX_PADRAO, "desc_min": None, "desc_max": None,
                "fotos_min": 1, "fotos_max": SHOPEE_FOTOS_MAX_PADRAO, "preco_min": None, "preco_max": None, "gtin": "",
                "lido": False, "erro": str(exc)}


def shopee_categorias() -> dict[str, dict[str, Any]]:
    """V20.32: arvore de categorias (get_category, pt-br): id -> {id, nome, pai, folha}."""
    def ler() -> dict[str, dict[str, Any]]:
        r = _shopee_resposta(_shopee_ler("/api/v2/product/get_category", {"language": "pt-br"}, "shopee_categorias"))
        saida: dict[str, dict[str, Any]] = {}
        for c in r.get("category_list") or []:
            if not isinstance(c, dict) or c.get("category_id") in (None, ""):
                continue
            cid = str(c["category_id"])
            saida[cid] = {"id": cid, "nome": str(c.get("display_category_name") or c.get("original_category_name") or cid),
                          "pai": str(c.get("parent_category_id") or ""), "folha": not bool(c.get("has_children"))}
        if not saida:
            raise RuntimeError("a Shopee devolveu a lista de categorias vazia")
        return saida
    return _shopee_cache(("categorias", ""), ler)


def _shopee_caminho(cid: str, cats: dict[str, dict[str, Any]]) -> str:
    nomes: list[str] = []
    atual, voltas = str(cid), 0
    while atual and atual in cats and voltas < 10:
        nomes.append(cats[atual]["nome"])
        atual, voltas = cats[atual]["pai"], voltas + 1
    return " > ".join(reversed(nomes))


def shopee_categoria_sugerir(titulo: str) -> list[dict[str, Any]]:
    """V20.32: categorias sugeridas pela Shopee para o titulo (category_recommend), com nome e caminho."""
    titulo = " ".join(str(titulo or "").split())
    if not titulo:
        raise ValueError("Informe o título.")
    r = _shopee_resposta(_shopee_ler("/api/v2/product/category_recommend", {"item_name": titulo[:255]},
                                     "shopee_categoria_sugerir"))
    cats = shopee_categorias()
    saida = []
    for cid in r.get("category_id") or []:
        c = cats.get(str(cid))
        saida.append({"categoria": str(cid), "nome": c["nome"] if c else str(cid),
                      "caminho": _shopee_caminho(str(cid), cats), "folha": bool(c and c["folha"])})
    return saida


SHOPEE_TIPO_ATRIBUTO = {1: "lista", 2: "lista_livre", 3: "livre", 4: "multi", 5: "multi_livre"}


def shopee_categoria_atributos(categoria: Any) -> dict[str, Any]:
    """V20.32: atributos da categoria (get_attribute_tree): so o nivel de cima (o condicional fica para o Seller
    Center). `obrigatorio` = mandatory; `tipo` lista|lista_livre|livre|multi|multi_livre; `unidades` quando pede."""
    cid = str(categoria or "").strip()
    if not cid.isdigit():
        raise ValueError("Categoria da Shopee inválida.")

    def ler() -> dict[str, Any]:
        r = _shopee_resposta(_shopee_ler("/api/v2/product/get_attribute_tree",
                                         {"category_id_list": cid, "language": "pt-br"}, "shopee_atributos"))
        arvore: list[Any] = []
        for item in r.get("list") or []:
            if isinstance(item, dict) and str(item.get("category_id")) == cid:
                arvore = item.get("attribute_tree") or []
        lista = []
        for a in arvore:
            if not isinstance(a, dict) or a.get("attribute_id") in (None, ""):
                continue
            info = a.get("attribute_info") if isinstance(a.get("attribute_info"), dict) else {}
            try:
                tipo = SHOPEE_TIPO_ATRIBUTO.get(int(info.get("input_type") or 3), "livre")
            except (TypeError, ValueError):
                tipo = "livre"
            valores = [{"id": str(v.get("value_id")), "nome": str(v.get("name") or v.get("value_id"))}
                       for v in a.get("attribute_value_list") or [] if isinstance(v, dict) and v.get("value_id") is not None]
            lista.append({"id": str(a["attribute_id"]), "nome": str(a.get("name") or a["attribute_id"]),
                          "obrigatorio": bool(a.get("mandatory")), "tipo": tipo, "valores": valores,
                          "unidades": [str(u) for u in info.get("attribute_unit_list") or [] if u]})
        return {"categoria": cid, "atributos": lista}
    return _shopee_cache(("atributos", cid), ler)


def shopee_marcas(categoria: Any) -> dict[str, Any]:
    """V20.32: marcas da categoria (get_brand_list, paginado) e se a marca e obrigatoria."""
    cid = str(categoria or "").strip()
    if not cid.isdigit():
        raise ValueError("Categoria da Shopee inválida.")

    def ler() -> dict[str, Any]:
        marcas: list[dict[str, str]] = []
        obrigatoria = False
        offset = 0
        for pagina in range(SHOPEE_MARCAS_PAGINAS):
            r = _shopee_resposta(_shopee_ler("/api/v2/product/get_brand_list",
                                             {"offset": offset, "page_size": 100, "category_id": int(cid), "status": 1,
                                              "language": "pt-br"}, "shopee_marcas" if pagina == 0 else ""))
            obrigatoria = obrigatoria or bool(r.get("is_mandatory"))
            for b in r.get("brand_list") or []:
                if isinstance(b, dict) and b.get("brand_id") is not None:
                    marcas.append({"id": str(b["brand_id"]),
                                   "nome": str(b.get("display_brand_name") or b.get("original_brand_name") or ""),
                                   "original": str(b.get("original_brand_name") or b.get("display_brand_name") or "")})
            if not r.get("has_next_page"):
                break
            try:
                offset = int(r.get("next_offset"))
            except (TypeError, ValueError):
                break
        return {"categoria": cid, "obrigatoria": obrigatoria, "marcas": marcas}
    return _shopee_cache(("marcas", cid), ler)


def shopee_marca_da_ficha(marca: Any, lista: dict[str, Any]) -> dict[str, str] | None:
    """V20.32 (pura): a marca da ficha na lista da Shopee (sem acento/caixa/espaco)."""
    alvo = re.sub(r"\s+", "", _anuncio_sem_acento(marca))
    if not alvo:
        return None
    for b in lista.get("marcas") or []:
        if re.sub(r"\s+", "", _anuncio_sem_acento(b.get("nome"))) == alvo or \
                re.sub(r"\s+", "", _anuncio_sem_acento(b.get("original"))) == alvo:
            return {"id": str(b["id"]), "nome": str(b.get("original") or b.get("nome"))}
    return None


def shopee_canais_envio() -> list[dict[str, Any]]:
    """V20.32: canais de envio da loja (get_channel_list). `usavel` = ligado e sem tamanho/preco a escolher."""
    def ler() -> list[dict[str, Any]]:
        r = _shopee_resposta(_shopee_ler("/api/v2/logistics/get_channel_list", None, "shopee_canais"))
        saida = []
        for c in r.get("logistics_channel_list") or []:
            if not isinstance(c, dict) or c.get("logistics_channel_id") in (None, ""):
                continue
            peso = c.get("weight_limit") if isinstance(c.get("weight_limit"), dict) else {}
            dim = c.get("item_max_dimension") if isinstance(c.get("item_max_dimension"), dict) else {}
            fee = str(c.get("fee_type") or "")
            saida.append({"id": str(c["logistics_channel_id"]), "nome": str(c.get("logistics_channel_name") or ""),
                          "ligado": bool(c.get("enabled")), "fee_type": fee,
                          "peso_max_kg": _money_number(peso.get("item_max_weight")) or None,
                          "peso_min_kg": _money_number(peso.get("item_min_weight")) or None,
                          "dim_max": {k: _money_number(dim.get(k)) or None for k in ("height", "width", "length")},
                          "usavel": bool(c.get("enabled")) and fee not in ("SIZE_SELECTION", "CUSTOM_PRICE")})
        return saida
    return list(_shopee_cache(("canais", ""), ler))


def shopee_canais_que_aceitam(canais: list[dict[str, Any]], peso_kg: float | None,
                              medidas: dict[str, float | None]) -> list[dict[str, Any]]:
    """V20.32 (pura): canais usaveis cujo limite de peso/medidas aceita o pacote (limite vazio = sem limite)."""
    saida = []
    for c in canais:
        if not c.get("usavel"):
            continue
        if peso_kg is not None:
            if c.get("peso_max_kg") and peso_kg > float(c["peso_max_kg"]):
                continue
            if c.get("peso_min_kg") and peso_kg < float(c["peso_min_kg"]):
                continue
        dm = c.get("dim_max") or {}
        if any(dm.get(k) and medidas.get(k) and float(medidas[k]) > float(dm[k]) for k in ("height", "width", "length")):
            continue
        saida.append(c)
    return saida


def _shopee_pacote_da_ficha(campos: dict[str, Any]) -> tuple[float | None, dict[str, float | None], list[str]]:
    """V20.32: peso (kg) e medidas (cm) LIDOS DA FICHA agora; o que falta vai na lista."""
    def n(v: Any) -> float | None:
        try:
            x = float(str(v).replace(",", "."))
        except (TypeError, ValueError):
            return None
        return x if x > 0 else None
    peso_g = n(campos.get("peso_g"))
    medidas = {"height": n(campos.get("altura_cm")), "width": n(campos.get("largura_cm")),
               "length": n(campos.get("comprimento_cm"))}
    falta = [nome for nome, v in (("peso", peso_g), ("altura", medidas["height"]), ("largura", medidas["width"]),
                                  ("comprimento", medidas["length"])) if v is None]
    return (round(peso_g / 1000.0, 3) if peso_g else None), medidas, falta


# ---- rascunho ----
def _shopee_rascunho_de_linha(row: Any) -> dict[str, Any]:
    d = dict(row)
    for campo, padrao in (("atributos_json", {}), ("fotos_json", []), ("erros_json", []), ("marca_json", {})):
        try:
            v = json.loads(d.pop(campo) or "")
        except (TypeError, ValueError):
            v = padrao
        d[campo[:-5]] = v if isinstance(v, type(padrao)) else padrao
    d["canal"] = "shopee"
    return d


def shopee_rascunho_ler(rid: Any) -> dict[str, Any] | None:
    try:
        n = int(rid)
    except (TypeError, ValueError):
        return None
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (n,)).fetchone()
    return _shopee_rascunho_de_linha(row) if row else None


def shopee_rascunhos_da_ficha(codigo: str) -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE ficha_codigo=? ORDER BY id DESC",
                          (normalize(codigo),)).fetchall()
    return [_shopee_rascunho_de_linha(r) for r in rows]


def _shopee_rascunho_limpar(dados: dict[str, Any]) -> dict[str, Any]:
    """V20.32: so os campos que vieram, conferidos (tipo e tamanho)."""
    out: dict[str, Any] = {}
    if "titulo" in dados:
        out["titulo"] = " ".join(str(dados.get("titulo") or "").split())[:255]
    if "categoria" in dados:
        cat = str(dados.get("categoria") or "").strip()
        if cat and not cat.isdigit():
            raise ValueError("Categoria da Shopee inválida.")
        out["categoria"] = cat
        out["categoria_nome"] = str(dados.get("categoria_nome") or "")[:300]
    if "descricao" in dados:
        out["descricao"] = str(dados.get("descricao") or "")[:10000]
    if "preco" in dados:
        p = dados.get("preco")
        if p in (None, ""):
            out["preco"] = None
        else:
            try:
                out["preco"] = round(float(str(p).replace(",", ".")), 2)
            except (TypeError, ValueError):
                raise ValueError("Preço inválido.")
            if isinstance(p, bool) or not math.isfinite(out["preco"]) or out["preco"] <= 0:  # revisao: inf/nan/bool
                raise ValueError("O preço precisa ser um número maior que zero.")
    if "quantidade" in dados:
        q = dados.get("quantidade")
        if q in (None, ""):
            out["quantidade"] = None
        else:
            try:
                out["quantidade"] = int(str(q))
            except (TypeError, ValueError):
                raise ValueError("Quantidade inválida.")
            if not 1 <= out["quantidade"] <= ANUNCIO_ESTOQUE_MAX:
                raise ValueError("A quantidade vai de 1 a 99999.")
    if "atributos" in dados:
        brutos = dados.get("atributos") if isinstance(dados.get("atributos"), dict) else {}
        attrs: dict[str, dict[str, str]] = {}
        for k, v in brutos.items():
            if not str(k).isdigit() or not isinstance(v, dict):
                continue
            item = {"valor_id": str(v.get("valor_id") or "").strip(), "valor": " ".join(str(v.get("valor") or "").split())[:255],
                    "unidade": str(v.get("unidade") or "").strip()[:20]}
            if item["valor_id"] and not item["valor_id"].isdigit():
                continue
            if item["valor_id"] or item["valor"]:
                attrs[str(k)] = item
        out["atributos"] = attrs
    if "marca" in dados:
        m = dados.get("marca") if isinstance(dados.get("marca"), dict) else {}
        mid = str(m.get("id") or "").strip()
        out["marca"] = {"id": mid, "nome": str(m.get("nome") or "")[:120]} if mid.isdigit() else {}
    if "fotos" in dados:
        brutas = dados.get("fotos") or []
        if not isinstance(brutas, list) or any(isinstance(x, bool) for x in brutas):
            raise ValueError("Fotos inválidas.")
        try:
            fotos = list(dict.fromkeys(int(x) for x in brutas))  # revisao: sem repetir a mesma foto
        except (TypeError, ValueError):
            raise ValueError("Fotos inválidas.")
        if len(fotos) > SHOPEE_FOTOS_MAX_PADRAO:
            raise ValueError(f"A Shopee aceita até {SHOPEE_FOTOS_MAX_PADRAO} fotos.")
        out["fotos"] = fotos
    return out


def shopee_rascunho_salvar(dados: dict[str, Any], ator: str, versao: Any) -> dict[str, Any]:
    """V20.32: cria (sem `id`, com `codigo`) ou atualiza (com `id`; `versao` conferida, senao FichaConflito)."""
    dados = dados if isinstance(dados, dict) else {}
    limpos = _shopee_rascunho_limpar(dados)
    agora = now_iso()
    with DB_LOCK:
        rid = dados.get("id")
        if rid in (None, ""):
            cod = normalize(dados.get("codigo"))
            if not cod or _ficha_ler_sem_lock(cod) is None:
                raise ValueError("Produto não encontrado.")
            fotos = limpos.get("fotos", [])
            cur = DB.execute(
                "INSERT INTO anuncio_rascunho_shopee_v2032(ficha_codigo,titulo,categoria,categoria_nome,atributos_json,"
                "marca_json,fotos_json,descricao,preco,quantidade,situacao,versao,criado_em,criado_por,atualizado_em,"
                "atualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,'rascunho',1,?,?,?,?)",
                (cod, limpos.get("titulo", ""), limpos.get("categoria", ""), limpos.get("categoria_nome", ""),
                 json.dumps(limpos.get("atributos", {}), ensure_ascii=False),
                 json.dumps(limpos.get("marca", {}), ensure_ascii=False), json.dumps(fotos), limpos.get("descricao", ""),
                 limpos.get("preco"), limpos.get("quantidade"), agora, str(ator or ""), agora, str(ator or "")))
            novo_id = int(cur.lastrowid)
        else:
            row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone()
            if row is None:
                raise ValueError("Rascunho não encontrado.")
            atual = _shopee_rascunho_de_linha(row)
            try:
                ok_versao = versao is not None and int(versao) == int(atual["versao"])
            except (TypeError, ValueError):
                ok_versao = False
            if not ok_versao:
                raise FichaConflito(atual)
            if atual["situacao"] not in SHOPEE_RASCUNHO_EDITAVEL:
                raise ValueError("Este rascunho já foi publicado ou está em publicação; não pode mais ser editado.")
            novo = {k: limpos.get(k, atual.get(k)) for k in SHOPEE_RASCUNHO_CAMPOS}
            attrs = limpos.get("atributos", atual.get("atributos") or {})
            if "categoria" in limpos and limpos["categoria"] != str(atual.get("categoria") or "") and "atributos" not in limpos:
                attrs = {}  # categoria nova = atributos de novo (cada categoria tem os seus)
            marca = limpos.get("marca", atual.get("marca") or {})
            if "categoria" in limpos and limpos["categoria"] != str(atual.get("categoria") or "") and "marca" not in limpos:
                marca = {}  # revisao: a marca e da lista da categoria; categoria nova = escolher de novo
            fotos = limpos.get("fotos", atual.get("fotos") or [])
            mudou = (any(novo[k] != atual.get(k) for k in SHOPEE_RASCUNHO_CAMPOS) or attrs != (atual.get("atributos") or {})
                     or marca != (atual.get("marca") or {}) or fotos != (atual.get("fotos") or []))
            if not mudou:
                return atual
            situacao = "rascunho" if atual["situacao"] == "validado" else atual["situacao"]
            DB.execute(
                "UPDATE anuncio_rascunho_shopee_v2032 SET titulo=?,categoria=?,categoria_nome=?,atributos_json=?,marca_json=?,"
                "fotos_json=?,descricao=?,preco=?,quantidade=?,situacao=?,versao=versao+1,atualizado_em=?,atualizado_por=? "
                "WHERE id=?",
                (novo["titulo"], novo["categoria"], novo["categoria_nome"], json.dumps(attrs, ensure_ascii=False),
                 json.dumps(marca, ensure_ascii=False), json.dumps(fotos), novo["descricao"], novo["preco"],
                 novo["quantidade"], situacao, agora, str(ator or ""), atual["id"]))
            novo_id = int(atual["id"])
        cod_ficha = DB.execute("SELECT ficha_codigo FROM anuncio_rascunho_shopee_v2032 WHERE id=?",
                               (novo_id,)).fetchone()["ficha_codigo"]
        fotos_ok = json.loads(DB.execute("SELECT fotos_json FROM anuncio_rascunho_shopee_v2032 WHERE id=?",
                                         (novo_id,)).fetchone()["fotos_json"] or "[]")
        if fotos_ok:
            marcas = ",".join("?" * len(fotos_ok))
            achadas = {int(r["id"]) for r in DB.execute(
                f"SELECT id FROM anuncio_foto_v2024 WHERE ficha_codigo=? AND id IN ({marcas})", (cod_ficha, *fotos_ok))}
            if achadas != set(fotos_ok):
                DB.rollback()
                raise ValueError("Há foto que não pertence a este produto.")
        DB.commit()
        row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (novo_id,)).fetchone()
    return _shopee_rascunho_de_linha(row)


def _shopee_trocar(rid: int, de: tuple[str, ...], para: str, erros: list[str], ator: str,
                   item_id: str | None = None, versao: int | None = None) -> dict[str, Any] | None:
    with DB_LOCK:
        extra, args_v = ("", ()) if versao is None else (" AND versao=?", (int(versao),))
        cur = DB.execute(
            f"UPDATE anuncio_rascunho_shopee_v2032 SET situacao=?, erros_json=?, item_id=COALESCE(?,item_id), "
            f"versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? AND situacao IN ({','.join('?' * len(de))})"
            + extra,
            (para, json.dumps(list(erros), ensure_ascii=False), item_id, now_iso(), str(ator or ""), rid, *de, *args_v))
        DB.commit()
        if cur.rowcount != 1:
            return None
        row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone()
    return _shopee_rascunho_de_linha(row)


def _shopee_conferir_local(r: dict[str, Any]) -> tuple[list[str], dict[str, Any]]:
    """V20.32: confere o rascunho contra o que a Shopee publica (limites, atributos, marca, canais) e a ficha (peso,
    medidas). Devolve (erros, contexto para o corpo). Leitura que falha = erro (nunca adivinha)."""
    erros: list[str] = []
    ctx: dict[str, Any] = {}
    ficha = ficha_ler(r["ficha_codigo"]) or {}
    campos = ficha.get("campos") or {}
    titulo = str(r.get("titulo") or "").strip()
    cat = str(r.get("categoria") or "")
    lim = shopee_item_limites(cat or None)
    ctx["limites"] = lim
    t_max = lim.get("titulo_max") or SHOPEE_TITULO_MAX_PADRAO
    if not titulo:
        erros.append("Informe o título.")
    elif len(titulo) > t_max:
        erros.append(f"Título com {len(titulo)} caracteres: a Shopee aceita até {t_max}.")
    elif lim.get("titulo_min") and len(titulo) < int(lim["titulo_min"]):
        erros.append(f"Título curto: a Shopee pede pelo menos {lim['titulo_min']} caracteres.")
    desc = str(r.get("descricao") or "").strip()
    if not desc:
        erros.append("Informe a descrição.")
    elif lim.get("desc_min") and len(desc) < int(lim["desc_min"]):
        erros.append(f"Descrição curta: a Shopee pede pelo menos {lim['desc_min']} caracteres.")
    elif lim.get("desc_max") and len(desc) > int(lim["desc_max"]):
        erros.append(f"Descrição longa: a Shopee aceita até {lim['desc_max']} caracteres.")
    if "[CONFIRMAR]" in desc.upper():
        erros.append("A descrição ainda tem [CONFIRMAR]: troque pelo texto certo.")
    fotos = list(r.get("fotos") or [])
    f_max = lim.get("fotos_max") or SHOPEE_FOTOS_MAX_PADRAO
    if fotos:  # revisao: a Shopee so aceita JPG/PNG (a WEBP passava no Conferir e travava o Publicar)
        with DB_LOCK:
            tipos = {int(x["id"]): str(x["tipo"]) for x in DB.execute(
                f"SELECT id, tipo FROM anuncio_foto_v2024 WHERE id IN ({','.join('?' * len(fotos))})", fotos)}
        for pos, fid in enumerate(fotos, 1):
            if tipos.get(int(fid)) not in ("jpg", "png"):
                erros.append(f"Foto {pos}: a Shopee aceita só JPG ou PNG (troque a foto).")
    if not fotos:
        erros.append("Escolha pelo menos uma foto.")
    elif len(fotos) > f_max:
        erros.append(f"{len(fotos)} fotos: a Shopee aceita até {f_max}.")
    preco = r.get("preco")
    if not preco or float(preco) <= 0:
        erros.append("Informe o preço.")
    elif lim.get("preco_max") and float(preco) > float(lim["preco_max"]):
        erros.append(f"Preço acima do limite da Shopee (R$ {lim['preco_max']}).")
    if not r.get("quantidade") or int(r["quantidade"]) < 1:
        erros.append("Informe a quantidade.")
    peso, medidas, falta = _shopee_pacote_da_ficha(campos)
    ctx["peso"], ctx["medidas"] = peso, medidas
    if falta:
        erros.append(f"Falta na ficha (Peso e medidas): {', '.join(falta)}. Preencha a ficha do produto.")
    if not cat:
        erros.append("Escolha a categoria.")
        return erros, ctx
    try:
        cats = shopee_categorias()
        if cat in cats and not cats[cat]["folha"]:
            erros.append("A categoria escolhida tem subcategorias: escolha a mais específica.")
        defs = shopee_categoria_atributos(cat)["atributos"]
        marcas = shopee_marcas(cat)
    except (RuntimeError, ValueError) as exc:
        erros.append(f"Não consegui ler a categoria na Shopee ({exc}).")
        return erros, ctx
    ctx["defs"] = defs
    attrs = r.get("atributos") or {}
    for d in defs:
        v = attrs.get(d["id"]) or {}
        if d["obrigatorio"] and not (v.get("valor_id") or v.get("valor")):
            erros.append(f"Atributo obrigatório sem valor: {d['nome']}.")
        if v.get("valor_id") and d["valores"] and v["valor_id"] not in {x["id"] for x in d["valores"]}:
            erros.append(f"Valor de {d['nome']} fora da lista da Shopee.")
        if d["tipo"] in ("lista", "multi") and v.get("valor") and not v.get("valor_id"):
            erros.append(f"{d['nome']}: escolha um valor da lista da Shopee.")
    marca = r.get("marca") or {}
    ctx["avisos"] = []
    if not marca.get("id"):
        achada = shopee_marca_da_ficha(campos.get("marca"), marcas)
        if achada:
            marca = achada
        elif marcas.get("obrigatoria"):
            erros.append("A Shopee pede a marca nesta categoria e a da ficha não está na lista: escolha a marca.")
        else:
            marca = {"id": "0", "nome": "No Brand"}
            if str(campos.get("marca") or "").strip():  # revisao: nunca "No Brand" calado
                ctx["avisos"].append(f"A marca da ficha ({campos.get('marca')}) não está na lista da Shopee para esta "
                                     "categoria: o anúncio vai como \"No Brand\". Escolha a marca se ela existir na lista.")
    elif marca.get("id") != "0" and marca.get("id") not in {str(b.get("id")) for b in marcas.get("marcas") or []}:
        erros.append("A marca escolhida não é da lista desta categoria: escolha de novo.")
    ctx["marca"] = marca
    try:
        canais = shopee_canais_que_aceitam(shopee_canais_envio(), peso, medidas)
    except RuntimeError as exc:
        erros.append(f"Não consegui ler os canais de envio da Shopee ({exc}).")
        canais = []
    else:
        if not canais and not falta:
            erros.append("Nenhum canal de envio da loja aceita este peso/medidas (ou nenhum está ligado).")
    ctx["canais"] = canais
    return erros, ctx


def shopee_item_corpo(r: dict[str, Any], ficha: dict[str, Any], image_ids: list[str], ctx: dict[str, Any]) -> dict[str, Any]:
    """V20.32 (pura): corpo do product/add_item."""
    campos = ficha.get("campos") or {}
    medidas = ctx.get("medidas") or {}
    attrs = []
    for aid, v in (r.get("atributos") or {}).items():
        if v.get("valor_id"):
            valor = {"value_id": int(v["valor_id"])}
        elif v.get("valor"):
            valor = {"value_id": 0, "original_value_name": v["valor"]}
            if v.get("unidade"):
                valor["value_unit"] = v["unidade"]
        else:
            continue
        attrs.append({"attribute_id": int(aid), "attribute_value_list": [valor]})
    marca = ctx.get("marca") or {"id": "0", "nome": "No Brand"}
    corpo: dict[str, Any] = {
        "original_price": float(r["preco"]), "description": str(r.get("descricao") or "").strip(),
        "item_name": str(r.get("titulo") or "").strip(), "item_status": "NORMAL",
        "weight": float(ctx.get("peso") or 0),
        "dimension": {"package_length": max(1, math.ceil(float(medidas.get("length") or 0))),
                      "package_width": max(1, math.ceil(float(medidas.get("width") or 0))),
                      "package_height": max(1, math.ceil(float(medidas.get("height") or 0)))},
        "logistic_info": [{"logistic_id": int(c["id"]), "enabled": True} for c in ctx.get("canais") or []],
        "category_id": int(r["categoria"]), "image": {"image_id_list": list(image_ids)}, "condition": "NEW",
        "item_sku": str(ficha.get("codigo") or r.get("ficha_codigo") or "")[:100],
        "seller_stock": [{"stock": int(r.get("quantidade") or 0)}],
        "brand": {"brand_id": int(marca.get("id") or 0), "original_brand_name": str(marca.get("nome") or "No Brand")},
        "attribute_list": attrs,
    }
    ean = re.sub(r"\D", "", str(campos.get("ean") or ""))
    corpo["gtin_code"] = ean if len(ean) in (8, 12, 13, 14) else "00"
    ncm = re.sub(r"\D", "", str(campos.get("ncm") or ""))
    if len(ncm) == 8:
        corpo["tax_info"] = {"ncm": ncm, "origin": "0"}
    return corpo


def shopee_rascunho_conferir(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.32: conferencia local (a Shopee nao tem "conferir sem criar"). Certo = `validado`; errado = `rascunho`."""
    r = shopee_rascunho_ler(rascunho_id)
    if r is None:
        raise ValueError("Rascunho não encontrado.")
    if r["situacao"] not in SHOPEE_RASCUNHO_EDITAVEL:
        raise ValueError("Este rascunho já foi publicado, está em publicação ou aguarda conferência no Seller Center.")
    erros, ctx = _shopee_conferir_local(r)
    para = "rascunho" if erros else "validado"
    # revisao: so troca a situacao se ninguem salvou no meio (o resultado e da versao conferida)
    novo = _shopee_trocar(int(r["id"]), SHOPEE_RASCUNHO_EDITAVEL, para, erros, ator, versao=int(r["versao"]))
    if novo is None:
        raise FichaConflito(shopee_rascunho_ler(r["id"]) or {})
    return {"ok": not erros, "situacao": para, "erros": erros, "avisos": ctx.get("avisos") or [], "rascunho": novo}


def shopee_conta_preco(codigo: str, preco: Any) -> dict[str, Any]:
    """V20.32: conta do preco na Shopee para a tela (so le): tarifa pela faixa + 3,5%, imposto, custo de Araçatuba,
    lucro e o preco ideal pela margem-alvo. Sem custo = sem lucro e sem preco ideal (nunca zero)."""
    base = anuncio_custo_para_preco(codigo)
    try:
        p = round(float(str(preco).replace(",", ".")), 2) if preco not in (None, "") else None
    except (TypeError, ValueError):
        p = None
    if p is not None and not math.isfinite(p):  # revisao: inf/nan quebravam o JSON da tela
        p = None
    out: dict[str, Any] = {**base, "preco": p, "comissao": None, "comissao_pct": None, "taxa_fixa": None,
                           "imposto_valor": None, "lucro": None, "margem": None, "preco_ideal": None}
    imp = float(base.get("imposto") or 0)
    custo = base.get("custo")
    if p and p > 0:
        pct, fixa = shopee_taxas_por_preco(p)
        out.update({"comissao": round(p * pct, 2), "comissao_pct": pct, "taxa_fixa": fixa,
                    "imposto_valor": round(p * imp, 2)})
        if custo is not None:
            lucro = p - p * pct - fixa - p * imp - float(custo)
            out.update({"lucro": round(lucro, 2), "margem": round(lucro / p, 4)})
    alvo = base.get("margem_alvo")
    if custo is not None and alvo is not None:
        # preco ideal: resolve faixa a faixa (a tarifa depende do preco) e fica com o que cai na propria faixa
        for ini, fim, pct, fixa in SHOPEE_FAIXAS_TAXA:
            den = 1 - pct - imp - float(alvo)
            if den <= 0:
                continue
            ideal = (float(custo) + fixa) / den
            if ini <= ideal < fim:
                out["preco_ideal"] = round(ideal + 0.0049, 2)
                break
    return out


def _shopee_canal_noromak(item_id: str, r: dict[str, Any], ator: str) -> None:
    """V20.32: anuncio criado pelo Noromak entra na lista (canal shopee, `noromak`, estoque Manual). SOB o DB_LOCK."""
    agora = now_iso()
    DB.execute(
        "INSERT INTO anuncio_canal_v2023(canal,conta,anuncio_id,ficha_codigo,sku_anuncio,controle,titulo,preco,estoque,"
        "status,categoria,lido_em,controle_em,controle_por) VALUES('shopee',?,?,?,?,'noromak',?,?,?,'NORMAL',?,?,?,?) "
        "ON CONFLICT(canal,conta,anuncio_id) DO UPDATE SET ficha_codigo=excluded.ficha_codigo,controle='noromak',"
        "controle_em=excluded.controle_em,controle_por=excluded.controle_por",
        (SHOPEE_ANUNCIO_CONTA, item_id, r["ficha_codigo"], r["ficha_codigo"], str(r.get("titulo") or ""), r.get("preco"),
         r.get("quantidade"), str(r.get("categoria") or ""), agora, agora, str(ator or "")))


def _shopee_ja_anunciado(cod: str) -> str:
    """Revisao (06/11): o produto ja tem anuncio na Shopee criado pelo Noromak (ou um rascunho publicando/incerto)?
    Devolve o motivo ('' = pode). SOB o DB_LOCK. Duas abas criavam dois rascunhos e publicavam dois itens."""
    ja = DB.execute("SELECT anuncio_id FROM anuncio_canal_v2023 WHERE canal='shopee' AND ficha_codigo=? "
                    "AND controle='noromak' AND COALESCE(removido_em,'')='' LIMIT 1", (cod,)).fetchone()
    if ja:
        return (f"Este produto já tem anúncio na Shopee criado pelo Noromak (item {ja['anuncio_id']}). Para outro "
                "anúncio, remova o atual da lista antes.")
    outro = DB.execute("SELECT id FROM anuncio_rascunho_shopee_v2032 WHERE ficha_codigo=? AND situacao IN "
                       "('publicando','incerto') LIMIT 1", (cod,)).fetchone()
    if outro:
        return f"O rascunho nº {outro['id']} deste produto está publicando ou aguarda conferência no Seller Center."
    return ""


def shopee_publicar_reservar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.32: confere e troca `validado -> publicando` sob o DB_LOCK (um anuncio por rascunho e por produto).
    Erro aqui = ValueError, nada mudou."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _shopee_rascunho_de_linha(row)
        sit = r["situacao"]
        if sit == "publicando":
            raise ValueError("Este rascunho já está sendo publicado.")
        if sit == "publicado":
            raise ValueError(f"Este rascunho já foi publicado (item {r.get('item_id') or ''}).")
        if sit == "incerto":
            raise ValueError("A última tentativa ficou sem resposta da Shopee: confira no Seller Center e libere antes.")
        if sit != "validado":
            raise ValueError("Confira (passo 6) antes de publicar.")
        motivo = _shopee_ja_anunciado(str(r["ficha_codigo"]))
        if motivo:
            raise ValueError(motivo)
        cur = DB.execute("UPDATE anuncio_rascunho_shopee_v2032 SET situacao='publicando', erros_json='[]', versao=versao+1, "
                         "atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='validado'", (now_iso(), str(ator or ""), rid))
        DB.commit()
        if cur.rowcount != 1:
            raise ValueError("Este rascunho já está sendo publicado.")
    return r


def _shopee_subir_foto(dados: bytes, mime: str, pos: int) -> str:
    """Revisao: tenta a assinatura da loja e, com erro de assinatura/autenticacao, a publica (a doc varia)."""
    ext = {"image/jpeg": "jpg", "image/png": "png"}.get(mime)
    if not ext:
        raise ValueError("a Shopee só aceita JPG ou PNG")
    multipart = ({"scene": "normal"}, ("image", f"foto{pos}.{ext}", dados, mime))
    try:
        resp = _shopee_chamar("POST", "/api/v2/media_space/upload_image", multipart=multipart,
                              timeout=SHOPEE_UPLOAD_TIMEOUT)
    except ShopeeRecusou as exc:
        _anuncio_amostra("shopee_upload_image [erro]", {"erro": str(exc), "corpo": exc.corpo})
        codigo = str((exc.corpo or {}).get("error") or "") if isinstance(exc.corpo, dict) else ""
        if not re.search(r"sign|auth|token", codigo, re.I):  # 2a revisao: so o codigo (a mensagem tem "Shopee")
            raise
        resp = _shopee_chamar("POST", "/api/v2/media_space/upload_image", multipart=multipart,
                              timeout=SHOPEE_UPLOAD_TIMEOUT, publico=True)
    _anuncio_amostra("shopee_upload_image", resp)
    iid = str((_shopee_resposta(resp).get("image_info") or {}).get("image_id") or "")
    if not iid:
        raise ValueError("a Shopee não devolveu o id da foto")
    return iid


def shopee_publicar_executar(r: dict[str, Any], ator: str) -> dict[str, Any]:
    """V20.32: o trabalho do Publicar (rascunho ja em `publicando`). Falha antes do add_item = `validado`."""
    rid, cod = int(r["id"]), str(r["ficha_codigo"])
    estado: dict[str, Any] = {"etapa": "antes", "fim": None, "item_id": None}

    def fim(para: str, erros: list[str], item_id: str | None = None) -> dict[str, Any]:
        novo = _shopee_trocar(rid, ("publicando",), para, erros, ator, item_id=item_id)
        estado["fim"] = novo or shopee_rascunho_ler(rid) or r
        audit(ator, "anuncios.shopee_publicar", f"{cod}|{rid}|{para}|{item_id or ''}|{'; '.join(erros)[:500]}")
        return {"ok": para == "publicado", "situacao": para, "item_id": item_id or "",
                "erros": [] if para == "publicado" else erros, "rascunho": estado["fim"]}

    try:
        try:
            shopee_refresh_access_token(False)
        except Exception as exc:
            return fim("validado", [f"Shopee sem conexão: {exc}"])
        try:
            ficha_ap = anuncio_ficha_payload(cod, ler_apollo=True, filiais=(SHOPEE_ANUNCIO_CONTA,))
        except Exception as exc:
            ficha_ap = None
            print(f"Aviso: Apollo nao lido para publicar {cod} na Shopee: {exc}", file=sys.stderr)
        est = (((ficha_ap or {}).get("estoque") or {}).get(SHOPEE_ANUNCIO_CONTA) or {})
        dpm = est.get("da_para_montar") if isinstance(est, dict) else None
        qtd = int(r.get("quantidade") or 0)
        if dpm is None:
            return fim("validado", ["O Apollo não respondeu (ou a fila não foi lida) — não publicado. Tente de novo."])
        if int(dpm) <= 0:
            return fim("validado", ["Sem estoque no Apollo de Araçatuba para montar este produto — não publicado."])
        if qtd < 1 or qtd > int(dpm):
            return fim("validado", [f"Quantidade {qtd} acima do que dá para montar no Apollo ({int(dpm)}) — não publicado."])
        erros, ctx = _shopee_conferir_local(r)
        if erros:
            return fim("validado", erros)
        ids: list[str] = []
        for pos, fid in enumerate(r.get("fotos") or [], 1):
            try:
                dados, mime = anuncio_foto_bytes(fid)
                ids.append(_shopee_subir_foto(dados, mime, pos))
            except Exception as exc:
                return fim("validado", [f"A foto {pos} não subiu para a Shopee ({exc}). Nada foi criado."])
        corpo = shopee_item_corpo(r, ficha_ler(cod) or {"codigo": cod}, ids, ctx)
        estado["etapa"] = "enviado"
        try:
            resp = _shopee_chamar("POST", "/api/v2/product/add_item", payload=corpo, timeout=SHOPEE_ITEM_TIMEOUT)
        except (ShopeeRecusou, ShopeeSemResposta) as exc:
            _anuncio_amostra("shopee_add_item [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None),
                                                        "enviado": corpo})
            if _shopee_talvez_fez(exc):  # revisao: erro interno/ocupado/tempo = a Shopee pode ter criado
                return fim("incerto", [SHOPEE_INCERTO_TEXTO, f"Detalhe: {exc}"])
            estado["etapa"] = "antes"
            return fim("erro", [f"A Shopee recusou: {exc}"])
        _anuncio_amostra("shopee_add_item", resp)
        item_id = str(_shopee_resposta(resp).get("item_id") or "")
        if not item_id.isdigit():
            return fim("incerto", [SHOPEE_INCERTO_TEXTO, "A Shopee respondeu sem o número do item."])
        estado["item_id"] = item_id
        with DB_LOCK:
            try:
                cur = DB.execute("UPDATE anuncio_rascunho_shopee_v2032 SET situacao='publicado', item_id=?, erros_json='[]', "
                                 "versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='publicando'",
                                 (item_id, now_iso(), str(ator or ""), rid))
                if cur.rowcount == 1:
                    _shopee_canal_noromak(item_id, r, ator)
                DB.commit()
            except Exception:
                DB.rollback()
                raise
            estado["fim"] = _shopee_rascunho_de_linha(
                DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone())
        audit(ator, "anuncios.shopee_publicar", f"{cod}|{rid}|publicado|{item_id}")
        return {"ok": True, "situacao": "publicado", "item_id": item_id, "erros": [], "rascunho": estado["fim"]}
    finally:
        if estado["fim"] is None:
            try:
                if estado["etapa"] == "antes":
                    fim("validado", ["Falha inesperada antes de criar o anúncio; nada foi criado na Shopee."])
                else:
                    # revisao: o numero do item, quando ja veio, nunca se perde
                    fim("incerto", [SHOPEE_INCERTO_TEXTO], item_id=estado["item_id"])
            except Exception as exc:
                print(f"Aviso: rascunho Shopee {rid} nao saiu de publicando: {exc}", file=sys.stderr)


def shopee_publicar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.32: reserva e publica (sincrono; a rota usa shopee_publicar_iniciar, em segundo plano)."""
    return shopee_publicar_executar(shopee_publicar_reservar(rascunho_id, ator), ator)


def shopee_publicar_iniciar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """Revisao (06/11): fotos + add_item passavam dos 60 s do nginx (504 com o anuncio criado). A rota reserva aqui
    (erro = 400 na hora) e o resto roda numa thread que solta o ANUNCIOS_PUBLICAR_LOCK no fim. A tela acompanha
    pelos rascunhos ate sair de `publicando`. Chamar COM o ANUNCIOS_PUBLICAR_LOCK pego."""
    r = shopee_publicar_reservar(rascunho_id, ator)
    resposta = {"ok": True, "iniciado": True, "rascunho": shopee_rascunho_ler(r["id"])}  # 2a revisao: antes do start

    def rodar() -> None:
        try:
            shopee_publicar_executar(r, ator)
        except Exception as exc:
            print(f"Aviso: publicar na Shopee {r['id']} falhou: {exc}", file=sys.stderr)
        finally:
            ANUNCIOS_PUBLICAR_LOCK.release()
    try:
        threading.Thread(target=rodar, name=f"shopee-publicar-{r['id']}", daemon=True).start()
    except BaseException:
        # nada saiu: volta a `validado` (a rota solta a trava); nunca fica preso em `publicando`
        _shopee_trocar(int(r["id"]), ("publicando",), "validado", ["A publicação não começou; tente de novo."], ator)
        raise
    return resposta


def shopee_incerto_liberar(rascunho_id: Any, item_id: Any, ator: str) -> dict[str, Any]:
    """V20.32: o Admin conferiu no Seller Center: com o numero do item = `publicado` (entra na lista); sem = volta a
    `validado`. Nao chama a Shopee. Item ja na lista com outro produto e recusado."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    texto = str(item_id or "").strip()
    if texto and not texto.isdigit():  # revisao: so numero (antes "55 5x" virava 555 calado)
        raise ValueError("Número do item inválido (só números, como aparece no Seller Center).")
    if texto:  # revisao: confere na Shopee que o item e deste produto (fora do DB_LOCK)
        pre = shopee_rascunho_ler(rid)
        if pre is None:
            raise ValueError("Rascunho não encontrado.")
        try:
            lido = _shopee_estoque_ler(texto)
        except (ShopeeRecusou, ShopeeSemResposta) as exc:
            raise ValueError(f"Não consegui conferir o item {texto} na Shopee ({exc}). Nada foi alterado.")
        if not lido.get("existe"):
            raise ValueError(f"A Shopee não achou o item {texto} nesta loja. Confira o número; nada foi alterado.")
        if normalize(lido.get("sku")) != normalize(pre["ficha_codigo"]):
            raise ValueError(f"O item {texto} na Shopee tem o SKU {lido.get('sku') or '(vazio)'}, não "
                             f"{pre['ficha_codigo']}: não é deste produto. Nada foi alterado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _shopee_rascunho_de_linha(row)
        if r["situacao"] != "incerto":
            raise ValueError("Só um rascunho sem resposta da Shopee (incerto) pode ser liberado.")
        if texto:
            ja = DB.execute("SELECT ficha_codigo, controle FROM anuncio_canal_v2023 WHERE canal='shopee' AND anuncio_id=?",
                            (texto,)).fetchone()
            if ja and (str(ja["ficha_codigo"] or "") != str(r["ficha_codigo"]) or str(ja["controle"] or "") != "noromak"):
                raise ValueError(f"O item {texto} já está na lista com outro produto ou outro controle. Nada foi alterado.")
        para = "publicado" if texto else "validado"
        try:
            DB.execute("UPDATE anuncio_rascunho_shopee_v2032 SET situacao=?, item_id=?, erros_json='[]', versao=versao+1, "
                       "atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='incerto'",
                       (para, texto or None, now_iso(), str(ator or ""), rid))
            if texto:
                _shopee_canal_noromak(texto, r, ator)
            DB.commit()
        except Exception:
            DB.rollback()
            raise
        novo = _shopee_rascunho_de_linha(DB.execute("SELECT * FROM anuncio_rascunho_shopee_v2032 WHERE id=?", (rid,)).fetchone())
    audit(ator, "anuncios.shopee_liberar", f"{r['ficha_codigo']}|{rid}|{para}|{texto}")
    return {"ok": True, "situacao": para, "item_id": texto, "rascunho": novo}


# ---------------------------------------------------------------------------
# V20.41 - Criar anuncio no TikTok Shop (Bauru) pela plataforma de anuncios (decisoes do dono, 07/11). Molde: a
# Shopee (V20.32). Construido pela documentacao da Open API 202309, sem resposta real: a 1a resposta de cada chamada
# fica em anuncio_amostra_v2024 (tipos tiktok_*) e, mascarada, em tiktok_amostra_v1963 - CONFERIR no 1o uso.
# - Leituras (categorias, sugestao, atributos, regras, marcas, deposito) pelo tiktok_api, cache de 24 h.
# - Escritas (foto, listing_check, criar) pelo _tiktok_chamar, que separa RECUSA (nada feito) de SEM RESPOSTA (pode
#   ter feito). Publicar = so com a fonte "api" (V20.40), perfil Admin, ANUNCIOS_PUBLICAR_LOCK, em segundo plano.
# - Preco digitado pelo Admin (o preco ideal do TikTok so sugere); estoque inicial = Apollo de Bauru lido AGORA menos
#   o vendido e nao baixado em Bauru (so pode ser menor); peso e medidas sempre da ficha na hora.
# - Publicado = linha canal='tiktok', conta='bauru', anuncio_id = id da variacao, user_product_id = product_id,
#   controle 'noromak', estoque Manual; e tiktok_sku_v1964 (espelho V20.40 e tela Estoque TikTok).
# ---------------------------------------------------------------------------
TIKTOK_ANUNCIO_CONTA = TIKTOK_CASA
TIKTOK_LEITURA_CACHE_S = 24 * 3600
TIKTOK_ANUNCIO_TITULO_MAX = 255
TIKTOK_ANUNCIO_DESC_MAX = 10000
TIKTOK_ANUNCIO_FOTOS_MAX = 9
TIKTOK_ANUNCIO_ITEM_TIMEOUT = 90
TIKTOK_ANUNCIO_UPLOAD_TIMEOUT = 60
TIKTOK_MARCAS_PAGINAS = 20  # revisar-antes-de-subir (V20.41): menos páginas por pedido (504); o resto pela busca do nome
TIKTOK_FOTO_HOSTS = ("tiktokcdn.com", "ibyteimg.com", "tiktokcdn-us.com", "ttwstatic.com")
TIKTOK_RASCUNHO_EDITAVEL = ("rascunho", "validado", "erro")
TIKTOK_RASCUNHO_CAMPOS = ("titulo", "categoria", "categoria_nome", "descricao", "preco", "quantidade")
TIKTOK_INCERTO_TEXTO = ("O TikTok não respondeu ao criar o anúncio: ele pode ter sido criado. Confira no Seller Center "
                        "(Produtos) e informe o número do produto (product_id), ou libere sem número se ele não existe. "
                        "Nada é repetido sozinho.")
_TIKTOK_LEITURA_CACHE: dict[tuple[str, str], tuple[float, Any]] = {}
_TIKTOK_LEITURA_LOCK = threading.Lock()
# Erro do lado do TikTok (interno, ocupado, tempo) numa ESCRITA pode ter feito: no criar vira `incerto`.
_TIKTOK_ERRO_TALVEZ_FEZ = re.compile(r"internal|server|busy|time[ _-]?out|system|unknown|retry", re.I)


class TikTokSemResposta(Exception):
    """V20.41: rede, timeout, 5xx ou resposta ilegivel: o TikTok PODE ter feito."""


class TikTokRecusou(Exception):
    """V20.41: o TikTok respondeu com recusa (ou a chamada nem saiu): nada foi feito no TikTok."""

    def __init__(self, mensagem: str, corpo: Any = None, status: int | None = None) -> None:
        super().__init__(mensagem)
        self.corpo = corpo
        self.status = status


class TikTokFonteNaoApi(ValueError):
    """V20.41: a fonte do TikTok e a extensao do Seller Center: a plataforma nao cria anuncio pela API (409)."""


def _tiktok_talvez_fez(exc: Exception) -> bool:
    if isinstance(exc, TikTokSemResposta):
        return True
    if isinstance(exc, TikTokRecusou):
        if exc.status == 408 or (exc.status or 0) >= 500:
            return True
        msg = str((exc.corpo or {}).get("message") or "") if isinstance(exc.corpo, dict) else ""
        return bool(_TIKTOK_ERRO_TALVEZ_FEZ.search(msg))
    return False


def _tiktok_http_bruto(metodo: str, url: str, token: str, corpo: bytes | None, tipo: str,
                       timeout: float) -> tuple[int, str]:
    """V20.41: so a rede (isolada para o teste). (status, texto); falha de rede = TikTokSemResposta."""
    req = urllib.request.Request(url, method=metodo, data=corpo, headers={
        "x-tts-access-token": token, "Content-Type": tipo, "Accept": "application/json"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return int(resp.status or 200), resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as exc:
        return int(exc.code), exc.read().decode("utf-8", "replace")
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise TikTokSemResposta(f"sem resposta do TikTok ({exc})")


def _tiktok_chamar(metodo: str, path: str, params: dict[str, Any] | None = None, body: Any = None, *,
                   multipart: tuple[dict[str, str], tuple[str, str, bytes, str]] | None = None,
                   timeout: float = 35, amostra: str = "") -> dict[str, Any]:
    """V20.41: chamada da loja que separa RECUSA de SEM RESPOSTA (o tiktok_api, que as leituras usam, devolve so
    RuntimeError e nao muda). Multipart: a assinatura do TikTok NAO inclui o corpo (so caminho + parametros)."""
    try:
        token = tiktok_access_token()
        row = tiktok_integration_row()
        cipher = str(row["shop_cipher"] or "").strip() if row else ""
        if not cipher:
            cipher = tiktok_buscar_loja()
    except Exception as exc:
        raise TikTokRecusou(f"TikTok sem conexão: {exc}")
    query = {k: str(v) for k, v in (params or {}).items() if v is not None and v != ""}
    query.update({"app_key": TIKTOK_APP_KEY, "timestamp": str(int(time.time())), "shop_cipher": cipher})
    if multipart is not None:
        corpo_b, tipo = _shopee_multipart(*multipart)
        query["sign"] = tiktok_assinar(path, query, "")
    else:
        texto_corpo = json.dumps(body, ensure_ascii=False, separators=(",", ":")) if body is not None else ""
        corpo_b, tipo = (texto_corpo.encode("utf-8") if texto_corpo else None), "application/json"
        query["sign"] = tiktok_assinar(path, query, texto_corpo)
    status, texto = _tiktok_http_bruto(metodo, TIKTOK_API_BASE + path + "?" + urlencode(query), token, corpo_b, tipo,
                                       timeout)
    dados = _anuncio_json_ou_none(texto)
    if status >= 500:
        raise TikTokSemResposta(f"TikTok HTTP {status}: {texto[:300]}")
    if not isinstance(dados, dict):
        if status >= 400:
            raise TikTokRecusou(f"TikTok HTTP {status}: {texto[:300]}", texto[:2000], status=status)
        raise TikTokSemResposta("resposta ilegível do TikTok")
    rota = f"{metodo} " + re.sub(r"/products/\d+", "/products/{id}", path)
    ok = status < 400 and int(dados.get("code") or 0) == 0
    _tiktok_guardar_amostra(rota if ok else rota + " [erro]", _tiktok_sc_mascarar(dados))
    if amostra:
        _anuncio_amostra(amostra if ok else amostra + " [erro]", dados)
    if not ok:
        raise TikTokRecusou(f"TikTok {path}: {dados.get('code')} {dados.get('message') or ''}".strip(), dados,
                            status=status)
    return dados


def _tiktok_ler(metodo: str, path: str, params: dict[str, Any] | None = None, body: Any = None,
                amostra: str = "") -> dict[str, Any]:
    """V20.41: leitura pelo tiktok_api (ja assina e guarda a amostra mascarada). Falha = RuntimeError."""
    try:
        resp = tiktok_api(metodo, path, params=params, body=body)
    except Exception as exc:
        if amostra:
            _anuncio_amostra(f"{amostra} [erro]", {"erro": str(exc)[:1000]})
        raise RuntimeError(str(exc))
    if amostra:
        _anuncio_amostra(amostra, resp)
    d = resp.get("data") if isinstance(resp, dict) else None
    return d if isinstance(d, dict) else {}


def _tiktok_cache(chave: tuple[str, str], ler: Any) -> Any:
    agora = time.time()
    with _TIKTOK_LEITURA_LOCK:
        hit = _TIKTOK_LEITURA_CACHE.get(chave)
        if hit and agora - hit[0] < TIKTOK_LEITURA_CACHE_S:
            return hit[1]
    valor = ler()
    with _TIKTOK_LEITURA_LOCK:
        if len(_TIKTOK_LEITURA_CACHE) > 500:
            _TIKTOK_LEITURA_CACHE.clear()
        _TIKTOK_LEITURA_CACHE[chave] = (agora, valor)
    return valor


def tiktok_categorias() -> dict[str, dict[str, Any]]:
    """V20.41: arvore de categorias da loja: id -> {id, nome, pai, folha}."""
    def ler() -> dict[str, dict[str, Any]]:
        d = _tiktok_ler("GET", "/product/202309/categories", None, None, "tiktok_categorias")
        saida: dict[str, dict[str, Any]] = {}
        for c in d.get("categories") or []:
            if not isinstance(c, dict) or c.get("id") in (None, ""):
                continue
            cid = str(c["id"])
            saida[cid] = {"id": cid, "nome": str(c.get("local_name") or c.get("name") or cid),
                          "pai": str(c.get("parent_id") or ""), "folha": bool(c.get("is_leaf"))}
        if not saida:
            raise RuntimeError("o TikTok devolveu a lista de categorias vazia")
        return saida
    return _tiktok_cache(("categorias", ""), ler)


def _tiktok_caminho(cid: str, cats: dict[str, dict[str, Any]]) -> str:
    nomes: list[str] = []
    atual, voltas = str(cid), 0
    while atual and atual in cats and voltas < 10:
        nomes.append(cats[atual]["nome"])
        atual, voltas = cats[atual]["pai"], voltas + 1
    return " > ".join(reversed(nomes))


def tiktok_categoria_sugerir(titulo: str) -> list[dict[str, Any]]:
    """V20.41: categoria sugerida pelo TikTok para o titulo (categories/recommend), com nome e caminho."""
    titulo = " ".join(str(titulo or "").split())
    if not titulo:
        raise ValueError("Informe o título.")
    d = _tiktok_ler("POST", "/product/202309/categories/recommend", None, {"product_title": titulo[:255]},
                    "tiktok_categoria_sugerir")
    try:
        cats = tiktok_categorias()
    except RuntimeError:
        cats = {}
    ids: list[str] = []
    if d.get("leaf_category_id") not in (None, ""):
        ids.append(str(d["leaf_category_id"]))
    for c in d.get("categories") or []:
        if isinstance(c, dict) and c.get("id") not in (None, ""):
            cid = str(c["id"])
            if cid not in ids and (c.get("is_leaf") or cid in cats and cats[cid]["folha"]):
                ids.append(cid)
    saida = []
    for cid in ids:
        c = cats.get(cid)
        nome = c["nome"] if c else next((str(x.get("name") or cid) for x in d.get("categories") or []
                                         if isinstance(x, dict) and str(x.get("id")) == cid), cid)
        saida.append({"categoria": cid, "nome": nome, "caminho": _tiktok_caminho(cid, cats) if c else nome,
                      "folha": bool(c["folha"]) if c else True})
    return saida


def tiktok_categoria_atributos(categoria: Any) -> dict[str, Any]:
    """V20.41: atributos do PRODUTO da categoria (os de venda/variacao ficam fora: um SKU so). `obrigatorio` =
    is_requried (grafia da doc) ou is_required; `livre` = aceita texto (is_customizable)."""
    cid = str(categoria or "").strip()
    if not cid.isdigit():
        raise ValueError("Categoria do TikTok inválida.")

    def ler() -> dict[str, Any]:
        d = _tiktok_ler("GET", f"/product/202309/categories/{cid}/attributes", None, None, "tiktok_atributos")
        lista = []
        for a in d.get("attributes") or []:
            if not isinstance(a, dict) or a.get("id") in (None, ""):
                continue
            if str(a.get("type") or "PRODUCT_PROPERTY").upper() != "PRODUCT_PROPERTY":
                continue
            valores = [{"id": str(v.get("id")), "nome": str(v.get("name") or v.get("id"))}
                       for v in a.get("values") or [] if isinstance(v, dict) and v.get("id") not in (None, "")]
            lista.append({"id": str(a["id"]), "nome": str(a.get("name") or a["id"]),
                          "obrigatorio": bool(a.get("is_requried") or a.get("is_required")),
                          "livre": bool(a.get("is_customizable")) or not valores, "valores": valores,
                          "multiplo": bool(a.get("is_multiple_selection"))})
        return {"categoria": cid, "atributos": lista}
    return _tiktok_cache(("atributos", cid), ler)


def tiktok_categoria_regras(categoria: Any) -> dict[str, Any]:
    """V20.41: o que a categoria exige (categories/{id}/rules): medidas do pacote, tabela de medidas, certificados."""
    cid = str(categoria or "").strip()
    if not cid.isdigit():
        raise ValueError("Categoria do TikTok inválida.")

    def ler() -> dict[str, Any]:
        d = _tiktok_ler("GET", f"/product/202309/categories/{cid}/rules", None, None, "tiktok_regras")
        pd_ = d.get("package_dimension") if isinstance(d.get("package_dimension"), dict) else {}
        sc = d.get("size_chart") if isinstance(d.get("size_chart"), dict) else {}
        certs = [str(c.get("name") or c.get("id")) for c in d.get("product_certifications") or d.get("certifications") or []
                 if isinstance(c, dict) and (c.get("is_required") or c.get("is_requried"))]
        return {"categoria": cid, "medidas_obrigatorias": bool(pd_.get("is_required")),
                "tabela_medidas_obrigatoria": bool(sc.get("is_required")), "certificados_obrigatorios": certs}
    return _tiktok_cache(("regras", cid), ler)


def tiktok_marcas(categoria: Any) -> dict[str, Any]:
    """V20.41: marcas da categoria (brands, paginado por page_token)."""
    cid = str(categoria or "").strip()
    if not cid.isdigit():
        raise ValueError("Categoria do TikTok inválida.")

    def ler() -> dict[str, Any]:
        marcas: list[dict[str, str]] = []
        token = ""
        for pagina in range(TIKTOK_MARCAS_PAGINAS):
            d = _tiktok_ler("GET", "/product/202309/brands", {"category_id": cid, "page_size": 100, "page_token": token},
                            None, "tiktok_marcas" if pagina == 0 else "")
            for b in d.get("brands") or []:
                if isinstance(b, dict) and b.get("id") not in (None, ""):
                    marcas.append({"id": str(b["id"]), "nome": str(b.get("name") or "")})
            token = str(d.get("next_page_token") or "")
            if not token:
                break
        # revisar-antes-de-subir (V20.41): sobrou página = lista incompleta (a marca da ficha é buscada pelo nome)
        return {"categoria": cid, "marcas": marcas, "incompleta": bool(token)}
    return _tiktok_cache(("marcas", cid), ler)


def tiktok_marca_buscar(categoria: Any, nome: Any) -> dict[str, str] | None:
    """revisar-antes-de-subir (V20.41): a marca da ficha pelo nome (brand_name), quando a lista da categoria veio cortada."""
    cid, alvo = str(categoria or "").strip(), str(nome or "").strip()
    if not cid.isdigit() or not alvo:
        return None
    try:
        d = _tiktok_ler("GET", "/product/202309/brands", {"category_id": cid, "brand_name": alvo, "page_size": 100},
                        None, "tiktok_marcas_busca")
    except Exception:
        return None
    lista = {"marcas": [{"id": str(b["id"]), "nome": str(b.get("name") or "")} for b in d.get("brands") or []
                        if isinstance(b, dict) and b.get("id") not in (None, "")]}
    return tiktok_marca_da_ficha(alvo, lista)


def tiktok_marca_da_ficha(marca: Any, lista: dict[str, Any]) -> dict[str, str] | None:
    """V20.41 (pura): a marca da ficha na lista do TikTok (sem acento/caixa/espaco)."""
    alvo = re.sub(r"\s+", "", _anuncio_sem_acento(marca))
    if not alvo:
        return None
    for b in lista.get("marcas") or []:
        if re.sub(r"\s+", "", _anuncio_sem_acento(b.get("nome"))) == alvo:
            return {"id": str(b["id"]), "nome": str(b.get("nome"))}
    return None


def tiktok_deposito_venda() -> dict[str, Any]:
    """V20.41: o UNICO deposito de venda ativo da loja. Nenhum ou mais de um = erro listando (nunca escolhe)."""
    def ler() -> list[dict[str, Any]]:
        d = _tiktok_ler("GET", "/logistics/202309/warehouses", None, None, "tiktok_depositos")
        return [w for w in d.get("warehouses") or [] if isinstance(w, dict)]
    lista = _tiktok_cache(("depositos", ""), ler)
    ativos = [w for w in lista if str(w.get("type") or "").upper() == "SALES_WAREHOUSE"
              and str(w.get("effect_status") or "ENABLED").upper() in ("ENABLED", "")]
    if len(ativos) != 1 or not str(ativos[0].get("id") or ""):
        nomes = ", ".join(f"{w.get('name') or '?'} ({w.get('id') or 'sem id'})" for w in ativos) or "nenhum"
        raise RuntimeError(f"a loja tem {len(ativos)} depósitos de venda ativos no TikTok ({nomes}): o Noromak não "
                           "escolhe o depósito — ajuste no Seller Center")
    return {"id": str(ativos[0]["id"]), "nome": str(ativos[0].get("name") or "")}


def _tiktok_descricao_html(texto: str) -> str:
    """V20.41 (pura): texto da ficha -> HTML simples (paragrafos e quebras), tudo escapado."""
    blocos = [b.strip() for b in re.split(r"\n\s*\n", str(texto or "").replace("\r\n", "\n")) if b.strip()]
    return "".join("<p>" + "<br>".join(html_module.escape(l.strip()) for l in b.split("\n")) + "</p>" for b in blocos)


def _tiktok_html_texto(htm: Any) -> str:
    """V20.41 (pura): descricao HTML do TikTok -> texto (quebras nos paragrafos/itens; sem tags)."""
    t = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", "", str(htm or ""))
    t = re.sub(r"(?i)<br\s*/?>", "\n", t)
    t = re.sub(r"(?i)</(p|div|li|h[1-6])\s*>", "\n", t)
    t = re.sub(r"(?i)<li[^>]*>", "- ", t)
    t = html_module.unescape(re.sub(r"<[^>]+>", "", t))
    linhas = [re.sub(r"[ \t]+", " ", l).strip() for l in t.split("\n")]
    return re.sub(r"\n{3,}", "\n\n", "\n".join(linhas)).strip()


# ---- rascunho ----
def _tiktok_rascunho_de_linha(row: Any) -> dict[str, Any]:
    d = dict(row)
    for campo, padrao in (("atributos_json", {}), ("fotos_json", []), ("erros_json", []), ("marca_json", {})):
        try:
            v = json.loads(d.pop(campo) or "")
        except (TypeError, ValueError):
            v = padrao
        d[campo[:-5]] = v if isinstance(v, type(padrao)) else padrao
    d["canal"] = "tiktok"
    return d


def tiktok_rascunho_ler(rid: Any) -> dict[str, Any] | None:
    try:
        n = int(rid)
    except (TypeError, ValueError):
        return None
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (n,)).fetchone()
    return _tiktok_rascunho_de_linha(row) if row else None


def tiktok_rascunhos_da_ficha(codigo: str) -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE ficha_codigo=? ORDER BY id DESC",
                          (normalize(codigo),)).fetchall()
    return [_tiktok_rascunho_de_linha(r) for r in rows]


def _tiktok_rascunho_limpar(dados: dict[str, Any]) -> dict[str, Any]:
    """V20.41: so os campos que vieram, conferidos (tipo e tamanho). Mesma regra da Shopee."""
    base = {k: v for k, v in dados.items() if k not in ("atributos", "fotos", "marca")}
    cat = str(base.get("categoria") or "").strip() if "categoria" in base else ""
    if cat and not cat.isdigit():
        raise ValueError("Categoria do TikTok inválida.")
    out = _shopee_rascunho_limpar(base)  # titulo, categoria, descricao, preco, quantidade: mesmas conferencias
    if "titulo" in dados:
        out["titulo"] = " ".join(str(dados.get("titulo") or "").split())[:TIKTOK_ANUNCIO_TITULO_MAX]
    if "atributos" in dados:
        brutos = dados.get("atributos") if isinstance(dados.get("atributos"), dict) else {}
        attrs: dict[str, dict[str, str]] = {}
        for k, v in brutos.items():
            if not str(k).isdigit() or not isinstance(v, dict):
                continue
            item = {"valor_id": str(v.get("valor_id") or "").strip(),
                    "valor": " ".join(str(v.get("valor") or "").split())[:255]}
            if item["valor_id"] and not item["valor_id"].isdigit():
                continue
            if item["valor_id"] or item["valor"]:
                attrs[str(k)] = item
        out["atributos"] = attrs
    if "marca" in dados:
        m = dados.get("marca") if isinstance(dados.get("marca"), dict) else {}
        mid = str(m.get("id") or "").strip()
        out["marca"] = {"id": mid, "nome": str(m.get("nome") or "")[:120]} if mid.isdigit() else {}
    if "fotos" in dados:
        brutas = dados.get("fotos") or []
        if not isinstance(brutas, list) or any(isinstance(x, bool) for x in brutas):
            raise ValueError("Fotos inválidas.")
        try:
            fotos = list(dict.fromkeys(int(x) for x in brutas))
        except (TypeError, ValueError):
            raise ValueError("Fotos inválidas.")
        if len(fotos) > TIKTOK_ANUNCIO_FOTOS_MAX:
            raise ValueError(f"O TikTok aceita até {TIKTOK_ANUNCIO_FOTOS_MAX} fotos.")
        out["fotos"] = fotos
    return out


def tiktok_rascunho_salvar(dados: dict[str, Any], ator: str, versao: Any) -> dict[str, Any]:
    """V20.41: cria (sem `id`, com `codigo`) ou atualiza (com `id`; `versao` conferida, senao FichaConflito)."""
    dados = dados if isinstance(dados, dict) else {}
    limpos = _tiktok_rascunho_limpar(dados)
    agora = now_iso()
    with DB_LOCK:
        rid = dados.get("id")
        if rid in (None, ""):
            cod = normalize(dados.get("codigo"))
            if not cod or _ficha_ler_sem_lock(cod) is None:
                raise ValueError("Produto não encontrado.")
            cur = DB.execute(
                "INSERT INTO anuncio_rascunho_tiktok_v2041(ficha_codigo,titulo,categoria,categoria_nome,atributos_json,"
                "marca_json,fotos_json,descricao,preco,quantidade,situacao,versao,criado_em,criado_por,atualizado_em,"
                "atualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,'rascunho',1,?,?,?,?)",
                (cod, limpos.get("titulo", ""), limpos.get("categoria", ""), limpos.get("categoria_nome", ""),
                 json.dumps(limpos.get("atributos", {}), ensure_ascii=False),
                 json.dumps(limpos.get("marca", {}), ensure_ascii=False), json.dumps(limpos.get("fotos", [])),
                 limpos.get("descricao", ""), limpos.get("preco"), limpos.get("quantidade"), agora, str(ator or ""),
                 agora, str(ator or "")))
            novo_id = int(cur.lastrowid)
        else:
            row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (rid,)).fetchone()
            if row is None:
                raise ValueError("Rascunho não encontrado.")
            atual = _tiktok_rascunho_de_linha(row)
            try:
                ok_versao = versao is not None and int(versao) == int(atual["versao"])
            except (TypeError, ValueError):
                ok_versao = False
            if not ok_versao:
                raise FichaConflito(atual)
            if atual["situacao"] not in TIKTOK_RASCUNHO_EDITAVEL:
                raise ValueError("Este rascunho já foi publicado ou está em publicação; não pode mais ser editado.")
            novo = {k: limpos.get(k, atual.get(k)) for k in TIKTOK_RASCUNHO_CAMPOS}
            trocou_cat = "categoria" in limpos and limpos["categoria"] != str(atual.get("categoria") or "")
            attrs = limpos.get("atributos", {} if trocou_cat else atual.get("atributos") or {})
            marca = limpos.get("marca", {} if trocou_cat else atual.get("marca") or {})  # marca e da lista da categoria
            fotos = limpos.get("fotos", atual.get("fotos") or [])
            mudou = (any(novo[k] != atual.get(k) for k in TIKTOK_RASCUNHO_CAMPOS) or attrs != (atual.get("atributos") or {})
                     or marca != (atual.get("marca") or {}) or fotos != (atual.get("fotos") or []))
            if not mudou:
                return atual
            situacao = "rascunho" if atual["situacao"] == "validado" else atual["situacao"]
            DB.execute(
                "UPDATE anuncio_rascunho_tiktok_v2041 SET titulo=?,categoria=?,categoria_nome=?,atributos_json=?,marca_json=?,"
                "fotos_json=?,descricao=?,preco=?,quantidade=?,situacao=?,versao=versao+1,atualizado_em=?,atualizado_por=? "
                "WHERE id=?",
                (novo["titulo"], novo["categoria"], novo["categoria_nome"], json.dumps(attrs, ensure_ascii=False),
                 json.dumps(marca, ensure_ascii=False), json.dumps(fotos), novo["descricao"], novo["preco"],
                 novo["quantidade"], situacao, agora, str(ator or ""), atual["id"]))
            novo_id = int(atual["id"])
        linha_r = DB.execute("SELECT ficha_codigo, fotos_json FROM anuncio_rascunho_tiktok_v2041 WHERE id=?",
                             (novo_id,)).fetchone()
        fotos_ok = json.loads(linha_r["fotos_json"] or "[]")
        if fotos_ok:
            achadas = {int(r["id"]) for r in DB.execute(
                f"SELECT id FROM anuncio_foto_v2024 WHERE ficha_codigo=? AND id IN ({','.join('?' * len(fotos_ok))})",
                (linha_r["ficha_codigo"], *fotos_ok))}
            if achadas != set(fotos_ok):
                DB.rollback()
                raise ValueError("Há foto que não pertence a este produto.")
        DB.commit()
        row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (novo_id,)).fetchone()
    return _tiktok_rascunho_de_linha(row)


def _tiktok_trocar(rid: int, de: tuple[str, ...], para: str, erros: list[str], ator: str, *,
                   product_id: str | None = None, sku_id: str | None = None,
                   versao: int | None = None) -> dict[str, Any] | None:
    with DB_LOCK:
        extra, args_v = ("", ()) if versao is None else (" AND versao=?", (int(versao),))
        cur = DB.execute(
            f"UPDATE anuncio_rascunho_tiktok_v2041 SET situacao=?, erros_json=?, product_id=COALESCE(?,product_id), "
            f"sku_id=COALESCE(?,sku_id), versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? "
            f"AND situacao IN ({','.join('?' * len(de))})" + extra,
            (para, json.dumps(list(erros), ensure_ascii=False), product_id, sku_id, now_iso(), str(ator or ""), rid,
             *de, *args_v))
        DB.commit()
        if cur.rowcount != 1:
            return None
        row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (rid,)).fetchone()
    return _tiktok_rascunho_de_linha(row)


def _tiktok_conferir_local(r: dict[str, Any]) -> tuple[list[str], dict[str, Any]]:
    """V20.41: confere o rascunho contra o que o TikTok publica (categoria folha, atributos, regras, marca, deposito)
    e a ficha (peso, medidas). Devolve (erros, contexto do corpo). Leitura que falha = erro (nunca adivinha)."""
    erros: list[str] = []
    ctx: dict[str, Any] = {"avisos": []}
    ficha = ficha_ler(r["ficha_codigo"]) or {}
    campos = ficha.get("campos") or {}
    titulo = str(r.get("titulo") or "").strip()
    if not titulo:
        erros.append("Informe o título.")
    elif len(titulo) > TIKTOK_ANUNCIO_TITULO_MAX:
        erros.append(f"Título com {len(titulo)} caracteres: o TikTok aceita até {TIKTOK_ANUNCIO_TITULO_MAX}.")
    desc = str(r.get("descricao") or "").strip()
    if not desc:
        erros.append("Informe a descrição.")
    elif len(desc) > TIKTOK_ANUNCIO_DESC_MAX:
        erros.append(f"Descrição longa: até {TIKTOK_ANUNCIO_DESC_MAX} caracteres.")
    if "[CONFIRMAR]" in desc.upper():
        erros.append("A descrição ainda tem [CONFIRMAR]: troque pelo texto certo.")
    fotos = list(r.get("fotos") or [])
    if not fotos:
        erros.append("Escolha pelo menos uma foto.")
    elif len(fotos) > TIKTOK_ANUNCIO_FOTOS_MAX:
        erros.append(f"{len(fotos)} fotos: o TikTok aceita até {TIKTOK_ANUNCIO_FOTOS_MAX}.")
    else:
        with DB_LOCK:
            tipos = {int(x["id"]): str(x["tipo"]) for x in DB.execute(
                f"SELECT id, tipo FROM anuncio_foto_v2024 WHERE id IN ({','.join('?' * len(fotos))})", fotos)}
        for pos, fid in enumerate(fotos, 1):
            if tipos.get(int(fid)) not in ("jpg", "png", "webp"):
                erros.append(f"Foto {pos}: o TikTok aceita JPG, PNG ou WEBP (troque a foto).")
    preco = r.get("preco")
    if not preco or float(preco) <= 0:
        erros.append("Informe o preço.")
    if not r.get("quantidade") or int(r["quantidade"]) < 1:
        erros.append("Informe a quantidade.")
    peso, medidas, falta = _shopee_pacote_da_ficha(campos)  # peso (kg) e medidas (cm) lidos da FICHA agora
    ctx["peso"], ctx["medidas"] = peso, medidas
    if falta:
        erros.append(f"Falta na ficha (Peso e medidas): {', '.join(falta)}. Preencha a ficha do produto.")
    cat = str(r.get("categoria") or "")
    if not cat:
        erros.append("Escolha a categoria.")
        return erros, ctx
    try:
        cats = tiktok_categorias()
        if cat in cats and not cats[cat]["folha"]:
            erros.append("A categoria escolhida tem subcategorias: escolha a mais específica.")
        defs = tiktok_categoria_atributos(cat)["atributos"]
        regras = tiktok_categoria_regras(cat)
        marcas = tiktok_marcas(cat)
    except (RuntimeError, ValueError) as exc:
        erros.append(f"Não consegui ler a categoria no TikTok ({exc}).")
        return erros, ctx
    ctx["defs"] = defs
    attrs = r.get("atributos") or {}
    for d in defs:
        v = attrs.get(d["id"]) or {}
        if d["obrigatorio"] and not (v.get("valor_id") or v.get("valor")):
            erros.append(f"Atributo obrigatório sem valor: {d['nome']}.")
        if v.get("valor_id") and d["valores"] and v["valor_id"] not in {x["id"] for x in d["valores"]}:
            erros.append(f"Valor de {d['nome']} fora da lista do TikTok.")
        if not d["livre"] and v.get("valor") and not v.get("valor_id"):
            erros.append(f"{d['nome']}: escolha um valor da lista do TikTok.")
    if regras.get("tabela_medidas_obrigatoria"):
        erros.append("Esta categoria exige tabela de medidas, que o Noromak não envia: escolha outra categoria ou "
                     "crie pelo Seller Center.")
    if regras.get("certificados_obrigatorios"):
        erros.append("Esta categoria exige certificado (" + ", ".join(regras["certificados_obrigatorios"])
                     + "), que o Noromak não envia: escolha outra categoria ou crie pelo Seller Center.")
    marca = r.get("marca") or {}
    if marca.get("id"):
        if marca["id"] not in {str(b.get("id")) for b in marcas.get("marcas") or []} and not (
                marcas.get("incompleta") and (tiktok_marca_buscar(r.get("categoria"), marca.get("nome")) or {}).get("id")
                == marca["id"]):
            erros.append("A marca escolhida não é da lista desta categoria: escolha de novo.")
    else:
        achada = tiktok_marca_da_ficha(campos.get("marca"), marcas)
        if not achada and marcas.get("incompleta"):  # revisar-antes-de-subir (V20.41): lista cortada → busca pelo nome
            achada = tiktok_marca_buscar(r.get("categoria"), campos.get("marca"))
        if achada:
            marca = achada
        elif str(campos.get("marca") or "").strip():  # nunca "sem marca" calado
            ctx["avisos"].append(f"A marca da ficha ({campos.get('marca')}) não está na lista do TikTok para esta "
                                 "categoria: o anúncio vai sem marca. Escolha a marca se ela existir na lista.")
    ctx["marca"] = marca
    try:
        ctx["deposito"] = tiktok_deposito_venda()
    except RuntimeError as exc:
        erros.append(f"Depósito do TikTok: {exc}.")
    return erros, ctx


def tiktok_produto_corpo(r: dict[str, Any], ficha: dict[str, Any], uris: list[str] | None,
                         ctx: dict[str, Any]) -> dict[str, Any]:
    """V20.41 (pura): corpo do POST /product/202309/products (e do listing_check). `uris` None = sem fotos."""
    medidas = ctx.get("medidas") or {}
    attrs = []
    for aid, v in (r.get("atributos") or {}).items():
        if v.get("valor_id"):
            valores = [{"id": str(v["valor_id"])}]
        elif v.get("valor"):
            valores = [{"name": str(v["valor"])}]
        else:
            continue
        attrs.append({"id": str(aid), "values": valores})
    corpo: dict[str, Any] = {
        "title": str(r.get("titulo") or "").strip(),
        "description": _tiktok_descricao_html(str(r.get("descricao") or "")),
        "category_id": str(r.get("categoria") or ""),
        "skus": [{"seller_sku": str(ficha.get("codigo") or r.get("ficha_codigo") or "")[:50],
                  "price": {"amount": f"{float(r['preco']):.2f}", "currency": "BRL"},
                  "inventory": [{"warehouse_id": str((ctx.get("deposito") or {}).get("id") or ""),
                                 "quantity": int(r.get("quantidade") or 0)}]}],
        "package_weight": {"value": f"{float(ctx.get('peso') or 0):g}", "unit": "KILOGRAM"},
        "package_dimensions": {"length": str(max(1, math.ceil(float(medidas.get("length") or 0)))),
                               "width": str(max(1, math.ceil(float(medidas.get("width") or 0)))),
                               "height": str(max(1, math.ceil(float(medidas.get("height") or 0)))),
                               "unit": "CENTIMETER"},
    }
    if uris is not None:
        corpo["main_images"] = [{"uri": u} for u in uris]
    marca = ctx.get("marca") or {}
    if marca.get("id"):
        corpo["brand_id"] = str(marca["id"])
    if attrs:
        corpo["product_attributes"] = attrs
    return corpo


def _tiktok_motivos_check(dados: dict[str, Any]) -> list[str]:
    """V20.41: motivos do listing_check (leitura tolerante: a doc tem fail_reasons[].reasons ou .reason)."""
    d = dados.get("data") if isinstance(dados.get("data"), dict) else {}
    motivos: list[str] = []
    for f in d.get("fail_reasons") or []:
        if isinstance(f, dict):
            for m in f.get("reasons") or ([f.get("reason") or f.get("message")] if (f.get("reason") or f.get("message")) else []):
                if str(m or "").strip():
                    motivos.append(str(m).strip())
        elif str(f or "").strip():
            motivos.append(str(f).strip())
    return motivos


def tiktok_rascunho_conferir(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: conferencia local e, se ela passou, o "Conferir no TikTok" (listing_check, sem fotos: elas so sobem no
    Publicar; motivo sobre foto e ignorado). listing_check que falha/nao existe = fica a conferencia local (com aviso)."""
    r = tiktok_rascunho_ler(rascunho_id)
    if r is None:
        raise ValueError("Rascunho não encontrado.")
    if r["situacao"] not in TIKTOK_RASCUNHO_EDITAVEL:
        raise ValueError("Este rascunho já foi publicado, está em publicação ou aguarda conferência no Seller Center.")
    erros, ctx = _tiktok_conferir_local(r)
    conferido_tiktok = False
    if not erros:
        corpo = tiktok_produto_corpo(r, ficha_ler(r["ficha_codigo"]) or {"codigo": r["ficha_codigo"]}, None, ctx)
        try:
            resp = _tiktok_chamar("POST", "/product/202309/products/listing_check", body=corpo,
                                  amostra="tiktok_listing_check")
            d = resp.get("data") if isinstance(resp.get("data"), dict) else {}
            motivos = [m for m in _tiktok_motivos_check(resp) if not re.search(r"image|imagem|foto|picture", m, re.I)]
            falhou = str(d.get("check_result") or "").upper() in ("FAILED", "FAIL")
            if falhou and motivos:
                erros.extend(f"O TikTok recusaria: {m}" for m in motivos)
            if falhou and not motivos and not _tiktok_motivos_check(resp):
                # revisar-antes-de-subir (V20.41): recusa sem motivo legível não passa como "conferido pelo TikTok"
                ctx["avisos"].append("O TikTok recusou a conferência sem um motivo legível: confira a amostra "
                                     "tiktok_listing_check. O Publicar é o teste de verdade.")
            else:
                conferido_tiktok = True
        except (TikTokRecusou, TikTokSemResposta) as exc:
            ctx["avisos"].append(f"O TikTok não conferiu ({str(exc)[:200]}): ficou só a conferência do Noromak. O "
                                 "Publicar é o teste de verdade.")
    para = "rascunho" if erros else "validado"
    novo = _tiktok_trocar(int(r["id"]), TIKTOK_RASCUNHO_EDITAVEL, para, erros, ator, versao=int(r["versao"]))
    if novo is None:
        raise FichaConflito(tiktok_rascunho_ler(r["id"]) or {})
    return {"ok": not erros, "situacao": para, "erros": erros, "avisos": ctx.get("avisos") or [],
            "conferido_tiktok": conferido_tiktok, "rascunho": novo}


def tiktok_conta_preco(codigo: str, preco: Any, margens: Any = None) -> dict[str, Any]:
    """V20.41: conta do preco no TikTok para a tela (so le): a regra da V19.84 (custo de BAURU, afiliado, frete,
    tarifa por faixa, imposto) e o preco ideal das margens pedidas. Kit do Cadastro = as pecas (KITn-X/...)."""
    cod = normalize(codigo)
    if not cod:
        raise ValueError("Informe o produto.")
    comp = kit_composicao(cod)
    sku = "/".join((f"KIT{int(c['quantidade'])}-{c['sku']}" if int(c["quantidade"]) > 1 else str(c["sku"]))
                   for c in comp["componentes"]) if comp else cod
    try:
        ms = [float(x) for x in str(margens or "15,20").split(",") if str(x).strip()][:4]
    except ValueError:
        raise ValueError("Margens inválidas.")
    try:
        p = round(float(str(preco).replace(",", ".")), 2) if preco not in (None, "") else None
    except (TypeError, ValueError):
        p = None
    if p is not None and (not math.isfinite(p) or p <= 0):
        p = None
    return tiktok_preco_sku(sku, ms, preco_atual=p)


def _tiktok_ja_anunciado(cod: str) -> str:
    """V20.41: o produto ja tem anuncio no TikTok (na lista, nao removido) ou um rascunho publicando/incerto? SOB o
    DB_LOCK. Devolve o motivo ('' = pode)."""
    ja = DB.execute("SELECT anuncio_id FROM anuncio_canal_v2023 WHERE canal='tiktok' AND ficha_codigo=? "
                    "AND COALESCE(removido_em,'')='' LIMIT 1", (cod,)).fetchone()
    if ja:
        return (f"Este produto já tem anúncio no TikTok (variação {ja['anuncio_id']}). Para outro anúncio, remova o "
                "atual da lista antes.")
    outro = DB.execute("SELECT id FROM anuncio_rascunho_tiktok_v2041 WHERE ficha_codigo=? AND situacao IN "
                       "('publicando','incerto') LIMIT 1", (cod,)).fetchone()
    if outro:
        return f"O rascunho nº {outro['id']} deste produto está publicando ou aguarda conferência no Seller Center."
    return ""


def _tiktok_canal_noromak(product_id: str, sku_id: str, r: dict[str, Any], ator: str, warehouse_id: str = "") -> None:
    """V20.41: anuncio criado pelo Noromak entra na lista (controle 'noromak', estoque Manual) e em tiktok_sku_v1964
    (espelho V20.40 e tela Estoque TikTok). SOB o DB_LOCK."""
    agora = now_iso()
    DB.execute("""INSERT INTO tiktok_sku_v1964(sku_id,product_id,titulo,status,seller_sku,warehouse_id,armazens,qtd_tiktok,visto_em)
                  VALUES(?,?,?,'PENDING',?,?,?,?,?)
                  ON CONFLICT(sku_id) DO UPDATE SET product_id=excluded.product_id, seller_sku=excluded.seller_sku""",
               (sku_id, product_id, str(r.get("titulo") or ""), r["ficha_codigo"], warehouse_id, 1 if warehouse_id else 0,
                r.get("quantidade"), agora))
    DB.execute(
        "INSERT INTO anuncio_canal_v2023(canal,conta,anuncio_id,ficha_codigo,sku_anuncio,controle,titulo,preco,estoque,"
        "status,categoria,user_product_id,lido_em,controle_em,controle_por) "
        "VALUES('tiktok',?,?,?,?,'noromak',?,?,?,'under_review',?,?,?,?,?) "
        "ON CONFLICT(canal,conta,anuncio_id) DO UPDATE SET ficha_codigo=excluded.ficha_codigo,controle='noromak',"
        "user_product_id=excluded.user_product_id,controle_em=excluded.controle_em,controle_por=excluded.controle_por",
        (TIKTOK_ANUNCIO_CONTA, sku_id, r["ficha_codigo"], r["ficha_codigo"], str(r.get("titulo") or ""), r.get("preco"),
         r.get("quantidade"), str(r.get("categoria") or ""), product_id, agora, agora, str(ator or "")))


def tiktok_publicar_reservar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: so com a fonte "api" (senao TikTokFonteNaoApi, 409). Confere e troca `validado -> publicando` sob o
    DB_LOCK (um anuncio por rascunho e por produto). Erro aqui = nada mudou."""
    if tiktok_fonte() != "api":
        raise TikTokFonteNaoApi("A fonte do TikTok é a extensão do Seller Center: criar anúncio pela plataforma só com a "
                                "fonte “API” (Integrações → TikTok Shop). Nada foi enviado.")
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _tiktok_rascunho_de_linha(row)
        sit = r["situacao"]
        if sit == "publicando":
            raise ValueError("Este rascunho já está sendo publicado.")
        if sit == "publicado":
            raise ValueError(f"Este rascunho já foi publicado (produto {r.get('product_id') or ''}).")
        if sit == "incerto":
            raise ValueError("A última tentativa ficou sem resposta do TikTok: confira no Seller Center e libere antes.")
        if sit != "validado":
            raise ValueError("Confira (passo 6) antes de publicar.")
        motivo = _tiktok_ja_anunciado(str(r["ficha_codigo"]))
        if motivo:
            raise ValueError(motivo)
        cur = DB.execute("UPDATE anuncio_rascunho_tiktok_v2041 SET situacao='publicando', erros_json='[]', versao=versao+1, "
                         "atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='validado'", (now_iso(), str(ator or ""), rid))
        DB.commit()
        if cur.rowcount != 1:
            raise ValueError("Este rascunho já está sendo publicado.")
    return r


def _tiktok_subir_foto(dados: bytes, mime: str, pos: int) -> str:
    """V20.41: images/upload (multipart, campo `data`, use_case MAIN_IMAGE) -> uri."""
    ext = {"image/jpeg": "jpg", "image/png": "png", "image/webp": "webp"}.get(mime)
    if not ext:
        raise ValueError("o TikTok aceita JPG, PNG ou WEBP")
    resp = _tiktok_chamar("POST", "/product/202309/images/upload",
                          multipart=({"use_case": "MAIN_IMAGE"}, ("data", f"foto{pos}.{ext}", dados, mime)),
                          timeout=TIKTOK_ANUNCIO_UPLOAD_TIMEOUT, amostra="tiktok_upload_image")
    uri = str(((resp.get("data") or {}) if isinstance(resp.get("data"), dict) else {}).get("uri") or "")
    if not uri:
        raise ValueError("o TikTok não devolveu o endereço da foto")
    return uri


def _tiktok_sku_criado(resp: dict[str, Any], cod: str) -> tuple[str, str]:
    """V20.41: (product_id, sku_id) da resposta do criar. Sem o sku_id = ''."""
    d = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    pid = str(d.get("product_id") or "")
    skus = [s for s in d.get("skus") or [] if isinstance(s, dict) and str(s.get("id") or "")]
    escolhido = next((s for s in skus if normalize(s.get("seller_sku")) == normalize(cod)), skus[0] if len(skus) == 1 else None)
    return pid, str((escolhido or {}).get("id") or "")


def tiktok_publicar_executar(r: dict[str, Any], ator: str) -> dict[str, Any]:
    """V20.41: o trabalho do Publicar (rascunho ja em `publicando`). Falha antes do criar = `validado`."""
    rid, cod = int(r["id"]), str(r["ficha_codigo"])
    estado: dict[str, Any] = {"etapa": "antes", "fim": None, "product_id": None}

    def fim(para: str, erros: list[str], product_id: str | None = None, sku_id: str | None = None) -> dict[str, Any]:
        novo = _tiktok_trocar(rid, ("publicando",), para, erros, ator, product_id=product_id, sku_id=sku_id)
        estado["fim"] = novo or tiktok_rascunho_ler(rid) or r
        audit(ator, "anuncios.tiktok_publicar", f"{cod}|{rid}|{para}|{product_id or ''}|{'; '.join(erros)[:500]}")
        return {"ok": para == "publicado", "situacao": para, "product_id": product_id or "", "sku_id": sku_id or "",
                "erros": [] if para == "publicado" else erros, "rascunho": estado["fim"]}

    try:
        try:
            tiktok_access_token()
        except Exception as exc:
            return fim("validado", [f"TikTok sem conexão: {exc}"])
        try:  # V20.41: Apollo de Bauru (revenda 3) lido AGORA menos o vendido e nao baixado em Bauru
            ficha_ap = anuncio_ficha_payload(cod, ler_apollo=True, filiais=(TIKTOK_ANUNCIO_CONTA,))
        except Exception as exc:
            ficha_ap = None
            print(f"Aviso: Apollo nao lido para publicar {cod} no TikTok: {exc}", file=sys.stderr)
        est = (((ficha_ap or {}).get("estoque") or {}).get(TIKTOK_ANUNCIO_CONTA) or {})
        dpm = est.get("da_para_montar") if isinstance(est, dict) else None
        qtd = int(r.get("quantidade") or 0)
        if dpm is None:
            return fim("validado", ["O Apollo de Bauru não respondeu (ou a fila não foi lida) — não publicado. Tente de novo."])
        if int(dpm) <= 0:
            return fim("validado", ["Sem estoque no Apollo de Bauru para montar este produto — não publicado."])
        if qtd < 1 or qtd > int(dpm):
            return fim("validado", [f"Quantidade {qtd} acima do que dá para montar no Apollo de Bauru ({int(dpm)}) — "
                                    "não publicado."])
        erros, ctx = _tiktok_conferir_local(r)
        if erros:
            return fim("validado", erros)
        if tiktok_fonte() != "api":  # revisar-antes-de-subir (V20.41): a fonte virou extensão depois do clique
            return fim("validado", ["A fonte do TikTok virou a extensão do Seller Center: nada foi criado."])
        uris: list[str] = []
        for pos, fid in enumerate(r.get("fotos") or [], 1):
            try:
                dados, mime = anuncio_foto_bytes(fid)
                uris.append(_tiktok_subir_foto(dados, mime, pos))
            except Exception as exc:
                return fim("validado", [f"A foto {pos} não subiu para o TikTok ({str(exc)[:200]}). Nada foi criado."])
        corpo = tiktok_produto_corpo(r, ficha_ler(cod) or {"codigo": cod}, uris, ctx)
        estado["etapa"] = "enviado"
        try:
            resp = _tiktok_chamar("POST", "/product/202309/products", body=corpo, timeout=TIKTOK_ANUNCIO_ITEM_TIMEOUT,
                                  amostra="tiktok_criar_produto")
        except (TikTokRecusou, TikTokSemResposta) as exc:
            _anuncio_amostra("tiktok_criar_produto [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None),
                                                             "enviado": corpo})
            if _tiktok_talvez_fez(exc):  # erro interno/ocupado/tempo = o TikTok pode ter criado
                return fim("incerto", [TIKTOK_INCERTO_TEXTO, f"Detalhe: {str(exc)[:300]}"])
            estado["etapa"] = "antes"
            return fim("erro", [f"O TikTok recusou: {str(exc)[:500]}"])
        product_id, sku_id = _tiktok_sku_criado(resp, cod)
        if not product_id.isdigit():
            return fim("incerto", [TIKTOK_INCERTO_TEXTO, "O TikTok respondeu sem o número do produto."])
        estado["product_id"] = product_id
        if not sku_id:
            return fim("incerto", [TIKTOK_INCERTO_TEXTO, f"O TikTok criou o produto {product_id} mas não devolveu a "
                                   "variação: libere com o número do produto."], product_id=product_id)
        with DB_LOCK:
            try:
                cur = DB.execute("UPDATE anuncio_rascunho_tiktok_v2041 SET situacao='publicado', product_id=?, sku_id=?, "
                                 "erros_json='[]', versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? "
                                 "AND situacao='publicando'", (product_id, sku_id, now_iso(), str(ator or ""), rid))
                if cur.rowcount == 1:
                    _tiktok_canal_noromak(product_id, sku_id, {**r, "quantidade": qtd}, ator,
                                          str((ctx.get("deposito") or {}).get("id") or ""))
                DB.commit()
            except Exception:
                DB.rollback()
                raise
            estado["fim"] = _tiktok_rascunho_de_linha(
                DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (rid,)).fetchone())
        audit(ator, "anuncios.tiktok_publicar", f"{cod}|{rid}|publicado|{product_id}|{sku_id}")
        return {"ok": True, "situacao": "publicado", "product_id": product_id, "sku_id": sku_id, "erros": [],
                "rascunho": estado["fim"]}
    finally:
        if estado["fim"] is None:
            try:
                if estado["etapa"] == "antes":
                    fim("validado", ["Falha inesperada antes de criar o anúncio; nada foi criado no TikTok."])
                else:
                    fim("incerto", [TIKTOK_INCERTO_TEXTO], product_id=estado["product_id"])  # o numero nunca se perde
            except Exception as exc:
                print(f"Aviso: rascunho TikTok {rid} nao saiu de publicando: {exc}", file=sys.stderr)


def tiktok_publicar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: reserva e publica (sincrono; a rota usa tiktok_publicar_iniciar, em segundo plano)."""
    return tiktok_publicar_executar(tiktok_publicar_reservar(rascunho_id, ator), ator)


def tiktok_publicar_iniciar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: como a Shopee: reserva aqui (erro = na hora) e o resto numa thread que solta o ANUNCIOS_PUBLICAR_LOCK.
    Chamar COM o ANUNCIOS_PUBLICAR_LOCK pego."""
    r = tiktok_publicar_reservar(rascunho_id, ator)
    resposta = {"ok": True, "iniciado": True, "rascunho": tiktok_rascunho_ler(r["id"])}

    def rodar() -> None:
        try:
            tiktok_publicar_executar(r, ator)
        except Exception as exc:
            print(f"Aviso: publicar no TikTok {r['id']} falhou: {exc}", file=sys.stderr)
        finally:
            ANUNCIOS_PUBLICAR_LOCK.release()
    try:
        threading.Thread(target=rodar, name=f"tiktok-publicar-{r['id']}", daemon=True).start()
    except BaseException:
        _tiktok_trocar(int(r["id"]), ("publicando",), "validado", ["A publicação não começou; tente de novo."], ator)
        raise
    return resposta


def tiktok_incerto_liberar(rascunho_id: Any, product_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: o Admin conferiu no Seller Center: com o numero do produto = `publicado` (le o produto no TikTok e so
    aceita se uma variacao tem o SKU do vendedor = codigo da ficha); sem numero = volta a `validado`."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    texto = str(product_id or "").strip()
    if texto and not texto.isdigit():
        raise ValueError("Número do produto inválido (só números, como aparece no Seller Center).")
    sku_id, deposito = "", ""
    if texto:  # confere no TikTok, fora do DB_LOCK
        pre = tiktok_rascunho_ler(rid)
        if pre is None:
            raise ValueError("Rascunho não encontrado.")
        try:
            d = _tiktok_ler("GET", f"/product/202309/products/{texto}", None, None, "tiktok_produto")
        except RuntimeError as exc:
            raise ValueError(f"Não consegui conferir o produto {texto} no TikTok ({str(exc)[:200]}). Nada foi alterado.")
        skus = [s for s in d.get("skus") or [] if isinstance(s, dict)]
        achado = next((s for s in skus if normalize(s.get("seller_sku")) == normalize(pre["ficha_codigo"])), None)
        if not d or achado is None:
            vistos = ", ".join(str(s.get("seller_sku") or "(vazio)") for s in skus) or "nenhuma variação"
            raise ValueError(f"O produto {texto} no TikTok tem o SKU {vistos}, não {pre['ficha_codigo']}: não é deste "
                             "produto. Nada foi alterado.")
        sku_id = str(achado.get("id") or "")
        inv = [i for i in achado.get("inventory") or [] if isinstance(i, dict)]
        deposito = str(inv[0].get("warehouse_id") or "") if len(inv) == 1 else ""
        if not sku_id:
            raise ValueError("O TikTok não mostrou o id da variação: nada foi alterado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _tiktok_rascunho_de_linha(row)
        if r["situacao"] != "incerto":
            raise ValueError("Só um rascunho sem resposta do TikTok (incerto) pode ser liberado.")
        if texto:
            ja = DB.execute("SELECT ficha_codigo FROM anuncio_canal_v2023 WHERE canal='tiktok' AND anuncio_id=?",
                            (sku_id,)).fetchone()
            if ja and str(ja["ficha_codigo"] or "") not in ("", str(r["ficha_codigo"])):
                raise ValueError(f"A variação {sku_id} já está na lista com outro produto. Nada foi alterado.")
        para = "publicado" if texto else "validado"
        try:
            DB.execute("UPDATE anuncio_rascunho_tiktok_v2041 SET situacao=?, product_id=?, sku_id=?, erros_json='[]', "
                       "versao=versao+1, atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='incerto'",
                       (para, texto or None, sku_id or None, now_iso(), str(ator or ""), rid))
            if texto:
                _tiktok_canal_noromak(texto, sku_id, r, ator, deposito)
            DB.commit()
        except Exception:
            DB.rollback()
            raise
        novo = _tiktok_rascunho_de_linha(DB.execute("SELECT * FROM anuncio_rascunho_tiktok_v2041 WHERE id=?",
                                                    (rid,)).fetchone())
    audit(ator, "anuncios.tiktok_liberar", f"{r['ficha_codigo']}|{rid}|{para}|{texto}|{sku_id}")
    return {"ok": True, "situacao": para, "product_id": texto, "sku_id": sku_id, "rascunho": novo}


# ---- V20.41: "Trazer dados do anuncio" do TikTok para a ficha (so leitura no TikTok) ----
def _tiktok_foto_url_ok(url: Any) -> bool:
    """So https de um host da CDN do TikTok (TIKTOK_FOTO_HOSTS). Qualquer outro endereco e recusado."""
    try:
        p = urlparse(str(url or "").strip())
        host = (p.hostname or "").lower()
    except ValueError:
        return False
    return p.scheme == "https" and any(host == h or host.endswith("." + h) for h in TIKTOK_FOTO_HOSTS)


class _TikTokFotoRedirecionamento(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: N802 (nome do urllib)
        if not _tiktok_foto_url_ok(newurl):
            raise urllib.error.URLError("a foto redirecionou para fora da CDN do TikTok")
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def _tiktok_foto_baixar(url: str) -> bytes:
    """V20.41: baixa UMA foto do produto (CDN publica, sem token), 20 s. Chamar FORA do DB_LOCK."""
    if not _tiktok_foto_url_ok(url):
        raise ValueError("endereço fora da CDN do TikTok")
    abridor = urllib.request.build_opener(_TikTokFotoRedirecionamento)
    req = urllib.request.Request(url, headers={"Accept": "image/*", "User-Agent": f"NoromakExpedicao/{APP_VERSION}"})
    with abridor.open(req, timeout=ANUNCIO_FOTO_ML_TIMEOUT) as resp:
        dados = resp.read(ANUNCIO_FOTO_MAX_BYTES + 1)
    if len(dados) > ANUNCIO_FOTO_MAX_BYTES:
        raise ValueError("a foto passa de 10 MB")
    return dados


def _tiktok_fotos_do_produto(d: dict[str, Any]) -> list[str]:
    urls: list[str] = []
    for img in d.get("main_images") or []:
        if isinstance(img, dict):
            cand = [u for u in (img.get("urls") or []) if isinstance(u, str)] + [str(img.get("url") or "")]
            u = next((x for x in cand if x.strip()), "")
            if u:
                urls.append(u.strip())
    return urls[:ANUNCIO_FOTOS_MAX]


def tiktok_trazer_dados(conta: Any, anuncio_id: Any, ator: str) -> dict[str, Any]:
    """V20.41: le o produto no TikTok (GET /product/202309/products/{id}) e traz para a ficha titulo, descricao e
    marca (origem anuncio_tiktok: o Admin e o "apagado pelo Admin" nunca mudam) e as fotos so se a ficha nao tem foto.
    A categoria do TikTok fica na linha do anuncio (a ficha guarda a categoria do ML). So com a fonte "api"."""
    if str(conta or "").strip() not in ("", TIKTOK_ANUNCIO_CONTA):
        raise ValueError("O TikTok é só da conta de Bauru.")
    if tiktok_fonte() != "api":
        raise ValueError("A fonte do TikTok é a extensão do Seller Center: “Trazer dados” do TikTok só com a fonte API.")
    sku_id = str(anuncio_id or "").strip()
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_canal_v2023 WHERE canal='tiktok' AND conta=? AND anuncio_id=?",
                         (TIKTOK_ANUNCIO_CONTA, sku_id)).fetchone()
        linha = dict(row) if row else None
        if linha is not None and not str(linha.get("user_product_id") or ""):
            pr = DB.execute("SELECT product_id FROM tiktok_sku_v1964 WHERE sku_id=?", (sku_id,)).fetchone()
            linha["user_product_id"] = str(pr["product_id"] or "") if pr else ""
    if linha is None:
        raise AnuncioNaoEncontrado(f"A variação {sku_id} do TikTok não está na lista.")
    if str(linha.get("removido_em") or ""):
        raise ValueError(f"A variação {sku_id} foi removida da lista pelo Admin: reinclua antes de trazer os dados.")
    product_id = str(linha.get("user_product_id") or "")
    if not product_id:
        raise ValueError("O Noromak não sabe o produto desta variação (atualize os anúncios do TikTok).")
    try:
        d = _tiktok_ler("GET", f"/product/202309/products/{product_id}", None, None, "tiktok_produto")
    except RuntimeError as exc:
        raise AnuncioMLSemResposta(f"O TikTok não respondeu ao ler o produto {product_id} ({str(exc)[:200]}). Nada foi "
                                   "alterado; tente de novo.")
    if not d:
        raise AnuncioNaoEncontrado(f"O produto {product_id} não foi encontrado no TikTok.")
    ficha = str(linha.get("ficha_codigo") or "")
    cats = [c for c in d.get("category_chains") or [] if isinstance(c, dict)]
    folha = next((c for c in cats if c.get("is_leaf")), cats[-1] if cats else {})
    with DB_LOCK:  # a linha do anuncio guarda o titulo e a categoria do TikTok (nao vao para a ficha do ML)
        DB.execute("UPDATE anuncio_canal_v2023 SET titulo=COALESCE(NULLIF(?,''),titulo), "
                   "categoria=COALESCE(NULLIF(?,''),categoria) WHERE canal='tiktok' AND conta=? AND anuncio_id=?",
                   (str(d.get("title") or ""), str(folha.get("id") or ""), TIKTOK_ANUNCIO_CONTA, sku_id))
        DB.commit()
    trazidos: dict[str, Any] = {"campos": [], "fotos": 0, "fotos_falharam": 0, "fotos_ja_tinha": False,
                                "descricao_erro": "", "sem_ficha": not ficha}
    if ficha:
        campos = {"nome": " ".join(html_module.unescape(str(d.get("title") or "")).split()),  # titulo pode vir com &amp;
                  "descricao": _tiktok_html_texto(d.get("description")),
                  "marca": str(((d.get("brand") or {}) if isinstance(d.get("brand"), dict) else {}).get("name") or "")}
        trazidos["campos"] = ficha_importar(ficha, campos, "anuncio_tiktok")
        trazidos.update(_anuncio_fotos_do_ml(ficha, _tiktok_fotos_do_produto(d), ator, url_ok=_tiktok_foto_url_ok,
                                             baixar=_tiktok_foto_baixar, candidatos=lambda u: [str(u or "").strip()],
                                             origem="anuncio_tiktok"))
    texto = _anuncio_trazido_texto(trazidos)
    audit(ator, "anuncios.trazer_dados", f"tiktok|{sku_id}|{ficha}|{texto}"[:2000])
    return {"ok": True, "mlb": sku_id, "anuncio_id": sku_id, "product_id": product_id, "conta": TIKTOK_ANUNCIO_CONTA,
            "ficha_codigo": ficha, "novo": False, "removido": False, "anuncio": linha, "trazidos": trazidos,
            "trazido_texto": texto}


# ---------------------------------------------------------------------------
# V20.34 - Criar anuncio e controlar estoque na MAGALU (Araçatuba). Desenho em
# docs/superpowers/specs/2026-11-06-anuncios-magalu-design.md. Construido pela especificacao OpenAPI oficial
# (developers.magalu.com/apis/products.openapi.yaml), sem resposta real: a 1a resposta de cada chamada fica em
# anuncio_amostra_v2024 (tipos `magalu_*`) - conferir no 1o uso.
# O que muda em relacao a Shopee:
# - Criar o SKU, o preco e o estoque respondem 202 (assincrono, `trace_id`): nada e "publicado" so pelo 202. O SKU
#   enviado e o codigo da ficha, entao da para conferir pela propria Magalu (GET do SKU): sem resposta no envio NAO e
#   incerto de cara, e `aguardando` - o acompanhamento le o SKU; existe = manda preco e estoque e vira `publicado`.
# - Nao ha upload de foto: a Magalu baixa a foto de um endereco https publico em JPEG. As fotos do Noromak ficam atras
#   do login (nginx); por isso as fotos vem do anuncio do ML desta ficha (mlstatic.com, publicas). So mlstatic, so JPEG.
# - SKU que ja existe na Magalu (criado por outra ferramenta) NAO e sobrescrito: o Publicar recusa.
# ---------------------------------------------------------------------------
MAGALU_ANUNCIO_CONTA = "aracatuba"
MAGALU_CANAL_ID = os.getenv("MAGALU_CANAL_ID", "9fe0d853-732b-4e4a-a0b0-cff988ed043d").strip()  # canal Magazine Luiza
MAGALU_TITULO_MAX = 150
MAGALU_DESC_MAX = 7000
MAGALU_FOTOS_MAX = 30
MAGALU_SKU_MAX = 32
MAGALU_ATRIBUTOS_MAX = 3
MAGALU_FICHA_TECNICA_MAX = 50
MAGALU_LEITURA_CACHE_S = 24 * 3600
MAGALU_HTTP_TIMEOUT = 35
MAGALU_ACOMPANHAR_PRAZO_S = 30 * 60      # SKU que nao aparece em 30 min (sem erro no trace) = incerto
MAGALU_ACOMPANHAR_INTERVALO_S = 20       # um rascunho e conferido na Magalu no maximo a cada 20 s
MAGALU_RASCUNHO_EDITAVEL = ("rascunho", "validado", "erro")
MAGALU_RASCUNHO_CAMPOS = ("titulo", "categoria", "categoria_nome", "marca", "descricao", "preco", "preco_de", "quantidade")
MAGALU_ESTOQUE_RELEITURA_ESPERAS: tuple[float, ...] = (2.0, 3.0)  # estoque assincrono; revisao: rota < 60 s
MAGALU_ESTOQUE_TIMEOUT = 12
MAGALU_INCERTO_TEXTO = ("A Magalu não mostrou o SKU depois do envio. Confira no painel da Magalu (Meus produtos) se o "
                        "anúncio foi criado e use “Conferir de novo” ou “Liberar”.")
_MAGALU_LEITURA_CACHE: dict[tuple[str, str], tuple[float, Any]] = {}
_MAGALU_LEITURA_LOCK = threading.Lock()
_MAGALU_ACOMPANHAR_VISTO: dict[int, float] = {}
_MAGALU_ACOMPANHAR_LOCKS: dict[int, threading.Lock] = {}
_MAGALU_ACOMPANHAR_LOCKS_LOCK = threading.Lock()


class MagaluSemResposta(Exception):
    """V20.34: rede, timeout ou 5xx - a Magalu pode ter feito."""


class MagaluRecusou(Exception):
    """V20.34: a Magalu respondeu com erro (4xx). `status` = HTTP; `corpo` = o que veio."""

    def __init__(self, msg: str, corpo: Any = None, status: int | None = None):
        super().__init__(msg)
        self.corpo = corpo
        self.status = status


def _magalu_talvez_fez(exc: Exception) -> bool:
    if isinstance(exc, MagaluSemResposta):
        return True
    if isinstance(exc, MagaluRecusou):
        return exc.status == 408 or (exc.status or 0) >= 500
    return False


def _magalu_erro_texto(corpo: Any) -> str:
    """V20.34: o 422 vem como lista {loc, msg}; o resto como {message}/{error}/texto."""
    if isinstance(corpo, dict):
        det = corpo.get("detail") if isinstance(corpo.get("detail"), list) else corpo.get("errors")
        if isinstance(det, list) and det:
            partes = []
            for d in det[:8]:
                if isinstance(d, dict):
                    loc = ".".join(str(x) for x in d.get("loc") or [] if str(x) != "body")
                    partes.append((loc + ": " if loc else "") + str(d.get("msg") or d.get("message") or d))
                else:
                    partes.append(str(d))
            return "; ".join(partes)[:600]
        for k in ("message", "error_description", "error", "detail"):
            if corpo.get(k):
                return str(corpo[k])[:600]
    return str(corpo or "")[:600]


def _magalu_chamar(method: str, path: str, params: dict[str, Any] | None = None, payload: Any = None, *,
                   timeout: int = MAGALU_HTTP_TIMEOUT) -> Any:
    """V20.34: chamada JSON a api.magalu.com com o token da loja (401 renova uma vez). 4xx = MagaluRecusou;
    rede/timeout/5xx = MagaluSemResposta. Resposta vazia (202 sem corpo) = {"status_http": codigo}."""
    query = {k: v for k, v in (params or {}).items() if v is not None and v != ""}
    url = MAGALU_API_BASE + path + (("?" + urlencode(query)) if query else "")

    def enviar(token: str) -> Any:
        dados = json.dumps(payload).encode("utf-8") if payload is not None else None
        h = {"Authorization": f"Bearer {token}", "Accept": "application/json",
             "User-Agent": f"NoromakExpedicao/{APP_VERSION}"}
        if dados is not None:
            h["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=dados, method=method.upper(), headers=h)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            texto = resp.read().decode("utf-8", "replace")
            if not texto.strip():
                return {"status_http": resp.status}
            return json.loads(texto)

    def uma(token: str) -> Any:
        try:
            return enviar(token)
        except urllib.error.HTTPError as exc:
            if exc.code == 401:
                raise MagaluHttp401()
            try:
                bruto = exc.read().decode("utf-8", "replace")
            except Exception:
                bruto = ""
            try:
                corpo: Any = json.loads(bruto) if bruto.strip() else {}
            except ValueError:
                corpo = bruto[:600]
            if exc.code >= 500 or exc.code == 408:
                raise MagaluSemResposta(f"Magalu HTTP {exc.code}: {_magalu_erro_texto(corpo)}")
            raise MagaluRecusou(f"Magalu HTTP {exc.code}: {_magalu_erro_texto(corpo)}", corpo, exc.code)
        except (urllib.error.URLError, TimeoutError, OSError) as exc:
            raise MagaluSemResposta(f"sem resposta da Magalu ({getattr(exc, 'reason', exc)})")
        except ValueError as exc:  # 2xx com corpo que nao e JSON
            raise MagaluSemResposta(f"resposta da Magalu ilegível ({exc})")

    try:
        token = magalu_access_token()
    except Exception as exc:
        raise MagaluRecusou(f"Magalu sem conexão: {exc}")
    try:
        return uma(token)
    except MagaluHttp401:
        try:
            return uma(magalu_access_token(force=True, recusado=token))
        except MagaluHttp401:
            raise MagaluRecusou("A Magalu recusou o acesso (401). Reconecte a conta em Integrações.", None, 401)


def _magalu_ler(path: str, params: dict[str, Any] | None, amostra: str) -> Any:
    """V20.34: leitura com amostra; erro vira RuntimeError (a tela mostra)."""
    try:
        dados = _magalu_chamar("GET", path, params)
    except (MagaluRecusou, MagaluSemResposta) as exc:
        if amostra:
            _anuncio_amostra(f"{amostra} [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None)})
        raise RuntimeError(str(exc))
    if amostra:
        _anuncio_amostra(amostra, dados)
    return dados


def _magalu_cache(chave: tuple[str, str], ler: Any) -> Any:
    agora = time.time()
    with _MAGALU_LEITURA_LOCK:
        hit = _MAGALU_LEITURA_CACHE.get(chave)
        if hit and agora - hit[0] < MAGALU_LEITURA_CACHE_S:
            return hit[1]
    valor = ler()
    with _MAGALU_LEITURA_LOCK:
        if len(_MAGALU_LEITURA_CACHE) > 500:
            _MAGALU_LEITURA_CACHE.clear()
        _MAGALU_LEITURA_CACHE[chave] = (agora, valor)
    return valor


def _magalu_texto(d: Any, *chaves: str) -> str:
    if not isinstance(d, dict):
        return ""
    for k in chaves:
        v = d.get(k)
        if isinstance(v, (str, int, float)) and not isinstance(v, bool) and str(v).strip():
            return str(v).strip()
    return ""


def _magalu_uuid_ok(texto: Any) -> bool:
    return bool(re.fullmatch(r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}",
                             str(texto or "").strip()))


def magalu_categorias_buscar(nome: str) -> list[dict[str, Any]]:
    """V20.34: categorias da Magalu pelo nome (GET /seller/v1/portfolios/categories?name=, no minimo 3 letras pela
    spec). Revisao: o endereco e no PLURAL (categories.openapi.yaml); `path` vem como "/automotivo/limpeza"."""
    nome = " ".join(str(nome or "").split())[:100]
    if len(nome) < 3:
        raise ValueError("Digite pelo menos 3 letras para buscar a categoria.")

    def ler() -> list[dict[str, Any]]:
        bruto = _magalu_ler("/seller/v1/portfolios/categories", {"name": nome, "_limit": 50}, "magalu_categorias")
        saida = []
        for c in _magalu_lista(bruto):
            cid = _magalu_texto(c, "id", "category_id")
            if not cid or not _magalu_uuid_ok(cid):
                continue
            caminho = c.get("path") if isinstance(c, dict) else ""
            if isinstance(caminho, list):
                caminho = " > ".join(_magalu_texto(x, "name", "title") if isinstance(x, dict) else str(x) for x in caminho)
            elif isinstance(caminho, str) and "/" in caminho:
                caminho = " > ".join(p.replace("-", " ") for p in caminho.strip("/").split("/") if p)
            saida.append({"categoria": cid, "nome": _magalu_texto(c, "name", "title") or cid,
                          "caminho": str(caminho or ""), "folha": None})
        return saida
    return list(_magalu_cache(("categorias", nome.lower()), ler))


def magalu_categoria_folha(categoria: str) -> bool | None:
    """V20.34 (revisao): a categoria tem subcategorias? GET .../categories/hierarchy?parent_id= (guardado 24 h).
    True = final; False = tem filhas; None = nao consegui ler (o Conferir avisa, nao barra)."""
    cid = str(categoria or "").strip()
    if not _magalu_uuid_ok(cid):
        return None

    def ler() -> dict[str, Any]:
        bruto = _magalu_ler("/seller/v1/portfolios/categories/hierarchy", {"parent_id": cid, "_limit": 5},
                            "magalu_categoria_filhas")
        filhas = [c for c in _magalu_lista(bruto) if _magalu_texto(c, "id") and _magalu_texto(c, "id") != cid]
        return {"folha": not filhas}
    try:
        return bool(_magalu_cache(("folha", cid), ler)["folha"])
    except RuntimeError:
        return None


def _magalu_defs(bruto: Any) -> list[dict[str, Any]]:
    """V20.34: atributos/ficha tecnica da categoria: {nome, rotulo, obrigatorio, recomendado, valores, variacao}.
    Revisao: a lista de opcoes vem em `choices` (spec); atributo `active: false` fica fora."""
    saida = []
    vistos: set[str] = set()
    for a in _magalu_lista(bruto):
        if not isinstance(a, dict) or a.get("active") is False:
            continue
        nome = _magalu_texto(a, "name", "display_name", "id")
        if not nome or nome.lower() in vistos:
            continue
        vistos.add(nome.lower())
        req = a.get("required")
        req_txt = str(req).strip().lower() if not isinstance(req, bool) else ("required" if req else "optional")
        valores = []
        for v in (a.get("choices") or a.get("values") or []):
            t = _magalu_texto(v, "value", "name", "id") if isinstance(v, dict) else str(v or "").strip()
            if t and t not in valores:
                valores.append(t)
        saida.append({"nome": nome[:255], "rotulo": _magalu_texto(a, "display_name") or nome,
                      "obrigatorio": req_txt in ("required", "true", "1", "mandatory"),
                      "recomendado": req_txt == "recommended", "valores": valores[:500],
                      "variacao": bool(a.get("variation"))})
    return saida


def magalu_categoria_atributos(categoria: Any) -> dict[str, Any]:
    """V20.34: atributos de variacao (/attributes) e ficha tecnica (/datasheet) da categoria (endereco no plural)."""
    cid = str(categoria or "").strip()
    if not _magalu_uuid_ok(cid):
        raise ValueError("Categoria da Magalu inválida.")

    def paginas(caminho: str, amostra: str) -> list[Any]:
        # 2a revisao: a spec pagina (_limit padrao 50, maximo 100): sem isto o obrigatorio depois do 50o sumia
        itens: list[Any] = []
        for pag in range(10):
            lote = _magalu_lista(_magalu_ler(caminho, {"_limit": 100, "_offset": pag * 100}, amostra if pag == 0 else ""))
            itens += lote
            if len(lote) < 100:
                break
        return itens

    def ler() -> dict[str, Any]:
        todos = _magalu_defs(paginas(f"/seller/v1/portfolios/categories/{cid}/attributes", "magalu_atributos"))
        ficha = _magalu_defs(paginas(f"/seller/v1/portfolios/categories/{cid}/datasheet", "magalu_ficha_tecnica"))
        # 2a revisao: /attributes traz tambem atributos que NAO sao de variacao (ex.: "Dimensões do Produto"): esses vao
        # para a ficha tecnica (o `attributes` do SKU e so de variacao: ate 3, nome ate 20)
        nomes = {d["nome"].lower() for d in ficha}
        ficha += [d for d in todos if not d.get("variacao") and d["nome"].lower() not in nomes]
        return {"categoria": cid, "atributos": [d for d in todos if d.get("variacao")], "ficha_tecnica": ficha}
    return dict(_magalu_cache(("atributos", cid), ler))


def magalu_fotos_do_ml(codigo: str) -> list[dict[str, str]]:
    """V20.34: fotos (enderecos publicos do mlstatic) dos anuncios do ML desta ficha, na ordem do anuncio. Le o ML
    agora (fora do DB_LOCK). Anuncio removido pelo Admin nao conta. Nada encontrado = []. Revisao: no maximo 3
    anuncios lidos (a rota nao pode passar dos 60 s do nginx)."""
    cod = normalize(codigo)
    with DB_LOCK:
        linhas = [dict(r) for r in DB.execute(
            "SELECT conta, anuncio_id FROM anuncio_canal_v2023 WHERE canal='ml' AND ficha_codigo=? "
            "AND COALESCE(removido_em,'')='' ORDER BY CASE controle WHEN 'noromak' THEN 0 ELSE 1 END, conta, anuncio_id",
            (cod,)).fetchall()]
    saida: list[dict[str, str]] = []
    vistos: set[str] = set()
    for ln in linhas[:3]:
        try:
            with ml_na_casa(ln["conta"]):
                det = ml_itens_detalhe([str(ln["anuncio_id"])], com_fotos=True)
        except Exception as exc:
            print(f"Aviso: fotos do {ln['anuncio_id']} nao lidas para a Magalu: {exc}", file=sys.stderr)
            continue
        for u in (det.get(str(ln["anuncio_id"])) or {}).get("fotos") or []:
            url = str(u or "").strip()
            if url.lower().startswith("http://"):
                url = "https://" + url[7:]
            if url and url not in vistos and _anuncio_foto_ml_url_ok(url):
                vistos.add(url)
                saida.append({"url": url, "mlb": str(ln["anuncio_id"])})
        if saida:
            break  # um anuncio basta (as mesmas fotos em todos)
    return saida[:MAGALU_FOTOS_MAX]


_MAGALU_FOTO_OK: dict[str, float] = {}  # revisao: foto ja conferida (JPEG) nao e baixada de novo por 24 h


def _magalu_foto_conferir(url: str) -> str:
    """V20.34: '' = a Magalu consegue usar (https do mlstatic, JPEG); senao o motivo. Baixa a foto (fora do DB_LOCK)."""
    if not str(url or "").lower().startswith("https://") or not _anuncio_foto_ml_url_ok(url):
        return "a foto precisa ser um endereço https do Mercado Livre (mlstatic.com)"
    if time.time() - _MAGALU_FOTO_OK.get(url, 0.0) < MAGALU_LEITURA_CACHE_S:
        return ""
    try:
        dados = _anuncio_foto_ml_baixar(url)
    except Exception as exc:
        return f"não consegui abrir a foto ({str(exc)[:120]})"
    if not dados.startswith(b"\xff\xd8\xff"):
        return "a Magalu aceita só JPEG e esta foto não é JPEG"
    if len(_MAGALU_FOTO_OK) > 2000:
        _MAGALU_FOTO_OK.clear()
    _MAGALU_FOTO_OK[url] = time.time()
    return ""


def _magalu_fotos_conferir(fotos: list[str], prazo: float | None) -> tuple[list[str], list[str]]:
    """V20.34 (revisao): confere as fotos em paralelo (6 por vez). Com `prazo` (s), o que nao terminou a tempo vira
    aviso (o Publicar, em segundo plano, confere sem prazo). Devolve (erros, avisos)."""
    import concurrent.futures as _cf
    erros: list[str] = []
    avisos: list[str] = []
    if not fotos:
        return erros, avisos
    ex = _cf.ThreadPoolExecutor(max_workers=min(6, len(fotos)), thread_name_prefix="magalu-foto")
    try:
        futs = {ex.submit(_magalu_foto_conferir, u): pos for pos, u in enumerate(fotos, 1)}
        feitos, faltam = _cf.wait(futs, timeout=prazo)
        for f in feitos:
            try:
                motivo = f.result()
            except Exception as exc:
                motivo = f"não consegui conferir ({str(exc)[:80]})"
            if motivo:
                erros.append(f"Foto {futs[f]}: {motivo}.")
        if faltam:
            avisos.append(f"{len(faltam)} foto(s) não terminaram de ser conferidas a tempo: o Publicar confere de novo.")
    finally:
        ex.shutdown(wait=False, cancel_futures=True)
    erros.sort(key=lambda t: int(re.search(r"\d+", t).group()) if re.search(r"\d+", t) else 0)
    return erros, avisos


def magalu_conta_preco(codigo: str, preco: Any, comissao: Any = None, taxa_fixa: Any = None,
                       frete: Any = None) -> dict[str, Any]:
    """V20.34: conta do preco na Magalu (so le): comissao/taxa fixa/frete do Precificador (`marketplaces.magalu`,
    comissao 0 = sem taxa cadastrada) ou os digitados na tela; imposto e custo de Araçatuba. Sem custo ou sem
    comissao = sem lucro e sem preco ideal (nunca zero)."""
    base = anuncio_custo_para_preco(codigo)

    def num(v: Any) -> float | None:
        if v in (None, "") or isinstance(v, bool):
            return None
        try:
            x = float(str(v).replace(",", "."))
        except (TypeError, ValueError):
            return None
        return x if math.isfinite(x) and x >= 0 else None

    p = num(preco)
    p = p if p else None
    try:
        tx = _magalu_taxas_precificador().get(normalize(codigo)) or {}
    except Exception as exc:
        print(f"Aviso: taxas da Magalu do Precificador nao lidas: {exc}", file=sys.stderr)
        tx = {}
    com_dig = num(comissao)
    com = (com_dig / 100.0 if com_dig is not None and com_dig >= 1 else com_dig) if com_dig is not None else tx.get("comissao")
    fixa = num(taxa_fixa) if num(taxa_fixa) is not None else tx.get("taxa_fixa", 0.0 if com is not None else None)
    fr = num(frete) if num(frete) is not None else tx.get("frete", 0.0 if com is not None else None)
    origem = "digitada" if com_dig is not None else ("Precificador" if tx else "")
    out: dict[str, Any] = {**base, "preco": p, "comissao_pct": com, "taxa_fixa": fixa, "frete": fr,
                           "taxas_origem": origem, "comissao": None, "imposto_valor": None, "lucro": None,
                           "margem": None, "preco_ideal": None}
    if com is None or com >= 1:
        out["comissao_pct"] = None
        out["sem_taxa"] = "Sem a comissão da Magalu no Precificador: digite a comissão para ver o lucro."
        if p:
            out["imposto_valor"] = round(p * float(base.get("imposto") or 0), 2)
        return out
    imp = float(base.get("imposto") or 0)
    custo = base.get("custo")
    fixa_f, fr_f = float(fixa or 0), float(fr or 0)
    if p:
        out.update({"comissao": round(p * com, 2), "imposto_valor": round(p * imp, 2)})
        if custo is not None:
            lucro = p - p * com - fixa_f - fr_f - p * imp - float(custo)
            out.update({"lucro": round(lucro, 2), "margem": round(lucro / p, 4)})
    alvo = base.get("margem_alvo")
    if custo is not None and alvo is not None:
        den = 1 - com - imp - float(alvo)
        if den > 0:
            out["preco_ideal"] = round((float(custo) + fixa_f + fr_f) / den + 0.0049, 2)
    return out


# ---- rascunho ----
def _magalu_rascunho_de_linha(row: Any) -> dict[str, Any]:
    d = dict(row)
    for campo, padrao in (("atributos_json", {}), ("ficha_tecnica_json", {}), ("fotos_json", []), ("erros_json", []),
                          ("envios_json", [])):
        try:
            v = json.loads(d.pop(campo) or "")
        except (TypeError, ValueError):
            v = padrao
        d[campo[:-5]] = v if isinstance(v, type(padrao)) else padrao
    d["canal"] = "magalu"
    return d


def magalu_rascunho_ler(rid: Any) -> dict[str, Any] | None:
    try:
        n = int(rid)
    except (TypeError, ValueError):
        return None
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (n,)).fetchone()
    return _magalu_rascunho_de_linha(row) if row else None


def magalu_rascunhos_da_ficha(codigo: str) -> list[dict[str, Any]]:
    with DB_LOCK:
        rows = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE ficha_codigo=? ORDER BY id DESC",
                          (normalize(codigo),)).fetchall()
    return [_magalu_rascunho_de_linha(r) for r in rows]


def _magalu_pares(brutos: Any, maximo: int, tam_nome: int, tam_valor: int) -> dict[str, str]:
    """V20.34: {nome: valor} limpo (nome e valor como a Magalu aceita; vazio sai)."""
    saida: dict[str, str] = {}
    for k, v in (brutos.items() if isinstance(brutos, dict) else []):
        nome = " ".join(str(k or "").split())[:tam_nome]
        valor = " ".join(str(v or "").split())[:tam_valor]
        if nome and valor:
            saida[nome] = valor
    if len(saida) > maximo:
        raise ValueError(f"A Magalu aceita até {maximo} itens aqui.")
    return saida


def _magalu_preco(dados: dict[str, Any], chave: str) -> float | None:
    p = dados.get(chave)
    if p in (None, ""):
        return None
    if isinstance(p, bool):
        raise ValueError("Preço inválido.")
    try:
        v = round(float(str(p).replace(",", ".")), 2)
    except (TypeError, ValueError):
        raise ValueError("Preço inválido.")
    if not math.isfinite(v) or v <= 0 or v > 999999.99:
        raise ValueError("O preço precisa ser um número maior que zero.")
    return v


def _magalu_rascunho_limpar(dados: dict[str, Any]) -> dict[str, Any]:
    """V20.34: so os campos que vieram, conferidos (tipo e tamanho)."""
    out: dict[str, Any] = {}
    if "titulo" in dados:
        out["titulo"] = " ".join(str(dados.get("titulo") or "").split())[:300]
    if "categoria" in dados:
        cat = str(dados.get("categoria") or "").strip()
        if cat and not _magalu_uuid_ok(cat):
            raise ValueError("Categoria da Magalu inválida.")
        out["categoria"] = cat
        out["categoria_nome"] = str(dados.get("categoria_nome") or "")[:300]
    if "marca" in dados:
        out["marca"] = " ".join(str(dados.get("marca") or "").split())[:100]
    if "descricao" in dados:
        out["descricao"] = str(dados.get("descricao") or "")[:MAGALU_DESC_MAX + 3000]
    if "preco" in dados:
        out["preco"] = _magalu_preco(dados, "preco")
    if "preco_de" in dados:
        out["preco_de"] = _magalu_preco(dados, "preco_de")
    if "quantidade" in dados:
        q = dados.get("quantidade")
        if q in (None, ""):
            out["quantidade"] = None
        else:
            try:
                out["quantidade"] = int(str(q))
            except (TypeError, ValueError):
                raise ValueError("Quantidade inválida.")
            if isinstance(q, bool) or not 1 <= out["quantidade"] <= ANUNCIO_ESTOQUE_MAX:
                raise ValueError("A quantidade vai de 1 a 99999.")
    if "atributos" in dados:
        out["atributos"] = _magalu_pares(dados.get("atributos"), MAGALU_ATRIBUTOS_MAX, 255, 50)
    if "ficha_tecnica" in dados:
        out["ficha_tecnica"] = _magalu_pares(dados.get("ficha_tecnica"), MAGALU_FICHA_TECNICA_MAX, 255, 500)
    if "fotos" in dados:
        brutas = dados.get("fotos") or []
        if not isinstance(brutas, list):
            raise ValueError("Fotos inválidas.")
        fotos = []
        for u in brutas:
            url = str(u or "").strip()
            if not url:
                continue
            if not url.lower().startswith("https://") or not _anuncio_foto_ml_url_ok(url) or len(url) > 500:
                raise ValueError("Foto da Magalu: só endereço https das fotos do anúncio do Mercado Livre (mlstatic.com).")
            if url not in fotos:
                fotos.append(url)
        if len(fotos) > MAGALU_FOTOS_MAX:
            raise ValueError(f"A Magalu aceita até {MAGALU_FOTOS_MAX} fotos.")
        out["fotos"] = fotos
    return out


def magalu_rascunho_salvar(dados: dict[str, Any], ator: str, versao: Any) -> dict[str, Any]:
    """V20.34: cria (sem `id`, com `codigo`) ou atualiza (com `id`; `versao` conferida, senao FichaConflito)."""
    dados = dados if isinstance(dados, dict) else {}
    limpos = _magalu_rascunho_limpar(dados)
    agora = now_iso()
    with DB_LOCK:
        rid = dados.get("id")
        if rid in (None, ""):
            cod = normalize(dados.get("codigo"))
            if not cod or _ficha_ler_sem_lock(cod) is None:
                raise ValueError("Produto não encontrado.")
            cur = DB.execute(
                "INSERT INTO anuncio_rascunho_magalu_v2034(ficha_codigo,titulo,categoria,categoria_nome,marca,atributos_json,"
                "ficha_tecnica_json,fotos_json,descricao,preco,preco_de,quantidade,situacao,versao,criado_em,criado_por,"
                "atualizado_em,atualizado_por) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,'rascunho',1,?,?,?,?)",
                (cod, limpos.get("titulo", ""), limpos.get("categoria", ""), limpos.get("categoria_nome", ""),
                 limpos.get("marca", ""), json.dumps(limpos.get("atributos", {}), ensure_ascii=False),
                 json.dumps(limpos.get("ficha_tecnica", {}), ensure_ascii=False),
                 json.dumps(limpos.get("fotos", []), ensure_ascii=False), limpos.get("descricao", ""),
                 limpos.get("preco"), limpos.get("preco_de"), limpos.get("quantidade"), agora, str(ator or ""), agora,
                 str(ator or "")))
            novo_id = int(cur.lastrowid)
        else:
            row = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (rid,)).fetchone()
            if row is None:
                raise ValueError("Rascunho não encontrado.")
            atual = _magalu_rascunho_de_linha(row)
            try:
                ok_versao = versao is not None and int(versao) == int(atual["versao"])
            except (TypeError, ValueError):
                ok_versao = False
            if not ok_versao:
                raise FichaConflito(atual)
            if atual["situacao"] not in MAGALU_RASCUNHO_EDITAVEL:
                raise ValueError("Este rascunho já foi publicado ou está em publicação; não pode mais ser editado.")
            novo = {k: limpos.get(k, atual.get(k)) for k in MAGALU_RASCUNHO_CAMPOS}
            troca_cat = "categoria" in limpos and limpos["categoria"] != str(atual.get("categoria") or "")
            attrs = limpos.get("atributos", {} if troca_cat else atual.get("atributos") or {})
            ficha_t = limpos.get("ficha_tecnica", {} if troca_cat else atual.get("ficha_tecnica") or {})
            fotos = limpos.get("fotos", atual.get("fotos") or [])
            mudou = (any(novo[k] != atual.get(k) for k in MAGALU_RASCUNHO_CAMPOS) or attrs != (atual.get("atributos") or {})
                     or ficha_t != (atual.get("ficha_tecnica") or {}) or fotos != (atual.get("fotos") or []))
            if not mudou:
                return atual
            situacao = "rascunho" if atual["situacao"] == "validado" else atual["situacao"]
            DB.execute(
                "UPDATE anuncio_rascunho_magalu_v2034 SET titulo=?,categoria=?,categoria_nome=?,marca=?,atributos_json=?,"
                "ficha_tecnica_json=?,fotos_json=?,descricao=?,preco=?,preco_de=?,quantidade=?,situacao=?,versao=versao+1,"
                "atualizado_em=?,atualizado_por=? WHERE id=?",
                (novo["titulo"], novo["categoria"], novo["categoria_nome"], novo["marca"],
                 json.dumps(attrs, ensure_ascii=False), json.dumps(ficha_t, ensure_ascii=False),
                 json.dumps(fotos, ensure_ascii=False), novo["descricao"], novo["preco"], novo["preco_de"],
                 novo["quantidade"], situacao, agora, str(ator or ""), atual["id"]))
            novo_id = int(atual["id"])
        DB.commit()
        row = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (novo_id,)).fetchone()
    return _magalu_rascunho_de_linha(row)


def _magalu_trocar(rid: int, de: tuple[str, ...], para: str, erros: list[str], ator: str, *,
                   versao: int | None = None, extra: dict[str, Any] | None = None) -> dict[str, Any] | None:
    """V20.34: troca a situacao SOB o DB_LOCK so se ela ainda e uma das esperadas (e a versao, quando dada)."""
    extra = extra or {}
    sets, args = ["situacao=?", "erros_json=?", "versao=versao+1", "atualizado_em=?", "atualizado_por=?"], \
        [para, json.dumps(list(erros), ensure_ascii=False), now_iso(), str(ator or "")]
    for k in ("sku", "trace_id", "enviado_em", "etapa", "status_magalu", "tentativas", "etapa_em", "qtd_enviada",
              "envios_json"):
        if k in extra:
            sets.append(f"{k}=?")
            args.append(extra[k])
    with DB_LOCK:
        cond, args_v = ("", ()) if versao is None else (" AND versao=?", (int(versao),))
        cur = DB.execute(f"UPDATE anuncio_rascunho_magalu_v2034 SET {', '.join(sets)} WHERE id=? AND situacao IN "
                         f"({','.join('?' * len(de))})" + cond, (*args, rid, *de, *args_v))
        DB.commit()
        if cur.rowcount != 1:
            return None
        row = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (rid,)).fetchone()
    return _magalu_rascunho_de_linha(row)


def _magalu_pacote_da_ficha(campos: dict[str, Any]) -> tuple[dict[str, float | None], list[str]]:
    """V20.34: peso (g) e medidas (cm) LIDOS DA FICHA agora; o que falta vai na lista."""
    def n(v: Any) -> float | None:
        try:
            x = float(str(v).replace(",", "."))
        except (TypeError, ValueError):
            return None
        return x if math.isfinite(x) and x > 0 else None
    m = {"peso_g": n(campos.get("peso_g")), "altura": n(campos.get("altura_cm")), "largura": n(campos.get("largura_cm")),
         "comprimento": n(campos.get("comprimento_cm"))}
    falta = [k.replace("_g", "") for k, v in m.items() if v is None]
    return m, falta


MAGALU_SKU_PERMITIDO = re.compile(r"^[A-Za-z0-9._-]+$")
MAGALU_CONFERIR_FOTOS_PRAZO_S = 25  # revisao: o Conferir roda na requisicao (nginx corta em 60 s)


def _magalu_conferir_local(r: dict[str, Any], *, fotos_prazo: float | None = MAGALU_CONFERIR_FOTOS_PRAZO_S
                           ) -> tuple[list[str], dict[str, Any]]:
    """V20.34: confere o rascunho contra o que a Magalu documenta (tamanhos, categoria e obrigatorios, fotos JPEG
    publicas) e a ficha (peso, medidas). Devolve (erros, contexto). Leitura que falha = erro (nunca adivinha)."""
    erros: list[str] = []
    avisos: list[str] = []
    ficha = ficha_ler(r["ficha_codigo"]) or {}
    campos = ficha.get("campos") or {}
    ctx: dict[str, Any] = {"avisos": avisos}
    sku = normalize(r["ficha_codigo"])
    if len(sku) > MAGALU_SKU_MAX:
        erros.append(f"O código do produto ({sku}) tem {len(sku)} caracteres: a Magalu aceita SKU de até {MAGALU_SKU_MAX}.")
    if not MAGALU_SKU_PERMITIDO.match(sku):
        # revisao: "/" (kit "A/B") e outros sinais no endereco da Magalu podem cair num 404 de rota, que seria lido
        # como "o SKU nao existe"; so letras, numeros, ponto, hifen e sublinhado
        erros.append(f"O código {sku} tem caractere que a Magalu pode não aceitar no SKU (só letras, números, “.”, “-” e “_”).")
    titulo = str(r.get("titulo") or "").strip()
    if not titulo:
        erros.append("Informe o título.")
    elif len(titulo) > MAGALU_TITULO_MAX:
        erros.append(f"Título com {len(titulo)} caracteres: a Magalu aceita até {MAGALU_TITULO_MAX}.")
    desc = str(r.get("descricao") or "").strip()
    if not desc:
        erros.append("Informe a descrição.")
    elif len(desc) > MAGALU_DESC_MAX:
        erros.append(f"Descrição com {len(desc)} caracteres: a Magalu aceita até {MAGALU_DESC_MAX}.")
    if "[CONFIRMAR]" in desc.upper():
        erros.append("A descrição ainda tem [CONFIRMAR]: troque pelo texto certo.")
    if not str(r.get("marca") or "").strip():
        erros.append("Informe a marca (a Magalu pede a marca em todo produto).")
    preco, preco_de = r.get("preco"), r.get("preco_de")
    if not preco:
        erros.append("Informe o preço.")
    elif preco_de and float(preco) > float(preco_de):
        erros.append("O preço “de” não pode ser menor que o preço de venda.")
    if not r.get("quantidade") or int(r["quantidade"]) < 1:
        erros.append("Informe a quantidade.")
    medidas, falta = _magalu_pacote_da_ficha(campos)
    ctx["medidas"] = medidas
    if falta:
        erros.append(f"Falta na ficha (Peso e medidas): {', '.join(falta)}. Preencha a ficha do produto.")
    ean = re.sub(r"\D", "", str(campos.get("ean") or ""))
    ctx["ean"] = ean if len(ean) in (8, 12, 13, 14) else ""
    if not ctx["ean"]:
        avisos.append("A ficha não tem EAN: o produto vai sem código de barras (a Magalu pode pedir depois).")
    for nome in (r.get("atributos") or {}):
        if len(nome) > 20:  # revisao: a spec do SKU limita o nome do atributo de variacao a 20
            erros.append(f"Atributo de variação “{nome}”: a Magalu aceita nome de até 20 caracteres.")
    fotos = list(r.get("fotos") or [])
    if not fotos:
        erros.append("Escolha pelo menos uma foto (as fotos vêm do anúncio do Mercado Livre deste produto).")
    else:
        e_f, a_f = _magalu_fotos_conferir(fotos, fotos_prazo)
        erros += e_f
        avisos += a_f
    cat = str(r.get("categoria") or "")
    ctx["defs"] = {"atributos": [], "ficha_tecnica": []}
    if not cat:
        erros.append("Escolha a categoria.")
        return erros, ctx
    try:
        defs = magalu_categoria_atributos(cat)
    except (RuntimeError, ValueError) as exc:
        erros.append(f"Não consegui ler a categoria na Magalu ({exc}).")
        return erros, ctx
    folha = magalu_categoria_folha(cat)
    if folha is False:
        erros.append("A categoria escolhida tem subcategorias: escolha a mais específica.")
    elif folha is None:
        avisos.append("Não consegui conferir se a categoria tem subcategorias.")
    ctx["defs"] = defs
    attrs, ficha_t = r.get("atributos") or {}, r.get("ficha_tecnica") or {}
    for grupo, valores, rotulo in (("atributos", attrs, "Atributo"), ("ficha_tecnica", ficha_t, "Ficha técnica")):
        for d in defs.get(grupo) or []:
            v = str(valores.get(d["nome"]) or "").strip()
            if d["obrigatorio"] and not v:
                erros.append(f"{rotulo} obrigatório sem valor: {d.get('rotulo') or d['nome']}.")
            elif v and d["valores"] and v not in d["valores"]:
                erros.append(f"{d.get('rotulo') or d['nome']}: escolha um valor da lista da Magalu.")
    return erros, ctx


MAGALU_MARCA_ENVIO = "noromak_envio"


def _magalu_marca_do_sku(lido: dict[str, Any] | None) -> str | None:
    """2a revisao: a marca do envio no SKU lido ('' = o SKU tem extra_data sem a marca; None = a resposta nao traz
    extra_data - ai vale o titulo)."""
    if not isinstance(lido, dict) or not isinstance(lido.get("extra_data"), list):
        return None
    for x in lido["extra_data"]:
        if isinstance(x, dict) and str(x.get("name") or "") == MAGALU_MARCA_ENVIO:
            return str(x.get("value") or "")
    return ""


MAGALU_CRIADO_ANTES_S = 120
MAGALU_CRIADO_DEPOIS_S = 3 * 24 * 3600


def _magalu_data_utc(texto: Any) -> datetime | None:
    """`2026-11-06T23:18:16.074000` (a Magalu manda sem fuso = UTC) ou ISO com fuso; invalido = None."""
    t = str(texto or "").strip().replace("Z", "+00:00")
    if not t:
        return None
    try:
        d = datetime.fromisoformat(t)
    except ValueError:
        return None
    return d if d.tzinfo else d.replace(tzinfo=timezone.utc)


def _magalu_sku_e_nosso(lido: dict[str, Any] | None, cod: str, titulo: Any, rid: int | None = None) -> bool:
    """2a revisao: o SKU lido foi criado por um envio do Noromak desta ficha? Pela marca (`rid:quando`) quando a
    Magalu devolve `extra_data`; sem ela, pelo titulo igual ao de um rascunho desta ficha que de fato enviou."""
    marca = _magalu_marca_do_sku(lido)
    with DB_LOCK:
        enviados = [dict(x) for x in DB.execute(
            "SELECT id, titulo, enviado_em, envios_json FROM anuncio_rascunho_magalu_v2034 WHERE ficha_codigo=? "
            "AND (COALESCE(enviado_em,'')<>'' OR COALESCE(envios_json,'[]')<>'[]')", (normalize(cod),)).fetchall()]
    if marca:
        rid_marca = marca.split(":", 1)[0]
        return rid_marca.isdigit() and int(rid_marca) in {int(x["id"]) for x in enviados}
    # 1o uso real (06/11, TUNAP109): a Magalu TROCA o extra_data pelo dela (IdProduct, update_only_front) e a marca
    # some. A prova passa a ser a data: o SKU foi criado (`created_at`, UTC) logo depois de um envio NOSSO desta ficha
    # (no maximo MAGALU_CRIADO_ANTES_S antes, por relogios diferentes, e ate MAGALU_CRIADO_DEPOIS_S depois). Um SKU de
    # outra ferramenta ja existia antes do envio (o Publicar le o SKU antes de enviar e recusa).
    criado = _magalu_data_utc(_magalu_texto(lido, "created_at"))
    if criado is not None:
        for x in enviados:
            try:
                horas = list(json.loads(x.get("envios_json") or "[]"))
            except (TypeError, ValueError):
                horas = []
            for h in horas + [x.get("enviado_em")]:  # V20.36: todos os envios, nao so o ultimo
                env = _magalu_data_utc(h)
                if env is not None and -MAGALU_CRIADO_ANTES_S <= (criado - env).total_seconds() <= MAGALU_CRIADO_DEPOIS_S:
                    return True
        return False
    titulo_lido = _magalu_texto(lido, "title")
    return _magalu_titulo_igual(titulo_lido, titulo) and any(_magalu_titulo_igual(x["titulo"], titulo_lido) for x in enviados)


def magalu_sku_corpo(r: dict[str, Any], ficha: dict[str, Any], ctx: dict[str, Any]) -> dict[str, Any]:
    """V20.34 (pura): corpo do POST /seller/v1/portfolios/skus (`additionalProperties: false`: so campos da spec)."""
    campos = ficha.get("campos") or {}
    m = ctx.get("medidas") or {}
    sku = normalize(r["ficha_codigo"])

    def dim(nome: str) -> dict[str, Any]:
        return {"name": nome,
                "height": {"value": round(max(0.001, float(m.get("altura") or 0)), 3), "unit": "cm"},
                "width": {"value": round(max(0.001, float(m.get("largura") or 0)), 3), "unit": "cm"},
                "length": {"value": round(max(0.001, float(m.get("comprimento") or 0)), 3), "unit": "cm"},
                "weight": {"value": max(1, int(math.ceil(float(m.get("peso_g") or 0)))), "unit": "g"}}
    ean = str(ctx.get("ean") or "")
    corpo: dict[str, Any] = {
        "sku": sku, "title": str(r.get("titulo") or "").strip(), "description": str(r.get("descricao") or "").strip(),
        "brand": str(r.get("marca") or "").strip(), "type": "product", "active": True,
        "group": {"id": sku[:50], "main_variation": True}, "channels": [{"id": MAGALU_CANAL_ID}],
        "identifiers": [{"type": "ean", "value": ean}] if ean else [], "has_ean": bool(ean),
        "datasheet": [{"name": k, "value": v} for k, v in (r.get("ficha_tecnica") or {}).items()],
        "attributes": [{"name": k, "value": v} for k, v in (r.get("atributos") or {}).items()],
        "dimensions": [dim("product"), dim("package")],
        "images": [{"reference": u, "type": "image/jpeg"} for u in r.get("fotos") or []],
        "videos": [], "podcasts": [], "origin": "national", "condition": "NEW",
        # 2a revisao: a marca do envio fica no proprio produto; o GET do SKU devolve `extra_data`, e so o SKU com a
        # marca de um rascunho desta ficha e tratado como nosso (o titulo pode ser mudado pela Magalu ou repetido)
        "extra_data": [{"name": MAGALU_MARCA_ENVIO, "value": str(ctx["marca_envio"])}] if ctx.get("marca_envio") else [],
    }
    if r.get("categoria"):
        corpo["category"] = {"id": str(r["categoria"])}
    ncm = re.sub(r"\D", "", str(campos.get("ncm") or ""))
    if len(ncm) == 8:
        corpo["ncm"] = ncm
    return corpo


def magalu_preco_corpo(r: dict[str, Any]) -> dict[str, Any]:
    """V20.34 (pura): preco em centavos, moeda BRL SEMPRE (no POST o padrao da Magalu e USD)."""
    por = int(round(float(r["preco"]) * 100))
    de = int(round(float(r.get("preco_de") or r["preco"]) * 100))
    return {"channel": {"id": MAGALU_CANAL_ID}, "list_price": max(de, por), "price": por, "currency": "BRL",
            "normalizer": 100}


def magalu_rascunho_conferir(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.34: conferencia local (a Magalu nao tem "conferir sem criar"). Certo = `validado`; errado = `rascunho`."""
    r = magalu_rascunho_ler(rascunho_id)
    if r is None:
        raise ValueError("Rascunho não encontrado.")
    if r["situacao"] not in MAGALU_RASCUNHO_EDITAVEL:
        raise ValueError("Este rascunho já foi publicado ou está em publicação.")
    erros, ctx = _magalu_conferir_local(r)
    para = "rascunho" if erros else "validado"
    novo = _magalu_trocar(int(r["id"]), MAGALU_RASCUNHO_EDITAVEL, para, erros, ator, versao=int(r["versao"]))
    if novo is None:
        raise FichaConflito(magalu_rascunho_ler(r["id"]) or {})
    return {"ok": not erros, "situacao": para, "erros": erros, "avisos": ctx.get("avisos") or [], "rascunho": novo}


def _magalu_sku_ler(sku: str) -> dict[str, Any] | None:
    """V20.34: o SKU na Magalu (None = nao existe). Erro de leitura sobe (MagaluRecusou/MagaluSemResposta)."""
    try:
        d = _magalu_chamar("GET", f"/seller/v1/portfolios/skus/{quote(sku, safe='')}")
    except MagaluRecusou as exc:
        if exc.status == 404:
            return None
        raise
    _anuncio_amostra("magalu_sku_ler", d)
    return d if isinstance(d, dict) else {}


def _magalu_canal_noromak(sku: str, r: dict[str, Any], ator: str, status: str = "", estoque: Any = None) -> None:
    """V20.34: anuncio criado pelo Noromak entra na lista (canal magalu, `noromak`, estoque Manual). SOB o DB_LOCK.
    Revisao: publicar de novo e reinclusao explicita do Admin (limpa `removido_em`, volta a Manual); o estoque e o
    lido na Magalu (None = sem leitura, nunca a quantidade pedida)."""
    agora = now_iso()
    DB.execute(
        "INSERT INTO anuncio_canal_v2023(canal,conta,anuncio_id,ficha_codigo,sku_anuncio,controle,titulo,preco,estoque,"
        "status,categoria,lido_em,controle_em,controle_por,estoque_modo) "
        "VALUES('magalu',?,?,?,?,'noromak',?,?,?,?,?,?,?,?,'manual') "
        "ON CONFLICT(canal,conta,anuncio_id) DO UPDATE SET ficha_codigo=excluded.ficha_codigo,controle='noromak',"
        "titulo=excluded.titulo,preco=excluded.preco,estoque=excluded.estoque,status=excluded.status,"
        "removido_em='',removido_por='',estoque_modo='manual',controle_em=excluded.controle_em,controle_por=excluded.controle_por",
        (MAGALU_ANUNCIO_CONTA, sku, r["ficha_codigo"], sku, str(r.get("titulo") or ""), r.get("preco"),
         estoque, str(status or ""), str(r.get("categoria") or ""), agora, agora, str(ator or "")))


def _magalu_ja_anunciado(cod: str, rid: int) -> str:
    """V20.34: o produto ja tem anuncio na Magalu criado pelo Noromak (ou outro rascunho em andamento)? SOB o DB_LOCK."""
    ja = DB.execute("SELECT anuncio_id FROM anuncio_canal_v2023 WHERE canal='magalu' AND ficha_codigo=? "
                    "AND COALESCE(removido_em,'')='' LIMIT 1", (cod,)).fetchone()
    if ja:
        return f"Este produto já tem anúncio na Magalu (SKU {ja['anuncio_id']})."
    outro = DB.execute("SELECT id FROM anuncio_rascunho_magalu_v2034 WHERE ficha_codigo=? AND id<>? AND situacao IN "
                       "('publicando','aguardando','incerto','publicado') LIMIT 1", (cod, rid)).fetchone()
    if outro:
        return f"O rascunho nº {outro['id']} deste produto já foi publicado ou está em publicação na Magalu."
    return ""


def magalu_publicar_reservar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.34: confere e troca `validado -> publicando` sob o DB_LOCK (um anuncio por produto). Erro = ValueError."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (rid,)).fetchone()
        if row is None:
            raise ValueError("Rascunho não encontrado.")
        r = _magalu_rascunho_de_linha(row)
        sit = r["situacao"]
        if sit in ("publicando", "aguardando"):
            raise ValueError("Este rascunho já está sendo publicado.")
        if sit == "publicado":
            raise ValueError(f"Este rascunho já foi publicado (SKU {r.get('sku') or ''}).")
        if sit == "incerto":
            raise ValueError("A última tentativa ficou sem confirmação da Magalu: confira e use “Conferir de novo” ou “Liberar”.")
        if sit != "validado":
            raise ValueError("Confira antes de publicar.")
        motivo = _magalu_ja_anunciado(str(r["ficha_codigo"]), rid)
        if motivo:
            raise ValueError(motivo)
        cur = DB.execute("UPDATE anuncio_rascunho_magalu_v2034 SET situacao='publicando', erros_json='[]', versao=versao+1, "
                         "reservado_em=?, atualizado_em=?, atualizado_por=? WHERE id=? AND situacao='validado'",
                         (now_iso(), now_iso(), str(ator or ""), rid))
        DB.commit()
        if cur.rowcount != 1:
            raise ValueError("Este rascunho já está sendo publicado.")
    return r


def _magalu_titulo_igual(a: Any, b: Any) -> bool:
    return " ".join(_anuncio_sem_acento(a).split()) == " ".join(_anuncio_sem_acento(b).split()) and bool(str(a or "").strip())


def magalu_publicar_executar(r: dict[str, Any], ator: str) -> dict[str, Any]:
    """V20.34: o trabalho do Publicar (rascunho ja em `publicando`). Falha antes do envio = `validado` (nada criado).
    Enviado (202, ou sem resposta) = `aguardando`: o acompanhamento le o SKU na Magalu e manda preco e estoque.
    Revisao: a marca "enviado" (`enviado_em`) e gravada ANTES do POST; no boot, `publicando` sem ela volta a
    `validado` (o envio nunca saiu: nao ha o que acompanhar, e um SKU alheio com o mesmo codigo nunca e tomado)."""
    rid, cod = int(r["id"]), str(r["ficha_codigo"])
    sku = normalize(cod)
    estado: dict[str, Any] = {"fim": None, "enviado": False}

    def fim(para: str, erros: list[str], **extra: Any) -> dict[str, Any]:
        novo = _magalu_trocar(rid, ("publicando",), para, erros, ator, extra=extra)
        estado["fim"] = novo or magalu_rascunho_ler(rid) or r
        audit(ator, "anuncios.magalu_publicar", f"{cod}|{rid}|{para}|{'; '.join(erros)[:500]}")
        return {"ok": para in ("aguardando", "publicado"), "situacao": para, "sku": sku, "erros": erros,
                "rascunho": estado["fim"]}

    try:
        try:
            ficha_ap = anuncio_ficha_payload(cod, ler_apollo=True, filiais=(MAGALU_ANUNCIO_CONTA,))
        except Exception as exc:
            ficha_ap = None
            print(f"Aviso: Apollo nao lido para publicar {cod} na Magalu: {exc}", file=sys.stderr)
        est = (((ficha_ap or {}).get("estoque") or {}).get(MAGALU_ANUNCIO_CONTA) or {})
        dpm = est.get("da_para_montar") if isinstance(est, dict) else None
        qtd = int(r.get("quantidade") or 0)
        if dpm is None:
            return fim("validado", ["O Apollo não respondeu (ou a fila não foi lida) — não publicado. Tente de novo."])
        if int(dpm) <= 0:
            return fim("validado", ["Sem estoque no Apollo de Araçatuba para montar este produto — não publicado."])
        if qtd < 1 or qtd > int(dpm):
            return fim("validado", [f"Quantidade {qtd} acima do que dá para montar no Apollo ({int(dpm)}) — não publicado."])
        erros, ctx = _magalu_conferir_local(r, fotos_prazo=None)
        if erros:
            return fim("validado", erros)
        try:
            ja = _magalu_sku_ler(sku)
        except (MagaluRecusou, MagaluSemResposta) as exc:
            return fim("validado", [f"Não consegui conferir na Magalu se o SKU {sku} já existe ({exc}). Nada foi criado."])
        if ja is not None:
            if _magalu_sku_e_nosso(ja, cod, r.get("titulo")):
                # revisao: o SKU que um envio NOSSO anterior criou tarde ("Não foi criado" antes de ele aparecer):
                # mesmo codigo e mesmo titulo = segue para preco e estoque, sem criar de novo
                return fim("aguardando", ["O produto deste envio já está na Magalu: o Noromak segue com o preço e o estoque."],
                           sku=sku, etapa_em=now_iso(), etapa="sku", tentativas=0)  # V20.36: sem trocar o enviado_em
            return fim("validado", [f"Já existe um produto com o SKU {sku} na Magalu (criado fora do Noromak). Nada foi "
                                    "enviado: o Noromak não sobrescreve produto de outra ferramenta."])
        agora = now_iso()
        ctx["marca_envio"] = f"{rid}:{agora}"
        corpo = magalu_sku_corpo(r, ficha_ler(cod) or {"codigo": cod}, ctx)
        with DB_LOCK:  # revisao: marca "enviado" antes do POST (o boot so acompanha o que de fato saiu)
            antes = DB.execute("SELECT envios_json FROM anuncio_rascunho_magalu_v2034 WHERE id=?", (rid,)).fetchone()
            try:
                envios = list(json.loads(antes["envios_json"] or "[]")) if antes else []
            except (TypeError, ValueError):
                envios = []
            DB.execute("UPDATE anuncio_rascunho_magalu_v2034 SET sku=?, enviado_em=?, envios_json=?, etapa='sku', "
                       "tentativas=0 WHERE id=? AND situacao='publicando'", (sku, agora, json.dumps((envios + [agora])[-50:]), rid))
            sem_este = json.dumps(envios[-50:])  # V20.36: recusado = o envio sai do historico
            DB.commit()
        estado["enviado"] = True
        try:
            resp = _magalu_chamar("POST", "/seller/v1/portfolios/skus", payload=corpo)
        except MagaluRecusou as exc:
            _anuncio_amostra("magalu_criar_sku [erro]", {"erro": str(exc), "corpo": exc.corpo, "enviado": corpo})
            if exc.status == 429:
                return fim("validado", ["A Magalu está com muitas chamadas agora (429): nada foi criado. Tente em 1 minuto."],
                           enviado_em=None, envios_json=sem_este)
            if exc.status == 423:
                return fim("validado", [f"A Magalu está com o cadastro bloqueado no momento (423): {exc}. Nada foi criado."],
                           enviado_em=None, envios_json=sem_este)
            return fim("erro", [f"A Magalu recusou: {exc}"], enviado_em=None, etapa="", envios_json=sem_este)
        except MagaluSemResposta as exc:
            _anuncio_amostra("magalu_criar_sku [erro]", {"erro": str(exc), "enviado": corpo})
            return fim("aguardando", [f"Sem resposta da Magalu no envio ({exc}). O Noromak confere sozinho se o SKU "
                                      "apareceu."], sku=sku, enviado_em=agora, etapa="sku")
        _anuncio_amostra("magalu_criar_sku", {"resposta": resp, "enviado": corpo})
        trace = _magalu_texto(resp, "trace_id", "id") if isinstance(resp, dict) else ""
        return fim("aguardando", [], sku=sku, trace_id=trace, enviado_em=agora, etapa="sku")
    finally:
        if estado["fim"] is None:
            try:
                if estado["enviado"]:
                    fim("aguardando", ["Falha depois do envio: o Noromak confere sozinho se o SKU apareceu."],
                        sku=sku, etapa="sku")
                else:
                    fim("validado", ["Falha inesperada antes de criar o anúncio; nada foi criado na Magalu."])
            except Exception as exc:
                print(f"Aviso: rascunho Magalu {rid} nao saiu de publicando: {exc}", file=sys.stderr)


def magalu_publicar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.34: reserva e publica (sincrono; a rota usa magalu_publicar_iniciar)."""
    return magalu_publicar_executar(magalu_publicar_reservar(rascunho_id, ator), ator)


def magalu_publicar_iniciar(rascunho_id: Any, ator: str) -> dict[str, Any]:
    """V20.34: a rota reserva aqui (erro = 400 na hora) e o resto roda numa thread que solta o ANUNCIOS_PUBLICAR_LOCK
    no fim (conferir as fotos baixando cada uma pode passar dos 60 s do nginx). Chamar COM a trava pega."""
    r = magalu_publicar_reservar(rascunho_id, ator)
    resposta = {"ok": True, "iniciado": True, "rascunho": magalu_rascunho_ler(r["id"])}

    def rodar() -> None:
        try:
            magalu_publicar_executar(r, ator)
        except Exception as exc:
            print(f"Aviso: publicar na Magalu {r['id']} falhou: {exc}", file=sys.stderr)
        finally:
            ANUNCIOS_PUBLICAR_LOCK.release()
    try:
        threading.Thread(target=rodar, name=f"magalu-publicar-{r['id']}", daemon=True).start()
    except BaseException:
        _magalu_trocar(int(r["id"]), ("publicando",), "validado", ["A publicação não começou; tente de novo."], ator)
        raise
    return resposta


def _magalu_trace_erro(trace_id: str) -> str:
    """V20.34: o resultado do 202 (GET /v0/traces/{id}): o texto do erro, ou '' (sem erro ou sem leitura).
    Revisao: a falha de leitura tambem fica na amostra (o endereco do trace nao esta numa spec publicada)."""
    if not trace_id:
        return ""
    try:
        d = _magalu_chamar("GET", f"/v0/traces/{quote(trace_id, safe='')}", timeout=20)
    except (MagaluRecusou, MagaluSemResposta) as exc:
        _anuncio_amostra("magalu_trace [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None)})
        return ""
    _anuncio_amostra("magalu_trace", d)
    msgs = []
    for t in _magalu_lista(d) or ([d] if isinstance(d, dict) else []):
        if isinstance(t, dict) and str(t.get("severity") or "").lower() in ("error", "critical"):
            msgs.append(_magalu_texto(t, "message", "code") or "erro sem mensagem")
    return "; ".join(msgs)[:600]


def _magalu_acompanhar_trava(rid: int) -> threading.Lock:
    with _MAGALU_ACOMPANHAR_LOCKS_LOCK:
        return _MAGALU_ACOMPANHAR_LOCKS.setdefault(rid, threading.Lock())


MAGALU_ETAPA_TENTATIVAS = 5        # revisao: preco/estoque recusado 5 vezes (ou 30 min) = erro, sem laco infinito
MAGALU_CONFIRMAR_PRAZO_S = 10 * 60  # preco/estoque aceitos (202) e ainda nao mostrados: publica com aviso depois disso


def _magalu_passou(iso: Any) -> float:
    try:
        quando = datetime.fromisoformat(str(iso or ""))
    except ValueError:
        return float("inf")
    if quando.tzinfo is None:
        quando = quando.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - quando).total_seconds()


def _magalu_passou_envio(r: dict[str, Any]) -> float:
    """V20.36: tempo desde o envio OU desde o "Conferir de novo" (etapa_em), o que for mais recente."""
    return min(_magalu_passou(r.get("enviado_em")), _magalu_passou(r.get("etapa_em")))


def _magalu_preco_ler(sku: str) -> int | None:
    """V20.34 (revisao): o preco de venda (centavos) do nosso canal; None = sem preco ou sem leitura."""
    try:
        d = _magalu_chamar("GET", f"/seller/v1/portfolios/prices/{quote(sku, safe='')}", timeout=20)
    except MagaluRecusou as exc:
        if exc.status == 404:
            return None
        raise
    _anuncio_amostra("magalu_preco_ler", d)
    for x in _magalu_lista(d):
        canal = x.get("channel") if isinstance(x, dict) and isinstance(x.get("channel"), dict) else {}
        if canal.get("id") and str(canal["id"]) != MAGALU_CANAL_ID:
            continue
        p = x.get("price") if isinstance(x, dict) else None
        if isinstance(p, (int, float)) and not isinstance(p, bool):
            norm = x.get("normalizer") if isinstance(x.get("normalizer"), (int, float)) else 100
            return int(round(float(p) * 100 / float(norm or 100)))
    return None


def _magalu_preco_enviar(sku: str, r: dict[str, Any]) -> None:
    """V20.34 (revisao): POST quando o SKU ainda nao tem preco no canal, PATCH quando ja tem (repetir o POST pode
    ser recusado). Erro sobe."""
    corpo = magalu_preco_corpo(r)
    metodo = "PATCH" if _magalu_preco_ler(sku) is not None else "POST"
    resp = _magalu_chamar(metodo, f"/seller/v1/portfolios/prices/{quote(sku, safe='')}", payload=corpo, timeout=20)
    _anuncio_amostra(f"magalu_preco_{metodo.lower()}", resp)


def _magalu_dpm_agora(cod: str) -> int | None:
    """V20.34 (revisao): o que da para montar no Apollo de Araçatuba AGORA (None = sem leitura)."""
    try:
        ficha_ap = anuncio_ficha_payload(cod, ler_apollo=True, filiais=(MAGALU_ANUNCIO_CONTA,))
    except Exception as exc:
        print(f"Aviso: Apollo nao lido para o estoque inicial de {cod} na Magalu: {exc}", file=sys.stderr)
        return None
    est = (((ficha_ap or {}).get("estoque") or {}).get(MAGALU_ANUNCIO_CONTA) or {})
    dpm = est.get("da_para_montar") if isinstance(est, dict) else None
    return None if dpm is None else max(0, int(dpm))


def _magalu_acompanhar_um(r: dict[str, Any], ator: str) -> dict[str, Any] | None:
    """V20.34: um passo do rascunho `aguardando` (etapas sku -> preco -> estoque -> confirmar). Chamar com a trava
    do rascunho. Cada etapa so grava quando algo mudou (sem subir a versao a toa)."""
    rid = int(r["id"])
    sku = str(r.get("sku") or normalize(r["ficha_codigo"]))
    etapa = str(r.get("etapa") or "sku")
    tent = int(r.get("tentativas") or 0)

    def ficar(msg: str, **extra: Any) -> dict[str, Any] | None:
        if [msg] == (r.get("erros") or []) and not extra:
            return r
        return _magalu_trocar(rid, ("aguardando",), "aguardando", [msg] if msg else [], ator, extra=extra)

    if etapa == "sku":
        try:
            lido = _magalu_sku_ler(sku)
        except (MagaluRecusou, MagaluSemResposta) as exc:
            if _magalu_passou_envio(r) > MAGALU_ACOMPANHAR_PRAZO_S:  # revisao: o prazo conta tambem aqui
                return _magalu_trocar(rid, ("aguardando",), "incerto", [MAGALU_INCERTO_TEXTO, f"Última leitura: {exc}"], ator)
            return ficar(f"Magalu sem resposta ao conferir o SKU ({str(exc)[:200]}); tento de novo em instantes.")
        if lido is None:
            erro = _magalu_trace_erro(str(r.get("trace_id") or ""))
            if erro:  # 2a revisao: nada foi criado - o envio deixa de valer como prova de SKU nosso
                # V20.36: o envio recusado tambem sai do historico (nao pode provar que um SKU de outro e nosso)
                restantes = [h for h in (r.get("envios") or []) if h != r.get("enviado_em")]
                return _magalu_trocar(rid, ("aguardando",), "erro", [f"A Magalu recusou: {erro}"], ator,
                                      extra={"etapa": "", "enviado_em": None, "envios_json": json.dumps(restantes)})
            if _magalu_passou_envio(r) > MAGALU_ACOMPANHAR_PRAZO_S:
                return _magalu_trocar(rid, ("aguardando",), "incerto", [MAGALU_INCERTO_TEXTO], ator)
            return r
        if not _magalu_sku_e_nosso(lido, str(r["ficha_codigo"]), r.get("titulo"), rid):
            # revisao: o SKU existe mas nao e o que enviamos (outra ferramenta usa o mesmo codigo): nunca toma
            return _magalu_trocar(rid, ("aguardando",), "erro", [
                f"O SKU {sku} existe na Magalu, mas não é o que o Noromak enviou (título “{_magalu_texto(lido, 'title')[:120]}”, "
                "sem a marca do envio). Nada foi alterado na Magalu."], ator, extra={"etapa": ""})
        r = _magalu_trocar(rid, ("aguardando",), "aguardando", [], ator,
                           extra={"etapa": "preco", "etapa_em": now_iso(), "tentativas": 0,
                                  "status_magalu": _magalu_texto(lido, "status")[:60]}) or r
        etapa, tent = "preco", 0

    def falhou(o_que: str, exc: Exception) -> dict[str, Any] | None:
        n = tent + 1
        if n >= MAGALU_ETAPA_TENTATIVAS or _magalu_passou(r.get("etapa_em")) > MAGALU_ACOMPANHAR_PRAZO_S:
            return _magalu_trocar(rid, ("aguardando",), "erro", [
                f"O produto {sku} foi criado na Magalu, mas {o_que} não foi aceito ({str(exc)[:300]}). Ajuste no painel da "
                "Magalu e use “Conferir de novo”."], ator, extra={"tentativas": n})
        return ficar(f"O produto {sku} foi criado na Magalu, mas {o_que} ainda não foi aceito ({str(exc)[:200]}). "
                     f"Tentativa {n} de {MAGALU_ETAPA_TENTATIVAS}.", tentativas=n)

    if etapa == "preco":
        try:
            _magalu_preco_enviar(sku, r)
        except (MagaluRecusou, MagaluSemResposta) as exc:
            _anuncio_amostra("magalu_preco [erro]", {"erro": str(exc), "corpo": getattr(exc, "corpo", None)})
            return falhou("o preço", exc)
        r = _magalu_trocar(rid, ("aguardando",), "aguardando", [], ator,
                           extra={"etapa": "estoque", "etapa_em": now_iso(), "tentativas": 0}) or r
        etapa, tent = "estoque", 0
    if etapa == "estoque":
        dpm = _magalu_dpm_agora(str(r["ficha_codigo"]))
        if dpm is None:  # revisao: o estoque inicial e o do Apollo AGORA (nunca o pedido de horas atras)
            if _magalu_passou(r.get("etapa_em")) > MAGALU_ACOMPANHAR_PRAZO_S:  # 2a revisao: so o prazo, sem tentativa
                return falhou("o estoque", RuntimeError("o Apollo não respondeu por 30 min: não envio estoque sem leitura"))
            return ficar("Esperando a leitura do Apollo de Araçatuba para mandar o estoque inicial.")
        qtd = min(int(r.get("quantidade") or 0), dpm)
        envio = _magalu_estoque_enviar(sku, qtd, criar=True)
        if envio["erro"]:
            return falhou("o estoque", RuntimeError(envio["erro"]))
        r = _magalu_trocar(rid, ("aguardando",), "aguardando", [], ator,
                           extra={"etapa": "confirmar", "etapa_em": now_iso(), "tentativas": 0, "qtd_enviada": qtd}) or r
        etapa = "confirmar"
    # confirmar: o preco e o estoque aceitos (202) aparecem na Magalu?
    preco_ok = estoque_lido = None
    try:
        preco_ok = _magalu_preco_ler(sku) == magalu_preco_corpo(r)["price"]
        estoque_lido = _magalu_estoque_ler(sku).get("estoque")
    except (MagaluRecusou, MagaluSemResposta):
        pass
    confirmado = bool(preco_ok) and estoque_lido is not None and estoque_lido == int(r.get("qtd_enviada") or 0)
    if not confirmado and _magalu_passou(r.get("etapa_em")) <= MAGALU_CONFIRMAR_PRAZO_S:
        return ficar("Preço e estoque enviados; esperando a Magalu mostrar.")
    avisos: list[str] = []
    if not confirmado:
        avisos.append("A Magalu ainda não mostra " + " e ".join(
            t for t, ok in (("o preço", preco_ok), ("o estoque", estoque_lido == int(r.get("qtd_enviada") or 0))) if not ok)
            + " enviado(s): confira no painel da Magalu.")
    status = str(r.get("status_magalu") or "")
    if status and status.lower() not in ("published", "publicado", "new", "draft", "policies_approved"):
        avisos.append(f"A Magalu mostra o produto como “{status}”: confira no painel da Magalu se há bloqueio.")
    if int(r.get("qtd_enviada") or 0) < int(r.get("quantidade") or 0):
        avisos.append(f"Estoque inicial {int(r.get('qtd_enviada') or 0)} (o Apollo de Araçatuba tinha menos que o pedido).")
    with DB_LOCK:
        try:
            cur = DB.execute("UPDATE anuncio_rascunho_magalu_v2034 SET situacao='publicado', etapa='publicado', "
                             "erros_json=?, versao=versao+1, atualizado_em=?, atualizado_por=? "
                             "WHERE id=? AND situacao='aguardando'",
                             (json.dumps(avisos, ensure_ascii=False), now_iso(), str(ator or ""), rid))
            if cur.rowcount == 1:
                _magalu_canal_noromak(sku, r, ator, status, estoque_lido)
            DB.commit()
        except Exception:
            DB.rollback()
            raise
    audit(ator, "anuncios.magalu_publicado", f"{r['ficha_codigo']}|{rid}|{sku}|{status}")
    return magalu_rascunho_ler(rid)


def magalu_acompanhar(rascunho_id: Any, ator: str = "sistema", *, forcar: bool = False) -> dict[str, Any] | None:
    """V20.34: um rascunho `aguardando` (fora do DB_LOCK; um por vez por rascunho: worker e tela nunca juntos).
    Revisao: o intervalo minimo e conferido DENTRO da trava; a trava sai da memoria quando o rascunho sai de aguardando."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        return None
    trava = _magalu_acompanhar_trava(rid)
    if not trava.acquire(blocking=False):
        return magalu_rascunho_ler(rid)
    r = None
    saiu = False  # 2a revisao: so limpa a trava/o intervalo quando o rascunho saiu de aguardando de verdade
    try:
        agora_m = time.monotonic()
        if not forcar and agora_m - _MAGALU_ACOMPANHAR_VISTO.get(rid, 0.0) < MAGALU_ACOMPANHAR_INTERVALO_S:
            return magalu_rascunho_ler(rid)
        _MAGALU_ACOMPANHAR_VISTO[rid] = agora_m
        r = magalu_rascunho_ler(rid)
        if r is None or r["situacao"] != "aguardando":
            saiu = True
            return r
        r = _magalu_acompanhar_um(r, ator) or magalu_rascunho_ler(rid)
        saiu = r is None or r.get("situacao") != "aguardando"
        return r
    finally:
        trava.release()
        if saiu:
            with _MAGALU_ACOMPANHAR_LOCKS_LOCK:
                _MAGALU_ACOMPANHAR_LOCKS.pop(rid, None)
            _MAGALU_ACOMPANHAR_VISTO.pop(rid, None)


def magalu_acompanhar_iniciar(rascunho_id: Any, ator: str) -> dict[str, Any] | None:
    """V20.34 (revisao): a rota so dispara o acompanhamento em segundo plano e devolve o rascunho como esta (cada
    chamada a Magalu espera ate 35 s; o nginx corta em 60). A tela pede de novo em 5 s."""
    r = magalu_rascunho_ler(rascunho_id)
    if r is None or r["situacao"] != "aguardando":
        return r
    threading.Thread(target=_magalu_acompanhar_seguro, args=(int(r["id"]), ator), daemon=True,
                     name=f"magalu-acompanhar-{r['id']}").start()
    return r


def _magalu_acompanhar_seguro(rid: int, ator: str, forcar: bool = False) -> None:
    try:
        magalu_acompanhar(rid, ator, forcar=forcar)
    except Exception as exc:
        print(f"Aviso: acompanhar rascunho Magalu {rid}: {exc}", file=sys.stderr)


MAGALU_ACOMPANHAR_LOTE = 3
MAGALU_ACOMPANHAR_ESPERA_S = 15     # revisao: a volta do estoque espera no maximo isso (Magalu lenta nao segura o ML)
_MAGALU_PENDENTES_LOCK = threading.Lock()


def magalu_acompanhar_pendentes(limite: int = MAGALU_ACOMPANHAR_LOTE) -> int:
    """V20.34: confere os rascunhos `aguardando` (sem nenhum, nem le a Magalu). Uma rodada por vez."""
    if not _MAGALU_PENDENTES_LOCK.acquire(blocking=False):
        return 0
    try:
        with DB_LOCK:
            todos = [int(x[0]) for x in DB.execute("SELECT id FROM anuncio_rascunho_magalu_v2034 "
                                                    "WHERE situacao='aguardando' ORDER BY id").fetchall()]
        # 2a revisao: os ha mais tempo sem conferir primeiro (o atualizado_em nao muda quando nada mudou)
        ids = sorted(todos, key=lambda x: _MAGALU_ACOMPANHAR_VISTO.get(x, 0.0))[:int(limite)]
        for rid in ids:
            _magalu_acompanhar_seguro(rid, "sistema")
        return len(ids)
    finally:
        _MAGALU_PENDENTES_LOCK.release()


def magalu_acompanhar_pendentes_fundo() -> None:
    """V20.34 (revisao): a volta do worker do estoque chama isto: o acompanhamento roda numa thread e a volta espera
    no maximo MAGALU_ACOMPANHAR_ESPERA_S. Sem rascunho aguardando, nem cria a thread."""
    with DB_LOCK:
        tem = DB.execute("SELECT 1 FROM anuncio_rascunho_magalu_v2034 WHERE situacao='aguardando' LIMIT 1").fetchone()
    if tem is None or _MAGALU_PENDENTES_LOCK.locked():
        return
    t = threading.Thread(target=magalu_acompanhar_pendentes, daemon=True, name="magalu-acompanhar")
    t.start()
    t.join(MAGALU_ACOMPANHAR_ESPERA_S)


def magalu_incerto_liberar(rascunho_id: Any, acao: Any, ator: str) -> dict[str, Any]:
    """V20.34: o Admin conferiu no painel da Magalu. `conferir` = volta a `aguardando` (o Noromak le o SKU de novo e
    segue SO se o titulo for o enviado); `nao_criado` = volta a `validado`. Revisao: `conferir` so a partir de
    `incerto`, ou de `erro` depois que o SKU ja foi reconhecido como nosso (preco/estoque recusado) - um `erro` de
    recusa do envio nunca vira `aguardando` (tomaria o SKU de outra ferramenta)."""
    try:
        rid = int(rascunho_id)
    except (TypeError, ValueError):
        raise ValueError("Rascunho não encontrado.")
    acao = str(acao or "").strip()
    if acao not in ("conferir", "nao_criado"):
        raise ValueError("Ação inválida.")
    atual = magalu_rascunho_ler(rid)
    if atual is None:
        raise ValueError("Rascunho não encontrado.")
    novo = None
    if acao == "conferir":
        if atual["situacao"] == "incerto":
            novo = _magalu_trocar(rid, ("incerto",), "aguardando", [], ator,
                                  extra={"etapa_em": now_iso(), "etapa": "sku", "tentativas": 0})  # V20.36
        elif atual["situacao"] == "erro" and (str(atual.get("etapa") or "") in ("preco", "estoque", "confirmar")
                                              or str(atual.get("enviado_em") or "")):
            # 1o uso real: o envio saiu e o SKU nao foi reconhecido; o acompanhamento confere de novo se e nosso
            novo = _magalu_trocar(rid, ("erro",), "aguardando", [], ator, extra={"etapa_em": now_iso(), "tentativas": 0})
    elif atual["situacao"] == "incerto":
        novo = _magalu_trocar(rid, ("incerto",), "validado", [], ator)
    if novo is None:
        raise ValueError("Este rascunho não está aguardando conferência na Magalu.")
    audit(ator, "anuncios.magalu_liberar", f"{novo['ficha_codigo']}|{rid}|{acao}")
    if acao == "conferir":
        novo = magalu_acompanhar_iniciar(rid, ator) or novo  # revisao: em segundo plano (nginx 60 s)
    return {"ok": True, "rascunho": novo}


# ---- estoque da Magalu (a conta de estoque 'magalu' = linhas canal='magalu', conta='aracatuba') ----
def _magalu_estoque_ler(sku: str) -> dict[str, Any]:
    """V20.34: GET /seller/v1/portfolios/stocks/{sku}: {existe, estoque, branches}. Estoque = soma do AVAILABLE do
    nosso canal; sem linha AVAILABLE ou quantidade sem numero = None (nunca 0)."""
    try:
        d = _magalu_chamar("GET", f"/seller/v1/portfolios/stocks/{quote(sku, safe='')}", timeout=MAGALU_ESTOQUE_TIMEOUT)
    except MagaluRecusou as exc:
        if exc.status == 404:
            return {"existe": False, "estoque": None, "branches": [], "linhas": 0}
        raise
    _anuncio_amostra("magalu_estoque_ler", d)
    linhas = [x for x in _magalu_lista(d) if isinstance(x, dict)]
    disp = []
    for x in linhas:
        if str(x.get("type") or "AVAILABLE").upper() != "AVAILABLE":
            continue
        canal = x.get("channel") if isinstance(x.get("channel"), dict) else {}
        if canal.get("id") and str(canal["id"]) != MAGALU_CANAL_ID:
            continue
        disp.append(x)
    estoque: int | None = None
    try:
        if disp and all(isinstance(x.get("quantity"), (int, float)) and not isinstance(x.get("quantity"), bool) for x in disp):
            estoque = int(sum(int(x["quantity"]) for x in disp))
    except (TypeError, ValueError):
        estoque = None
    branches = sorted({str((x.get("branch") or {}).get("id") or "") for x in disp if isinstance(x.get("branch"), dict)} - {""})
    return {"existe": True, "estoque": estoque, "branches": branches, "linhas": len(disp)}


def _magalu_estoque_enviar(sku: str, qtd: int, criar: bool = False) -> dict[str, Any]:
    """V20.34 (revisao): le e grava o estoque (absoluto): PATCH quando ja ha linha AVAILABLE, POST quando nao; com o
    branch unico; dois CDs = recusa. NAO rele (a gravacao e assincrona). {erro, antes, lido, aceito}."""
    out: dict[str, Any] = {"erro": "", "antes": None, "lido": {}, "aceito": False, "metodo": "stocks"}
    try:
        antes = _magalu_estoque_ler(sku)
    except (MagaluRecusou, MagaluSemResposta) as exc:
        out["erro"] = f"não consegui ler o estoque na Magalu ({exc})"
        return out
    out["antes"], out["lido"] = antes["estoque"], antes
    if not antes["existe"] and not criar:
        out["erro"] = "a Magalu não achou o SKU nesta loja"
        return out
    # 2a revisao: no estoque inicial (SKU ja reconhecido como nosso) o 404 do GET e "sem estoque ainda": POST
    if len(antes["branches"]) > 1:
        out["erro"] = ("o SKU tem estoque em mais de um centro de distribuição na Magalu (" + ", ".join(antes["branches"])
                       + "): ajuste na Magalu, o Noromak não escolhe")
        return out
    corpo: dict[str, Any] = {"channel": {"id": MAGALU_CANAL_ID}, "quantity": int(qtd), "type": "AVAILABLE"}
    if antes["branches"]:
        corpo["branch"] = {"id": antes["branches"][0]}
    metodo = "PATCH" if antes.get("linhas") else "POST"
    out["metodo"] = f"stocks {metodo}"
    try:
        r = _magalu_chamar(metodo, f"/seller/v1/portfolios/stocks/{quote(sku, safe='')}", payload=corpo,
                           timeout=MAGALU_ESTOQUE_TIMEOUT)
        _anuncio_amostra(f"magalu_estoque_{metodo.lower()}", r)
        out["aceito"] = True
    except MagaluRecusou as exc:
        _anuncio_amostra(f"magalu_estoque_{metodo.lower()} [erro]", {"erro": str(exc), "corpo": exc.corpo})
        out["erro"] = f"a Magalu recusou: {exc}"
    except MagaluSemResposta as exc:
        out["sem_resposta"] = f"sem resposta da Magalu ({exc})"
    return out


MAGALU_ESTOQUE_SEM_MOSTRAR_MAX = 3
_MAGALU_ESTOQUE_SEM_MOSTRAR: dict[str, int] = {}


def _magalu_estoque_gravar_api(sku: str, qtd: int, ficha_codigo: str = "") -> dict[str, Any]:
    """V20.34: le, grava (absoluto) e rele; so e ok quando a Magalu mostra o numero (a gravacao e assincrona).
    Revisao: aceito (202) e ainda nao mostrado = `ignorado` "aguardando a Magalu" (nao conta como erro nem para o
    Automatico; a proxima rodada confere); releitura curta (a rota do Manual nao pode passar dos 60 s)."""
    res: dict[str, Any] = {"ok": False, "antes": None, "depois": None, "metodo": "stocks", "erro": "", "lido": {}}
    if ficha_codigo and normalize(sku) != normalize(ficha_codigo):
        res["erro"] = f"o SKU {sku} não é o código da ficha ({ficha_codigo}): nada enviado"
        return res
    envio = _magalu_estoque_enviar(sku, qtd)
    res.update(antes=envio["antes"], metodo=envio["metodo"])
    if envio["erro"]:
        res["erro"] = envio["erro"]
        return res
    for espera in MAGALU_ESTOQUE_RELEITURA_ESPERAS:
        time.sleep(espera)
        try:
            depois = _magalu_estoque_ler(sku)["estoque"]
        except (MagaluRecusou, MagaluSemResposta):
            continue
        if depois is None:
            continue
        res["depois"] = depois
        if depois == qtd:
            res.update(ok=True, erro="")
            _MAGALU_ESTOQUE_SEM_MOSTRAR.pop(sku, None)
            return res
    if envio.get("aceito") or envio.get("sem_resposta"):
        n = _MAGALU_ESTOQUE_SEM_MOSTRAR.get(sku, 0) + 1
        _MAGALU_ESTOQUE_SEM_MOSTRAR[sku] = n
        if n >= MAGALU_ESTOQUE_SEM_MOSTRAR_MAX:  # 2a revisao: sem laco calado - na 3a vez seguida conta como erro
            _MAGALU_ESTOQUE_SEM_MOSTRAR.pop(sku, None)
            res["erro"] = (f"a Magalu aceitou o estoque {n} vezes seguidas e não mostra o número (mostra "
                           f"{res['depois'] if res['depois'] is not None else 'sem número'}, enviado {qtd}): confira no painel")
            return res
        res.update(ignorado="aguardando_magalu",
                   erro=(f"a Magalu aceitou ({'sem resposta' if envio.get('sem_resposta') else '202'}) e ainda mostra "
                         f"{res['depois'] if res['depois'] is not None else 'sem número'} (enviado {qtd}); a próxima rodada confere"))
    return res


# ---------------------------------------------------------------------------
# V20.26 - Estoque dos anuncios (fase 3; plano docs/superpowers/plans/2026-11-05-anuncios-fase3-estoque.md).
# Excecao a regra "o Noromak nunca grava estoque": grava no ML, SO em anuncio `controle='noromak'` (nunca Full,
# Alephee ou removido pelo ADMIN). Manual = o Admin digita e vai na hora; Automatico = Apollo da filial menos o
# vendido e nao baixado (kit = peca que da menos). Valor desconhecido nunca vira zero (nao envia).
# A UNICA funcao que grava estoque no ML e `ml_estoque_gravar` (sempre rele o anuncio para confirmar).
# ---------------------------------------------------------------------------
ANUNCIO_ESTOQUE_MODOS = ("manual", "automatico")
ANUNCIO_ESTOQUE_CONTA_MODOS = ("simulacao", "lote", "automatico")
ANUNCIO_ESTOQUE_LOG_MAX = 20000
ANUNCIO_ESTOQUE_MAX = 99999
# V20.26 (revisao): anuncio parado no ML nao recebe estoque (o worker repetia o erro a cada 10 min para sempre)
ANUNCIO_ESTOQUE_STATUS_PARADO = {"closed": "encerrado", "inactive": "inativo", "under_review": "em revisão",
                                 # V20.32: situacoes da Shopee
                                 "BANNED": "bloqueado", "SELLER_DELETE": "excluído", "SHOPEE_DELETE": "excluído pela Shopee"}
# V20.32: a "conta de estoque" e a chave do interruptor e da rodada: as casas do ML ('aracatuba', 'bauru') e 'shopee'
# (a Shopee de Araçatuba: linhas canal='shopee', conta='aracatuba'; Apollo e fila de Araçatuba, o mesmo estoque do ML).
ESTOQUE_CONTA_SHOPEE = "shopee"
ESTOQUE_CONTA_MAGALU = "magalu"  # V20.34: a Magalu de Araçatuba (linhas canal='magalu', conta='aracatuba')
# V20.41: o TikTok de Bauru (linhas canal='tiktok', conta='bauru'; Apollo e fila de Bauru). Só com a fonte "api" (os
# anúncios ficam com controle 'noromak'); com a extensão o controle é 'tiktok' e quem manda é a tela Estoque TikTok.
ESTOQUE_CONTA_TIKTOK = "tiktok"
# V20.34: contas de estoque que nao sao casa do ML (rodam numa thread na volta do worker; ML nao espera por elas)
ESTOQUE_CONTAS_FORA = (ESTOQUE_CONTA_SHOPEE, ESTOQUE_CONTA_MAGALU, ESTOQUE_CONTA_TIKTOK)


def _estoque_conta_valida(conta: Any) -> str:
    c = str(conta or "").strip().lower()
    return c if c in ESTOQUE_CONTAS_FORA else ml_casa_valida(conta)


def _estoque_alvo(conta: str) -> tuple[str, str, str]:
    """V20.32: (canal, conta da linha do anuncio, filial do Apollo/fila) da conta de estoque."""
    if conta == ESTOQUE_CONTA_SHOPEE:
        return "shopee", SHOPEE_ANUNCIO_CONTA, SHOPEE_ANUNCIO_CONTA
    if conta == ESTOQUE_CONTA_MAGALU:
        return "magalu", MAGALU_ANUNCIO_CONTA, MAGALU_ANUNCIO_CONTA
    if conta == ESTOQUE_CONTA_TIKTOK:  # V20.41
        return "tiktok", TIKTOK_CASA, TIKTOK_CASA
    return "ml", conta, conta


def _anuncio_estoque_linha(canal: str, conta: str, anuncio_id: str) -> dict[str, Any] | None:
    """V20.26: linha do anuncio. Chamar SOB o DB_LOCK."""
    row = DB.execute("SELECT * FROM anuncio_canal_v2023 WHERE canal=? AND conta=? AND anuncio_id=?",
                     (canal, conta, anuncio_id)).fetchone()
    return dict(row) if row else None


def _anuncio_estoque_elegivel(row: dict[str, Any] | None) -> str:
    """V20.26: '' = o Noromak pode mexer no estoque deste anuncio; senao o motivo."""
    if row is None:
        return "Anúncio não encontrado."
    if str(row.get("removido_em") or ""):
        return "Anúncio removido da lista pelo Admin."
    if str(row.get("controle") or "") == "full" or str(row.get("logistica") or "") == "fulfillment":
        return "Anúncio Full: o estoque é do Mercado Livre."
    if str(row.get("controle") or "") != "noromak":
        return "O estoque deste anúncio não é controlado pelo Noromak."
    # revisar-antes-de-subir (V20.41): SKU do TikTok cortado no limite (V20.08) sem vínculo à mão nunca recebe estoque —
    # o fim pode ter perdido uma peça inteira, mesmo que o trecho exista como código no Apollo.
    vinc: Any = True
    if str(row.get("canal") or "") == "tiktok" and len(str(row.get("sku_anuncio") or "")) >= TIKTOK_SKU_LIMITE:
        with DB_LOCK:  # reentrante: há quem chame já sob a trava
            vinc = DB.execute("SELECT 1 FROM tiktok_vinculo_v1964 WHERE sku_id=?",
                              (str(row.get("anuncio_id") or ""),)).fetchone()
    if vinc is None:
        return ("SKU do TikTok cortado em 50 caracteres: o kit pode ter perdido uma peça. Faça o vínculo à mão na tela "
                "Estoque TikTok antes de controlar o estoque.")
    return ""


def _anuncio_estoque_registrar(canal: str, conta: str, anuncio_id: str, modo: str, de: Any, para: Any,
                               motivo: str, resultado: str, detalhe: str, ator: str) -> None:
    """V20.26: uma linha no registro; guarda so os ultimos ANUNCIO_ESTOQUE_LOG_MAX."""
    def _int(v: Any) -> int | None:
        try:
            return None if v is None or isinstance(v, bool) else int(v)
        except (TypeError, ValueError):
            return None

    with DB_LOCK:
        cur = DB.execute(
            "INSERT INTO anuncio_estoque_log_v2026(criado_em,canal,conta,anuncio_id,modo,de,para,motivo,resultado,detalhe,ator) "
            "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (now_iso(), str(canal), str(conta), str(anuncio_id), str(modo or ""), _int(de), _int(para),
             str(motivo or "")[:300], str(resultado or ""), str(detalhe or "")[:1000], str(ator or "")))
        corte = int(cur.lastrowid or 0) - ANUNCIO_ESTOQUE_LOG_MAX
        if corte > 0:
            DB.execute("DELETE FROM anuncio_estoque_log_v2026 WHERE id<=?", (corte,))
        DB.commit()


def anuncio_estoque_log(canal: str, conta: str, anuncio_id: str = "", limite: int = 50) -> list[dict[str, Any]]:
    """V20.26: ultimos registros (mais novo primeiro). Sem `anuncio_id` = a conta inteira."""
    limite = max(1, min(500, int(limite or 50)))
    with DB_LOCK:
        if anuncio_id:
            rows = DB.execute("SELECT * FROM anuncio_estoque_log_v2026 WHERE canal=? AND conta=? AND anuncio_id=? "
                              "ORDER BY id DESC LIMIT ?", (canal, conta, anuncio_id, limite)).fetchall()
        else:
            rows = DB.execute("SELECT * FROM anuncio_estoque_log_v2026 WHERE canal=? AND conta=? ORDER BY id DESC LIMIT ?",
                              (canal, conta, limite)).fetchall()
    return [dict(r) for r in rows]


def anuncio_estoque_modo_definir(canal: str, conta: str, anuncio_id: str, modo: str, ator: str) -> dict[str, Any]:
    """V20.26: Manual / Automatico de um anuncio. So `noromak` e nao-Full."""
    modo = str(modo or "").strip().lower()
    if modo not in ANUNCIO_ESTOQUE_MODOS:
        raise ValueError("Modo de estoque inválido (manual ou automatico).")
    with DB_LOCK:
        row = _anuncio_estoque_linha(canal, conta, anuncio_id)
        motivo = _anuncio_estoque_elegivel(row)
        if motivo:
            raise ValueError(motivo)
        # V20.28: SKU com cara de dois codigos juntos so vai ao Automatico depois de o Admin escolher Peca ou Kit
        if modo == "automatico" and anuncio_tipo_a_confirmar(row.get("ficha_codigo")):
            raise ValueError("O SKU deste anúncio parece dois códigos juntos (kit?). Na ficha, escolha “Este produto "
                             "é: Peça” ou “Kit” antes de ligar o Automático.")
        antes = str(row.get("estoque_modo") or "manual")
        DB.execute("UPDATE anuncio_canal_v2023 SET estoque_modo=? WHERE canal=? AND conta=? AND anuncio_id=?",
                   (modo, canal, conta, anuncio_id))
        DB.commit()
    if antes != modo:
        _anuncio_estoque_registrar(canal, conta, anuncio_id, modo, None, None, f"modo {antes} -> {modo}",
                                   "ignorado", "troca de modo pelo Admin", ator)
    audit(ator, "anuncios.estoque_modo", f"{canal}|{conta}|{anuncio_id}|{antes}->{modo}")
    return {"ok": True, "anuncio_id": anuncio_id, "modo": modo}


def anuncio_estoque_config(conta: str) -> dict[str, Any]:
    """V20.26: interruptor do Automatico da conta. Sem linha = Simulacao (nada e enviado)."""
    conta = _estoque_conta_valida(conta)
    with DB_LOCK:
        row = DB.execute("SELECT * FROM anuncio_estoque_config_v2026 WHERE conta=?", (conta,)).fetchone()
    # V20.26 (revisao): + a chave "o Disponivel do Apollo ja tira o atendimento aberto" (padrao desligada)
    desconta = {"apollo_desconta_atendimento": bool(int(row["apollo_desconta_atendimento"] or 0)) if row is not None else False,
                "desconta_em": str(row["desconta_em"] or "") if row is not None else "",
                "desconta_por": str(row["desconta_por"] or "") if row is not None else ""}
    if row is None or str(row["modo"] or "") not in ANUNCIO_ESTOQUE_CONTA_MODOS:
        return {"conta": conta, "modo": "simulacao", "atualizado_em": "", "atualizado_por": "", **desconta}
    return {"conta": conta, "modo": str(row["modo"]), "atualizado_em": str(row["atualizado_em"] or ""),
            "atualizado_por": str(row["atualizado_por"] or ""), **desconta}


def anuncio_estoque_desconta_definir(conta: str, valor: Any, ator: str) -> dict[str, Any]:
    """V20.26 (revisao): liga = desconta so os pendentes SEM atendimento no Apollo (o Disponivel ja tiraria o resto).
    Ligar so depois de o Guilherme confirmar. Perfil Admin (nao OWNER); auditado e registrado."""
    conta = _estoque_conta_valida(conta)
    if not isinstance(valor, bool) and valor not in (0, 1):
        raise ValueError("Informe ligado (true) ou desligado (false).")
    novo = 1 if bool(valor) else 0
    antes = anuncio_estoque_config(conta)["apollo_desconta_atendimento"]
    with DB_LOCK:
        DB.execute("INSERT INTO anuncio_estoque_config_v2026(conta,modo,apollo_desconta_atendimento,desconta_em,desconta_por) "
                   "VALUES(?,'simulacao',?,?,?) ON CONFLICT(conta) DO UPDATE SET "
                   "apollo_desconta_atendimento=excluded.apollo_desconta_atendimento, desconta_em=excluded.desconta_em, "
                   "desconta_por=excluded.desconta_por", (conta, novo, now_iso(), str(ator or "")))
        DB.commit()
    if bool(antes) != bool(novo):
        _anuncio_estoque_registrar(_estoque_alvo(conta)[0], _estoque_alvo(conta)[1], "", "automatico", None, None,
                                   "desconto do pendente: " + ("só sem atendimento no Apollo" if novo else "todo o pendente"),
                                   "ignorado", "chave mudada pelo Admin", ator)
    audit(ator, "anuncios.estoque_desconta_atendimento", f"{conta}|{int(bool(antes))}->{novo}")
    return anuncio_estoque_config(conta)


def anuncio_estoque_config_definir(conta: str, modo: str, ator: str) -> dict[str, Any]:
    """V20.26: a rota exige o OWNER para ligar o Automatico."""
    conta = _estoque_conta_valida(conta)
    modo = str(modo or "").strip().lower()
    if modo not in ANUNCIO_ESTOQUE_CONTA_MODOS:
        raise ValueError("Modo inválido (simulacao, lote ou automatico).")
    antes = anuncio_estoque_config(conta)["modo"]
    with DB_LOCK:
        DB.execute("INSERT INTO anuncio_estoque_config_v2026(conta,modo,atualizado_em,atualizado_por) VALUES(?,?,?,?) "
                   "ON CONFLICT(conta) DO UPDATE SET modo=excluded.modo, atualizado_em=excluded.atualizado_em, "
                   "atualizado_por=excluded.atualizado_por", (conta, modo, now_iso(), str(ator or "")))
        DB.commit()
    audit(ator, "anuncios.estoque_config", f"{conta}|{antes}->{modo}")
    return anuncio_estoque_config(conta)


# V20.26: gravar estoque no ML. Uma gravacao por anuncio por vez (trava por anuncio); ML fora do DB_LOCK.
ANUNCIO_ESTOQUE_RELEITURA_ESPERAS: tuple[float, ...] = (1.0, 2.0, 3.0)  # o ML demora uns segundos a mostrar
ANUNCIO_ESTOQUE_TRAVA_S = 60
_ANUNCIO_ESTOQUE_TRAVAS: dict[tuple[str, str], threading.Lock] = {}
_ANUNCIO_ESTOQUE_TRAVAS_LOCK = threading.Lock()
ANUNCIO_ESTOQUE_DEPOSITOS = ("seller_warehouse", "store")


def _anuncio_estoque_trava(conta: str, mlb: str) -> threading.Lock:
    with _ANUNCIO_ESTOQUE_TRAVAS_LOCK:
        return _ANUNCIO_ESTOQUE_TRAVAS.setdefault((conta, mlb), threading.Lock())


def _anuncio_estoque_qtd(valor: Any) -> int:
    """V20.26: inteiro 0..ANUNCIO_ESTOQUE_MAX. Texto, fracao, negativo ou vazio = ValueError (nunca vira 0)."""
    if isinstance(valor, bool) or valor is None or (isinstance(valor, str) and not valor.strip()):
        raise ValueError("Informe a quantidade.")
    try:
        f = float(str(valor).strip().replace(",", ".")) if isinstance(valor, str) else float(valor)
    except (TypeError, ValueError):
        raise ValueError("Quantidade inválida.")
    if f != f or f < 0 or f > ANUNCIO_ESTOQUE_MAX or int(f) != f:
        raise ValueError(f"Quantidade inválida (inteiro de 0 a {ANUNCIO_ESTOQUE_MAX}).")
    return int(f)


def _ml_estoque_http(method: str, path: str, payload: dict[str, Any] | None = None,
                     headers: dict[str, str] | None = None) -> tuple[Any, dict[str, str]]:
    """V20.26: chamada JSON ao ML que devolve tambem os cabecalhos (o estoque do user-product usa `x-version`).
    Token da casa atual (chamar dentro de ml_na_casa); 401 renova uma vez. Erro = RuntimeError com .ml_status."""
    url = ML_API_BASE + path

    def chamar(token: str) -> tuple[Any, dict[str, str]]:
        body = json_dumps(payload).encode("utf-8") if payload is not None else None
        h = {"Accept": "application/json", "Authorization": "Bearer " + token,
             "User-Agent": f"NoromakExpedicao/{APP_VERSION}"}
        if body is not None:
            h["Content-Type"] = "application/json"
        h.update(headers or {})
        req = urllib.request.Request(url, data=body, headers=h, method=method.upper())
        with urllib.request.urlopen(req, timeout=ML_HTTP_TIMEOUT) as resp:
            texto = resp.read().decode("utf-8", "replace").strip()
            cab = {str(k).lower(): str(v) for k, v in resp.headers.items()}
            return (json.loads(texto) if texto else {}), cab

    token, _ = ml_access_token()
    try:
        try:
            return chamar(token)
        except urllib.error.HTTPError as exc:
            if exc.code != 401:
                raise
            token, _ = ml_access_token(force_refresh=True)
            return chamar(token)
    except urllib.error.HTTPError as exc:
        try:
            detalhe = exc.read().decode("utf-8", "replace")[:4000]
        except Exception:
            detalhe = ""
        erro = RuntimeError(f"Mercado Livre respondeu HTTP {exc.code}: {detalhe[:400]}")
        erro.ml_status = exc.code  # type: ignore[attr-defined]
        erro.ml_corpo = detalhe  # type: ignore[attr-defined]
        raise erro from exc


def _ml_estoque_ler_item(mlb: str) -> dict[str, Any]:
    """V20.26: o anuncio como o ML mostra agora (dentro de ml_na_casa). available_quantity sem numero = None."""
    d = ml_api_get(f"/items/{mlb}?attributes=id,available_quantity,user_product_id,shipping,status,variations")
    d = d if isinstance(d, dict) else {}
    q = d.get("available_quantity")
    qtd = int(q) if isinstance(q, (int, float)) and not isinstance(q, bool) else None
    return {"available_quantity": qtd, "user_product_id": str(d.get("user_product_id") or "").strip(),
            "logistic_type": str((d.get("shipping") or {}).get("logistic_type") or "") if isinstance(d.get("shipping"), dict) else "",
            "status": str(d.get("status") or ""),
            # V20.26 (revisao): com variacoes o estoque e por variacao (o PUT do anuncio nao vale)
            "variacoes": bool(isinstance(d.get("variations"), list) and d.get("variations"))}


def _ml_estoque_reler(mlb: str, qtd: int) -> int | None:
    """V20.26: rele ate o ML mostrar `qtd` (ou acabarem as esperas). Devolve o ultimo numero lido (None = sem leitura)."""
    ultimo: int | None = None
    for espera in ANUNCIO_ESTOQUE_RELEITURA_ESPERAS or (0,):
        if espera:
            time.sleep(espera)
        try:
            ultimo = _ml_estoque_ler_item(mlb)["available_quantity"]
        except Exception:
            continue
        if ultimo == qtd:
            break
    return ultimo


def _ml_estoque_up_ler(up: str) -> tuple[list[dict[str, Any]], str]:
    """V20.26: locais do estoque do user-product e a versao (cabecalho x-version) para o PUT."""
    corpo, cab = _ml_estoque_http("GET", f"/user-products/{up}/stock")
    _anuncio_amostra("estoque_up_ler", {"corpo": corpo, "x-version": (cab or {}).get("x-version")})
    locais = [l for l in ((corpo or {}).get("locations") or []) if isinstance(l, dict)] if isinstance(corpo, dict) else []
    return locais, str((cab or {}).get("x-version") or "")


def _ml_estoque_up_gravar(up: str, qtd: int, versao: str) -> None:
    """V20.26: PUT do local selling_address com o x-version lido; 409 (versao mudou) = rele e tenta uma vez."""
    for tentativa in (1, 2):
        try:
            corpo, _ = _ml_estoque_http("PUT", f"/user-products/{up}/stock/type/selling_address", {"quantity": qtd},
                                        headers={"x-version": versao} if versao else None)
            _anuncio_amostra("estoque_put_up", corpo)
            return
        except RuntimeError as exc:
            if getattr(exc, "ml_status", None) == 409 and tentativa == 1:
                _, versao = _ml_estoque_up_ler(up)
                continue
            raise


# V20.27: estoque multiorigem do ML (caso real 05/11 20:28, conta de Aracatuba): o user-product volta SEM
# selling_address e com UM local seller_warehouse (store_id + network_node_id). Grava-se nesse deposito pelo
# PUT /user-products/{id}/stock/type/seller_warehouse com o x-version do GET. meli_facility (Full) nao conta.
def _ml_estoque_depositos(locais: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [l for l in (locais or []) if str(l.get("type") or "") in ANUNCIO_ESTOQUE_DEPOSITOS]


def _ml_estoque_depositos_texto(depositos: list[dict[str, Any]]) -> str:
    partes = []
    for d in depositos:
        nome = str(d.get("store_id") or d.get("network_node_id") or d.get("type") or "?")
        st = str(d.get("status") or "")
        partes.append(f"depósito {nome}: {d.get('quantity')} un." + (f" ({st})" if st and st != "active" else ""))
    return "; ".join(partes)


def _ml_estoque_deposito_unico(locais: list[dict[str, Any]]) -> tuple[dict[str, Any] | None, str]:
    """V20.27: o deposito do vendedor onde gravar, ou (None, motivo). Nunca adivinha entre dois."""
    deps = _ml_estoque_depositos(locais)
    tipos = {str(l.get("type") or "") for l in (locais or [])}
    if "selling_address" in tipos and "seller_warehouse" in tipos:
        return None, ("anúncio com endereço de venda e depósito do vendedor juntos (" + _ml_estoque_depositos_texto(deps)
                      + "): ajuste no ML")
    if not deps:
        return None, "anúncio com depósito do vendedor: ajuste no ML"
    if (len(deps) != 1 or str(deps[0].get("type") or "") != "seller_warehouse"
            or str(deps[0].get("status") or "") != "active"
            or not str(deps[0].get("store_id") or "").strip() or not str(deps[0].get("network_node_id") or "").strip()):
        return None, f"anúncio com depósito do vendedor ({_ml_estoque_depositos_texto(deps)}): ajuste no ML"
    return deps[0], ""


def _ml_estoque_wh_gravar(up: str, qtd: int, versao: str, deposito: dict[str, Any]) -> None:
    """V20.27: PUT no deposito seller_warehouse; 409 = rele (mesmo deposito, versao nova) e tenta uma vez."""
    for tentativa in (1, 2):
        corpo_put = {"locations": [{"store_id": str(deposito.get("store_id")),
                                    "network_node_id": str(deposito.get("network_node_id")), "quantity": int(qtd)}]}
        try:
            corpo, _ = _ml_estoque_http("PUT", f"/user-products/{up}/stock/type/seller_warehouse", corpo_put,
                                        headers={"x-version": versao} if versao else None)
            _anuncio_amostra("estoque_put_seller_warehouse", corpo)
            return
        except RuntimeError as exc:
            if getattr(exc, "ml_status", None) == 409 and tentativa == 1:
                locais, versao = _ml_estoque_up_ler(up)
                novo, motivo = _ml_estoque_deposito_unico(locais)
                if novo is None or str(novo.get("store_id")) != str(deposito.get("store_id")):
                    raise RuntimeError(motivo or "o depósito do vendedor mudou no ML; nada enviado") from exc
                deposito = novo
                continue
            raise


def _ml_estoque_wh_reler(up: str, store_id: str, qtd: int) -> int | None:
    """V20.27: rele o estoque do user-product ate o deposito mostrar `qtd`. None = sem leitura."""
    ultimo: int | None = None
    for espera in ANUNCIO_ESTOQUE_RELEITURA_ESPERAS or (0,):
        if espera:
            time.sleep(espera)
        try:
            locais, _ = _ml_estoque_up_ler(up)
        except Exception:
            continue
        dep = next((l for l in locais if str(l.get("type") or "") == "seller_warehouse"
                    and str(l.get("store_id") or "") == str(store_id)), None)
        q = (dep or {}).get("quantity")
        ultimo = int(q) if isinstance(q, (int, float)) and not isinstance(q, bool) else None
        if ultimo == qtd:
            break
    return ultimo


def ml_estoque_gravar(conta: str, mlb: str, quantidade: Any, *, ator: str, modo: str, motivo: str,
                      conferir: Any = None) -> dict[str, Any]:
    """V20.26: a UNICA funcao que grava estoque no ML. `{ok, antes, depois, metodo, erro, resultado}`.
    Recusa (ValueError) anuncio que nao e `noromak`, Full ou removido, e quantidade invalida, sem chamar o ML.
    `conferir()` (opcional) roda DENTRO da trava do anuncio, antes de qualquer chamada: devolve
    (quantidade, '') para seguir ou (None, motivo) para desistir (o Automatico rele o modo e a fila ali).
    So e `ok` quando a releitura mostra a quantidade enviada (o PUT pode responder 200 sem mudar)."""
    conta = ml_casa_valida(conta)
    mlb = str(mlb or "").strip().upper()
    qtd = _anuncio_estoque_qtd(quantidade)
    with DB_LOCK:
        motivo_recusa = _anuncio_estoque_elegivel(_anuncio_estoque_linha("ml", conta, mlb))
    if motivo_recusa:
        raise ValueError(motivo_recusa)
    trava = _anuncio_estoque_trava(conta, mlb)
    if not trava.acquire(timeout=ANUNCIO_ESTOQUE_TRAVA_S):
        return {"ok": False, "resultado": "erro", "antes": None, "depois": None, "metodo": "",
                "erro": "Outro envio de estoque deste anúncio ainda está em andamento."}
    try:
        if conferir is not None:
            novo, por_que = conferir()
            if novo is None:
                _anuncio_estoque_registrar("ml", conta, mlb, modo, None, qtd, motivo, "ignorado", por_que, ator)
                return {"ok": False, "resultado": "ignorado", "antes": None, "depois": None, "metodo": "",
                        "erro": por_que}
            qtd = _anuncio_estoque_qtd(novo)
        with DB_LOCK:  # o Admin pode ter passado a Alephee/removido enquanto esperava a trava
            motivo_recusa = _anuncio_estoque_elegivel(_anuncio_estoque_linha("ml", conta, mlb))
        if motivo_recusa:
            _anuncio_estoque_registrar("ml", conta, mlb, modo, None, qtd, motivo, "ignorado", motivo_recusa, ator)
            return {"ok": False, "resultado": "ignorado", "antes": None, "depois": None, "metodo": "",
                    "erro": motivo_recusa}
        with ml_na_casa(conta):
            res = _ml_estoque_gravar_na_casa(mlb, qtd)
        voltou_manual = False
        ok = bool(res["ok"])
        resultado = "ok" if ok else ("ignorado" if res.get("ignorado") else "erro")
        detalhe = res["metodo"] + (": " + res["erro"] if res.get("erro") else "")
        _anuncio_estoque_registrar("ml", conta, mlb, modo, res["antes"], qtd, motivo, resultado, detalhe, ator)
        with DB_LOCK:
            agora = now_iso()
            if res.get("depois") is not None:
                DB.execute("UPDATE anuncio_canal_v2023 SET estoque=? WHERE canal='ml' AND conta=? AND anuncio_id=?",
                           (int(res["depois"]), conta, mlb))
            if ok:
                DB.execute("UPDATE anuncio_canal_v2023 SET estoque_enviado=?, estoque_enviado_em=? "
                           "WHERE canal='ml' AND conta=? AND anuncio_id=?", (qtd, agora, conta, mlb))
            if res.get("ignorado") == "full":
                antes_modo = (_anuncio_estoque_linha("ml", conta, mlb) or {}).get("estoque_modo")
                # V20.26 (revisao): virou Full = volta a Manual (o Automatico nunca religa sozinho)
                DB.execute("UPDATE anuncio_canal_v2023 SET logistica='fulfillment', estoque_modo='manual' "
                           "WHERE canal='ml' AND conta=? AND anuncio_id=?", (conta, mlb))
                voltou_manual = antes_modo == "automatico"
            lido = res.get("lido") or {}
            if lido:
                DB.execute("UPDATE anuncio_canal_v2023 SET variacoes=?, status=COALESCE(NULLIF(?,''),status) "
                           "WHERE canal='ml' AND conta=? AND anuncio_id=?",
                           (1 if lido.get("variacoes") else 0, str(lido.get("status") or ""), conta, mlb))
            DB.commit()
        if voltou_manual:
            _anuncio_estoque_registrar("ml", conta, mlb, "manual", None, None, "modo automatico -> manual", "ignorado",
                                       "o ML mostra o anúncio como Full", "sistema")
        if ok and modo == "manual":
            audit(ator, "anuncios.estoque_manual", f"{conta}|{mlb}|{res['antes']}->{qtd}")
        return {"ok": ok, "resultado": resultado, "antes": res["antes"], "depois": res.get("depois"),
                "metodo": res["metodo"], "erro": res.get("erro") or "", "quantidade": qtd,
                "ignorado": str(res.get("ignorado") or "")}
    finally:
        trava.release()


def _shopee_estoque_ler(item_id: str) -> dict[str, Any]:
    """V20.32: o item na Shopee (get_item_base_info): {existe, sku, estoque, locais, variacoes, status}.
    Revisao: deposito sem numero = estoque None (nunca 0); sem `seller_stock` = None (o "disponivel" ja tira a
    reserva e nao e o numero gravado)."""
    dados = _shopee_chamar("GET", "/api/v2/product/get_item_base_info", {"item_id_list": str(item_id)})
    _anuncio_amostra("shopee_estoque_ler", dados)
    lista = _shopee_resposta(dados).get("item_list") or []
    item = lista[0] if lista and isinstance(lista[0], dict) else {}
    info = item.get("stock_info_v2") if isinstance(item.get("stock_info_v2"), dict) else {}
    locais = [x for x in info.get("seller_stock") or [] if isinstance(x, dict)]
    estoque: int | None = None
    try:
        if locais and all(x.get("stock") is not None for x in locais):
            estoque = sum(int(x["stock"]) for x in locais)
    except (TypeError, ValueError):
        estoque = None
    return {"existe": bool(item), "sku": str(item.get("item_sku") or ""), "estoque": estoque,
            "locais": [str(x.get("location_id") or "") for x in locais],
            "variacoes": bool(item.get("has_model")), "status": str(item.get("item_status") or "")}


SHOPEE_STATUS_SEM_ESTOQUE = ("BANNED", "SELLER_DELETE", "SHOPEE_DELETE", "DELETED")


def _shopee_estoque_gravar_api(item_id: str, qtd: int, ficha_codigo: str = "") -> dict[str, Any]:
    """V20.32: le, grava (update_stock, absoluto) e rele; so e ok quando a Shopee mostra o numero.
    Revisao: so grava no item cujo SKU e o da ficha, com UM deposito (mandado pelo local lido) e ativo."""
    res: dict[str, Any] = {"ok": False, "antes": None, "depois": None, "metodo": "update_stock", "erro": "", "lido": {}}
    try:
        antes = _shopee_estoque_ler(item_id)
    except (ShopeeRecusou, ShopeeSemResposta) as exc:
        res["erro"] = f"não consegui ler o item na Shopee ({exc})"
        return res
    res["antes"] = antes["estoque"]
    res["lido"] = antes
    if not antes["existe"]:
        res["erro"] = "a Shopee não achou o item nesta loja"
        return res
    if ficha_codigo and normalize(antes["sku"]) != normalize(ficha_codigo):
        res["erro"] = f"o item na Shopee tem o SKU {antes['sku'] or '(vazio)'}, não {ficha_codigo}: nada enviado"
        return res
    if antes["status"] in SHOPEE_STATUS_SEM_ESTOQUE:
        res.update(erro=f"item {antes['status']} na Shopee: nada enviado", ignorado="status")
        return res
    if antes["variacoes"]:
        res.update(erro="anúncio com variações: o estoque é por variação; ajuste na Shopee", ignorado="variacoes")
        return res
    if len(antes["locais"]) > 1:
        res["erro"] = ("o item tem mais de um depósito na Shopee (" + ", ".join(x or "sem id" for x in antes["locais"])
                       + "): ajuste na Shopee, o Noromak não escolhe o depósito")
        return res
    if antes["estoque"] is None:
        res["erro"] = "a Shopee não mostrou o estoque do item: nada enviado"
        return res
    local = antes["locais"][0] if antes["locais"] else ""
    estoque_item: dict[str, Any] = {"stock": qtd}
    if local:
        estoque_item = {"location_id": local, "stock": qtd}
    try:
        r = _shopee_chamar("POST", "/api/v2/product/update_stock",
                           payload={"item_id": int(item_id), "stock_list": [{"model_id": 0, "seller_stock": [estoque_item]}]})
        _anuncio_amostra("shopee_update_stock", r)
        falhas = _shopee_resposta(r).get("failure_list") or []
        if falhas:
            res["erro"] = "a Shopee recusou: " + "; ".join(str((f or {}).get("failed_reason") or f) for f in falhas)[:300]
            return res
    except ShopeeRecusou as exc:
        _anuncio_amostra("shopee_update_stock [erro]", {"erro": str(exc), "corpo": exc.corpo})
        res["erro"] = f"a Shopee recusou: {exc}"
        if not _shopee_talvez_fez(exc):
            return res
    except ShopeeSemResposta as exc:
        res["erro"] = f"sem resposta da Shopee ({exc}); relido abaixo"
    for espera in ANUNCIO_ESTOQUE_RELEITURA_ESPERAS:
        time.sleep(espera)
        try:
            depois = _shopee_estoque_ler(item_id)["estoque"]
        except (ShopeeRecusou, ShopeeSemResposta):
            continue
        if depois is None:
            continue
        res["depois"] = depois
        if depois == qtd:
            res.update(ok=True, erro="")
            return res
    if not res["erro"]:
        res["erro"] = f"a Shopee aceitou mas mostra {res['depois']} (enviado {qtd})"
    return res


def shopee_estoque_gravar(conta: str, item_id: str, quantidade: Any, *, ator: str, modo: str, motivo: str,
                          conferir: Any = None) -> dict[str, Any]:
    """V20.32: a UNICA funcao que grava estoque na Shopee (mesmo contrato do ml_estoque_gravar). So anuncio
    `noromak` da Shopee de Araçatuba; `conferir()` roda dentro da trava do anuncio."""
    return _estoque_gravar_fora(ESTOQUE_CONTA_SHOPEE, item_id, quantidade, _shopee_estoque_gravar_api, ator=ator,
                                modo=modo, motivo=motivo, conferir=conferir)


def magalu_estoque_gravar(conta: str, item_id: str, quantidade: Any, *, ator: str, modo: str, motivo: str,
                          conferir: Any = None) -> dict[str, Any]:
    """V20.34: a UNICA funcao que grava estoque na Magalu (mesmo contrato). `item_id` = o SKU na Magalu."""
    return _estoque_gravar_fora(ESTOQUE_CONTA_MAGALU, item_id, quantidade, _magalu_estoque_gravar_api, ator=ator,
                                modo=modo, motivo=motivo, conferir=conferir)


def tiktok_estoque_gravar(conta: str, item_id: str, quantidade: Any, *, ator: str, modo: str, motivo: str,
                          conferir: Any = None) -> dict[str, Any]:
    """V20.41: a ÚNICA função que grava estoque no TikTok pela plataforma de anúncios (mesmo contrato). `item_id` = o id
    da variação (sku_id). Só com a fonte "api"."""
    return _estoque_gravar_fora(ESTOQUE_CONTA_TIKTOK, item_id, quantidade, _tiktok_estoque_gravar_api, ator=ator,
                                modo=modo, motivo=motivo, conferir=conferir)


TIKTOK_ESTOQUE_RELEITURA_ESPERAS = (2, 3, 5)
TIKTOK_STATUS_SEM_ESTOQUE = {"DELETED", "SELLER_DELETED", "PLATFORM_DEACTIVATED_DELETED", "FREEZE", "PLATFORM_DEACTIVATED"}


def _tiktok_estoque_ler(sku_id: str) -> dict[str, Any]:
    """V20.41: a variação lida agora no TikTok (GET do produto): SKU, situação, depósitos e quantidade. Só lê."""
    with DB_LOCK:
        row = DB.execute("SELECT product_id FROM tiktok_sku_v1964 WHERE sku_id=?", (str(sku_id),)).fetchone()
        if row is None:
            row = DB.execute("SELECT user_product_id AS product_id FROM anuncio_canal_v2023 WHERE canal='tiktok' "
                             "AND anuncio_id=?", (str(sku_id),)).fetchone()
    product_id = str((row["product_id"] if row else "") or "")
    if not product_id:
        raise ValueError("o Noromak não sabe o produto desta variação (atualize os anúncios do TikTok)")
    resp = tiktok_api("GET", f"/product/202309/products/{product_id}")
    dados = resp.get("data") if isinstance(resp.get("data"), dict) else {}
    saida: dict[str, Any] = {"existe": False, "status": str(dados.get("status") or ""), "sku": "", "locais": [],
                             "estoque": None, "product_id": product_id, "variacoes": False}
    for sk in dados.get("skus") or []:
        if isinstance(sk, dict) and str(sk.get("id") or "") == str(sku_id):
            inv = [i for i in (sk.get("inventory") or []) if isinstance(i, dict)]
            saida.update(existe=True, sku=str(sk.get("seller_sku") or ""),
                         locais=[str(i.get("warehouse_id") or "") for i in inv],
                         estoque=_tiktok_quantidade(inv[0].get("quantity")) if len(inv) == 1 else None)
    return saida


def _tiktok_estoque_gravar_api(sku_id: str, qtd: int, ficha_codigo: str = "") -> dict[str, Any]:
    """V20.41: lê, grava (inventory/update, número absoluto) e relê; só é ok quando o TikTok mostra o número.
    Só a variação cujo SKU é o da ficha (ou com vínculo à mão), com UM depósito e produto ativo."""
    res: dict[str, Any] = {"ok": False, "antes": None, "depois": None, "metodo": "inventory/update", "erro": "", "lido": {}}
    # revisar-antes-de-subir (V20.41): sob o TIKTOK_ESTOQUE_LOCK (a troca de fonte usa a mesma): a extensão nunca abre uma
    # rodada (grava por diferença) no meio de um envio absoluto pela API.
    if not TIKTOK_ESTOQUE_LOCK.acquire(timeout=30):
        res["erro"] = "outro envio de estoque ao TikTok está em andamento; tenta na próxima volta"
        return res
    try:
        return _tiktok_estoque_gravar_api_na_vez(sku_id, qtd, ficha_codigo, res)
    finally:
        TIKTOK_ESTOQUE_LOCK.release()


def _tiktok_estoque_gravar_api_na_vez(sku_id: str, qtd: int, ficha_codigo: str, res: dict[str, Any]) -> dict[str, Any]:
    if tiktok_fonte() != "api":
        res.update(erro="a fonte do TikTok é a extensão do Seller Center: nada enviado pela API", ignorado="fonte")
        return res
    try:
        antes = _tiktok_estoque_ler(sku_id)
    except Exception as exc:
        res["erro"] = f"não consegui ler a variação no TikTok ({str(exc)[:200]})"
        return res
    res["antes"] = antes["estoque"]
    if not antes["existe"]:
        res["erro"] = "o TikTok não achou esta variação na loja"
        return res
    with DB_LOCK:
        vinc = DB.execute("SELECT codigos FROM tiktok_vinculo_v1964 WHERE sku_id=?", (str(sku_id),)).fetchone()
    if ficha_codigo and not vinc and normalize(antes["sku"]) != normalize(ficha_codigo):
        res["erro"] = f"a variação no TikTok tem o SKU {antes['sku'] or '(vazio)'}, não {ficha_codigo}: nada enviado"
        return res
    if antes["status"] in TIKTOK_STATUS_SEM_ESTOQUE:
        res.update(erro=f"produto {antes['status']} no TikTok: nada enviado", ignorado="status")
        return res
    if len(antes["locais"]) != 1 or not antes["locais"][0]:
        res["erro"] = ("a variação tem " + (f"{len(antes['locais'])} depósitos" if antes["locais"] else "nenhum depósito")
                       + " no TikTok: ajuste no Seller Center, o Noromak não escolhe o depósito")
        return res
    if antes["estoque"] is None:
        res["erro"] = "o TikTok não mostrou a quantidade da variação: nada enviado"
        return res
    corpo = {"skus": [{"id": str(sku_id), "inventory": [{"warehouse_id": antes["locais"][0], "quantity": int(qtd)}]}]}
    try:
        r = tiktok_api("POST", f"/product/202309/products/{antes['product_id']}/inventory/update", body=corpo)
        erros = ((r.get("data") or {}).get("errors") or []) if isinstance(r.get("data"), dict) else []
        if erros:
            res["erro"] = "o TikTok recusou: " + "; ".join(f"{(e or {}).get('code')} {(e or {}).get('message') or ''}"
                                                       for e in erros if isinstance(e, dict))[:300]
            return res
    except Exception as exc:
        res["erro"] = f"o TikTok não confirmou o envio ({str(exc)[:200]}); relido abaixo"
    for espera in TIKTOK_ESTOQUE_RELEITURA_ESPERAS:
        time.sleep(espera)
        try:
            depois = _tiktok_estoque_ler(sku_id)["estoque"]
        except Exception:
            continue
        if depois is None:
            continue
        res["depois"] = depois
        if depois == qtd:
            res.update(ok=True, erro="")
            with DB_LOCK:
                DB.execute("UPDATE tiktok_sku_v1964 SET qtd_tiktok=? WHERE sku_id=?", (qtd, str(sku_id)))
                DB.commit()
            return res
    if not res["erro"]:
        res["erro"] = f"o TikTok aceitou mas mostra {res['depois']} (enviado {qtd})"
    return res


def _estoque_gravador(canal: str) -> Any:
    """V20.34: quem grava o estoque de cada canal."""
    return {"shopee": shopee_estoque_gravar, "magalu": magalu_estoque_gravar,
            "tiktok": tiktok_estoque_gravar}.get(canal, ml_estoque_gravar)  # V20.41


def _estoque_gravar_fora(conta_est: str, item_id: str, quantidade: Any, api: Any, *, ator: str, modo: str, motivo: str,
                         conferir: Any = None) -> dict[str, Any]:
    """V20.32/V20.34: gravar estoque num marketplace que nao e o ML (Shopee, Magalu): elegibilidade, trava do anuncio,
    `conferir()` dentro da trava, `api(item_id, qtd, ficha)` (le, grava, rele) e o registro."""
    canal, conta_linha, _filial = _estoque_alvo(conta_est)
    item_id = str(item_id or "").strip()
    qtd = _anuncio_estoque_qtd(quantidade)
    with DB_LOCK:
        recusa = _anuncio_estoque_elegivel(_anuncio_estoque_linha(canal, conta_linha, item_id))
    if recusa:
        raise ValueError(recusa)
    trava = _anuncio_estoque_trava(conta_est, item_id)
    if not trava.acquire(timeout=ANUNCIO_ESTOQUE_TRAVA_S):
        return {"ok": False, "resultado": "erro", "antes": None, "depois": None, "metodo": "",
                "erro": "Outro envio de estoque deste anúncio ainda está em andamento."}
    try:
        if conferir is not None:
            novo, por_que = conferir()
            if novo is None:
                _anuncio_estoque_registrar(canal, conta_linha, item_id, modo, None, qtd, motivo, "ignorado", por_que, ator)
                return {"ok": False, "resultado": "ignorado", "antes": None, "depois": None, "metodo": "", "erro": por_que}
            qtd = _anuncio_estoque_qtd(novo)
        with DB_LOCK:
            recusa = _anuncio_estoque_elegivel(_anuncio_estoque_linha(canal, conta_linha, item_id))
        if recusa:
            _anuncio_estoque_registrar(canal, conta_linha, item_id, modo, None, qtd, motivo, "ignorado", recusa, ator)
            return {"ok": False, "resultado": "ignorado", "antes": None, "depois": None, "metodo": "", "erro": recusa}
        with DB_LOCK:
            ficha_linha = str((_anuncio_estoque_linha(canal, conta_linha, item_id) or {}).get("ficha_codigo") or "")
        res = api(item_id, qtd, ficha_linha)
        ok = bool(res["ok"])
        resultado = "ok" if ok else ("ignorado" if res.get("ignorado") else "erro")
        detalhe = res["metodo"] + (": " + res["erro"] if res.get("erro") else "")
        _anuncio_estoque_registrar(canal, conta_linha, item_id, modo, res["antes"], qtd, motivo, resultado, detalhe, ator)
        with DB_LOCK:
            if res.get("depois") is not None:
                DB.execute("UPDATE anuncio_canal_v2023 SET estoque=? WHERE canal=? AND conta=? AND anuncio_id=?",
                           (int(res["depois"]), canal, conta_linha, item_id))
            if ok:
                DB.execute("UPDATE anuncio_canal_v2023 SET estoque_enviado=?, estoque_enviado_em=? "
                           "WHERE canal=? AND conta=? AND anuncio_id=?", (qtd, now_iso(), canal, conta_linha, item_id))
            lido = res.get("lido") or {}
            if lido:
                DB.execute("UPDATE anuncio_canal_v2023 SET variacoes=?, status=COALESCE(NULLIF(?,''),status) "
                           "WHERE canal=? AND conta=? AND anuncio_id=?",
                           (1 if lido.get("variacoes") else 0, str(lido.get("status") or ""), canal, conta_linha, item_id))
            DB.commit()
        if ok and modo == "manual":
            audit(ator, "anuncios.estoque_manual", f"{canal}|{item_id}|{res['antes']}->{qtd}")
        return {"ok": ok, "resultado": resultado, "antes": res["antes"], "depois": res.get("depois"),
                "metodo": res["metodo"], "erro": res.get("erro") or "", "quantidade": qtd,
                "ignorado": str(res.get("ignorado") or "")}
    finally:
        trava.release()


def _ml_estoque_gravar_na_casa(mlb: str, qtd: int) -> dict[str, Any]:
    """V20.26: o caminho da gravacao (dentro de ml_na_casa e da trava do anuncio)."""
    saida: dict[str, Any] = {"ok": False, "antes": None, "depois": None, "metodo": "", "erro": ""}
    try:
        item = _ml_estoque_ler_item(mlb)
    except Exception as exc:
        saida["erro"] = f"o Mercado Livre não respondeu a leitura do anúncio ({str(exc)[:200]}); nada enviado"
        return saida
    saida["antes"] = item["available_quantity"]
    saida["lido"] = item  # V20.26 (revisao): status e variacoes lidos agora vao para a linha do anuncio
    if item["logistic_type"] == "fulfillment":
        saida.update(ignorado="full", erro="anúncio Full: o estoque é do Mercado Livre; nada enviado")
        return saida
    if item["status"] in ANUNCIO_ESTOQUE_STATUS_PARADO:
        saida.update(ignorado="status", erro=f"anúncio {ANUNCIO_ESTOQUE_STATUS_PARADO[item['status']]} no ML; nada enviado")
        return saida
    if item["variacoes"]:
        saida.update(ignorado="variacoes", erro="anúncio com variações: o estoque é por variação; ajuste no ML")
        return saida
    if item["available_quantity"] == qtd:
        saida.update(ok=True, depois=qtd, metodo="nenhum", erro="o ML já mostrava essa quantidade")
        return saida
    up = item["user_product_id"]
    locais: list[dict[str, Any]] | None = None
    versao = ""
    if up:
        try:
            locais, versao = _ml_estoque_up_ler(up)
        except Exception:
            locais = None  # sem leitura dos locais: tenta o PUT do anuncio e confere na releitura
    tipos = {str(l.get("type") or "") for l in (locais or [])}
    tem_selling = "selling_address" in tipos

    def _pelo_deposito() -> dict[str, Any]:
        # V20.27: estoque multiorigem: um deposito seller_warehouse ativo; mais de um (ou inativo) = recusa listando
        deposito, motivo = _ml_estoque_deposito_unico(locais or [])
        if deposito is None:
            saida["erro"] = motivo
            return saida
        store_id = str(deposito.get("store_id"))
        erro_put = ""
        try:
            _ml_estoque_wh_gravar(up, qtd, versao, deposito)
        except Exception as exc:  # pode ter mudado mesmo assim (5xx/timeout): a releitura decide
            erro_put = str(exc)[:300]
        no_deposito = _ml_estoque_wh_reler(up, store_id, qtd)
        try:
            no_anuncio = _ml_estoque_ler_item(mlb)["available_quantity"]
        except Exception:
            no_anuncio = None
        saida["depois"] = no_deposito
        saida["ok"] = no_deposito == qtd
        if not saida["ok"]:
            saida["erro"] = (f"o ML recusou o estoque do depósito {store_id} ({erro_put})" if erro_put else
                             f"o ML não mudou o estoque do depósito {store_id} (mostra {no_deposito})")
        elif no_anuncio is not None and no_anuncio != qtd:
            saida["erro"] = f"depósito {store_id} com {qtd}; o anúncio mostra {no_anuncio}"
        return saida

    def _pelo_up(depois_items: str = "") -> dict[str, Any]:
        nonlocal locais, versao
        saida["metodo"] = (saida["metodo"] + "+" if saida["metodo"] else "") + "user_product"
        if locais is None:
            try:
                locais, versao = _ml_estoque_up_ler(up)
            except Exception as exc:
                saida["erro"] = (depois_items + "; " if depois_items else "") + f"estoque do user-product não lido ({str(exc)[:200]})"
                return saida
        tipos_up = {str(l.get("type") or "") for l in locais}
        if "seller_warehouse" in tipos_up or "selling_address" not in tipos_up:
            return _pelo_deposito()
        try:
            _ml_estoque_up_gravar(up, qtd, versao)
        except Exception as exc:
            erro_put = str(exc)[:300]
            saida["depois"] = _ml_estoque_reler(mlb, qtd)
            saida["ok"] = saida["depois"] == qtd
            if not saida["ok"]:
                saida["erro"] = f"o ML recusou o estoque do user-product ({erro_put})"
            return saida
        saida["depois"] = _ml_estoque_reler(mlb, qtd)
        saida["ok"] = saida["depois"] == qtd
        if not saida["ok"]:
            saida["erro"] = f"o ML não mudou o estoque (mostra {saida['depois']})"
        return saida

    if tipos & set(ANUNCIO_ESTOQUE_DEPOSITOS):
        return _pelo_up()
    saida["metodo"] = "items"
    erro_put = ""
    try:
        resp = _ml_promo_http("PUT", f"/items/{mlb}", {"available_quantity": qtd})
        _anuncio_amostra("estoque_put_item", resp)
    except Exception as exc:  # pode ter mudado mesmo assim (5xx/timeout): a releitura decide
        erro_put = str(exc)[:300]
    saida["depois"] = _ml_estoque_reler(mlb, qtd)
    if saida["depois"] == qtd:
        saida["ok"] = True
        return saida
    # V20.26 (RF3): 200 sem mudar (conta com varios depositos) - tenta o caminho do user-product
    if up and (locais is None or tem_selling):
        return _pelo_up(f"PUT do anúncio sem efeito (mostra {saida['depois']})")
    saida["erro"] = (f"o ML recusou ({erro_put})" if erro_put else
                     f"o ML não mudou o estoque (mostra {saida['depois']})")
    return saida


# V20.26: calculo do Automatico. Apollo lido em rodizio (como o TikTok, V19.64) e guardado por (codigo, filial);
# o calculo so usa as leituras guardadas (nunca chama o Apollo). Desconhecido = None = nao envia.
ANUNCIO_APOLLO_POR_MINUTO = 3          # das 20/min do Apollo, divididas com Faturamento, Separacao e TikTok
ANUNCIO_APOLLO_VALIDADE_S = 6 * 3600   # leitura mais velha que isso nao vale (nao envia)
ANUNCIO_ESTOQUE_BAIXO = 3
_ANUNCIO_APOLLO_CHAMADAS: list[float] = []
_ANUNCIO_APOLLO_LOCK = threading.Lock()


def _anuncio_estoque_pecas(ficha_codigo: Any, catalogo: dict[str, dict[str, Any]],
                           conhecidos: Any) -> tuple[list[dict[str, Any]], str]:
    """V20.26: pecas que o anuncio consome [{codigo, chave, quantidade}] ou ([], motivo).
    Kit = Cadastro de Kits / KITn-X; "A/B" = uma de cada (regra da V19.48, `_separacao_partes`); peca = ela mesma.
    `codigo` = como vai ao Apollo (normalize); `chave` = _exp_norm_codigo, a chave da fila e do kit_da_para_montar."""
    cod = normalize(ficha_codigo)
    if not cod:
        return [], "anúncio sem produto (SKU)"
    info = _ficha_tipo_info(cod)
    confirmada = {cod} if info["confirmado"] and info["tipo"] == "peca" else None
    # V20.26 (revisao) / V20.28: a mesma regra do pendente (Peca confirmada = o codigo inteiro)
    partes, comp = _anuncio_sku_partes(cod, catalogo, conhecidos, confirmada)
    if comp and not comp.get("ativo", True):
        return [], "kit inativo no Cadastro de Kits"
    elif not comp and not confirmada and anuncio_tipo_a_confirmar(cod, catalogo=catalogo, info=info):
        return [], "SKU parece dois códigos juntos (kit?): confirme na ficha se é Peça ou Kit"
    pecas: dict[str, dict[str, Any]] = {}
    for codigo, qtd in partes:
        chave = _exp_norm_codigo(codigo)
        if not chave or int(qtd or 0) <= 0:
            continue
        p = pecas.setdefault(chave, {"codigo": normalize(codigo), "chave": chave, "quantidade": 0})
        p["quantidade"] += int(qtd)
    if not pecas:
        return [], "SKU sem código do Apollo"
    return list(pecas.values()), ""


def _anuncios_automatico_linhas(conta: str, anuncio_id: str = "") -> list[dict[str, Any]]:
    """V20.26: anuncios da conta em Automatico que o Noromak pode mexer. Chamar SOB o DB_LOCK.
    V20.32: `conta` = conta de estoque ('shopee' = as linhas da Shopee de Araçatuba)."""
    canal, conta_linha, _filial = _estoque_alvo(conta)
    sql = ("SELECT * FROM anuncio_canal_v2023 WHERE canal=? AND conta=? AND estoque_modo='automatico' "
           "AND controle='noromak' AND COALESCE(removido_em,'')='' AND COALESCE(logistica,'')<>'fulfillment'")
    args: tuple[Any, ...] = (canal, conta_linha)
    if anuncio_id:
        sql += " AND anuncio_id=?"
        args += (anuncio_id,)
    return [dict(r) for r in DB.execute(sql + " ORDER BY anuncio_id", args).fetchall()]


def _anuncios_conhecidos_lazy() -> Any:
    guardado: list[set[str]] = []

    def ler() -> set[str]:
        if not guardado:
            try:
                guardado.append(_separacao_codigos_conhecidos())
            except Exception:
                guardado.append(set())
        return guardado[0]
    return ler


def _anuncios_codigos_automatico(filial: str) -> dict[str, str]:
    """V20.26: codigos do Apollo (normalize) das pecas dos anuncios em Automatico da filial."""
    with DB_LOCK:
        linhas = _anuncios_automatico_linhas(filial)
        if filial == SHOPEE_ANUNCIO_CONTA:  # V20.32: a Shopee (V20.34: e a Magalu) le o mesmo Apollo de Araçatuba
            linhas += _anuncios_automatico_linhas(ESTOQUE_CONTA_SHOPEE)
            linhas += _anuncios_automatico_linhas(ESTOQUE_CONTA_MAGALU)
        if filial == TIKTOK_CASA:  # V20.41: o TikTok lê o mesmo Apollo de Bauru que o ML de Bauru
            linhas += _anuncios_automatico_linhas(ESTOQUE_CONTA_TIKTOK)
    if not linhas:
        return {}
    catalogo = _load_kit_catalog()
    conhecidos = _anuncios_conhecidos_lazy()
    codigos: dict[str, str] = {}
    for r in linhas:
        pecas, _ = _anuncio_estoque_pecas(r.get("ficha_codigo"), catalogo, conhecidos)
        for p in pecas:
            codigos.setdefault(p["codigo"], p["codigo"])
    return codigos


def anuncios_apollo_ler(codigo: str, filial: str) -> bool:
    """V20.26: uma consulta ao Apollo (limite compartilhado; CrmLimiteAtingido sobe). Sem resposta = None guardado
    (o anuncio nao recebe envio; nunca zero). Devolve True quando a leitura mudou."""
    revenda = ANUNCIO_REVENDA[filial]
    cod = normalize(codigo)
    disponivel: float | None = None
    try:
        disponivel = _apollo_da_revenda(crm_stock_lookup(cod, operador="anuncios-estoque", wait_seconds=0), revenda)
    except CrmLimiteAtingido:
        raise
    except Exception:
        disponivel = None
    with DB_LOCK:
        antes = DB.execute("SELECT disponivel, respondeu FROM anuncio_apollo_v2026 WHERE codigo=? AND filial=?",
                           (cod, filial)).fetchone()
        DB.execute("INSERT OR REPLACE INTO anuncio_apollo_v2026(codigo,filial,disponivel,respondeu,lido_em,lido_epoch) "
                   "VALUES(?,?,?,?,?,?)", (cod, filial, disponivel, 1 if disponivel is not None else 0, now_iso(),
                                           int(time.time())))
        DB.commit()
    if antes is None:
        return True
    return (antes["disponivel"] != disponivel) or (int(antes["respondeu"] or 0) != (1 if disponivel is not None else 0))


def anuncios_apollo_ler_proximo(filial: str, mudancas: set[str] | None = None,
                                apenas: set[str] | None = None) -> str | None:
    """V20.26: uma volta do rodizio (no maximo ANUNCIO_APOLLO_POR_MINUTO por minuto, todas as filiais juntas).
    Ordem: nunca lido > estoque <= ANUNCIO_ESTOQUE_BAIXO lido ha mais de 10 min > o mais antigo.
    So os codigos dos anuncios em Automatico da filial. `mudancas` recebe a filial quando a leitura mudou.
    V20.42: `apenas` = so estes codigos (com o lote em dia, o rodizio cobre so o que o lote nao manda)."""
    codigos = _anuncios_codigos_automatico(filial)
    if apenas is not None:
        codigos = {k: v for k, v in codigos.items() if k in apenas}
    if not codigos:
        return None
    with DB_LOCK:
        lidos = {str(r["codigo"]): dict(r) for r in
                 DB.execute("SELECT * FROM anuncio_apollo_v2026 WHERE filial=?", (filial,)).fetchall()}
    epoch = int(time.time())
    quedas = _anuncio_pend_quedas(filial)

    def prioridade(cod: str) -> tuple[int, int]:
        r = lidos.get(cod)
        q = quedas.get(_exp_norm_codigo(cod))
        if r and q is not None and int(q) >= int(r["lido_epoch"] or 0):
            return (-1, int(r["lido_epoch"] or 0))  # V20.26 (revisao): pedido concluido - rele esta peca primeiro
        if not r:
            return (0, 0)
        idade = epoch - int(r["lido_epoch"] or 0)
        baixo = r["disponivel"] is not None and float(r["disponivel"]) <= ANUNCIO_ESTOQUE_BAIXO
        if baixo and idade > 600:
            return (1, int(r["lido_epoch"] or 0))
        return (2, int(r["lido_epoch"] or 0))

    escolhido = min(sorted(codigos), key=prioridade)
    with _ANUNCIO_APOLLO_LOCK:
        agora = time.monotonic()
        _ANUNCIO_APOLLO_CHAMADAS[:] = [t for t in _ANUNCIO_APOLLO_CHAMADAS if agora - t < 60]
        if len(_ANUNCIO_APOLLO_CHAMADAS) >= ANUNCIO_APOLLO_POR_MINUTO:
            return None
        _ANUNCIO_APOLLO_CHAMADAS.append(agora)
    try:
        mudou = anuncios_apollo_ler(codigos[escolhido], filial)
    except CrmLimiteAtingido:
        return None  # o limite do Apollo esta com as outras telas: fica para a proxima volta
    if mudou and mudancas is not None:
        mudancas.add(filial)
    return escolhido


# V20.42: estoque relido em LOTE (Guilherme, 09/11). A Linx nao tem "o que mudou desde" nem avisa a mudanca; no
# lugar, a porta POST /api/v1/expedicao/estoque/lote devolve o disponivel de ate 500 codigos em cada casa, lido na
# hora, o mesmo numero da porta estoque (90/90 conferidos), limite de 6/min SEPARADO dos 20/min. Uma chamada por
# minuto com TODOS os codigos em Automatico (as duas filiais juntas, mais os do TikTok pela extensao); o rodizio de
# 3/min fica de reserva (lote falhou, ou nao deu certo nos ultimos ANUNCIO_APOLLO_LOTE_RESERVA_S).
# Formato real (09/11): {"ok": true, "itens": [{"codigo","revenda","disponivel","tem_cadastro","erro"}]}.
# disponivel null / tem_cadastro null / erro = casa sem resposta = None (nunca zero); tem_cadastro false = 0.
ANUNCIO_APOLLO_LOTE_S = 60              # uma volta do lote por minuto
ANUNCIO_APOLLO_LOTE_POR_MINUTO = 5      # chamadas por minuto (a porta aceita 6; 1 de folga)
ANUNCIO_APOLLO_LOTE_MAX = 500           # codigos por chamada (o maximo da porta)
ANUNCIO_APOLLO_LOTE_COD_MAX = 30        # tamanho maximo do codigo na porta (maior = 422 na chamada inteira)
ANUNCIO_APOLLO_LOTE_RESERVA_S = 180     # sem lote completo ha mais que isto, o rodizio volta
ANUNCIO_APOLLO_LOTE_TIMEOUT = 60
ANUNCIO_APOLLO_LOTE_FECHADA_S = 600     # porta nao liberada (404): tenta de novo em 10 min
_APOLLO_LOTE_LOCK = threading.Lock()
_APOLLO_LOTE_ESTADO: dict[str, Any] = {}
_APOLLO_LOTE_CHAMADAS: list[float] = []


def _apollo_lote_zerar() -> None:
    with _APOLLO_LOTE_LOCK:
        _APOLLO_LOTE_ESTADO.clear()
        _APOLLO_LOTE_ESTADO.update({"tentado_mono": 0.0, "ok_epoch": 0, "tiktok_ok_epoch": 0, "erro": "",
                                    "erro_em": "", "ok_em": "", "codigos": 0, "chamadas": 0, "fechada_ate": 0.0,
                                    "fora": {}})
        _APOLLO_LOTE_CHAMADAS.clear()


_apollo_lote_zerar()


def _apollo_estoque_lote_http(codigos: list[str], revendas: list[int]) -> dict[str, Any]:
    """V20.42: uma chamada a porta estoque/lote (so leitura). Erro sobe como PortaErro."""
    if not CHAVE_CRM:
        raise PortaErro("CHAVE_CRM não está configurada no servidor.")
    corpo = {"codigos": list(codigos), "revendas": list(revendas), "operador": "anuncios-estoque"}
    req = urllib.request.Request(
        f"{EXP_PORTA_BASE}/estoque/lote", data=json.dumps(corpo).encode("utf-8"), method="POST",
        headers={"X-Chave-Expedicao": CHAVE_CRM, "Content-Type": "application/json", "Accept": "application/json",
                 "User-Agent": f"NoromakExpedicao/{APP_VERSION}"})
    return _exp_porta_resposta(req, False, timeout=ANUNCIO_APOLLO_LOTE_TIMEOUT)


_APOLLO_LOTE_HTTP_REAL = _apollo_estoque_lote_http


def _apollo_lote_valor(item: dict[str, Any]) -> float | None:
    if item.get("ok") is False or item.get("erro") or item.get("tem_cadastro") is None:
        return None
    if item.get("tem_cadastro") is False:
        return 0.0
    valor = _apollo_number(item.get("disponivel"))
    return None if valor is None else max(0.0, valor)


def apollo_lote_em_dia(tiktok: bool = False) -> bool:
    """V20.42: o ultimo lote completo (todos os codigos, sem erro) foi ha menos de ANUNCIO_APOLLO_LOTE_RESERVA_S.
    `tiktok` = o dos codigos do TikTok pela extensao."""
    with _APOLLO_LOTE_LOCK:
        quando = int(_APOLLO_LOTE_ESTADO.get("tiktok_ok_epoch" if tiktok else "ok_epoch") or 0)
    return bool(quando) and time.time() - quando < ANUNCIO_APOLLO_LOTE_RESERVA_S


def apollo_lote_fora(filial: str) -> set[str]:
    """V20.42: codigos da filial que o lote nao manda (codigo maior que a porta aceita): o rodizio cobre."""
    with _APOLLO_LOTE_LOCK:
        return set((_APOLLO_LOTE_ESTADO.get("fora") or {}).get(filial) or ())


def apollo_lote_situacao() -> dict[str, Any]:
    with _APOLLO_LOTE_LOCK:
        e = dict(_APOLLO_LOTE_ESTADO)
    return {"em_dia": apollo_lote_em_dia(), "ok_em": e.get("ok_em") or "", "erro": e.get("erro") or "",
            "erro_em": e.get("erro_em") or "", "codigos": int(e.get("codigos") or 0),
            "a_cada_s": ANUNCIO_APOLLO_LOTE_S}


def anuncios_apollo_lote(mudancas: set[str] | None = None) -> bool:
    """V20.42: uma volta do lote (no maximo uma por ANUNCIO_APOLLO_LOTE_S). Le todos os codigos dos anuncios em
    Automatico (Araçatuba e Bauru; Shopee/Magalu = Araçatuba, TikTok = Bauru) e os do TikTok pela extensao, grava em
    anuncio_apollo_v2026 / tiktok_apollo_v1964 e poe em `mudancas` a filial cuja leitura mudou. Devolve True quando
    o lote leu TUDO (o rodizio pode descansar). Falha = nada gravado daquela chamada; o rodizio continua."""
    agora_mono = time.monotonic()
    with _APOLLO_LOTE_LOCK:
        if agora_mono - float(_APOLLO_LOTE_ESTADO.get("tentado_mono") or 0) < ANUNCIO_APOLLO_LOTE_S \
                and _APOLLO_LOTE_ESTADO.get("tentado_mono"):
            return False
        if agora_mono < float(_APOLLO_LOTE_ESTADO.get("fechada_ate") or 0):
            return False
    por_filial = {f: _anuncios_codigos_automatico(f) for f in ANUNCIO_REVENDA}
    tiktok: dict[str, str] = {}
    if _tiktok_extensao_le_apollo():
        tiktok = _tiktok_codigos_apollo()
    pedidos: dict[str, str] = {}      # normalize(codigo) -> como vai a porta
    fora: dict[str, set[str]] = {}
    revendas: set[int] = set()
    for filial, cods in por_filial.items():
        for cod in cods:
            if len(cod) > ANUNCIO_APOLLO_LOTE_COD_MAX:
                fora.setdefault(filial, set()).add(cod)
                continue
            pedidos.setdefault(normalize(cod), cod)
            revendas.add(ANUNCIO_REVENDA[filial])
    tiktok_fora = False
    for cod in tiktok.values():
        if len(str(cod)) > ANUNCIO_APOLLO_LOTE_COD_MAX:
            tiktok_fora = True
            continue
        pedidos.setdefault(normalize(cod), str(cod))
        revendas.add(TIKTOK_REVENDA_APOLLO)
    with _APOLLO_LOTE_LOCK:
        _APOLLO_LOTE_ESTADO["fora"] = fora
    if not pedidos:
        return False
    with _APOLLO_LOTE_LOCK:
        _APOLLO_LOTE_ESTADO["tentado_mono"] = agora_mono
    lista = sorted(pedidos.values())
    lidos: dict[tuple[str, int], float | None] = {}
    completo = True
    erro = ""
    repetido = False
    for i in range(0, len(lista), ANUNCIO_APOLLO_LOTE_MAX):
        parte = lista[i:i + ANUNCIO_APOLLO_LOTE_MAX]
        with _APOLLO_LOTE_LOCK:
            agora = time.monotonic()
            _APOLLO_LOTE_CHAMADAS[:] = [t for t in _APOLLO_LOTE_CHAMADAS if agora - t < 60]
            if len(_APOLLO_LOTE_CHAMADAS) >= ANUNCIO_APOLLO_LOTE_POR_MINUTO:
                completo = False
                erro = erro or "mais códigos que cabem num minuto: o rodízio cobre o resto"
                break
            _APOLLO_LOTE_CHAMADAS.append(agora)
        try:
            dados = _apollo_estoque_lote_http(parte, sorted(revendas))
        except PortaErro as exc:
            completo, erro = False, str(exc)
            if "404" in str(exc):
                with _APOLLO_LOTE_LOCK:
                    _APOLLO_LOTE_ESTADO["fechada_ate"] = time.monotonic() + ANUNCIO_APOLLO_LOTE_FECHADA_S
            break
        except Exception as exc:
            completo, erro = False, f"lote do Apollo: {exc}"
            break
        if not isinstance(dados, dict) or dados.get("ok") is not True or not isinstance(dados.get("itens"), list):
            completo = False
            erro = str((dados or {}).get("erro") or "resposta sem itens") if isinstance(dados, dict) else "resposta inválida"
            break
        voltou: dict[tuple[str, int], float | None] = {}
        for item in dados["itens"]:
            if not isinstance(item, dict):
                continue
            try:
                rev = int(item.get("revenda"))
            except (TypeError, ValueError):
                continue
            voltou[(normalize(item.get("codigo")), rev)] = _apollo_lote_valor(item)
        for cod in parte:  # codigo pedido que nao voltou = sem resposta (None), nunca zero
            for rev in revendas:
                lidos[(normalize(cod), rev)] = voltou.get((normalize(cod), rev))
    if lidos:
        _apollo_lote_gravar(lidos, por_filial, tiktok, mudancas)
    epoch = int(time.time())
    with _APOLLO_LOTE_LOCK:
        _APOLLO_LOTE_ESTADO["codigos"] = len(lista)
        if completo:
            _APOLLO_LOTE_ESTADO["ok_epoch"] = epoch
            _APOLLO_LOTE_ESTADO["ok_em"] = now_iso()
            _APOLLO_LOTE_ESTADO["erro"] = ""
            if tiktok and not tiktok_fora:
                _APOLLO_LOTE_ESTADO["tiktok_ok_epoch"] = epoch
        else:
            repetido = _APOLLO_LOTE_ESTADO.get("erro") == erro[:300]
            _APOLLO_LOTE_ESTADO["erro"] = erro[:300]
            _APOLLO_LOTE_ESTADO["erro_em"] = now_iso()
    if not completo and not repetido:  # o mesmo erro a cada minuto vai para o log uma vez so
        print(f"[anuncios_estoque] lote do Apollo: {erro[:300]}", file=sys.stderr, flush=True)
    return completo


def _apollo_lote_gravar(lidos: dict[tuple[str, int], float | None], por_filial: dict[str, dict[str, str]],
                        tiktok: dict[str, str], mudancas: set[str] | None) -> None:
    """V20.42: grava as leituras do lote (a mesma linha que o rodizio grava). So o que foi lido."""
    epoch, quando = int(time.time()), now_iso()
    with DB_LOCK:
        for filial, cods in por_filial.items():
            rev = ANUNCIO_REVENDA[filial]
            for cod in cods:
                chave = (normalize(cod), rev)
                if chave not in lidos:
                    continue
                valor = lidos[chave]
                antes = DB.execute("SELECT disponivel, respondeu FROM anuncio_apollo_v2026 WHERE codigo=? AND filial=?",
                                   (cod, filial)).fetchone()
                resp = 1 if valor is not None else 0
                DB.execute("INSERT OR REPLACE INTO anuncio_apollo_v2026(codigo,filial,disponivel,respondeu,lido_em,"
                           "lido_epoch) VALUES(?,?,?,?,?,?)", (cod, filial, valor, resp, quando, epoch))
                if mudancas is not None and (antes is None or antes["disponivel"] != valor
                                             or int(antes["respondeu"] or 0) != resp):
                    mudancas.add(filial)
        for chave_tk, cod in tiktok.items():
            chave = (normalize(cod), TIKTOK_REVENDA_APOLLO)
            if chave not in lidos:
                continue
            valor = lidos[chave]
            DB.execute("""INSERT OR REPLACE INTO tiktok_apollo_v1964(codigo,disponivel,respondeu,erro,lido_em,lido_epoch)
                          VALUES(?,?,?,?,?,?)""",
                       (chave_tk, valor, 1 if valor is not None else 0,
                        "" if valor is not None else "Bauru não respondeu no Apollo", quando, epoch))
        DB.commit()


# V20.26 (revisao): quando o pendente de uma peca CAI (a Conferencia concluiu o pedido), o Apollo ainda nao baixou ate
# reler a peca (rodizio de 3/min). Enquanto a leitura da peca for mais velha que a queda, o anuncio nao sobe acima do
# ultimo enviado, e a peca vai para o comeco do rodizio. Sem chamada a mais. Memoria do processo (reiniciar = esquece).
_ANUNCIO_PEND_VISTO: dict[tuple[str, str], dict[str, int]] = {}   # (filial, tipo do pendente) -> o ultimo visto
_ANUNCIO_PEND_QUEDA: dict[tuple[str, str], float] = {}            # (filial, chave da peca) -> quando caiu


def _anuncio_pend_observar(filial: str, tipo: str, pend: dict[str, int] | None) -> None:
    if pend is None:
        return
    agora = time.time()
    with _ANUNCIO_PEND_LOCK:
        antes = _ANUNCIO_PEND_VISTO.get((filial, tipo))
        if antes is not None:
            for chave, q in antes.items():
                if int(pend.get(chave, 0) or 0) < int(q or 0):
                    _ANUNCIO_PEND_QUEDA[(filial, chave)] = agora
        _ANUNCIO_PEND_VISTO[(filial, tipo)] = dict(pend)
        for k, t in list(_ANUNCIO_PEND_QUEDA.items()):  # mais velha que a validade da leitura: a leitura ja venceu
            if agora - t > ANUNCIO_APOLLO_VALIDADE_S:
                del _ANUNCIO_PEND_QUEDA[k]


def _anuncio_pend_quedas(filial: str) -> dict[str, float]:
    with _ANUNCIO_PEND_LOCK:
        return {c: t for (f, c), t in _ANUNCIO_PEND_QUEDA.items() if f == filial}


def _anuncios_estoque_calcular(conta: str, anuncio_id: str = "") -> tuple[list[dict[str, Any]], Any]:
    """V20.26: (itens, versao da fila usada). A versao e lida ANTES da fila: se mudar no meio, a conferida antes
    do envio e diferente e o anuncio e recalculado (RF1).
    V20.26 (revisao): calcula descontando todo o pendente e so o sem atendimento no Apollo; `calculado` e o da chave
    `apollo_desconta_atendimento` da conta. Pedido concluido segura a subida ate o Apollo reler a peca.
    V20.32: `conta` = conta de estoque; a Shopee usa a filial de Araçatuba (o mesmo estoque do ML)."""
    conta = _estoque_conta_valida(conta)
    filial = _estoque_alvo(conta)[2]
    with DB_LOCK:
        versao = _ml_versoes_storage("conf_pedidos", PENDING_ORDER_DELETE_KEY_V1766)
        linhas = _anuncios_automatico_linhas(conta, anuncio_id)
        lidos = {str(r["codigo"]): dict(r) for r in
                 DB.execute("SELECT * FROM anuncio_apollo_v2026 WHERE filial=?", (filial,)).fetchall()} if linhas else {}
    if not linhas:
        return [], versao
    desconta_atend = bool(anuncio_estoque_config(conta).get("apollo_desconta_atendimento"))
    pend_tudo = pendentes_por_filial((filial,)).get(filial)
    pend_sem = pendentes_sem_atendimento(filial) if pend_tudo is not None else None
    _anuncio_pend_observar(filial, "tudo", pend_tudo)
    _anuncio_pend_observar(filial, "sem_atendimento", pend_sem)
    quedas = _anuncio_pend_quedas(filial)
    pend = pend_sem if desconta_atend else pend_tudo
    catalogo = _load_kit_catalog()
    conhecidos = _anuncios_conhecidos_lazy()
    epoch = int(time.time())
    itens: list[dict[str, Any]] = []
    for r in linhas:
        pecas, motivo = _anuncio_estoque_pecas(r.get("ficha_codigo"), catalogo, conhecidos)
        status = str(r.get("status") or "")
        if not motivo and status in ANUNCIO_ESTOQUE_STATUS_PARADO:  # V20.26 (revisao)
            motivo = f"anúncio {ANUNCIO_ESTOQUE_STATUS_PARADO[status]} no ML: nada é enviado"
        if not motivo and int(r.get("variacoes") or 0):
            motivo = "anúncio com variações: o estoque é por variação; ajuste no ML"
        if not motivo and pend is None:
            motivo = "fila de pedidos não lida" if pend_tudo is None else "Faturamento não lido (pedidos com atendimento)"
        disp: dict[str, float | None] = {}
        saida_pecas = []
        segura: list[str] = []
        for p in pecas:
            lido = lidos.get(p["codigo"])
            valor: float | None = None
            if lido is None:
                motivo = motivo or f"aguardando a leitura do Apollo ({p['codigo']})"
            elif not int(lido.get("respondeu") or 0) or lido.get("disponivel") is None:
                motivo = motivo or f"o Apollo não respondeu ({p['codigo']})"
            elif epoch - int(lido.get("lido_epoch") or 0) > ANUNCIO_APOLLO_VALIDADE_S:
                motivo = motivo or f"leitura do Apollo antiga ({p['codigo']})"
            else:
                valor = float(lido["disponivel"])
                q = quedas.get(p["chave"])
                if q is not None and int(q) >= int(lido.get("lido_epoch") or 0):
                    segura.append(p["codigo"])
            disp[p["chave"]] = valor
            saida_pecas.append({"codigo": p["codigo"], "quantidade": p["quantidade"], "disponivel": valor,
                                "a_baixar": None if pend is None else int(pend.get(p["chave"], 0) or 0),
                                "a_baixar_tudo": None if pend_tudo is None else int(pend_tudo.get(p["chave"], 0) or 0),
                                "a_baixar_sem_atendimento": None if pend_sem is None else int(pend_sem.get(p["chave"], 0) or 0),
                                "lido_em": str((lido or {}).get("lido_em") or "")})
        # V20.26 (revisao): teto = o MENOR entre o ultimo enviado e o lido no ML (venda que ainda nao esta na fila)
        _tetos = [x for x in (r.get("estoque_enviado"), r.get("estoque")) if x is not None]
        teto = min(_tetos) if _tetos else None
        comps = [{"sku": p["chave"], "quantidade": p["quantidade"]} for p in pecas]

        def bruto(pd: dict[str, int] | None) -> int | None:
            if motivo or pd is None:
                return None
            n = kit_da_para_montar(comps, disp, pd)
            return None if n is None else min(int(n), ANUNCIO_ESTOQUE_MAX)

        def numero(n: int | None) -> int | None:
            if n is not None and segura and (teto is None or n > int(teto)):
                return None if teto is None else int(teto)  # segura: nunca acima do ultimo enviado
            return n

        b_tudo, b_sem = bruto(pend_tudo), bruto(pend_sem)
        calc_tudo, calc_sem = numero(b_tudo), numero(b_sem)
        calculado = calc_sem if desconta_atend else calc_tudo
        b = b_sem if desconta_atend else b_tudo
        segurado = ""
        if b is not None and b != calculado:
            segurado = (f"pedido concluído: não sobe antes de o Apollo reler {', '.join(segura)}"
                        + (f" (fica em {int(teto)}, daria {b})" if teto is not None else f" (daria {b})"))
        if calculado is None and not motivo:
            motivo = segurado or "sem leitura do Apollo"
        referencia = r.get("estoque") if r.get("estoque") is not None else r.get("estoque_enviado")
        itens.append({"anuncio_id": str(r["anuncio_id"]), "conta": conta, "ficha": str(r.get("ficha_codigo") or ""),
                      "titulo": str(r.get("titulo") or ""), "modo": "automatico",
                      "atual_ml": r.get("estoque"), "estoque_enviado": r.get("estoque_enviado"),
                      "estoque_enviado_em": str(r.get("estoque_enviado_em") or ""),
                      "estoque_calculado_antes": r.get("estoque_calculado"),
                      "calculado": calculado, "calculado_tudo": calc_tudo, "calculado_sem_atendimento": calc_sem,
                      "desconta_atendimento": desconta_atend, "segurado": segurado if calculado is not None else "",
                      "motivo": motivo, "pecas": saida_pecas, "referencia": referencia,
                      # muda quando o anuncio e lido de novo (puxada/"Trazer dados"): zera a contagem de erros seguidos.
                      # Nada que o proprio envio grava (estoque, status, variacoes) entra aqui.
                      "assinatura": "|".join(str(r.get(k) or "") for k in ("user_product_id", "logistica", "lido_em")),
                      "muda": calculado is not None and calculado != referencia})
    return itens, versao


def anuncios_estoque_calcular(conta: str) -> list[dict[str, Any]]:
    """V20.26: `{anuncio_id, ficha, atual_ml, calculado, motivo, pecas, ...}` dos anuncios em Automatico da conta.
    `calculado` None = nao envia (motivo diz por que)."""
    return _anuncios_estoque_calcular(conta)[0]


# V20.26: rodada do Automatico (worker e "Enviar agora") e a tela.
ANUNCIO_ESTOQUE_ERRO_ESPERA_S = 600    # mesmo numero recusado pelo ML: o worker so tenta de novo depois disso
ANUNCIO_ESTOQUE_RECALCULO_S = 600      # o worker refaz a conta mesmo sem mudanca (leitura do Apollo venceu etc.)
ANUNCIO_ESTOQUE_ERROS_PARAR = 3        # V20.26 (revisao): erros seguidos no mesmo numero = para ate o numero/anuncio mudar
# (conta, mlb) -> (quando, numero, erros seguidos, assinatura do anuncio, ultimo erro). Memoria do processo.
_ANUNCIO_ESTOQUE_ERRO: dict[tuple[str, str], tuple[float, int, int, str, str]] = {}
_ANUNCIO_ESTOQUE_RODADA_LOCKS: dict[str, threading.Lock] = {c: threading.Lock() for c in (*CASAS, *ESTOQUE_CONTAS_FORA)}


def _anuncio_estoque_motivo_envio(it: dict[str, Any]) -> str:
    partes = [f"{p['codigo']}: Apollo {p['disponivel']:g} − a baixar {p['a_baixar']}" + (f" (÷{p['quantidade']})" if p["quantidade"] > 1 else "")
              for p in it.get("pecas") or [] if p.get("disponivel") is not None and p.get("a_baixar") is not None]
    texto = "; ".join(partes) + f" = {it.get('calculado')}"
    # V20.26 (revisao): o outro jeito de descontar, para o dono comparar por alguns dias antes de ligar a chave
    if it.get("calculado_tudo") != it.get("calculado_sem_atendimento"):
        texto += (f" (descontando tudo: {it.get('calculado_tudo')} · só sem atendimento: "
                  f"{it.get('calculado_sem_atendimento')})")
    if it.get("segurado"):
        texto += " · " + str(it["segurado"])
    return texto[:300]


def anuncios_estoque_rodada(conta: str, *, ator: str, forcar: bool = False) -> dict[str, Any]:
    """V20.26: calcula e, conforme o modo da conta, registra (simulacao), envia no clique (lote, `forcar`) ou envia
    (automatico) o que mudou. Antes de cada envio, DENTRO da trava do anuncio, rele o modo do anuncio (virou Manual =
    desiste, RF4), o modo da conta e a versao da fila (mudou = recalcula esse anuncio, RF1).
    V20.32: tambem a conta 'shopee' (grava pelo shopee_estoque_gravar)."""
    conta = _estoque_conta_valida(conta)
    canal, conta_linha, _filial = _estoque_alvo(conta)
    gravar = _estoque_gravador(canal)  # V20.34: Shopee, Magalu ou ML
    trava = _ANUNCIO_ESTOQUE_RODADA_LOCKS[conta]
    if not trava.acquire(timeout=30 if forcar else 0.01):
        return {"ok": False, "ocupado": True, "erro": "Outra rodada do estoque desta conta está em andamento."}
    try:
        cfg = anuncio_estoque_config(conta)["modo"]
        itens, versao = _anuncios_estoque_calcular(conta)
        agora = now_iso()
        with DB_LOCK:
            mudou_calc = False
            for it in itens:
                if it["calculado"] != it["estoque_calculado_antes"]:
                    DB.execute("UPDATE anuncio_canal_v2023 SET estoque_calculado=?, estoque_calculado_em=? "
                               "WHERE canal=? AND conta=? AND anuncio_id=?",
                               (it["calculado"], agora, canal, conta_linha, it["anuncio_id"]))
                    mudou_calc = True
            if mudou_calc:
                DB.commit()
        res: dict[str, Any] = {"ok": True, "conta": conta, "modo": cfg, "avaliados": len(itens), "mudariam": 0,
                               "enviados": 0, "erros": 0, "simulados": 0, "ignorados": 0, "detalhes": []}
        for it in itens:
            if not it["muda"]:
                continue
            res["mudariam"] += 1
            mlb, calc = it["anuncio_id"], int(it["calculado"])
            motivo = _anuncio_estoque_motivo_envio(it)
            if cfg == "simulacao":
                if it["calculado"] != it["estoque_calculado_antes"]:
                    _anuncio_estoque_registrar(canal, conta_linha, mlb, "automatico", it["referencia"], calc, motivo,
                                               "simulado", "Simulação: nada enviado ao marketplace", ator)
                    res["simulados"] += 1
                continue
            if cfg == "lote" and not forcar:
                continue
            chave = (conta, mlb)
            erro_antes = _ANUNCIO_ESTOQUE_ERRO.get(chave)
            if erro_antes and (erro_antes[1] != calc or erro_antes[3] != it["assinatura"]):
                erro_antes = None  # V20.26 (revisao): o numero ou o anuncio mudou: tenta de novo, contagem do zero
            if (not forcar and erro_antes
                    and (erro_antes[2] >= ANUNCIO_ESTOQUE_ERROS_PARAR
                         or time.time() - erro_antes[0] < ANUNCIO_ESTOQUE_ERRO_ESPERA_S)):
                res["parados"] = int(res.get("parados") or 0) + (1 if erro_antes[2] >= ANUNCIO_ESTOQUE_ERROS_PARAR else 0)
                continue

            def conferir(mlb: str = mlb, calc: int = calc) -> tuple[int | None, str]:
                with DB_LOCK:
                    row = _anuncio_estoque_linha(canal, conta_linha, mlb)
                    versao_agora = _ml_versoes_storage("conf_pedidos", PENDING_ORDER_DELETE_KEY_V1766)
                if row is None or str(row.get("estoque_modo") or "") != "automatico":
                    return None, "o anúncio passou para Manual: o Automático não envia"
                modo_conta = anuncio_estoque_config(conta)["modo"]
                if modo_conta == "simulacao" or (modo_conta == "lote" and not forcar):
                    return None, f"a conta está em {modo_conta}: nada enviado"
                if versao_agora != versao:  # RF1: chegou venda (ou mudou a fila) depois do calculo
                    novos, _ = _anuncios_estoque_calcular(conta, mlb)
                    if not novos or novos[0]["calculado"] is None:
                        return None, "a fila mudou e o estoque ficou sem número: " + (
                            novos[0]["motivo"] if novos else "anúncio fora do Automático")
                    return int(novos[0]["calculado"]), ""
                return calc, ""

            try:
                r = gravar(conta, mlb, calc, ator=ator, modo="automatico", motivo=motivo, conferir=conferir)
            except ValueError as exc:
                res["ignorados"] += 1
                res["detalhes"].append({"anuncio_id": mlb, "resultado": "ignorado", "erro": str(exc)})
                continue
            res["detalhes"].append({"anuncio_id": mlb, "resultado": r["resultado"], "para": r.get("quantidade", calc),
                                    "erro": r.get("erro") or ""})
            if r["ok"]:
                res["enviados"] += 1
                _ANUNCIO_ESTOQUE_ERRO.pop(chave, None)
            elif r["resultado"] == "ignorado" and r.get("ignorado") not in ("status", "variacoes"):
                res["ignorados"] += 1  # desistiu (virou Manual, Full, fila sem numero...): nao conta como erro
            else:
                # V20.26 (revisao): erro, ou o ML mostrou o anuncio parado/com variacoes: conta os seguidos
                res["erros" if r["resultado"] != "ignorado" else "ignorados"] += 1
                n = (erro_antes[2] + 1) if erro_antes else 1
                _ANUNCIO_ESTOQUE_ERRO[chave] = (time.time(), calc, n, it["assinatura"], str(r.get("erro") or "")[:200])
        return res
    finally:
        trava.release()


def anuncios_estoque_payload(conta: str, anuncio_id: str = "") -> dict[str, Any]:
    """V20.26: GET /api/anuncios/estoque - calculo, interruptor da conta e ultimos registros. So le (nunca o ML/Apollo)."""
    conta = _estoque_conta_valida(conta)
    canal, conta_linha, _filial = _estoque_alvo(conta)
    anuncio_id = str(anuncio_id or "").strip().upper()
    itens, _ = _anuncios_estoque_calcular(conta, anuncio_id)
    with DB_LOCK:
        cont = DB.execute(
            "SELECT estoque_modo, COUNT(*) AS n FROM anuncio_canal_v2023 WHERE canal=? AND conta=? AND controle='noromak' "
            "AND COALESCE(removido_em,'')='' AND COALESCE(logistica,'')<>'fulfillment' GROUP BY estoque_modo",
            (canal, conta_linha)).fetchall()
        anuncio = _anuncio_estoque_linha(canal, conta_linha, anuncio_id) if anuncio_id else None
    por_modo = {str(r["estoque_modo"]): int(r["n"]) for r in cont}
    saida: dict[str, Any] = {
        "conta": conta, "config": anuncio_estoque_config(conta), "itens": itens,
        "resumo": {"automatico": por_modo.get("automatico", 0), "manual": por_modo.get("manual", 0),
                   "mudariam": sum(1 for i in itens if i["muda"]),
                   "sem_numero": sum(1 for i in itens if i["calculado"] is None)},
        "log": anuncio_estoque_log(canal, conta_linha, anuncio_id, 50), "apollo_por_minuto": ANUNCIO_APOLLO_POR_MINUTO,
        "apollo_lote": apollo_lote_situacao(),  # V20.42
        "envio": anuncios_estoque_envio_situacao(conta),  # V20.26 (revisao): "Enviar agora" em segundo plano
        "erros_repetidos": [e for e in anuncios_estoque_erros_repetidos() if e["conta"] == conta]}
    if anuncio_id:
        saida["anuncio"] = None if anuncio is None else {
            k: anuncio.get(k) for k in ("anuncio_id", "conta", "ficha_codigo", "titulo", "controle", "logistica",
                                        "estoque", "estoque_modo", "estoque_enviado", "estoque_enviado_em",
                                        "estoque_calculado", "estoque_calculado_em", "removido_em")}
        if anuncio is not None:
            saida["anuncio"]["pode_controlar"] = not _anuncio_estoque_elegivel(anuncio)
    return saida


def _anuncios_estoque_memoria_limpar() -> None:
    """V20.26 (revisao): memoria do processo do estoque automatico (os testes recomecam do zero)."""
    with _ANUNCIO_PEND_LOCK:
        _ANUNCIO_PEND_VISTO.clear()
        _ANUNCIO_PEND_QUEDA.clear()
        _ANUNCIO_PEND_CACHE.clear()
    _ANUNCIO_ESTOQUE_ERRO.clear()
    with ANUNCIOS_ESTOQUE_ENVIO_LOCK:
        ANUNCIOS_ESTOQUE_ENVIO.clear()


def anuncios_estoque_erros_repetidos() -> list[dict[str, Any]]:
    """V20.26 (revisao): anuncios em que o Automatico parou de tentar (ANUNCIO_ESTOQUE_ERROS_PARAR erros seguidos)."""
    return [{"conta": c, "anuncio_id": m, "para": e[1], "erros": e[2], "erro": e[4]}
            for (c, m), e in sorted(dict(_ANUNCIO_ESTOQUE_ERRO).items()) if e[2] >= ANUNCIO_ESTOQUE_ERROS_PARAR]


# V20.26 (revisao): o "Enviar agora" roda numa thread (com ~30 anuncios passava dos 60 s do nginx = 504). Um por conta
# de cada vez; a tela acompanha pelo `envio` do GET /api/anuncios/estoque.
ANUNCIOS_ESTOQUE_ENVIO: dict[str, dict[str, Any]] = {}
ANUNCIOS_ESTOQUE_ENVIO_LOCK = threading.Lock()
_ANUNCIOS_ESTOQUE_ENVIO_TRAVAS: dict[str, threading.Lock] = {c: threading.Lock() for c in (*CASAS, *ESTOQUE_CONTAS_FORA)}


def anuncios_estoque_envio_situacao(conta: str) -> dict[str, Any]:
    with ANUNCIOS_ESTOQUE_ENVIO_LOCK:
        return json.loads(json.dumps(ANUNCIOS_ESTOQUE_ENVIO.get(conta) or {"rodando": False}))


def _anuncios_estoque_envio_fundo(conta: str, ator: str) -> None:
    res: dict[str, Any] = {}
    erro = ""
    try:
        res = anuncios_estoque_rodada(conta, ator=ator, forcar=True)
        if res.get("ocupado"):
            erro = str(res.get("erro") or "Outra rodada do estoque desta conta está em andamento.")
        try:
            audit(ator, "anuncios.estoque_enviar", f"{conta}|{res.get('enviados')} enviados|{res.get('erros')} erros")
        except Exception as exc:
            print(f"Aviso: auditoria do envio de estoque nao gravada: {exc}", file=sys.stderr)
    except Exception as exc:
        erro = f"{type(exc).__name__}: {exc}"[:300]
        print(f"Aviso: envio de estoque de {conta} falhou: {erro}", file=sys.stderr)
    finally:
        with ANUNCIOS_ESTOQUE_ENVIO_LOCK:
            try:
                ANUNCIOS_ESTOQUE_ENVIO.setdefault(conta, {}).update(
                    rodando=False, fim_em=now_iso(), erro=erro, ok=not erro,
                    resultado={k: res.get(k) for k in ("avaliados", "mudariam", "enviados", "erros", "ignorados",
                                                        "parados", "detalhes")})
            finally:
                _ANUNCIOS_ESTOQUE_ENVIO_TRAVAS[conta].release()


def anuncios_estoque_envio_iniciar(conta: str, ator: str) -> bool:
    """V20.26 (revisao): False = ja tem um envio desta conta rodando (a rota responde 409)."""
    conta = _estoque_conta_valida(conta)
    trava = _ANUNCIOS_ESTOQUE_ENVIO_TRAVAS[conta]
    if not trava.acquire(blocking=False):
        return False
    try:
        with ANUNCIOS_ESTOQUE_ENVIO_LOCK:
            ANUNCIOS_ESTOQUE_ENVIO[conta] = {"rodando": True, "iniciado_em": now_iso(), "iniciado_por": str(ator or ""),
                                             "fim_em": "", "ok": None, "erro": "", "resultado": {}}
        threading.Thread(target=_anuncios_estoque_envio_fundo, args=(conta, ator), daemon=True,
                         name=f"anuncios-estoque-{conta}").start()
    except Exception:
        with ANUNCIOS_ESTOQUE_ENVIO_LOCK:
            ANUNCIOS_ESTOQUE_ENVIO[conta] = {"rodando": False, "fim_em": now_iso(), "ok": False,
                                             "erro": "O envio não começou.", "resultado": {}}
        trava.release()
        raise
    return True


def anuncio_estoque_manual(conta: str, anuncio_id: str, quantidade: Any, ator: str) -> dict[str, Any]:
    """V20.26: o Admin digitou: vai na hora ao ML. Anuncio em Automatico recusa (a proxima rodada desfaria).
    V20.32: conta 'shopee' grava na Shopee."""
    conta = _estoque_conta_valida(conta)
    canal, conta_linha, _filial = _estoque_alvo(conta)
    anuncio_id = str(anuncio_id or "").strip().upper()
    qtd = _anuncio_estoque_qtd(quantidade)
    with DB_LOCK:
        row = _anuncio_estoque_linha(canal, conta_linha, anuncio_id)
    motivo = _anuncio_estoque_elegivel(row)
    if motivo:
        raise ValueError(motivo)
    if str(row.get("estoque_modo") or "manual") != "manual":
        raise ValueError("O anúncio está em Automático: troque para Manual para digitar o estoque.")

    def conferir() -> tuple[int | None, str]:  # trocou para Automatico enquanto esperava a trava
        with DB_LOCK:
            r = _anuncio_estoque_linha(canal, conta_linha, anuncio_id)
        if r is None or str(r.get("estoque_modo") or "manual") != "manual":
            return None, "o anúncio passou para Automático"
        return qtd, ""

    gravar = _estoque_gravador(canal)  # V20.34: Shopee, Magalu ou ML
    return gravar(conta, anuncio_id, qtd, ator=ator, modo="manual", motivo="digitado pelo Admin", conferir=conferir)


def anuncios_estoque_volta(estado: dict[str, Any]) -> list[str]:
    """V20.26: uma volta do worker. Le 1 codigo do Apollo por filial com anuncio em Automatico (rodizio) e roda a
    rodada das contas em que a leitura mudou, a fila mudou ou passou ANUNCIO_ESTOQUE_RECALCULO_S. Devolve as contas."""
    with DB_LOCK:
        contas = [str(r[0]) for r in DB.execute(
            "SELECT DISTINCT conta FROM anuncio_canal_v2023 WHERE canal='ml' AND estoque_modo='automatico' "
            "AND controle='noromak' AND COALESCE(removido_em,'')='' AND COALESCE(logistica,'')<>'fulfillment'").fetchall()]
        fora = [c for c in ESTOQUE_CONTAS_FORA if DB.execute(
            "SELECT 1 FROM anuncio_canal_v2023 WHERE canal=? AND estoque_modo='automatico' AND controle='noromak' "
            "AND COALESCE(removido_em,'')='' LIMIT 1", (_estoque_alvo(c)[0],)).fetchone() is not None]
    try:  # V20.34: rascunhos da Magalu esperando o SKU aparecer (revisao: numa thread, espera <= 15 s)
        magalu_acompanhar_pendentes_fundo()
    except Exception as exc:
        print(f"[anuncios_estoque] acompanhar Magalu: {exc}", file=sys.stderr, flush=True)
    contas = sorted(c for c in contas if c in ANUNCIO_REVENDA)
    contas += fora  # V20.32: a Shopee (V20.34: e a Magalu) entram como conta propria, com a filial de Araçatuba
    mudancas: set[str] = set()
    try:  # V20.42: lote de 1 em 1 minuto (todos os codigos; tambem os do TikTok pela extensao, mesmo sem conta aqui)
        anuncios_apollo_lote(mudancas)
    except Exception as exc:
        print(f"[anuncios_estoque] lote do Apollo: {exc}", file=sys.stderr, flush=True)
    if not contas:
        return []
    em_dia = apollo_lote_em_dia()
    for f in sorted({_estoque_alvo(c)[2] for c in contas}):  # um rodizio por filial (ML e Shopee juntos)
        if em_dia:  # V20.42: o rodizio so cobre o que o lote nao manda (reserva)
            resto = apollo_lote_fora(f)
            if resto:
                anuncios_apollo_ler_proximo(f, mudancas, apenas=resto)
            continue
        anuncios_apollo_ler_proximo(f, mudancas)
    with DB_LOCK:
        versao = _ml_versoes_storage("conf_pedidos", PENDING_ORDER_DELETE_KEY_V1766)
    afetadas = {c for c in contas if _estoque_alvo(c)[2] in mudancas}
    for c in ESTOQUE_CONTAS_FORA:
        if estado.get(f"{c}_pendente") and c in contas:
            afetadas.add(c)  # 2a revisao: mudanca que chegou com a rodada da Shopee/Magalu ocupada
    if versao != estado.get("versao"):
        estado["versao"] = versao
        afetadas |= set(contas)
    agora = time.monotonic()
    if agora - float(estado.get("recalculo") or 0) > ANUNCIO_ESTOQUE_RECALCULO_S:
        estado["recalculo"] = agora
        afetadas |= set(contas)
    for c in sorted(afetadas):
        if c in ESTOQUE_CONTAS_FORA:
            # revisao (06/11): Shopee fora do ar (35 s por chamada) nao pode segurar o ML na mesma volta: roda numa
            # thread e a volta espera no maximo ANUNCIO_ESTOQUE_SHOPEE_ESPERA_S (a trava da rodada impede duas juntas)
            # V20.34: o mesmo para a Magalu (a gravacao dela e assincrona e a releitura espera ate ~30 s)
            if _ANUNCIO_ESTOQUE_RODADA_LOCKS[c].locked():
                estado[f"{c}_pendente"] = True  # 2a revisao: a mudanca fica para a proxima volta (nao se perde)
                continue
            estado[f"{c}_pendente"] = False
            t = threading.Thread(target=_anuncios_estoque_rodada_segura, args=(c,), daemon=True,
                                 name=f"anuncios-estoque-{c}")
            t.start()
            t.join(ANUNCIO_ESTOQUE_SHOPEE_ESPERA_S)
            continue
        _anuncios_estoque_rodada_segura(c)
    return sorted(afetadas)


ANUNCIO_ESTOQUE_SHOPEE_ESPERA_S = 20


def _anuncios_estoque_rodada_segura(conta: str) -> None:
    try:
        anuncios_estoque_rodada(conta, ator="sistema")
    except Exception as exc:
        print(f"[anuncios_estoque] rodada de {conta} falhou: {exc}", file=sys.stderr, flush=True)


def anuncios_estoque_loop(stop_event: threading.Event) -> None:
    """V20.26: estoque automatico dos anuncios do ML (20 s). Sem anuncio em Automatico nao le nada."""
    if stop_event.wait(75):
        return
    estado: dict[str, Any] = {}
    while not stop_event.is_set():
        try:
            anuncios_estoque_volta(estado)
        except Exception as exc:
            print(f"[anuncios_estoque] {exc}", file=sys.stderr, flush=True)
        stop_event.wait(20)


PROMO_TAXAS_DO_PRECIFICADOR ="taxas do Precificador (o Mercado Livre não respondeu)"


def _promo_prod_com_ml(prod: dict[str, Any] | None, mlb: str, preco: Any,
                       det: dict[str, Any] | None = None) -> tuple[dict[str, Any] | None, str]:
    """V18.77: a conta da promoção usa a comissão e o frete DO ANÚNCIO no ML (decisão do
    dono em 08/10). O que o ML não devolver fica com o valor do Precificador — nunca zero.
    Devolve (produto para a conta, origem): origem "" = tudo do ML."""
    if not prod:
        return prod, ""
    det = det or {}
    try:
        t = ml_tarifa_frete_anuncio(mlb, preco, tipo=str(det.get("tipo") or ""),
                                    categoria=str(det.get("categoria") or ""))
    except Exception:
        return prod, PROMO_TAXAS_DO_PRECIFICADOR
    novo = dict(prod)
    if t.get("comissao") is not None:
        novo["comissao"] = t["comissao"]
    if t.get("frete") is not None:
        novo["taxa_fixa"] = round((t.get("taxa_fixa") or 0.0) + t["frete"], 2)
    if t.get("comissao") is None and t.get("frete") is None:
        return prod, PROMO_TAXAS_DO_PRECIFICADOR
    if t.get("comissao") is None or t.get("frete") is None:
        falta = "comissão" if t.get("comissao") is None else "frete"
        return novo, f"{falta} do Precificador (o Mercado Livre não respondeu)"
    return novo, ""


PROMO_PAINEL_MAX = 40


def _ml_vinculos_mlb_sku() -> dict[str, str]:
    raw, _, _ = get_storage("ml_sku_mlb_links_v1")
    try:
        dados = json.loads(raw or "{}")
    except Exception:
        dados = {}
    out: dict[str, str] = {}
    if isinstance(dados, dict):
        for sku, linhas in dados.items():
            for row in (linhas if isinstance(linhas, list) else []):
                mlb = row.get("mlb") if isinstance(row, dict) else row
                mlb = str(mlb or "").strip().upper()
                if mlb and mlb not in out:
                    out[mlb] = str(sku or "").strip().upper()
    return out


def ml_sku_do_anuncio(bruto: Any, conhecidos: dict[str, Any] | None = None) -> str:
    """V18.27: no SKU do anúncio do ML o código é o que vem DEPOIS do traço
    (ex.: 1304-6008.004.206.00.6 -> 6008.004.206.00.6).

    O prefixo do ML é sempre numérico, e isso importa: há códigos do Apollo que
    já têm traço (816.6090-0). Cortar sem olhar transformaria esse em "0".
    Só corta quando o pedaço antes do traço é só dígitos.
    """
    texto = str(bruto or "").strip().upper()
    if not texto:
        return ""
    if conhecidos and texto in conhecidos:
        return texto                      # já é o código do cadastro
    if "-" in texto:
        antes, depois = texto.split("-", 1)
        antes, depois = antes.strip(), depois.strip()
        if depois and antes.isdigit():
            return depois
    return texto


